pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small for any
    // plausible future item (items >= 1, but realistically >= 10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual.
    score -= 2.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. this bin's residual is far below mean residual (poor fit).
    if bin_residual == bin_capacity {
        // New bin starts with full residual; penalize so it is chosen only
        // when existing fits are bad (their scores get dead-space penalties).
        let spread = mean_residual - post_residual as f64;
        if spread < 0.0 {
            // Existing bins have small residuals -> opening new bin is good.
            score -= 35.0 + (-spread) * 0.5;
        } else {
            score += 25.0 + spread * 0.3;
        }
        // Early in stream, prefer consolidating into open bins less strongly.
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; if post_residual is tiny, extra penalty.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are "dead". Penalize small-but-nonzero gaps hard.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead zone: gap below ~20 cannot fit most items (sizes 1..100, but
        // tight fits waste capacity). Quadratic penalty in the dead zone.
        if post_residual < 20 {
            score += (20.0 - pr) * (20.0 - pr) * 2.5;
        } else if post_residual <= 40 {
            // Semi-usable zone: mild penalty to prefer larger leftovers.
            score += (40.0 - pr) * 1.5;
        } else {
            // Comfortable residual: reward proportionally.
            score -= (pr - 40.0) * 0.8;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Exact-fit lookahead: if the next item exactly consumes post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits comfortably: mild reward.
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this leftover: penalize proportional dead space.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Open-bins pressure: penalize spreading across many bins when a tight
    // fit exists; encourage consolidating into fewer bins.
    let pressure = open_bins_count as f64 * 0.15;
    score += pressure * (pr / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual becomes dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh bin should only win when placing
    // here would create severe dead space or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.85;
        // Reward opening a new bin for large items that would leave tiny gaps.
        if post_residual < 15 {
            score -= 40.0;
        }
        // If the next item chains perfectly in the fresh bin, encourage it.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come
        // can fill residuals later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    } else {
        // Mean-residual coupling: placing into a bin far below the mean
        // residual (very full bin) is efficient; reward it slightly.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.25;
        } else {
            score += (-dev) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 18.0 * (x - 0.5) * (x - 0.5) * (1.0 + progress) * cap;
    score -= 12.0 * x * (1.0 - x) * (0.5 + progress) * cap;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= 20.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if x < nx {
            score += 10.0 * (nx - x) * (1.0 + progress) * cap;
        } else {
            score -= 6.0 * (x - nx) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size is 1, but tiny gaps waste capacity). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Penalize residual that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        } else {
            // Post residual can host next item: reward proportionally.
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits
    // (mean residual low means bins are mostly full; high mean residual with
    // poor fit here suggests fragmentation -> new bin may be better).
    if bin_residual == bin_capacity {
        let fit_here = (bin_residual - item_size) as f64;
        if fitting_bins_count > 0 {
            // Compare against best possible fit in existing bins: penalize
            // opening new bins when any open bin leaves less waste.
            score += 15.0 + fit_here * 0.2;
            if mean_residual < item_size as f64 + 5.0 {
                score -= 10.0; // existing bins nearly full, new bin is fine
            }
        }
    }

    // Late-stream conservatism: near the end, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins that stay near the pack's average fill.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are nearly unusable
    // for items of size >= 1 drawn from the stream; penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + 4.0 * (11 - post_residual) as f64;
    }
    // Slightly-dead zone [11, 20]: items below 10 exist, so partially usable.
    if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a compact fit exists; scale with progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when this bin would leave
    // a dead gap or the fit is loose; otherwise prefer reusing open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, mitigated if item is large
        // (a big item deserves fresh space) or if fit would be tight.
        let mut new_bin_score = 40.0 - item_size as f64 * 0.4;
        if post_residual <= 10 {
            new_bin_score += 30.0; // fresh bin leaves usable space, not dead
        }
        // Late in the stream, opening new bins is more acceptable than
        // fragmenting; early on, prefer consolidation.
        new_bin_score -= 20.0 * progress;
        // If lookahead item fits the post-residual, this placement chains well.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 12.0;
    }

    // Mean-residual context: if this bin's residual deviates favorably
    // (smaller than mean), it is a good consolidation target.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers that nothing can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can also host the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for the next item: dead space penalty scaled by gap
        score += (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Prefer bins whose residual is close to the item (tight fit) over very large residuals.
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += gap * 0.3;

    // New-bin candidate: attractive when open bins are crowded or the fit is terrible,
    // but not when this bin offers a perfect fit.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.0 && post_residual < 10;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if bad_fit || crowded || open_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 20.0;
        }
    }

    // Mild tie-breaker toward bins with residual near mean (balance load).
    score -= (mean_residual - bin_residual as f64).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but discount small residuals that are hard to reuse.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Harmonic class of post_residual: residuals in "dead" classes get penalized.
    // Classes mod 10 model typical item granularity; residuals 1..=9 are near-useless.
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if cls != 0 && post_residual < 20 {
        score += 10.0;
    }

    // Integer-division thresholds: can next item fit after this placement?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward reserving space for the lookahead item (chained fit).
            let chain_left = post_residual - next_item_size;
            score -= 15.0;
            score -= 0.3 * chain_left as f64;
            // Perfect chain: lookahead exactly fills remainder.
            if chain_left == 0 {
                score -= 30.0;
            } else if chain_left < 10 {
                score += 8.0; // creates sliver after chain
            }
        } else {
            score += 12.0; // lookahead cannot follow into this bin
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are large (poor fits everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = avg_open / bin_capacity as f64;
        score = bin_capacity as f64 * 0.9 - 60.0 * pressure - 8.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild stream-progress term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Penalize creating residual far from mean (fragmentation drift).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 500.0; // next item will perfectly fill this bin
        } else if diff > 0 {
            // next item fits: mild reward proportional to tightness
            score -= 50.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize creating dead space
            score += 30.0 * (-diff) as f64;
        }
    }

    // Penalize small unusable post_residual (dead space) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins whose residual is below mean (tight bins get filled first),
    // penalize placement in bins far above mean residual.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mildly penalize so we only open new bins when
    // placements elsewhere are truly bad; relax penalty late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 50.0 * progress;
        // If next item is huge and current item is small, opening fresh bin is attractive.
        if next_item_size > bin_capacity / 2 && item_size < 20 {
            score -= 100.0;
        }
    }

    // Slight preference for bins that already hold a similar-size item pattern:
    // reward when item consumes a large fraction of the residual.
    if bin_residual > 0 {
        score -= 20.0 * (item_size as f64 / bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps (10..=20) are semi-dead: moderate penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Next item cannot use this bin's leftover: leftover likely dead space.
            score += (post_residual as f64) * 0.5;
        } else {
            // Next item fits; residual left after it determines dead-space risk.
            let r2 = post_residual - next_item_size;
            if r2 < 10 && r2 > 0 {
                score += 8.0;
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight; prefer finishing tight bins.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.3;

    // Progress: later in the stream, waste matters more; tighten tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    // New-bin candidate: only attractive when all fits are bad (large dead space elsewhere).
    if bin_residual == bin_capacity {
