    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits: reward proportionally to how snugly it lands
        let post2 = pr - next_item_size;
        score -= (pr - post2) as f64 * 0.5;
        if post2 < 10 {
            score += 20.0; // creates new dead zone for the item after next
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this residual: soft penalty scaled by waste
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline score = capacity.
    // Only allow opening a new bin when current open bins are congested
    // (few fitting bins relative to open bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score -= 20.0 + 15.0 * congestion.min(3.0) + 10.0 * (1.0 - progress);
    } else {
        // Prefer bins with residual below the mean (consolidate waste)
        if (bin_residual as f64) < mean_residual {
