    // Reward tight fits relative to the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight match).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    }
    // Penalize if post_residual can't hold the next item and is small anyway.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 25 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score += 70.0 - 10.0 * pressure;
    }

    // Stream progression: early on, be more willing to open bins (long horizon to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    // Mean residual alignment: prefer bins near the average residual state.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1) could use
    // are catastrophic; gaps below typical item sizes are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Tight fit reward: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // would strand the next item
    }

    // Open-bin pressure: discourage scattering across many bins early,
    // allow more bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - 1.0 * progress);

    // New-bin candidate: neutral baseline, mildly high so it only wins when
    // no open bin offers a decent fit (post_residual == bin_capacity here).
    if bin_residual == bin_capacity {
        score = 85.0 + (open_bins_count as f64) * 0.5 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize wasting a large residual on a small item (poor fill efficiency).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * waste * 30.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: reward leaving space exactly usable by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear penalty on waste.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are nearly useless
    } else if post_residual >= 10 && post_residual < 30 {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward;
    // if next item cannot fit post residual but this bin was roomy, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            // next item won't fit here after placement; penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    // (consolidation pressure), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    score -= 0.05 * open_f * (bin_residual as f64 - mean_residual).max(0.0);

    // Early in the stream: mildly discourage opening new bins so bins fill up.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it is clearly better to spread load.
        let spread_benefit = if next_item_size > 0 && next_item_size >= item_size { 8.0 } else { 0.0 };
        score += 12.0 - 8.0 * progress - spread_benefit + 0.3 * open_f.max(4.0);
    }

    // Late in the stream: be greedy about exact fills.
    if progress > 0.8 && post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual by capacity fraction bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Dead-space penalty: residuals just above item sizes are wasteful.
    // Penalize small-but-not-zero residuals (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Integer-division thresholds: post_residual in [1..=eighth] is nearly dead.
    let dead_class = post_residual / 12; // coarse classes of size 12
    score += dead_class as f64 * 5.0;

    // Reward leaving residuals that common item sizes can still fill.
    // Next item lookahead: if next_item_size fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item fills the leftover.
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 150.0 * fill;
            // Modular harmony: post_residual % next_item_size small means chain fits.
            let m = post_residual % next_item_size.max(1);
            score -= (12 - m.min(12)) as f64 * 4.0;
        } else {
            // Next item cannot fit here; leftover likely dead. Penalize by leftover size.
            score += 20.0 + 0.3 * pr;
        }
    } else {
        // Last item: leftover is pure waste; prefer minimal residual.
        score += 0.5 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; penalize mildly so decent existing fits win,
        // but reward when open bins are crowded (high mean residual usage).
        score += 40.0;
        let crowding = 1.0 - (mean_residual / c).clamp(0.0, 1.0);
        score -= 120.0 * crowding;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * progress;
    }

    // Encourage tight fits relative to current residual (best-fit core signal).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // Modulo-4 harmonic bonus: residuals divisible by 4 align with common item grids.
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Penalize creating residual in awkward band (60..=75): too big to ignore, too small for large items.
    if post_residual > 60 && post_residual < 80 {
        score += 25.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Reward leaving just enough room for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: slightly penalize fresh bins so we prefer
    // reusing open bins with good fits, but allow opening when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 6.0;
        if open_bins_count > 0 {
            let fragmentation = mean_residual / (bin_capacity as f64);
            // If existing bins are full-ish, opening a new bin is attractive.
            if fragmentation < 0.25 {
                score -= 10.0;
            }
        }
    }

    // Time-horizon modulation: early in the stream, be conservative (prefer
    // spreading); late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Mild pressure from many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // to keep balance, unless it's a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: best-fit core — prefer minimal post_residual, with slight nonlinearity
    // to strongly punish leaving awkward mid-range residuals.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64).powf(1.7) * bin_capacity as f64;

    // Perfect-fit reward: exact fill is always excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: reward proportionally to how snugly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize placements that strand the lookahead item.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity or when
    // many open bins already exist (diversification), otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        // Large items waste little in a fresh bin; small items should go into open bins.
        score += 25.0 * (1.0 - size_ratio);
        // Late in the stream or with many open bins, opening fresh bins is fine.
        score -= 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins slightly, more so when mean residual is high
        // (bins are fragmented; consolidate into them).
        score -= 2.0 + 0.05 * mean_residual;
    }

    // Penalize placements into nearly-full bins that leave tiny unusable slivers
    // (residual 1..=5) unless it's a perfect fit.
    if post_residual > 0 && post_residual <= 5 {
        score += 6.0;
    }

    // Mild time-horizon term: early on, prefer keeping residuals flexible
    // (closer to mean_residual); later, prioritize tight packing.
    score += (1.0 - progress) * 0.03 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 300.0; // chain-perfect fit
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportional to the shortfall,
        // encouraging bins that leave room for the lookahead item.
        let shortfall = (next_item_size - post_residual as u32) as f64;
        score += 3.0 * shortfall;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize large dead space that nothing (sizes >= 1) can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins fit badly.
    if bin_residual == bin_capacity {
        // Neutral-ish base; a new bin's post_residual is large, so add a mild
        // opening penalty that good fits on existing bins can overcome.
        score += 30.0;
        // Late in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild pressure to close out bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (exact match after placement).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item also fits here: reward proportional to how well it fills.
            let two_step_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 300.0 * two_step_fill;
        } else {
            // Next item cannot use the post-residual: penalize dead space,
            // scaled by how much of the bin is wasted.
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            score += 120.0 * dead_frac;
        }
    }

    // Favor bins whose residual is already below average (tight bins first),
    // keeping large-residual bins flexible for future large items.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // placing here over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for tighter fits overall (post_residual quadratic penalty).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits terribly everywhere else. Penalize the empty-bin candidate
    // (bin_residual == bin_capacity) unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_frac = item_size as f64 / bin_capacity as f64;
        score += 200.0 * (1.0 - large_item_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10 partition dead space.
    let residue = post_residual % 10;
    let harmonic = (post_residual / 10) as f64; // number of full 10-slots left

    // Penalize leftovers that are too small to be useful (dead space).
    // A leftover < 10 is nearly unusable given min item size 1..100 unknown;
    // weight by harmonic class: prefer leftovers that are multiples of 10.
    if residue == 0 {
        score -= 6.0 * harmonic.min(8.0);
    } else {
        // non-aligned leftovers: penalty grows as residue deviates from 0/5
        let dev = residue.min(10 - residue) as f64;
        score += 1.5 * dev;
    }

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // reward proportional to how tightly next item nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0; // nested leftover stays harmonic-aligned
            }
        } else {
            // next item won't fit here: mild penalty for stranding space
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
        if post_residual <= 5 {
            score -= 30.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a fresh bin when existing fits are very poor (large post_residual
    // relative to capacity) or when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: keep it moderately high so it loses to good fits
        score = bin_capacity as f64 * 0.55;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64).ln().max(0.0);
        // open a new bin if mean residual across open bins is small (they're all tight)
        let tight = (mean_residual / bin_capacity as f64) < 0.15;
        if tight || fitting_bins_count == 0 {
            score -= 25.0 + 10.0 * crowded * (1.0 - progress);
        }
        // late in the stream, avoid spawning bins for tiny gains
        if progress > 0.9 {
            score += 10.0;
        }
    } else {
        // penalty for leaving very large holes in partially filled bins
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score += 12.0 * frac;
        }
        // slight preference for filling fuller bins (best-fit bias already via base)
        score -= 0.05 * (1.0 - frac) * (bin_residual as f64);
    }

    // Mean-residual steering: prefer bins below the mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: post_residual in (0,10] is nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: classify by capacity fractions.
    // post_residual <= 25 (quarter) is low-value space; <= 50 half; > 50 rich.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 25.0;
    } else if post_residual <= half {
        score += 5.0;
    } else {
        score -= 15.0; // leaving >half: bin stays flexible, good
    }

    // Modular class on post_residual (mod 10): residuals that are multiples
    // of 10 are more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            } else {
                score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            let overshoot = next_item_size - post_residual;
            score += (overshoot % 20) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor residuals. Base new-bin score near mean residual.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin useful
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    } else {
        // Slight preference for fuller bins when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits with small slack: still good.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit in the leftover: penalize dead space, worse when tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 80.0 * (1.0 - waste);
    }

    // Tight fits are valuable: reward small post_residual when it's still usable.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver penalty
    }
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    }

    // Compare against mean residual: prefer bins that reduce dispersion.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Base new-bin cost; lowered late in stream or when few alternatives.
        score = 150.0 - 40.0 * progress - 10.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (1..=min plausible size) are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // hard dead space penalty
    }

    // Non-linear penalty on unusable small gaps: any post_residual below the
    // smallest likely future item creates a "graveyard" gap.
    let gap = post_residual as f64;
    if gap > 0.0 && gap <= 10.0 {
        score += (11.0 - gap) * 15.0; // the smaller the leftover, the worse
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is consumed by a large fraction by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Coupling with lookahead: if the next item fits exactly in the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item would NOT fit here but would fit if we left
    // more room — i.e., post_residual is a bad trap for the lookahead.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // prefer filling existing bins when many are already open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — finishing it off is good; if far above mean,
    // lightly discourage dumping into it.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.2;

    // New-bin candidate handling: an empty bin has huge residual by
    // definition; make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins
        // could fit the item (few fitting bins => new bin is less wasteful).
        score = bin_capacity as f64 * 0.9 + (fitting_bins_count as f64) * 8.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If the item would leave a perfectly reusable residual in a new bin
        // matching the lookahead, allow the new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a small nonzero gap that likely cannot
    // host a future item is heavily penalized (quadratic in its "wastedness").
    let dead_zone: f64 = 20.0; // gaps below this are rarely reusable
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        let waste = dead_zone - post_residual as f64;
        score += 3.0 * waste * waste / dead_zone;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: late in the stream or with many open bins, discourage
    // spreading across bins; favor filling existing ones.
    score += 0.6 * open_bins_count as f64 * (0.3 + progress);

    // New-bin candidate: give it a moderate baseline so it only wins when the
    // best existing fit is poor (high post_residual / dead space).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score = 55.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item fills bin completely afterwards
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Penalize if post_residual cannot host next item but is small (dead space)
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer minimal residual
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight" -> good targets
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize wasting a very full bin on a small item
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.3 && bin_residual < bin_capacity {
        score += 10.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0
            - 10.0 * stream_progress
            - 0.5 * open_bins_count as f64;
        // If next item is large, opening fresh bin may enable pairing
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    score
}

