    // Smooth polynomial coupling: tight fits are rewarded, weighted by stream progress
    let tightness = 1.0 - norm_pr;
    score -= 45.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that can't fit the lookahead item (smooth quadratic)
    let waste = (next_norm - norm_pr).max(0.0);
    score += 30.0 * waste * waste * (1.0 - progress);

    // Last-chance bonus: strong reward, scaled by how much of the bin gets used
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0 * fit_norm * (0.5 + progress);
    }

    // Mild penalty for spreading across many bins when residuals are already large
    let spread = (mean_residual - pr) / cap;
    score += 8.0 * spread * spread;

    // Prefer using fuller bins more aggressively as stream progresses
    score -= 10.0 * progress * fit_norm;

    // New-bin candidate: penalize opening fresh bins unless residual would be well used
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * fit_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but only if post_residual
    // is large enough to still be "harmonically useful" for a future item.
    // Dead space: post_residual in [1..=9] is nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 6.0; // small leftover = big penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Harmonic class of post_residual: residues that match common item sizes
    // (multiples of 10 and small remainders) are more valuable.
    let pr = post_residual as i64;
    let class_bonus: f64 = if pr >= 10 {
        // post_residual divisible by 10 aligns with the classic item grid
        if pr % 10 == 0 { -25.0 }
        else if pr % 5 == 0 { -12.0 }
        else {
            // distance to nearest multiple of 10 -> dead-space risk
            let d = (pr % 10).min(10 - pr % 10);
            (d as f64) * 2.0
        }
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mild penalty for wasting space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // partial harmony: next item leaves a residue in a good class
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 { score -= 20.0; }
            else if npr < 10 { score += 15.0; }
            else { score -= 5.0; }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post_residual means poor fit anyway).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: empty bin has huge residual; make it unattractive when
    // a reasonable fit exists in an open bin, but attractive when open bins are bad.
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good-fit score
        score = 55.0 + (open_bins_count as f64).sqrt() * 2.0;
        // if many open bins are nearly full (low mean residual), opening fresh is fine
        if mean_residual < 20.0 {
            score -= 15.0;
        }
        // early in stream, opening new bins is cheap (future packing freedom)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // Prefer filling already-open bins: small bonus per open bin pressure.
        score -= (open_bins_count as f64) * 0.5;
        // Slight pull toward bins with residual close to item_size (tightness).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match gets a big discount; near matches get graded discount
        if diff == 0.0 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 30.0 - diff * 3.0;
        } else {
            // Penalize large leftovers that can't host the next item
            if post_residual < next_item_size {
                score += 4.0 + (next_item_size as f64 - post_residual as f64) * 0.25;
            } else {
                score += diff * 0.4;
            }
        }
    } else {
        // Last item: minimize waste directly
        score -= 10.0;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless current bin would be badly wasted
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 && post_residual < next_item_size {
            8.0
        } else {
            0.0
        };
        score = score + 25.0 - waste;
    }

    // Slight preference for filling bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_capacity - bin_residual) as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals that can't host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * next_fit;
        // Perfect chaining bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty scaled by leftover size.
        score += 0.15 * post_residual as f64 * (0.5 + 0.5 * progress);
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins
    // are fragmented or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Default mild penalty so existing bins win close calls...
        score += 8.0 + 10.0 * pressure;
        // ...but if item is large and mean residual is small, opening fresh is better.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 22.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
        let _ = fragmentation;
    }

    // Global state: spread penalty for bins far from the mean residual (balance keeping).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins as stream progresses (compaction pressure).
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping by stream progress.
    // Early on, prefer tight fits (quadratic penalty on large residual);
    // late in the stream, residual waste matters even more (cubic growth).
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr * (0.5 + progress));

    // Smooth interaction: post_residual coupled with mean residual across open bins.
    // A bin whose post-residual is far below the mean residual is a good fit.
    let mr = mean_residual.max(0.0);
    let fit_gap = (mr - pr) / cap;
    score -= 12.0 * fit_gap * fit_gap.abs().sqrt() * (1.0 + progress);

    // Lookahead coupling: reward post-residual that still accommodates next item,
    // penalize post-residual that is too small to ever be useful (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx) / cap;
        if usable >= 0.0 {
            score -= 6.0 * usable.sqrt();
        } else {
            // dead space: unusable gap before next item fits; penalize smoothly
            let dead = (-usable) * cap;
            score += 0.15 * dead * (1.0 + 0.5 * norm_pr);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin), with smooth scaling by open-bin count.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin gets a mild penalty that grows
    // with stream progress (prefer packing into existing bins late in stream),
    // but is relaxed when open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mr / cap).min(1.0);
        score = cap * (0.6 + 0.4 * progress) - 8.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream consumed
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Harmonic class of the leftover space ----
    // Residuals that are multiples of common item granularities (10, 20, 25, 50)
    // are "usable" leftovers; odd/prime-ish leftovers are dead space.
    let mut harmonic_bonus = 0.0;
    if post_residual % 50 == 0 {
        harmonic_bonus += 18.0;
    } else if post_residual % 25 == 0 {
        harmonic_bonus += 12.0;
    } else if post_residual % 20 == 0 {
        harmonic_bonus += 10.0;
    } else if post_residual % 10 == 0 {
        harmonic_bonus += 7.0;
    } else if post_residual % 5 == 0 {
        harmonic_bonus += 3.0;
    } else {
        // inharmonic leftover: penalize proportionally to how small it is
        harmonic_bonus -= (post_residual as f64).sqrt() * 0.8;
    }
    score -= harmonic_bonus;

    // ---- Lookahead coupling: can the next item land in post_residual? ----
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect harmonic match with lookahead item
        if next_item_size == post_residual {
            score -= 45.0;
        } else {
            // reward tight-but-feasible follow-up fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here: penalize if leftover is stranded small space
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // ---- Last-chance bin: strongly favor using it ----
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits harder
        score -= 2.0 * (fitting_bins_count as f64).ln();
    }

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; only attractive when current bins
        // fit badly (large post_residual would be wasted) or late in stream.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        // early stream: prefer consolidating into open bins
        score += (1.0 - progress) * 25.0;
        // many open bins with slack: discourage another bin
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Prefer bins whose residual deviates from mean in a useful (smaller) way
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for filling bins that are already well-used
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 10.0; // marginal gap
    }

    // Reward filling a bin that is the only fitting option (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins tighter than the average residual.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: favor placements leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New-bin candidate: only attractive when current bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + mean_residual * 0.2 - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // reward proportionally to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // post_residual too small for next item: penalize small dead space
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 80.0 * (10.0 - dead) / 10.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual means we consolidated well.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= 30.0 * (mean_residual - pr) / mean_residual;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could take the item,
    // unless the fit is terrible (post_residual very small already handled).
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score = full capacity residual;
        // make it unattractive unless current bins leave huge dead space.
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Small bonus for tight fits generally (low post_residual relative to capacity).
    score -= 50.0 * (1.0 - pr / bin_capacity as f64);

    // Slight preference to fill bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty to encourage spreading when many bins fit.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this is an excellent chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot fit here: mild penalty for stranding space.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item of the stream: any residual is pure waste.
        score += post_residual as f64 * 0.5;
    }

    // Global state: many open bins with high mean residual -> discourage
    // opening more space; prefer packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }
    score += 5.0 * open_bins_count as f64 * (0.3 + 0.7 * progress) / 20.0;

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let urgency = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Base cost of a new bin, discounted by fit scarcity and item bulk.
        score += 55.0 * scarcity - 30.0 * urgency * scarcity;
        // Late in the stream, avoid opening bins for small leftovers.
        if progress > 0.8 && item_size < 40 {
            score += 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Late in the stream, dead space matters more (fewer chances to fill it).
    let mut score = x * x * (1.0 + 2.0 * progress) * cap;

    // Smooth cubic interaction: mid-range residuals are penalized extra late,
    // tiny residuals (good fits) are rewarded.
    score += 0.5 * x * (1.0 - x) * (1.0 - x) * cap * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    score -= (1.0 - x).powi(3) * (2.0 + 6.0 * progress);

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill_ratio = nx / pr.max(1.0);
            score -= 3.0 * fill_ratio * (1.0 + progress);
        } else {
            // next item cannot use this residual: penalize proportional to leftover
            score += 0.02 * (pr - nx) * (0.5 + progress);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Mean residual context: prefer bins whose residual is below the mean
    // (concentrate waste in few bins) — smooth coupling.
    let mean_x = mean_residual / cap;
    score += 1.5 * (x - mean_x) * (1.0 + progress);

    // New-bin candidate: make it moderately attractive only when the fit is poor
    // (large post_residual) or late with many open bins; otherwise discourage.
    if bin_residual == bin_capacity {
        let poor_fit = x; // == 1.0 for empty bin baseline
        let _ = poor_fit;
        // empty bin has x = 1.0, base score is high; adjust with context
        score -= 4.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // discourage opening new bins when item fits well somewhere implicitly
        // via the base quadratic term already being maximal.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
