    let res_class = post_residual / 10;
    let res_mod = post_residual % 10;

    // Reward near-exact fills: post_residual in [0,5) is dead-space-free
    if post_residual < 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic penalty: residuals in awkward classes (11..19, 21..29 style gaps)
    if res_mod >= 1 && res_mod <= 5 && post_residual > 10 {
        score += (6 - res_mod) as f64 * 2.0;
    }

    // Reward if next item fits exactly into the resulting residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let pair_class = (post_residual - next_item_size) / 10;
            score -= (5 - pair_class.min(5)) as f64 * 3.0;
        } else {
            // next item cannot use this residual at all: penalize large leftover
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive for large items
    if bin_residual == bin_capacity {
        // big item into fresh bin: good (leaves predictable residual class)
        if cap_frac >= 0.5 {
            score -= 5.0;
        } else {
            // small item into fresh bin wastes capacity if other bins fit it
            score += (fitting_bins_count as f64) * 8.0 + (1.0 - cap_frac) * 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Encourage packing into bins below mean residual (consolidation)
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(30.0) * 0.4;
    }

    // Late-stream tightening: prefer tight fits as stream progresses
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Cap-class coupling: items near half capacity pair well with residual classes 40-60
    if (item_size >= 40 && item_size <= 60) && post_residual >= 40 && post_residual <= 60 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item are pure waste — penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual low) or many bins are open.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 0.5 + (mean_residual - 30.0).max(0.0);
        score += 45.0 - pressure.min(45.0);
    }

    // Mild pressure to fill existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (bin_residual - post_residual) as f64 / item_size.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect match: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize post-residuals that are too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.3 * post_residual as f64;
    }

    // Compare post_residual against mean residual: avoid creating extreme outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless no open bin is a good fit
    // (i.e., only reward opening a new bin when post_residual is large and useful).
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // two items planned into a fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += 0.2 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild superlinearity
    score += (post_residual as f64).powf(1.3) * 0.05;

    // Lookahead: if the next item fits into the post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.35 * (post_residual - next_item_size) as f64;
        } else if next_item_size <= post_residual + 8 {
            // near-miss: slight penalty for just barely blocking next item
            score += 3.0;
        }
        // If next item is huge, prefer conserving large residual bins
        if next_item_size > post_residual && post_residual > 40 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize scattering when many bins are open and residuals are fragmented
    if open_bins_count > 3 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += frag * 0.15;
    }

    // Time horizon: late in the stream, be greedy (minimize waste now);
    // early, keep residual balanced with mean residual for future flexibility
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.2;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item would leave a very awkward residual in existing bins, or few
    // bins fit and the stream is early (long horizon amortizes the bin).
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) < 10.0 || post_residual > 60;
        if awkward || (fitting_bins_count <= 2 && progress < 0.5) {
            score -= 18.0;
        } else {
            score += 30.0; // default: prefer reusing open bins
        }
    }

    // Mild penalty for very large dead space creation
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // normalized dead space after placement

    // Base: minimize leftover, with non-linear penalty on large residuals
    let mut score = post;
    score += cap * norm_post.powi(3) * (1.0 + 2.0 * progress);

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_post * (1.0 - norm_post);
    score -= cap * 0.35 * coupling * (0.5 + 0.5 * (1.0 - progress) * (1.0 - progress));

    // Lookahead: reward if next item fits the post residual (smooth reward)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            let overflow = (nxt - post) / cap;
            score += 6.0 * overflow * overflow;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post * norm_post);
    }

    // Slight preference for filling bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post) * 0.5;

    // Deviation from mean residual: prefer bins whose residual is near mean (smooth balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction buckets.
    let post = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..=3 harmonic quarter-classes

    // Reward tight fits strongly (small post_residual classes).
    match class {
        0 => score -= 30.0,                     // nearly perfect fit
        1 => score -= 12.0,                     // good residual
        2 => score -= 3.0,                      // moderate
        _ => {}                                 // wasteful class: no reward
    }

    // Dead-space penalty: residual that no plausible item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Harmonic coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Lookahead fit quality: how well next item would fill remaining space.
            let after_next = post_residual - next_item_size;
            score -= 8.0 + (after_next as f64) * 0.15;
        } else {
            // Next item won't fit here: penalize bins that strand the lookahead.
            score += 6.0 + (nxt - post) * 0.2;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early when many items remain, but costly
        // if existing bins fit decently (post_residual small).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress);
        if post_residual == 0 { score -= 40.0; } // perfect fit never open new bin
    }

    // Modulo harmonic: reward post_residuals divisible by common item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Prefer filling bins with above-average residual (balance avoidance of
    // fragmenting many bins) mildly.
    if (post as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10, min item size) are the worst.
    if post_residual < 10 {
        score -= 60.0; // perfect fill, essentially zero waste
    } else if post_residual <= 20 {
        // gap too small for most items: heavy penalty
        score += 25.0;
    } else if post_residual <= 35 {
        score += 10.0;
    } else {
        // large leftover space is reusable, mild reward
        score -= 5.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidating.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidate into emptier-of-mean bins? no:
    // favor bins tighter than average to close them out).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 20.0; // next item nearly seals this bin
            } else {
                score -= 5.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
    }

    // New-bin candidate handling: empty bin only wins when no open bin fits well.
    if bin_residual == bin_capacity {
        let stream_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: opening bins is cheap-ish; late stream: penalize new bins hard
        let new_bin_penalty = 30.0 + 40.0 * stream_frac + 1.5 * open_bins_count as f64;
        score += new_bin_penalty;
        // but if the item is huge relative to capacity and mean residual is small,
        // a fresh bin may be the only sane choice
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Slight preference for bins whose residual exceeds item size by a comfortable margin
    // to avoid fragmenting mid-sized gaps when a smaller gap would suffice.
    if post_residual > 0 && post_residual < item_size {
        score += 100.0; // should never happen (item wouldn't fit), safety guard
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual (partial chain reward)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.15;
    }
    // Next item would NOT fit: post residual becomes dead space
    else if next_item_size > 0 && next_item_size != 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual < 10 {
        score += 20.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.10;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild pressure to close bins when many are open
    score += open_bins_count as f64 * 0.5;

    // Slight late-stream conservatism: prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    // Discourage opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 40.0;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            // waste of residual if next item cannot use it
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // New-bin candidate logic: fresh bin has perfect residual; make it attractive
    // only when current bin fit is poor (large post_residual or dead space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, prefer filling existing bins
        let open_penalty = 15.0 + 40.0 * progress;
        score = bin_capacity as f64 - open_penalty
            + 0.1 * open_bins_count as f64
            + 0.2 * mean_residual;
        // If next item is large, a fresh bin is more valuable
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins with below-mean residual (more crowded bins fill first)
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild pressure to keep number of open bins bounded as stream progresses
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual and fit quality
    let pr = post_residual as f64;
    let prn = pr / cap;
    let item_n = item_size as f64 / cap;

    // Non-linear polynomial coupling: quadratic + cubic shaping of post residual
    // Small post residuals are excellent (tight fit), large ones wasteful.
    score += 12.0 * prn * prn - 8.0 * prn * prn * prn;

    // Smooth interaction between fit tightness and stream progress:
    // early in stream, tolerate larger residuals (future items may fill them);
    // late in stream, penalize dead space more strongly.
    let progress_coupling = (prn - 0.5) * (prn - 0.5) * (1.0 - progress) * 6.0;
    score += progress_coupling;

    // Cubic coupling of item size with residual: prefer filling bins with large items tightly
    score -= 4.0 * item_n * item_n * (1.0 - prn) * (1.0 - prn);

    // Lookahead: if next item fits in the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            // smooth penalty proportional to overshoot
            let over = (nxt - pr) / cap;
            score += 5.0 * over * over;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - prn * prn);
    }

    // Global residual pressure: if mean residual across open bins is high,
    // encourage consolidating into existing bins rather than opening new ones.
    let mean_norm = mean_residual / cap;
    score += 3.0 * mean_norm * mean_norm * prn;

    // New-bin candidate handling: an empty bin has prn == 1.0; penalize it smoothly
    // unless the item is large relative to residual elsewhere (handled by coupling above).
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress) * (1.0 - item_n);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor placements leaving near-zero residual.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Harmonic class of the leftover: classify post_residual into residue bands.
    let band = post_residual % 25;
    match band {
        0 => score -= 12.0,          // leftover is a "nice" fraction of capacity
        1..=10 => score += 8.0,      // awkward small dead space
        11..=20 => score -= 3.0,     // moderate, reusable
        _ => score -= 8.0,           // large leftover, very reusable
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // how well next item harmonically divides the leftover
            let k = post_residual / next_item_size.max(1);
            score -= 6.0 * (k.min(4) as f64);
        } else {
            // next item cannot use leftover: penalize proportionally to wasted potential
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap_f);
        }
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // current fit is poor. Empty-bin call gets post == cap_f, band 0 gives -12.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // If next item is large and current bin would be nearly emptied anyway,
        // slightly favor fresh bins late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress * (1.0 - item_size as f64 / cap_f);
    }

    // Prefer bins whose residual is far from mean (specialized niches).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Mild preference for filling bins with small residual already.
    score += 0.1 * (bin_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item are "dead". Penalize them super-linearly.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * fill_ratio * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; a large post residual is wasted unless reusable.
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.5;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + fill_ratio * 20.0;
    }

    // New-bin candidate: opening a bin should only win when the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + open_bins_count as f64 * 1.5;
        // But if the item would leave a dead gap in every existing bin, a fresh
        // bin is attractive: discount the new-bin penalty for large items.
        if fill_ratio > 0.8 {
            score -= 40.0;
        }
        // Late in the stream, opening new bins is riskier (leftover space unused).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Open-bins pressure: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into bins that reduce spread.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += spread * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: does next item exactly fill post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits here later; mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize small residuals
            if post_residual < 10 {
                score += 30.0;
            }
        }
    } else {
        // last item: prefer exact fits only
        score += (post_residual as f64) * 0.5;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when reasonable open bins exist
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // but allow a new bin if current item creates very poor fit everywhere
        if next_item_size > 0 && post_residual == bin_capacity as u32 - item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (wasted space < 10).
    if post_residual < 10 {
        score -= 30.0 * (10.0 - post_residual as f64);
    }

    // Penalize dead space: residual that no plausible item (1..=80) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to encourage spreading.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for chaining: next item would leave another usable residual.
        let chain_residual = post_residual as f64 - next_item_size as f64;
        if chain_residual < 10.0 {
            score -= 8.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow: this residual is likely stranded.
        score += 6.0;
    }

    // Global state coupling: compare this bin's residual to the mean residual.
    let resid = bin_residual as f64;
    if resid > mean_residual + 20.0 {
        // This bin is unusually full already; prefer tighter bins elsewhere.
        score += 4.0;
    } else if resid < mean_residual - 20.0 {
        // Sparse bin: placing here wastes its large capacity.
        score += 3.0;
    }

    // Time horizon: early in the stream, be conservative about opening new bins
    // (many items remain, so keep bins flexible); late in the stream, allow
    // tighter, more aggressive fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = 1.0 + 2.0 * progress;
    score *= tightness;

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream fills up.
        let open_cost = 40.0 - 20.0 * progress;
        score = open_cost + item_size as f64;
        // If only this new bin can fit the item, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Avoid opening new bins early when open bins exist that fit.
        if open_bins_count > 0 && progress < 0.5 {
            score += 15.0 * (0.5 - progress);
        }
    }

    // Small regularization to break ties deterministically.
    score += 0.001 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: leftover space, mildly discounted early (waste matters more later).
    let mut score = pr * (0.6 + 0.8 * progress);

    // Non-linear polynomial coupling: squared post-residual penalizes large dead space,
    // weighted by stream progress (late waste is costlier).
    score += (pr * pr / cap) * (0.25 + 0.75 * progress * progress);

    // Cubic interaction: residuals that are "awkward" (large but not reusable by next item)
    // get extra penalty; if next item fits in post_residual, reward the bin.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // next item slots perfectly or well: reward proportionally to tightness
            let tight = (pr - ni) / cap;
            score -= 8.0 * (1.0 - tight) * (1.0 + progress);
            score -= 6.0 * (ni / cap) * (1.0 - progress);
        } else {
            // dead space relative to lookahead: cubic-ish penalty
            let dead = pr / cap;
            score += 5.0 * dead * dead * dead * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * progress;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score -= 2.5 * (mean_residual - pr) / cap;

    // Mild preference for keeping the number of open bins low.
    score += 0.15 * open_bins_count as f64;

    // Smooth preference for very tight fits (post residual near zero) via exp-like term.
    score -= 4.0 * (-pr / 15.0).exp() * (1.0 + progress);

    // New-bin candidate: make it attractive only when current bin would leave bad residue.
    if bin_residual == bin_capacity {
        // neutral-ish base; opening a new bin is good if this item is small relative to cap
        score = 10.0 + 20.0 * (it / cap) * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap - it {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer-division tiers.
    let post = post_residual;
    let tier = post / 10; // 0..=10 harmonic tier
    let residue = post % 10;

    // Penalize awkward residues (dead space that rarely fits 10..80 items well).
    let residue_penalty: f64 = match residue {
        0 => -6.0,   // perfect fill class
        1..=9 => residue as f64 * 0.35,
        _ => 0.0,
    };
    score += residue_penalty;

    // Reward large post_residual only in high tiers (bin stays reusable),
    // but penalize extreme waste (item too small for this bin).
    match tier {
        0 => score -= 12.0, // near-perfect fit
        1 => score -= 5.0,
        2 => score += 2.0,
        3 => score += 6.0,
        4 => score += 10.0,
        5 => score += 14.0,
        6 => score += 18.0,
        7 => score += 22.0,
        8 => score += 26.0,
        9 => score += 30.0,
        _ => score += 34.0,
    }

    // Coupling with next item (k=2 lookahead): harmonic match between
    // post_residual and next_item_size classes.
    if next_item_size > 0 {
        let next = next_item_size.min(bin_capacity);
        if next <= post {
            // Next item fits exactly into this bin's future residual:
            let gap = post - next;
            let gap_res = gap % 10;
            score -= match gap_res {
                0 => 10.0,
                1..=9 => 4.0 - gap_res as f64 * 0.2,
                _ => 0.0,
            };
        } else {
            // Next item cannot use this bin: mild penalty scaled by overflow class.
            let over = (next - post) / 10;
            score += 2.0 + over as f64 * 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline so it wins only when
    // all open bins would create bad harmonic classes.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= post {
            score -= 4.0;
        }
    }

    // Slight preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Progress coupling: late in the stream, prefer tighter fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - (post as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score -= 3.0 * pressure * tightness;

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual would otherwise dominate; offset baseline).
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * pressure;
    }

    // Lookahead: if next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: exact match between leftover and next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack / 20.0); // next item still fits, reward closeness
        } else {
            let miss = (next_item_size - post_residual) as f64;
            // leftover smaller than next item: dead space penalty grows as miss shrinks
            score += 25.0 * (1.0 - miss / (next_item_size as f64).max(1.0)) * (60.0 / (60.0 + post_residual as f64));
        }
    }

    // Reward filling bins tightly relative to mean residual.
    if post_residual < mean_residual {
        score -= (mean_residual - post_residual) * 0.8;
    } else {
        score += (post_residual - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when good open bins exist and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 50.0 * (1.0 - progress) + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin may be wise
        }
    }

    // Mild penalty for tiny unusable leftovers.
    if post_residual > 0 && next_item_size > 0 && post_residual < 10 && post_residual < next_item_size {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (add) when post residual is large relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 18.0;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            // Dead space penalty scaled by how far short we fall.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // If next item fits exactly, extra reward.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state coupling: with many open bins, prefer consolidation
    // (penalize spreading residual thin across bins).
    let open_f = open_bins_count as f64;
    score += 0.3 * open_f * (post_residual as f64 / bin_capacity as f64);

    // Mean residual deviation: bins far below mean residual waste potential;
    // prefer bins whose residual is close to (or below) the mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in stream, be pickier about dead space; late in
    // stream, prioritize just packing things in (favor any fitting bin).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);
    if progress > 0.8 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no existing bin fits well
    // (i.e., many fitting bins means spreading is wasteful) or residuals are tiny.
    if bin_residual == bin_capacity {
        let spread_pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).ln().max(0.0)
        } else {
            0.0
        };
        // Base cost of a fresh bin; reduced when open bins are nearly full on average.
        let avg_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 35.0 + 10.0 * spread_pressure - 20.0 * avg_fullness;
        // Late in stream, opening new bins is more acceptable.
        score -= 15.0 * progress;
        // If lookahead item is large, a fresh bin is safer.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;                       // normalized post residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = (item_size as f64) / cap;    // normalized item size
    let look = (next_item_size as f64) / cap;

    // Base: quadratic waste penalty on post residual (smooth, non-linear)
    let mut score = x * x * cap;

    // Smooth interaction: late in the stream, tight closures are worth more,
    // so reward small post residuals progressively via cubic coupling.
    let tightness = (1.0 - x).clamp(0.0, 1.0);
    score -= progress * 12.0 * tightness * tightness * tightness * cap;

    // Perfect/near-perfect fit reward (smooth exponential-like trough via polynomial)
    let perfect = 1.0 - (x * 4.0).min(1.0);
    score -= 8.0 * perfect * perfect * (0.3 + 0.7 * progress);

    // Lookahead coupling: penalize leaving a residual that neither fits the
    // next item well nor is tiny (dead space), as a smooth bump.
    let gap = (x - look).abs();
    let dead = (1.0 - (gap * 3.0).min(1.0)) * x;
    score += 6.0 * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * tightness;
    }

    // New-bin candidate handling: empty bin gets a mild inertia penalty that
    // shrinks as the stream progresses (opening fresh bins is worse early).
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0 * fill;
    }

    // Mild diversity term: avoid fragmenting when many bins are open.
    score += (open_bins_count as f64).ln() * 0.5 * x;

    // Mean-residual anchoring: prefer bins close to the fleet mean residual
    // to keep residuals balanced (smooth quadratic deviation).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let post_class = post_residual / (bin_capacity / 10); // classes of width 10
    let next_class = if next_item_size > 0 { next_item_size / (bin_capacity / 10) } else { 0 };

    // Reward when the leftover class can exactly host the next item's class.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // Perfect chaining: next item fills bin exactly or nearly.
        score -= 30.0 * (1.0 - slack as f64 / cap);
        // Harmonic class match bonus: same decile => likely tight reuse.
        if post_class == next_class {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // Dead space for the lookahead item: penalize by unusable fraction.
        score += 8.0 + 10.0 * (post_residual as f64 / cap);
    }

    // Tight-fit reward: small post_residual relative to capacity.
    score -= 20.0 * (1.0 - post_residual as f64 / cap);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would create large dead space.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        let waste = (post_residual as f64) / cap;
        if post_residual > 0 && waste > 0.4 && crowded > 0.5 {
            score -= 15.0; // prefer fresh bin over a very wasteful fit
        } else {
            score += 40.0; // discourage opening new bins by default
        }
    }

    // Harmonic modulo coupling: bins whose residual is a multiple of common
    // item sizes (10/20/40) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    // Slight preference for bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (assume ~10)
    // or smaller than the next item when the next item could otherwise be paired.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space: wasted capacity
        } else if next_item_size > 0 && post_residual < next_item_size {
            // gap cannot host the lookahead item: mild penalty scaled by how much it misses by
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // usable gap: reward proportionally to how flexible the gap is
            score -= 6.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits: fraction of residual consumed by the item.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has residual == capacity, so penalize it there.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if no open bin fits well (post_residual huge relative to capacity), soften
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (more full bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate: extra pressure against new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // If this bin can also host the next item after placement, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (post_residual small relative to capacity)
    let tightness = (post_residual as f64) / cap;
    score += tightness * 10.0; // base scale: smaller post_residual => lower score

    // Aggressive 2-step lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 30.0 + 20.0 * (next / cap);
            // extra reward if the two items nearly fill the bin
            let combined = (item_size + next_item_size) as f64 / cap;
            score -= 25.0 * combined;
        } else {
            // next item cannot follow here: penalize leaving a gap next item could have used elsewhere
            let gap = post_residual as f64;
            if gap > 0.0 && next > gap {
                score += 8.0 * (1.0 - gap / next);
            }
        }
    }

    // Compare residual to mean residual across open bins
    if mean_residual > 0.0 {
        let rel = (post_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 12.0 * (1.0 - rel); // better than average residual: favor
        } else {
            score += 6.0 * (rel - 1.0).min(2.0); // worse than average: penalize
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let waste_here = (bin_residual - item_size) as f64;
        let poor_fit = if fitting_bins_count > 0 {
            let best_alt = fitting_bins_count; // existence of alternatives
            // penalize new bin more when other bins can fit and lookahead is favorable
            40.0 - 15.0 * (best_alt as f64).min(3.0)
        } else {
            -10.0
        };
        score = waste_here + poor_fit;
        // If next item is large and would fit the fresh bin residual, make new bin attractive
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 15.0;
        }
        // Early in stream, new bins are cheap; late, avoid fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Prefer filling bins with larger residual usage when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: quadratic coupling of post_residual with progress.
    // Early in the stream, prefer leaving flexible space; later, minimize post residual hard.
    let tightness_weight = 1.0 + 2.0 * progress;
    score -= tightness_weight * (cap - post) / cap * 10.0;

    // Penalize very small unusable residuals (dead space) with smooth saturating term.
    let dead = post / cap;
    score += 15.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - progress);

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 8.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            // next item won't fit here; mildly penalize leaving large residual it can't use
            score += 2.0 * (gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it is only
    // chosen when no open bin offers a good fit (its raw post is cap - item).
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.5 * progress) + 0.5 * open_bins_count as f64;
    }

    // Encourage balancing residuals across open bins: prefer bins whose post residual
    // is close to the mean residual (smooth interaction).
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * cap / 100.0;

    // Slight penalty for proliferating bins early in the stream.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "composable" class (small multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are exactly representable by typical item sizes
        // (harmonic divisors of capacity).
        let harmonic_divs: [u32; 6] = [10, 20, 25, 40, 50, 100];
        for d in harmonic_divs {
            if pr % d == 0 {
                score -= 6.0 * (d as f64 / 100.0);
                break;
            }
        }
        // Penalize residuals in "dead" bands: too small for the smallest item (1)
        // but awkwardly below common sizes.
        if pr < 10 && pr > 0 {
            score += 8.0; // near-dead space
        }
        // Modulo-10 class bonus: residuals divisible by 10 compose well.
        if pr % 10 == 0 {
            score -= 3.0;
        }
    } else {
        // Perfect fit: strongly rewarded.
        score -= 25.0;
    }

    // Integer-division threshold on residual: residual >= 50 is "half-open" class,
    // keep such bins attractive.
    if bin_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportional to tightness of the pair fit.
            let pair_tight = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - pair_tight / cap).max(0.0);
        } else {
            // Next item won't fit here: mild penalty for hoarding space.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: its post_residual equals capacity - item.
        score += 5.0;
        if item_size >= 60 {
            score -= 6.0; // large items are fine in fresh bins
        }
        // If many bins are open with big mean residual, discourage more bins.
        score += 0.5 * open_bins_count as f64;
        score += 0.05 * (mean_residual - cap * 0.5).max(0.0);
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_residual / cap);

    // Tight-fit reward: item filling most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small non-zero gaps are the worst outcome: they are hard to reuse.
    // Penalize them sharply so a perfect fill (post_residual == 0) dominates,
    // and a tiny leftover (1..=10) ranks worse than a comfortably reusable gap.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Exponential "usefulness" of the leftover space: tiny gaps are nearly useless.
        score += 28.0 * (-pr / 9.0).exp();
        // Extra hard penalty for the most pathological slivers (1..=5 units).
        if post_residual <= 5 {
            score += 18.0;
        } else if post_residual <= 10 {
            score += 7.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // --- Lookahead coupling: does the leftover still fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leftover remains usable for the upcoming item.
            score -= 4.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Leftover is dead with respect to the next item.
            score += 6.0;
        }
    }

    // --- Fit quality relative to the fleet's mean residual ---
    // Preferring bins whose post-residual sits well below the mean squeezes
    // the "full" bins first and keeps a pool of large reusable gaps.
    let fit_gap = mean_residual - pr;
    if fit_gap > 0.0 {
        score -= 0.15 * fit_gap.min(40.0);
    }

    // --- Open-bins pressure: when many bins are open, strongly prefer
    // consolidating into an existing bin over spawning a new one. ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).powf(0.85) * (0.5 + 0.7 * progress);
    score -= pressure;

    // --- Last-chance bonus: if this is the only bin that fits, use it
    // rather than opening a fresh bin (unless it would create dead space). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual > 0 && post_residual <= 5 {
            score += 10.0; // ...but not if it produces a sliver.
        }
    }

    // --- New-bin candidate calibration ---
    // A brand-new empty bin has bin_residual == bin_capacity; its raw
    // post_residual is huge, but give it a mild nudge so it only wins when
    // every open bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            // Perfect 2-step fit: place here, next item seals the bin.
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 25.0;
        } else if diff <= 10.0 {
            score -= 12.0;
        } else {
            // Penalize residuals that are large enough to be "wasted" but not usable.
            score += diff * 0.35;
        }

        // If next item is too big for this bin's post-residual, slight penalty
        // (dead space), unless post_residual is tiny anyway.
        if post_residual < next_item_size {
            score += (post_residual as f64) * 0.15;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual deviates
    // favorably (smaller) from the mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when it enables a perfect
    // 2-step pairing (item + next item = full bin), otherwise penalize.
    if bin_residual == bin_capacity {
        let pair = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && (bin_capacity as f64 - pair).abs() <= 2.0 {
            score -= 20.0; // fresh bin that will be perfectly sealed next step
        } else {
            score += 40.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Late in the stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Reward tight fits relative to capacity (non-linear coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how much would remain.
            score -= 20.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item would not fit here: penalize if it would fit in the residual now.
            if next_item_size <= bin_residual {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Global state coupling: if many open bins with high mean residual,
    // prefer consolidating into bins with residual below the mean (fill the emptier ones).
    if open_bins_count > 1 && mean_residual > 0.0 {
        let rel = bin_residual as f64 - mean_residual;
        score += 2.0 * rel;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize using existing bins less); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, costly late.
        score -= 80.0 * (1.0 - progress);
        score += 120.0 * progress;
        // Never open a new bin if a perfect fit exists elsewhere is handled by score ordering;
        // also discourage opening when many bins are open.
        score += 5.0 * open_bins_count as f64 * progress;
    } else {
        // Reward using existing bins more as stream progresses.
        score -= 60.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Penalize leaving large awkward residuals (dead space) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small residual is fine (nearly full)
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 10.0; // awkward zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 8.0 * poly;

    // Reward tight fits, more so late in the stream.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (4.0 + 6.0 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bin bonus (smooth, amplified by progress).
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let waste = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - waste * waste);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Congestion term: many open bins -> prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // New-bin candidate: only attractive for large items / poor fits.
    if bin_residual == bin_capacity {
        score -= 6.0 * (item_size as f64 / cap);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    score -= 30.0 * (1.0 - (post_residual as f64 / cap)).powi(4);

    // Harmonic classes of post_residual: small modulo classes are reusable.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus = match class {
        0 => 18.0,
        1 | 2 | 3 => 10.0,
        4 | 5 | 6 => 4.0,
        _ => -6.0, // dead-ish space classes 7..9
    };
    score -= class_bonus;

    // Integer-division threshold: post_residual divided into size bands.
    let band = pr / 20; // 0..=5
    score -= match band {
        0 => 15.0,
        1 => 8.0,
        2 => 2.0,
        3 => 0.0,
        4 => -4.0,
        _ => -8.0,
    };

    // If next item fits exactly in post_residual, big reward (chained fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; penalize proportionally to wasted slack
            score += 5.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into bins with low residual (below mean).
    if open_bins_count > 0 && (post_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current fit is bad
    // or nothing meaningful can be chained. Penalize opening bins early.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40 || (next_item_size > 0 && next_item_size > post_residual);
        if bad_fit {
            score -= 10.0;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Late in stream: squeeze items into existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10.0f64; // items are >=1, but tiny gaps rarely reusable
    if (post_residual as f64) < dead_threshold {
        // unusable sliver: penalize hard, scaled by how close to zero
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Penalize "awkward" residuals: gaps that only fit very small items
    // (e.g. <= 20) are low-utility dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (20 - post_residual) as f64 / 20.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 10.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; this residual becomes dead space
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - 0.5 * progress);

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // only chosen when open bins offer poor fits (high dead space).
    if bin_residual == bin_capacity {
        // penalize proportional to how many bins already fit the item
        score += 30.0 + 5.0 * fitting_bins_count as f64;
        // early in the stream, opening a bin is more acceptable
        score -= 15.0 * (1.0 - progress);
        // if no existing bin can fit, opening is necessary
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // below average (more filled), avoiding the emptiest bins for small items.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0 - 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Perfect 2-step match: next item exactly fills post_residual -> strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits into post_residual: good lookahead chaining
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit into post_residual: penalize, worse if post_residual is large dead space
    else if next_item_size > 0 {
        score += 10.0 + 0.3 * post_residual as f64;
    }

    // Reward closeness of post_residual to mean residual (keeps bins homogeneous)
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= 0.2 * (bin_capacity as f64 - dev);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space relative to item size: small post-residual that
    // cannot fit typical future items is wasted.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size >= item_size {
            // Next item is bigger; keep larger residuals available.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a
    // near-perfect fit or the stream is early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let perfect = (item_size as f64 / bin_capacity as f64) > 0.9;
        if perfect {
            score -= 20.0;
        } else if progress < 0.3 && open_bins_count > 4 {
            score -= 2.0;
        } else {
            score += 10.0;
        }
    }

    // Spread management: penalize bins far from the mean residual to keep
    // the bin portfolio homogeneous (easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening too many bins relative to stream size.
    if open_bins_count as f64 > 0.5 * (step_index as f64 + 1.0) {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap; // fraction of bin used after placement

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = post * (1.0 + 0.8 * (post / cap));

    // Smooth non-linear coupling: reward tight fits more as stream progresses
    let tightness = (fill * fill * (3.0 - 2.0 * fill)).clamp(0.0, 1.0); // smoothstep on fill
    score -= 30.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize post-residual that matches neither current nor next item (dead space)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (post - next).abs() / cap;
        score += 12.0 * (1.0 - (-4.0 * gap).exp()) * (1.0 - progress);
        // Reward exact chain fit: item then next_item
        if post >= next {
            score -= 8.0 * (next / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one fitting bin -> avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.5 * open_bins_count as f64 * (1.0 - fill);

    // Alignment with mean residual: prefer bins near the mean (balanced packing)
    score += 3.0 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only when no open bin fits well
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score = cap - 10.0 * (1.0 - progress) + 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0; // last chance failed elsewhere -> open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: tiny leftovers are dead space.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 60.0; // worst class: nearly unusable sliver
    } else if pr > 10 && pr <= 20 {
        score += 25.0;
    } else if pr > 20 && pr <= 30 {
        score += 8.0;
    } else if pr == 0 {
        score -= 40.0; // perfect closure
    }

    // Modular residue classes (mod 10) of post_residual: values that pair
    // with common item sizes (multiples of 10) are more reusable.
    let m = pr % 10;
    if pr > 0 {
        score -= (10 - m) as f64 * 1.5; // residue closer to a multiple of 10 is better
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 45.0;

    // Lookahead coupling: if the next item can fit into the post residual,
    // reward; if it cannot, penalize proportionally to the mismatch.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // exact or near-exact chaining
            let chain_gap = pr - next_item_size;
            if chain_gap <= 5 {
                score -= 12.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the
    // empty bin attractive only when it is genuinely needed.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 45.0; // an existing bin is the last chance: keep it alive
        } else {
            score += 20.0; // mild preference to reuse existing bins
        }
        // late in the stream, avoid spawning bins that will stay mostly empty
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Crowd penalty: when many bins are open, prefer consolidating into
    // bins with below-mean residual (i.e., tighter bins).
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10) can use are poison.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving residual that likely fits the lookahead item (k=2 lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item: mild penalty scaled by near-miss
        score += 6.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (tighter bins get filled first),
    // penalizing bins that are unusually empty relative to the mean.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large dead space would result elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < 10.0 {
            score += 10.0; // next item nearly fills a fresh bin: good to open
        }
    }

    // Slight preference for filling fuller bins overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Reward closeness of post_residual to the lookahead item
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-diff / 20.0).exp();
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // very small post_residual (<10) is near-perfect packing; very large is wasteful.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // excellent tight fit
    }
    if post_residual > 50 {
        score += 0.5 * (post_residual as f64 - 50.0); // discourage leaving huge holes
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to residual space elsewhere or no tight option exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so existing bins usually win...
        score += 55.0;
        // ...unless the item is big (poor fit likely anywhere) late in the stream.
        if item_size >= 60 {
            score -= 30.0 + 10.0 * progress;
        }
        // If next item is huge too, a fresh bin keeps flexibility.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Slight preference for filling fuller bins (smaller residual before placement).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // Mild pressure against proliferating many open bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few typical items (1..100) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild exploration bonus when many bins fit: pick the best-fit one.
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            if next_fit > 0.85 {
                score -= 10.0 * next_fit;
            } else if next_fit > 0.5 {
                score -= 4.0 * next_fit;
            }
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slightly penalize wasting residual space.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: with many open bins, prefer consolidating into fuller bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fullness * (open_bins_count as f64).ln().max(1.0);

    // Mean residual deviation: prefer bins whose residual is below average (fuller bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Dynamic time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 8.0 + 20.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is attractive if the item is large and no open bin fits well.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: post residual, with non-linear shaping (dead space penalized super-linearly).
    let mut score = pr * (1.0 + 0.6 * prn * prn);

    // Smooth coupling with stream progress: tighter packing valued more later in stream.
    score += 12.0 * prn * progress;

    // Reward tight fits smoothly: gaussian-like bump around small post_residual.
    let tightness = (-8.0 * prn * prn).exp();
    score -= 18.0 * tightness;

    // Penalize when bin residual barely exceeds item (wasteful near-full use) unless tight.
    let waste = (bin_residual as f64 - item_size as f64) / cap;
    score -= 6.0 * (1.0 - waste) * (1.0 - waste) * (1.0 - progress);

    // Last-chance bonus: only fitting bin should be favored.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that can host next item smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = (pr - ns).max(0.0);
        let compat = (fits_next / cap).max(0.0).min(1.0);
        score -= 8.0 * compat * (1.0 - compat) * 4.0;
        // Penalize leaving residual just below next item (dead zone), smooth via sigmoid.
        let dead = 1.0 / (1.0 + (-(pr - ns) / 5.0).exp());
        score += 9.0 * dead * (1.0 - (prn * prn));
    }

    // Mild diversity penalty relative to mean residual (avoid extreme outliers).
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make empty bin moderately attractive only early or when fit is poor.
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress);
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space quality by integer division
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: tiny unusable slivers (<10) — strongly penalize
    if post_residual < 10 {
        score += 40.0;
    }
    // Class 2: unusable gap (10..=item floor classes) — penalize proportionally
    else if post_residual < item_size.max(10) {
        score += 15.0;
    }

    // Perfect fit reward: post residual is 0 or an exact harmonic fraction of capacity
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual * 2 == bin_capacity {
        score -= 25.0;
    } else if post_residual * 3 == bin_capacity {
        score -= 15.0;
    } else if post_residual * 4 == bin_capacity {
        score -= 10.0;
    }

    // Residual divisible by small harmonics (2,4,5) is more reusable
    if post_residual % 2 == 0 { score -= 3.0; }
    if post_residual % 5 == 0 { score -= 3.0; }
    if post_residual % 10 == 0 { score -= 4.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item divides post residual
            if post_residual % next_item_size == 0 {
                score -= 12.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize tight fills more
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, slightly above good fits
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0; // new bin can host next item too
        }
    }

    // Mild preference to fill bins below mean residual (balance exploitation)
    score -= 0.05 * (mean_residual - pr);

    // Early stream: encourage opening bins less; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest item (1) are pure loss;
    // gaps that can't fit the lookahead item are semi-dead.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // can't accommodate lookahead item
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0; // exact lookahead fit
    }

    // Reward tight fits proportionally
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins would leave bad gaps
    if bin_residual == bin_capacity {
        let stream_progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins mildly, more as stream progresses
        score += 18.0 + 10.0 * stream_progress + 1.5 * open_bins_count as f64;
        // but if lookahead item is large, a fresh bin is fine
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward if the next item fits into the post residual ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains perfectly: strong reward proportional to how snugly it fits.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack_after_next * 0.5;
        } else {
            // Next item won't fit here: penalize dead space that blocks the lookahead.
            let wasted = (next_item_size - post_residual) as f64;
            score += wasted * 0.8;
        }
    }

    // --- Perfect fit bonus ---
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small unusable-ish gap: mild penalty on top of base.
        score += 15.0;
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score -= (mean_residual - post_residual as f64) * 0.3;

    // --- Last chance: this is the only open bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New empty bin candidate: make it costly unless it is genuinely better ---
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; large items justify it more.
        score += 90.0 - item_size as f64 * 0.6;
        // Late in the stream, prefer reusing existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // --- Prefer filling larger items into bins with larger residuals (pair big with big slack) ---
    score += (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - post_residual as f64) * 0.2;

    // --- Crowding: many open bins -> favor consolidation ---
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + progress * progress);

    // Polynomial coupling of normalized post-residual with progress:
    // late in the stream, small residuals are less valuable; penalize large dead space
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual relative to item)
    score -= 25.0 * norm_item * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, reward this bin
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 15.0 * fit_quality * (0.5 + progress);
        } else {
            // next item won't fit: penalize leaving a residual that's too big to be useful
            score += 10.0 * (ns / cap) * (pr / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr * 0.5);
    }

    // Many open bins: mild penalty to discourage spreading items across bins
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating below mean (consolidate large residuals)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev - 8.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize slightly unless residuals are mostly unusable
    if bin_residual == bin_capacity {
        let unusable = if mean_residual > 0.0 {
            (mean_residual / cap).powi(2)
        } else {
            0.0
        };
        score = cap + 20.0 - 60.0 * unusable * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: exact quarters of capacity are "good" states.
    let quarter = bin_capacity / 4;
    let harmonic_bonus = if post_residual == 0 {
        -40.0 // perfect fit
    } else if post_residual % quarter == 0 {
        -18.0 // leaves a reusable harmonic class (25/50/75)
    } else if post_residual % (bin_capacity / 5) == 0 {
        -10.0
    } else if post_residual < 10 {
        25.0 // dead space: unusable for any future item
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: reward if next item fits into the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next == 0 {
                score -= 30.0;
            } else if slack_after_next % quarter == 0 {
                score -= 14.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += 6.0; // next item won't chain here
        }
    } else {
        // last item: any non-zero residual is waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this is an early step with room to consolidate later.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = cap * 0.9 + fragmentation * 0.3 + open_bins_count as f64 * 2.0 - progress * 10.0;
        if fitting_bins_count == 1 {
            score += 40.0; // never open new when a lone bin can fit the item
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score -= 15.0; // new bin can host the upcoming big item
        }
    }

    // Mild tie-breaking: prefer fuller bins (smaller residual) and modest bin counts.
    score += open_bins_count as f64 * 0.05;
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual in general).
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += 0.3 * open_bins_count as f64;

    // Last-chance bin bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Penalize new-bin opening when existing bins can absorb the item well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    // Late-stream conservatism: prefer filling existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead-space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain: this bin then next item exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward chains that keep slack small (tight 2-step packing)
            if slack <= 5.0 {
                score -= 200.0;
            } else {
                score -= 50.0 / slack;
            }
        } else {
            // next item cannot follow in this bin: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no tight fit exists elsewhere
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 250.0;
        // but if lookahead suggests a fresh bin can host a good chain, soften
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0;
        }
        // late in stream, avoid opening bins needlessly
        if next_item_size == 0 {
            score += 400.0;
        }
    }

    // Mild preference for fuller bins overall
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Small penalty for many open bins to discourage bin proliferation
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fragmentation penalty relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 1.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Time horizon: late in stream, prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Many open bins: penalize spreading, favor filling existing ones
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        if poor_fit && open_bins_count > 0 {
            score -= 10.0;
        } else {
            score += 18.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste tolerance is low (quadratic in post_norm); late, keep bins tight.
    let p2 = post_norm * post_norm;
    let p3 = p2 * post_norm;
    score += 18.0 * p2 * (0.5 + progress) + 12.0 * p3 * (1.0 - progress);

    // Interaction: residual relative to mean residual across open bins
    let mean = if mean_residual.is_finite() { mean_residual } else { cap };
    let rel = (bin_residual as f64 - mean) / cap;
    score += 8.0 * rel * rel - 4.0 * rel;

    // Lookahead coupling: bonus if next item fits post_residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = post - nxt;
        if fit_gap >= 0.0 {
            let g = fit_gap / cap;
            score -= 14.0 * (1.0 - g) * (1.0 - g * g);
        } else {
            score += 6.0 * (-fit_gap / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - p2);
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * post_norm * 3.0;

    // Small new-bin bias so empty bins are chosen only for large items / poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with
    // common item sizes (multiples of 10) are more reusable.
    let r = post_residual;
    let class = r % 10;
    let class_bonus = match class {
        0 => 18.0,                      // perfect multiple of 10: pairs with almost anything
        5 => 8.0,                       // half-class: still quite reusable
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        3 | 7 => -2.0,
        _ => -5.0,                      // 4 | 6: awkward dead space
    };
    score -= class_bonus;

    // Integer-division threshold: residual usable if it exceeds the minimum item size.
    if r >= 10 {
        score -= 6.0;
    } else if r > 0 {
        score += 12.0; // unusable sliver
    } else {
        score -= 25.0; // perfect closure
    }

    // Lookahead coupling: reward if next item fits exactly or well into post-residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;              // perfect next fit
        } else if next_item_size <= r {
            let frac = next_item_size as f64 / r.max(1) as f64;
            score -= 10.0 * frac;       // better fill fraction, better score
        } else {
            score += 4.0;               // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or current fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let bad_fit = (bin_residual - item_size) as f64;
        score = 55.0 + crowded * 6.0 - bad_fit * 0.2;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= 60 && item_size >= 60 {
            score += 15.0; // two big items: keep fresh bin for pairing
        }
    }

    // Late-stream tightening: waste matters more as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.35 * progress;

    // Slight preference for bins tighter than the mean (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
