    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: neutral baseline with mild penalty so it's chosen
    // only when all open bins look bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly (or nearly) matches next item size:
    // the leftover space is immediately usable by the lookahead item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / 50.0).max(-1.0);
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step match: chain closes exactly
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer the fullest possible packing
        score -= 10.0;
    }

    // Reward tight fits overall
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * fill;

    // Penalize small unusable residuals (dead space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins below mean residual slightly (balance), but keep tight fits dominant
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // a large, mismatched residual. Empty-bin call: post_residual == capacity.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow new bin if item is large and no tight fit is possible elsewhere
        if item_size >= bin_capacity * 9 / 10 {
            score -= 45.0;
        }
    }

    // Slight preference to fill older bins as stream progresses
    score += 0.002 * (step_index as f64 / total_items.max(1) as f64) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
