        let tight = (mean_residual - item_size as f64).abs() < 5.0;
        if tight && open_bins_count > 0 {
            score -= 30.0;
        } else {
            score += 60.0 + 80.0 * (1.0 - progress);
        }
    }

    // Mild preference for tighter bins among equals
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty (strongly prefer tight fits)
    let mut score = pr * pr / cap;

    // Smooth cubic coupling of waste with stream progress: tightness matters more later
    score += 12.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward small post_residual that still allows the lookahead item to fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && pr - nxt <= 20.0 {
            score -= 8.0 * (1.0 - (pr - nxt) / 20.0);
