        // Penalize residual that is just barely too small for the lookahead item (dead space)
        if pr < nxt {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate (empty bin): penalize mildly, more so early when open bins exist
    if bin_residual == bin_capacity {
