        score += 6.0 + pressure * 2.0;
        // Late stream: opening fresh bins is fine (future closeout)
        score -= 10.0 * progress * progress;
    }

    // Align with mean residual: bins far from the mean residual get a gentle nudge
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes.
    // Class A: post_residual divisible into small chunks (post % 10 == 0) -> more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr <= 10 {
        score -= 8.0; // small dead space, easy to fill later
    } else if pr % 10 == 0 {
        score -= 4.0; // decadal residual: likely matchable with 10..80 items
    } else if pr < 10 {
        score += 6.0; // sliver below 10: nearly unusable (items >= 1 though)
    } else {
        // non-decadal: penalize by how far from a decadal boundary
        let frac = (pr % 10) as f64;
        score += frac * 0.3;
    }

    // Harmonic class via integer division thresholds on post_residual
    let class = pr / 20; // 0..=5 harmonic bands
    score += class as f64 * 2.0; // bigger bands = more wasted space

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            // next item cannot use this residual: penalize leftover proportionally
            score += (next_item_size as f64 - pr as f64).abs() * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // opening a new bin is costly; make it unattractive unless residual classes above push other bins up
        score += 20.0;
        // but if current item is small relative to capacity and many bins open, prefer fresh bin
        if item_size * 2 <= bin_capacity && open_bins_count > 3 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for pairing in fresh bin
        }
    }

    // Progress-based calibration: early in stream, be pickier (keep bins flexible)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far above mean, mildly penalize
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.1;

    // Congestion: many open bins -> prefer filling existing ones
    if open_bins_count > 5 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized. Items 1..100, so a residual below ~10 is nearly dead.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit is excellent: strong reward.
        score -= 40.0;
    }

    // Reward residuals that can host a plausible future item (couple with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item then leaves a small-but-usable gap.
        let nxt_post = post_residual as i64 - next_item_size as i64;
        if nxt_post > 0 && nxt_post < 20 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap just below the next item: mildly penalize.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin is cheap so prefer tight fills.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score = 70.0 + 10.0 * open_pressure;
        // Cheap to open early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If current item would leave a bad gap in every bin, opening is fine.
        if post_residual == bin_capacity as u32 - item_size.min(bin_capacity) && item_size >= 50 {
            score -= 5.0;
        }
    } else {
        // Slight penalty for using a bin when many bins are open and this fit is loose.
        let looseness = (post_residual as f64) / bin_capacity as f64;
        score += 10.0 * open_pressure * looseness;
    }

    // Tie-break toward bins with below-average residual (tighter bins first).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fit (low post residual)
    score -= 3.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64);

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leftover dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins with residual close to item need
    let diff = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.2 * diff;

    // Last-chance bin: strong preference to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual * 0.5 {
            score += 15.0;
        }
    }

    // Late in stream, prefer filling existing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer leaving small residual (tight fit), but not unusably small.
    let mut score = post;

    // Tightness reward: perfect-ish fits heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next > 0.0 {
        if next == post {
            score -= 60.0;
        } else if next <= post {
            // next fits: reward proportional to how much would remain after next
            let after_next = post - next;
            score -= 20.0 * (1.0 - after_next / cap);
        } else {
            // next doesn't fit here: slight penalty if we leave a medium hole
            if post >= next * 0.5 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: many open bins with high mean residual -> prefer filling existing bins
    let fill_pressure = mean_residual / cap;
    if open_bins_count > 2 && fill_pressure > 0.3 {
        score -= 10.0 * fill_pressure;
    }

    // New-bin candidate handling: opening a bin is penalized unless current bin
    // would leave a large hole and no other bin is tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: cost of opening, discounted late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_score = cap * 0.55 - 30.0 * progress;
        // If item fills a large fraction of a fresh bin, opening is attractive
        new_score -= 0.4 * (item / cap) * cap;
        // If many bins are open with waste, opening a fresh bin is fine
        new_score -= 5.0 * fill_pressure;
        // If this is a last-chance fit, opening a new bin is bad
        if fitting_bins_count == 1 {
            new_score += 50.0;
        }
        // Perfect fit in an existing bin beats a new bin
        if post_residual == 0 || post_residual <= 5 {
            new_score += 60.0;
        }
        return new_score;
    }

    // Time horizon: late in stream, be greedy — minimize residual aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post / cap);

    // Prefer bins whose residual was already small (avoid fragmenting big holes)
    let pre_frac = bin_residual as f64 / cap;
    score += 10.0 * pre_frac * (1.0 - item / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized post-residual
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;

    // Non-linear coupling: dead space penalized more heavily as the stream progresses
    // (late in the stream, leaving large residuals is worse since fewer items remain to fill them).
    let coupling = pr2 * (1.0 + 2.0 * progress) + pr3 * progress;
    score += 12.0 * coupling;

    // Tight fit reward: smooth polynomial bonus for small post-residual, stronger early
    let tightness = (1.0 - pr).powi(3);
    score -= (8.0 + 10.0 * (1.0 - progress)) * tightness;

    // Reward filling a bin that would otherwise waste space: compare residual to mean residual
    score -= 0.4 * (mean_residual - bin_residual as f64).max(0.0) / cap;

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if it barely misses, penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let slack = (post_residual as f64 - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * ((nx - post_residual as f64) / cap);
        }
    }

    // New-bin candidate handling: an empty bin has huge post-residual; make it less attractive
    // unless existing bins are badly fragmented. Bias grows with open bin count.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64 * (1.0 + progress);
    }

    // Mild penalty for many open bins, encouraging consolidation early
    score += 0.3 * open_bins_count as f64 * prog2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveals
    // "usable" leftover classes (e.g. multiples of 5/10 pair well with items 10..80).
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward residuals that fall into harmonically "friendly" classes:
    // multiples of 10 are ideal (items are typically multiples of 10),
    // multiples of 5 next, everything else penalized.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    } else if pr == 0 {
        // Perfect fill: strongest reward.
        score -= 60.0;
    }

    // Integer-division thresholds: how many "typical small items" (size 10)
    // could still fit? More usable slots -> better bin.
    let slots10 = pr / 10;
    score -= (slots10 as f64) * 3.0;

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx <= pr {
            // Next item fits perfectly: huge reward.
            if nx == pr {
                score -= 45.0;
            } else {
                score -= 8.0 + 20.0 * (nx as f64) / (cap as f64);
            }
        } else {
            // Next item won't fit here; mildly penalize tight residuals that
            // strand the lookahead, scaled by how close it is.
            let gap = nx - pr;
            score += (gap as f64).min(20.0) * 0.4;
        }
        // Harmonic match: next item shares residue class with post_residual
        if nx % 10 == pr % 10 && nx <= pr {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has a large raw score
    // (post_residual == capacity); push it up unless the stream is early
    // or many bins are open and fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 55.0 * (1.0 - progress);
        // Prefer new bin late in stream when open bins are fragmented.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Fragmentation guard: residuals in the awkward (1..10) band are dead space.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; favor bins near/below mean usage.
    let diff = (post_residual as f64) - mean_residual;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small,
    // likely unusable gaps) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // If the residual left behind can still accommodate typical future items,
    // treat it as usable and soften the penalty.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }
    // Conversely, if the leftover cannot fit the lookahead item, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the fit into
    // open bins is poor; otherwise keep it slightly penalized.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.3 * item_size as f64;
    }

    // Mild drift term: later in the stream, tighten tolerance for waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near-perfect match: next item fits snugly with small slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (-slack / 12.0).exp();
    }
    // Next item does NOT fit here: penalize proportionally to wasted potential.
    if next_item_size > 0 && next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        score += 0.35 * miss.min(40.0);
    }

    // Tight fits are good: reward small post_residual non-linearly.
    if post_residual > 0 {
        score += 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(3.0)) - 25.0;
    } else {
        score -= 40.0; // perfect fill
    }

    // Compare against mean residual: prefer bins that end up below the mean
    // (concentrating fill), penalize leaving above-average residuals.
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let crowding = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = 60.0 + 0.3 * (open_bins_count as f64) * crowding;
        if next_item_size == 0 {
            score += 10.0;
        }
        if fitting_bins_count == 1 {
            score += 45.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Slight stream-progression pressure: tighten up as stream nears completion.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large unusable dead space: residual after placement
    // that is too small for the smallest conceivable item is pure waste.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.6; // wasteful big leftover
    }

    // Exactness reward: quadratic in how tight the fit is.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Lookahead coupling: reward if next item fits into post_residual,
    // penalize if next item barely misses (would force a new bin anyway).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next < 10 {
                score -= 18.0; // two-item cascade fill
            } else {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // next item could have fit before this placement; mild penalty
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with large mean residual -> consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 && mean_residual > item_size as f64 + 10.0 {
        score -= 5.0 + mean_residual * 0.05 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is acceptable only when
    // the item is large or this bin's fit would leave a big awkward gap.
    if bin_residual == bin_capacity {
        let awkward = if post_residual > 40 { 0.0 } else { 60.0 };
        score += 40.0 + awkward - (item_size as f64) * 0.3;
        // late in the stream, prefer closing out bins rather than spawning
        score += progress * 10.0;
    }

    // Time horizon: early on, be slightly conservative (keep bins flexible);
    // late, be aggressive about filling anything.
    score -= progress * (10.0 - post_residual as f64 * 0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr * (1.0 + 0.35 * progress * norm_pr);
    let curvature = pr * (1.0 - progress) * (1.0 - norm_pr) * 0.25;
    let mut score = base - curvature;

    // Penalize dead space that shrinks as the stream progresses (tighter packing late).
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits smoothly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio * fit_ratio;

    // Lookahead: reward residual that can hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mildly discourage spreading across many open bins early on.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * (1.0 - progress);

    // New-bin candidate: keep it neutral-to-slightly-attractive only when the fit is bad.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals that fall into "dead zones" — too small for likely items
    // Class boundaries: 0, 10, 20, 30, 50, 75, 100 (harmonic-ish splits of capacity)
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual <= 5 {
        score -= 45.0; // near-perfect fit
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score += 5.0;
    } else if post_residual <= 50 {
        score += 15.0;
    } else {
        score += 25.0; // large residual wasted on a small item
    }

    // Non-linear coupling: reward small residuals quadratically
    score -= (1.0 - frac) * (1.0 - frac) * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when many bins are open and mean residual is high
        score += 35.0 + 0.15 * (open_bins_count as f64) + 0.10 * mean_residual;
        // If next item is small, a fresh bin is more attractive
        if next_item_size > 0 && (next_item_size as f64) < 0.25 * cap {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here anyway; residual becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Integer division threshold: residual in [item_min, item_min*2) is risky
    if post_residual >= 1 && post_residual < 10 {
        score += 20.0; // nearly unusable dead space
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * frac;

    // Prefer filling bins with larger residuals when mean residual is high (balance load)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1
    // unknown, assume small items ~<=10) are pure waste; punish hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Relative fit quality: fraction of bin used by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.5 * pressure;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 50 {
            score -= 20.0;
        }
        // If mean residual of open bins is small (they're all nearly full),
        // a new bin is more acceptable.
        score -= (mean_residual / 10.0).min(25.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // If next item cannot fit in post_residual, the gap is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Slight preference for fuller bins (small residual) overall.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = (post - next) as f64;
            // Reward tight 2-step fit: post_residual almost exactly next_item_size.
            score -= (next / 100.0) * 40.0 * (1.0 - gap / 100.0);
            if gap == 0.0 {
                score -= 25.0; // perfect 2-step chain
            }
        } else {
            // Next item cannot fit in this bin after placement: penalize large leftover
            // relative to next item (dead space from lookahead perspective).
            score += (next - post) * 0.15;
        }
    }

    // Penalize dead space that is too small to be useful for typical items (<= 10 min size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance bonus: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is below the mean (filling emptier-of-space bins keeps
    // larger residuals available for future big items).
    score += (post_residual as f64 - mean_residual) * 0.1;

    // Late in the stream, consolidate aggressively to avoid leaving many open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 10.0;

    // Slight preference for filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for any plausible item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if it
    // would leave dead space, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 6.0; // next item forces another bin anyway
        } else {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many bins are already open and
    // this bin is fresh (avoid bin proliferation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 8.0 * progress + 0.3 * open_bins_count as f64;
        // But opening a new bin is fine if no bin fits well (post_residual small
        // relative to item spread): handled by last-chance bonus above.
    }

    // Late in the stream, consolidate: favor bins that can still absorb future items.
    let horizon = 1.0 - step_index as f64 / (total_items.max(1) as f64);
    score += horizon * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    let tight = 1.0 - x; // fullness after placement
    score -= 30.0 * tight * tight * (0.5 + progress);
    score -= 20.0 * tight * tight * tight * progress;
    // penalize large residuals more strongly as stream progresses (dead space matters later)
    score += 15.0 * x * x * (0.3 + 0.7 * progress);
    // smooth interaction: reward near-perfect fits via cubic in tightness
    score -= 25.0 * (1.0 - (x - 0.0) * (x - 0.0)) * x * x; // valley near small residual
    // lookahead coupling: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 12.0 * (1.0 - (nx / pr.max(1.0) as f64)) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (nx - pr as f64) / cap;
        }
    }
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * progress;
    // pull toward mean residual to keep bins balanced
    score += 0.3 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common item sizes (or near them) are valuable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible into small chunks (highly reusable)
    let div_small = if post_residual >= 10 { post_residual % 10 == 0 } else { false };
    let div_5 = post_residual % 5 == 0;
    if div_small {
        score -= 8.0;
    } else if div_5 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Class B: integer-division thresholds on post_residual
    let q = post_residual / 10; // how many size-10 chunks fit in leftover
    match q {
        0 => score += 12.0,           // dead space < 10: nearly unusable
        1 => score += 4.0,
        2 => score -= 2.0,
        3 => score -= 5.0,
        _ => score -= 7.0,            // lots of room left: keep flexible
    }

    // Coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact / near-exact harmonic match rewarded
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0;
            } else if gap <= 5 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize proportional to overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += 3.0 + over as f64;
        }
    } else {
        // last item: minimize waste aggressively
        score += post * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin would be wrecked
    if bin_residual == bin_capacity {
        let waste_if_placed = post;
        if waste_if_placed < 10.0 && next_item_size > post_residual && next_item_size > 0 {
            score -= 25.0; // opening fresh bin beats creating dead space
        } else {
            score += 30.0; // prefer existing bins otherwise
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good
    // "filler" target when bins are many (harmonic balancing of residuals).
    let dev = mean_residual - post;
    if open_bins_count > 3 {
        score += 0.05 * dev;
    }

    // Stream progression: late in the stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (10.0 - (post / 10.0)).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but small gaps < ~12 are statistically unusable) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 12 {
            score += 60.0 * (12.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 18.0 * (25.0 - post_residual as f64) / 13.0;
        }
    } else {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 45.0;
    }

    // Reward tight fits generally: small post_residual relative to item size.
    score -= 25.0 * (item_size as f64) / (item_size as f64 + post_residual as f64 + 1.0);

    // Last-chance bin (only one fitting bin): strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones (lower score for real bins),
    // few open bins -> allow opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - 0.5 * progress);
    if bin_residual < bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: penalize when open bins are underutilized, reward when mean residual is low.
        score += 10.0 * pressure;
        score += 0.15 * mean_residual;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 12 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space guaranteed relative to the known next item
            score += 10.0 + 0.5 * (post_residual as f64);
        }
    }

    // Prefer bins whose residual is already small (denser bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * diff;                       // penalize mismatch
        if post_residual == next_item_size {
            score -= 25.0;                         // perfect 2-step match bonus
        }
        // Slight reward if next item still fits after current placement
        if next_item_size <= post_residual {
            score -= 6.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 5.0;
    }

    // Relative residual vs mean: prefer bins with less residual than average (tighter packing)
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Penalize large dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;                              // tiny dead space is wasted capacity
    }

    // Last-chance fitting: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if poor_fit {
            score -= 10.0 + 5.0 * progress;        // opening fresh bin can be better
        } else {
            score += 20.0;                         // discourage new bins when decent fits exist
        }
        // Prefer reusing when few open bins
        if open_bins_count <= 2 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (except tiny dead space that is unusable).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, demand a very good fit.
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Lookahead: if the next item would fit exactly in the post-residual, reward heavily;
    // if the next item cannot fit in post-residual anyway, mild penalty for wasting space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() <= 2.0 {
            score -= 20.0;
        } else if nxt > post_residual as f64 && post_residual > 0 {
            score += 5.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        } else {
            // next item fits: prefer leaving room close to next size (soft pairing)
            score += 0.05 * (post_residual as f64 - nxt).abs();
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let pressure = mean_residual / cap;
    if open_bins_count > 3 && pressure > 0.3 {
        score -= 6.0 * pressure;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Encourage opening a new bin only when item is large and current fit is poor.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Large items: opening fresh bin is fine (score lowered).
        // Small items into new bin: penalize (wasteful).
        score += 20.0 * (1.0 - frac) - 5.0 * frac;
        // Early in stream, allow exploration of new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Time horizon: late in the stream, avoid opening new bins and squeeze existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 15.0 * (progress - 0.8) * (bin_residual == bin_capacity) as i32 as f64;
        score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);
    }

    // Mild preference for bins whose residual is close to the mean (balanced packing).
    score += 0.08 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress.clamp(0.0, 1.0);
    let poly = 1.0 + 2.0 * t - 3.0 * t * t + 2.0 * t * t * t; // smooth non-monotone weight in ~[1,2]

    // Penalize large leftover space early (waste), reward tight fits later.
    score += prn * prn * 30.0 * poly;

    // Reward bins whose residual closely matches the next item (lookahead synergy).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gn = gap / cap;
        score -= (1.0 - gn) * (1.0 - gn) * 12.0 * (1.0 + t);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    let mean_norm = mean_residual / cap;
    score += open_bins_count as f64 * mean_norm * 1.5;

    // Small penalty for exact-perfect fill only early (keep flexibility), none later.
    score -= (1.0 - t) * (prn * (1.0 - prn)) * 4.0 * 4.0; // peaks at prn=0.5

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity quarters
    let cap = bin_capacity as f64;
    let quarter = cap / 4.0;
    let pr = post_residual as f64;

    // Dead-space penalty: small unusable residuals are costly
    if pr > 0.0 && pr < 10.0 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Reward exact/near-exact fills (perfect packing class)
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 30.0;
    }

    // Harmonic residue classes: residuals that are multiples of common item
    // size classes (mod 10, mod 25) are more likely reusable.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 12.0;
    } else if m10 <= 2 {
        score -= 5.0;
    }
    let m25 = post_residual % 25;
    if m25 == 0 {
        score -= 10.0;
    }

    // Fractional capacity classes: post residual in (0, 1/4), (1/4, 1/2), etc.
    if pr > 0.0 && pr < quarter {
        score += 15.0; // tiny sliver, low utility
    } else if pr < quarter * 2.0 {
        score -= 6.0;  // moderate utility
    } else if pr < quarter * 3.0 {
        score -= 10.0; // good utility
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item fits: reward proportionally to tightness of that fit
            let tight = 1.0 - ((pr - nxt) / cap).abs();
            score -= 8.0 + 12.0 * tight;
            // harmonic check: post_residual mod next_item_size small => chainable
            if post_residual % next_item_size <= 3 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize more when residual is a sliver
            score += 10.0 + 20.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation)
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * fill_ratio * (open_bins_count.min(50) as f64 / 50.0);

    // Late in stream: consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fill_ratio;

    // Pull toward mean residual to keep balance (mild)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: neutral-ish baseline, penalize opening early, allow late
    if bin_residual == bin_capacity {
        score += 55.0 - 30.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.9 {
            score -= 20.0; // big next item may need fresh space anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // since items are >= 1 but small gaps waste capacity; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Gaps that can still fit the lookahead item get a mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Gaps that cannot fit the next item become risky dead space.
    else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Waste relative to capacity: prefer filling bins tightly overall.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage scattering across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if open bins are on average quite full,
    // slightly favor placing into this bin rather than opening new ones.
    score -= mean_residual * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when no open bin fits,
    // otherwise penalized so we exhaust existing bins first.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            score += 20.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight 2-step fit: subtract bonus proportional to closeness.
        let lookahead_bonus = 60.0 / (1.0 + diff);
        score -= lookahead_bonus;
        // Slight penalty if post_residual is bigger than next item but small enough
        // that it risks becoming dead space.
        if post_residual > next_item_size && post_residual < 20 {
            score += (20 - post_residual) as f64 * 1.5;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Reward using bins that are below mean residual (filling emptier bins),
    // penalize dipping far below mean residual creating fragmentation.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.25 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // no open bin offers a decent fit; the lookahead bonus on open bins with
    // tight 2-step matches will usually beat it.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if no other bin fits, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in stream, slightly prefer consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post_residual as f64;

    // Reward tight fits (wasted space is dead space).
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.15;

    // Lookahead: penalize leaving a residual that barely fails to fit the next item,
    // reward leaving exactly enough room for it.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap < 10.0 {
            score -= 12.0; // perfect chain fit
        } else if gap < 0.0 && gap > -8.0 {
            score += 10.0; // near-miss: creates unusable sliver
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + post_residual as f64 * 0.2;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when existing residuals are large/fragmented
    // or late in the stream where a fresh bin amortizes well.
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = if mean_residual > 0.0 { (item_size as f64 / mean_residual).min(2.0) } else { 1.0 };
        score += 30.0;              // base cost of opening a bin
        score -= progress * 15.0;   // late stream: fresh bin has long horizon
        score -= fragmentation * 0.3;
        score -= pressure * 8.0;    // item large relative to mean residual -> poor fits likely
    } else {
        // Prefer bins whose residual is close to the item (best fit flavor).
        score += (bin_residual as f64 - item_size as f64).abs() * 0.4;
        // Slight bonus for bins below mean residual (use the fullest bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: waste after placement, normalized
    let mut score = pr / cap;

    // Non-linear waste penalty: quadratic growth in dead space (small residuals are fine)
    let x = pr / cap;
    score += 0.8 * x * x;

    // Tightness reward: reward near-full fills with smooth coupling
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 1.5 * fill_ratio * fill_ratio * (1.0 - progress);

    // Stream-progress coupling: as stream progresses, penalize residual more strongly
    // (late items should pack tighter), using smooth polynomial interaction
    score += (0.5 + 1.2 * progress) * x * (1.0 + 0.5 * x);

    // Lookahead: if the next item fits into post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 0.9 * (1.0 - slack) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to leftover dead space
        score += 0.4 * x * (1.0 - progress);
    }

    // Last-chance bin: strongly favor if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - x);
    }

    // New empty bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 0.6 + 0.8 * progress;
        // But if no open bin fits, this is the only option anyway
        if fitting_bins_count == 0 {
            score -= 3.0;
        }
    }

    // Mean-residual context: prefer bins whose residual deviates favorably from mean
    let dev = pr - mean_residual;
    score += 0.15 * dev / cap;

    // Mild preference to consolidate into fewer bins when many are open
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // are more reusable. Classify via modulo arithmetic.
    let pr = post_residual;
    let mut reusability = 0.0f64;
    if pr > 0 {
        if pr % 10 == 0 { reusability += 6.0; }
        if pr % 20 == 0 { reusability += 3.0; }
        if pr % 25 == 0 { reusability += 3.0; }
        if pr % 50 == 0 { reusability += 3.0; }
        // small unusable residuals are dead space
        if pr < 10 { reusability -= 12.0; }
        else if pr < 20 { reusability -= 5.0; }
    } else {
        // perfect fill is ideal
        reusability += 15.0;
    }
    score -= reusability;

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + 0.05 * (pr - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize more if we wasted a lot
            score += 0.03 * (next_item_size - pr) as f64;
        }
    } else {
        // last item: prefer zero residual
        score += 0.1 * pr as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists elsewhere. Make empty-bin mildly expensive by default,
    // cheaper when many open bins are cluttered with large mean residual.
    if bin_residual == bin_capacity {
        let clutter = (open_bins_count as f64) * (mean_residual / cap);
        score += 25.0 - clutter.min(20.0);
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Fraction-of-capacity thresholds: placing large items into large-residual
    // bins is natural; penalize putting small items into huge empty-ish bins.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    if fill_frac < 0.25 && bin_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // Integer-division threshold: residuals in [30,50] are valuable "half bins"
    if (pr / 25) == 1 && pr >= 30 {
        score -= 4.0;
    }

    // Mild preference to keep number of open bins stable early on
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but practically < next_item_size) are wasted unless the bin is nearly full.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // Dead space: gap smaller than the next item (or tiny absolute gap)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 2.5 * gap; // unusable for lookahead -> heavy penalty
        }
        if post_residual < 10 {
            score += 6.0; // small sliver is almost surely dead space
        }
    } else {
        score -= 12.0; // perfect fit: strongly reward
    }

    // Reward tight packing relative to what the item consumed
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: prefer using existing bins when many are open,
    // but allow opening a new bin when few bins are open and fit is poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score -= pressure;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: make it attractive only when existing bins would leave bad gaps
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: moderate; dead-space penalties above
        // can push poor fits above this.
        score = 25.0 + 5.0 * (1.0 - fill_ratio);
        if open_bins_count == 0 {
            score -= 30.0; // must open when nothing open
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: when average residual is small, conserve remaining space
    score += 0.05 * (mean_residual - gap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let new_post = post_residual - next_item_size;
            // Reward chains where the following residual stays small.
            score -= (30.0 - new_post.min(30) as f64) * 0.8;
            // Penalize if next item would leave a tiny dead space again.
            if new_post > 0 && new_post <= 5 {
                score += 10.0;
            }
        } else {
            // Next item won't fit here: mild penalty for tight bins that block lookahead.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If many open bins exist and mean residual is large, prefer reusing bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 25.0;
        }
        // Late in the stream, discourage new bins more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 20.0;
        }
    }

    // Penalize leaving large unusable residuals (> 10) that likely can't fit future items.
    if post_residual > 10 {
        score += (post_residual as f64 - 10.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic discount for small post-residual (good fits).
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.01;

    // Penalize dead space: residuals that are too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual cannot fit the next item
    // only mildly, but strongly penalize wasting a bin that could host the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps room for the next item: chain potential
        } else {
            score += 4.0;
        }
        // Exact two-item fill is ideal
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when global
    // residuals are fragmented (mean residual low relative to item needs) or
    // few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins are roomy on average
        score += 15.0 + fragmentation * 30.0 - progress * 10.0;
        // But if the item is large and mean residual is small, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // Early stream: allow more bins to build flexibility
        if open_bins_count < 3 {
            score -= 12.0;
        }
    }

    // Prefer filling fuller bins: reward using a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Mild penalty for spreading across many open bins when this bin is nearly full already.
    if post_residual == 0 {
        score -= 20.0; // perfect closure of a bin
    }

    // Time-horizon modulation: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.02;

    // Slight preference for bins below mean residual (balance avoidance of many half-empty bins)
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr as f64;

    // Smooth non-linear coupling: residual value decays with stream progress
    // (late in the stream, tight fits matter more; waste is penalized harder).
    let decay = (1.0 - progress).powf(1.5);
    score -= norm_pr * norm_pr * 40.0 * decay;

    // Reward bins whose post-residual closely matches the next item (chaining).
    let chain_fit = if nxt > 0.0 { (pr - nxt).abs() } else { pr * 0.5 };
    score += (chain_fit / cap) * 25.0 * (0.5 + 0.5 * progress);

    // Penalize exact-zero-ish residuals only early (dead space is fine if tiny? no:
    // perfect closure is great) — reward near-perfect closure smoothly.
    let closure = 1.0 - (pr / cap);
    score -= closure.powf(4.0) * 30.0 * (1.0 - progress * 0.3);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 4.0;

    // Deviation from mean residual: prefer bins near/below the mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 10.0 - dev * 5.0;

    // Smooth quadratic coupling of item size with progress: big items early
    // prefer roomy bins, big items late prefer tight bins.
    let size_norm = item / cap;
    score += size_norm * norm_pr * 20.0 * (1.0 - progress);
    score -= size_norm * norm_pr * 15.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10.
    // Residuals that are "perfect complements" of common item sizes (multiples of 10)
    // are more reusable; penalize awkward residues (e.g. 1..9) that create dead space.
    let r = post_residual % 10;
    if post_residual > 0 {
        score += match r {
            0 => -8.0,                       // perfectly reusable residual
            1 | 9 => 4.0,                    // nearly dead space
            2 | 8 => 2.5,
            3 | 7 => 1.5,
            4 | 6 => 0.5,
            _ => 0.0,                        // 5: half-capacity complement
        };
    } else {
        score -= 25.0; // perfect packing: bin closed exactly
    }

    // Integer-division thresholds on post_residual: large residuals are valuable.
    let quarter = bin_capacity / 4;
    if post_residual >= quarter {
        score -= 6.0;
    }
    if post_residual >= bin_capacity / 2 {
        score -= 6.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // strongly reward this bin (harmonic pair completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how tightly it packs
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
            // penalize if next leaves an awkward residue again
            if (post_residual - next_item_size) % 10 != 0 && post_residual - next_item_size > 0 {
                score += 3.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize moderately so we prefer reusing bins
    // with good fits, but keep it viable when all fits are bad (post_residual small).
    if bin_residual == bin_capacity {
        score += 12.0;
        // opening a new bin is more attractive early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Spread-awareness: when mean residual across open bins is high, avoid
    // creating yet another large-residual bin.
    if mean_residual > bin_capacity as f64 / 3.0 && post_residual > bin_capacity as f64 / 2.0 {
        score += 5.0;
    }

    // Mild pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 25.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward filling a bin nearly completely.
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Coupling with open bins count: penalize spreading across many bins,
    // but relax pressure near the start of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., best post_residual among open bins would be large dead space).
    if bin_residual == bin_capacity {
        let new_bin_score = bin_capacity as f64 - item_size as f64;
        let dead = new_bin_score - post_residual as f64; // 0 for the new bin itself
        let _ = dead;
        // Base cost of opening a new bin, modulated by how badly existing
        // bins would fragment (mean_residual far from item_size).
        let mismatch = (mean_residual - item_size as f64).abs();
        let open_pressure = if open_bins_count > 0 { 18.0 - mismatch.min(18.0) } else { -50.0 };
        score += 12.0 + open_pressure;
        // If a lookahead item could pair with the leftover, opening is better.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: prefer bins whose post_residual can host next item.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 20 {
            score -= 20.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Perfect 2-step match: post_residual exactly fits the next item
    if next > 0.0 && (post - next).abs() < 0.5 {
        score -= 40.0;
    }

    // Post residual can still hold the next item: mild reward scaled by tightness
    if next > 0.0 && post >= next {
        score -= 8.0 * (1.0 - (post - next) / cap);
    }

    // Dead space: post residual smaller than next item (and nonzero) -> penalize
    if next > 0.0 && post > 0.0 && post < next {
        score += 12.0 * (1.0 - post / next);
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual means tighter packing (good)
    score -= 3.0 * (mean_residual - post) / cap;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into tighter bins
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post / cap);
    }

    // Late in the stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post / cap);

    // Slight penalty for the brand-new empty bin unless nothing else is good
    if bin_residual == bin_capacity {
        score += 6.0;
        // But if next item is large and no open bin fits well, allow new bin
        if next > 0.0 && next > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit. Reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Penalize large post_residual dead space strongly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.15) * 0.08;
    } else {
        // Perfect fit: strong reward.
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if next_item_size <= bin_residual {
            // next item could have gone here instead; mild penalty if we leave bad shape
            if post_residual > 0 && post_residual < next_item_size {
                score += 3.0;
            }
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly in existing bins or there are no/few fitting bins.
    if bin_residual == bin_capacity {
        let waste_existing = mean_residual - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        } else {
            // penalize opening new bin; relax penalty when mean residual is small
            // (existing bins nearly full) or late in stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let mut penalty = 18.0 - 6.0 * progress;
            if waste_existing < 5.0 {
                penalty -= 6.0;
            }
            if post_residual > 60 {
                penalty += 10.0; // huge empty bin waste for small item
            }
            score += penalty;
        }
    } else {
        // Existing bin: slight preference for bins with below-mean residual (consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Prefer filling bins with larger current load (fewer bins stay lingering).
        score -= 0.03 * (bin_capacity - bin_residual) as f64;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.4 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), amplified non-linearly
    let mut score = pr * (1.0 + 0.6 * fit_ratio * fit_ratio);

    // Non-linear penalty for medium dead space that is unlikely to be reused
    let dead = pr / cap;
    score += 8.0 * dead * dead * (1.0 - dead);

    // Perfect-fit reward (smooth, via polynomial of post_residual)
    let perfect = (cap - pr) / cap; // fraction filled
    score -= 6.0 * perfect * perfect * perfect;

    // Stream progress coupling: late in stream, be greedier about tight fits
    score -= (1.0 - progress) * pr * 0.15;
    score += progress * pr * 0.10;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Mild preference to keep mean residual balanced
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in the "hard zone" (1..=9)
    // is nearly unusable for items >= 10, so penalize it heavily.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 45.0 - (pr as f64) * 3.0; // smaller dead space = worse
    }

    // Reward perfect / near-perfect fits via capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.02 {
        score -= 30.0; // essentially perfect fit
    } else if frac < 0.10 {
        score -= 12.0;
    }

    // Modulo-class coupling: if next item fits exactly in post_residual,
    // strongly prefer this bin (two-item chain closure).
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits: reward proportionally to how snugly it lands
        let post2 = pr - next_item_size;
        score -= (pr - post2) as f64 * 0.5;
        if post2 < 10 {
            score += 20.0; // creates new dead zone for the item after next
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this residual: soft penalty scaled by waste
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline score = capacity.
    // Only allow opening a new bin when current open bins are congested
    // (few fitting bins relative to open bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score -= 20.0 + 15.0 * congestion.min(3.0) + 10.0 * (1.0 - progress);
    } else {
        // Prefer bins with residual below the mean (consolidate waste)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Mild preference for fuller bins as stream progresses
        score -= (1.0 - bin_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Harmonic integer-division tier on post_residual: multiples of common
    // item classes (10,20,25,50) are reusable; odd fragments are not.
    if pr >= 10 {
        let reusable = pr % 10 == 0 || pr % 25 == 0 || pr % 20 == 0;
        if reusable {
            score -= 8.0;
        } else if pr < 25 {
            score += 6.0; // awkward small fragment
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future
    // item (min item size = 1, but tiny slivers < 5 are effectively dead)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }
    // Perfect fit: strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward fits that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is just barely too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Open-bin pressure: discourage spreading across many bins; favor
    // closing out existing bins before opening new ones.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: a fresh bin is attractive only when the
    // item is large relative to mean residual (poor fit elsewhere) or when
    // many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) < 0.35 * mean_residual.max(1.0);
        if poor_fit || open_bins_count > 6 {
            score -= 6.0;
        } else {
            score += 10.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * tightness;
    }

    // Late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
