pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the minimum item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Sweet spot: leaving room for a mid-size item is good.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here anyway; residual waste is less meaningful.
            score += 2.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes the residual capacity
    // of other open bins; only attractive when existing fits are very tight/fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if fitting_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Penalize new bins when open bins still have plenty of room.
        score += 35.0 + 60.0 * fragmentation;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Many open bins -> discourage opening yet another.
        score += 2.5 * open_bins_count as f64;
    } else {
        // Slight preference to fill bins that are already mostly full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 6.0 * fullness;
    }

    // Global balance: prefer bins whose residual is near the mean (keeps options open).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early stream: be more tolerant of opening bins to build a good spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity && progress < 0.2 {
        score -= 4.0 * (0.2 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = 1.0 + 2.0 * t - 3.0 * t * t + 2.0 * t * t * t;
    score += 12.0 * prn * prn * poly;

    // Penalize residual that cannot fit a plausible next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 6.0 + 10.0 * t * (ns - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - t) * ((pr - ns) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * t;
    }

    // Prefer bins tighter than the mean residual (good fits)
    score -= 3.0 * (mean_residual - pr) / cap;

    // Mild penalty for proliferating bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - t) * 0.5;

    // New-bin candidate: keep neutral-ish, penalize slightly when decent fits exist
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * t + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // are more reusable. Quantize post_residual into k = post_residual / 10.
    let k = post_residual / 10;
    // Reward "harmonic" residual classes (multiples of 10) that pair well
    // with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Penalize dead space in low classes (unusable slivers).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Integer-division threshold: bins whose residual is in the "half" band
    // (40..=60) are versatile; slight reward.
    if (40..=60).contains(&post_residual) {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact or near-exact harmonic pairing.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0; // perfect fill
            } else if gap % 10 == 0 {
                score -= 8.0; // harmonic gap
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; penalize modestly, more if this bin
            // would be left with a dead-space residue.
            score += (next_item_size - post_residual) as f64 * 0.15;
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when existing
    // bins are very full (low mean residual) or this item is huge.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset by stream position and load.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55
            - progress * 8.0
            - (mean_residual / cap) * 20.0
            - if item_size >= 50 { 15.0 } else { 0.0 };
        // If several bins already fit, discourage new bin.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
    }

    // Mild preference for fullest bins (small residual) via mean coupling.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Harmonic modulo penalty on residual class mismatch with item size.
    let cls_item = item_size % 10;
    let cls_res = post_residual % 10;
    if cls_item != 0 && cls_res != 0 && cls_item + cls_res == 10 {
        score -= 2.0; // residues complement to a decade
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
