    // Prefer bins with residuals close to the item (minimize waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * waste;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 35.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits exactly into a fraction of post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to wasted potential
        let waste = (next_item_size - post_residual) as f64;
        score += 15.0 * (waste / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual across open bins
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;
    score -= 10.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count >= 1 {
            score += 80.0;
        }
        // New bin more acceptable early in stream or when many bins already open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 50.0 * (1.0 - progress);
    }

    // Discard leftover dead space below the smallest plausible item
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residuals below the mean (compact them first).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Mild preference for using existing bins vs opening new ones, decaying over time.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well.
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            let best_gap = (bin_residual as f64 - item_size as f64).max(0.0);
            (post_residual as f64 - best_gap).max(0.0) / bin_capacity as f64
        };
        score += 40.0 * (1.0 - 0.5 * progress) - 20.0 * desperation;
    }

    // Late in the stream, consolidate aggressively into fewest bins.
    score += progress * 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling: post residual penalized more heavily as stream progresses
    let mut score = pr * (1.0 + 0.8 * progress);

    // Smooth quartic dead-space penalty, intensifying with progress
    score += 30.0 * x.powi(4) * (0.5 + progress);

    // Reward tight fits: subtract bonus when post_residual is small, scaled by progress
    let tightness = 1.0 - x;
    score -= 25.0 * tightness.powi(3) * (0.6 + 0.4 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item could use the post residual, reward leaving that much space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: baseline score, penalized less early, more late
    if bin_residual == bin_capacity {
        score += 35.0 - 25.0 * progress + 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 harmonic class
    let next_class = (next_item_size / eighth).min(8);

    // Penalize dead space that no plausible item can fill: post_residual < smallest class.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward when next item's class matches the leftover class (perfect harmonic pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        score -= (40.0 - diff as f64).max(0.0) * 1.5;
        // Exact modulo pairing bonus
        if post_residual % eighth == 0 && next_item_size % eighth == 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover: penalize proportional to wasted class.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Integer-division thresholds on post_residual classes.
    match post_class {
        0 => score -= 10.0,               // near-perfect fill
        1 => score -= 5.0,                // small leftover, good
        2 | 3 => { score -= 2.0; }        // quarter-ish leftovers
        4 | 5 => { score += 3.0; }        // half-empty: mediocre
        _ => { score += 6.0; }            // mostly empty: poor use
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer only when open bins would create large dead space.
    if bin_residual == bin_capacity {
        // Base neutral cost of opening a new bin.
        score = bin_capacity as f64 * 0.75;
        // Open a fresh bin if existing bins are fragmented (high mean residual).
        if mean_residual > (bin_capacity / 2) as f64 {
            score -= 15.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    // Tie-break: prefer bins whose residual is close to mean (balanced packing).
    score -= (mean_residual - bin_residual as f64).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual that is too small to hold a future item (min item size = 1,
    // but practically gaps below a usable threshold are dead weight) is heavily penalized.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfect fill: reward strongly (gap is truly unusable but bin is exhausted).
        score -= 60.0 + 0.5 * item_size as f64;
    } else if post_residual < 25 {
        // Small awkward gap: penalize super-linearly.
        let g = post_residual as f64;
        score += (25.0 - g) * 2.5;
    }

    // Reward tight fits: small fraction of residual consumed relative to bin.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 30.0;

    // Reward bins whose residual was close to item size (near-perfect packing).
    let slack = (bin_residual - item_size) as f64;
    score += (slack / bin_capacity as f64) * 20.0;

    // --- Open-bin pressure ---
    // Too many open bins: encourage filling existing ones, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + 8.0 * (1.0 - progress));
    score += pressure * 3.0;

    // Mean residual alignment: prefer bins with residual near item size.
    let align = (mean_residual - item_size as f64).abs();
    score += align * 0.3;

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        // If this bin's post_residual can host the next item, reward it.
        if post_residual >= next_item_size {
            score -= 25.0;
            // Bonus for exact-ish match with next item.
            let next_slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - next_slack / bin_capacity as f64) * 10.0;
        } else {
            // Post residual can't fit next item: mild penalty scaled by how close it was.
            score += 8.0;
        }
    }

    // --- Last-chance bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly prefer it over opening a new bin.
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Base cost plus pressure so we don't proliferate bins.
        let mut new_bin_cost = 55.0 + pressure * 4.0;
        // If no open bin fits (this call is the only candidate), opening is necessary.
        if fitting_bins_count == 0 {
            new_bin_cost = 5.0;
        } else if fitting_bins_count == 1 {
            // The single fitting bin already gets -40; make new bin worse unless
            // the existing fit is terrible (huge dead space would result).
            new_bin_cost += 10.0;
        }
        // Late in the stream, consolidating matters less than clean fits.
        new_bin_cost -= progress * 5.0;
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: more aggressive packing late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 + 30.0 * progress;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the next item, scaled by how snugly it fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= (next_item_size as f64) * (1.0 - slack / bin_capacity as f64) * 0.6;
    } else if next_item_size > 0 {
        // Penalize dead space too small for the next item (unusable residue).
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5 * (0.5 + progress);
    }

    // Reward being below mean residual (tighter than average bin).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could still absorb the item,
    // unless the item is large relative to capacity (better in a fresh bin).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += if fill > 0.5 { 5.0 } else { 25.0 + 10.0 * (1.0 - progress) };
        } else {
            score -= 10.0;
        }
    }

    // Mild penalty for large absolute post-residual waste when many bins are open.
    if open_bins_count > 3 {
        score += (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize residual that is unusable for the next item (dead space),
    // reward residual that can host the lookahead item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            score -= 15.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            score += 10.0 + (next - post_residual as f64) * 0.3;
        }
        // Perfect pair: post residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= fit_ratio * 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fitting bins exist and item is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bins are more acceptable late in the stream or when few bins fit.
        let mut nb_score = item_size as f64 * 0.4;
        nb_score -= (fitting_bins_count as f64) * 5.0;
        nb_score -= progress * 10.0;
        // If mean residual is large, prefer reusing open bins.
        nb_score += mean_residual * 0.15;
        if open_bins_count == 0 {
            nb_score -= 100.0;
        }
        score += nb_score;
    }

    // Mild preference to fill bins with above-average remaining space.
    if !is_new_bin {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Penalize leaving residual in the awkward zone (too small to be useful,
    // too large to ignore), since item sizes span 1..100.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    score -= 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);
    score += 20.0 * norm_pr * norm_pr * progress;
    // penalize large dead space more as stream advances
    score += 15.0 * (norm_pr * norm_pr * norm_pr) * (0.5 + progress);
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }
    // lookahead: reward bins whose post-residual fits next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 + 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }
    // prefer bins below mean residual slightly (tighter packing)
    score += 3.0 * (mean_residual - bin_residual as f64) / cap;
    // mild penalty for opening new bins late in stream when alternatives exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 * (1.0 - progress) + 5.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division thresholds.
    // Waste classes: 0 (perfect), 1..=5 (tiny), 6..=15 (small), 16..=30 (medium), >30 (dead space).
    let waste_class: u32 = match post_residual {
        0 => 0,
        1..=5 => 1,
        6..=15 => 2,
        16..=30 => 3,
        _ => 4,
    };
    let waste_penalty = [0.0, 2.0, 6.0, 14.0, 30.0][waste_class as usize];
    score += waste_penalty;

    // Reward near-perfect fits strongly.
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item-size blocks (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0)
            || (post_residual % 20 == 0)
            || (post_residual % 25 == 0)
            || (post_residual % 50 == 0);
        if reusable {
            score -= 8.0;
        } else {
            score += 3.0;
        }
        // Odd awkward residuals are harder to fill later.
        if post_residual % 2 == 1 {
            score += 1.5;
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 10.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize small leftovers.
            if post_residual < next_item_size && post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the fit into existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Neutral-ish base; opening a new bin is good for large items leaving
        // a structured residual.
        score = (bin_capacity - item_size) as f64;
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        // If existing bins are crowded (low mean residual), a fresh bin is fine.
        if mean_residual < 20.0 {
            score -= 5.0;
        }
    }

    // Stream progression: early on, prefer tight packing into few bins;
    // later, be slightly more willing to spread out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    // Coupling with mean residual: prefer bins below the mean (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Mild pressure against proliferating many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.35 + 0.65 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    if bin_residual != bin_capacity {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild penalty for opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // penalize residuals too small for any future item (dead space)
        if post_residual < 1 {
            score += 50.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Reward bins tighter than average (good fits), penalize loose bins
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current bin would leave
    // very unusable dead space while a fresh bin fits item + next item
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= item_size + next_item_size.min(post_residual) {
            // fresh bin can host item then next item exactly-ish
            let d = (post_residual as i64 - (item_size + next_item_size) as i64).abs() as f64;
            score -= 70.0 / (1.0 + d);
        }
        // late in stream, avoid opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // mild penalty for wasting large residuals on small items
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins unless
    // current residuals are fragmented or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - mean_residual.floor();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() + 1.0 };
        // Prefer new bin when item is large relative to open residuals
        let large_item_bonus = if item_size as f64 > mean_residual { 20.0 } else { -20.0 };
        score += 40.0 * pressure - large_item_bonus + 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.25;

    // Slight preference for more-filled bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_capacity as f64 - bin_residual as f64) * (-0.1 * progress);

    // Discourage opening many bins early: scale new-bin cost with open count.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * progress * cap * 0.4;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= (pr - nxt).min(cap) * 0.15 * progress;
        }
    }

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Mild penalty when many bins are open and this placement wastes residual
    score += norm_pr * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Deviation from mean residual: prefer bins near/below mean to balance load
    score += (pr - mean_residual).abs() * 0.1;

    // New-bin candidate: neutral-ish baseline, opened only when fits are poor
    if bin_residual == bin_capacity {
        score += cap * 0.35 + norm_item * cap * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty: small post-residuals that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit reward via modulo classes
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % quarter == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Harmonic class of item size relative to capacity fractions
    let class = |x: u32| -> u32 {
        if x >= half { 3 } else if x >= quarter { 2 } else { 1 }
    };
    let iclass = class(item_size);
    let nclass = if next_item_size == 0 { 0 } else { class(next_item_size) };

    // If next item's class matches the residual class of this bin, favor placing here
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap % quarter == 0 {
            score -= 10.0;
        } else if gap < 10 {
            score += 15.0;
        }
        // big item now, big item next: prefer tight packing
        if iclass == 3 && nclass == 3 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; slight bonus for filling this bin fully now
        score += (post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 2.0;
        if item_size >= half {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Progress-scaled tie-breaker: tighter packing matters as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.05 * progress;

    // Prefer bins with below-mean residual (consolidate emptier space)
    score += (mean_residual - bin_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals in the "unusable gap" zone (1..=12) are toxic: almost no
    // future item (min size 1, but typical items are larger) can fill them,
    // so they are effectively lost capacity. Penalize them super-linearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as f64) * (13 - post_residual as f64) * 8.0;
    }
    // Mid-range gaps (13..=30) are partially usable; mild penalty.
    if post_residual > 12 && post_residual <= 30 {
        score += (post_residual as f64 - 12.0) * 1.5;
    }
    // Large leftover space is fine: it stays flexible. Slight reward for
    // leaving exactly 0 (perfect fit).
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Tight-fit reward relative to item size ---
    // Reward bins where the item occupies a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // --- Last-chance pressure ---
    // If this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }
    // Many fitting bins means low urgency; soften selection slightly.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // --- Open-bin pressure ---
    // Keep the number of open bins in check: each additional open bin adds
    // a small penalty, encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // --- Mean-residual coupling ---
    // If the fleet-wide mean residual is small, remaining bins are all tight;
    // prefer this bin even more (avoid scattering across tight bins).
    score -= (mean_residual / bin_capacity as f64).max(0.0) * 6.0;

    // --- Lookahead (k=2) ---
    // If the next item can exactly fill this bin's post-residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 12 {
            // Next item would leave a dead gap: discourage.
            score += 10.0;
        } else if next_item_size > post_residual {
            // Next item can't use the leftover anyway; leftover is truly dead.
            score += post_residual as f64 * 0.3;
        }
    }

    // --- New-bin candidate handling ---
    // An empty bin has bin_residual == bin_capacity. Only prefer it when the
    // item is large relative to capacity and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 * mean_residual / (bin_capacity as f64);
        let pressure = (item_size as f64 / bin_capacity as f64) * 30.0 + fragmentation * 1.2;
        // Default: new bin is worse than a decent fit.
        score += 55.0 - pressure;
    }

    // --- Stream progression ---
    // Late in the stream, consolidation matters more (no future to amortize).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward if next item fits into post_residual ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills the leftover space
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 + 0.35 * (next_item_size as f64);
            if slack_after_next == 0 {
                score -= 25.0; // exact 2-item fill, ideal
            }
        } else {
            // Next item cannot follow here; penalize proportional to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(60.0);
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 5.0;
    }

    // --- Penalize dead space relative to bin capacity ---
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead;

    // --- Mean-residual coupling: prefer bins deviating favorably from the mean ---
    // A bin with residual below mean being filled reduces dispersion (good consolidation)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 18.0;
        // Extra strong late in the stream where bin count dominates cost
        score -= 10.0 * progress;
    }

    // --- New-bin candidate handling: only attractive when no open bin fits well ---
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base penalty: prefer using existing bins when reasonable
        score += 30.0;
        // But if many bins already fit the item, discourage new bin more
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // Large leftover items benefit from fresh bins early on
        if item_size >= bin_capacity / 2 && open_bins_count > 0 {
            score -= 5.0 * (item_size as f64 / bin_capacity as f64);
        }
        // Perfect-fit items (item == capacity) always favor new bin
        if item_size == bin_capacity {
            score -= 100.0;
        }
    } else if post_residual == 0 {
        // Perfect closure of an existing bin is excellent
        score -= 20.0;
    }

    // Mild tie-breaking noise-free determinism: prefer earlier bins slightly
    score += 0.001 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space being "wasted" on a large item that nearly fills the bin:
    // exact fits (post_residual small but nonzero) are excellent; zero is perfect.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item can fit into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward for a complementary pair (item + next nearly fills bin).
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill > 0.95 {
                score -= 35.0;
            }
        } else {
            // Next item won't fit here: slight penalty proportional to leftover awkwardness.
            score += 5.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (late in the stream, consolidation matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * (1.0 - progress);
        // If next item is large and would pair with this item in a fresh bin, cheaper.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 20.0;
        }
        // Many open bins: discourage opening more.
        score += 5.0 * open_bins_count as f64;
    }

    // Global state coupling: if mean residual is high, prefer bins below the mean
    // (drain the emptiest-ish bins first to consolidate others).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for very small post residuals that can't fit the minimum item (1..100 range):
    // keep dead space either zero or usable (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals less; later, dead space is costlier.
    let progress_coupling = norm_post * norm_post * (1.0 + 2.0 * progress);
    score += 40.0 * progress_coupling;

    // Reward tight fits more strongly as stream progresses (cubic term)
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strong smooth reward scaled by how well it fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + tightness);
    }

    // Lookahead: reward if next item fits in post_residual (smooth affinity)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (post - nxt).max(0.0);
        let affinity = 1.0 - fit_next / cap;
        score -= 15.0 * affinity * affinity;
        // Penalize if next item leaves awkward gap
        let gap = (post - nxt).max(0.0);
        score += 10.0 * (gap / cap) * (gap / cap) * (1.0 + progress);
    }

    // Mild penalty relative to mean residual: avoid leaving bin far below mean
    score += 5.0 * (mean_residual - post).max(0.0) / cap;

    // Penalize spreading across too many open bins late in stream
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // New-bin candidate: smooth penalty unless current bin is a bad fit
    let waste = norm_post; // large post_residual = wasted capacity
    let new_bin_bias = 8.0 * (1.0 - (waste * 4.0).min(1.0)) * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 10.0).floor() as i64; // 0..=9 harmonic class

    // Reward residuals that fall into "reusable" classes (small, likely fillable by future items)
    let reusable = matches!(class, 0 | 1 | 2 | 3);
    if reusable {
        score -= 6.0 + 4.0 * (3 - class.min(3)) as f64;
    } else {
        // Penalize mid-range dead space (hard to fill)
        score += 3.0 + 2.0 * (class as f64 - 4.0).min(5.0) * 0.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo arithmetic on next_item_size: does the next item mesh with post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Harmonic coupling: post_residual is an integer multiple of next_item_size
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        // Next item leaves a small residue too
        let next_post = post_residual - next_item_size;
        if next_post <= bin_capacity / 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize if residual is wasted
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 30.0 - 10.0 * pressure.min(3.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big items pair well in fresh bins
        }
    }

    // Tightness bonus: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Stream progression: as stream advances, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post > 0.0 {
        // Gap too small to ever hold a plausible item (min item size 1, but
        // practically anything below ~10 is nearly dead given the stream).
        let dead_threshold = 9.0;
        if post <= dead_threshold {
            score += 60.0 * (1.0 - post / dead_threshold); // near-zero gap punished hardest
        }
        // Medium gaps that cannot fit the lookahead item are semi-dead.
        if next_item_size > 0 && post < next_item_size as f64 {
            score += 12.0;
        }
    }

    // Reward tight fits (perfect fill is ideal).
    if post == 0.0 {
        score -= 25.0;
    }

    // Prefer bins whose residual was large (big-gap bins absorb items well).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if average residual is small, conserve tight bins;
    // if average residual is large, prefer filling loose bins.
    score += 0.10 * (mean_residual - post);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item would leave a poor fit everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        score += 20.0 + 10.0 * progress;
        // If the current item is large, a fresh bin is often the right home.
        if item_size >= 60 {
            score -= 12.0;
        }
        // If lookahead is large too, fresh bin pairs well.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Slight preference for placing larger items into fuller bins early.
    score -= 0.05 * item_size as f64 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential decay of post_residual
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-gap / 10.0).exp();
        } else {
            // next item cannot fit here; slight penalty
            score += 5.0;
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating unusable dead space relative to minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it moderately attractive only when no tight fit exists
    if bin_residual == bin_capacity {
        score += 30.0 - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward partial compatibility, scaled by how much would remain after.
            let after_next = post_residual - next_item_size;
            score -= 20.0 * (after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize proportionally to wasted space.
            score += 8.0 * tightness;
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    // and early in the stream; relax slightly when many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 15.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
    }

    // Prefer filling bins whose residual is already small relative to the mean
    // (consolidate waste into fewer bins).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Mild pressure to keep the number of open bins down.
    score += 0.05 * open_bins_count as f64;

    // Late in the stream, favor aggressive consolidation (minimize leftover spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth non-linear coupling: wasted-space penalty grows with progress
    let waste = pr * pr;
    score += 18.0 * waste * (0.5 + progress);

    // Reward tight fits with a smooth saturating term
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Interaction between post_residual and mean residual: avoid fragmenting
    let frag = (pr - mean_residual / bin_capacity as f64).abs();
    score += 6.0 * frag * frag;

    // Lookahead coupling: smooth quadratic penalty if next item wastes space
    if next_item_size > 0 {
        let gap = (pr * bin_capacity as f64 - next_item_size as f64).max(0.0);
        let ng = gap / bin_capacity as f64;
        score += 8.0 * ng * ng * (1.0 - progress);
    }

    // Last-chance bonus, smooth in fitting_bins_count
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr);
    }

    // Mild pressure against hoarding many open bins late in the stream
    score += 2.0 * (open_bins_count as f64).ln() * progress * pr;

    // New-bin candidate: penalize opening fresh bins unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "usable" for
    // common small items (multiples of 10 up to 100) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = 10 - (pr % 10 == 0) as u32 * 0; // class marker
        let _ = harmonic;
        // Perfect fill: huge reward.
        if pr == 0 {
            score -= 1000.0;
        } else {
            // Dead-space penalty grows super-linearly for awkward residuals
            // (small non-decade leftovers are hard to fill).
            let dead = if pr < 10 { 40.0 } else if pr < 20 { 18.0 } else { 0.0 };
            score += dead;

            // Decade-aligned residuals are attractive: subtract a bonus.
            if pr % 10 == 0 {
                score -= 6.0 + (pr / 10) as f64;
            }

            // Can the lookahead item fit exactly? Strong reward.
            if next_item_size > 0 {
                if next_item_size == pr {
                    score -= 120.0;
                } else if next_item_size < pr {
                    let nr = pr - next_item_size;
                    // Reward if lookahead leaves another decade-aligned residual.
                    if nr % 10 == 0 { score -= 25.0; }
                    score -= (nr as f64).ln().max(0.0) * 2.0;
                } else {
                    // Lookahead cannot use this bin's leftover: mild penalty,
                    // worse when the leftover is tiny (true dead space).
                    if pr < next_item_size && pr < 30 { score += 12.0; }
                }
            }
        }
    } else {
        score -= 1000.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when no open
    // bin offers a decent fit; scale with stream progress (waste matters
    // more later) and with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64) + 2.0 * open_bins_count as f64;
        // But if lookahead is large and no residual class helps, new bin is fine.
        if next_item_size > 60 { score -= 15.0; }
    }

    // Prefer tighter fits overall: reward small post_residual relative to capacity.
    score -= 10.0 * (1.0 - pr as f64 / bin_capacity as f64).powi(3);

    // Prefer bins below mean residual (consolidate emptier space? no —
    // prefer filling bins that are already fuller than average).
    if (bin_residual as f64) < mean_residual {
        score += 4.0;
    } else {
        score -= 3.0;
    }

    // Integer-division threshold: if post_residual falls in [10,30) band,
    // treat as semi-dead unless lookahead matches.
    if pr >= 10 && pr < 30 && next_item_size != pr && !(next_item_size > 0 && next_item_size < pr) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // only smallest items can use it
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.3; // prefer chains with small leftover slack
            if slack < 1.0 {
                score -= 10.0; // exact chain
            }
        } else {
            score += 5.0; // next item can't reuse this bin
        }
    }

    // Last-chance bonus: sole fitting bin should be strongly favored over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when open fits are bad,
    // but reduce penalty when many bins are open (fragmentation pressure) or
    // when the item is small enough that residual 100-item is fine.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 20.0;
        new_bin_penalty += open_bins_count as f64 * 2.0;
        new_bin_penalty -= mean_residual * 0.1;
        if item_size > 50 {
            new_bin_penalty -= 10.0; // big items tolerate fresh bins
        }
        if progress > 0.9 {
            new_bin_penalty += 10.0; // late stream: prefer closing bins tightly
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for bins with below-mean residual (tighten loose bins).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Penalize large post residuals relative to capacity (wasteful large gap).
    score += (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong tight-fit reward
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // 2-step lookahead: reward when next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr <= post_residual as f64 {
            let next_fit = 1.0 - ((post_residual as f64 - nr) / bin_capacity as f64);
            score -= 40.0 * next_fit * next_fit;
        } else {
            // next item won't fit: penalize leaving residual that is too small to be useful
            let waste = (nr - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * waste;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual deviates favorably
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.max(0.0);
            if best_possible >= item_size as f64 {
                score += 20.0;
            }
        }
    }

    // Slight preference for using fewer open bins late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large unusable dead space: residual too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += 4.0 * ((next_item_size as f64 - post_residual as f64) / 50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-full bin when many alternatives exist.
    if fitting_bins_count > 3 && post_residual > 0 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let fill_bonus = (mean_residual / bin_capacity as f64) * 8.0;
        score -= fill_bonus;
    }

    // Time horizon: early in stream, be pickier about residual quality; late, just fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (1.0 - tightness);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when this bin is a poor fit for the item
    // (large post-residual waste relative to capacity) or no good existing option.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // Empty bin is attractive if the item is large (small waste) — but must
        // compete with last-chance bonuses, so add a calibrated offset.
        score += 20.0 + 60.0 * waste_ratio;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / c;
    let base = pr as f64;
    // smooth polynomial coupling of post residual with progress
    let poly = norm_pr * norm_pr * (1.0 - t) * 40.0 + norm_pr * t * 25.0;
    // tight fit reward (small post residual), stronger later in stream
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr) * (30.0 + 30.0 * t);
    let mut score = base + poly - tight;
    // lookahead: prefer bins whose residual still fits next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 8.0 * (1.0 - (ns / c)) * (1.0 - t);
        } else {
            score += 6.0 * (ns / c);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // penalize opening new bin when open bins exist and mean residual is large
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + mean_residual * 0.2;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets (capacity fractions of 100).
    let post_mod = post_residual % 10;
    // Dead space penalty: residuals that no item (min size 1..100, but typical classes 10..80)
    // can nicely fill are penalized. Residuals in {0} are perfect; small nonzero are bad.
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // penalize by how far post_residual is from a "usable" harmonic class
        let usable = if post_residual >= 10 && post_residual <= 80 { 1.0 } else { 0.0 };
        if usable == 0.0 {
            score += 15.0; // residual too small (or >80, impossible here) => dead space
        }
        // fractional dead-space: post_mod near 0 is fine, near 9 is worst
        score += (post_mod as f64) * 0.8;
    }

    // Harmonic coupling with next item: does post_residual leave room for the lookahead?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // exact lookahead fit
        } else if next_item_size < post_residual {
            let rem = post_residual - next_item_size;
            // reward if remaining after lookahead is harmonic (multiple of 10 or 0)
            if rem % 10 == 0 {
                score -= 8.0;
            }
            score -= 5.0; // lookahead fits at all
        } else {
            score += 6.0; // lookahead won't fit here; this bin becomes dead
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // New-bin candidate: make it moderately attractive only when current bin waste is high.
    if bin_residual == bin_capacity {
        score += 4.0 + mean_residual * 0.05;
    }

    // Slight adaptation over stream progress: tighten packing later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (20 - post_residual) as f64;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer filling bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * (0.5 + progress);

    // Lookahead: if the next item would fit the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 10.0; // would create another dead gap for the lookahead item
    }

    // New-bin candidate: keep it attractive when existing fits are poor,
    // but discourage opening bins when decent fits exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        score -= 60.0 / (1.0 + diff);
        // exact chain match: item + next item perfectly fills bin
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        }
        // penalize leaving residual too small for next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0; // new bin more attractive if next item is large
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize post_residual that is too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer scarcer opportunities elsewhere
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global state: if mean residual is high, prefer filling existing bins
    // rather than spreading items; if low, opening new bins is safer.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.3;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: empty bin should only win when existing
    // bins are poor fits (large post_residual) or few bins can fit.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 40.0; // opening a new bin is fine when no real alternative
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Slight preference for bins with residual close to item_size (perfect fill).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += waste * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space non-linearly (quartic-ish growth in normalized residual)
    score += 30.0 * pr_norm * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: small post_residual gets a bonus, stronger early in the stream
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // New-bin candidate: neutral-ish baseline, penalized slightly more as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "useful" residue class modulo common item-size buckets are worth keeping.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual is exactly 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Class B: post_residual too small for the minimum item (1) — dead space classes.
    // Small nonzero leftovers (1..=10) are near-dead; penalize them.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Harmonic bucket: integer division of post_residual into size classes.
    // Residues in [11, 30] are mid-class: only useful for small items.
    let bucket = post_residual / 25; // 0,1,2,3 harmonic class
    match bucket {
        0 => score += 10.0,                       // tiny leftover, poor class
        1 => score -= 5.0,                        // 25..49, decent for small items
        2 => score -= 12.0,                       // 50..74, good mid class
        _ => score -= 8.0,                        // 75..99, large leftover but bin nearly fresh
    }

    // Coupling with next item: if the leftover can host the lookahead item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward when leftover is a tight harmonic multiple of next size.
        if post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit: penalize proportionally to how "wasted" the bin is.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; only prefer it
    // when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline minus a mild discount so it wins only
        // against badly-fragmented open bins.
        score -= 15.0;
        // Penalize opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // Penalize if many bins are already open and mean residual is large.
        score += (open_bins_count as f64).sqrt() * 2.0;
        if mean_residual > cap * 0.5 {
            score += 15.0;
        }
    }

    // Mild preference for filling bins that are already well used.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * 10.0;

    // Mean-residual coupling: favor bins deviating below the mean residual
    // (i.e., tighter bins) to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item are pure waste. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Medium-small gaps are risky too, but less so.
    if post_residual >= 10 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    }
    // If next item would leave a dead gap, penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (favor filling).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * 2.0 * (0.5 + progress);

    // Relative tightness vs. mean residual: filling below-mean bins is good.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let would_be_dead = post_residual > 0 && post_residual < 10;
        if would_be_dead {
            score -= 50.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when next item fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly reusable
        } else if post_residual >= next_item_size {
            // reward tight leftover margin after the next item would land
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack_after_next * 0.5;
        } else {
            // next item cannot follow here; penalize proportionally to wasted chain potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score += 5.0;
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual means this bin is more "consumed" -> favorable.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual is huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // but penalize if residual after placement is unusably small
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0; // default penalty: prefer existing bins
        if fitting_bins_count == 0 || (next_item_size > 0 && post_residual == next_item_size) {
            score -= 45.0; // opening fresh bin is justified for perfect chain
        }
        // early in stream, new bins are cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild reward for tight fits overall (small post_residual relative to item)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Slight penalty for proliferating bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize post-residuals that are "dead space": too small for the smallest
    // plausible future item (<= 10). Anything below 10 is nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.10 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Perfect pairing: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // (few fitting bins) or residuals are fragmented.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).abs();
        let penalty = 14.0 + 0.6 * open_bins_count as f64 + 20.0 * (1.0 - scarcity);
        // Discount the penalty late in the stream (consolidation phase).
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score += penalty * (1.0 - 0.5 * horizon);
        let _ = fragmentation;
    }

    // Mild penalty for leaving residuals in the awkward 11..=30 band: hard to fill
    // with typical items but not dead space.
    if (11..=30).contains(&post_residual) {
        score += 3.0 + 0.05 * post_residual as f64;
    }

    // Global balance: slightly prefer bins whose residual is below the mean
    // (fills the emptier bins first, keeping tight bins for big items).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Quadratic penalty on post_residual scaled by stream progress:
    // late in the stream, dead space hurts more.
    let norm_post = post / cap;
    score += (norm_post * norm_post) * cap * (0.3 + 0.9 * progress);

    // Tight-fit reward: strongly prefer bins where item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * cap * 0.4;

    // Smooth coupling: penalize post_residual relative to mean residual across bins.
    score += (post - mean_residual) * (0.15 + 0.5 * progress) * (1.0 - norm_post);

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post.max(1.0);
        score -= next_fit * next_fit * cap * (0.25 + 0.35 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover space.
        score += norm_post * cap * 0.1 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // New-bin candidate: neutral baseline with slight late-stream discount,
    // penalized more when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        score = cap * (0.55 - 0.25 * progress) + 0.2 * mean_residual * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near capacity multiples
    // are more reusable. Classify post_residual into harmonic buckets.
    let cap = bin_capacity as f64;
    let quarter = cap / 4.0;
    let pr = post_residual as f64;

    // Harmonic class bonus: residuals that are multiples of 25 (or close)
    // pair well with common item sizes; reward them.
    let harmonic = (pr / quarter).round() * quarter;
    let harmonic_dev = (pr - harmonic).abs();
    score += harmonic_dev * 0.8; // penalize off-class residuals

    // Exact harmonic alignment reward
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Dead-space penalty: tiny unusable leftovers
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility of next item with post residual
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
            if (post_residual as i64 - next_item_size as i64).rem_euclid(10) == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual; mildly penalize
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (reduce bin count pressure)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_ratio * 20.0 * (open_bins_count as f64).sqrt().min(5.0);

    // Late in stream: consolidation matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress * (1.0 - fill_ratio);

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual = capacity - item
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 10.0; // discourage abandoning the lone fitting bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mean residual context: when open bins are generally full, avoid waste
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Baseline: best-fit (smaller leftover space => lower score).
    let mut score = post;

    // Perfect fit: closing a bin is ideal, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: tiny nonzero gaps are likely unusable forever.
    let dead_floor: f64 = 10.0;
    if post_residual > 0 && post < dead_floor {
        score += (dead_floor - post) * 3.0;
    }

    if nxt > 0.0 {
        if post >= nxt {
            // Chain fit: this bin can also host the lookahead item.
            score -= 6.0 + nxt * 0.5;
        } else if post > 0.0 {
            if res >= nxt {
                // We are ruining a bin that could have hosted the next item whole.
                score += (nxt - post) * 2.0 + 12.0;
            } else {
                // Residual is dead relative to the next item, but the bin couldn't
                // have hosted it anyway: milder penalty.
                score += (nxt - post) * 0.5;
            }
        }
    }

    // Slight preference for bins tighter than the current fleet average.
    score += (res - mean_residual) * 0.05;

    if is_new_bin {
        // Opening a new bin: fixed cost plus pressure from fleet size,
        // amplified as the stream progresses (less time left to fill partials).
        score += 18.0 + open_bins_count as f64 * 3.0 * (1.0 + progress);
        if fitting_bins_count >= 1 {
            // Existing bins can host the item; make the fresh bin pay extra.
            score += 10.0 + fitting_bins_count as f64 * 2.0;
        }
        if nxt > 0.0 && post >= nxt {
            // A fresh bin chains the next item nicely; soften its penalty.
            score -= 8.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance before opening a new bin: strongly favor this placement.
        score -= 45.0 + item * 0.2;
    }

    let _ = cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 10.0;

    // Aggressive 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + diff);
        // Penalize leaving residual that neither fits next item nor is tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += post_residual as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += post_residual as f64 * 0.5;
    }

    // Prefer bins with residual below mean residual (compact usage), penalize wasteful large-residual bins.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins or big item relative to residuals -> keep new-bin score high).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If the item would leave a lot of dead space in any open bin, opening a new bin
        // becomes relatively better: discount the new-bin penalty.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let min_item = 1.0;
        if (post_residual as f64) < min_item {
            score -= 50.0;
        }
        // Post-residual too small for typical items is wasted capacity.
        if post_residual < 10 && post_residual > 0 {
            score += 8.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post-residual matches next item closely.
            score -= 10.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.05 * residual_gap * (1.0 + progress);

    // Late in the stream, prefer compacting into existing bins rather than spreading.
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 6.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (large residual gap) or few bins are open.
    if bin_residual == bin_capacity {
        let escape_cost = 40.0 + 25.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
        score += escape_cost;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 60.0; // huge item coming, fresh bin is right
        }
    }

    // Mild penalty for putting small items into nearly empty bins.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio < 0.35 && bin_residual as f64 > 0.8 * bin_capacity as f64 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: penalize wasted residual quadratically (small dead space is costly)
    let mut score = post * (1.0 + (1.0 - fit_frac).powi(2));

    // Smooth non-linear coupling with stream progress: early on tolerate slack,
    // later demand tight fits (post_residual weight grows with progress).
    score *= 1.0 + 0.8 * progress * (1.0 - fit_frac);

    // Reward near-perfect packing via smooth sigmoid-like term
    score -= 6.0 * (-post / 12.0).exp();

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx).abs();
        score -= 8.0 * (-diff / 10.0).exp();
        // penalize post_residual slightly larger than next item (unusable sliver)
        if post > nx && post - nx < 10.0 {
            score += 5.0 * (1.0 - (post - nx) / 10.0);
        }
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but relax penalty as stream progresses / open bins pile up.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress - 0.3 * open_bins_count as f64;
        // if no bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "small residue"
    // classes are nearly perfect fits; reward them strongly.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity left over

    // Dead-space penalty: leftover that is too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..10 classes
    let class_bonus: f64 = match class {
        0 => -60.0,                      // leftover < 10: near-perfect
        1 => -20.0,                      // 10..19: fits smallest items
        2 | 3 => -5.0,                   // mid classes
        4 | 5 | 6 => 10.0,               // awkward middling leftovers
        7 | 8 => 0.0,
        _ => -30.0,                      // nearly empty bin: very reusable
    };
    score += class_bonus;

    // Modulo coupling: leftover that is a multiple of common item sizes is reusable.
    let m = post_residual % 10;
    if m == 0 {
        score -= 12.0;
    } else {
        score += m as f64 * 0.8; // ragged leftovers penalized
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportionally to how well the next item uses the leftover
            let nxt_use = next_item_size as f64 / pr.max(1.0);
            score -= 40.0 * nxt_use;
        } else {
            // leftover can't host next item: penalize if gap is small (wasted)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer denser (more filled) bins when many bins are open.
    score -= (1.0 - frac) * (open_bins_count as f64).sqrt() * 3.0;

    // Mild pressure toward consolidation early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 30.0 + mean_residual * 0.3;
        score = if fitting_bins_count == 0 { -50.0 } else { base + score };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: gaps that are too small to hold a typical item
    // (1..=10) are essentially unusable; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Moderate gaps (10..=20) are risky too: mildly penalize.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // If the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
    }
    // If next item does NOT fit here, this bin becomes dead space for it;
    // penalize proportionally to how close it was.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open,
    // discourages proliferation of bins.
    score -= open_bins_count as f64 * 2.0;

    // Prefer bins with residual close to item_size (tight fit) via
    // relative waste measure.
    if bin_residual > item_size {
        let rel = item_size as f64 / bin_residual as f64;
        score -= rel * 10.0;
    }

    // Slight preference for larger residual bins when stream is early,
    // to keep flexibility; late in stream, just minimize waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so it only wins when all open bins
    // give poor fits (their dead-space penalties push them above this).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large dead space quadratically.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;
    score += 0.02 * (post_residual as f64).powi(2);

    // 2-step lookahead: reward when post_residual exactly or nearly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: strong reward, tighter gap = better.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would not fit: penalize proportionally to wasted potential.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // Perfect chaining bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Compare against mean residual: leaving this bin far above mean residual wastes space.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: new bin is necessary
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // An existing bin chains perfectly; discourage new bin.
            score += 10.0;
        } else if fitting_bins_count == 1 {
            // Last-chance bin exists; new bin should lose unless fit is terrible.
            let worst_fit = item_size as f64 / bin_capacity as f64;
            if worst_fit < 0.9 {
                score += 35.0;
            }
        }
        // Late in the stream, avoid leaving many near-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress * (open_bins_count as f64).sqrt();
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * waste * waste * (bin_capacity as f64);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mildly penalize blocking large residuals.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        } else if fitting_bins_count == 1 {
            score += 10.0; // prefer the last-chance existing bin
        }
        // Late in the stream, fewer bins matter less; allow opening slightly more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to the item (best-fit style refinement).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * fit_gap;

    // Fragmentation guard: avoid leaving residuals that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Prefer filling bins with larger existing load when many bins are open.
    score += 0.02 * (open_bins_count as f64) * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: when mean residual is small, conserve open bins.
    if mean_residual < item_size as f64 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual

    // Base: non-linear polynomial in normalized post residual (tight fits favored)
    let mut score = 3.0 * x - 2.5 * x * x + 4.0 * x * x * x;

    // Smooth coupling with stream progress: later in stream, punish wasted space harder
    score += (0.5 + 2.0 * progress) * x * x * cap * 0.05;

    // Lookahead: reward residual that could fit the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n).abs() / cap;
        score -= 1.5 * (-3.0 * fit_gap * fit_gap).exp();
        // exact-fit lookahead bonus
        score -= 2.0 * (-8.0 * fit_gap * fit_gap).exp();
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a bin, scaled by waste it would create
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * x + 2.0 * progress * x;
    }

    // Slight preference for bins whose residual deviates from mean (consolidate similar fills)
    let dev = (pr as f64 - mean_residual) / cap;
    score -= 0.4 * dev * dev * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fits (post==0) strongly favored.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize residuals that are "awkward" classes: small but nonzero
        // residues (dead space) vs large reusable ones.
        let frac = post / cap;
        if frac < 0.10 {
            score += 30.0; // tiny dead space, hard to reuse
        } else if frac < 0.30 {
            score += 8.0;
        } else if frac < 0.60 {
            score -= 5.0; // sweet spot: fits most mid items
        } else {
            score -= 10.0; // large residual, very reusable
        }

        // Modulo-10 harmonic classes: residuals divisible by 10 align with
        // common item granularity.
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 25.0; // perfect chain
            } else {
                score -= (slack as f64).min(20.0) * 0.4;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default mild penalty so it's chosen only when
    // open bins would create bad fits; but attractive early in the stream
    // or when open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 20.0 + 40.0 * (1.0 - progress) - mean_residual * 0.3;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Don't open a new bin for a small item if a roomy bin exists.
        if item_size <= 20 && mean_residual > 50.0 {
            score += 60.0;
        }
    }

    // Tie-break toward bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly larger but still hard-to-fill gaps are also penalized.
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits: post_residual close to zero is excellent.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Fractional fill quality: the fuller the bin, the better.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 40.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual coupling: if open bins already have lots of slack, avoid spreading further.
    if bin_residual != bin_capacity {
        score += 0.15 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += 5.0; // next item cannot use the gap; dead space likely
        }
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.4 + 0.3 * mean_residual;
        score += 25.0 + pressure;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If only one bin fits, opening a new bin may be reasonable; soften penalty.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: next item exactly fills leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0; // perfect chain: bin closes fully
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement, scaled
            score += 0.5 * slack;
            // extra reward if next item leaves a small, still-usable gap
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 20.0;
            }
        } else {
            // next item cannot follow in this bin; leftover must hold alone
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 15.0; // tiny dead space is worthless
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize very tight fits slightly less than wasteful large gaps:
    if post_residual == 0 {
        score -= 200.0; // perfect fill now
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect fill
    }

    // New-bin candidate handling: only attractive when no decent fit exists
    // or many bins are open and current ones are fragmented.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0;
        let fragmented = open_bins_count > 0 && mean_residual < item_size as f64;
        if desperate {
            score -= 500.0;
        } else if fragmented {
            score -= 5.0;
        } else {
            score += 120.0; // prefer placing into an existing usable bin
        }
    }

    // Mild stream-progression pressure: consolidate more as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize small unusable dead space (< next item size) unless nearly full.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward when post_residual matches lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fits = (fitting_bins_count as f64) <= 1.0;
        // Prefer new bin when few fitting bins and mean residual is low (existing bins full).
        if poor_fits && mean_residual < item_size as f64 {
            score -= 90.0;
        } else {
            score += 50.0 + 30.0 * progress;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight bias toward bins with residuals close to the mean (balanced packing).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual squared normalized by capacity
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm = pr / cap;
    score += 8.0 * norm * norm * cap * (0.5 + progress);

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize post_residual that cannot fit the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * gap / cap * (1.0 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item
        score -= 4.0 * (post_residual - next_item_size) as f64 / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - norm);
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely useful
    if bin_residual == bin_capacity {
        let useful = if next_item_size > 0 && next_item_size >= item_size { 1.0 } else { 0.0 };
        score += 15.0 - 10.0 * useful - 5.0 * progress;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Slight preference for balancing residuals across open bins
    score += 0.5 * (post_residual as f64 - mean_residual).abs() / cap;

    // Small bonus for larger items placed early (better packing later)
    score -= 0.05 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Residuals in low classes (0..=2) are excellent; high classes are dead space.
    score -= 30.0 / (1.0 + class as f64);

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with the next item: reward residuals that the next item can nearly fill.
    if next_item_size > 0 {
        let d = post_residual as i64 - next_item_size as i64;
        if d == 0 {
            score -= 60.0; // next item exactly fills this bin
        } else if d > 0 && d <= 10 {
            score -= 25.0; // next item leaves a tiny sliver
        } else if d < 0 && (-d) as u32 <= item_size {
            score += 10.0; // next item would barely not fit: mild penalty
        }
        // Harmonic pairing: residual in the same decade class as next item size
        if post_residual / 10 == next_item_size / 10 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: any residual is pure waste; prefer fullest bin.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual > 40 {
            score += 20.0; // item would leave big hole even in fresh bin
        }
        // Early in the stream, allow more bins; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins get used first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Small modulo tie-breaker on residual to break exact ties deterministically.
    score += (post_residual % 3) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a small nonzero gap that likely cannot
    // host a future item is heavily penalized (quadratic in its "wastedness").
    let dead_zone: f64 = 20.0; // gaps below this are rarely reusable
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        let waste = dead_zone - post_residual as f64;
        score += 3.0 * waste * waste / dead_zone;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: late in the stream or with many open bins, discourage
    // spreading across bins; favor filling existing ones.
    score += 0.6 * open_bins_count as f64 * (0.3 + progress);

    // New-bin candidate: give it a moderate baseline so it only wins when the
    // best existing fit is poor (high post_residual / dead space).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score = 55.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits into post_residual -> moderate reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * tightness;
    }
    // Dead space: leftover too small for the next item -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Penalize post_residuals in the "unusable" band (too small for typical items 1..=100
    // but not near-zero): residual in (0, 10) is likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Perfect closure (residual 0) is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins whose post_residual deviates
    // favorably (larger usable space than average is good, smaller is bad).
    let mr = mean_residual - post_residual as f64;
    score += 0.3 * mr;

    // New-bin candidate: only attractive when no open bin is a good match
    // (many fitting bins -> discourage opening new bins).
    if bin_residual == bin_capacity {
        score += 55.0 + 12.0 * fitting_bins_count as f64;
        // But if next item is huge and this item is small, opening fresh may pay off.
        if next_item_size > 0 && next_item_size >= 70 && item_size <= 30 {
            score -= 35.0;
        }
    }

    // Late in the stream, consolidate: discourage opening new bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

