        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * next_fill;
    }
    // Penalize leaving a residual just below the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when few bins fit or fit is terrible.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let poor_fit = (item_size as f64 / cap) < 0.5;
        let pressure = mean_residual / cap;
        // Penalize new bins generally; discount when residual space is abundant
        // and item is large (likely to leave unusable slivers elsewhere).
        score += 35.0 - 30.0 * scarcity - (if poor_fit { 15.0 } else { 0.0 }) + 20.0 * (1.0 - pressure);
        // Early in stream, opening bins is cheaper (build capacity pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Mild preference for fuller bins when many bins are open (consolidation).
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 5.0 * fill * (open_bins_count.min(50) as f64 / 50.0);
    }

    // Deviation from mean residual: prefer bins that are outliers-full.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * if bin_residual as f64 > mean_residual { -1.0 } else { 1.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // early on, waste matters less; later, dead space is penalized quadratically.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let progress_coupling = norm_pr * (1.0 + 2.5 * progress * progress);
    score += progress_coupling * cap * 0.35;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    score -= 8.0 * tightness;

    // Last-chance bin: strongly reward using it (avoids opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless residual would be very small
    if bin_residual == bin_capacity {
        let lookahead_waste = if next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 { gap * gap } else { 0.0 }
        } else { 0.0 };
        score += 30.0 + 0.3 * (open_bins_count as f64) + 0.2 * lookahead_waste;
    }

    // Lookahead coupling: if next item fits smoothly into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let smooth = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 6.0 * smooth * (1.0 + progress);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // next item can't use this bin's leftover: penalize dead space smoothly
        score += 0.15 * pr * (0.5 + progress);
    }

    // Mild preference for bins with larger residuals (best-fit behavior emerges
    // naturally since post_residual dominates, but add slight balancing term)
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Integer-division thresholds on post_residual: bins with residual in
    // "dead zones" (too small to host anything useful) get penalized.
    let dead_threshold: u32 = 10; // smallest possible item
    if post_residual < dead_threshold {
        score += 50.0; // pure dead space
    } else if post_residual < 2 * dead_threshold {
        score += 20.0;
    }

    // Harmonic classes: post_residual mod 10 and mod 25
    let m10 = post_residual % 10;
    let m25 = post_residual % 25;
    score += (m10 as f64) * 0.8;
    score += (m25 as f64) * 0.5;

    // Coupling with next item: if next item exactly fits post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nm = post_residual % next_item_size.max(1);
            score -= 15.0 - (nm as f64) * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness term: prefer small residual fraction non-linearly
    score += frac * frac * 30.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin mildly unless current fit is bad
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= dead_threshold * 2 {
            score -= 20.0; // keep new bin clean for tiny future items
        }
    }

    // Progress-aware scaling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but practically below the lookahead item) are wasted space.
    if post_residual > 0 {
        if post_residual < next_item_size.max(1) {
            // Dead space that cannot hold the next item: heavy penalty, worse the smaller the gap.
            score += 25.0 + (next_item_size.max(1) - post_residual) as f64 * 0.8;
        } else if next_item_size > 0 && post_residual == next_item_size {
            // Perfect provision for the lookahead item: strong reward.
            score -= 20.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Usable gap: mild reward proportional to how tightly it matches lookahead.
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fill: maximal reward.
        score -= 40.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage spreading into fresh space;
    // favor closing out bins by accepting loose fits there.
    if open_bins_count > 2 {
        score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no decent fit exists
    // (i.e., current bin fit would leave a bad dead gap) or stream is early.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < next_item_size.max(1);
        if bad_fit && fitting_bins_count >= 1 {
            // Opening fresh beats creating dead space in an existing bin.
            score -= 30.0;
        } else {
            // Otherwise keep using existing bins.
            score += 22.0 + 2.0 * open_bins_count as f64;
        }
        // Early stream: opening bins is cheap and builds diversity.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.15 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if the fleet of open bins already has slack,
    // penalize leaving yet more slack behind.
    if mean_residual > 0.0 {
        score += 0.15 * (post_residual as f64 - mean_residual).abs().min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
