    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here: mild penalty scaled by overflow size.
            score += 1.5 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * progress;
    }

    // Penalize spreading across too many open bins relative to mean residual.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).abs();

    // New-bin candidate (empty bin): penalize opening new bins unless all open bins
    // would leave very large unusable residuals; smooth gate via norm_post of others.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        let gate = 1.0 / (1.0 + (-8.0 * (avg_waste - 0.5)).exp()); // smooth sigmoid
        score += 8.0 * (1.0 - gate) + 2.0;
        // Late in the stream, closing out is fine; relax the penalty smoothly.
        score -= 3.0 * progress * progress;
    }

    // Small tie-breaker favoring fuller bins.
    score -= 0.1 * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
