pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host the
    // smallest plausible future item are "dead space" — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (small but still usable residual).
    score -= (bin_residual - post_residual) as f64 * 0.8;

    // Penalize bins far below the mean residual (poor relative fit).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a good pairing with
    // the lookahead item (large item now, leaving room for next item).
    if bin_residual == bin_capacity {
        let mut nb = 15.0 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size <= post_residual.max(bin_capacity - item_size) {
            nb -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        nb += (step_index as f64 / total_items.max(1) as f64) * 10.0;
        score += nb;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    // If next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 {
        let lookahead_sum = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - lookahead_sum).abs() < 0.5 {
            score -= 60.0;
        } else if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item still fits after this placement: mildly favorable, tighter is better.
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item won't fit here afterward: penalize wasted residual relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // Last item of the stream: prefer minimal post_residual.
        score += 0.5;
    }

    // Penalize post_residual relative to mean residual (avoid creating unusually wasteful bins).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.35;

    // Penalize small unusable dead space (fragmentation), but allow near-zero residual.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If lookahead shows a perfect fill is possible in a fresh bin, make it attractive.
        if next_item_size > 0 && (bin_capacity as u64 - item_size as u64 - next_item_size as u64) == 0 {
            score -= 70.0;
        }
        // Early in the stream, opening bins is cheaper (build a diverse pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // If many bins are already open and residuals are high, discourage opening more.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Slight preference for tighter fits overall.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Penalize dead space that is too small to be useful later (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large gaps.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing bins to consolidate.
    if open_bins_count > 2 {
        score += 0.6 * open_bins_count as f64;
        score -= (mean_residual - post_residual as f64).abs() * 0.3;
    }

    // Time horizon: early in the stream, encourage opening bins with good
    // balance; late in the stream, pack greedily into whatever fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 20.0;
    score -= progress * fit_ratio * 10.0;

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit is poor.
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count == 0 { 0.0 } else { mean_residual / bin_capacity as f64 };
        score += 45.0 - crowd * 70.0 + fit_ratio * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is required
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual (dead space fraction)
    let x = pr / cap;

    // Non-linear polynomial coupling with stream progress:
    // early in the stream, waste is cheap (bins will still be reused);
    // late in the stream, waste becomes costly (less opportunity to fill).
    let weight = 1.0 + 2.5 * progress * progress + 1.5 * progress;

    // Base: penalize leftover space, with cubic smoothing so tiny residuals
    // are strongly favored (near-perfect fits).
    let mut score = x * weight * (1.0 + 3.0 * x * x);

    // Reward tight fits: subtract a smooth function of how well item fills bin.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 4.0 * tightness * tightness * (1.0 - progress * 0.5);

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (smooth quadratic bonus).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 3.0 * (1.0 - gap).max(0.0) * (1.0 - gap);
        // penalize leaving a residual that is just barely too small for next item
        if next_item_size as f64 > pr {
            score += 1.5 * ((next_item_size as f64 - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, especially early,
    // and more when many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.15 * open_bins_count as f64 + 2.0 * progress;
        // but a new bin is attractive if current item is huge relative to
        // typical residuals (avoids fragmenting many bins)
        score -= 2.0 * (item_size as f64 / cap) * (item_size as f64 / cap);
    }

    // Mild attraction toward bins whose residual is close to mean residual
    // (keeps the pool homogeneous, smooth Gaussian-like term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic classes of post_residual (capacity / 10 buckets) ---
    // Bucket 0 (residual 0..9): near-perfect fit, but tiny leftovers <10 are dead space
    // Bucket 1 (10..19): awkward zone, likely unusable for typical items -> penalize
    // Bucket 2 (20..29): still awkward for medium items -> mild penalty
    // Buckets 3+ (30..100): reusable space, mild reward for larger usable chunks
    let cls = (post_residual / 10) as i32;
    match cls {
        0 => {
            if post_residual == 0 { score -= 30.0; }      // perfect fit, best outcome
            else { score += 25.0; }                        // dead space < 10
        }
        1 => { score += 18.0; }                            // awkward dead zone
        2 => { score += 6.0; }                             // semi-awkward
        3 => { score -= 4.0; }                             // usable for small items
        4 => { score -= 6.0; }                             // good reusable chunk
        _ => { score -= 2.0; }                             // large residual: acceptable
    }

    // --- Lookahead coupling (k=2): reward bins where the next item also fits ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain placement possible: strong reward, scaled by how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 - snug.min(20.0) * 0.3;
        } else {
            // next item won't fit here after placement: mild penalty
            score += 8.0;
        }
    }

    // --- Last-chance bin: if this is the only open bin that fits, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // forced: no open bin can fit; neutral baseline
            score += 0.0;
        } else {
            // opening a new bin when alternatives exist: penalize proportionally
            // to how much reusable capacity we're abandoning (mean_residual)
            score += 70.0 + mean_residual * 0.4 + (open_bins_count as f64) * 2.0;
        }
    }

    // --- Progression term: late in the stream, consolidation matters more ---
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 4.0;

    // --- Prefer filling bins that are already relatively full (residual close to item) ---
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += waste * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps are mildly penalized beyond their raw value.
    if post_residual >= 10 && post_residual < 25 {
        score += 5.0;
    }

    // Reward tight fits (exact fit is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space that blocks the known next item
    }

    // Last chance: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // and when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let mut nb = 20.0;
        nb += 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            nb += 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        nb += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        score += nb;
    }

    // Open-bin pressure: mildly prefer fuller bins (low residual) when many bins open.
    score += 0.3 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is near the mean (balance) slightly.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
