pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: scale by how much of the item is "used up" relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * (item_size as f64);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * chain_quality;
    }
    // Penalize leaving a residual that is too small for typical next items (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin, more so when other bins fit fine
    // and mean residual is healthy; relax penalty late in the stream or when
    // open bins are nearly full on average.
    if is_new_bin {
        let mut penalty = 9.0;
        penalty += 0.3 * mean_residual;
        penalty += 1.5 * open_bins_count as f64;
        // If existing fitting options are poor (many fitting bins but big residuals wasted),
        // opening fresh can still be reasonable; decay penalty with progress.
        penalty *= (1.0 - 0.5 * progress);
        score += penalty;
    } else {
        // Mild reward for consolidating into bins that are already quite full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 4.0 * fullness;
    }

    // Slight preference for exact fills.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste left behind (quadratic penalty on unusable space)
    let mut score = pr * (1.0 + 0.008 * pr / cap);

    // Tight-fit reward: strongly favor small post_residual relative to capacity
    score -= 12.0 * (1.0 - pr / cap).powi(3);

    // Lookahead: penalize if next item cannot fit the post residual (dead end)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 6.0 + 0.15 * (nxt - pr);
        } else {
            // reward leaving exactly enough room for the next item
            score -= 4.0 * (1.0 - (pr - nxt) / cap).abs().min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: smooth penalty growing with stream progress and item size,
    // so early on we open bins freely but later we prefer filling existing ones.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 8.0 + 25.0 * progress + 0.1 * item;
        // Exception: opening a new bin is fine when open bins are nearly full on average
        score -= 10.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // Mild preference to balance residuals toward the mean (avoid many near-empty bins)
    score += 0.05 * (pr - mean_residual).abs();

    // Stream-progress coupling: as the stream advances, waste becomes costlier
    score += 5.0 * progress * (pr / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is post_residual
    // under typical item granularity (items are 1..100, common small sizes 1..20)?
    let pr = post_residual;
    let small_pool = if pr >= 20 { 1.0 } else { pr as f64 / 20.0 };

    // Reward small dead space (tight fit), strongly.
    score -= 60.0 * small_pool;

    // Perfect-fit harmonic classes: post_residual divisible by common sizes
    if pr > 0 {
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 8.0;
            }
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Great: chain placement possible; reward proportional to how snugly
            score -= 25.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this leftover: penalize large dead space
            score += 0.35 * (pr as f64 - (pr % next_item_size.max(1)) as f64);
        }
    } else {
        // Last item: any fit is fine, prefer tightest
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly, more so when
    // fragmentation is low and mean residual is healthy.
    if bin_residual == bin_capacity {
        let healthy = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 35.0 + 45.0 * healthy;
        // Late in the stream, opening new bins is more acceptable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Mild pressure to consolidate across many open bins
    score += 0.5 * open_bins_count as f64;

    // Slight preference for bins whose residual is above the mean (keeps
    // large-capacity bins available for big future items)
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Modulo threshold on item size: awkward sizes (prime-ish / non-decade)
    // leave uglier gaps, so prefer bins that absorb them with small leftover
    if item_size % 10 != 0 && pr < 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space weight grows as the gap becomes too small for typical items.
        let dead_threshold = 12.0; // below this, gap is nearly unusable (min item size)
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Non-linear penalty: tiny gaps are catastrophically bad.
        if post_residual <= 3 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving a gap that can fit the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Post-residual too small for next item: dead-space pressure.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bins pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 30.0;
    } else {
        // Mild penalty scaling with number of open bins to consolidate.
        score += (open_bins_count as f64).ln() * 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins get filled first, keeping large residuals flexible).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for opening a new bin early vs late in the stream
    // is neutral; but penalize new-bin candidate slightly so it only wins
    // when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Progress-based dead-space tolerance: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus: strongly subtract when next item fills this bin exactly.
        score -= 40.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0).powi(3);
        // Penalize leaving residual that is *just* below the next item size (dead space).
        if (post_residual as i64) < (next_item_size as i64) && post_residual > 0 {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
        // Exact fit for the next item: huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score += 10.0;
    }

    // Reward using bins that are already relatively empty (below mean residual),
    // keeping fuller bins available for future large items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of open bins exist (bin consolidation).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual very small), allow new bin.
        if post_residual == 0 {
            score -= 45.0;
        }
    }

    // Progress-aware scaling: early in the stream, be more conservative about
    // fragmenting bins; later, prioritize immediate waste minimization.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Discourage leaving tiny unusable residuals (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to typical small item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0; // nearly perfect fill
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * (next_item_size as f64);
        } else {
            // Penalize leaving a gap that is useless for the next item,
            // scaled by how badly it misses.
            let gap_waste = (next_item_size - post_residual) as f64;
            score += 0.35 * gap_waste.min(40.0);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score -= 40.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    } else if fitting_bins_count > 1 {
        // With several options, prefer the emptiest fitting bin (best consolidation).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    // or the stream is early with few bins open.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -100.0 // must open a new bin
        } else {
            // Compete with existing bins: penalize opening unless existing fits are poor.
            let poor_fit = (fitting_bins_count as f64) * (1.0 - fit_ratio);
            25.0 + 0.5 * open_bins_count as f64 - 10.0 * poor_fit
        };
        score += desperation;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 30.0 * (1.0 - t);
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // placements that drain large residuals.
    score -= 0.05 * mean_residual * t;

    // Mild time-horizon damping: late in the stream, favor tightness even more.
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits, with non-linear (quadratic) waste penalty.
    let mut score = post + (post / cap).powi(2) * cap * 0.5;

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    score *= 1.0 + 0.35 * progress * (post / cap);

    // Reward filling bins when many bins are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64).ln_1p();
    score -= 0.6 * open_pressure * (1.0 - post / cap);

    // Prefer bins whose residual is close to the mean residual (balance).
    score += 0.25 * ((post - mean_residual) / cap).abs();

    // Lookahead coupling: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        if post >= nx {
            score -= 3.0 * (1.0 - gap / cap);
        } else {
            // penalize residuals that are just barely too small for next item
            score += 1.5 * (1.0 - gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: penalize opening a bin mildly; discount the penalty when
    // no open bin fits well (item is large relative to residuals) or stream is early.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 6.0 - 3.0 * (1.0 - post / cap) - 2.0 * progress;
        score += new_bin_penalty.max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small harmonics) are preferred.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -60.0 // perfect fit: strongly favored
    } else if pr % 10 == 0 {
        -8.0 * (pr as f64 / 10.0).min(3.0) // coarse harmonic leftover, reusable
    } else if pr % 5 == 0 {
        -3.0
    } else if pr < 10 {
        25.0 // dead space below the smallest useful quantum
    } else {
        0.0
    };
    score += class_penalty;

    // Coupling with lookahead: if next item fits the leftover, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0; // exact harmonic pair
        } else if next_item_size <= pr {
            let waste_after_next = pr - next_item_size;
            score -= 30.0 - waste_after_next as f64 * 0.4;
        } else {
            // leftover too small for the next item: penalize proportionally
            score += ((next_item_size - pr) as f64).min(40.0) * 0.6;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0 + 0.3 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer using it
    // only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
    } else {
        // Prefer fuller bins: compare against mean residual of open bins.
        let fullness = (bin_residual as f64) / cap;
        score -= 15.0 * fullness;
        if (bin_residual as f64) > mean_residual + 1e-9 {
            score += 5.0; // relatively emptier bin: mild penalty
        }
    }

    // Late in the stream, tighten packing (fewer chances to amortize bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill;
        // Penalize residual that cannot accommodate even the smallest future item.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead: reward residual that can host the next item, penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; acceptable only if
        // existing fits are poor (their dead-space penalties dominate).
        score += 55.0 + 10.0 * pressure;
    } else {
        // Favor bins with residual close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev * (1.0 + 0.5 * pressure);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (chain fill).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        // Perfect chain match: strong reward.
        if gap < 1.0 {
            score -= 25.0;
        } else if post >= nxt {
            // Next item fits into this bin's residual: reward proportionally to tightness.
            let tight = 1.0 - gap / bin_capacity as f64;
            score -= 18.0 * tight * tight;
        } else {
            // Next item would NOT fit here: penalize leaving residual that is
            // neither zero nor usable, scaled by how much is wasted.
            let waste = nxt - post;
            score += 8.0 * (waste / bin_capacity as f64);
        }
        // Bonus if post_residual exactly equals next item (perfect 2-chain).
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual after
    // placement is below the current mean (compacting the average).
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post - mean_residual) / mean_residual;
        score += 6.0 * rel;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize new-bin candidate unless the fit is exceptional or few bins open.
    if bin_residual == bin_capacity {
        let is_good_chain = next_item_size > 0 && post_residual >= next_item_size
            && (post_residual as f64 - next_item_size as f64).abs() < 2.0;
        if is_good_chain {
            score -= 5.0;
        } else {
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Dead-space penalty: residuals too small for the minimum item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild stream-progression term: early on, be slightly more willing to
    // open bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * (post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: baseline cost of opening a bin.
        score = bin_capacity as f64 * 0.92;
        // Slightly cheaper to open a new bin early in the stream (more future use).
        score -= (1.0 - progress) * 6.0;
        // If the next item fits into the fresh bin's residual, opening is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // If many bins can already fit the item, opening yet another is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    } else {
        // Reward placements whose leftover can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 9.0;
        }
        // Perfect or near-perfect fill gets a strong bonus.
        if post_residual == 0 {
            score -= 20.0;
        } else if post_residual < 10 {
            score -= 10.0;
        }
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // Penalize bins whose residual is far below the mean (fragmented bins),
        // unless this placement cleans them up.
        if (bin_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
            score += 5.0;
        }
        // Mild late-stream pressure to consolidate into existing bins.
        score += progress * 3.0;
        // Penalize leaving dead space proportional to how unusable it is
        // (leftover smaller than the smallest plausible item).
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex to punish mid-range waste
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr) * 4.0);

    // Non-linear polynomial coupling with stream progress
    let poly = 3.0 * progress * progress - 2.0 * progress * progress * progress; // smoothstep in [0,1]
    score += poly * (pr - mean_residual) * 0.35;

    // Early stream: prefer tight fits (low post residual) less aggressively,
    // late stream: strongly prefer tight fits
    score -= (1.0 - poly) * (item_size as f64 / cap) * 12.0;
    score -= poly * (item_size as f64 / cap) * 30.0;

    // Last-chance bin bonus (avoid opening new bins when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * poly;
    }

    // Penalize leaving residual close to but below next item (dead space)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score -= 8.0 * (gap / cap) * (1.0 - gap / cap) * 4.0 * (1.0 - poly);
        }
        if next_item_size as f64 > pr && pr > 0.0 {
            score += 6.0 * poly; // unusable for next item, mild penalty late
        }
    }

    // Many open bins: discourage spreading; few open bins: encourage filling
    let oc = open_bins_count as f64;
    score += (oc / (oc + 4.0)) * norm_pr * 20.0 * poly;

    // New-bin candidate: neutral-ish baseline with progress-dependent reluctance
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * poly - 5.0 * (1.0 - poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: tight fits (small leftover) rewarded hard
    let harmonic_class = post_residual / 10;
    score += match harmonic_class {
        0 => -4.0,              // near-perfect fit (0..10 left)
        1 => -2.0,              // good fit
        2 => 0.0,               // neutral
        3 => 1.5,               // mediocre
        4 => 3.0,               // poor
        _ => 4.5 + (harmonic_class as f64 - 5.0) * 0.3, // wasteful
    };

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: reward if the next item can also fit here (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain quality: smaller next item fits more easily, mild extra reward
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else {
            // dead space for the known next item: penalize by the gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter bins via mean-residual contrast
        score += (mean_residual - bin_residual as f64) * 0.08;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // no open bin fits: opening a new bin is mandatory
            score -= 1000.0;
        } else {
            // discourage opening a new bin when alternatives exist,
            // more strongly early in the stream (keep bins consolidatable)
            score += 18.0 + 12.0 * (1.0 - progress);
        }
    }

    // Mild pressure to fill bins when many are open
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can't hold even the smallest plausible
    // next item are pure waste — penalize them heavily.
    let min_useful = 1u32;
    if post_residual < min_useful {
        score += 1000.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space relative to what the lookahead item could use:
    // a gap smaller than next_item_size is unusable for the immediate future.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Reward gaps that exactly or nearly fit the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * f64::exp(-slack / 4.0);
        }
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= 10.0 * f64::exp(-(post_residual as f64) / 5.0);

    // Open-bin pressure: discourage spreading across many bins unless the fit is great.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the current bin would leave a large,
    // awkward residual or when few bins fit the item.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score = bin_capacity as f64 - 5.0;
        // Prefer a new bin when existing fits are poor (many contenders means decent fits exist).
        score += 3.0 * fitting_bins_count as f64;
        // If this bin would be the only fit, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, avoid opening new bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild alignment with mean residual state: bins far from mean residual are
    // slightly penalized (keeps bin states homogeneous for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits tightly but not perfectly -> moderate reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    }
    // Next item would NOT fit here: penalize leaving a residual that strands space.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Prefer bins whose residual is already below mean (tight bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when few/no good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_tight = mean_residual < item_size as f64 * 0.5;
        if pressure > 0.0 && mean_tight {
            score -= 55.0;
        } else {
            score += 45.0;
        }
    }

    // Mild phase bias: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let pr = post_residual as f64;
    score -= (cap - pr) / cap * (cap - pr) / cap * 30.0;

    // Penalize dead space that no typical item can use.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny sliver = wasted capacity
    }

    // Last-chance bin: strongly favor using it, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward;
    // if next item cannot fit but could fit a fresh bin, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 + 10.0 * (1.0 - (pr - nx) / cap);
        } else if bin_residual != bin_capacity && nx > pr {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);
    score += pressure * (2.0 + 3.0 * progress);

    // New-bin candidate: only attractive when existing residuals are poor
    // (item leaves large unusable gap everywhere).
    if bin_residual == bin_capacity {
        let gap_penalty = if pr > 0.0 && pr < 15.0 { 40.0 } else { 0.0 };
        score += 12.0 + pressure * 4.0 + gap_penalty;
    } else {
        // Mild reward for keeping bins ordered by fill level.
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
    }

    // Late stream: tighten packing further.
    score -= (1.0 - progress) * 0.0 + progress * 5.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, scaled non-linearly (wasted space hurts more when small)
    let mut score = post * (1.0 + 0.8 * (1.0 - post / cap).powi(3));

    // Smooth coupling of post_residual with stream progress:
    // late in stream, tight fits (small post_residual) are rewarded more aggressively
    let tight = (1.0 - post / cap).powi(2);
    score -= 30.0 * progress * tight;
    score += 12.0 * (1.0 - progress) * (post / cap).powi(2);

    // Reward near-perfect fits smoothly via quartic of post_residual
    score -= 0.15 * (cap - post).powi(4) / cap.powi(3);

    // Dead-space penalty if post_residual is too small for typical future items
    let too_small = ((40.0 - post) / 40.0).max(0.0);
    score += 25.0 * too_small.powi(2);

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * ((nxt - post) / cap).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - post / cap).abs();

    // New-bin candidate: neutral-ish baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarter classes of capacity
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score -= 12.0, // nearly full bin: excellent, minimal dead space
        1 => score += 2.0,  // 25-50 residual: moderate dead space
        2 => score += 5.0,  // 50-75 residual
        _ => {}             // bin barely used
    }

    // Modulo-10 residue: small post_residual classes are valuable
    let m = post_residual % 10;
    score -= (10 - m) as f64 * 0.15;

    // Reward tight fit with lookahead: next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving residual that next item cannot use well
    if next_item_size > 0 && next_item_size > post_residual {
        // dead space until future items; scale by how far off
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Integer-division threshold: residual divisible by common item sizes
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin useful for the near future too
        }
    }

    // Progress-aware mild pressure toward consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Prefer bins below mean residual (consolidate into emptier bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 25.0;
    } else if post_residual > 60 {
        score += 10.0; // large residual is fine, mild penalty to prefer tighter fills
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open bins pressure: discourage spreading across many bins late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight penalty for using a fresh empty bin (its residual == capacity).
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin residual after placement exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual can still hold the next item: mild reward proportional to slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * ((post_residual - next_item_size) as f64).min(30.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot hold the next item: penalize proportionally.
        let waste = post_residual as f64;
        score += 8.0 + 0.5 * waste;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize slightly so it's chosen only when
    // open bins are truly bad fits, but keep it competitive for large items.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.1 * item_size as f64;
    }

    // Late in the stream, consolidate harder (fewer wasted residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual waste, especially when it's unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Perfect chaining: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no open bin fits well or state is crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
        let pressure = mean_residual < item_size as f64 * 1.2;
        if fitting_bins_count > 1 {
            score += 60.0; // open bins exist that fit, prefer them
        }
        if crowded && pressure {
            score -= 35.0; // opening fresh bin is fine when state is bloated
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can absorb a pair
        }
    }

    // Time-horizon scaling: later in the stream, waste matters more (fewer chances to fill gaps)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Global residual coupling: penalize bins far above mean residual (fragmenting the pool)
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Tighter packing favored more strongly as stream progresses
    let tightness = (pr / cap).powi(2);
    score += 30.0 * progress * tightness;
    score -= 8.0 * (1.0 - progress) * (1.0 - tightness);

    // Reward exact / near-exact fills with smooth polynomial
    let fit_ratio = 1.0 - (pr / cap);
    score -= 15.0 * fit_ratio * fit_ratio * fit_ratio;

    // Lookahead coupling: penalize leaving residual that neither fits next item nor is tiny
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.15 * gap;
        if pr >= nx {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild penalty for spreading bins wide when many open
    score += 0.02 * open_bins_count as f64 * (1.0 - tightness);

    // Diverge from mean residual: prefer bins below mean residual (fuller bins)
    score += 0.1 * (mean_residual - pr).max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity remaining after placement

    // Harmonic classes: 0 (perfect), (0,1/8], (1/8,1/4], (1/4,1/2], (1/2,1]
    if post_residual == 0 {
        score -= 60.0; // perfect fill — best possible
    } else if pr <= c / 8.0 {
        score -= 30.0; // small dead space, nearly full
    } else if pr <= c / 4.0 {
        score -= 10.0; // acceptable quarter-class
    } else if pr <= c / 2.0 {
        score += 5.0; // mid-class: half-wasted potential
    } else {
        score += 12.0; // large leftover: bin barely used
    }

    // Modulo-arithmetic bonus on post_residual: multiples of 8 and 10 pair well
    // with common item sizes drawn from 1..=100.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 8 == 0 {
        score -= 4.0;
    }

    // Lookahead: reward if next item fits exactly or well into the post residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let next_fit = pr - ni;
            if next_fit == 0.0 {
                score -= 35.0; // chain: perfect second placement
            } else if next_fit <= c / 8.0 {
                score -= 18.0; // chain leaves small residue
            } else if next_fit <= c / 4.0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead
            score += 6.0 + (ni - pr) / c * 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (residual == capacity): only attractive when current bin
    // would leave a large awkward residue or no bin fits well.
    if bin_residual == bin_capacity {
        let awkward = pr > c / 2.0 && pr < c; // placing into new bin leaves full residual
        if awkward || (next_item_size > 0 && (next_item_size as f64) > pr && pr > c / 3.0) {
            score -= 20.0;
        } else {
            score += 30.0; // discourage opening new bins when fits exist
        }
    }

    // Pressure term: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 3.0 * (0.5 + progress);
    }
    if (mean_residual - pr).abs() < c / 8.0 {
        score -= 4.0; // prefer bins near the mean residual (balanced packing)
    }

    // Integer-division threshold: prefer post_residual in lower half of its class
    let q = post_residual / 12;
    if q <= 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are "dead".
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize post_residual that cannot fit the lookahead item while residual could.
    if next_item_size > 0 {
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 18.0;
        }
        if post_residual >= next_item_size {
            score -= 8.0; // preserves room for lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: prefer tighter (smaller-residual) bins as bin count grows.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins already below mean residual (compact bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin would leave large dead space
    // or nothing fits well; make empty bin moderately costly otherwise.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= dead_threshold || post_residual == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large leftover space: prefer tight fits.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - next).abs() < 1.0 {
            score -= 25.0; // perfect chain: next item fills this bin exactly
        } else if next <= pr {
            // partial match quality: how well the next item uses leftover
            let fill = next / pr;
            score -= 12.0 * fill;
        } else {
            // next item cannot fit here: leftover likely dead space
            score += 6.0 * (1.0 - pr / (bin_capacity as f64));
        }
        // bonus if next item leaves a near-perfect residual too (2-chain)
        if next <= pr {
            let pr2 = pr - next;
            if pr2 <= 5.0 {
                score -= 8.0;
            }
        }
    } else {
        // last item: strongly prefer minimal post_residual
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist and stream is early.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let urgency = (mean_residual / bin_capacity as f64) * (1.0 - progress);
        score += 20.0 + 30.0 * urgency;
        // still allow new bin if item is huge and mean residual is small
        if (item_size as f64) > mean_residual * 1.5 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progression through the stream.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large dead space more aggressively as the stream progresses
    // (late waste is harder to amortize).
    let dead_space_weight = 0.5 + 1.5 * progress;
    score += dead_space_weight * (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual as u64 >= next_item_size as u64 {
            let slack = post_residual as f64 - next_item_size as f64;
            if slack == 0.0 {
                score -= 15.0; // perfect two-item chain
            } else {
                score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here regardless; slight penalty for tight leftover
            // that is likely to become dead space.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Global state coupling: if mean residual is high, prefer bins below the mean
    // (consolidate toward emptier bins to preserve large gaps elsewhere).
    if bin_residual as f64 > mean_residual {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.03 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits poorly in all open bins or there are no open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else if fitting_bins_count == 0 {
            score -= 25.0; // no open bin fits; new bin is required
        } else {
            // Opening a new bin wastes the residual of existing bins;
            // penalize proportionally to how much capacity would be abandoned.
            score += 0.15 * mean_residual * (open_bins_count as f64).sqrt();
            // Early in the stream, keeping options open is cheaper.
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins with residuals that are "nice" divisors
    // (residuals near multiples of common item sizes 10..80 reduce future waste).
    let r = post_residual as f64;
    let nearest_multiple = (r / 10.0).round() * 10.0;
    score -= 1.5 * (1.0 - (r - nearest_multiple).abs() / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual normalized, penalized non-linearly.
    let post_norm = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 30.0 * (1.0 + progress);

    // Smooth polynomial coupling: residual before placement interacts with progress.
    let res_norm = bin_residual as f64 / bin_capacity as f64;
    score += res_norm * res_norm * 10.0 * (1.0 - progress);

    // Lookahead: bonus if next item fits well in the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - slack * slack);
    } else if next_item_size > post_residual {
        score += 5.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate handling: make empty bin attractive only when it seems worthwhile.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early, expensive late.
        score = 40.0 + 60.0 * progress - (mean_residual - post_residual as f64).abs();
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty proportional to open bins to discourage bin proliferation.
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced use).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands create discrete affinity levels.
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Perfect fit (zero waste) heavily rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    } else if post_residual > 40 {
        score += 12.0; // large dead space penalized
    }

    // Integer-division dead-space class: post_residual that cannot host any
    // plausible next item (>=1) is waste; but tiny residuals are fine.
    let dead = post_residual < next_item_size && next_item_size > 0;
    if dead {
        // Penalize proportionally to how much of next item cannot fit,
        // but soften if this bin was a last-chance bin.
        let waste = (next_item_size - post_residual) as f64;
        let last_chance = fitting_bins_count == 1 && bin_residual != bin_capacity;
        score += waste * if last_chance { 0.15 } else { 0.6 };
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item (chain fit).
        let chain = post_residual - next_item_size;
        score -= (chain.min(30)) as f64 * 0.4;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., few fitting bins or item is large relative to mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 1.15 && fitting_bins_count <= 1);
        if tight {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else {
            score += 45.0 + open_bins_count as f64 * 1.5;
        }
    }

    // Slight preference for fuller bins (lower residual) when many bins open.
    score += mean_residual * 0.05;
    score -= (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = wasted space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual < 30 {
        score += 15.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Reward using a tight bin (small residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    // Pressure from number of open bins: discourage opening new bins when many open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: favor bins whose post-residual still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Stream progression: tighten behavior later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: penalize adding to already-loose bins.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item closes this bin
        } else if post_residual >= next_item_size {
            // next item fits, reward proportional to how much remains after
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * chain_left;
        } else {
            // next item won't fit here; penalize dead space that blocks it
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Reward exact fill (bin closed now)
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless item is huge relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 70.0 * tightness;
        // opening a new bin is fine if it will absorb the next item too
        if next_item_size > 0 && (next_item_size + item_size) as f64 <= bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Contextual coupling with mean residual: prefer bins near mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in stream: be pickier about waste; late: just close bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
