pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;

    // Non-linear polynomial coupling: penalize mid-range waste more than extremes
    score += 12.0 * (x * (1.0 - x) * 4.0 - 0.5).abs() * cap * 0.1;

    // Stream progress coupling: late in the stream, tighten packing (favor small residuals more)
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 8.0 * progress_weight * x * x * cap * 0.05;

    // Reward tight fits with lookahead synergy
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 + 5.0 * (1.0 - ((next_item_size as f64 - pr).abs()) / cap);
    } else if next_item_size > 0 {
        score += 2.0 * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New bin candidate: prefer only when existing residuals are small
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * mean_residual - 10.0 * t;
    }

    // Open bins pressure: many open bins -> discourage spreading
    score += (open_bins_count as f64).ln().max(0.0) * x * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions.
    // Residuals that are "nice" (multiples of common item sizes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals divisible by small harmonic steps (10, 20, 25, 50).
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    // Penalize awkward dead space: small but nonzero residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // Harmonic class of the double-placement leftover.
            if leftover % 10 == 0 { score -= 8.0; }
            score += leftover as f64 * 0.3;
        } else {
            // Next item cannot follow here; slight penalty scaled by overshoot class.
            let over = (next_item_size - post_residual) % 20;
            score += over as f64 * 0.5;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when current residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs() / cap;
        // Open new bin if mean residual across bins is low (existing bins nearly full).
        score = cap - 10.0 * fragmentation - 20.0 * (1.0 - progress) * (mean_residual / cap);
        if item_size >= 50 {
            score -= 8.0; // large items like fresh bins
        }
    }

    // Mild preference for tighter bins overall.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harder.
    // A residual gap is "dead" if no plausible future item (>=1, up to 100)
    // can use it well; small nonzero post_residuals are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Perfect fit reward: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer compacting into
    // existing bins rather than spreading; with few bins, allow spreading.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += bin_pressure * post_residual as f64 * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item would fit into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // creates gap that next item cannot use
        }
    }

    // Mean residual coupling: if this bin is much tighter than average,
    // prefer filling it (balance residuals across bins).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.05;
    }

    // New-bin candidate handling: a fresh empty bin should only win when
    // no existing bin offers a decent fit. Penalize it mildly so tight
    // existing fits win, but not so much that poor fits beat it.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If current item nearly fills a whole bin, opening new bin is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }

    // Penalize leaving a small dead gap the next item can't use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Mild reward if next item can still fit in the post residual
    if next_item_size > 0 && post_residual >= next_item_size && next_item_size > 0 {
        score -= 10.0;
    }

    // Prefer tighter bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New empty bin candidate: penalize unless few bins fit the item
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let base = 80.0;
        let relief = if fitting_bins_count > 0 { (fitting_bins_count as f64).min(5.0) * 25.0 } else { 0.0 };
        score += base + relief - (fitting_bins_count as f64) * 10.0;
        // If next item is large and nothing fits well, opening fresh is okay
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Slight pressure early vs late in stream to consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space (< 10) slightly, since it's unusable for most items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 5.0;
        } else if (post_residual as i64) > 0 && (next_item_size as i64) > (post_residual as i64) {
            // Next item won't fit here; penalize leaving awkward residual.
            let gap = (next_item_size as f64) - (post_residual as f64);
            if gap < 10.0 {
                score += 4.0;
            }
        }
    }

    // Time horizon: late in the stream, consolidate into existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    let mean_res_norm = mean_residual / (bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * mean_res_norm;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream with many open bins, opening new bins is worse.
        score += 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let t = progress;

    // Base: reward small post_residual, with progress-dependent curvature.
    score = pr - 30.0 * prn * (1.0 - prn) * (0.5 + t);

    // Tight fits are increasingly valuable as the stream progresses.
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * t);

    // Penalize dead space: post_residual too small to ever be useful,
    // penalized more strongly early in the stream (long future).
    let dead = if next_item_size > 0 { (post_residual < next_item_size) as i32 as f64 } else { 0.0 };
    score += dead * (8.0 + 20.0 * (1.0 - t));

    // Lookahead: reward bins that leave room for the next item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (gap / bin_capacity as f64) * (1.0 - t);
        } else {
            score += 4.0 * (-gap / bin_capacity as f64);
        }
    }

    // Last-chance bin bonus: avoid opening new bins when few fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.5 * open_bins_count as f64 * t * t;

    // New-bin candidate: prefer it only when residuals are tight late.
    if bin_residual == bin_capacity {
        score = pr + 18.0 - 14.0 * t - 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Reward near-perfect fills (post_residual in small harmonic classes).
    if post_residual <= eighth {
        score -= 12.0;
    } else if post_residual <= quarter {
        score -= 5.0;
    }

    // Penalize dead space in the awkward middle band (post_residual % 10 in 1..4).
    let m = post_residual % 10;
    if m >= 1 && m <= 4 {
        score += 6.0 + (4 - m) as f64;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= eighth {
                score -= 8.0;
            }
            score += (nxt_post as f64) * 0.05;
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted potential.
            score += ((next_item_size - post_residual) as f64) * 0.03;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * (mean_residual / c);
        score += 8.0 - congestion.min(8.0);
        score -= (item_size as f64) * 0.1;
    }

    // Mild spread control: avoid bins far below mean residual (fragmentation risk).
    let dev = (bin_residual as f64) - mean_residual;
    if dev > 0.0 {
        score += dev * 0.02;
    }

    // Stream progression: late in stream, tighten packing (prefer tight fits more).
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= progress * 3.0 * (1.0 - pr / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=15) are heavily penalized.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }
    // Mid-range gaps (16..=30) mildly penalized since few items fit them.
    if post_residual > 15 && post_residual <= 30 {
        score += 12.0 * (1.0 - (post_residual - 15) as f64 / 15.0);
    }

    // Reward tight fits (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 40.0;
    } else if item_size as f64 / bin_capacity as f64 > 0.7 {
        score -= 10.0; // placing large items is generally good
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 25.0 + 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Slight preference for bins with larger residual among open bins.
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead synergy: if next item fits the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.2 * (post_residual - next_item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // perfect lookahead match bonus
            let match_err = (post_residual as f64 - next).abs();
            score -= 30.0 * (1.0 - match_err / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize proportionally to leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Penalize residuals that are small but unusable (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Compare post residual to mean residual: below-mean leftovers are efficient
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Early in stream: encourage consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Slight penalty for opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space: post_residual too small for any future item (min size 1).
    if post_residual > 0 {
        score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0).min(1.0));
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Wasted residual relative to the lookahead item.
        score += 6.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when current bins are poor.
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        // Early in the stream, opening bins is cheap; later it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 + 30.0 * progress;
        if mean_residual > item_size as f64 {
            score += 15.0; // existing bins have room; discourage new bin
        }
        if avg_fill < 40.0 {
            score += 10.0;
        }
    }

    // Prefer filling bins that are already well-used (larger item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Mild penalty when many bins are open and mean residual is high (fragmentation pressure).
    if open_bins_count > 3 && mean_residual > 50.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - 0.5 * norm_pr * progress;
    score += 40.0 * poly;

    // Penalize dead space more as stream progresses
    score += 30.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: avoid opening new bins when only this bin fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual can still fit the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Mild penalty coupling with number of open bins and mean residual
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: the fuller the bin becomes, the better.
    score -= 45.0 * (1.0 - post / cap);

    // Dead-space penalties: residuals too small to hold any plausible item.
    if post > 0.0 && post < 10.0 {
        score += 30.0;
    } else if post < 20.0 {
        score += 12.0;
    }

    // Harmonic classes: residuals that are multiples of 10 are "clean" slots
    // (many item sizes pair well with them); awkward remainders get penalized
    // proportionally to how non-decimal they are.
    let m = (post_residual % 10) as f64;
    if m == 0.0 {
        score -= 6.0;
    } else {
        score += 0.35 * m;
    }

    // Integer-division thresholds on post_residual: classify leftover capacity
    // into usable size bands (items are 1..=100, so bands of 25 matter).
    let band = post_residual / 25;
    score -= match band {
        0 => 0.0,          // nearly dead space
        1 => 4.0,          // small slot
        2 => 8.0,          // medium slot
        _ => 2.0,          // large slot, still flexible
    };

    // Lookahead (k=2): reward if the next item can also fit in the leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 18.0;
            // extra harmony: next item lands this residual on a clean class
            if ((post - nxt) as u32) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it before
    // opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        } else {
            // Prefer a new bin only when existing bins are fragmented
            // (mean residual low) and the current fit is poor.
            let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
            score += 14.0 - 18.0 * fragmentation;
            if post < 25.0 {
                score -= 10.0; // new bin leaves a large fresh residual
            }
        }
    }

    // Slight stream-progression tilt: late in the stream, favor consolidation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable for
    // typical items (sizes >= 1..100), so penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits (waste < 10 already handled; bonus for exact fit).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item can also fit in the resulting gap,
    // this placement is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild penalty, it is likely dead space.
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins instead of opening new ones.
    score -= 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): add a mild bias so
    // existing bins win unless they would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64;
    }

    // Slight progression awareness: late in the stream, tighten up more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powf(3.0);
    if post_residual == 0 {
        score -= 60.0; // exact fill is ideal
    }

    // 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // perfect chain fill
        } else if post_residual >= next_item_size {
            // good: next item can go here too
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize by wasted gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Compare against mean residual: bins already tight are more valuable targets.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still useful for lookahead
        }
    }

    // Late-stream urgency: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize small dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 5.0;
        }
    } else {
        // Last item: prefer most-filled bin.
        score -= 20.0 * fill;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Penalize opening a new bin unless the item is large relative to capacity
    // or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 45.0
            - 30.0 * item_frac
            - 20.0 * progress
            + 4.0 * open_bins_count as f64;
    }

    // Global state coupling: if mean residual is high, prefer bins that reduce
    // dispersion (post_residual close to mean_residual).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Mild time-horizon pressure: early in stream, be slightly conservative
    // (favor packing into existing bins); late, allow new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: residual wastefulness grows super-linearly
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Tight fits rewarded smoothly (small post_residual relative to item)
    let tightness = 1.0 - (pr / it).min(4.0) / 4.0;
    score -= 25.0 * tightness * tightness;

    // Lookahead synergy: next item fits snugly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        let smooth_fit = fit_quality * fit_quality * fit_quality;
        score -= 18.0 * smooth_fit * (1.0 - progress * 0.5);
        // penalize blocking next item
        if nx > pr {
            score += 10.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize smoothly unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste = 1.0 - (it / cap);
        let open_pressure = (open_bins_count as f64).ln() / (1.0 + (mean_residual / cap));
        score += 35.0 + 20.0 * waste * waste - 8.0 * open_pressure;
    }

    // Mild preference for bins below mean residual (balance residuals smoothly)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * dev.signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, and mid-range chunks) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> highly reusable leftover.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class B: post_residual divisible by 5 (but not 10) -> moderately reusable.
    else if post_residual % 5 == 0 {
        score -= 5.0;
    }
    // Class C: dead space (very small leftover) -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division thresholds: leftover big enough for typical small items.
    let small_item = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual >= small_item {
        // Lookahead fit: excellent, subtract proportional to how snugly next item fits.
        let snug = 1.0 - ((post_residual - small_item) as f64) / cap;
        score -= 8.0 + 10.0 * snug;
    } else if next_item_size > 0 {
        // Next item cannot fit here; mild penalty to deprioritize.
        score += 6.0;
    }

    // Perfect fit reward: post_residual == 0 is ideal closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity or no open bin fits well. Penalize opening new bins when the
    // stream is early (many items still to come) unless item is big.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / cap;
        score += 20.0 - 15.0 * size_frac - 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin preserves room: small discount.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let mean_dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * mean_dev;

    // Many open bins: encourage closing bins (low post_residual) to reduce spread.
    if open_bins_count > 4 {
        score += 0.05 * post * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 40 {
        score += 3.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open bins pressure: penalize spreading across many bins slightly.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow new bin for large items when mean residual is small (poor fits).
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        if mean_fit_gap > 30.0 && open_bins_count > 2 {
            score -= 18.0;
        }
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // relative to the bin and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: proportional to wasted capacity
        score = bin_capacity as f64 - item_size as f64;
        // If other bins fit the item, opening a new bin is a last resort unless
        // the fit in those bins would leave large dead space.
        if fitting_bins_count > 0 {
            // Penalize slightly so tight existing fits win; but if the item is
            // big, a fresh bin may still be preferable (score already high).
            score += 5.0;
        }
        // Lookahead: if next item is small, a fresh bin leaves room for it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = step_index as f64 / total_items as f64;
        score -= 20.0 * (1.0 - progress);
        return score;
    }

    // Reward near-perfect fits: post_residual close to zero is ideal.
    let pr = post_residual as f64;
    score = pr * pr / (bin_capacity as f64); // quadratic penalty on dead space

    // Aggressive 2-step lookahead: perfect match with next item is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Chain fit: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to combined fill.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize bins that strand the next item,
            // scaled by how much the next item overshoots.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    } else {
        // Last item: purely minimize dead space.
        score -= 30.0; // any placement is fine, favor existing bins
    }

    // Relative-to-mean-residual coupling: prefer placing into bins with residual
    // below the mean (tighter bins) to consolidate small residuals elsewhere.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.3 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using
    // it instead of opening a new bin (unless post_residual is huge).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual > bin_capacity / 2 {
            score += 20.0; // but not if it leaves a big awkward gap
        }
    }

    // Prefer bins that are already fairly full (small residual) generally.
    score += 0.1 * residual_f;

    // Mild penalty for spreading across many open bins when item is small.
    if item_size <= 30 && open_bins_count > 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(3.0) * 60.0;

    // Penalize unusable dead space: residual too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: penalize if next item fits current post_residual (good), else mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: this is the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only open a new bin when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > (bin_capacity as f64 - item_size as f64) * 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 30.0 + 20.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Mild preference for bins with residual below mean (consolidate emptier bins elsewhere).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits, amplified late in the stream
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit a plausible next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 12.0 * (ns - pr) / cap;
        } else {
            score -= 6.0 * (pr - ns) / cap;
        }
    } else {
        score += 5.0; // last item: prefer filling existing bins
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference for bins below mean residual (balance residuals)
    score += 0.05 * (pr - mean_residual);

    // Slight penalty for proliferating open bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space class: residuals that no item (min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 100.0; // perfect closure
    }

    // Harmonic class of post_residual: classify by integer division into
    // usable bands. Residuals in [20,50] are "gold" (fit most items),
    // [10,20) decent, [50,100) large slack.
    let band = post_residual / 10;
    match band {
        0 => { score += 0.0; }                      // 0..10 handled above
        1 => { score -= 15.0; }                     // 10..20: tight but usable
        2 | 3 | 4 => { score -= 25.0; }             // 20..50: gold zone
        5 | 6 => { score -= 10.0; }                 // 50..70
        _ => { score += 5.0; }                      // 70+: loose fit
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // strongly reward; if it nearly fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish score so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 - (post_residual as f64) * 0.0
            + if open_bins_count == 0 { -200.0 } else { 0.0 }
            + (fitting_bins_count as f64) * 2.0;
        // Penalize new bin more late in stream if open bins could still hold.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1) are pure waste.
    // Penalize any post_residual that is unusably small relative to the residual scale.
    if post_residual > 0 {
        // Dead space zone: post_residual smaller than a plausible next-item slice.
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            // Exponential blow-up as the gap approaches zero usefulness.
            let tightness = (dead_threshold - post_residual as f64) / dead_threshold;
            score += tightness * tightness * 40.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Moderate leftover gaps are good if they can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain-friendly placement
        } else if post_residual > 0 {
            score += 6.0; // gap too small for the known next item
        }
    }

    // Exact-fit flavor: residual equal to item size means bin becomes empty-ish.
    if post_residual as f64 > 0.0 && post_residual <= item_size / 2 {
        score += 4.0; // half-filled sliver, risky dead space
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance: strongly favor using this bin over opening a new one.
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // If this is a last-chance situation for an existing bin, new bin is bad.
        if fitting_bins_count <= 1 {
            score += 20.0;
        }
        // Late in the stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If item is large, new bin is more acceptable (less fragmentation risk).
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    // Slight pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (minimal dead space).
    let waste = post_residual as f64;
    score += 0.9 * (waste / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-gap / 6.0).exp(); // bonus when next item fits snugly
        // Penalize leaving residual the next item cannot use at all.
        if (post_residual as u32) < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Bonus if next item can still fit after this placement.
        if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Compare against mean residual of open bins: prefer bins that tighten the spread.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin unless current bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        // New bin: baseline cost; accept only if item is large relative to capacity
        // or existing residuals are all too small.
        score = bin_capacity as f64 - 0.6 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && (next_item_size as i64 - post_residual as i64).abs() <= 5 {
            score -= 10.0; // fresh bin pairs well with next item
        }
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.15 * (bin_capacity - bin_residual) as f64;

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in stream, prefer tight packing into existing bins;
    // late in stream, waste tolerance rises (fewer future items to serve).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residual too small to plausibly serve future items.
    // Minimum plausible item size ~ 1..100 unknown; use item_size as a proxy for scale.
    let dead_threshold = (item_size as f64 * 0.5).min(50.0);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (1.5 - progress);
    }

    // Lookahead: if the next item cannot fit in the post residual, this bin
    // becomes useless for the lookahead pair — penalize proportionally.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * (0.8 + 0.6 * (1.0 - progress));
        } else {
            // Bonus: bin can also absorb the lookahead item (chained fit).
            let slack = (post_residual - next_item_size) as f64;
            score -= slack * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // current fit is poor (large post residual or many competing fits exist).
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 40.0;
        // If item fits poorly anywhere (post_residual tiny => great fit),
        // opening new bin is less justified; if fit is bad, new bin gains appeal.
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score -= fit_quality * 30.0;
        // Many open bins with high mean residual => reuse them instead.
        score += (open_bins_count as f64).ln().max(0.0) * 8.0
               + (mean_residual / bin_capacity as f64) * 20.0;
        // Early in the stream, opening bins is cheaper (long horizon to fill them).
        score -= (1.0 - progress) * 15.0;
    }

    // Mild preference for bins with below-average residual (tighter bins),
    // keeping looser bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Tiny reward for exact-ish fits.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows with progress
    let waste_curve = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += 30.0 * waste_curve;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving a gap that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let gap_norm = gap / cap;
            score += 25.0 * gap_norm * gap_norm * (1.0 + progress);
        } else {
            // next item fits: reward
            score -= 15.0 * (1.0 + progress);
        }
    } else {
        // last item: strongly prefer filling residual
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bin bonus when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Slight preference for bins below mean residual (balance) with smooth term
    score += 5.0 * (pr - mean_residual) / cap;

    // Mild penalty for many open bins, encouraging consolidation
    score += 2.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space in small-modulo classes is
    // nearly unusable for typical item sizes, so penalize those classes.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Modulo-10 harmonic class: leftovers ≡ 1..9 (mod 10) waste at least that much.
    let m10 = pr % 10;
    if pr > 0 && m10 > 0 {
        score += m10 as f64 * 0.7;
    }
    // Modulo-5 refinement of the penalty.
    let m5 = pr % 5;
    if pr > 0 && m5 > 0 && m5 < 5 {
        score += m5 as f64 * 0.3;
    }

    // Integer-division thresholds: exact-fill classes are golden.
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr <= 5 {
        score -= 12.0; // near-perfect
    } else if pr <= 10 {
        score -= 5.0;
    }

    // Capacity fraction bands: leftover below 1/4 of capacity is dead space.
    if prf < cap * 0.25 {
        score += 8.0;
    } else if prf < cap * 0.5 {
        score += 2.0;
    } else if prf >= cap * 0.9 {
        score -= 3.0; // keeping a big bin nearly whole is fine
    }

    // Harmonic pairing with the lookahead item: reward leftovers that can
    // exactly host the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 18.0;
        } else if pr >= next_item_size && (pr - next_item_size) <= 10 {
            score -= 8.0;
        } else if pr < next_item_size && pr > 0 {
            score += 6.0; // leftover too small for the known next item
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin should only win when all open bins
    // would leave large, badly-classified residue.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when the stream is young.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = cap * 0.55 - 10.0 * (1.0 - progress);
        // If the next item fits in the fresh bin after this one, opening is
        // more attractive (harmonic stacking).
        if next_item_size > 0 && next_item_size <= pr.min(bin_residual) {
            new_bin_score -= 12.0;
        }
        if open_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score = score.min(new_bin_score) - 0.0;
        // Replace score entirely for the new-bin candidate evaluation.
        return new_bin_score;
    }

    // Mild diversity bonus: spreading load keeps mean residual balanced.
    score -= (mean_residual - prf).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual tightly matches the item (small relative slack).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that just barely fails to host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are ample.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 1.5;
        // But if this bin's residual deviates favorably from the mean (more room), use it.
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // New-bin candidate: keep it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // forced new bin
        } else if post_residual > 35 {
            score -= 5.0; // fresh bin keeps large usable space
        } else {
            score += 25.0; // prefer packing into existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits too: penalize leftover after both placements
            let double_left = post_residual - next_item_size;
            score += double_left as f64 * 0.5;
            if double_left == 0 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here: penalize small unusable post residuals
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize mildly unless few fitting bins or big item
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += 10.0 + pressure - (item_size as f64 - 50.0) * 0.1;
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference for tighter existing bins
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Penalize leaving large dead space, scaled by how full the bin already is.
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score += (post_residual as f64) * fill_ratio * 0.8;

    // Lookahead: if the next item fits exactly in the post-residual, reward; if next item
    // would leave this bin's post-residual unusable anyway, mild reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let leftover = post_residual as f64 - nxt;
            score -= 18.0 * (1.0 - leftover / cap);
        } else {
            // next item can't use leftover: dead space likely
            score += 6.0;
        }
    }

    // Last chance: only one bin fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins below mean residual (consolidate waste), above mean spread load.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: early in stream, be conservative with new bins; late, tolerate opening.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax as stream progresses.
        score += 30.0 * (1.0 - t) + (open_bins_count as f64) * 0.5;
    } else {
        // Existing bins get slight global-load discount.
        score -= t * 2.0;
    }

    // Fragmentation guard: avoid leaving residuals in the "awkard zone" (just below common sizes).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        score += 8.0 * (1.0 - pr / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly sub-linear to tolerate small leftovers.
    let mut score = pr.powf(0.85);

    // Smooth non-linear coupling: residual waste weighted by stream progress.
    // Late in the stream, dead space becomes more costly.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (smooth falloff).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns).max(0.0) / cap;
        let miss = (ns - pr).max(0.0) / cap;
        // Reward leaving exactly enough room for next item (tight lookahead fit).
        score -= 4.0 * (-fit_gap * 6.0).exp();
        // Penalize just-missing the next item (smooth hinge via tanh).
        score += 6.0 * miss.tanh() * miss;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Scarcity pressure: fewer fitting bins -> prefer consolidation into this one.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 3.0 * scarcity * (1.0 - norm_pr);

    // Mild pull toward mean residual to keep bin profiles balanced.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin, more so late in stream,
    // unless post_residual is large (fresh bin starts with full residual).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 5.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    } else if pr == 0.0 {
        // Perfect fit reward.
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Harmonic class of post_residual: dead space in low residue classes
    // (mod 10) is less reusable by typical item sizes (1..100 ints).
    let r = post_residual % 10;
    let class_penalty = match r {
        0 => -8.0,           // perfectly aligned residue, highly reusable
        1 | 9 => 6.0,        // awkward slivers
        2 | 8 => 3.0,
        5 => -3.0,           // half-of-ten residue, decent reuse
        _ => 1.0,
    };
    score += class_penalty * (post_residual as f64 / 10.0).min(3.0);

    // Lookahead: reward bins whose post_residual can host the next item exactly or nearly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 25.0; // chain a perfect pair
        } else {
            score -= 12.0 * (1.0 - next_fit_gap as f64 / 50.0).max(0.0);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; mild penalty proportional to overflow.
        score += 4.0 * ((next_item_size - post_residual) as f64 / 20.0).min(1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity (big items deserve fresh bins)
    // or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin for large items late in the stream; penalize otherwise.
        score += 45.0 - 40.0 * size_frac - 10.0 * progress;
        // If many bins are open with large mean residual, discourage new bins.
        score += (mean_residual / 20.0).min(6.0);
        // If no open bin fits, new bin is forced anyway; soften its score.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Small progress-based tie-breaker noise-free deterministic term.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer bins whose residual closely matches the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Open-bin pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 0.8;

    // Deviation from mean residual: avoid leaving this bin far off the average.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    }
    // Penalize if next item would be stranded in a tiny leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) * 0.6 + (mean_residual / bin_capacity as f64) * 10.0;
        score += 20.0 - crowd.min(20.0);
        if fitting_bins_count > 2 {
            score += 15.0; // plenty of alternatives; opening new bin is wasteful
        }
    }

    // Mild stream-progression term: tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + match_gap); // strong reward for tight 2-step fit
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain: bin sealed after next item
        }
        // Penalize leaving space that neither fits the next item nor is useful
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64; // dead space for next item
        }
    }

    // Penalize post_residual deviating from mean residual (favor balanced closures)
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev / (1.0 + mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Reward tight fits (small waste) more aggressively over time
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    // Mild penalty for wasting space in a fresh bin when many bins already open
    if bin_residual == bin_capacity {
        score += 2.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving little dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that would strand a nearly-fitting next item.
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += 12.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= 0.35 * bin_capacity as f64 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate logic: opening a fresh bin is attractive only when
    // the item is large relative to the bin or existing bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let pressure = (item_size as f64) / (bin_capacity as f64);
        let openness = if total_items > 0 {
            1.0 - (step_index as f64 / total_items as f64)
        } else {
            1.0
        };
        let attractiveness = 0.5 * frag + 0.7 * pressure + 0.3 * openness
            - if fitting_bins_count <= 1 { 0.4 } else { 0.0 };
        if attractiveness > 0.55 {
            score -= 25.0 * (attractiveness - 0.55);
        } else {
            score += 30.0 * (0.55 - attractiveness);
        }
    }

    // Mild penalty for scattering across many open bins when mean residual
    // is already low (consolidation pressure).
    if open_bins_count > 2 {
        score += 0.15 * (open_bins_count as f64).ln() * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Quadratic/cubic dead-space penalty on post_residual (smooth non-linear coupling)
    let post_norm = post / cap;
    score += 8.0 * post_norm * post_norm * cap;
    score -= 4.0 * post_norm * post_norm * post_norm * cap;

    // Tight fits (small post_residual) rewarded more as stream progresses
    let tight = 1.0 - post_norm;
    score -= tight * tight * (10.0 + 20.0 * progress);

    // Penalize bins whose residual is far from the mean residual (fragmentation avoidance)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Lookahead coupling: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap * cap * 0.1 + 4.0 * (1.0 - progress);
        } else {
            let use_ratio = nxt / post.max(1.0);
            score -= 6.0 * use_ratio * (1.0 - use_ratio);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation early)
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot class" the leftover falls in
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Perfect-fit reward: residual exactly divisible by common class sizes
    if post == 0 {
        score -= 50.0;
    } else if post % 10 == 0 {
        score -= 8.0;
    } else if post >= eighth && post % eighth == 0 {
        score -= 4.0;
    }

    // Penalize dead space: leftover too small for any plausible item (1..100 range, min item 1)
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    } else if post < quarter && post > 0 {
        score += 10.0 * (1.0 - post as f64 / quarter as f64);
    }

    // Reward leftovers that can host the next item (lookahead coupling)
    if next_item_size > 0 {
        if post >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
            // exact next-fit: post_residual == next_item_size is ideal
            if post == next_item_size {
                score -= 12.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into tight fits
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / cap);
    score -= 0.3 * pressure;

    // Tightness reward: fraction of bin used by this placement
    let tightness = item_size as f64 / cap;
    score -= 15.0 * tightness * tightness;

    // New-bin candidate: only attractive if this bin would waste a lot
    if bin_residual == bin_capacity {
        // opening fresh is penalized mildly; wins only when existing fits are terrible
        score += 18.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity - 1) {
            score -= 5.0;
        }
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 20) are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 - (post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits (waste <= 5).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: mild penalty scaled by gap.
        score += ((next_item_size - post_residual) as f64) * 0.5;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 2.0;
        // But if this bin is the only fitting option, opening a new bin
        // is better than a forced bad fit elsewhere.
        if fitting_bins_count <= 1 && post_residual < 20 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid opening a new bin.
        score -= 20.0;
    }

    // Mild global residual context: prefer bins tighter than the mean.
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Late-stream tightening: be pickier about dead space as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits snugly into post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            // next item fits: reward tight coupling
            let slack_after_next = post_residual as f64 - next;
            score -= 60.0 * (1.0 - slack_after_next / bin_capacity as f64);
            if slack_after_next == 0.0 {
                score -= 300.0;
            }
        } else {
            // next item does NOT fit: penalize leaving dead space that blocks it
            let overhang = next - post_residual as f64;
            score += 25.0 * (overhang / 100.0).min(1.0);
            // if post_residual is unusably small relative to typical items, penalize
            if post_residual < 10 {
                score += 40.0;
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins driven below mean
    // (concentrating waste into fewer bins) but avoid extreme fragmentation
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 1.0 {
            score -= 30.0 * (1.0 - ratio).min(1.0);
        } else {
            score += 15.0 * (ratio - 1.0).min(1.0);
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 80.0;
        // more attractive early in the stream or when many bins already open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * progress;
        // if the item is large, fresh capacity is valuable
        score -= 0.5 * item_size as f64;
        // if next item also large, fresh bin even more attractive
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Mild penalty for wasting a large bin on a small item
    score += 0.3 * (item_size as f64 / bin_residual.max(1) as f64) * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight superlinear penalty on waste.
    score += (post_residual as f64).powf(1.35) * 0.02;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, tighten discrimination between them.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item,
    // penalize bins that would strand dead space unusable by the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 0.10 * post_residual as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // If next item exactly fills post-residual, this is a perfect pairing.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small residuals are dead space; penalize leaving tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global state: when many bins are open and mean residual is high,
    // encourage consolidation into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly
        // (high mean residual relative to item, or few fitting bins).
        score = bin_capacity as f64 * 0.5;
        score += 0.5 * mean_residual;
        if fitting_bins_count <= 1 {
            score -= 70.0; // no real alternative -> opening a new bin is fine
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0; // existing bins have room; discourage new bin
        }
        score += 15.0 * (1.0 - progress); // early stream: slightly prefer opening bins
    } else {
        // Existing bin: mild preference to fill bins with larger residuals (balance load)
        // when the stream is late, to close out bins.
        if progress > 0.7 && post_residual < mean_residual {
            score -= 5.0;
        }
        // Prefer bins whose residual is close to item size (relative tightness).
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;
    }

    // Cap extreme negative scores to keep comparisons stable.
    if score < -200.0 { score = -200.0; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, with non-linear (quadratic) dead-space aversion
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling of residual aversion with stream progress:
    // later in the stream, waste matters more (compounding quadratic)
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits smoothly: item fraction of bin
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Penalize crowding when many bins are open and this residual is far below mean
    let mean_gap = mean_residual - pr;
    score += 5.0 * (mean_gap / cap).tanh() * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 20.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // next item won't fit: mildly penalize leaving awkward residual
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate: keep it neutral-ish; open new bins when residuals are tight
    if bin_residual == bin_capacity {
        score = pr + 15.0 * (1.0 - progress) - 10.0 * (mean_residual / cap).tanh();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are "usable" future slots; odd/tiny residues are dead space.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, strongly favored
    } else {
        let harmonic_bonus: f64 = if post % 50 == 0 {
            25.0
        } else if post % 25 == 0 {
            18.0
        } else if post % 20 == 0 {
            15.0
        } else if post % 10 == 0 {
            10.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead-space penalty: tiny unusable residues (integer-division threshold)
        let dead = post < 10;
        if dead {
            score += 40.0;
        }
        // Penalize residues too small for the smallest plausible next item class
        let half_class = post / 2; // integer division threshold
        if next_item_size > 0 && post < next_item_size && half_class < 10 {
            score += 20.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post && post % next_item_size == 0 {
            score -= 12.0;
        } else if next_item_size > post {
            score += 6.0; // next item won't fit here; keep residual flexible
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New empty bin candidate: make it moderately unattractive unless the fit
    // into open bins is terrible (large post_residual waste).
    if bin_residual == bin_capacity {
        score += 55.0;
        if post_residual > 30 {
            score -= 20.0; // big item: fresh bin is fine
        }
    }

    // Fraction-of-capacity coupling: prefer filling bins past halfway
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap_f;
    score -= fill_frac * 10.0;

    // Progress-based mild conservatism: late in the stream, keep bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be used again are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residual smaller than the lookahead item is likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Perfect fit: near-zero residual is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the empty-bin candidate gets penalized, encouraging consolidation).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    // Mild pressure to use existing bins when many are open.
    if bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    // Slight preference for bins with residual close to the mean (balanced packing).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Penalize leaving residual that cannot fit the next item (dead space risk).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to current residual (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Penalize residuals deviating from mean (prefer balancing usable space).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (mean_residual.min(100.0));
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Slight bonus for using bins with small residual (consolidation).
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Penalize dead space: residual that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Bonus if next item fits exactly-ish
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += gap as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no good fit exists among open bins
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 1.5;
        if fitting_bins_count == 0 {
            score -= 45.0; // nothing fits elsewhere -> open new bin
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer reusing bins over opening new ones
    score += (mean_residual - post_residual as f64) * 0.1;

    // Time horizon: early in stream, be conservative with open bins;
    // later, pack tighter
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = post * (1.0 - progress * 0.6) + (pr * pr) * cap * (0.3 + 0.5 * progress);

    // Penalize dead space that is too small for typical future items
    let dead = if post > 0.0 { (1.0 - pr).min(1.0) * (cap - post).max(0.0) * 0.0 } else { 0.0 };
    let small_gap_penalty = if post > 0.0 && post < 10.0 { (10.0 - post) * 2.0 } else { 0.0 };

    // Reward tight fits (small post_residual) more strongly early in the stream
    let tight_bonus = -1.0 * (cap - post).max(0.0) * (1.0 - progress) * 0.5;

    // Last-chance bin: strong reward to use it before opening a new bin
    let last_chance = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // Lookahead: if next item fits in the post residual, reward this placement
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= post { -4.0 } else { 0.0 };
    // If next item nearly fits, slight penalty for wasting the space
    let near_miss = if next_item_size > 0 && (next_item_size as f64) > post && (next_item_size as f64) - post <= 10.0 { 2.0 } else { 0.0 };

    // Prefer filling bins with below-average residual (balance avoidance of fragmentation)
    let mean_coupling = (mean_residual - post) * 0.05 * (0.5 + progress);

    // Slight penalty for opening new bins late in the stream when alternatives exist
    let new_bin_penalty = if bin_residual == bin_capacity { 3.0 + 6.0 * progress } else { 0.0 };

    base + dead + small_gap_penalty + tight_bonus + last_chance + lookahead + near_miss + mean_coupling + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    // Harmonic class of post_residual: dead space is worse when it cannot
    // accommodate typical small items. Classify via integer division thresholds.
    let class = post_residual / 10; // 0..10 harmonic classes
    let class_penalty = match class {
        0 => 0.0,                 // perfect fit
        1 => 4.0,                 // tiny dead space, nearly unusable
        2 => 8.0,
        3 => 6.0,
        4 => 3.0,
        5 => 1.0,                 // ~half capacity, still flexible
        6 => 2.0,
        7 => 4.0,
        8 => 6.0,
        9 => 5.0,
        _ => 0.0,                 // empty bin class
    };
    score += class_penalty;

    // Lookahead: reward bins whose post_residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // wastes the chain opportunity
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 20.0;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        } else if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0;
        }
        // discourage opening new bins late in the stream when bins exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    // Nudge toward bins tighter than the mean residual (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Fine-grained modulo tiebreak on post_residual to break symmetric classes
    // (favor residuals that are multiples of 5, common item-friendly sizes).
    if post_residual % 5 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are nearly worthless; penalize them heavily.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        // post_residual is unusable dead space -> big penalty added.
        score += (bin_capacity as f64) * 3.0;
    } else {
        // Reward small (but usable) residuals quadratically: tighter fits win.
        score -= 2.0 * ((bin_capacity as f64) - (post_residual as f64)).max(0.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 2.0;
    }

    // Dead-space pressure: penalize residuals that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // This bin becomes useless for the next item -> penalize.
            score += (next_item_size as f64) * 1.5;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Residual remains usable -> reward.
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // (penalize new-bin / low-fill candidates) to avoid bin proliferation.
    score += (open_bins_count as f64) * 0.75;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= bin_capacity as f64 * 1.5;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to typical residuals (poor fit elsewhere) or when
    // few bins are open. Give it a moderate base penalty.
    if bin_residual == bin_capacity {
        score += 5.0 + (item_size as f64) * 0.3 + (open_bins_count as f64) * 2.0;
        // If item is big relative to mean residual, new bin becomes attractive.
        score -= ((item_size as f64) - mean_residual).max(0.0) * 1.2;
    }

    // Slight late-stream conservatism: near the end, waste matters less,
    // so tighten fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base term.

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if gap < 1.0 {
            score -= 60.0; // perfect pairing: item + next item fill the bin
        } else if pr >= nxt {
            // next item can still fit here later; reward proportionally
            score -= 25.0 * (nxt / pr).min(1.0);
        } else {
            // post_residual too small for next item: dead-space penalty scaled
            // by how close it is to being useless (small leftover = wasted).
            let waste = 1.0 - (pr / nxt);
            score += 20.0 * waste;
        }

        // If post_residual matches next item AND next item fits with the one
        // after conceptually, prefer bins whose leftover is minimal overall.
        if gap < 1.0 && pr < 10.0 {
            score -= 15.0; // near-perfect closure of the bin
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: bins with residuals far below the mean are
    // "almost full" -> placing here consolidates waste. Reward them.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (mean_residual - res) / mean_residual; // >0 means tighter than mean
        score -= 10.0 * rel.max(-1.0).min(1.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 4 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should only win when no open bin gives a good fit, so penalize it
    // mildly, more so as the stream progresses (amortize bin cost early).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + 20.0 * progress + 5.0 * open_pressure;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual),
    // quadratic encouragement for very tight fits.
    if res < 20.0 {
        score -= 8.0 * (20.0 - res) / 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward leaving a residual that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.10 * next_item_size as f64;
    }
    // Penalize residuals that became too small to be practically reusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    let is_new_bin = bin_residual == bin_capacity;
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when existing fits are poor.
    // Penalty grows for small items (wasting capacity) and slightly early in the stream.
    if is_new_bin {
        score += 8.0 + 0.25 * item_size as f64 * (1.0 - 0.5 * progress);
    }

    // Prefer bins that are already more full than average (consolidate fragmentation),
    // scaled mildly by how many bins are open.
    let fullness_gap = (bin_capacity as f64 - bin_residual as f64)
        - (bin_capacity as f64 - mean_residual);
    score -= 0.10 * fullness_gap * (1.0 + open_bins_count as f64 * 0.02);

    // Global pressure: with many open bins, tightening fits matters more.
    score *= 1.0 - 0.01 * (open_bins_count as f64).min(20.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, normalized
    let mut score = post / cap;

    // Quadratic penalty for wasted space (dead space grows superlinearly)
    score += 0.35 * (post / cap) * (post / cap);

    // Tight fit reward: subtract when post_residual is small
    let tightness = 1.0 - (post / cap);
    score -= 0.6 * tightness * tightness * tightness;

    // Non-linear coupling: waste tolerance shrinks as stream progresses
    let urgency = progress * progress;
    score += 0.9 * (post / cap) * (post / cap) * urgency;

    // Lookahead coupling: reward leaving space that fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (post - nxt).abs() / cap;
        score += 0.25 * compat * compat;
        // exact-fit lookahead bonus
        if post >= nxt {
            let frac = nxt / post.max(1.0);
            score -= 0.4 * frac * frac;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 0.5 + 0.5 * progress;
    }

    // Penalize scattering across many open bins when residuals are large
    let mean_norm = mean_residual / cap;
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * mean_norm * mean_norm;

    // New-bin candidate handling: mildly penalize a fresh empty bin unless
    // the item is large relative to capacity (better to start fresh for big items)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 0.3 - 0.3 * (item / cap);
        // early in stream, fresh bins are cheaper
        score -= 0.2 * (1.0 - progress) * (1.0 - progress);
    }

    // Smooth cubic regularization on item size (prefer placing big items tightly)
    score -= 0.1 * (item / cap) * (item / cap) * (item / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class: how well post_residual aligns with capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    // Penalize residuals that fall into "dead zones" (small, unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Modulo classes on post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more likely reusable.
    let reusable = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 20 == 0) as f64 * 6.0
        + (post_residual % 25 == 0) as f64 * 5.0
        + (post_residual % 50 == 0) as f64 * 7.0;
    score -= reusable;

    // Integer division thresholds: post_residual bucketed by quarters.
    let quarter = post_residual / (bin_capacity / 4);
    match quarter {
        0 => score += 5.0,          // nearly full bin: good
        1 => score += 2.0,          // 25-50% residual
        2 => score -= 1.0,          // 50-75% residual
        _ => score -= 3.0,          // mostly empty
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving medium dead space.
        score += (post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only good when the item
    // is large or existing fits are poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.5
            + (1.0 - (step_index as f64).max(1.0) / (total_items as f64).max(1.0)) * 10.0;
        // Large items pack cleanly in fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 10.0 + pressure * 0.3;
        } else {
            score += 20.0 + pressure * 0.5;
        }
    }

    // Mean residual coupling: when open bins are generally empty, prefer them.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Moderately small gaps are less useful than mid-range gaps.
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness);

    // Penalize bins whose post_residual cannot host the lookahead item
    // while an alternative bin could combine them.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0;
        } else {
            score -= 5.0; // keeps room for the next item
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (new bin gets post_residual == capacity, so it
    // must be pushed up here).
    let pressure = open_bins_count as f64;
    score -= 3.0 * pressure / (1.0 + (bin_residual as f64 / bin_capacity as f64));

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild global trend: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below the mean residual (fills emptier bins, keeps
    // tighter bins available for small future items).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight packing (low post_residual).
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus: post_residual equals next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still hold next item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: bins tighter than average are attractive.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild penalty on new-bin candidate unless current bins are very full.
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 20.0 {
            score += 10.0;
        }
    }

    // Early stream: be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Penalize small dead space that nothing can use (items >= 1, so any residual
    // is technically usable, but tiny residuals are wasteful; reward moderate residuals)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much it consumes
            let consume = next_item_size as f64 / post_residual.max(1.0) as f64;
            score -= 80.0 * consume;
        } else {
            // next item won't fit here: slight penalty for leaving big gap
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Many fitting bins: mild penalty encourages spreading / diversity
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, be more selective (penalize wasteful bins);
    // late in stream, just pack anything that fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 25.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    // Global state coupling: penalize bins far from mean residual when many bins open
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev * (open_bins_count as f64 / (open_bins_count as f64 + 10.0));

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced late in stream or when open bins are crowded
        let crowd = mean_residual / bin_capacity as f64;
        let mut new_bin_cost = 120.0 - 60.0 * progress;
        if crowd < 0.25 && open_bins_count > 0 {
            new_bin_cost -= 40.0; // open bins nearly full, new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_residual {
            new_bin_cost -= 30.0; // big items coming: fresh bin useful
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let coupling = prn * prn * (1.0 - progress) + prn * progress * 0.5;
    score += coupling * 10.0;

    // Reward tight fits, more strongly as stream progresses
    let tight = 1.0 - prn;
    score -= tight * tight * (1.0 + progress) * 5.0;

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild penalty when many bins already open (encourage consolidation)
    score += open_bins_count as f64 * 0.05 * progress;

    // Align with mean residual: prefer bins close to the mean state
    score += (mean_residual - pr).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic class of the residual: residuals divisible into common
    // item-size classes (10..80 in steps) are more reusable.
    let pr = post_residual;
    let reusable = if pr == 0 { 0 } else {
        (10..=80).rev().filter(|&s| s <= pr)
            .map(|s| (pr % s == 0) as u32).sum::<u32>()
    };
    score -= 6.0 * reusable as f64;

    // Penalize dead space below the smallest plausible item (harmonic floor).
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does this placement leave room for the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Bonus scaled by how well the leftover matches the next item.
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack;
        } else {
            score += 10.0;
        }
        // Harmonic match: next item exactly divides the post residual.
        if next_item_size > 0 && pr % next_item_size == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would be badly wasted.
    if bin_residual == bin_capacity {
        let waste = (post_residual as f64) / bin_capacity as f64;
        score += 55.0 * waste; // empty bin starts neutral-ish; penalize if it would stay loose
        score -= 20.0 * (open_bins_count as f64).ln().max(0.0) * 0.0; // no-op guard
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins mid-stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * progress * 0.1;

    // Prefer bins whose residual is above the item's harmonic complement.
    let complement = bin_capacity.saturating_sub(item_size);
    if bin_residual >= complement {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // while exact fits (post_residual == 0) are strongly rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fill: always best
    } else if post_residual < 10 {
        // unusable dead space for typical items (>=10 in classic regime, but sizes 1..100):
        // penalize proportionally to how "orphaned" the gap is
        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 5.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement wastes space
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 150.0;
        // but if the best alternative leaves tiny dead space, opening a new bin is fine
        if post_residual == 0 {
            score -= 400.0;
        }
        // opening new bins becomes more attractive late in the stream when many bins are open
        score -= 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // (i.e., penalize new-bin creation more when open_bins_count is large)
    if bin_residual == bin_capacity {
        score += 3.0 * open_bins_count as f64;
    } else {
        // reward using bins whose residual deviates from mean (better consolidation)
        score -= 0.5 * (bin_residual as f64 - mean_residual).abs().max(0.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 250.0;
        } else if gap < 10 {
            score += gap as f64 * 20.0; // would create dead space next step
        } else {
            score -= 10.0;
        }
    }

    // Slight preference to fill fuller bins earlier in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 120.0; // perfect match for the next item
        } else if diff <= 10 {
            score -= 60.0 / diff as f64; // near match
        } else {
            // penalize wasted space that the next item cannot use
            score += (diff as f64) * 0.3;
        }

        // If next item cannot fit here after placement, slight penalty unless post_residual is tiny.
        if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Dead-space penalty: residuals below the minimum item size are unusable.
    if post_residual < 1 {
        score += 200.0;
    } else if post_residual <= 5 {
        score += 25.0;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of existing residuals.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins are tight or this is a bad fit situation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        // A new bin is attractive when mean residual is low (existing bins nearly full)
        // or when the item is large relative to typical residual.
        score = 60.0 + pressure * 50.0 - progress * 10.0 - (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // if the next item would also fit in a fresh bin alongside, slightly favor opening
            if next_item_size + item_size <= bin_capacity {
                score -= 15.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild preference for tighter bins overall relative to mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below next item is wasted.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // residual too small for the lookahead item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        } else {
            // residual can host the next item: reward
            score -= (post_residual as f64 - next_item_size as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for competing bins to keep spread
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Penalize opening a new bin when plenty of aggregate residual exists,
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual * open_bins_count as f64;
        score += waste * 0.08 - progress * 5.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items fit best in fresh bins
        }
        if next_item_size as f64 > post_residual as f64 && next_item_size > 0 {
            score += 3.0;
        }
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Slight preference for bins below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: dead space, amplified by smooth polynomial in progress
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    // Non-linear coupling: residual relative to capacity, cubic shaping
    let r_norm = pr / cap;
    score += 12.0 * r_norm * r_norm * r_norm * cap * 0.1;

    // Fit tightness reward: item filling bin fraction smoothly rewarded
    let fill = it / cap;
    score -= 10.0 * fill * fill;

    // Scarcity coupling: fewer fitting bins -> smooth bonus for using this one
    let fbn = fitting_bins_count as f64;
    score -= 8.0 / (fbn * fbn + 1.0);

    // Lookahead: penalize leaving residual too small for next item, reward usable residual
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        // smooth transition via difference ratio
        let gap = (nx - pr).abs();
        score += 0.35 * gap * (1.0 - usable * 0.9);
        score -= 0.15 * usable * (pr - nx).min(30.0);
    } else {
        // last item: strongly prefer zero residual
        score += 0.5 * pr;
    }

    // New-bin candidate handling: neutral residual, but penalize opening early / when fits exist
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score = pr + 14.0 * (1.0 - progress) + 6.0 / (fitting_bins_count.max(1) as f64);
        if nx > 0.0 && nx <= cap {
            score += 0.2 * nx;
        }
    }

    // Mean residual coupling: avoid diverging from fleet state, smooth quadratic
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / (1.0 + progress);

    // Open-bin pressure: many open bins -> prefer consolidation
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "friendly" residue classes (multiples of 10 / 25 / 50) are more
    // reusable, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Modulo-10 harmony: leftover divisible by 10 is ideal for integer-sized future items.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else {
        score += mod10 as f64 * 0.3;
    }

    // Modulo-25 harmony: quarter-capacity alignment is a strong reusable class.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer-division thresholds on post_residual:
    // - tiny leftovers (< 10) are dead space -> penalize.
    // - large leftovers are naturally good (already captured by base term).
    if post_residual < 10 {
        score += 8.0;
    }

    // Dead-zone band: leftovers in (40, 50) can only host the smallest items
    // relative to their size; slight penalty to push item elsewhere.
    if post_residual > 40 && post_residual < 50 {
        score += 2.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is a chain win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item leaves a multiple-of-10 residue too.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
            score -= 2.0;
        } else {
            // Next item cannot use this bin's leftover; mild penalty scaled
            // by how much capacity fraction is stranded.
            score += frac * 3.0;
        }
    }

    // Congestion modulation: with many open bins, prefer tight fits (low post
    // residual already does this); with few bins, opening new bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let congestion = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0).max(1.0);
    score += congestion.min(6.0) * 0.4 * (0.5 + progress);

    // New-bin candidate calibration: an empty bin has residual == capacity.
    // Base score there is `capacity` (100), which is naturally high; add a
    // mild extra penalty unless the current bin would strand a lot of space.
    if bin_residual == bin_capacity {
        // Opening fresh is attractive early or when item is huge relative to mean residual.
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        if mean_fit < 0.85 {
            score += 10.0; // keep item in existing bins when they fit reasonably
        } else {
            score -= 5.0; // poor fit anywhere -> fresh bin is fine
        }
    }

    // Exact-fill perfection: placing the item leaves zero residual.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < item_size {
        // gap smaller than current item is likely dead unless future items are tiny
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 40.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    score += 3.0 * open_bins_count as f64;

    // New-bin candidate: penalize unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But if the gap this item would leave elsewhere is dead space, new bin is fine.
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits in the post residual, reward leaving useful space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item does NOT fit in post residual but would fit elsewhere, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: if mean residual is high, prefer bins above average (consolidate).
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Late in stream: consolidate harder, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits with small slack: still good.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit in the leftover: penalize dead space, worse when tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 80.0 * (1.0 - waste);
    }

    // Tight fits are valuable: reward small post_residual when it's still usable.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver penalty
    }
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    }

    // Compare against mean residual: prefer bins that reduce dispersion.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Base new-bin cost; lowered late in stream or when few alternatives.
        score = 150.0 - 40.0 * progress - 10.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    let pressure = (open_bins_count as f64) / (8.0 + open_bins_count as f64);
    score -= 10.0 * fill * pressure;

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let mut penalty = 18.0;
        if fitting_bins_count > 0 {
            // worse if an existing bin fits well (post_residual small)
            penalty += 0.4 * post_residual as f64;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 15.0 * (1.0 - progress);
        // If mean residual is high, existing bins have room; discourage new bin.
        penalty += 0.1 * mean_residual;
        score += penalty;
    }

    // Mild time-horizon modulation: later in stream, prioritize consolidation.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress
    let t = progress * std::f64::consts::PI;
    score += 30.0 * (1.0 - (t).cos()) * norm_pr * (1.0 - norm_pr) * 4.0;

    // Penalize waste relative to mean residual state
    score += 0.15 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 + progress);
        } else {
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Mild penalty for many open bins with large residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it slightly unattractive unless item is large
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "nice" fractions
    // of capacity (0, cap/4, cap/3, cap/2) or exactly 0.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    if post_residual == 0 {
        score -= 25.0; // perfect fit, best outcome
    } else {
        let harmonic_bonus = match post_residual {
            r if r == quarter => 12.0,
            r if r == third => 10.0,
            r if r == half => 9.0,
            r if r % 10 == 0 => 6.0, // multiple of 10, easily reusable
            r if r < 10 => 0.0,      // dead space
            _ => 2.0,
        };
        score -= harmonic_bonus;
    }

    // Penalize tiny unusable dead space nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Harmonic pairing: does next_item_size divide or fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // chains perfectly to next item
        } else if post_residual >= next_item_size {
            let r2 = post_residual - next_item_size;
            if r2 == 0 || r2 == quarter || r2 == third || r2 == half || r2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here; slight penalty if it would fit nowhere else
            if fitting_bins_count <= 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - cap / 2.0).abs();
        // penalize new bin mildly; more when bins are large-residual (unfragmented)
        score += 20.0 + fragmentation * 0.3 - progress * 5.0;
    } else {
        // reward using bins whose residual is far below mean (consolidate)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Modulo-10 class coupling between item and residual
    if (bin_residual % 10) == (item_size % 10) && bin_residual >= item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual as i32 as f64) * 4.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit reward relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Dead space measured against capacity scale.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // If this bin is the last fitting bin, strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin residuals are poor for the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 40.0;
        // If next item fits in the post-residual, keep the current bin; penalize new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
        // When mean residual is large, opening a new bin wastes space.
        score += (mean_residual / bin_capacity as f64) * 30.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Reward placing into existing bins whose residual exceeds item by a comfortable margin.
        if post_residual >= 10 {
            score -= 10.0;
        }
        // Lookahead: if next item fits exactly into post_residual, bonus.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit: penalize wasted lookahead potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(60.0);
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * progress;
        if open_bins_count > 0 && post_residual <= 15 {
            score -= 30.0; // new bin still fine if item is large
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            score -= 2.0; // next item can also fit here: good chaining
        }
    } else {
        // Last item: just minimize post_residual; reward using existing bins.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so later in the stream
    // and when many bins are already open; relax early when consolidation room is scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // But if mean residual across open bins is small (fragmented), new bin is less bad.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
    }

    // Mild preference for bins below mean residual (balance residual distribution).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Slight reward for filling bins closer to full as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (item_size as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, smoothed by polynomial shaping.
    let mut score = pr;

    // Non-linear coupling: penalize residual quadratically more as stream progresses
    // (late stream: tight packing matters more; early stream: keep bins flexible).
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * fit_quality * (1.0 + progress);

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (-gap / 30.0) * (1.0 + progress);
    }

    // Last-chance bonus: sole fitting bin should be favored over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Mean residual dispersion: avoid creating residual far below the mean
    // (keeps bin population homogeneous, smooth quadratic penalty).
    let dev = (mean_residual - pr) / cap;
    score += 15.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly, but relax late in the stream
    // when many bins are already open (fragmentation risk grows).
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact quanta are valuable dead space
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Reward leaving post_residual in "usable" harmonic classes (multiples of 10/quarter)
    if post % 10 == 0 {
        score -= 6.0;
    }
    if post % quarter == 0 && post > 0 {
        score -= 8.0;
    }
    if post % eighth == 0 && post > 0 {
        score -= 3.0;
    }

    // Penalize awkward residuals: small nonzero leftovers are dead space
    if post > 0 && post < 10 {
        score += 15.0;
    } else if post > 0 && post < eighth {
        score += 8.0;
    }

    // Integer-division threshold on post_residual: mid-range residual is good
    let div_class = post / eighth;
    match div_class {
        0 => score += 10.0,          // tiny residual: nearly full bin, but dead space
        1 | 2 => score -= 5.0,       // sweet spot: 12..37 remaining
        3 => score -= 2.0,           // quarter residual
        4 => score -= 4.0,           // half residual: very reusable
        _ => score += 1.0,           // large residual: bin barely used
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 10.0;
            // exact fit for next item is a jackpot
            if next_item_size == post {
                score -= 12.0;
            }
            // harmonic match: next item divides residual evenly
            if post % next_item_size == 0 {
                score -= 5.0;
            }
        } else if post > 0 && next_item_size > post && next_item_size - post < 10 {
            score += 6.0; // next item barely misses: wasted potential
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (mean_residual / cap).max(0.05);
        score = cap as f64 * 0.55
            + congestion * 2.0
            - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= half && post_residual >= half {
            score -= 6.0; // fresh bin can host the next item too
        }
    }

    // Mean-residual coupling: prefer bins deviating favorably from the mean
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    score -= 0.05 * dev;

    // Prefer tighter (fuller) bins slightly, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - res_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Moderate dead space (hard to fill but not impossible) gets a graded penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening fills
    // rather than spreading; when few bins are open, slightly prefer reuse.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement strongly (chained perfect fit).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: the remaining gap is likely dead space.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Mean-residual coupling: if this bin is much tighter than average,
    // prefer filling it (consolidation), else keep it as a reservoir.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit (i.e., all fits would leave large dead space).
    if bin_residual == bin_capacity {
        // Base penalty so real bins with good fits are preferred.
        score += 60.0;
        // But if this is a late stream and open bins are fragmented,
        // opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
        // If many bins are open and mean residual is small (fragmented),
        // a fresh bin becomes more attractive.
        if mean_residual < (item_size as f64) {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residual is good, but penalize dead space below typical small-item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are safer bets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // but if the item is large relative to mean residual, new bin may be fine
        score -= 0.2 * item_size as f64;
    }

    // Late-stream pressure: consolidate as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish, slightly penalized so it's
    // chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Encourage using bins whose residual deviates below the mean
    // (consolidate small residuals into fewer bins).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Time horizon: early in stream, be pickier about tight fits;
    // late in stream, just fill anything to avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);
    score -= 5.0 * progress;

    // Many open bins: prefer filling existing ones harder.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) + 1.4 * x * x * (1.0 - progress);

    // Penalize large dead space quadratically, more strongly early in the stream
    score += 2.0 * x.powi(3) * (1.5 - progress);

    // Reward tight fits (small post_residual) with a smooth exponential term
    score -= (1.0 - x).powi(2) * 0.5 * (1.0 + progress);

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - x);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score += 0.6 * gap * gap - 0.5 * nx * (1.0 - x).max(0.0);
    }

    // Mild penalty for bin proliferation, smoothed with progress
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Slight preference toward bins below mean residual (balance residuals)
    score += 0.3 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: dead space in (0..10) is nearly unusable.
    let gap_class = post_residual / 10;
    let gap_mod = post_residual % 10;
    match gap_class {
        0 => {
            // gap 0..9: dead space penalty, worst at gap 0 (perfect) is good, tiny gaps bad
            if post_residual == 0 {
                score -= 60.0; // perfect fit reward
            } else {
                score += (10 - gap_mod) as f64 * 4.0;
            }
        }
        1 => { score += gap_mod as f64 * 0.5; }        // gap 10..19: mildly usable
        2 => { score -= 5.0; }                          // gap 20..29: usable for small items
        3 => { score -= 10.0; }                         // gap 30..39: good
        _ => { score -= 12.0; }                         // gap >= 40: very reusable
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact-ish match is valuable
            let slack = post_residual - next_item_size;
            score -= (10 - slack.min(10)) as f64 * 2.0;
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        // last item: prefer zero waste strongly
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad class.
    if bin_residual == bin_capacity {
        // baseline new bin: neutral-ish, penalized so we prefer decent fits
        score += 30.0 + mean_residual * 0.1;
        if post_residual < item_size as f64 {
            // unreachable for empty bin, guard only
        }
    }

    // Progress: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    // Many open bins: prefer consolidating into fuller bins.
    if open_bins_count > 2 {
        score += (bin_residual as f64 / cap) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are nearly unusable
    // for items of size >= 1 drawn from the stream; penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + 4.0 * (11 - post_residual) as f64;
    }
    // Slightly-dead zone [11, 20]: items below 10 exist, so partially usable.
    if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a compact fit exists; scale with progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when this bin would leave
    // a dead gap or the fit is loose; otherwise prefer reusing open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, mitigated if item is large
        // (a big item deserves fresh space) or if fit would be tight.
        let mut new_bin_score = 40.0 - item_size as f64 * 0.4;
        if post_residual <= 10 {
            new_bin_score += 30.0; // fresh bin leaves usable space, not dead
        }
        // Late in the stream, opening new bins is more acceptable than
        // fragmenting; early on, prefer consolidation.
        new_bin_score -= 20.0 * progress;
        // If lookahead item fits the post-residual, this placement chains well.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 12.0;
    }

    // Mean-residual context: if this bin's residual deviates favorably
    // (smaller than mean), it is a good consolidation target.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post-residual (tight packing), but not too small (dead space).
    let mut score = post;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post - nxt;
        if slack <= 10.0 {
            score -= 40.0 - 2.0 * slack;
        } else {
            // Larger slack: mild reward proportional to how much of next item is absorbed.
            score -= 10.0 * (nxt / (post + 1.0));
        }
    }
    // Next item does NOT fit here: penalize proportionally to wasted opportunity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (nxt - post);
    }

    // Dead-space penalty: post residual too small for any realistic item (items >= 1,
    // but tiny slivers are hard to fill). Penalize residuals in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post) * 3.0;
    }

    // Relative-to-mean coupling: bins with residual well above mean are better targets
    // for large items; bins below mean should be drained first.
    let mean_gap = post - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; opening new bins is expensive, so give it a mild penalty
        // that lookahead rewards can overcome.
        score += 25.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // fresh bin perfectly matches next item too
        }
    }

    // Stream progression: late in the stream, consolidate harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln() * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively at low post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size {
            // Bin could host next item only if we DON'T place here: penalize mildly.
            score += 6.0;
        }
        // If next item is large, prefer keeping large residuals intact.
        if next_item_size >= 60 && post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= pressure * (0.5 + progress);

    // Relative fit vs mean residual: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0);
        }
    }

    // New-bin candidate handling: empty bins are neutral-to-slightly-penalized
    // unless item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let base = 45.0 - 0.3 * item_size as f64;
        let scarcity = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += base + scarcity - 20.0 * progress;
        // Prefer opening a new bin for large items that would fragment existing bins.
        if item_size > 60 {
            score -= 15.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    score += 0.35 * pr * (progress * progress);

    // Penalize large dead space relative to capacity, amplified late in stream
    let dead = pr / cap;
    score += 12.0 * dead * dead * (0.3 + progress);

    // Reward tight fits (small post_residual) with non-linear bonus
    score -= 8.0 * (-pr / (item + 5.0)) * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead coupling: prefer bins whose residual can still host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (1.0 - pr / cap) * (1.0 - progress * 0.4);
    } else if next_item_size > 0 {
        // post_residual unusable for next item: penalize dead space smoothly
        score += 4.0 * dead * (1.0 + progress);
    }

    // Mean residual coupling: avoid drifting far from fleet average
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.02 * open_bins_count as f64 * dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue determines dead-space quality.
    let post_mod = post_residual % 10;
    // Residues 0 (perfect) and small residues pair well with common item sizes.
    let residue_penalty = match post_mod {
        0 => -18.0,
        1 | 2 => -6.0,
        3 | 4 => 2.0,
        5 | 6 => 4.0,
        7 | 8 => 7.0,
        _ => 10.0,
    };
    score += residue_penalty;

    // Integer-division thresholds: post_residual in [0,10] is nearly dead space.
    let dead = post_residual / 10; // 0 => dead zone
    if dead == 0 {
        score += 25.0;
    } else if dead == 1 {
        score -= 5.0;
    }

    // Reward tight fits: waste ratio via capacity fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 40.0;

    // Lookahead coupling: if next item fits post_residual exactly or by harmonic class.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 22.0; // perfect two-step packing
            } else {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it is only chosen when all else is bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.15 * open_bins_count as f64;
        // But if current item is large relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual {
            score -= 35.0;
        }
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // Mean-residual coupling: prefer bins near mean residual (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.08;

    score
}

