    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the larger the fraction of the bin's residual the item consumes,
    // the better the packing density. Subtract proportionally.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Lookahead (k=2): reward leaving room for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.0;
        }
        // Penalize creating a residual that is too small for the next item
        // but still wasted dead space (fragmentation risk).
        let frag = post_residual as f64 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        score += 0.05 * frag;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // If no open bin can fit the item, the new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        } else {
            // Base penalty for opening a new bin when alternatives exist.
            score += 12.0;
            // But for large items relative to the mean residual, opening a fresh bin
            // can be wise (avoids destroying big residual space for small waste).
            if (item_size as f64) > mean_residual + 10.0 {
                score -= 6.0;
            }
            // Early in the stream, slightly prefer consolidating into existing bins
            // to keep the open-bin pool small.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mild pressure against accumulating many open bins.
    score += 0.03 * open_bins_count as f64;

    // Slight time-dependent tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalize post residual
    let prn = pr / cap;

    // Smooth polynomial coupling: reward small post_residual non-linearly
    score -= 40.0 * prn * (1.0 - prn);

    // Stream-progress coupling: later in the stream, prefer tighter fits more strongly
    let prog_coupling = progress * progress * (1.0 - progress);
    score -= 60.0 * prog_coupling * prn * (1.0 - prn);

    // Penalize dead space that cannot fit a plausible next item (smooth sigmoid-ish term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - pr;
        let miss = gap / cap;
        let w = 1.0 / (1.0 + (-8.0 * miss).exp()); // ~0 if fits, ~1 if not
        score += 25.0 * w * (0.5 + progress);
    } else {
        // Last item: purely minimize waste
        score -= 30.0 * prn * prn;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are quite full
    if bin_residual == bin_capacity {
        let fullness = 1.0 - mean_residual / cap;
        score += 10.0 + 45.0 * (1.0 - fullness) * (1.0 - progress);
    }

    // Mild pressure toward consolidating into fewer bins
    score += open_bins_count as f64 * 0.05;

    // Mean residual context: prefer bins whose residual deviates smoothly from the mean
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: modular structure on capacity
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,               // perfect fit
        1..=5 => 1.0,           // near-perfect: dead space almost unusable anyway
        6..=15 => 2.0,          // small class
        16..=30 => 3.0,         // medium class
        31..=50 => 4.0,         // large class
        _ => 5.0,               // huge leftover
    };
    score += class * 3.0;

    // Integer-division harmonic coupling: post_residual bucket vs next item bucket
    if next_item_size > 0 {
        let nb = next_item_size / 10; // next item harmonic class
        let pb = pr / 10;             // post residual class
        if nb > 0 && pb > 0 {
            let harmony = (nb as f64 - pb as f64).abs();
            // reward when next item fits exactly into post residual
            if next_item_size == pr {
                score -= 12.0;
            } else if next_item_size < pr {
                score -= 6.0 / (1.0 + harmony);
            } else {
                // next item won't fit here: leftover is a trap
                score += 4.0 + harmony * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish, but avoid opening new bins
    // when many open bins exist and mean residual is high (fragmentation risk)
    if bin_residual == bin_capacity {
        score = 55.0; // base cost of a fresh bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count as f64 * mean_residual / cap > 0.5 {
            score += 10.0 * progress; // penalize new bins when fragmentation high
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 20.0; // next item can't fit any open bin anyway
        }
    }

    // Tightness reward: fraction of bin consumed by this item
    let tightness = item_size as f64 / cap;
    score -= tightness * 10.0;

    // Mild global balance: prefer bins with residuals near mean (keeps options open)
    score += (post - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for the next item: likely dead space.
        score += 6.0;
    }

    // Tight fits (small gap relative to item) are preferable.
    score += (item_size as f64) * 0.15;

    // Open-bin pressure: when many bins are open, prefer reusing existing
    // bins over opening new ones; penalize the empty new-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening a bin is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is already below average (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 12.0 / (1.0 + post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        score -= 25.0 / (1.0 + next_gap as f64);
        if next_gap == 0 {
            score -= 35.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space creation.
        score += 8.0;
        // Slight reward if post_residual is small enough to be nearly dead anyway.
        if post_residual < 10 {
            score -= 6.0;
        }
    }

    // Compare residual to mean residual across open bins: prefer filling below-average-space bins.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (fitting_bins_count as f64);
        // If next item is large and this bin is fresh, opening a new bin can be OK.
        if next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Late in the stream: be more conservative, prefer reusing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward if next item fits in post_residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 + 30.0 * chain_quality;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 5.0; // small crumbs are fine
        } else {
            score += 0.3 * dead;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist with large residuals
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 100.0; // preserve last-chance bin usage
        }
        // early in stream, opening bins is cheaper (more future items to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0;
        }
    } else {
        // Prefer bins with residuals far from mean residual (diversity of sizes)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.2 * dev;
        // Prefer emptier bins when many bins open (consolidation pressure)
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 0.1 * pressure * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear penalty growth
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty: residuals too small for likely future items
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = (nxt - pr).max(0.0);
        score += 0.6 * waste * (1.0 - progress);
        // Reward bins whose post-residual fits the lookahead item
        if pr >= nxt {
            score -= 0.9 * nxt * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.35 * cap * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly early, allow late in stream
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += (0.25 - 0.15 * progress) * cap + 0.05 * open_bins_count as f64;
    }

    // Mean-residual coupling: discourage bins far from fleet mean (fragmentation)
    score += 0.1 * (pr - mean_residual).abs() * (0.5 + progress);

    // Smooth polynomial progress interaction on tight fits
    let tight = 1.0 - norm_pr;
    score -= 8.0 * tight * tight * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let q = post_residual * 4 / bin_capacity; // 0..3 class of leftover quarter
    let class_bonus: f64 = match q {
        0 => 0.0,          // nearly full bin: ideal
        1 => -6.0,         // leftover <= 25%: still great
        2 => 4.0,          // leftover 25-50%: mediocre dead space
        _ => 12.0,         // large leftover: wasteful
    };
    score += class_bonus;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty scaled by how unusable the leftover is for the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // leftover cannot host next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // leftover can host next item: reward
            score -= 8.0;
        }
        // modulo coupling: leftover sharing residue class with next item
        if post_residual > 0 && (post_residual % 10) == (next_item_size % 10) {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            score -= 20.0; // big next item pairs well with fresh bin
        }
    }

    // Encourage consolidation when many bins are open: prefer bins below mean residual
    // (tighter bins) so loose bins get filled first.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold: leftover divisible into halves of capacity is reusable.
    if post_residual % (bin_capacity / 2) == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit even a minimal item (size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // creating a tiny unusable sliver is worst-case
    }
    // Gaps too small for the lookahead item are semi-dead (wasted unless later tiny items arrive).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Reward perfect / tight fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward leaving a gap that exactly accommodates the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
        // Reward gaps in the "useful" range (>=10), scaled by how reusable they are.
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Reward last-chance bins: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and discourage spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Prefer bins whose residual is already below average (consolidating fullness).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 55.0 - 45.0 * desperation
            + (post_residual as f64 - bin_residual as f64) * 0.0;
        // If the next item would perfectly fill this fresh bin alongside current one, ease opening.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0; // chain perfect fit
        } else {
            // Penalize residuals that tease but don't fit next item (dead space).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            } else {
                // Next item fits: mild reward proportional to closeness.
                score -= (next_item_size as f64) / (1.0 + diff as f64);
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving residuals far below mean (fragmentation) but reward tight packing.
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Discard new-bin candidate unless nothing decent exists: new bin has full residual,
    // only attractive when lookahead matches large space or item is big.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.3;
        }
        if item_size >= 70 {
            score -= 40.0;
        }
    }

    // Late in stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits (small post_residual already handled),
    // but add a mild penalty for very large leftover space to break ties.
    let t = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: if the next item fits exactly into the post_residual,
    // this bin becomes highly attractive (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here: slight penalty proportional to leftover dead space
            score += 0.5 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    // Small residual that likely becomes dead space: penalize residuals that
    // are too small for the minimum item but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin when many open bins
    // already have usable residual, and when we are deep in the stream.
    if bin_residual == bin_capacity {
        // New bin base attractiveness: moderate residual (empty bin has full residual)
        score = bin_capacity as f64 * 0.9;
        // Early in the stream, opening bins is fine; late, avoid it.
        score += 20.0 * t;
        // If open bins already have generous mean residual, discourage new bin.
        score += 0.3 * mean_residual;
        // If few fitting bins exist, opening a new bin is less costly.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Lookahead: if next item also fits in a fresh bin together with current item,
        // a new bin is reasonable.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Global pressure: when many bins are open with small mean residual,
    // prefer consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= 0.1 * mean_residual;
        // Slight preference to fill bins with larger residual less eagerly late in stream
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let it_norm = it / cap;

    // Base: post-residual (tighter fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals; later, penalize wasted space quadratically.
    let waste_penalty = pr_norm * pr_norm * (0.5 + 2.5 * progress) * cap;
    score += 0.6 * waste_penalty;

    // Smooth interaction: item size vs residual, favoring bins where item fills
    // a large fraction of the residual (cubic fill term).
    let fill = it / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill * fill * (1.0 - progress);

    // Penalize residuals that leave awkward gaps relative to mean residual.
    let gap = (pr - mean_residual) / cap;
    score += 8.0 * gap * gap * cap;

    // Lookahead coupling: smooth polynomial reward if next item fits post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = ((pr - nx) / cap).max(0.0);
        let slack = (nx - pr).abs() / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 - slack) * fits.max(0.0).min(1.0);
        score += 4.0 * slack * slack * cap;
    }

    // Last-chance bin: strong smooth reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - progress * 0.5);

    // Mild penalty for proliferation of open bins, smoothed by progress.
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Small cubic residual curvature to break ties smoothly.
    score += 0.05 * pr_norm * pr_norm * pr_norm * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction bucket it lands in.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer division thresholds on post_residual (harmonic classes of C).
    // Residuals in (0,10] are dead space; (10,20] can hold smallest items, etc.
    let class = post_residual / 10; // 0..=10
    score += match class {
        0 => -30.0,                       // perfect / near-perfect fill
        1 => -8.0,                        // can still fit tiny items (1..10)
        2 => 0.0,
        3 => 2.0,
        4 => 4.0,
        5 => 6.0,
        6 => 8.0,
        7 => 10.0,
        8 => 12.0,
        9 => 14.0,
        _ => 20.0,                        // barely touched bin, wasteful
    };

    // Modulo coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= post_residual {
            let rem = post_residual % nxt;
            // reward exact division (rem==0), penalize awkward remainders
            score -= (nxt as f64) * (1.0 - rem as f64 / nxt.max(1) as f64) * 0.35;
            if rem == 0 {
                score -= 6.0;
            }
            // double-fill: item + next leaves harmonic small class
            let post2 = post_residual - nxt;
            if post2 <= 10 {
                score -= 10.0;
            } else if post2 <= 20 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            score += ((nxt - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Fraction-of-capacity harmonic thresholds on bin fill level.
    let fill = 1.0 - frac;
    if fill > 0.8 {
        score -= 12.0; // nearly full bins are precious, close them out
    } else if fill > 0.5 {
        score -= 3.0;
    }

    // New-bin candidate: only attractive late in stream or when mean residual is tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 20.0 * progress - 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild diversity bonus: spreading across bins when many are open with slack.
    if open_bins_count > 3 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0 - post_residual as f64; // 50..60 penalty for tiny gaps
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // reward this placement; if next item is large and post residual is a
    // useless sliver, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; favor consolidating into existing space.
    score += (open_bins_count as f64) * 1.5;

    // Slightly favor bins whose residual is below the mean (tighter bins first),
    // keeping low-residual bins for small future items.
    let tightness = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Early in the stream, be more permissive about opening new bins
    // (build a good pool); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate handling: empty bin has residual == capacity, so its
    // raw post_residual is large; add a mild fixed cost so it only wins when
    // all fitting bins score badly.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly in the post-residual (perfect 2-step match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how much of post_residual the next item consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here: penalize large dead space.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize post_residual that is too small to ever be useful (dead space below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Compare residual to mean residual across open bins: favor bins that become closer to the mean
    // (balanced packing) unless it's a tight fit opportunity.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If next item is large and current item is small, opening fresh may be wise.
        if next_item_size > 50 && item_size < 30 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer packing into bins with smaller pre-residual (tighter bins first).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Slight preference to use bins when many are open (avoid bin proliferation).
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer minimal post_residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tight) * (1.0 - tight) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but relax penalty if existing residuals are all poor for the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = bin_capacity as f64 - item_size as f64;
        score += waste * 0.5;
        // Penalize more when many bins already open (fragmentation control).
        score += open_bins_count as f64 * 2.0;
        // Early stream: allow opening bins more freely to build a pool.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    } else {
        // Using an open bin reduces pressure; reward slightly.
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // keeping this residual is valuable; if not, the residual is dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // Next item fits now but not after placing this item here:
            // consider leaving this bin for the next item.
            let gap = (post_residual + item_size - next_item_size) as f64;
            score += gap * 0.3;
        } else {
            // Dead-space penalty proportional to unusable residual.
            score += post_residual as f64 * 0.4;
        }
    }

    // Global residual context: if mean residual is high, prefer bins whose
    // post residual stays near the mean (keep pool homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late-stream conservatism: waste less as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual (tight fit), with non-linear shaping
    let mut score = post.powf(1.4) / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, moderate residuals are acceptable; late, waste is heavily penalized
    let waste_coupling = (post / cap).powi(3) * (0.5 + progress) * 2.0;
    score += waste_coupling;

    // Perfect fit bonus (post_residual near zero)
    if post_residual == 0 {
        score -= 3.0;
    } else if post_residual <= 10 {
        score -= 2.0 * (1.0 - post / 10.0);
    }

    // Penalize residuals that are too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 1.5 * (1.0 - post / 10.0);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 1.2 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use leftover; penalize proportional to wasted space
        score += 0.8 * (post / cap);
    }

    // Late stream: prefer filling existing bins over opening new ones
    score += progress * (open_bins_count as f64).sqrt() * 0.3;

    // Slight penalty if this bin's residual deviates from mean residual
    // (encourages homogenization of residual space)
    score += 0.4 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: make it moderately attractive only when it's a great
    // deal early or when open bins are scarce; otherwise mild penalty
    if bin_residual == bin_capacity {
        score = cap * 0.6 - progress * cap * 0.2;
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
