pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 60.0; // gap too small for any future item
    } else if post_residual >= min_item && post_residual < 20 {
        score += 15.0; // tight gap, likely dead space
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit, zero waste
    }

    // Reward leaving gaps that can fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // gap blocks the next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over creating more residual spread; with few bins, be less picky.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins whose residual is close to what we consume (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 12.0;

    // New-bin candidate: only attractive when no good fit exists
    // (its post_residual is large, so dead-space penalties already apply).
    if bin_residual == bin_capacity {
        let late = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 15.0 * late; // slightly cheaper to open early
    }

    // Mild alignment with mean residual state: avoid bins far from the mean
    // when the mean is small (fragmentation control).
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
        score += dev * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits into the post residual,
    // this placement is excellent (creates a chain of fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 50.0 + leftover_after_next as f64;
        // Exact two-item fill is ideal.
        if leftover_after_next == 0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; penalize dead space relative to next item.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Compare post residual against mean residual: prefer bins that end up
    // tighter than average (consolidating space).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize large unusable residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 20.0; // tiny dead space is wasted bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive if no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // If item nearly fills a fresh bin, opening is reasonable.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 100.0 * fill;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization, non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        score -= 25.0 * (1.0 - pr / cap).powi(6);
    }

    // Penalize dead space that no plausible item (1..100) can use well:
    // residual in (0, 10) is pure waste; residual in [10, 40) partially reusable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0;
    } else if pr >= 10.0 && pr < 40.0 {
        score += 6.0 * (1.0 - pr / 40.0);
    }

    // Lookahead coupling: if next item fits the post-residual exactly, big reward;
    // if next item fits at all, moderate reward; if not, penalize tight fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            if slack == 0.0 {
                score -= 35.0;
            } else {
                score -= 18.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item won't fit here: prefer leaving larger, more usable residual.
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let ob = open_bins_count as f64;
    score -= 2.0 * (ob / (ob + 5.0)) * (1.0 - pr / cap);

    // Global state: if mean residual is large, closing gaps is cheap; if small,
    // be pickier about which bin absorbs the item.
    score += 0.15 * (mean_residual - pr).abs();

    // Time horizon: early in stream, be more exploratory (favor new-bin usage
    // less strongly later); late in stream, squeeze every bin.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (1.0 - pr / cap);

    // New-bin candidate handling: opening a bin is fine early or when this item
    // is large and no existing bin fits well (post_residual would be tiny anyway).
    if bin_residual == bin_capacity {
        let base = 45.0 - 30.0 * t;
        // If item is large relative to capacity, new bin is attractive.
        let large_item_bonus = 20.0 * (item_size as f64 / cap);
        score = base + (post_residual as f64) - large_item_bonus;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 10.0; // fresh bin accommodates the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, superlinearly (dead space grows costly).
    let mut score = pr * pr / cap;

    // Smooth tight-fit reward: strongly favor small post_residual.
    score -= (1.0 - pr / cap).powi(4) * 60.0;

    // Coupling with stream progress: as stream advances, prefer filling existing
    // bins ever more aggressively (non-linear ramp).
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += pr * 0.3 * (progress_coupling - 1.0);

    // Lookahead: bonus if the next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        let next_fits = if pr >= nxt { 1.0 } else { 0.0 };
        score -= next_fits * (1.0 - fit_gap / cap).powi(3) * 35.0;
        // Penalize leaving a residual that no plausible next item uses well.
        score += (1.0 - next_fits) * pr * 0.2;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // existing residuals are large relative to the item (smooth gate).
    if bin_residual == bin_capacity {
        let gate = ((mean_residual - isz) / cap).clamp(0.0, 1.0);
        score = 20.0 + 50.0 * (1.0 - gate) * (1.0 - gate) - 30.0 * progress * progress;
    } else {
        // Mild preference to consolidate across many open bins.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (pr / cap);
    }

    // Mean-residual alignment: bins far from the fleet mean get a soft pull.
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual / (bin_capacity / 4)) % 4; // harmonic index 0..3

    // Dead-space penalties by harmonic class:
    // leftover in (0..=10] is nearly dead -> heavy penalty unless it's zero.
    if post_residual > 0 && post_residual <= 10 {
        score += 30.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    } else if post_residual > 25 && post_residual <= 50 {
        score += 4.0;
    } else if post_residual > 50 {
        // very roomy leftover: mild penalty, wasteful for a large item
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit: reward strongly
    }

    // Modulo-arithmetic bonus: post_residual divisible by small harmonics is
    // easier to fill with typical small items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // chain fit
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic alignment: next item leaves another clean residue
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 8.0; }
            if nr <= 5 && nr > 0 { score += 10.0; } // creates dead space next
        } else {
            // next item cannot use this bin's residue: penalize wasting space now
            score += 6.0 + pr / c * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it mildly attractive only when current
    // fit is bad (large post_residual relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let badness = (pr / c).clamp(0.0, 1.0);
        score = 20.0 + 45.0 * badness - 15.0 * (1.0 - progress);
        // open new bin early when few bins exist (cheap), late only if fit is poor
        if open_bins_count < 3 { score -= 10.0; }
        if post_residual <= 10 { score += 50.0; } // never open a bin to avoid tiny residue
    }

    // Global context: nudge toward bins tighter than the mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Integer-division threshold on item size: large items prefer tight bins.
    if item_size >= bin_capacity / 2 && post_residual <= bin_capacity / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can ever usefully fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver -> heavily penalize
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // only smallest items can use it
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 30.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit, penalize creating a residual that blocks it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0; // next item nearly perfect-fills this bin
        }
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // residual too small for lookahead item
        }
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is already low.
    if open_bins_count > 2 {
        score += 0.5 * (open_bins_count as f64 - 2.0) * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count >= 1 && post_residual < 20 {
            score += 40.0; // an existing bin would fit tightly; avoid new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual (soft lookahead reward).
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * tightness;
    }

    // Penalize leaving residual too small for typical items (dead space),
    // unless it perfectly matched (already rewarded above).
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        let waste = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 25.0 * waste * waste;
    }

    // Zero residual is ideal (bin fully closed).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual below mean are
    // more "advanced" (closer to full); prefer filling those first.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate handling: empty bin gets a mild penalty so that
    // decent fits into open bins are preferred, but not so large that a
    // bad fit into an existing bin wins.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If lookahead won't fit either, opening a fresh bin is fine.
        if next_item_size > post_residual {
            score -= 12.0;
        }
    }

    // Late in the stream, consolidation matters more: reward tight fits harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less (subtract) when item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact fit jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward leaving room for the next item (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // bonus if post_residual is a snug host for next item
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * snug * snug;
        } else {
            // penalize leaving dead space that next item can't use
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist; new-bin candidate detection.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin attractive only if item is large relative to capacity or few alternatives.
        score += 20.0
            - 0.15 * (item_size as f64)
            - 2.0 * (open_bins_count as f64).ln().max(0.0)
            - 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // late in stream, prefer closing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    } else {
        // Reward using bins with below-average residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Prefer bins with larger residual when many bins fit (keep small-residual bins for small items).
        if fitting_bins_count > 2 {
            score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        }
    }

    // Small dead-space shaping: quadratic penalty on large post residuals.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) are strongly rewarded.
    let tightness = 1.0 - post / cap;
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 12.0 * tightness * tightness * progress_poly * cap / 100.0;

    // Penalize dead space that cannot fit the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        let waste = if gap > 0.0 { gap } else { 0.0 };
        let waste_frac = waste / cap;
        score += 8.0 * waste_frac * waste_frac * cap;
        // Reward leaving room exactly for the lookahead item.
        let match_bonus = 1.0 - (gap.abs() / cap).min(1.0);
        score -= 6.0 * match_bonus * (0.5 + 0.5 * progress_poly);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress_poly;
    }

    // Mild penalty for spreading across many open bins vs consolidating.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Pull toward mean residual: avoid outliers in residual distribution.
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress_poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small, reusable" class are favored. Classes by integer division of
    // post_residual into 10-wide bands (capacity 100 => 10 classes).
    let pr = post_residual;
    let class = pr / 10; // 0..10
    // Reward exact small leftovers strongly (they are near-dead space only
    // if too small; moderate leftovers 20-50 are reusable).
    let class_bonus: f64 = match class {
        0 => -12.0,                       // perfect fit
        1 => -6.0,                        // tiny leftover, likely dead
        2..=5 => -14.0,                   // sweet spot: reusable residuals
        6..=8 => -4.0,                    // large leftover, mediocre
        _ => 0.0,                         // nearly empty bin usage
    };
    score += class_bonus;

    // Exact modulo harmony: post_residual divisible into clean chunks
    // (e.g. post_residual % 25 == 0 or % 20 == 0) leaves composable space.
    if pr > 0 && (pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 && pr >= 30) {
        score -= 5.0;
    }

    // Lookahead harmony: if next item fits exactly in post_residual,
    // strongly prefer this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits: penalize proportional to wasted harmony
            let nxt = next_item_size as f64;
            score -= 6.0 * (nxt / (pr as f64 + 1.0));
            // harmonic pair: item+next divides capacity nicely
            if (item_size + next_item_size) % 50 == 0 || (item_size + next_item_size) % 34 == 0 {
                score -= 6.0;
            }
        } else {
            // next item will NOT fit here: slight penalty for stranding
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when few bins are open; penalize spreading when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let spread_penalty = 15.0 * (open_bins_count as f64 / 8.0).min(2.5);
        score += spread_penalty - 10.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bin is wasteful.
        if mean_residual > item_size as f64 + 10.0 {
            score += 8.0;
        }
    }

    // Tightness coupling: prefer bins where the item fills a large fraction
    // of the residual (best-fit flavor, nonlinear).
    let fill = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 10.0 * fill * fill;

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // any realistic item (below the minimum plausible item size) are pure waste.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && bin_residual != bin_capacity {
        score += 200.0; // unusable sliver -> strong penalty
    } else if (post_residual as f64) < min_item && bin_residual == bin_capacity {
        // new-bin candidate producing a sliver is terrible
        score += 500.0;
    }

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual > 0 {
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    } else {
        score -= 60.0; // perfect fill
    }

    // Dead-space gradient: penalty grows super-linearly as post_residual
    // falls into the "hard to reuse" zone (below ~35% of capacity).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 35.0 {
        score += (35.0 - pr) * (35.0 - pr) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage consolidating into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item cannot use leftover: mild penalty proportional to gap
            score += 0.1 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Prefer bins whose residual is already below average (consolidation).
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - (bin_residual as f64)).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: next item exactly fills remainder.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead credit proportional to how close the next item fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot fit here; penalize small unusable remainders.
        score += 15.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Zero post-residual is a perfect fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize the brand-new empty bin candidate mildly, unless existing bins
    // would leave very tight/awkward remainders.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening new bins is relatively cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Slight preference to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // small unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 12.0;
        } else {
            // next item cannot fit here; mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance: only fitting bin — strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation into existing bins
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: bins with residual below mean are scarcer, favor them
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New bin candidate: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a bin, reduced late in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 - progress * 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // next item may want a fresh bin too; slight discount
            score -= 8.0;
        }
        if fitting_bins_count == 1 {
            // an existing bin fits and is last chance; never open new bin
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear waste penalty: dead space that cannot fit the next item is worse,
    // and the penalty grows polynomially with stream progress.
    let unusable = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64
    } else {
        0.0
    };
    let progress_poly = 0.5 + 1.5 * progress * progress;
    score += 0.35 * unusable * progress_poly;

    // Reward tight fits: quadratic coupling of fill ratio with post_residual.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving residuals close to but below the typical small item size,
    // using mean_residual as a smooth scale reference.
    let dead_zone = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dead_zone * dead_zone / (bin_capacity as f64);

    // New-bin candidate: encourage opening a fresh bin early (when many items remain),
    // discourage it late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let remaining = if total_items > step_index { (total_items - step_index) as f64 } else { 1.0 };
        score += 25.0 * (1.0 - progress) - 2.0 * remaining.min(10.0) as f64 * progress;
        // If no open bin fits well, opening a new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight penalty for spreading across many open bins.
        score += 0.3 * open_bins_count as f64 * (0.5 + progress);
    }

    // Reward bins whose residual after placement stays usable for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
