            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use this residual: penalize large residuals
            score += post_residual as f64 * 0.15;
            // harmonic penalty: residual in awkward classes
            let r = post_residual % 20;
            if r > 10 { score += (r - 10) as f64 * 0.8; }
        }
    } else {
        // last item: any residual is pure waste
        score += post_residual as f64 * 0.5;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening new bin unless all fits are bad
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 6.0; // next item won't fit a fresh residual either... keep open bins busy
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // open new bin if mean residual of open bins is too fragmented
        if mean_residual < item_size as f64 * 0.4 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Progress-based mild exploitation of tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 5 {
        score -= 5.0 * (1.0 - progress);
    }

    // Integer-division threshold: reward residuals that are multiples of common item sizes
    for k in [10u32, 20, 25, 50] {
        if post_residual >= k && post_residual % k == 0 {
            score -= 3.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (<= 10) are effectively wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Post-residual won't help the next item; mildly penalize creating dead space.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and make opening a new bin less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 30.0 + pressure;
    } else {
        // Existing bins get a mild reward that grows with open-bin count.
        score -= (pressure * 0.3).min(20.0);
    }

    // Prefer bins tighter than average (filling the emptiest-first / tightest-fit style).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) nonlinearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual < 30 {
        score -= 10.0;
    } else {
        // Penalize large leftover space (wasteful residual).
        score += (post_residual as f64 - 30.0) * 0.3;
    }

    // Aggressive 2-step lookahead: perfect match for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 20.0 - slack; // near-perfect match
            } else {
                score += slack * 0.15; // next item would leave big gap
            }
        } else {
            // Next item cannot fit here; residual is dead space for lookahead.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare against mean residual: prefer bins whose residual is above mean
    // (they have more room), penalize squeezing tight bins below mean.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin gives
    // a good fit (post_residual large) or item is huge relative to residual.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline, penalized so open bins with decent fits win.
        score += 35.0;
        // Favor a fresh bin for very large items (they need full space anyway).
        if item_size >= 70 {
            score -= 30.0;
        }
        // Early in stream, allow more bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: fraction of bin consumed by this placement
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Extra reward if next item then nearly fills bin
        let chain_residual = post_residual - next_item_size;
        if chain_residual <= 10 {
            score -= 40.0;
        }
    }
    // Penalize leaving a gap that next item barely misses
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 30.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New bin candidate handling: only prefer a fresh bin when existing bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        // Penalize new bins mildly; relax penalty late in the stream or under high pressure
        let mut new_bin_penalty = 120.0 + 20.0 * pressure;
        new_bin_penalty -= 150.0 * progress * crowding;
        score += new_bin_penalty.max(10.0);
    } else {
        // Prefer bins whose residual deviates below the mean (fill the emptiest-tight ones)
        let dev = mean_residual - bin_residual as f64;
        score += 0.5 * dev;
    }

    // Penalize large dead space that few typical items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild preference for bins with lower residual among many options
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten packing later in the stream
    score += 12.0 * progress * norm_pr * norm_pr;

    // Reward tight fits via smooth interaction of item size and residual
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that is too small for typical items (smooth dead-zone)
    let deadness = 1.0 - (norm_pr / 0.2).min(1.0);
    score += 10.0 * deadness * deadness * (1.0 - progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward leaving room for the next item (smooth overlap term)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let overlap = (nx - norm_pr).max(0.0);
        score += 6.0 * overlap;
        // Extra reward if next item fits exactly into post-residual
        let fit_next = 1.0 - (nx - norm_pr).abs() / cap;
        score -= 10.0 * fit_next.max(0.0) * fit_next;
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it moderately attractive, more so early in stream
    if bin_residual == bin_capacity {
        score = cap * (1.1 - 0.25 * progress) - 6.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (capacity fractions) ----
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left after placement

    // Dead-space penalty: residuals that are "hard to fill" get punished.
    // Harmonic classes: residual in (0,10] is nearly dead; (10,20] poor;
    // exact quarter/half classes are reusable anchors.
    if post_residual == 0 {
        score -= 40.0; // perfect fit — best possible outcome
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space, nearly unusable
    } else if post_residual <= 20 {
        score += 10.0; // poor leftover
    }

    // Integer-division thresholds: residual divisible by common item classes
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 6.0; // residual on a harmonic grid (10/20/30...) is reusable
    }
    if r % 25 == 0 && r > 0 {
        score -= 4.0; // quarter-capacity anchor class
    }
    if r % 50 == 0 && r > 0 {
        score -= 3.0; // half-capacity anchor class
    }
    // Awkward primes / odd classes are harder to fill exactly
    if r % 10 != 0 && r % 5 != 0 {
        score += 2.0;
    }

    // ---- Lookahead coupling (k=2): does the next item fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // next item exactly seals this bin
        } else if next_item_size < post_residual {
            // reward proportionally, but less if it leaves a bad class again
            let next_post = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (next_post as f64) / cap_f);
            if next_post % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0; // only bin that fits — avoid opening a new bin
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // A fresh bin is attractive early (many future items) or when the
        // stream is nearly done and residual waste matters little.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 30.0 * (1.0 - progress); // fresh bins more valuable early
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host the next item comfortably too
            nb -= 4.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            nb -= 8.0; // existing bins are nearly full — new bin is good
        }
        score = score.max(0.0) + nb + 10.0; // baseline so perfect fits beat new bin
    }

    // ---- Mild global regularization ----
    score -= 0.05 * mean_residual;
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: mild penalty.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no real bins exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Base new-bin score anchored to mean residual; prefer it only if
            // the best fit would leave a worse gap.
            score += 55.0 + mean_residual * 0.2;
        }
    }

    // Mild stream-progression adaptation: later in the stream, be slightly
    // more tolerant of residual space (closing bins matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Reward bins whose residual is close to the mean (keeps residuals balanced).
    score -= (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and the next item size (perfect chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect lookahead match
        } else if post_residual as u32 >= next_item_size {
            // next item still fits here: reward proportionally to tightness
            score -= 25.0 * (1.0 - diff / 100.0);
        } else {
            // next item won't fit: penalize wasted residual
            score += 10.0 + diff * 0.3;
        }

        // Extra reward if placing item now AND next item leaves a small tail
        let post2 = post_residual as f64 - next;
        if post2 >= 0.0 && post2 <= 10.0 {
            score -= 15.0;
        }
    }

    // Tight fit reward: small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 20.0 / (1.0 + tightness);

    // Relative to mean residual: prefer bins that become tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 15.0;
        // more open bins => prefer reusing existing bins
        score += open_bins_count as f64 * 2.0;
        // if next item is huge and no open bin can chain, new bin is fine
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
        // early in stream, opening bins is cheaper
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Penalize leaving residuals in the awkward 20..40 dead zone
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 40.0 {
        score += 0.4 * (40.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).

    // Lookahead: if next item fits in the post-residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * next_item_size as f64;
        } else {
            // Penalize residual that is too small for the next item (dead space risk),
            // scaled by how close the wasted space is to a usable chunk.
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Penalize opening a new bin mildly, more so when many bins are already open
    // and their mean residual could still absorb future items.
    if bin_residual == bin_capacity {
        score += 8.0;
        score += 1.5 * open_bins_count as f64;
        score += 0.3 * mean_residual;
    } else {
        // Reward using existing bins whose residual is close to the mean
        // (keeps the pool of residuals homogeneous and mergeable).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Time horizon: early in the stream, be more willing to open bins (long future);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Non-linear tightness coupling: reward near-perfect fills superlinearly.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap; // 0..1
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits (low post residual) more strongly as stream advances
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (10.0 + 30.0 * progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (nxt - pr) / cap * (0.5 + progress);
        } else {
            // reward bins that leave exactly usable room for next item
            score -= 8.0 * (1.0 - ((pr - nxt) / cap).abs()) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: prefer it only when it beats fragmented placements
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo small integers.
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;
    let mod20 = (pr % 20) as f64;
    let class10 = (pr / 10) as f64; // integer-division class (decade of leftover)

    // Penalize dead space: small nonzero post_residual is worst (unusable sliver).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Reward exact fit.
    if pr == 0 {
        score -= 15.0;
    }

    // Harmonic residue penalties: residues near 0 mod 10/20 are "clean" classes.
    score += 0.6 * mod5 + 0.4 * mod10 + 0.5 * mod20;

    // Decade class coupling: prefer leaving residuals in the same decade class
    // as the next item's size class so the next item may fit.
    let next_class = (next_item_size / 10) as f64;
    if next_item_size > 0 && pr >= next_item_size {
        // next item fits here: reward alignment of classes
        score -= 6.0 + 1.5 * next_class;
        // extra reward if next item fills this bin nearly exactly
        let nr = pr - next_item_size;
        if nr < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to waste
        score += 0.25 * pr as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it mildly attractive only when current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        if pr >= 60 {
            score -= 10.0; // a fresh bin with big residual is fine early
        }
    }

    // Progress-coupled tightening: as stream advances, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (0.3 * pr as f64);

    // Mean residual coupling: if this bin is far below mean residual, it is
    // relatively full — favor it; if far above, penalize.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are nearly worthless; penalize them heavily.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Perfect fill is a jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual is far from any useful future fit:
    // if the next item cannot fit here but this bin still has space,
    // the leftover risks becoming dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0 + 0.25 * post_residual as f64;
    }
    // Reward bins that can also host the next item (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: prefer using existing bins over proliferating bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // current bins are crowded (mean residual low) or many bins already open
    // with poor spread. Otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score -= crowding * 6.0;           // crowded open bins -> new bin OK
        score += 10.0;                      // base reluctance to open new bin
        score += open_bins_count as f64 * 0.3; // many open bins -> slightly favor reuse
    }

    // Mild stream-progression tie-breaker: later in the stream, be slightly
    // more conservative with leftovers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.15;

    // Deviation from mean residual: prefer bins close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) but not zero-waste obsession
    score = post_residual as f64 * 0.9;

    // Strong 2-step lookahead: reward when the NEXT item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how snugly
            score -= (12.0 * next_item_size as f64) / (post_residual as f64 + 5.0);
        } else {
            // next item cannot fit here; penalize leftover dead space a bit more
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
        // mild continuous coupling on the absolute gap
        score += 0.05 * diff;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average waste is good (bin becomes "well used")
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // opening a new bin costs ~ one full bin of wasted capacity potential;
        // make it expensive unless the item is huge relative to capacity
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 30.0 * tightness;
        // early in the stream, new bins are cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // if next item is small, a fresh bin can host it too
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Slight preference to keep many open bins from proliferating:
    // filling existing bins is favored when many are open
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Nonlinear nudge: heavily penalize residuals that are too small for typical
    // future items (dead space below the minimum useful size ~10)
    if post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is heavily favored.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Non-linear penalty for dead space relative to capacity.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * waste_ratio * 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0; // perfect two-item chain
            } else {
                score -= (next_item_size as f64 / post_residual as f64) * 8.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; keep this bin flexible (low residual is fine).
            score -= 3.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (bin consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.05;

    // Early in the stream, be more willing to open/consolidate; late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        // But allow new bin if item is huge and nothing tight exists (handled by comparisons).
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits (large fill) mildly; later, dead space matters more.
    let prog_coupling = x * x * (0.5 + 2.0 * progress) + x * x * x * (1.0 + 3.0 * progress);
    score += 20.0 * prog_coupling;

    // Reward near-perfect fills more strongly as stream advances (smooth in progress).
    let fill_ratio = item_size as f64 / cap;
    score -= 30.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic in gap).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap < 0.0 {
            score += 8.0 * (gap / cap) * (gap / cap) * cap * (0.5 + progress);
        } else {
            // Smooth small reward when lookahead fits exactly-ish
            score -= 6.0 * (1.0 - (gap / cap)) * (1.0 - (gap / cap));
        }
    }

    // Last-chance bin: strong smooth reward, decaying with progress (early saving matters most).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many bins when residuals are high (smooth in mean_residual).
    let mr = mean_residual / cap;
    score += 5.0 * mr * mr * (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * progress);

    // New-bin candidate: smooth penalty that grows with progress and number of open bins,
    // but relaxes if this bin would otherwise waste a lot (high post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + 2.0 * (open_bins_count as f64);
        score -= 10.0 * (1.0 - x); // empty bin has x=1, reduces penalty slightly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residual mod 10 classes ---
    let pr = post_residual;
    let class = pr % 10;
    // Perfect fits (class 0, small residual) are excellent: reward strongly.
    if pr == 0 {
        score -= 60.0;
    } else if class == 0 {
        // residual divisible by 10 -> likely reusable by typical item sizes
        score -= 12.0;
    } else if class <= 2 {
        // tiny dead space: nearly perfect
        score -= 6.0;
    } else if class >= 8 {
        // awkward large dead space mod class
        score += 8.0;
    }

    // Integer-division thresholds on post_residual: which "size bands" fit next?
    // Bands: [1,20), [20,35), [35,50), [50,70), [70,100]
    let band = if pr == 0 { 0 } else if pr < 20 { 1 } else if pr < 35 { 2 } else if pr < 50 { 3 } else { 4 };
    match band {
        0 => score -= 25.0,
        1 => score -= 4.0,
        2 => score += 2.0,
        3 => score += 6.0,
        _ => score += 10.0,
    }

    // Coupling: can the lookahead item (k=2) fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward, scaled by how tightly it fits
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / cap);
        } else {
            // lookahead won't fit: penalize proportionally to wasted opportunity
            let miss = (next_item_size - pr) as f64;
            score += 4.0 + 6.0 * (miss / cap);
        }
        // Harmonic alignment: next item size mod 10 matching residual class
        if next_item_size % 10 == class && next_item_size <= pr {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline: new bin has full 100 residual; make it mediocre by default
        score = 50.0;
        // open new bin if no open bin fits at all, or if this would be a near-perfect fit
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && item_size as f64 >= 0.7 * cap {
            score -= 10.0; // big item: fresh bin is fine
        }
        // late in stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 10.0 * progress;
        }
    }

    // Mean-residual coupling: keep bin residuals balanced around mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Early stream: encourage filling few bins tightly
    if open_bins_count > 0 && step_index < total_items / 10 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful item are pure waste -> heavy penalty.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score -= 40.0; // nearly perfect fit, strongly reward
    } else if (post_residual as f64) < 19.0 {
        // gap below the minimum item size (items >= 10): unusable dead space
        score += 25.0;
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening bins is costly when pressure is low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        // penalize new bins unless the item is large or many bins are open
        score += 20.0 + 30.0 * (1.0 - progress) - 10.0 * pressure;
        if item_size > bin_capacity / 2 {
            score -= 15.0; // large items are fine in a fresh bin
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; a large post residual is then wasted
            score += 0.05 * post_residual as f64;
        }
    }

    // Mild preference to spread across bins when mean residual is high
    score += 0.02 * (bin_residual as f64 - mean_residual);

    // Open-bin pressure: many open bins -> favor filling existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are wasted capacity
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size, penalize near-misses.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 60.0; // perfect 2-chain
        } else if gap <= 10 {
            score -= 25.0 * (1.0 - gap as f64 / 10.0);
        } else {
            score += gap as f64 * 0.15; // mismatch penalty
        }
        // If next item cannot fit anywhere else, prefer keeping space for it.
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 45.0 * crowding - 10.0 * progress;
        // discourage hoarding new bins when plenty already exist
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer consolidating into bins with above-average residual usage.
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful (below min item size 1..100 unknown, use heuristic band).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 20.0 {
        score += 8.0 * (1.0 - dead / 20.0);
    } else if dead == 0.0 {
        score -= 15.0; // perfect closure
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins -> discourage new bins, encourage consolidation.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (mean_residual / bin_capacity as f64);

    // Time horizon: early in stream, be more exploratory (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 10.0 + 25.0 * progress + 0.3 * open_f;
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0; // big item coming, fresh bin may be wise
        }
    } else {
        score -= 8.0 * progress;
    }

    // Mild preference for bins already below mean residual (balance spreading).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Dead-space penalty grows non-linearly as the stream progresses
    score += 8.0 * norm_pr * norm_pr * (0.5 + p2);

    // Reward tight fits more strongly later in the stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + p3);

    // Coupling with mean residual: penalize bins far from the fleet mean
    score += 2.0 * (pr - mean_residual).abs() / cap * (1.0 + p2);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + p2);
    }

    // Lookahead: reward leaving exactly next_item_size, penalize blocking it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Scarcity pressure: when few bins fit, penalize waste mildly
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score += 5.0 * norm_pr * scarcity;

    // New-bin candidate: make it attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * (1.0 - norm_pr);
        score -= 3.0 + 6.0 * fragmentation * (1.0 + p2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes via division into
    // capacity-fraction bands. Small residuals are fine (nearly full), mid residuals bad.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Class 0: post_residual <= 10  -> excellent, strong reward
    // Class 1: 11..=25              -> good
    // Class 2: 26..=50              -> neutral/mediocre
    // Class 3: 51..=100             -> poor (half-empty bin)
    let class = if post_residual <= 10 { 0u32 }
        else if post_residual <= 25 { 1 }
        else if post_residual <= 50 { 2 }
        else { 3 };

    score -= match class { 0 => 60.0, 1 => 30.0, 2 => 0.0, _ => -20.0 };

    // Non-linear dead-space penalty: quadratic in residual beyond half capacity
    if post_residual > bin_capacity / 2 {
        let over = (post_residual - bin_capacity / 2) as f64;
        score += 0.8 * over * over / cap;
    }

    // Perfect-fit harmonic: post_residual divisible into clean classes (0, or exactly
    // a small class like 10/20) get extra harmony reward
    if post_residual == 0 { score -= 80.0; }
    else if post_residual % 10 == 0 && post_residual <= 30 { score -= 15.0; }

    // Lookahead: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally, more if snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit: penalize creating residual that traps nothing
            score += 10.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless existing fits are terrible.
        // Base cost of a fresh bin:
        score += 55.0;
        // Cheaper to open a new bin when many open bins already exist (fragmentation)
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If the current item is large relative to capacity, a fresh bin is natural
        if item_size * 5 >= bin_capacity * 4 { score -= 20.0; }
        // If no other bin fits (fitting_bins_count counts this new bin only in that case
        // context), the +55 is offset by last-chance logic elsewhere; add mild progress bonus
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // next item also large, fresh bin keeps room
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Slight preference for bins with lower residual among equally good fits
    // (use fullest bins first): residual below mean -> reward
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early stream: be a bit greedy with new bins to spread load; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // typical items (below the minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0; // likely unusable
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // If the leftover can fit the next item, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If the leftover cannot fit the next item but is large, it's risky dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 8.0 * open_bins_count as f64 * (0.5 + progress);
        // A new bin is more acceptable when existing residuals are large/fragmented.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    } else {
        // Using existing bins relieves pressure; slightly favor when many bins open.
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let fit_quality = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_quality * fit_quality * bin_capacity as f64;

    // Lookahead: penalize if next item also fits this bin's post-residual (keep it? no—
    // actually reward keeping room for the next item)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // this placement leaves no room for lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins, discourage new bins
    let openness = open_bins_count as f64;
    score += (mean_residual - post_residual as f64) * 0.15;
    if is_new_bin {
        score += openness * 2.0 + 10.0 * t;
    } else {
        score -= 2.0;
    }

    // Time horizon: early on, allow exploration (new bins cheap); late, pack tight
    if t > 0.5 {
        score += 5.0 * fit_quality;
    } else {
        score -= 2.0 * (1.0 - t);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0; // small dead space is fine
    } else if post_residual < 20 {
        score -= 4.0;
    } else {
        // large dead space: penalize more if no future item likely fits (sizes >= 10)
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, non-linearly modulated by stream progress.
    let mut score = x * (1.0 + 2.0 * progress * x) * cap;

    // Polynomial coupling: prefer tight fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= (1.0 + 3.0 * progress) * tightness * tightness * cap * 0.5;

    // Reward near-perfect fills.
    if post_residual <= 2 {
        score -= 50.0 + 50.0 * progress;
    }

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as u32) < next_item_size {
            score += 0.3 * nx * (1.0 + progress);
        } else {
            score -= 0.2 * nx * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: keep it competitive only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild preference toward balancing residuals against the mean.
    score += 0.1 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides into capacity
    let pr = post_residual;
    if pr > 0 {
        // gcd-style harmonic coupling between post_residual and capacity
        let mut g = pr;
        let mut c = bin_capacity;
        while c != 0 { let t = g % c; g = c; c = t; }
        let gcd = g as f64;
        let lcm = (pr as f64) * cap / gcd.max(1.0);
        score -= 8.0 * (gcd / cap); // reward residuals harmonically aligned with capacity
        score += (lcm / cap).ln().max(0.0) * 2.0; // penalize long periods (bad divisibility)

        // Integer division thresholds: residual classes mod common divisors
        let cls10 = pr % 10;
        if cls10 == 0 { score -= 4.0; }        // multiples of 10 are ideal in C=100
        else if cls10 <= 2 { score += 3.0; }   // slivers
        let cls25 = pr % 25;
        if cls25 == 0 { score -= 2.5; }
    }

    // Fraction of capacity consumed by this item
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac; // prefer filling bins heavily

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect pairing
        } else if next_item_size <= pr {
            score -= 6.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here: penalize wasting a good bin
            score += 2.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or few bins fit
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap > 0.6;
        if !big && fitting_bins_count > 0 {
            score += 12.0 + 3.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        if open_bins_count == 0 { score -= 20.0; } // must open first bin
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 4.0 * progress;
    }

    // Mild preference for bins tighter than the mean residual
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the next item are wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (tight but feasible fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening a new one.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // Opening a new bin is attractive only if existing residuals are tiny/dead.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Slight preference for filling bins with larger residuals when few bins open.
        score -= 0.05 * bin_residual as f64;
    }

    // Early in the stream, be more willing to keep bins tidy (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * (next_item_size as f64);
        } else {
            // next item won't fit here; penalize wasted residual
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize large dead space relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny residual is nearly perfect
    }

    // New-bin candidate: make it unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    // Progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 0.9 * (1.0 - post / cap) * (1.0 - post / cap) * cap;

    // Penalize dead space that is too small for typical items
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 0.5 * (post - nxt);
        } else {
            score += 0.35 * (nxt - post).min(40.0);
        }
    }

    // Prefer bins whose residual is below mean (consolidating small residuals)
    let diff = mean_residual - bin_residual as f64;
    score -= 0.15 * diff;

    // Time horizon: early in stream, be more selective about tight fits; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0 * (1.0 - post / cap);

    // Penalize spreading across many open bins when a tight option exists
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * norm_pr * norm_pr);

    // Penalize large dead space quadratically (wasted capacity grows super-linearly).
    score += 18.0 * norm_pr * norm_pr * (1.0 + 0.5 * progress);

    // Reward tight fits: small post_residual gets a discount.
    score -= 22.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mean-residual divergence: prefer bins whose residual deviates smoothly from the mean
    // to consolidate similarly-filled bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Crowd penalty: many open bins -> prefer filling existing ones (smooth in open count).
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powi(2);
    score -= 20.0 * crowd * (1.0 - norm_pr);

    // New-bin candidate: keep it mildly unattractive unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * norm_pr * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, 25, 50) are more reusable than arbitrary remainders.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let harmonic_bonus = if post_residual == 0 {
        -30.0
    } else if post_residual == half || post_residual == quarter {
        -8.0
    } else if post_residual % 10 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small-but-nonzero dead space (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo-class coupling: if the next item exactly fills the post-residual,
    // strongly reward this placement (perfect two-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item still fits afterwards: mild reward, scaled by leftover class
            let leftover = post_residual - next_item_size;
            if leftover == 0 {
                score -= 35.0;
            } else if leftover % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit in this bin afterwards; penalize by gap size
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 15 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Base penalty for opening a new bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, or when many bins are open with slack, prefer
        // consolidating: increase the new-bin penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if open_bins_count > 3 {
            score += 5.0 * (open_bins_count as f64).min(20.0);
        }
        // But if the mean residual is large and this item is large, a fresh bin
        // may be genuinely better: relax the penalty.
        if mean_residual > 0.6 * cap && item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Tight fits are valuable: reward small post-residual non-linearly.
    score -= 30.0 * (-post_residual as f64 / 20.0).exp();

    // Mild pressure to keep mean residual across open bins balanced.
    score += 0.05 * ((mean_residual - post_residual as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=12) are wasted space.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward if the lookahead item exactly fills the post residual (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Slight reward if next item still fits after this placement.
        score -= 8.0;
    } else if next_item_size > post_residual {
        // This placement strands the next item; penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // tighter bins (low residual) rather than spreading load.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += (bin_residual as f64 - mean_residual) * 0.25 * pressure;

    // New-bin candidate: make it attractive only when existing fit is poor
    // (large post residual would leave dead space) or few bins are open.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        if post_residual as f64 >= avg_waste * 0.9 && open_bins_count > 2 {
            score -= 15.0; // fresh bin competitive when current fits are sloppy
        } else {
            score += 30.0; // discourage needless bin proliferation
        }
    }

    // Mild global preference for tight fits scaled by stream progress.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly in the post residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // Reward leaving a small-but-usable gap for the next item.
            score -= 25.0 * (1.0 - (slack_after_next as f64) / (bin_capacity as f64));
        } else {
            // Next item does NOT fit in this bin's residual: penalize wasting
            // space that the lookahead item cannot use.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.35 * overshoot;
        }
    }

    // Relative to mean residual: prefer bins tighter than the fleet average
    // (consume the most constrained space first).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * (post_residual as f64);
    }

    // Penalize the brand-new empty bin candidate mildly, so it is only chosen
    // when open bins would create large dead space or when it enables a
    // perfect chained fit with the lookahead item.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can host both current and next item comfortably.
            score -= 30.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future
        // items to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild penalty for leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 2.5 * frac * frac * bin_capacity as f64;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead (k=2): reward leaving space for the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // perfect pairing
        } else if gap > 0 {
            // next item fits too; reward proportional to how well it uses leftover
            score -= 10.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty scaled by how badly
            score += 0.15 * (-gap) as f64;
        }
    }

    // Dead-space penalty: residuals that can't fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer filling fuller bins when many bins are open (consolidation pressure).
    score += 0.4 * open_bins_count as f64 * frac;

    // Global state coupling: when mean residual is high, discourage spreading waste.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Time horizon: late in stream, tighten packing (avoid opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and if open bins exist.
        score += 25.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // big item coming, new bin may still be reasonable
        }
    } else {
        score -= 8.0 * progress; // favor existing bins more over time
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover residual, mildly
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (large items) -> reward small post_residual more;
    // late, residual waste matters more, so amplify quadratic term.
    let t = progress;
    let pr_norm = pr / cap; // normalized residual in [0,1]

    // Smooth polynomial interaction: quadratic + cubic terms scaled by progress
    let quad = pr_norm * pr_norm * (1.0 + 2.0 * t);
    let cubic = pr_norm.powi(3) * (0.5 + 2.0 * t);
    score += 20.0 * quad + 10.0 * cubic;

    // Reward near-perfect fits smoothly (Gaussian-like bump around post_residual == 0)
    let fit_bonus = (-pr_norm * pr_norm * 40.0).exp();
    score -= 30.0 * fit_bonus;

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let snug = 1.0 - ((pr - n) / cap).abs();
            score -= 12.0 * snug * (0.5 + t);
        } else {
            // penalize residuals that cannot host the next item, scaled by waste
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + t);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mean_norm = mean_residual / cap;
    score += 2.0 * mean_norm * (open_bins_count as f64).ln().max(0.0) * t;

    // New-bin candidate: keep it slightly unattractive unless residual waste of existing bins is severe
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - t);
        // allow new bin when all open residuals are tiny (nothing fits well)
        score -= 15.0 * (1.0 - mean_norm).max(0.0) * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residues that are "perfect partners"
    // for common item sizes (multiples of 10/25/50) are less dead than awkward ones.
    let post = post_residual;
    let partner_bonus = if post == 0 {
        60.0 // perfect closure
    } else if post % 50 == 0 || post % 25 == 0 {
        25.0
    } else if post % 10 == 0 {
        15.0
    } else {
        0.0
    };
    score -= partner_bonus;

    // Penalize awkward residues via integer-division thresholds:
    // small unusable slivers (< 10, min item size) are dead space.
    if post > 0 && post < 10 {
        score += 40.0;
    }

    // --- Lookahead coupling: does post_residual pair harmonically with next item?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits exactly or leaves a good residue
            let nxt_post = post - next_item_size;
            score -= if nxt_post == 0 {
                35.0
            } else if nxt_post % 10 == 0 {
                12.0
            } else {
                4.0
            };
            // harmonic match: next item divides the post-residue evenly
            if post % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            let gap = next_item_size - post;
            score += (gap as f64).min(80.0) * 0.15;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the item leaves a clean harmonic residue there.
        let clean_fit = (bin_capacity - item_size) % 10 == 0;
        let crowded = mean_residual < (item_size as f64) * 0.9;
        if clean_fit && (crowded || open_bins_count == 0) {
            score -= 20.0;
        } else {
            score += 25.0; // prefer filling existing bins by default
        }
    } else {
        // Reward tight fits in existing bins (small relative waste).
        let tightness = 1.0 - (post as f64) / (bin_capacity as f64);
        score -= tightness * 10.0;

        // Reward bins whose residual is below the mean (consolidating fullness).
        if (post as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // --- Stream progression: later in the stream, be greedier about tight fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (bin_capacity - post) as f64 * 0.05;
    }

    // --- Modulo class of item size: items that are capacity fractions (25/50/75)
    // pack predictably; slight bonus for placing them in partially filled bins.
    if item_size % 50 == 0 || item_size % 25 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - 4.0 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Prefer bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
        if post_residual >= 60 {
            score -= 10.0; // large item into fresh bin is fine
        }
    }

    // Mean residual alignment: prefer bins near the mean residual to keep balance.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when post_residual equals next_item_size (perfect 2-step chain)
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item fits in this bin's leftover: reward proportionally to tightness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit leftover: penalize wasted space
            score += 10.0 + diff * 0.3;
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are less attractive targets
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for tighter fits as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // New-bin candidate: only prefer it when residuals are highly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 15.0 - 30.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize wasted space relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize residuals that cannot fit the next item (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving exactly-useful space
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0 + 0.35 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist (new-bin candidate)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count as f64).recip();
        score += 8.0 + 20.0 * pressure * (0.5 + 0.5 * (1.0 - progress));
    }

    // Global state coupling: prefer bins whose residual deviates from mean
    // (consolidate large residuals, avoid fragmenting many similar bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.5 * (dev / (bin_capacity as f64));

    // Prefer filling bins with small residual to close them out
    if post_residual < 10 {
        score -= 9.0;
    }

    // Mild preference for using more-loaded bins as stream progresses
    let load = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * load * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly discounted early (fill bins loosely early on)
    let mut score = pr * (0.55 + 0.45 * progress);

    // Non-linear polynomial coupling of residual waste with stream progress:
    // dead space becomes increasingly costly as the stream advances
    let waste_curve = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 60.0 * waste_curve;

    // Cubic interaction: tiny residuals are gold (near-perfect closure)
    let tight = (1.0 - norm_pr).max(0.0);
    score -= 40.0 * tight * tight * tight * (0.5 + 0.5 * progress);

    // Lookahead: reward residuals that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        let kernel = (-fit_gap / (cap * 0.25)).exp();
        score -= 18.0 * kernel * (1.0 + progress);
        // penalize residuals that strand just below next item size
        if pr < nx {
            score += 12.0 * (nx - pr) / cap * (0.5 + progress);
        }
    }

    // Mean residual deviation coupling: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - 0.5 * progress);

    // Last chance: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a bin early is cheap, late is expensive
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
        score = cap * (0.9 - 0.4 * progress) + 50.0 * open_pressure;
        if next_item_size > 0 {
            // a fresh bin is attractive if next item also large
            score -= 10.0 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins of capacity 100 split into 5 classes
    let cls = (post_residual / 20) as f64; // 0..5
    // Dead-space penalty: residuals that no typical item can use
    let unusable = if post_residual == 0 { 0.0 }
        else if post_residual < 10 { 40.0 }
        else { 0.0 };
    score += unusable;

    // Reward tight fits (post_residual in low harmonic classes)
    score -= 12.0 * (1.0 - cls / 5.0) * (post_residual as f64 / cap);

    // Perfect fit: strong reward
    if post_residual == 0 { score -= 60.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: default preference to reuse open bins
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
        // But if current item is large relative to mean residual, opening new bin ok
        let frac = item_size as f64 / cap;
        score -= 25.0 * frac * frac;
        // late in stream, prefer closing out bins
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * t;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good "filler" target
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Harmonic modulo penalty: residuals like 99..91 (only tiny items fit) are bad
    if post_residual >= 91 && post_residual <= 99 { score += 25.0; }
    // residuals in 50..=59 accept mid items well
    if post_residual >= 50 && post_residual <= 59 { score -= 8.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero dead space.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead-space gap: penalize proportionally (strict avoidance).
        score += (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Marginal zone: mild penalty to prefer bins leaving usable space.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins, pressure grows with open count.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 2.5;
        // Early in the stream, opening a bin is cheaper (spread items out).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead: if the next item can fit into the resulting residual,
    // reward leaving a compatible gap; penalize gaps that block it badly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 6.0;
        }
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
