pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: penalize so existing bins are preferred,
    // but the penalty shrinks as the stream matures.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.08 * open_bins_count as f64 - 3.0 * t;
        // If no open bin can take the item, the new bin is the only choice.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Slightly favor opening a bin early for large items that would
        // otherwise fragment a nearly-full bin.
        if item_size >= bin_capacity / 2 {
            score -= 1.5;
        }
    } else {
        // Lookahead: reward bins whose post-residual can host the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 2.5 + 2.0 * t;
        }
        // Penalize dead space that neither the next item nor small items can use.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 3.0;
        }
        // Near-perfect fit: strongly reward.
        if post_residual < 10 {
            score -= 5.0;
        } else if post_residual < 20 {
            score -= 2.0;
        }
        // Last-chance bin: if this is the only bin that fits, prefer it to
        // avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 4.0;
        }
        // Mild tie-break: prefer bins whose residual is close to the mean
        // (keeps the pool balanced for future items).
        score += 0.03 * (mean_residual - post_residual as f64).abs();
        // Late in the stream, consolidation matters more: penalize leaving
        // large residuals scattered.
        score += 0.02 * post_residual as f64 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with smooth non-linear polynomial shaping
    let mut score = norm_pr * norm_pr * (2.0 + 3.0 * progress) + 0.4 * norm_pr;

    // Dead-space penalty grows as stream progresses (less time to reuse small gaps)
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 2.0 * dead * (0.5 + progress);

    // Coupling with mean residual: avoid scattering space when mean residual is already low
    let mr = mean_residual / cap;
    score += 1.5 * norm_pr * mr;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Lookahead coupling: reward if next item fits into post residual (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 1.2 * (nx / cap) * (1.0 - norm_pr);
        } else {
            score += 0.8 * ((nx - pr) / cap);
        }
    }

    // Mild pressure to consolidate: fewer open bins preferred, stronger late in stream
    score += 0.15 * open_bins_count as f64 * (0.3 + progress) / (1.0 + norm_pr);

    // New-bin candidate: penalize opening new bins early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 2.5 - 2.0 * progress + 3.0 * norm_pr * (1.0 - norm_pr) * 0.0;
        score += 1.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals that are "clean" fractions of capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty grows super-linearly for small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Harmonic classes: post_residual divisible by 5 or 10 is more reusable
    // (items drawn from 1..100 often cluster on multiples of 5/10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Integer-division thresholds: classify residual into coarse bands.
    let band = post_residual / 10;
    score += (band as f64) * 3.0; // prefer tighter fits mildly (post_residual already does this)

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score += 30.0; // near-miss lookahead: risky
            }
        } else {
            // next item can't use this residual; residual likely dead space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets baseline score so that
    // it only wins when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 2.0;
        // If current item is large and few bins fit it, new bin is attractive.
        if item_size as f64 > cap * 0.7 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // room for pairing in fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).sqrt() * (1.0 - pr / cap) * 5.0;

    // Progress-aware tightening: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr / cap) * 20.0;

    // Mean-residual coupling: penalize deviating far below mean residual
    // (wasting a rich bin on a small item) unless it's a near-perfect fit.
    let dev = (mean_residual - pr) / cap;
    if dev > 0.0 {
        score += dev * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // Penalize large leftover gaps that will likely become dead space,
        // scaled by how close post_residual is to the "danger zone".
        let gap = post_residual as f64;
        score += 0.25 * gap * (gap / bin_capacity as f64);
    }

    // Reward tight fits: item consumes most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 15.0; // next item won't fit here -> dead space likely
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Prefer bins with residuals near the current mean (keeps residual distribution balanced).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive if no open bin fits well,
    // i.e. this bin is empty and existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // and stream is early (more items still coming to fill it).
        let base = 45.0 - 20.0 * (1.0 - progress);
        let pressure = (open_bins_count as f64) * 0.8;
        // If the next item is large, a fresh bin is more useful.
        let lookahead_bonus = if next_item_size >= 50 { 8.0 } else { 0.0 };
        score = base + pressure + lookahead_bonus + (bin_capacity - item_size) as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: low post_residual relative to item size.
    let fit_ratio = post_residual as f64 / cap;
    score += 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 10.0 * (next_item_size as f64 / cap);
        // Extra reward if the next item would then fill the bin exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the upcoming item.
        let waste = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        score += 0.25 * waste;
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already below-average residual (denser bins absorb items well).
    score += 2.0 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.3 * (post_residual as f64 / cap) * 100.0;
    }

    // Discourage opening new bins when plenty of open bins fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score = cap * 0.9;
        // At stream start, opening bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If no open bin fits well, opening a new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize new bins when many bins are already open and one fits.
        if fitting_bins_count >= 1 {
            score += 20.0 + 5.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically.
    score += 0.01 * (post_residual as f64) * (post_residual as f64);

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - lookahead_fit / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes mean residual across open bins.
        score += 10.0 + 0.5 * mean_residual;
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        // Many open bins: discourage opening more.
        score += 0.3 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 0.2 * open_bins_count as f64;
    }

    // Prefer bins with residuals close to the item (best-fit flavor) coupled with global state.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Late in the stream, tighten packing aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with a convex penalty
    // on large residuals so near-full bins are strongly favored.
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Non-linear coupling: as the stream progresses, dead space becomes
    // costlier (fewer future items to fill it), so inflate residual penalty.
    let late = progress * progress;
    score += 12.0 * late * pr_norm * (1.0 - pr_norm);

    // Reward bins whose leftover matches the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - diff / cap) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild penalty when this bin is already far below the mean residual
    // (keep residual spread balanced), scaled smoothly.
    score += 3.0 * ((pr - mean_residual) / cap).tanh();

    // Slight preference for keeping fewer open bins late in the stream.
    score += 0.5 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a fresh bin when others fit,
    // unless the item is large enough that a fresh bin is attractive.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * (item_size as f64 / cap);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 200.0;
    } else if post_residual <= bin_capacity / 5 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical items (below min item size 10 -> 1..10 dead zone)
    if post_residual < 10 && post_residual > 0 {
        score += 150.0;
    }

    // Harmonic class: post_residual divisible by common item strides (10, 20, 25, 50)
    let post = post_residual;
    if post > 0 && (post % 50 == 0 || post % 25 == 0 || post % 20 == 0 || post % 10 == 0) {
        score -= 40.0;
    }
    // Odd/awkward classes penalized
    if post % 10 != 0 && post >= 10 {
        score += 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item won't fit here: penalize large leftover
            score += pr * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are poor,
    // but keep it attractive late in the stream or when mean residual is low.
    if bin_residual == bin_capacity {
        score = pr + 30.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Tight-fit coupling: item fills most of the bin
    let fill = (item_size as f64) / (bin_residual as f64);
    if fill > 0.9 {
        score -= 80.0;
    }

    // Stream progression: as stream ends, prefer closing bins tightly (waste less per bin)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;
    score += (mean_residual - pr) * 0.3;

    // Open bins count: many open bins -> prefer filling existing ones over new bins
    if open_bins_count > 5 {
        score += if bin_residual == bin_capacity { 40.0 } else { -10.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (small slack ratio).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 15.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item cannot fit in post-residual but this bin is not the only
    // option, mild penalty for wasting capacity.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, penalize opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean
        // residual is still large.
        score += 35.0 + open_pressure + 0.4 * mean_residual;
        // Allow new bin early in the stream or when it enables a near-perfect
        // split for the current item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 90 {
            score -= 45.0;
        }
        if progress < 0.05 {
            score -= 10.0;
        }
    } else {
        // Filling an existing bin reduces pressure slightly.
        score -= open_pressure * 0.1;
    }

    // Prefer bins below mean residual (consolidating emptier space usage).
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportional to how snug the pair is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(150.0);
        } else {
            // Next item won't fit here: penalize leaving residual the next item can't use.
            score += 80.0;
        }
    }

    // Compare post_residual to mean residual across open bins: prefer bins that
    // tighten the overall distribution (avoid one bin hogging all slack).
    let mean_post = mean_residual - item_size as f64;
    score += 0.5 * (post_residual as f64 - mean_post).abs();

    // Penalize large dead space relative to the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny dead space is fine, essentially full
    } else if post_residual >= 10 && post_residual < 20 {
        score += 20.0; // awkward zone: too small for most items, too big to ignore
    }

    // Last-chance bin: if this is the only bin that fits, favor using it over
    // opening a new bin (penalize the new-bin candidate implicitly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is only good if existing bins are very full (low mean residual).
        score += 400.0 - 300.0 * fragmentation;
        // Early in stream, opening bins is cheaper (more room to consolidate later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
        // If next item is large and this bin is empty, a fresh bin may be ideal.
        if next_item_size >= 60 {
            score -= 200.0;
        }
    }

    // Mild preference to fill bins with more items already (fewer open bins is better).
    score += 2.0 * open_bins_count as f64;

    // Slight nudge toward tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residuals non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Leftover too small for next item: penalize dead space scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Global residual pressure: many open bins with high mean residual
    // -> prefer filling existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= pressure * 15.0;
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New-bin candidate: penalize more when open bins are underused or
        // early in the stream; relax late when fragmentation dominates.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + pressure * 20.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // fresh bin is fine for next item anyway, slight penalty
        }
    }

    // Prefer bins whose residual is close to the item (minimal waste).
    let slack = (bin_residual - item_size) as f64;
    score += slack * 0.15;

    // Mild phase coupling: later in stream, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, keep residuals tight; later, tolerate larger leftovers.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * (1.0 - prn) * progress;
    score += 12.0 * poly * cap / 100.0;

    // Perfect fit reward (smooth, non-linear)
    let fit_quality = 1.0 - prn;
    score -= 20.0 * fit_quality * fit_quality * fit_quality;

    // Penalize creating dead space that can't fit the next item (lookahead k=2)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (1.0 + progress);
        } else {
            // next item fits exactly-ish: reward tight chaining
            score -= 8.0 * (1.0 - (-gap / cap)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - prn);
    }

    // Mild penalty when bin residual deviates from mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: how well leftover divides into useful chunks
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual strongly (tight fit)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else {
        // Harmonic penalty: dead space measured in capacity fractions
        let frac = pr / cap;
        score += 25.0 * frac * frac;
        // Penalize residuals that are awkward: not expressible as small multiples
        let class = post_residual % 10;
        if class != 0 {
            score += 4.0; // non-decade leftover is less reusable
        }
        // Very large leftovers relative to typical next item are fine (keep bin flexible)
        if pr >= 80.0 {
            score -= 10.0;
        } else if pr >= 50.0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 12.0 * fill * (1.0 + progress);

    // Mean residual context: if this bin is much emptier than average, mildly deprioritize
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a bin is only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced when few bins open / early stream
        let mut open_cost = 35.0 - 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            open_cost = -1000.0; // must open
        }
        // if some existing bin gives a tight fit (small post_residual), discourage new bin
        if fitting_bins_count > 0 && post_residual >= 0 {
            open_cost += 20.0 * (1.0 - (item_size as f64 / cap));
        }
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if next item cannot use the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 12.0 * (lookahead_gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin will be exactly closed by next item
        } else if post_residual > next_item_size {
            // next item fits too: mild reward proportional to how well it nests
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit in residual: penalize dead space creation
            score += 10.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable to keep tight
    let rel = if mean_residual > 0.0 { post_residual as f64 / mean_residual } else { 1.0 };
    score += 6.0 * (rel - 1.0).abs() * (if post_residual as f64 > mean_residual { 1.0 } else { -0.5 });

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        // Penalize opening new bins generally
        score += 45.0;
        // But if next item is large and current fit would leave bad residual, ease penalty
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 6.0; // next item won't fit here after placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to prefer the best-fit among them (already via post_residual),
    // but encourage consolidation when many bins are open.
    if open_bins_count > 4 {
        let crowding = (open_bins_count as f64).ln();
        score -= 3.0 * crowding * (1.0 - (post_residual as f64) / cap);
    }

    // Time horizon: early in the stream, be pickier about low-quality fits (long future),
    // late in the stream, accept placements to avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tight;

    // Mean residual coupling: if open bins are generally empty (high mean residual),
    // discourage opening/spreading into new space; prefer filling existing bins.
    let fill_ratio = (bin_residual as f64) / cap;
    if mean_residual > cap * 0.5 && fill_ratio < mean_residual / cap {
        score += 5.0 * (mean_residual / cap - fill_ratio);
    }

    // New-bin candidate handling: penalize opening a fresh bin unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a new bin, discounted when current bin fits are poor
        // (post_residual large) or few bins can fit the item.
        let best_fit_pressure = (post_residual as f64) / cap; // for new bin, = 0; use item context
        let _ = best_fit_pressure;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { (item_size as f64) / cap };
        score += 30.0 - 20.0 * poor_fits;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0; // fresh bin still useful for upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth non-linear polynomial coupling of residual with progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 40.0 * poly;
    // reward tight fits, more so as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (0.5 + progress);
    // penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual) * (1.0 - progress);
    // lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += (next_item_size as f64 - pr) * 0.3;
        }
    }
    // last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }
    // mild preference for consolidating when many bins are open
    score += open_bins_count as f64 * 0.05 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / cap_f;
    score -= 30.0 * fill_ratio;

    // Harmonic class of post_residual: dead space in residue classes.
    // Residuals in low classes (small leftover) are excellent.
    let pr = post_residual;
    let class = pr / (bin_capacity / 4); // 0..3 harmonic quartile
    score += match class {
        0 => -8.0,          // leftover <= 25: nearly perfect
        1 => 0.0,           // 26..50: ok
        2 => 6.0,           // 51..75: wasteful
        _ => 12.0,          // 76..99: very wasteful split
    };

    // Modulo-10 harmonic: exact decade residuals are reusable by typical items.
    if pr % 10 == 0 {
        score -= 4.0;
    }
    if pr % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let nxt_left = pr - next_item_size;
            if nxt_left <= 10 {
                score -= 10.0;
            } else {
                score -= 5.0 * (1.0 - nxt_left as f64 / cap_f);
            }
        } else {
            // next item won't fit here: penalize leaving awkward space
            score += 0.03 * (pr as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should lose unless
    // no decent fit exists (this call is the empty-bin candidate).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -100.0
        } else {
            // penalize new bin more when good fits are available
            40.0 + 8.0 * (fitting_bins_count as f64)
        };
        score += desperation;
    } else {
        // Mild preference for existing bins early vs late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * progress;
    }

    // Prefer balancing residuals toward the mean (avoid many near-full + one huge).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Crowding: with many open bins, prefer filling existing ones tighter.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 range, so anything < 1 is impossible, but small
    // gaps are hard to fill) become dead space. Penalize gaps below a
    // "usable threshold" quadratically.
    let usable_threshold = 20.0f64.min(mean_residual.max(1.0));
    if (post_residual as f64) < usable_threshold {
        score += (usable_threshold - post_residual as f64) * (usable_threshold - post_residual as f64) * 0.8;
    } else {
        // Reward leaving a gap that can host the lookahead item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0;
        }
        // Mild reward for gaps that fit the next item at all.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 4.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // consolidating into existing bins; few open bins -> opening new bins
    // is cheaper so be pickier about bad fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (1.0 - progress * 0.5);

    // New-bin candidate handling: an empty bin has a flat score around
    // capacity minus small offset; adjust so it wins only when all open
    // fits are poor (large post_residual / dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 4.0 + open_bins_count as f64 * 0.5;
        // Late in the stream, prefer closing out existing bins.
        score += progress * 3.0;
        // If next item is huge, a fresh bin is attractive.
        if next_item_size >= 70 {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: bins far below the mean residual are good
    // consolidation targets (they are "almost full").
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good (already base), amplify small leftovers.
    if post_residual > 0 {
        score += 8.0 / post_residual as f64;
    } else {
        score -= 12.0; // perfect fill
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            score += 0.05 * post_residual as f64;
        }
    }

    // Compare post residual against mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.08 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is huge and would leave little residual, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 22.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with fewer open alternatives (consolidation).
    if open_bins_count > 1 {
        score -= 0.3 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual non-linearly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fit_quality * fit_quality;

    // Last-chance bin: heavy bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain potential: exact chain match is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.15 * wasted;
        }
    }

    // Penalize creating small unusable residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 8.0;
    }

    // Global state: when many bins are open with high mean residual,
    // discourage opening new bins (new-bin candidate has residual == capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_item = item_size as f64;
        let expected_fill = avg_item / bin_capacity as f64;
        // New bin is only attractive if open bins are quite full already.
        let openness = (mean_residual / bin_capacity as f64 - expected_fill).max(0.0);
        score += 40.0 * (1.0 - openness) * (0.5 + 0.5 * (1.0 - progress));
        // Slight penalty scaled by number of open bins to limit bin sprawl.
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Prefer bins with residual below the mean (consolidate fuller bins).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * dev;
    }

    // Mild time-horizon modulation: early on, be greedy about tight fits;
    // later, weigh lookahead more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress * (1.0 - fit_quality);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual polynomial in progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (2.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize large dead space more as stream progresses
    score += progress * norm_pr * norm_pr * 30.0;

    // Reward tight fits (small post residual) with lookahead compatibility
    let lookahead_fit = if next_item_size > 0 && (next_item_size as f64) <= pr {
        1.0 - (next_item_size as f64 - pr).abs() / cap
    } else {
        0.0
    };
    score -= 15.0 * lookahead_fit * (1.0 - norm_pr);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize when open bins exist early, favor late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
        score -= 5.0 * progress;
    }

    // Mean residual divergence penalty
    score += 0.3 * (mean_residual - pr).abs();

    // Scarcity term: fewer fitting bins -> prefer this bin smoothly
    score -= 6.0 / (fit + 1.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual by capacity fraction bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Dead-space penalty: residuals just above item sizes are wasteful.
    // Penalize small-but-not-zero residuals (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Integer-division thresholds: post_residual in [1..=eighth] is nearly dead.
    let dead_class = post_residual / 12; // coarse classes of size 12
    score += dead_class as f64 * 5.0;

    // Reward leaving residuals that common item sizes can still fill.
    // Next item lookahead: if next_item_size fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item fills the leftover.
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 150.0 * fill;
            // Modular harmony: post_residual % next_item_size small means chain fits.
            let m = post_residual % next_item_size.max(1);
            score -= (12 - m.min(12)) as f64 * 4.0;
        } else {
            // Next item cannot fit here; leftover likely dead. Penalize by leftover size.
            score += 20.0 + 0.3 * pr;
        }
    } else {
        // Last item: leftover is pure waste; prefer minimal residual.
        score += 0.5 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; penalize mildly so decent existing fits win,
        // but reward when open bins are crowded (high mean residual usage).
        score += 40.0;
        let crowding = 1.0 - (mean_residual / c).clamp(0.0, 1.0);
        score -= 120.0 * crowding;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * progress;
    }

    // Encourage tight fits relative to current residual (best-fit core signal).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // Modulo-4 harmonic bonus: residuals divisible by 4 align with common item grids.
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Penalize creating residual in awkward band (60..=75): too big to ignore, too small for large items.
    if post_residual > 60 && post_residual < 80 {
        score += 25.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or the lookahead item) are unusable waste -> heavy penalty.
    let dead_threshold = 10u32.min(item_size.max(next_item_size));
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // If lookahead item fits perfectly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < dead_threshold {
            score += 15.0; // would create dead space for next item
        }
    }

    // Reward tight fits (small post residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.15 + 0.1 * progress);

    // Prefer bins below mean residual (fill fuller bins first).
    score += (post_residual as f64 - mean_residual) * 0.2;

    // New empty bin candidate: make it unattractive unless current bin is hopeless.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        // But attractive if no open bin fits well (post_residual large scatter).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits relative to mean residual across open bins
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // 2-step lookahead: reward when post_residual exactly matches next item (perfect chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item still fits in leftover: good chain
            score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
            // extra bonus if next item fills bin completely after two placements
            if post_residual - next_item_size == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: leftover becomes dead space unless tiny
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // tiny residue is fine
            } else {
                score += 0.5 * dead; // penalize large unusable leftover
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin fits poorly
    if bin_residual == bin_capacity {
        let poor_fit = bin_residual - item_size;
        // Opening new bin only attractive if it would leave existing bins stranded
        // or item is huge relative to residuals
        let stranded = mean_residual < item_size as f64;
        if stranded || (poor_fit as f64) < 0.25 * mean_residual {
            score -= 6.0;
        } else {
            score += 30.0; // keep using open bins when they fit decently
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (fitting_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual.
    score -= (cap - post_residual as f64).powf(1.7) * 0.35;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize dead space that likely can't be reused by future items.
    if post_residual > 0 && post_residual < item_size {
        score += (post_residual as f64) * 0.9; // stranded fragment
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 18.0 + 0.25 * (post_residual as f64 - nxt);
        } else if nxt > bin_residual as f64 {
            // next item needs a new bin anyway; prefer filling this bin fully
            score -= 8.0;
        } else {
            // next item won't fit here; mildly penalize leaving a bad gap
            score += 6.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation (prefer existing bins over new).
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 5.0;
    }

    // New-bin candidate handling: make empty bin moderately unattractive unless
    // this bin would be a poor host.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * progress; // early stream: new bins ok; later: avoid
        if item_size as f64 > mean_residual && mean_residual > 0.0 {
            score -= 25.0; // no open bin is roomy enough -> new bin is fine
        }
    } else {
        // Prefer bins whose residual is close to the item (good utilization).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += fit_gap * 0.15;
    }

    // Global mean-residual coupling: if open bins are already loose, prefer them.
    if mean_residual > 0.0 {
        score -= 0.05 * (mean_residual - post_residual as f64).abs().recip().min(10.0);
    }

    // Time-horizon modulation: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let mean_r = mean_residual / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = 0.35 * t * t + 0.15 * t + 0.5;
    score += 2.0 * progress_poly * norm_pr * norm_pr * cap;

    // Reward tight fits via smooth cubic of (1 - normalized post residual)
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize when this bin is the only fitting bin (last-chance placement)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Interaction with mean residual across open bins
    score += 1.5 * (norm_pr - mean_r) * (norm_pr - mean_r) * cap * (0.5 + t);

    // Lookahead: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 6.0 * gap * (1.0 - gap);
    }

    // Mild penalty for opening a new bin when many bins are open late in stream
    if bin_residual == bin_capacity {
        score += 4.0 * (open_bins_count as f64 / (1.0 + t * 10.0)) * (1.0 - t);
    }

    // Small dead-space penalty via smooth quartic of residual
    score += 0.05 * pr * pr * pr * pr / (cap * cap * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Harmonic class: integer-division buckets of post_residual (10-wide classes)
    let class = (post_residual / 10) as f64;
    score += class * 3.0;

    // Perfect closure: bin exactly filled
    if post_residual == 0 {
        score -= 50.0;
    }
    // Dead-space class: residual too small for any item (sizes >= 10)
    else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Brand-new empty bin candidate: neutral-high baseline; opened only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 && bin_residual != bin_capacity {
        if (next_item_size as u32) > post_residual {
            score += 5.0;
        } else {
            score -= (next_item_size as f64) * 0.1;
        }
    }

    // Coupling with mean residual across open bins
    score -= (mean_residual - pr) * 0.2;

    // Slight progression pressure: prefer tighter packing late in the stream
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Reward tight fits nonlinearly (smaller post_residual favored more).
        score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // Penalize residuals that cannot fit the smallest plausible item (1..100 unknown, use small bound).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Lookahead: if next item would fit in the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item is large and this placement wastes space, penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit options exist.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // Last chance bin: strongly favor using it to avoid opening a new bin.
        score -= 30.0;
    }
    if open_bins_count > 4 {
        score -= (open_bins_count as f64 - 4.0) * 2.0;
    }

    // New-bin candidate handling: an empty bin has neutral base; only open a new bin
    // if fits elsewhere are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 35.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host anything next; slight discount.
            score -= 5.0;
        }
        // If existing bins are fragmented, opening fresh is less bad.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Mean-residual coupling: prefer bins deviating below mean fill (tighter packing).
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += mean_gap * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual close to next item size (lookahead affinity)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-gap / 12.0).exp();
    }

    // Penalize dead space: residuals too small for any plausible future item
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_useful = 1.0 + 8.0 * (1.0 - progress);
    if post_residual > 0 && (post_residual as f64) < min_useful {
        score += 25.0 * (min_useful - post_residual as f64);
    }

    // Reward tight fits relative to mean residual across open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness);
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - bin_residual as f64).min(20.0);
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual).min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer opening a new bin only when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64
        } else {
            0.0
        };
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score = 90.0 + poor_fit_elsewhere * 0.5 - pressure * 3.0;
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the last fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to waste
            score += 3.0;
        }
    }

    // Penalize opening a new bin when open bins have plenty of slack.
    if bin_residual == bin_capacity {
        score += 30.0;
        score += open_bins_count as f64 * 1.5;
        if mean_residual > item_size as f64 + 10.0 {
            score += 10.0;
        }
    } else {
        // Slight preference for bins with below-average residual (keeps large gaps free).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Early in the stream, be more conservative about filling bins poorly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly non-linear (prefer small but not zero dead space)
    let mut score = pr + 8.0 * pr_norm * pr_norm * cap;

    // Smooth polynomial coupling of residual with stream progress:
    // late in the stream, tighten tolerance for wasted space
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 12.0 * progress * pr_norm * pr_norm * cap;
    score -= 10.0 * progress_coupling * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - pr_norm;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize leaving residual that no typical next item can use (dead space)
    let next_gap = (next_item_size as f64 - pr).abs();
    if next_item_size > 0 {
        score -= 6.0 * (-next_gap / 20.0) * (-next_gap / 20.0);
        if pr >= next_item_size as f64 {
            score -= 5.0; // next item can still fit here
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference to spread across bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Keep empty new-bin candidates neutral-to-slightly-attractive only for huge items
    if bin_residual == bin_capacity {
        score += 4.0 - 8.0 * (item_size as f64 / cap);
    }

    // Mean residual alignment: prefer bins whose residual is close to mean (balanced packing)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let r = post_residual;

    // Perfect fit: harmonic anchor, heavily rewarded.
    if r == 0 {
        score -= 40.0;
    }

    // Harmonic classes: residuals divisible by common item-size increments
    // are more likely reusable by future items.
    if r % 10 == 0 {
        score -= 5.0;
    }
    if r % 25 == 0 {
        score -= 3.0;
    }
    if r % 50 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Reward a tight lookahead fit (small leftover after next item too).
            score -= 10.0 + (r - next_item_size) as f64 * 0.05;
        } else {
            // Residual is dead space with respect to the next item.
            score += 8.0;
        }
    }

    // Integer-division threshold: residual that can hold at least half of
    // typical items is more valuable than residual below the small-item floor.
    if r >= 10 && r < 25 {
        score += 2.0; // awkward mid-range residual
    }
    if r > 0 && r < 10 {
        score += 6.0; // unusable sliver: strong penalty
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalized so it only wins when every open
    // bin offers a poor fit. Slight scaling with fleet size / stream phase.
    if bin_residual == bin_capacity {
        score = 30.0 + 0.3 * open_bins_count as f64
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can absorb the lookahead item
        }
    }

    // Deviation from fleet mean residual: prefer bins whose post residual
    // tracks the average, keeping the fleet balanced.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept the smallest plausible item are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Coupling with lookahead: prefer bins whose post_residual can still
    // accommodate the next item, penalize those that strand the lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation as the number of open bins grows.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a tight fit already — favor packing it further.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }

    // Mild progress term: late in the stream, prefer tighter packing.
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // next item exactly fills this bin
        } else if post_residual > next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward leaving just enough for the next item, scaled by tightness.
            score -= 30.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            if next_post == 0 {
                score -= 20.0; // chain fill: both items exhaust the bin
            }
        } else {
            // Next item can't follow in this bin; penalize proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative-to-mean coupling: prefer bins already below mean residual (tighter).
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // Penalize new bins mildly; more when many bins already open.
        score += 12.0 + 2.0 * open_pressure.sqrt();
        // But if item is large and would leave big dead space anyway, new bin
        // can be competitive: reduce penalty when item barely fits a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small regularization toward balance across open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powf(3.0) * 30.0;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward when next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
        // Perfect chain: post_residual exactly fits next item.
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 12.0;
        }
    } else {
        // Last item: prefer fullest bin, discard leftovers freely.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the tightest (post_residual term already does this).
        score += 2.0;
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 1.5 {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate logic: opening a new bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 * 0.6;
        // Early stream: opening bins is fine.
        score -= progress * 10.0;
        // If the item barely fits anywhere else, new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if fitting_bins_count == 1 && bin_residual - item_size > 0 {
            // Compare: only one fitting bin, and it would leave lots of dead space.
            let waste_elsewhere = (bin_residual as f64 - item_size as f64);
            if waste_elsewhere > 30.0 {
                score -= 10.0;
            }
        }
        // Lookahead synergy: fresh bin can host both current and next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Late stream: consolidate, avoid opening new bins.
        score += progress * 20.0;
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins with residuals near the item (waste-avoidance coupling).
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += diff * 6.0;

    // Non-linear coupling: penalize mid-range post_residuals (hard-to-fill slivers).
    if post_residual >= 10 && post_residual <= 25 {
        score += 8.0 * (1.0 - ((post_residual as f64 - 17.5).abs() / 7.5));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // residual waste matters more as the stream progresses.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * prn * prn * cap * 0.5;

    // Perfect-fit reward (smooth gaussian-like bump on zero post-residual)
    score -= 25.0 * (-(prn * prn) / 0.01).exp();

    // Lookahead coupling: reward residuals that leave room for the next item,
    // penalize residuals that nearly-but-not-quite fit it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        let gapn = gap / cap;
        if gap >= 0.0 {
            score -= 12.0 * (-(gapn * gapn) / 0.004).exp();
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for crowding when many bins fit, prefer tighter fits
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins below mean residual (tighter bins), smoothly.
    let diff = (mean_residual - pr) / cap;
    score += 5.0 * diff * (1.0 - progress);

    // Mild penalty for opening new bins early in the stream.
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (15.0 - 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // small-item-friendly chunks. Residuals that are multiples of common
    // small sizes are reusable; awkward residuals are penalized.
    let c = bin_capacity as f64;

    // Penalize dead space that is too small to hold a plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic divisibility bonuses: post_residual divisible by small
    // denominators is "usable space" -> reward.
    let pr = post_residual as f64;
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: classify residual into harmonic bands
    // (quarter, half, three-quarters of capacity).
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score += 12.0,   // tiny leftover: nearly dead
        1 => score += 4.0,    // quarter residual
        2 => score -= 2.0,    // half residual: excellent
        3 => score -= 5.0,    // three-quarters: great
        _ => {}               // full (new bin)
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic class of the next gap: post_residual % next_item_size
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; slight penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += (over / c) * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has a large baseline score;
    // make it attractive only when open bins are crowded on average.
    if bin_residual == bin_capacity {
        score = c - mean_residual * 0.5 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps (< 10) are penalized
    // heavily beyond their raw residual value since they are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += fit_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the leftover, penalize dead space more.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins whose residual is below the mean (fill the emptier-feeling bins),
    // i.e. penalize bins with large residuals relative to mean slightly.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin's raw score is (capacity - item_size),
    // which is usually large; add a small fixed surcharge so it only wins when
    // existing bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post_residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose residual after placement
    // can accommodate the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // exact chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps future options balanced.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits more aggressively.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin is a fallback. Penalize opening
    // a new bin mildly so it only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 150.0 * (1.0 - progress);
    }

    // Mild penalty for waste scaled by item size (large items deserve tight bins).
    score += 0.3 * (post_residual as f64) * (item_size as f64 / bin_capacity as f64);

    // Slight preference to spread load when many bins are open.
    score += 0.1 * (open_bins_count as f64).ln() * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core with non-linear tightening: exact fits heavily rewarded.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += 8.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Reward near-exact fits (post_residual small but nonzero).
    if post_residual > 0 && post_residual < 12 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize leaving dead space that no plausible future item (10..80) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * 0.35 + mean_residual * 0.05;
        let poor_alternatives = (fitting_bins_count == 0) as f64 * 30.0
            + (fitting_bins_count == 1) as f64 * 10.0;
        // Base cost of a fresh bin, discounted by global pressure and poor fits.
        score = 40.0 + 25.0 * (1.0 - progress) - pressure.min(30.0) - poor_alternatives;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin useful for upcoming big item too
        }
    }

    // Mild time-varying exploration bias.
    score += ((step_index % 7) as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let base = post * (0.55 + 0.9 * prog2 + 1.6 * prog3);

    // Reward near-perfect fits smoothly (quartic in tightness)
    let fit_reward = -6.0 * tight * tight * tight * tight * cap * 0.01;

    // Dead-space penalty: quadratic in post_residual, amplified late in stream
    let dead = 0.004 * post * post * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward; else penalize smoothly
    let nxt = next_item_size as f64;
    let lookahead = if nxt > 0.0 {
        let diff = nxt - post;
        -3.0 * (1.0 / (1.0 + diff * diff / 50.0)) + 0.02 * diff.max(0.0)
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // Mild penalty for spreading across many bins
    let spread = 0.15 * open_bins_count as f64 * (0.3 + progress);

    base + dead + fit_reward + lookahead + last_chance + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/2, 3/4 of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap * 0.25;
    let half = cap * 0.5;

    // Penalize leftovers in "dead zones": too small for typical items
    // but too large to ignore. Use integer-division thresholds.
    if post_residual > 0 {
        let dead_class = (post_residual / 10) % 3; // harmonic class mod 3 on decile
        match dead_class {
            0 => score += 12.0,          // tiny slivers: nearly unusable
            1 => score += 4.0,           // awkward mid slivers
            _ => score -= 2.0,           // large usable chunks
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Fraction-of-capacity coupling: prefer bins whose fill crosses
    // the half-capacity harmonic boundary with this placement.
    let pre_frac = bin_residual as f64 / cap;
    let post_frac = pr / cap;
    if pre_frac >= half && post_frac < half {
        score -= 15.0; // crossing 1/2 boundary: good compaction
    } else if pre_frac >= quarter && post_frac < quarter {
        score += 8.0; // falling into 1/4 dead zone is risky
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // reward heavily; if next item would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += 6.0; // bin closes anyway; mild penalty vs alternatives
        } else {
            let gap = post_residual - next_item_size;
            score += (gap % 7) as f64 * 1.5; // harmonic jitter on gap
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when open
    // bins have poor residuals or many bins are already open.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let pressure = mean_residual / cap; // high mean residual = open bins are roomy
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base + pressure * 40.0 - progress * 10.0
            + (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large items into fresh bins
        }
    }

    // Small progress-based tie-breaker: later in stream, be greedier
    // about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 + (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0; // moderate waste zone
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; allow opening new bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // New-bin candidate handling: an empty bin has large residual; make it
    // competitive only when no existing bin gives a good fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        } else if fitting_bins_count == 1 {
            // last-chance bin exists; opening new bin is only ok if the fit
            // would be terrible (large post_residual in that bin is unknown,
            // so rely on mean residual as proxy).
            if mean_residual - item_size as f64 > 25.0 {
                score -= 30.0;
            }
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: leftover becomes dead space
        score += 8.0;
    }

    // Mean residual coupling: placing into a bin with below-mean residual
    // (tighter bin) is favored, balancing residual spread.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; penalize large leftover.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus: exact fill of the bin.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small dead space that likely can't fit future items (min size 1..10)
        score += 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            // Next item won't fit here; mildly penalize large leftovers that invite waste
            (next_item_size - post_residual) as f64
        };
        // Exact match for next item is highly desirable
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        score += 0.5 * gap;

        // If the next item fits exactly after this placement, strong bonus
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // If next item cannot fit in post_residual and post_residual is too small
        // for typical items, penalize (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Relative-to-mean coupling: bins with residuals above the mean are better
    // candidates to consume (keep low-residual bins tight for small items).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when no good
    // fit exists among open bins (high post_residual elsewhere, or item barely fits).
    if bin_residual == bin_capacity {
        // Default moderate score for a new bin.
        score = 60.0;
        // If item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If many open bins already, discourage opening another.
        score += 2.0 * open_bins_count as f64;
        // Lookahead: if next item is large, having a fresh bin may help.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 14.0 * tightness * tightness;

    // Penalize creating small dead space that nothing (>=10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Wasted residual that the next item cannot use.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin would leave a large unusable gap, or the fit is terrible.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Late in the stream, consolidate into existing bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 12.0 * progress - 20.0 * fit_ratio;
        // If many bins are open and fragmented, prefer reusing one.
        score += 0.6 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0; // fresh bin pairs well with the next item
        }
    }

    // Global fragmentation pressure: bins with residual far below the mean
    // are valuable; placing here keeps uniform, usable residuals.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.25 * diff;

    // Mild preference for bins with moderate (not huge) residual to avoid
    // dumping items into the most flexible bins unnecessarily.
    if bin_residual != bin_capacity && (bin_residual as f64) > mean_residual + 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Squared/cubic terms smooth-shape the preference for tight fits.
    let norm_pr = pr / cap; // in [0,1]
    let p = progress;
    // Early stream: emphasize waste strongly; late stream: relax slightly.
    let waste_weight = 1.0 + 0.8 * (1.0 - p) * (1.0 - p) - 0.3 * p * p;
    score += waste_weight * norm_pr * norm_pr * cap * 0.5;

    // Perfect-fit reward (smooth, no piecewise cutoffs).
    score -= 40.0 * (1.0 - norm_pr).powi(8);

    // Dead-space penalty for residuals too small to ever host typical items.
    let deadness = ((35.0 - pr).max(0.0) / 35.0).powi(3);
    score += 25.0 * deadness;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 30.0 * (1.0 - p);
    }

    // Lookahead: reward if next item fits the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 15.0 * snug * snug;
        } else {
            // Penalize leaving a residual that blocks the next item.
            score += 10.0 * ((nxt - pr) / cap).powi(2);
        }
    }

    // Mild preference for consolidating into fewer bins late in the stream.
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * p);

    // Compare against mean residual: bins far below mean waste potential.
    score += 0.3 * (mean_residual - pr).max(0.0);

    // New-bin candidate adjustment: allow opening when open bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted early (amortization over stream).
        score = cap as f64 * 0.85 - 50.0 * (1.0 - p);
        // If this bin would be the only fitting option, opening is cheap.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "clean" fractions
    // of capacity (multiples of 10, 20, 25, 50) since future items align better.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect closure, strongly favored
    } else if pr % 50 == 0 {
        -14.0
    } else if pr % 25 == 0 {
        -10.0
    } else if pr % 20 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward residual, penalize
    };
    score += harmonic_bonus;

    // Coupling with next item: reward residuals that can exactly host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            // next item still fits, but leftover after it matters
            let nxt_left = post_residual - next_item_size;
            score += (nxt_left as f64) * 0.35;
            if nxt_left % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by shortfall
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's
    // genuinely needed (few fitting bins or large item).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // opening new bin attractive only for big items late in stream with many open bins
        let bonus = -6.0 + 14.0 * pressure * (0.5 + 0.5 * progress) + 8.0 * item_frac;
        score += bonus.max(0.0) * 2.0;
    }

    // Spread-awareness: bins far from the mean residual are slightly penalized
    // to keep residual classes homogeneous (harmonic grouping).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Mild preference for tighter fills as stream progresses
    score += (1.0 - (post_residual as f64) / cap) * -3.0 * (step_index as f64 / (total_items.max(1) as f64));

    // Integer division threshold: penalize residuals in "dead zones" (1..9)
    if pr > 0 && pr < 10 {
        score += 9.0 - pr as f64; // smaller dead space is worse than larger
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else if post_residual >= 10 {
        // Reward tight-but-usable fits (small usable residual preferred).
        score -= 25.0 / post_residual as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Open-bin pressure: with few open bins, prefer using them over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) + 1.0;
    score += 3.0 * pressure * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the mean (balance load).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 55.0 - 0.4 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large consecutive items favors a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is great.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space that next item cannot use (2-step lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // Dead space for the next item: penalize proportionally to waste.
            score += (nxt - post_residual as f64) * 1.5;
        } else {
            // Reward leaving room exactly for the next item.
            score -= (post_residual as f64 - nxt).abs() * 0.8;
        }
    } else {
        // Last item: pure tight-fit bonus.
        score -= 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize many-fitting-bin waste slightly by residual relative to mean.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 100.0 - 30.0 * progress;
        // If next item would combine with this one into a fresh bin nicely, discount.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            new_bin_score -= 25.0;
        }
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Scarcity pressure: when few bins fit, favor existing bins over new ones.
    if fitting_bins_count <= 2 {
        score -= 10.0 / fitting_bins_count as f64;
    }

    // Penalize opening new bins when many bins already have ample room.
    if bin_residual == bin_capacity {
        let slack = mean_residual - item_size as f64;
        if slack > 0.0 {
            score += 15.0 + slack * 0.4;
        }
        // Early in the stream, opening bins is cheap; later it is costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Reward keeping mean residual aligned: prefer bins near the mean.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild bonus for filling bins deeply as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Tiny tie-breaker favoring bins with more residual (keeps big gaps for big items).
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, smoothly penalized non-linearly
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Coupling post_residual with stream progress: early on tolerate waste,
    // later become progressively stricter about large residuals
    let progress_tightening = 1.0 + 1.5 * progress * progress;
    score *= progress_tightening;

    // Smooth interaction: small post_residual that also matches the next item
    // is doubly valuable (perfect chain fit) -> strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        let chain_fit = (-gap * gap * 20.0).exp();
        score -= 12.0 * chain_fit * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Reward tightening relative to the fleet's mean residual (consolidation)
    score -= 0.15 * (mean_residual - pr);

    // Mild penalty for proliferating bins when many are already open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate (empty bin): its post_residual equals capacity,
    // which already scores high; add a smooth extra penalty so it only wins
    // when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 20.0 * (1.0 - (fitting_bins_count as f64).recip());
    }

    // Smooth tiny coupling between item size and residual (big items want snug bins)
    score += 0.02 * (item_size as f64 / cap) * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "clean"
    // divisions of capacity (likely to be exactly filled later).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fill reward: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo harmonic classes on post_residual relative to capacity.
    // Residuals that divide capacity evenly (e.g. 50, 25, 20, 10) are reusable.
    let harmonic_divisors: [u32; 8] = [50, 25, 20, 10, 5, 4, 2, 1];
    for d in harmonic_divisors.iter() {
        if bin_capacity % d == 0 && post_residual % d == 0 && post_residual > 0 {
            score -= 6.0 * (d as f64 / 50.0);
            break;
        }
    }

    // Penalize awkward dead space: residuals in (0, 10) are nearly unusable
    // given typical item sizes; also penalize 11..=19 range mildly.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let npr = post_residual - next_item_size;
            // Reward if the chain leaves another clean residual.
            if npr == 0 {
                score -= 18.0;
            } else if npr < 10 {
                score += 6.0; // chain would create dead space
            }
        } else {
            // Next item won't fit here anyway; slight penalty for tiny residuals.
            if post_residual < next_item_size && post_residual < 20 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * (post_residual as f64);
    }

    // New-bin candidate handling: empty bin gets a moderate base cost so we
    // prefer reusing open bins with good fits, but opening is preferred over
    // leaving huge unusable dead space in a partially-filled bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses
        // (amortization) and with fewer open bins relative to items seen.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.35 - 10.0 * progress;

        // If the item is large, a fresh bin is naturally attractive.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        // If many bins are open with large mean residual, prefer reusing them.
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // Last item: no point opening a new bin if anything fits elsewhere.
        if next_item_size == 0 && fitting_bins_count >= 1 {
            score += 40.0;
        }
    }

    // Mild tightening pressure: prefer bins whose residual is below the mean
    // (concentrate fill), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0 * progress;
        } else {
            score += 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small for any
    // plausible future item (items >= 1, but realistically >= 10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
