    score -= 2.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. this bin's residual is far below mean residual (poor fit).
    if bin_residual == bin_capacity {
        // New bin starts with full residual; penalize so it is chosen only
        // when existing fits are bad (their scores get dead-space penalties).
        let spread = mean_residual - post_residual as f64;
        if spread < 0.0 {
            // Existing bins have small residuals -> opening new bin is good.
            score -= 35.0 + (-spread) * 0.5;
        } else {
            score += 25.0 + spread * 0.3;
        }
        // Early in stream, prefer consolidating into open bins less strongly.
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; if post_residual is tiny, extra penalty.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect/near-perfect match with next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight two-item packing bonus
        score -= 12.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0);
        // Exact match jackpot: next item fills bin completely
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that neither fits next item nor is small
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer fullest packing
        score -= 10.0;
    }

    // Prefer bins already below mean residual (dense bins absorb waste better)
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
        // Opening a new bin is fine if the item is large and fits well anyway
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // Avoid new bin late in stream if few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Small penalty shaping: mildly favor tight fits nonlinearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold a typical item (min size 1, but
    // residual below ~10 is rarely reusable).
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill, big reward
    } else if post_residual < item_size {
        // dead space smaller than next possible item is semi-useless
        score += 4.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 2.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists. Base penalty grows with usable open capacity.
    if bin_residual == bin_capacity {
        let open_usable: f64 = mean_residual * open_bins_count as f64;
        let pressure = if item_size as f64 <= open_usable / open_bins_count.max(1) as f64 { 1.0 } else { 0.0 };
        score += 10.0 + 0.5 * open_bins_count as f64 + 20.0 * pressure;
        // but if current bin is a terrible fit (huge waste), soften the penalty
        let waste = bin_capacity.saturating_sub(item_size) as f64;
        if waste > 60.0 {
            score -= 18.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins with below-average residual (keeps a spread
    // of residual sizes available for future items).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling: penalize large residuals more as stream progresses
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    // Reward tight fits (small post_residual) with smooth decay
    score -= 25.0 * (-norm_pr * 8.0).exp();
    // Penalize waste relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual).abs();
    // Lookahead coupling: reward leaving space for next item, penalize blocking it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_next = (pr >= ni) as i32 as f64;
        score -= 12.0 * fit_next * (1.0 - norm_pr);
        score += 8.0 * (1.0 - fit_next) * (1.0 - progress);
    }
    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }
    // Mild penalty for opening new bins early in the stream
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (10.0 + 15.0 * progress);
    // Penalize very many open bins slightly
    score += 0.05 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near 0 are "perfect" closures.
    let post = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward near-exact fills (dead space ~ 0).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        // dead space below min item size is unusable — mild reward anyway
        score -= 8.0;
    }

    // Harmonic classes: post_residual in (0,10], (10, quarter], (quarter, half], ...
    if post_residual > 10 && post_residual <= quarter {
        // small-but-usable residue: mild penalty to prefer tighter fits
        score += 6.0;
    } else if post_residual > quarter && post_residual <= half {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 5 {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residue: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // modulo harmony: next_item_size divides-ish the residue
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64;
        let new_bin_base = cap * 0.35 + tightness * 0.5;
        // penalize opening new bins early in the stream / when many open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = new_bin_base + open_bins_count as f64 * 4.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size > item_size && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0; // fresh bin can host the bigger lookahead item
        }
        if fitting_bins_count > 0 && item_size <= 60 {
            score += 15.0; // discourage abandoning open bins for small items
        }
    }

    // Mild pressure toward bins with below-mean residual (consolidate).
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; residuals below a "usable" threshold are heavily penalized.
    let usable_threshold = 12.0f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if (post_residual as f64) < usable_threshold {
        // Unusable dead space: quadratic penalty on top of raw residual.
        let dead = usable_threshold - post_residual as f64;
        score += dead * dead * 2.0 + 25.0;
    }

    // Tightness reward: how well the item fills this bin relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 20.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward
    // this placement (chaining); if next item nearly fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual + 8 {
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins; mildly prefer
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is close to the mean (keep residuals uniform,
    // leaving large shared gaps for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: penalize opening a new bin, scaled by how many bins
    // already fit the item and how early in the stream we are.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 40.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            new_bin_penalty += 25.0 * fitting_bins_count as f64;
        }
        // If the resulting residual would be very small (near-perfect pack into
        // a fresh bin), allow it despite the penalty.
        if post_residual <= 5 {
            new_bin_penalty -= 50.0;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when next item exactly
    // fills the post_residual (perfect chain), penalize mismatch.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let gap = pr - nr;
            // Perfect lookahead fit: big bonus proportional to gap smallness.
            score -= 0.9 * (bin_capacity as f64 - gap) / bin_capacity as f64 * 20.0;
            // Extra reward if gap is zero.
            if gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here: mild penalty scaled by overflow.
            let overflow = nr - pr;
            score += 0.35 * overflow;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average residual is good (consolidation).
    let pr = post_residual as f64;
    score += 0.5 * (mean_residual - pr);

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        // But if post_residual would be a useless sliver, soften the bonus.
        if post_residual < 10 && post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate (empty bin): default score = capacity - item_size.
    // Penalize opening a new bin when decent fitting bins exist, unless
    // the item is large and current bins would leave heavy fragmentation.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        let frag = if next_item_size > 0 && post_residual > 0
            && (next_item_size as u32) > post_residual
        { 6.0 } else { 0.0 };
        score += fit_pressure - frag;
        // Late in the stream, opening new bins is cheaper (fewer future regrets).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Small penalty for many open bins: prefer consolidating into fewer bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional to wasted fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fills of the bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 8.0;
        }
        // Perfect two-item packing: this item + next item exactly fills bin.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // New-bin candidate handling: only attractive when existing fits are bad.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when it beats poor fits.
        score += 30.0;
        // If mean residual across open bins is large, prefer reusing bins.
        score += 0.35 * mean_residual;
        // Early in stream, slightly discourage bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress);
        // If many bins already fit the item, new bin is clearly worse.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // Large item with no good reuse: new bin becomes reasonable.
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    } else {
        // Mild penalty per open bin to discourage hoarding many half-empty bins.
        score += 0.15 * open_bins_count as f64;
    }

    // Time-horizon modulation: late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits via non-linear post-residual penalty
    let mut score = (pr / cap).powf(1.6) * 120.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (bins get filled later);
    // late, punish residual waste more aggressively.
    let progress_coupling = 0.5 + 1.5 * progress * progress;
    score += pr * 0.35 * progress_coupling;

    // Non-linear interaction: residual^2 scaled by progress
    score += (pr * pr) / (cap * cap) * 40.0 * progress;

    // Reward high fill ratio smoothly
    score -= fill * fill * 25.0;

    // Last-chance bin: strong smooth bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize opening new bins when many bins are already open,
    // coupled smoothly with mean residual (fragmentation indicator)
    let frag = (mean_residual / cap).clamp(0.0, 1.0);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (30.0 + 50.0 * frag * frag + 20.0 * progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        score -= fits_next * (15.0 + 10.0 * (pr - next_item_size as f64) / cap);
        // penalize leaving residual too small for typical next items
        let near_miss = ((pr - next_item_size as f64).abs() / cap).powi(3);
        score += near_miss * 20.0;
    }

    // Mild smooth penalty on spreading across many bins
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "dead"
    // classes (small, unusable slivers) should be penalized; residuals that
    // match common item-size-friendly classes should be rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity harmonic: reward residuals that are exact
    // divisions of capacity (50, 25, 20, 10...) since future items can tile them.
    let harmonic_bonus = if post_residual > 0 {
        let mut h = 0.0;
        for d in [2u32, 4, 5, 10, 20, 25, 50] {
            if bin_capacity % d == 0 && post_residual % (bin_capacity / d) == 0 {
                h += 3.0 / (d as f64).sqrt();
            }
        }
        h
    } else {
        6.0 // perfect fill
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual <= 15 {
        score += 8.0;
    }

    // Modulo-class coupling with next item: if the next item fits exactly
    // into post_residual, strongly reward; if it nearly fits, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (-gap / 20.0).exp();
        } else {
            // next item can't use this bin's residual: slight penalty scaled
            // by how much would be wasted relative to mean residual
            score += 0.15 * ((next_item_size - post_residual) as f64).min(cap) / cap * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // is large and open bins are crowded (mean residual small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded && item_size >= 50 {
            score -= 12.0 + 8.0 * progress;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference to pack into bins with residual close to item size
    // (tight fit reward) using integer division threshold classes.
    let tight_class = bin_residual / item_size.max(1);
    if tight_class == 1 {
        score -= 4.0;
    } else if tight_class >= 3 {
        score += 2.0 * (tight_class as f64 - 2.0);
    }

    // Slight normalization by capacity so score stays comparable.
    score * (100.0 / cap)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual as i32 as f64) * 4.0;
    }
    // Gaps of 10..19 are semi-dead for typical item ranges: mild penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still host a plausible future item (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact lookahead fit is ideal.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    // Lookahead dead zone: next item just barely misses this bin.
    else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Open bins pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.7;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins with residual far below mean residual (fragmented bin).
    let res = post_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual) * 0.15;
    } else {
        score += (mean_residual - res) * 0.15;
    }

    // Early in the stream, be slightly more willing to open fresh bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item fills bin completely afterwards
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Penalize if post_residual cannot host next item but is small (dead space)
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer minimal residual
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight" -> good targets
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize wasting a very full bin on a small item
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.3 && bin_residual < bin_capacity {
        score += 10.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0
            - 10.0 * stream_progress
            - 0.5 * open_bins_count as f64;
        // If next item is large, opening fresh bin may enable pairing
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Reward exact/near-exact fits heavily.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize bins whose residual is much larger than the mean (wasteful use of a roomy bin)
    // unless this is the only fitting bin (last-chance placement).
    if fitting_bins_count > 1 && (bin_residual as f64) > mean_residual + 20.0 {
        score += 8.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    // (dead space), reward residuals that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Early in the stream: keep bins flexible (prefer moderate residuals for future items).
    // Late in the stream: just fill bins as tightly as possible.
    if progress < 0.5 {
        score += 5.0 * (1.0 - progress * 2.0);
    } else {
        score -= 5.0 * (progress - 0.5) * 2.0;
    }

    // Many open bins: discourage spreading across bins; prefer consolidating into fewer bins.
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely the best option
    // (i.e., no open bin fits well). Base post_residual=100 already scores high;
    // add extra penalty scaled by how many bins could fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + 10.0 * fitting_bins_count as f64;
        } else {
            score -= 10.0; // no alternative: opening is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_curve = 1.0 + 0.6 * progress - 0.4 * progress * progress;
    let mut score = norm_post * (1.0 + 0.8 * prog_curve * fit_ratio);

    // Non-linear reward for tight fits (small post_residual), stronger late in stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + 0.7 * progress);

    // Penalize dead space relative to next item (smooth interaction)
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (norm_post - nxt).max(0.0);
        score += gap * gap * 1.5;
        let exact = (norm_post - nxt).abs();
        score -= (1.0 - exact.min(1.0)) * 0.4;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.2 * dev * dev;

    // New-bin candidate: smooth baseline that tight fits must beat
    if bin_residual == bin_capacity {
        score += 0.35 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 (dead-space classes)
    let residue = post_residual % 10;
    // Residues 1..9 (nonzero, non-aligned) are "dead space" prone -> penalize
    if residue != 0 {
        score += (10 - residue) as f64 * 1.5;
    } else {
        // perfectly aligned residual (0,10,20,...) -> reward
        score -= 4.0;
    }

    // Integer-division thresholds on post_residual: classify usability
    let usable_class = post_residual / 10; // how many 10-sized items fit
    score -= usable_class as f64 * 2.0;

    // Next item lookahead: if next item fits in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 + (slack % 10) as f64 * 0.8;
        } else {
            // next item won't fit here: mild penalty scaled by overshoot class
            let over = next_item_size - post_residual;
            score += (over / 10) as f64 * 1.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Coupling with mean residual: bins far below mean residual are wasteful targets
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 3.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 2.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // opening a new bin costs: penalize more when many bins open or late in stream
        score += 25.0 + crowd * 0.8 + progress * 5.0;
        // but if item is large and would leave tiny residue anywhere, fresh bin is fine
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Exact fit: zero residual is perfect
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small for the smallest plausible item
    // (1..100 range -> treat gaps < 10 as near-dead, < 25 as partially dead).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 60.0 * (10.0 - gap) / 10.0; // tiny slivers: strong penalty
    } else if gap >= 10.0 && gap < 25.0 {
        score += 18.0 * (25.0 - gap) / 15.0; // partially usable gap
    }

    // Reward tight fits (perfect or near-perfect packing).
    if gap == 0.0 {
        score -= 120.0;
    } else if gap <= 5.0 {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if gap >= next {
            let slack = gap - next;
            if slack < 5.0 {
                score -= 70.0; // next item nearly fills this bin
            } else {
                score -= 25.0 * (1.0 - slack / gap.max(1.0));
            }
        } else {
            // next item cannot reuse the gap -> dead space risk
            score += 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin for a marginal gain.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 30.0 * pressure * (gap / bin_capacity as f64);

    // Mean residual coupling: bins with residual far below mean are scarcer to fill;
    // favor bins whose gap is close to the mean residual (balanced packing).
    let dev = (gap - mean_residual).abs();
    score += 8.0 * (dev / (mean_residual + 10.0));

    // New-bin candidate: baseline anchored slightly above a good existing fit,
    // but attractive when existing bins would create dead space or none fit well.
    if bin_residual == bin_capacity {
        score = 35.0 + 0.15 * open_bins_count as f64 + gap; // gap == capacity here
        if next_item_size > 0 && (next_item_size as f64) >= 90.0 {
            score -= 20.0; // big next item benefits from fresh bin
        }
    }

    // Mild stream-progression tie-breaker: later in stream, be slightly more
    // conservative about opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: after placing this item, the next item fits exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual (good 2-step chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit after placement: penalize dead space that blocks lookahead.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tight fit reward: leaving little residual is good, but not unusably small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize bins whose residual deviates strongly below the mean residual
    // (fragmenting a bin that already has a good fill relative to fleet average).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    if dev < 0.0 {
        score += 8.0 * (-dev);
    } else {
        score -= 4.0 * dev;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let bad_fits = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 20.0 - 25.0 * bad_fits;
    }

    // Early in the stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing else can use (post_residual < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Reward perfect fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.3 * pressure * (1.0 - fit_ratio);

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    // New-bin candidate: penalize opening a new bin unless existing fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the item is large relative to capacity, opening a fresh bin is fine.
        score -= 0.4 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap; // 1 = perfect fit

    // Reward tight fits with smooth polynomial coupling to stream progress
    score -= tightness * tightness * (20.0 + 30.0 * progress) * (0.5 + 0.5 * fit_frac);

    // Penalize large dead space non-linearly
    score += (pr / cap) * (pr / cap) * 15.0;

    // New-bin candidate: penalize mildly unless item is huge or late in stream
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * fit_frac * (0.3 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: prefer residual that could fit next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 12.0 * (-gap * gap / 200.0);
        // avoid wasting residual much larger than next item
        if pr > nx {
            score += 0.05 * (pr - nx);
        }
    }

    // Slight preference for filling bins with low mean residual (consolidation)
    score += 0.1 * (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: reward residuals that belong
    // to "usable" residue classes (small leftovers are dead space unless tiny).
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 500.0;
    } else if pr <= 10 {
        // Small dead space: mildly penalized beyond raw value.
        score += (11 - pr) as f64 * 2.0;
    } else {
        // Reward residuals that are multiples of common item-size classes
        // (10/20/25/50) since future items likely match those granularities.
        let class_bonus: f64 = if pr % 50 == 0 {
            120.0
        } else if pr % 25 == 0 {
            70.0
        } else if pr % 20 == 0 {
            55.0
        } else if pr % 10 == 0 {
            35.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Lookahead: if the next item fits exactly into the post residual,
        // this is a chaining opportunity — reward it strongly.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 180.0;
            } else if next_item_size <= pr {
                let next_left = pr - next_item_size;
                // Reward chains that leave small or class-aligned leftovers.
                if next_left <= 10 {
                    score -= 90.0;
                } else if next_left % 10 == 0 {
                    score -= 40.0;
                } else {
                    // Penalize chains that shatter space into odd leftovers.
                    score += (next_left % 10) as f64 * 1.5;
                }
            } else {
                // Next item cannot follow here; slight penalty proportional
                // to how much residual goes unused.
                score += ((next_item_size - pr) as f64).min(40.0) * 0.5;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (huge post residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual > 40 {
            // Poor fit in the only fitting bin: soften the reward so a fresh
            // bin can win when this bin would be shattered.
            score += (post_residual - 40) as f64 * 1.2;
        }
    }

    // New-bin candidate handling: an empty bin scores its full residual
    // (bin_capacity). Make it attractive only when existing bins would be
    // badly fragmented or when the current item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; late, prefer consolidating.
        let openness = 1.0 - progress;
        score -= openness * 30.0;
        // Large items justify fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // If no bin fits well (post residual large everywhere), new bin wins.
        if mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.5 {
            score -= 20.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> discourage
    // spreading; prefer bins whose post residual beats the mean.
    if open_bins_count > 0 {
        let diff = mean_residual - post_residual as f64;
        score += diff * 0.3;
    }

    // Integer-division threshold on item size: very large items should go
    // into the bin that leaves the least fragmentation.
    if item_size > bin_capacity * 3 / 4 {
        score += post_residual as f64 * 0.5; // extra weight on tight fits
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves some residual: mild reward proportional to fit tightness
            score -= 20.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // next item would NOT fit here: penalize leaving residuals that can't serve it
            let waste = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += 8.0 * waste.min(50.0);
            }
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Pressure from open bins: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * open_bins_count as f64;
    } else {
        // Filling existing bins is mildly rewarded, more so when many bins are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (consolidate space in emptier bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be slightly more willing to open bins (diversity); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Post residual can still fit the next item -> moderate reward, tighter is better.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Post residual too small for next item: penalize proportional wasted space,
    // but less harsh if post_residual is exactly 0 (bin perfectly closed).
    else if next_item_size > 0 && post_residual > 0 {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Reward closing bins tightly (small residuals are dead space if unusable).
    if post_residual < 10 {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (tighter bins first) to preserve
    // roomier bins for larger future items.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless this placement
    // would leave a very awkward residual in every existing option.
    if bin_residual == bin_capacity {
        let wasteful = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if wasteful && fitting_bins_count > 0 {
            // Opening new bin is fine when the item fits poorly everywhere:
            // make new bin competitive by canceling the base residual penalty.
            score -= post_residual as f64 * 0.9;
        } else {
            score += 60.0;
        }
    }

    // Late in the stream, consolidate aggressively to minimize final bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual and its non-linear polynomial coupling with progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + 0.5 * progress) + pr_norm * (1.0 - progress);

    let mut score = pr as f64 + 20.0 * poly;

    // Reward tight fits (small post-residual) more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * fit_quality * fit_quality;
    } else if next_item_size > post_residual && post_residual > 0 {
        // penalize dead space that the next item cannot use
        score += 8.0 * pr_norm * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    if bin_residual as f64 > mean_residual {
        score += 0.05 * (open_bins_count as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // common small item sizes (modular arithmetic on capacity fractions).
    let pr = post_residual;
    // Reward residuals that are multiples of common harmonics (divisible by 10, 20, 25, 50)
    let harmonic_bonus = if pr == 0 {
        60.0
    } else if pr % 10 == 0 {
        15.0
    } else if pr % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space: residuals too small for any item (min size 1, but
    // practically below typical small item class) are wasted.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Coupling with lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish score = full capacity, but adjust by
    // stream position and open-bin pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap_f * 0.85 + progress * 20.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        }
    }

    // Mean residual alignment: prefer bins whose post residual tracks mean
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Tight-fit reward: small post residual relative to capacity fraction
    let frac = post_residual as f64 / cap_f;
    if frac > 0.0 && frac <= 0.05 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable waste
    // (items are >= 1, but tiny slivers rarely match future items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: fraction of residual consumed, amplified.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize leaving a gap that neither fits the next item nor is large.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving a gap exactly sized for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals are already fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create fragmented states.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this item would create a large dead space elsewhere).
    if bin_residual == bin_capacity {
        // Baseline competitive score: slightly better than a badly
        // fragmenting placement, worse than any decent fit.
        score = 35.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize wasted residual
            score += 0.3 * post_residual as f64;
        }
    }

    // Penalize large residual relative to mean (dead space)
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 150.0;
        // but if no existing bin fits well, new bin becomes viable
        if fitting_bins_count == 0 || item_size > 50 {
            score -= 100.0;
        }
    }

    // Mild preference to fill bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is base; add non-linear penalty for large waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: if post_residual can still hold the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * snug;
    }
    // If post_residual is dead space (too small for next item but nonzero), penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * post_residual as f64;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with small residuals relative to mean (fill fuller bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: be pickier about waste; late: consolidate to avoid opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor filling existing bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: keep it neutral-to-slightly-unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (bin_capacity - item_size) <= 20;
        score += if tight_exists { 30.0 } else { 3.0 + 10.0 * (1.0 - progress) };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Smooth polynomial coupling of post residual with stream progress.
    // Early on (progress ~ 0): favor tight fits strongly (post_residual weighted more).
    // Later (progress ~ 1): post residual less dominant, allow looser packing.
    let w = 1.0 + 0.8 * (1.0 - progress) * (1.0 - progress) - 0.4 * progress * progress;
    score = pr * w;

    // Reward near-perfect fits: subtract a smooth gaussian-like bump around norm_pr ~ 0.
    let fit_bonus = 12.0 * (-(norm_pr * norm_pr) / 0.02).exp();
    score -= fit_bonus;

    // Penalize dead space: residuals that are too small to fit typical items later.
    // Smooth polynomial penalty growing with unusable small residuals relative to lookahead.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            let unusable = (gap / cap).powi(2);
            score += 10.0 * unusable * (1.0 + progress);
        } else {
            // Reward bins that can also fit the next item (smooth quadratic reward).
            let slack = (pr - nx) / cap;
            score -= 6.0 * (slack - slack * slack);
        }
    } else {
        // Last item: strongly reward closing bins tightly.
        score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Last-chance bin: reward using it to avoid opening a new bin (smooth sigmoid-like term).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress) + 4.0;
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual alignment.
    let mr = mean_residual / cap;
    score += 2.0 * open_bins_count as f64 * (mr * mr) * 0.01;

    // Prefer bins whose residual is close to the mean (balanced packing), smooth quadratic.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).

    // Harmonic class of post_residual: dead-space classes get penalties.
    // Class residuals into eighths of capacity; low classes are "usable slots".
    let class = (post_residual * 8) / bin_capacity; // 0..7 integer division threshold
    match class {
        0 => score -= 30.0,                      // near-perfect fill
        1 => score -= 12.0,                      // small but possibly useful
        2 => score += 0.0,
        3 => score += 6.0,                       // awkward mid residual
        4 => score += 10.0,
        _ => {}                                  // large residual is fine (bin mostly empty)
    }

    // Modulo-style harmonic bonus: residuals that are multiples of common
    // small item sizes are more likely to be exactly filled later.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 8.0;
    }

    // Lookahead (k=2): if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            score -= 10.0; // next item can still use this bin
        } else {
            score += 5.0; // next item won't fit; residual likely wasted
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a decent fit, better than a bad one.
        score = (bin_capacity as f64) * 0.55; // 55 for C=100
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // opening a bin for a big item is safer
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with below-mean residual (they are the "tight" ones);
    // placing into an already-loose bin spreads waste.
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 4.0;
    } else if bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Many open bins: encourage filling existing ones rather than opening more.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Mid-range gaps: penalize proportionally, they are hard to fill.
        score += 0.8 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless dead space is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // allow it when many open bins exist and fragmentation is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = 15.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // New bin is fine if the item leaves a large, reusable residual.
        score -= 0.3 * post_residual as f64;
    }

    // Prefer bins with below-mean residual (tighter packing).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer minimal post_residual, with slight superlinear penalty on waste.
    score += (post / cap) * 5.0;

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // this placement is highly desirable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 8.0 * fit_quality;
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // post_residual is stranded relative to next item.
            let stranded = (nxt - post) / cap;
            score += 4.0 * stranded;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps flexibility for future items.
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev;

    // Last-chance bin: strongly favor using the only bin that fits,
    // especially when the fit is tight.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
        if post <= 10 {
            score -= 4.0; // near-perfect fill
        }
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let good_open_fit = if next_item_size > 0 {
            fitting_bins_count > 0 && post >= 0.0
        } else {
            false
        };
        // Base cost of opening a new bin.
        score = cap * 0.75;
        // If open bins are fragmented (mean residual low) and few fit,
        // opening a fresh bin becomes relatively better.
        if fitting_bins_count <= 1 && mean_residual < item_size as f64 {
            score -= cap * 0.5;
        }
        if good_open_fit {
            score += 10.0;
        }
        // Early in stream, slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize leaving tiny unusable slivers (dead space < 10).
    if post > 0.0 && post < 10.0 {
        score -= 2.0; // a nearly full bin is excellent, reward it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits into the post residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item can't use
        score += 0.15 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; worse when many bins are already open
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is too small for typical future items,
        // opening a fresh bin becomes attractive
        if mean_residual < item_size as f64 * 0.6 {
            score -= 45.0;
        }
        // Late in the stream, avoid spreading items across too many bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    } else {
        // Favor reusing bins whose residual is close to mean (balance spread)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Penalize bins that would leave a small unusable sliver (waste zone 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress:
    // early on, tolerate larger residuals (favor spreading); later, demand tight fits.
    let progress_coupling = 40.0 * (1.0 - progress) * (x * x) - 20.0 * progress * (x * (1.0 - x));
    score += progress_coupling;

    // Penalize dead space relative to mean residual (smooth quadratic term)
    let dead = (pr - mean_residual).max(0.0);
    score += 0.5 * (dead / cap) * dead;

    // Reward bins that are the only fitting option (last-chance placement)
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving space compatible with the next item (smooth bell)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score += 15.0 * (1.0 - (-4.0 * diff * diff).exp()) * (1.0 - progress);
        // strong reward if next item fits exactly in the post residual
        if pr >= nx {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Mild penalty for proliferation of open bins
    score += (open_bins_count as f64).ln() * 2.0;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes into
    // capacity fractions (C/4, C/2, C/3 style buckets).
    let cap4 = bin_capacity / 4;
    let cap2 = bin_capacity / 2;
    let cap3 = bin_capacity / 3;

    // Reward post-residuals that land on useful harmonic classes.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= cap4 {
        score -= 25.0; // small dead space, likely fillable by future small items
    } else if post_residual == cap2 {
        score -= 20.0; // exact half is a classic harmonic target
    } else if post_residual == cap3 {
        score -= 18.0;
    } else if post_residual <= cap2 {
        score -= 8.0;
    } else {
        // Large leftover: penalize unless it is itself a harmonic fraction of C
        score += (post_residual as f64 - cap2 as f64) * 0.35;
        if post_residual % cap4 == 0 {
            score -= 6.0;
        }
    }

    // Modulo coupling: leftover divisible by common small item sizes is reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use this leftover: penalize proportional to waste
            score += (next_item_size - post_residual).min(bin_capacity) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin for a small item is wasteful
    // unless existing residuals are all too fragmented.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, softened when open bins are fragmented.
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: must open
        }
        if open_bins_count > 0 {
            let frag = mean_residual / bin_capacity as f64;
            // If mean residual is large but unusable (item doesn't fit), opening is fine.
            score -= frag * 15.0;
        }
        if item_size > cap2 {
            score -= 20.0; // big items deserve fresh space
        }
    }

    // Tight fit reward: filling a bin almost exactly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 15.0 * fill_ratio;
    } else if fill_ratio < 0.3 {
        score += 10.0 * (0.3 - fill_ratio); // penalize sparse fills of tight bins
    }

    // Stream progression: late in the stream, prefer closing bins (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += open_bins_count as f64 * 1.5;
        if post_residual <= cap4 {
            score -= 10.0 * progress;
        }
    }

    // Mild pressure against bins whose residual deviates far from the mean
    // (keeps a balanced family of residuals for harmonic pairing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 15.0;
    }

    // Reward leaving residuals that can still host typical items.
    let usable_threshold = 30.0;
    if post_residual as f64 >= usable_threshold {
        score -= 8.0;
    } else if post_residual as f64 >= 10.0 {
        score -= 3.0;
    }

    // Coupling with lookahead: prefer bins whose post_residual can host next item.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // dead space for the next item
        }
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        if crowded && open_bins_count > 0 {
            score -= 12.0;
        } else if poor_fit && open_bins_count > 0 {
            score += 30.0;
        } else {
            score += 18.0; // default: prefer existing bins
        }
    }

    // Mild stream progression: as stream advances, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (mean_residual / bin_capacity as f64 - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits into the post_residual,
    // reward this bin heavily (perfect 2-item chain).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * chain_waste;
        } else {
            // Post-residual too small for the next item: penalize dead space,
            // more so when the leftover is small (unusable fragment).
            let frag = post_residual as f64;
            score += 8.0 * (1.0 - frag / 50.0).max(0.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post_residual stays near/below the mean (balanced packing).
    score += 0.10 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the item
    // is large or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score -= large_item_bonus;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in the stream, opening new bins is fine (no closure pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Last chance: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (more room than average) when not tight
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
        // But if no existing bin fits well, new bin is attractive
        if post_residual == 0 || fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - (pr / cap);

    // smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let t2 = tight * tight;

    let mut score = pr
        // late in the stream, dead space hurts more (non-linear ramp)
        + pr * (0.35 * progress + 0.65 * p3)
        // reward near-perfect fits, more strongly later
        - 12.0 * t2 * (0.5 + 0.9 * progress)
        // penalize leaving residuals that fit neither the next item nor typical sizes
        - 8.0 * (pr - next_item_size as f64).abs() / cap * (0.4 + 0.8 * progress)
        // last-chance bin bonus: strongly prefer using the only fitting bin
        - (if fitting_bins_count == 1 { 25.0 + 15.0 * progress } else { 0.0 })
        // mild penalty when bin residual deviates from mean residual (imbalance)
        + 0.05 * (pr - mean_residual).abs()
        // slight penalty for opening new bins when many are open and fit exists
        + (if bin_residual == bin_capacity { 6.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (0.5 + progress) } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls on
    // small-modulo classes (waste buckets) are penalized harder.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class 0: perfect fit -> strong reward.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Dead-space class: leftover too small for typical items (pr < 10
        // cannot hold anything; 10..=20 holds only tiny items).
        if pr < 10 {
            score += 25.0; // unusable sliver
        } else if pr <= 20 {
            score += 10.0; // low-utility class
        }

        // Harmonic compatibility: does post_residual admit the lookahead item?
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Reward proportional to how snugly the next item would nest.
                let nest = (next_item_size as f64) / (pr as f64); // in (0,1]
                score -= 18.0 * nest;
                // Extra reward when next item nearly fills the leftover exactly.
                let gap = pr - next_item_size;
                if gap <= 5 {
                    score -= 12.0;
                }
            } else {
                // Leftover is in a class the next item cannot use.
                score += 8.0;
            }
        }

        // Fractional-capacity class of post_residual (quarter bins).
        let quarter = (prf / cap * 4.0).floor();
        score += 3.0 * quarter; // prefer smaller quarter-class leftovers
    }

    // Reward tight fits relative to the current residual (best-fit core).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin is expensive; penalize unless this is
    // early in the stream or the item simply does not fit anywhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 35.0 + 30.0 * progress;
        // If many bins can fit the item, definitely prefer an existing one.
        if fitting_bins_count > 1 {
            new_bin_penalty += 20.0;
        }
        // Large items relative to capacity justify fresh bins more.
        if (item_size as f64) / cap > 0.6 {
            new_bin_penalty -= 25.0;
        }
        // If no open bin would leave a usable next-item slot, soften penalty.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_possible = if bin_residual >= item_size + next_item_size { 0u32 } else { 1 };
            if best_possible == 0 {
                new_bin_penalty += 10.0;
            }
        }
        score += new_bin_penalty;
    }

    // Mild pressure against accumulating many half-empty bins.
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0) / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (min size 1, but practically small gaps) are
    // heavily penalized, especially in the "unusable" band.
    let dead_zone_low = 0.0f64;
    let dead_zone_high = 12.0f64;
    let pr = post_residual as f64;
    if pr > dead_zone_low && pr < dead_zone_high {
        // Deeper inside the dead zone => larger penalty (peak mid-band).
        let mid = (dead_zone_low + dead_zone_high) / 2.0;
        let depth = 1.0 - (pr - mid).abs() / (dead_zone_high - dead_zone_low) / 2.0;
        score += 8.0 * depth;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 6.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 0.8 * pressure;
    } else {
        // Opening a new bin is penalized progressively as open bins grow,
        // but slightly relaxed early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 4.0 + 1.5 * pressure - 2.0 * progress;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits into the resulting residual,
    // reward this placement; if residual is just barely too small for the
    // next item, penalize (near-miss dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0;
        } else if pr > 0.0 && nx - pr <= 10.0 {
            score += 2.5 * (1.0 - (nx - pr) / 10.0);
        }
    }

    // Prefer bins whose residual is already below the mean (tighter bins
    // get filled first, keeping looser bins flexible).
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
