pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward high fill (tight fits): quadratic bonus
    score -= 40.0 * fill * fill;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * next_fit_tightness;
        // Perfect chaining: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for leaving awkward space
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer tighter competition mildly
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare with mean residual across open bins: placing in a bin whose
    // residual deviates strongly from the mean may be wasteful
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate (empty bin): decide when opening a new bin is better
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 55.0;
        // Open new bin if current item is large and no tight fit exists elsewhere
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them)
        score -= 25.0 * (1.0 - progress);
        // If many bins are already open, discourage opening more
        score += 2.0 * open_bins_count as f64;
        // If the only fitting bin is this new one anyway, it must be chosen
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // If next item is large, a fresh bin gives flexibility
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * progress * progress;
    score += 6.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= fill * fill * (1.0 + 3.0 * progress) * 4.0;

    // Penalize dead space: post_residual too small for typical future items
    let min_size = 1.0f64;
    if pr < min_size {
        score += 20.0;
    }
    if pr > 0.0 && next_item_size > 0 {
        let look = next_item_size as f64;
        if look <= pr {
            // lookahead fits: reward proportional to lookahead utilization
            score -= (look / pr) * 3.0 * (1.0 - progress);
        } else {
            // lookahead wasted: penalize unusable gap
            score += ((look - pr) / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly unless existing bins are very full
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (1.0 - progress);
        if mean_residual < 0.15 * cap && progress > 0.5 {
            score -= 6.0;
        }
    }

    // Mild pressure from number of open bins: encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * pr_norm;

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes are near-perfectly packed; reward them.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,
        1..=5 => -30.0,
        6..=15 => -10.0,
        16..=30 => 5.0,
        31..=50 => 15.0,
        _ => 25.0,
    };
    score += class;

    // Modulo-10 granularity: dead space in multiples of 10 is more reusable
    // by typical item sizes; penalize non-aligned residuals.
    let aligned = (pr % 10) as f64;
    score += 0.6 * aligned;

    // Lookahead: if the next item fits exactly into post_residual, strongly
    // favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: mild penalty proportional
            // to wasted potential.
            score += 0.15 * (next_item_size as f64 - pr as f64).min(50.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // gives a decent fit. Penalize relative to how full open bins are.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let mean_fit = mean_residual / cap;
        score = 60.0 + 5.0 * crowding.max(1.0).ln() - 20.0 * mean_fit;
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 30.0; // fresh bin serves next item perfectly
        }
    }

    // Tight-fit reward: filling a bin nearly exactly is ideal.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (superlinear in how "wasted" the gap is).
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead zone: gap too small for the smallest plausible future item (<=20)
        if post_residual < 20 {
            score += 60.0 * (1.0 - pr / 20.0);
        } else {
            // Larger gaps are mildly good: they can absorb future items
            score -= 0.15 * pr;
        }
    } else {
        // Perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits: fraction of residual consumed by the item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; but ease pressure late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (open_bins_count as f64) * (1.0 - 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive
    // unless the fit in it is essentially unavoidable. Give it a baseline
    // penalty so open bins with decent fits win.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if no open bin fits well (post_residual in new bin is small,
        // i.e., item nearly fills a bin), allow opening: reduce penalty.
        let new_fill = item_size as f64 / bin_capacity as f64;
        score -= 50.0 * new_fill * new_fill;
    }

    // Lookahead coupling: if the next item could use the resulting gap,
    // reward leaving exactly that much room.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            score -= 0.25 * next_item_size as f64;
        }
    }

    // Slight preference to fill bins below mean residual (equalize load
    // toward fuller bins).
    score -= 0.05 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if the item actually fits.
    let fit_gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score -= 40.0 / (1.0 + fit_gap);

    // 2-step lookahead: strongly reward if the NEXT item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chaining: bin closes exactly
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover space
            let leftover = post_residual - next_item_size;
            score -= 60.0 * (next_item_size as f64) / (1.0 + leftover as f64);
        } else {
            // next item does NOT fit in this bin: penalize wasted dead space
            let waste = next_item_size - post_residual;
            score += 0.8 * waste as f64;
            // if next item can't even fit a fresh bin, this lookahead is moot; soften
            if next_item_size > bin_capacity {
                score -= 0.8 * waste as f64;
            }
        }
    }

    // Penalize leaving residuals that are hard to reuse (small but nonzero dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Compare against mean residual: prefer bins whose residual is already below average
    // (concentrate filling into emptier-relative bins keeps large gaps elsewhere).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate (empty bin): discourage unless nothing else is attractive.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin currently fits, opening a new bin is necessary/fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the next item is huge and this item is small, saving space may pay off.
        if next_item_size > 0 && next_item_size > item_size + 20 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, allow more bins to stay open (flexibility); later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 && progress > 0.5 {
        score += 0.5 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly weight small post_residual.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that no plausible item (min size 1, typical >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement (chaining good pairs).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let chain_gap = post_residual as f64 - nxt;
            score -= (30.0 * (1.0 - chain_gap / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here regardless; slight penalty for very large leftovers
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should be attractive only when
    // the current item fits poorly everywhere (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global congestion.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 55.0 - 10.0 * congestion - 15.0 * progress;
        // If the item fills a fresh bin well, reward opening.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill * fill;
    }

    // Mild preference to fill bins with large residuals when many bins are open
    // (consolidation pressure).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon term: early in stream, be slightly more exploratory (favor new
    // bins less); late, be greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: cubic in post_residual, amplified by stream progress
    let post_norm = post / cap;
    score += 6.0 * post_norm.powi(3) * (1.0 + 2.0 * progress) * cap;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= 4.0 * (1.0 - post_norm).powi(2);

    // Penalize leaving residual that is close to but less than typical item sizes
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = post - n;
        if gap >= 0.0 {
            // residual can host next item: smooth reward proportional to leftover
            score -= 2.0 * (1.0 - (gap / cap)) * (1.0 - (gap / cap));
        } else {
            // residual just below next item: dead space penalty, smooth in distance
            let miss = (-gap / cap).powi(2);
            score += 8.0 * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins with residuals near the mean (balance load)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Smooth interaction: tightness vs progress coupling
    score -= 3.0 * progress * (1.0 - post_norm).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 25.
    // Residuals in "waste classes" (small, unusable slivers) are heavily penalized.
    let post = post_residual as u32;
    let cls10 = post % 10;
    let cls25 = post % 25;

    // Dead-space penalty: residuals < 10 can never host another item (min size 1... but
    // small items exist), so weight by how close to zero we land.
    if post < 10 {
        score += (10 - post) as f64 * 3.0;
    } else if post < 20 {
        score += (20 - post) as f64 * 1.2;
    }

    // Modulo-class coupling: post_residual divisible by 25 or 10 is "harmonic" —
    // likely to be exactly fillable by future items. Reward these classes.
    if post > 0 {
        if cls25 == 0 {
            score -= 12.0;
        } else if cls10 == 0 {
            score -= 8.0;
        } else if cls10 <= 3 {
            score += 6.0; // awkward sliver class
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let nxt = next_item_size as f64;
            // Harmonic fraction: next/post ratio near simple fractions (1/2, 1/3, 2/3)
            let r = nxt / post as f64;
            if (r - 0.5).abs() < 0.02 || (r - 1.0 / 3.0).abs() < 0.02 || (r - 2.0 / 3.0).abs() < 0.02 {
                score -= 10.0;
            }
            score += (post - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; if this is the last-chance bin, mild penalty
            // is fine since item must go elsewhere anyway — slight reward for keeping
            // post_residual large.
            score -= (post as f64 - cap * 0.5).abs() * 0.05;
        }
    }

    // Perfect fit reward.
    if post == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin,
    // unless the fit is terrible (huge post_residual waste class).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post >= 10 && cls25 != 0 && cls10 != 0 {
            score -= 5.0;
        }
    }

    // New-bin candidate (empty bin): penalize opening a new bin when reasonable
    // open bins exist; scale with stream progress and open-bin count.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.75 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // Allow new bin only when current item is small and next item is large
        // (reserve capacity heuristic via harmonic halves).
        if item_size <= bin_capacity / 4 && next_item_size >= bin_capacity / 2 {
            score -= 60.0;
        }
        // If no open bin fits at all, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with residual below mean (tighter bins).
    score += (post as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that is too small for the smallest plausible item (size 1..10 band)
    // is pure waste; weight it super-linearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits: the closer post_residual is to 0 (but usable), the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin count pressure: with many open bins, prefer filling existing ones
    // over opening new ones; also mildly penalize new-bin candidates.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        score += 18.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Lookahead coupling: if the next item fits into the post_residual, reward it;
    // if it nearly fits (small miss), penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if nxt - post_residual as f64 <= 5.0 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (compact bins get filled first).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

