            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Dead space: leftover that the next item cannot use.
            // Penalize most when post_residual is just barely below next_item_size.
            let miss = (next_item_size - post_residual) as f64;
            let miss_frac = miss / next_item_size as f64;
            let near_miss_penalty = if miss <= 10.0 {
                20.0 * (1.0 - miss / 10.0) // near-miss: heavy penalty
            } else {
                0.0
            };
            score += 4.0 + near_miss_penalty + 3.0 * (1.0 - miss_frac);
        }
    }

    // --- Relative-to-mean coupling: prefer bins whose residual deviates favorably ---
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        // Bins tighter than average are precious: filling them is good.
        if res < mean_residual {
            score -= 0.5 * (mean_residual - res);
        } else {
            score += 0.3 * (res - mean_residual);
        }
    }

    // --- Exact / near-exact fit bonus ---
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- New-bin candidate handling: opening a fresh bin wastes capacity of the old one ---
    if bin_residual == bin_capacity {
        // New bin baseline: attractive only if current fit is terrible.
        // Encourage new bins early (more stream left to amortize), discourage late.
        score = 25.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin chains well too
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is mandatory
        }
    }

    // --- Mild pressure against hoarding many open bins ---
    score += 0.15 * open_bins_count as f64 * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
