    }

    // New-bin candidate: keep it attractive early, discourage late when
    // consolidation into open bins is preferable; discourage if many bins open.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 0.5 * cap - 20.0 * (1.0 - progress) + 30.0 * open_pressure;
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the fleet mean when they fit tighter than average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let mut score = post;

    // Harmonic class of post_residual: mod-10 buckets. Residuals in
    // [0,10) are "dead" (only tiny items fit); reward hitting them,
    // penalize awkward mid-range classes like 40..60.
    let r = post_residual % 10;
    match r {
        0 => score -= 12.0,                 // perfectly reusable class
        1..=3 => score -= 6.0,              // nearly reusable
        4..=6 => score += 8.0,              // awkward class
        7..=9 => score += 3.0,
        _ => {}
    }

    // Integer-division threshold: post_residual / item_size tells how
    // many copies of the current item would still fit — more copies
    // means the bin stays "productive".
    if item_size > 0 {
        let copies = post_residual / item_size;
        score -= copies as f64 * 4.0;
    }

    // Lookahead coupling: strongly reward if the next item fits the
    // post residual exactly or closely (harmonic pairing).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 10.0 - gap.min(10) as f64; // exact fit of next item: big reward
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to waste
        score += (next_item_size as f64 - post).min(20.0) * 0.3;
    }

    // Capacity fraction logic: fractional fill level of the bin.
    let fill = 1.0 - post / cap;
    score -= fill * 15.0; // prefer fuller bins

    // Last-chance bin: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin, but less so
    // when the item is large (would leave big residual in any bin)
    // or when few bins are open relative to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 14.0;
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 6.0; // big items are fine in fresh bins
        }
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open
        }
        if progress > 0.8 {
            new_bin_penalty -= 4.0; // late stream: consolidation less valuable
        }
        score += new_bin_penalty;
        // Fresh bin leaves post_residual = cap - item: judge it fairly
        score -= (cap - item_size as f64) * 0.05;
    }

    // Mean-residual coupling: if open bins are already slack-heavy,
    // slightly discourage spreading into this bin's remaining space.
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (typical items are >= 10, but allow small-item streams) are
    // heavily penalized with a non-linear ramp.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Penalize leaving a gap that exactly invites waste but not a useful
    // next-item fit; reward when the lookahead item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // new-bin candidate would leave a cleaner large residual.
    score += open_bins_count as f64 * 1.5;

    // Slight preference for bins whose residual is close to the mean
    // (keeps residuals balanced so future items have uniform targets).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate handling: an empty bin is attractive early or when
    // open bins would create dead space; less attractive when it fragments.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_space_if_used_existing = if fitting_bins_count >= 1 {
            (bin_capacity - item_size).min(bin_capacity) as f64
        } else { 0.0 };
        // Opening a new bin leaves a large residual = flexible; reward it
        // moderately, but penalize when many bins are already open.
        score -= 40.0 + progress * 20.0 - dead_space_if_used_existing * 0.1;
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * diff;
        // Perfect chain: next item exactly fills the bin after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits comfortably after this placement.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
        // Placing here would leave dead space smaller than the next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that are already partially filled
    // (low residual) so we consolidate into few bins.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Penalize excessive leftover waste relative to capacity.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: if this is the only bin that fits, favor using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    // (large post_residual) or stream is early and bins are plentiful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * (1.0 - progress);
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 4.0;
        } else {
            score += 10.0;
        }
    }

    // Slight penalty for opening many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual already favored, add quadratic emphasis.
    score += (post_residual as f64 / cap).powi(3) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize bins whose leftover is too small for the next item (dead space),
    // reward leftovers that exactly accommodate the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr < nx {
            score += (nx - pr) * 0.6; // wasted for the next item
        } else if (pr - nx).abs() < 1.0 {
            score -= 25.0; // chain of perfect fits
        } else {
            score -= (pr - nx).min(20.0) * 0.3; // next item fits reasonably
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no open bin
    // offers a good fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        // Empty bin: baseline moderate score; worse if many bins already open.
        score = cap * 0.85 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Global state: if mean residual across open bins is large, prefer filling
    // existing bins rather than leaving slack everywhere.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.4;
    }

    // Time horizon: early in the stream, be more selective (prefer tight fits);
    // late in the stream, just close bins out.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * (1.0 - t);

    // Mild penalty on very fragmented states (many open bins).
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with a convexity shift over the stream.
    // Late in the stream, dead space matters more (fewer chances to fill it),
    // so weight the polynomial residual penalty more heavily.
    let w = 0.6 + 1.6 * progress * progress;
    let mut score = w * pr;

    // Smooth non-linear coupling: reward tight fits (small x) super-linearly,
    // penalize awkward mid-range leftovers with a bump around x ~ 0.4-0.6.
    let bump = (x - 0.45) * (x - 0.45);
    score += 30.0 * bump * (1.0 - progress * 0.5);

    // Perfect-fit reward (smooth exponential-like via polynomial approximation).
    let tightness = (1.0 - x).max(0.0);
    score -= 20.0 * tightness * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: if next item can use the post residual, reward leaving
    // exactly that much space; if post residual is just barely too small for the
    // next item, penalize the near-miss dead space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            // next item fits exactly => strong reward, scaled by exactness
            let exact = 1.0 - (gap / cap).min(1.0);
            score -= 15.0 * exact * exact * (0.5 + progress);
        } else {
            // near miss: dead space that next item cannot use
            let miss = (-gap / cap).min(1.0);
            score += 10.0 * (1.0 - miss) * (1.0 - miss) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight penalty for spreading across many open bins when residuals are large;
    // encourages consolidation into bins with low mean residual.
    let mean_norm = mean_residual / cap;
    score += 5.0 * mean_norm * mean_norm * (1.0 - progress);

    // New-bin candidate calibration: an empty bin has x = 1.0; make it attractive
    // only when the stream is early or when post residual would be very tight anyway.
    if bin_residual == bin_capacity {
        score += 8.0 * progress * progress * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let cls = if post_residual == 0 { 0 }
        else if post_residual <= quarter { 1 }
        else if post_residual <= half { 2 }
        else { 3 };

    // Reward near-perfect fits strongly.
    match cls {
        0 => score -= 40.0,
        1 => score -= 8.0 + (quarter as f64 - post_residual as f64) * 0.5,
        2 => score += 6.0,
        _ => score += 15.0,
    }

    // Integer-division thresholds: reward leaving a residual that is a clean multiple
    // of common small-item sizes (harmonic slots for future items).
    for slot in [10u32, 20, 25, 50] {
        if post_residual >= slot && post_residual % slot == 0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= quarter { score -= 10.0; }
            else { score += gap as f64 * 0.2; }
        } else {
            // next item won't fit here: mild penalty proportional to wasted class
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = if post_residual <= quarter { 1.0 } else { 0.0 };
        score += 25.0 - 20.0 * fit_quality - 10.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (compactness pressure).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight load balancing: more open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Medium-small gaps are mildly penalized since few item sizes fit.
        score += 8.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward a fit that exactly accommodates the lookahead item too.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual too small for lookahead: penalize proportionally.
        score += 3.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight packing
    // and make new bins less attractive.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has large post_residual by definition,
    // so it already scores high; add extra pressure when open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But allow new bin when the only fits leave terrible dead space.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Deviation from mean residual: bins far above mean residual are better targets.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be slightly more willing to open bins (better long-run packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the
    // next item size (chain packing), penalize post-residuals that are too
    // small to be useful (dead space).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * gap;
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Dead space: post residual too small for the next item (min size 1).
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 0.8 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter (smaller residual)
    // than the mean; penalize bins that are already roomier than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin should only win when the fit into
    // existing bins is very poor. Penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Small bonus for tight fits generally (low post residual relative to capacity).
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0 * (1.0 - frac * 5.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 10.0 * (1.0 - rem2 as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if post residual becomes dead space.
            if post_residual < 10 && post_residual > 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residuals.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 + 20.0 * pressure - 10.0 * t;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Favor bins whose residual is above mean (use "loose" bins first).
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
        // Slight preference for fewer open bins being consolidated.
        score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Late in stream: be more conservative, prefer tighter fits harder.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += frac * 10.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * (1.0 - progress) * (1.0 - progress);

    let mut score = post + 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: penalize residuals that cannot host the next item,
    // reward residuals that can, with smooth quadratic interaction.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 + progress);
        } else {
            score += 8.0 * ((-gap) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild preference for consolidating into fewer bins.
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are large.
    if bin_residual == bin_capacity {
        let waste_pressure = mean_residual / cap;
        score += 15.0 * (1.0 - waste_pressure) * (1.0 - progress) - 5.0 * waste_pressure;
    }

    // Slight penalty for deviating from the mean residual (balance-aware).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (multiples of small divisors) are preferred,
    // since future items can pack into them more cleanly.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Reward leftover sizes that divide cleanly into common item sizes.
    let mut harmony_bonus = 0.0;
    for d in [10u32, 20, 25, 50].iter() {
        if *d != 0 && post_residual % d == 0 && post_residual > 0 {
            harmony_bonus += 8.0;
        }
    }
    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit: strongly reward exact packing.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a harmonic pair — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Partial harmony: reward proportional to how well next item
            // divides the post residual (integer-division threshold logic).
            let q = post_residual / next_item_size.max(1);
            if q >= 2 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use this bin's leftover; slight penalty.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave terrible dead space (post_residual tiny but nonzero)
    // or when the stream is early and consolidation is cheap.
    if bin_residual == bin_capacity {
        // Fresh bin: score = capacity - item, adjusted.
        score = (bin_capacity - item_size) as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening new bins is cheap; later, discourage it.
        score -= (1.0 - progress) * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: prefer placing into bins whose residual is
    // above the mean (keep tight bins for tight fits).
    if (bin_residual as f64) < mean_residual {
        score += 6.0;
    } else {
        score -= 3.0;
    }

    // Capacity fraction thresholds on post_residual: penalize leftovers in
    // awkward bands (just under half or just under capacity).
    if cap_frac > 0.4 && cap_frac < 0.5 {
        score += 5.0;
    }
    if cap_frac > 0.9 {
        score += 12.0;
    }

    score += harmony_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 60.0; // dead space too small for any plausible item
    }
    // Non-linear penalty on tiny residuals (quadratic blowup near zero)
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 400.0 / (pr + 2.0);
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: prefer existing bins more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize wasted space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual: avoid leaving much more space than average
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.1 * dev; // slight reward for tighter-than-average bins
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer opening a new bin if this is truly
    // a fresh bin and current fits are poor; otherwise penalize new bins mildly.
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 30.0; // big item now, next smaller: fresh bin pairing is fine
        }
    }

    // Late in stream, tighten packing (avoid opening bins near the end)
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    // Prefer filling bins with larger residual when few bins are open
    if open_bins_count > 1 {
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual == 0 is perfect; small residuals waste space.
    let perfect = if post_residual == 0 { 60.0 } else { 0.0 };
    score -= perfect;

    // Penalize residuals that can never serve typical items (dead space), scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_zone = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0 * (0.5 + progress);
    score += dead_zone;

    // Lookahead: if post_residual can exactly host the next item, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Residual too small for next item: mild penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins with larger residual (keep tight bins free).
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Prefer bins whose residual deviates from mean residual (consolidate similar bins).
    score -= (bin_residual as f64 - mean_residual).abs() * -0.2;

    // Penalize opening a new bin when open bins fit, unless nothing fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64) > mean_residual * 0.9;
        if poor_fit {
            score -= 30.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Mild early-stream bias toward filling existing bins aggressively.
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: residual cost grows super-linearly as stream progresses
    let progress_factor = 1.0 + 0.6 * progress * progress;
    score *= progress_factor;

    // Non-linear penalty on normalized dead space (quartic-ish smooth term)
    score += 40.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits via smooth tanh-like term on post_residual
    let tight = ((pr / cap) * 6.2831853 - 1.5707963).tanh();
    score -= 15.0 * (tight * 0.5 + 0.5) * (1.0 - progress);

    // Penalize opening new bins late in stream unless residual is truly large
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new_bin * (25.0 + 50.0 * progress) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.1 * gap * (0.5 + progress);
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= 8.0 * fits_next * (1.0 - progress);
    }

    // Mild dispersion penalty: bins far from mean residual are less attractive
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // decile buckets (capacity fractions). Small classes are good (tight fit).
    let post_class = (post_residual * 10) / bin_capacity; // 0..=10 integer class
    let item_class = (item_size * 10) / bin_capacity;

    // Reward tight fits: subtract more for lower post_residual classes,
    // with a harmonic (1/(k+1)) weighting so class 0 is heavily rewarded.
    let harmonic = 1.0 / (post_class as f64 + 1.0);
    score -= 12.0 * harmonic;

    // Penalize dead space: leftover too small for the smallest plausible item (size 1..100).
    // If post_residual < ~10 it's nearly dead space; if it's in an awkward band
    // (just below a typical item) it's also bad. Use modulo structure:
    // residuals in [1,9] are near-dead; residuals in [41,60] are semi-flexible.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // near-dead space
    }
    if post_residual >= 41 && post_residual <= 60 {
        score -= 4.0; // flexible mid band, can host medium items
    }

    // Integer-division threshold coupling with the lookahead item:
    // if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // perfect chain: next item exactly fills remainder
            if slack == 0 {
                score -= 25.0;
            } else {
                // reward proportionally, using harmonic decay on slack class
                let slack_class = (slack * 10) / bin_capacity;
                score -= 10.0 / (slack_class as f64 + 1.0);
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much leftover would be wasted relative to next item size
            let waste_ratio = post_residual as f64 / (next_item_size as f64 + 1.0);
            score += 6.0 * waste_ratio.min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, prefer bins that keep residual structure clean:
        // penalize bins whose residual deviates far from the mean residual.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Prefer filling bins that are already relatively full (small residual),
    // scaled by stream progress: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (0.5 + progress);

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Only prefer opening a new bin when no existing bin offers a decent fit,
    // i.e. when the best existing option would create near-dead space. We approximate:
    // make the empty bin attractive only if the item is large and would leave a
    // "clean" harmonic residual (post class in the flexible band).
    if bin_residual == bin_capacity {
        if post_class >= 3 && post_class <= 7 {
            score -= 8.0; // clean split, fresh bin is fine
        } else {
            score += 10.0; // avoid scattering items into new bins with awkward leftovers
        }
        // late in the stream, discourage opening bins aggressively
        score += 10.0 * progress;
    }

    // Small modulo-based tiebreaker on post_residual classes to break ties deterministically
    // without randomness: prefer residuals that are multiples of 25 (common item pairings).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual that cannot fit the next item is dead weight; penalize more
    // when the next item is close to fitting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps a usable slot for lookahead
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mildly discourage opening new bins by boosting empty-bin score.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline high; lower it only if current bins are
        // fragmented (high mean residual) so consolidation is preferred.
        score = 95.0 + open_bins_count as f64 * 0.5 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open
        }
    } else {
        // Occupied bin: reward filling bins that are already fairly full.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 15.0;
        // Penalize bins whose residual diverges from the mean (fragmentation).
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;
    }

    // Late in the stream, tighten up: prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match between post_residual and next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step chaining
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / bin_capacity as f64);
        }
    } else {
        // last item: just minimize post residual
        score += 0.0;
    }

    // Relative to mean residual: prefer bins that become tighter than average
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    let mean_frac = mean_residual / cap.max(1.0);
    score += 25.0 * (post_frac - mean_frac);

    // Penalize small unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or this is a big item early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_frac < 0.25;
        if crowded && progress > 0.1 {
            score -= 15.0; // fresh capacity is valuable when bins are full of dead space
        } else {
            score += 20.0; // prefer reusing open bins otherwise
        }
        // discourage opening bins for small items
        score += (item_size as f64) * 0.15;
    }

    // Mild reward for tight fits (small post residual relative to item)
    score -= (item_size as f64) / (bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual <= 30 {
        score += 8.0 * (30.0 - post_residual as f64) / 30.0; // awkward small gap
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain;
        } else {
            // Next item won't fit here; slight penalty if we leave a gap smaller than next item.
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize it
    // proportionally to how many bins are already open and how much slack
    // exists globally, but allow it when the item is huge and would leave
    // unusable space everywhere else.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let global_slack = mean_residual / bin_capacity as f64;
        let mut new_bin_cost = 35.0 + 6.0 * open_bins_count as f64 * (1.0 - progress);
        new_bin_cost += 20.0 * global_slack;
        // If item is large and leaves little room, opening a fresh bin is fine.
        let fill = item_size as f64 / bin_capacity as f64;
        new_bin_cost -= 45.0 * fill * fill;
        score += new_bin_cost;
    }

    // Mild global-state coupling: when mean residual across bins is high,
    // prefer bins below the mean (consolidate slack).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Late in the stream, be more conservative: prefer tighter fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post residual, with a smooth non-linear penalty
    // on very small residuals (dead space) that grows quadratically.
    let mut score = pr + (pr / cap).powi(2) * 12.0;

    // Smooth stream-progress coupling: early on, tolerate larger residuals
    // (more future items to fill them); late, squeeze harder.
    score *= 1.0 + 0.35 * progress * (1.0 - progress).powi(2) * (pr / cap);

    // Tight-fit reward: strongly subtract when post_residual is near zero.
    let tight = 1.0 - (pr / cap);
    score -= tight.powi(3) * 25.0;

    // Lookahead: reward if next item could fit into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            let slack = (pr as f64 - nx) / cap;
            score -= (1.0 - slack).powi(2) * 8.0 * (1.0 - progress);
        } else {
            // Penalize creating residual too small for the next item.
            score += ((nx - pr as f64) / cap).powi(2) * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count <= 1 && !is_new_bin {
        score -= 18.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin unless current residual is
    // badly fragmented or the stream is early with plenty of room to fill.
    if is_new_bin {
        let frag = (mean_residual / cap).powi(2);
        score += 14.0 * (1.0 - progress) * (1.0 - frag) + 10.0;
        // Allow new bin late in the stream when mean residuals are large
        // (fragmentation) — smooth relief term.
        score -= frag * 12.0 * progress;
    }

    // Mild preference to consolidate across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (eighths) — small classes are "good" dead space.
    let frac = (post_residual as f64) / (bin_capacity as f64);
    let class = (post_residual / (bin_capacity / 8).max(1)) as f64; // 0..8 harmonic class
    score += class * 2.0; // penalize large leftover classes

    // Integer division thresholds: residual divisible by common item sizes
    // (10,20,25,50) means the leftover is reusable by typical items.
    if post_residual > 0 {
        let mut reuse_bonus = 0.0;
        for m in [10u32, 20, 25, 40, 50] {
            if post_residual % m == 0 {
                reuse_bonus += 6.0;
            }
        }
        score -= reuse_bonus;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else {
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize proportional to waste
        score += 5.0 + frac * 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are terrible. Penalize the fresh bin by a base offset that scales
    // with how many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * fitting_bins_count as f64;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mean-residual coupling: bins far below mean residual are underused;
    // prefer filling them (low residual = high priority already, add small
    // pull toward mean).
    score -= 0.05 * (mean_residual - post_residual as f64).abs();

    // Modulo harmonic tiebreak on item size classes (odd/even style classes)
    let item_class = item_size % 4;
    score -= match item_class {
        0 => 3.0, // items divisible by 4 pack flexibly
        2 => 1.5,
        _ => 0.0,
    };

    // Mild pressure to reduce open bin count
    score += 0.3 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Gaps below the minimum item size (1..10) are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Gaps that can only fit very small items are nearly dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward: strongly favor exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over creating more.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 2.0;
    } else {
        // New-bin candidate: penalize slightly so it only wins when fits
        // into open bins are genuinely bad (large dead space).
        score += 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit post residual but could fit bin_residual
    // only marginally better, small penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping loose bins flexible).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Reward if next item still fits in the bin after placement
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64) * 0.5;
    }
    // Penalize leaving dead space that cannot fit the next item
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a perfect next-item match
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 100.0;
        } else {
            score += 50.0 + mean_residual * 0.2;
        }
    }

    // Mild penalty for very small post_residual (wasted capacity) unless it's near zero
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight normalization against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this leftover: mild penalty scaled by waste.
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Spread load when many bins fit: prefer bins with less residual.
        score += 2.0 * (bin_residual as f64 - mean_residual);
    }

    // Prefer filling bins with low residual overall (consolidation).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, encourage opening new bins for large items
    // (keep flexibility); late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus;
        // Opening a new bin is especially good for large items early on.
        score -= new_bin_bonus * (item_size as f64 / bin_capacity as f64);
    }

    // When many bins are open, discourage opening even more.
    if bin_residual == bin_capacity {
        score += 3.0 * open_bins_count as f64 * progress;
    }

    // Slight preference for placing larger items into fuller bins.
    score -= 0.1 * (item_size as f64) * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits, non-linearly scaled
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals matter more (dead space is costlier).
    let progress_weight = 0.35 + 0.65 * progress * progress;
    score += progress_weight * (pr / cap) * (pr / cap) * cap;

    // Reward near-perfect fits with a smooth cubic decay
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize residuals that are small but not zero (unusable slivers),
    // smoothly via a quadratic centered at a fraction of capacity.
    let x = pr / cap;
    let sliver = (x - 0.08) * (x - 0.08);
    score += 6.0 * (1.0 - x) * sliver;

    // Lookahead: reward leaving room for the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let gapn = gap / cap;
        score -= 8.0 * (-gapn * gapn * 4.0).exp();
    }

    // Last-chance bin: strongly favor using it (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild penalty when many bins are already open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins far below mean residual waste capacity
    score += 0.1 * (mean_residual - pr).max(0.0);

    // New-bin candidate: neutral-ish baseline, opened only if no decent fit exists
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * progress - 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as u32;

    // Dead-space penalty grows super-linearly for residuals in awkward classes
    if post > 0 && post < eighth {
        score += (eighth - post) as f64 * 3.0;
    } else if post >= eighth && post < quarter {
        // sweet spot: small but reusable sliver class
        score -= post as f64 * 0.5;
    } else if post >= quarter && post < bin_capacity / 2 {
        score -= post as f64 * 0.25;
    } else if post == 0 {
        score -= 25.0; // perfect closure
    }

    // Modulo-10 class coupling between post_residual and next item
    if next_item_size > 0 {
        let class_gap = (post % 10).abs_diff(next_item_size % 10);
        if next_item_size <= post {
            // next item fits here: reward alignment of residue classes
            score -= (post - next_item_size) as f64 * 0.6;
            if class_gap == 0 { score -= 8.0; }
            if post - next_item_size < eighth { score += 6.0; } // would strand tiny residue
        } else {
            // next item cannot use this bin; penalize small leftover classes
            score += class_gap as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins with high mean residual: prefer consolidating into full ones
    let tightness = (bin_residual as f64 - mean_residual) / cap;
    score -= tightness * 10.0;

    // Late in the stream, bias toward filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 20.0 + 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Prefer bins with residual close to item size (tight fit)
    let slack = (bin_residual - item_size) as f64;
    score += (slack / cap).powi(3) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness ratio: prefer bins where the item occupies a large fraction
    // of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading when already many
    // bins are open (favor consolidation into existing bins).
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: when open bins are on average very full
    // (low mean residual), a new bin may be warranted; when mean residual is
    // high, penalize opening a new empty bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competes with filled bins.
        score += 20.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            // next item cannot fit into typical open bins -> opening a fresh
            // bin for a big item is reasonable.
            score -= 25.0;
        }
        if item_size > 70 {
            score -= 10.0; // large items fit cleanly into fresh bins
        }
    } else if next_item_size > 0 {
        // Bonus if next item fits exactly into the post-residual of this bin.
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // Early in the stream, allow slightly more liberal bin opening; late in
    // the stream, be conservative (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space, superlinear to discourage small dead gaps.
    score += (post_residual as f64).powf(1.35) * 0.05;

    // --- 2-step lookahead: reward if the next item fits exactly into post_residual ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Next item fits here: reward tight chaining (perfect match rewarded most).
            let gap = post - next;
            score -= (100.0 - gap.min(100.0)) * 0.9;
            // Extra reward for exact or near-exact chaining.
            if gap <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item will NOT fit in this bin's remainder: mild penalty scaled by overflow size.
            score += (next - post) * 0.25;
        }

        // Coupling with mean residual: if this bin's post_residual is near the mean,
        // prefer it (keeps residual distribution tight and predictable).
        let dev = (post - mean_residual).abs();
        score += dev * 0.08;
    }

    // --- Last-chance logic: if this is the ONLY bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large relative to capacity
        // (poor fit candidates elsewhere) or when no open bins fit well.
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin by default...
        score += 40.0;
        // ...but discount the penalty when the item is large (little room for partners anyway)
        score -= tightness * 30.0;
        // And when many bins already exist (spread load, avoid fragmenting many bins).
        if open_bins_count > 0 {
            let avg_load_frac = 1.0 - (mean_residual / bin_capacity as f64);
            score -= avg_load_frac * 10.0;
        }
        // If the next item is large too, a fresh bin can host the pair better.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // --- Stream progression: later in the stream, be greedier about tight fits ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Small tie-breaker favoring fuller bins.
    score -= (bin_residual - post_residual) as f64 * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item can still be placed here; mild reward proportional to fill
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward medium dead space
            let dead = post_residual as f64 / cap;
            score += 12.0 * dead * dead;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (more filled bins first).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (res_f - mean_residual) / cap;
    }

    // Penalize creating very small unusable slivers (< 10 min item size).
    if post_residual < 10 {
        score -= 10.0; // full bin is fine, dead space eliminated
    } else if post_residual < item_size.min(20) {
        score += 6.0; // sliver that likely nothing fits
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more future items to pair).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins are open and residuals are high, avoid spreading items.
        score += 0.5 * open_bins_count as f64;
        // If the current item is large, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
        // If next item is also large, fresh bin pairs well with big items.
        if next_item_size > 40 {
            score -= 6.0;
        }
    } else {
        // Mild reward for keeping items in existing bins early on.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * (1.0 - progress);
    }

    // Nonlinear coupling: squared residual normalized, penalizing half-empty outcomes.
    let norm = post_residual as f64 / cap;
    score += 10.0 * norm * norm * (1.0 - progress_hint(step_index, total_items));

    score
}

#[inline]
fn progress_hint(step_index: usize, total_items: usize) -> f64 {
    step_index as f64 / (total_items.max(1) as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, with non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (minimize post_residual strongly);
    // late in the stream, dead space matters more, so amplify quadratic term.
    let norm_pr = pr / cap;
    let coupling = progress * norm_pr * norm_pr * cap;
    score += coupling * (1.0 + progress);

    // Smooth cubic penalty for very small residuals (dead space) growing with progress
    let dead = (cap - pr) / cap; // fill fraction
    score -= (dead * dead * dead) * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - nxt / cap) * (10.0 + 15.0 * progress);
        } else {
            score += (nxt - pr) / cap * (8.0 + 12.0 * progress);
        }
    }

    // New-bin candidate: empty bin gets a mild penalty unless open bins are tight
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - mean_residual / cap;
        score += 5.0 + 25.0 * (1.0 - mean_tightness) * (1.0 - progress);
    }

    // Slight penalty for proliferation of open bins
    score += open_bins_count as f64 * 0.05;

    // Mean residual alignment: prefer bins whose residual is below mean (already tight)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulus classes.
    let class = post_residual / 10; // integer division threshold classes (0..10)
    let phase = post_residual % 10;

    // Reward residuals that form "perfect" harmonic slots (0, 10, 20, ... divisible classes)
    if phase == 0 {
        score -= 6.0;
    } else if phase <= 2 || phase >= 8 {
        score -= 2.0; // near-aligned classes are still useful
    } else {
        score += 3.0; // awkward middle phases create dead space
    }

    // Very small dead space is excellent (tight fit)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Coupling with next item lookahead: does the leftover class admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host next item: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic match: next item lands exactly on a class boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // leftover too small for next item: penalize dead class
            score += 4.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        // base penalty so we prefer filling existing bins
        score += 18.0;
        // if open bins have large mean residual, new bin is wasteful -> extra penalty
        score += 10.0 * crowded;
        // late in stream with many bins, discourage proliferation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
        // but if current bin is a bad fit (huge item, huge residual), allow new bin
        if item_size as f64 > 0.9 * bin_residual as f64 {
            score -= 30.0;
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    // Modulo-3 harmonic resonance on item vs residual
    if (bin_residual % 3) == (item_size % 3) {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer reusing existing space.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / 50.0).max(0.0) * 12.0;
    }
    // If next item cannot use the leftover, penalize leaving large-but-unusable gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0;
        score -= fragmentation * 20.0;
        score -= (open_bins_count as f64) * 1.5;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if post_residual < 20 {
            score += 15.0; // opening a bin that will be mostly empty is bad
        }
    }

    // Mild stream-progression tie-breaker: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: hugely reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small residuals that nothing (min size 1..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64) * 0.5;
        // Extra reward when the next item fits almost exactly (chained fit).
        let chain_waste = post_residual - next_item_size;
        score -= (chain_waste as f64).min(20.0);
    } else if next_item_size > 0 {
        // Penalize leaving space that the next item cannot use.
        score += (next_item_size as f64) * 0.3;
    }

    // Favor filling bins with low residual relative to mean (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit anywhere) or many bins are already open.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let pressure = (open_bins_count as f64) * 0.15;
        let poor_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        // Base penalty discourages opening new bins; reduced when justified.
        score += 120.0 - large_item * 100.0 - pressure - poor_fit * 90.0;
        // If next item is big, a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.2;
        }
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual dominates).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize wasting residual that the next item cannot use.
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many fitting bins -> we can afford to be picky; penalize loose fits more.
    if fitting_bins_count > 2 {
        score += 0.3 * post_residual as f64 * 0.1 * (fitting_bins_count as f64).min(10.0);
    }

    // Global state: if mean residual is high, prefer consolidating into fuller bins.
    if mean_residual > 20.0 {
        score += 0.05 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Time horizon: early in stream, slightly prefer opening new bins for large items
    // (keeps flexibility); later, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when item is large and no good fit exists.
        let openness = (1.0 - progress) * 15.0;
        score -= openness;
        score += 0.4 * post_residual as f64; // empty bin residual is 100; make it costly later
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 10.0;
        }
    } else {
        // Late stream: reward using open bins more aggressively.
        score -= 8.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residual is plentiful.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: dead space penalized super-linearly as stream progresses
    score += 40.0 * norm_post.powf(3.0) * (0.5 + progress);
    score -= 30.0 * norm_item * (1.0 - norm_post).powf(2.0);

    // Tight-fit reward: smooth quadratic in residual match
    let tight = 1.0 - (norm_post / (norm_item + 1e-9)).abs().min(2.0) / 2.0;
    score -= 20.0 * tight * tight;

    // Last-chance bonus, smoothly damped by progress
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space for next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = norm_post - nx;
        score -= 15.0 * (-diff * diff * 8.0).exp() * (1.0 - progress);
    }

    // Mild penalty when many bins open and this residual is wasteful
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 3.0;
    score += (mean_residual - post) * 0.05;

    // New-bin candidate: penalize moderately so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 45.0 * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "reusable"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else {
        // Classify leftover by divisibility (harmonic classes).
        let mut harmonicity = 0.0f64;
        for &d in &[10u32, 20, 25, 30, 40, 50] {
            if pr % d == 0 {
                harmonicity += 1.0;
            }
        }
        // Leftovers that are multiples of common sizes are useful -> reward.
        score -= harmonicity * 6.0;

        // Dead-space penalty: tiny leftovers (< 10, minimum item size) are waste.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }

        // Mid-range leftovers (roughly half a bin) are the most reusable.
        if pr >= 40 && pr <= 60 {
            score -= 8.0;
        }
    }

    // Lookahead: does the next item fit into the post placement?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // Harmonic match: next item exactly divides the leftover.
            if pr % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here; leftover becomes dead until later.
            score += 6.0;
            if pr < next_item_size && pr < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fit; base score already
        // favors small post_residual, add mild pressure toward fullness.
        score -= (item_size as f64) * 0.15;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly, but more when many bins
        // are already open and fragmented (encourage consolidation).
        score += 15.0 + 2.0 * (open_bins_count as f64).min(20.0);
        // If current bin would be nearly emptied by this item, new bin is fine.
        if post_residual == 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid spreading out.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Mean residual coupling: when average leftover is small, bins are nearly
    // full; prefer placements that keep residuals aligned with the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Penalize wasting a nearly-full bin on a small item (large post_residual left).
    if post_residual > 40 {
        score += 0.35 * (post_residual as f64 - 40.0);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by tiny post residual, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate: allow opening a new bin only when current fits are poor
    // (item leaves big dead space or no tight fit exists).
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; subtract when item is large relative to capacity
        score = bin_capacity as f64 * 0.55 - 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 200.0;
        } else {
            // penalize mismatch scaled by size of mismatch
            score += diff * 0.5;
            // penalize if next item cannot fit into the post-residual
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size as f64 - post_residual as f64) * 1.5;
            }
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual), already base score
        score -= 50.0;
    }

    // Reward tight packing relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize new-bin candidate unless current bins have large unusable residuals
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening a new bin is more acceptable early; penalize more later
        score += 120.0 * (1.0 - 0.5 * progress);
        // if this bin is the last chance, opening a new bin is worse
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // if mean residual across open bins is small, opening is more acceptable
        score -= mean_residual * 0.4;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Avoid leaving dead space below typical minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual < 10 {
        score -= 25.0;
    } else {
        score += 0.35 * post_residual as f64 * (1.0 - tightness);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Time horizon: early in the stream, prefer consolidation into open bins;
    // late in the stream, be more willing to open fresh bins for balance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0 + 0.05 * mean_residual;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth stream-progress coupling: later in stream, tighter packing preferred
    let tight = (pr_norm * (1.0 - progress)).powi(2);
    score += 12.0 * tight * pr_norm;

    // Reward near-perfect fits (small post residual) with smooth decay
    score -= 18.0 * (-pr / 12.0).exp();

    // Penalize dead space that next item can't use
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (0.5 + 0.5 * progress);
        } else {
            score -= 4.0 * (-gap.abs() / 10.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, unless current residual is very wasteful
    if bin_residual == bin_capacity {
        let waste = pr_norm * pr_norm;
        score += 20.0 - 30.0 * waste * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 3.0 * (mean_residual - pr) / cap;

    // Open bins pressure: many open bins -> favor filling existing ones
    score -= 0.8 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable, reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit, best possible
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -6.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr < 10 {
        15.0 // dead space below smallest item class
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Fractional residual: penalize large leftover fractions of capacity
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score += 6.0 * (frac - 0.5); // wasteful big leftover when smaller bins exist
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 20.0;
        } else {
            let nfrac = next_item_size as f64 / pr as f64;
            score -= 10.0 * nfrac;
        }
    } else if next_item_size > 0 {
        // next item won't fit here after placement; mild penalty scaled by how far off
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is very poor
    if bin_residual == bin_capacity {
        let base = 25.0 + frac * 40.0;
        // open new bin only if no open bin offers a tight fit (post_residual small)
        let tight_exists = post_residual <= 15 && bin_residual != bin_capacity;
        score = if tight_exists { 1e9 } else { base + (open_bins_count as f64) * 0.5 };
        // perfect-fit lookahead on a fresh bin is still fine
        if next_item_size > 0 && next_item_size <= pr && next_item_size == pr {
            score -= 10.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (exploration)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - progress); // prefer existing bins early, tighten later
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight — favor it
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps more than large ones.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space below minimum item size is pure waste
        } else {
            // penalty grows super-linearly as gap shrinks toward unusability
            let gap = post_residual as f64;
            score += (10.0 - gap / 10.0).max(0.0) * (10.0 - gap / 10.0).max(0.0) * 3.0;
        }
    } else {
        score -= 25.0; // perfect fill rewarded
    }

    // Reward tight fits: post_residual small relative to item_size
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
        score -= tightness * 20.0;
    }

    // Open bins pressure: discourage spreading across many bins early
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        // If the next item could use the fresh bin too, opening is more attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Prefer bins below mean residual (loose bins) for large items
    if (bin_residual as f64) > mean_residual && item_size > 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fills (post_residual small => already low base).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity.
        score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;
    }

    // Aggressive 2-step lookahead: strongly reward post_residual == next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nx {
            score -= 800.0;
        } else if nx <= pr {
            // Next item fits here afterward: good chain placement.
            let chain_waste = pr - nx;
            score -= 300.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize proportionally to gap.
            score += 0.8 * (nx - pr).min(100.0);
        }
    }

    // Compare post_residual to mean residual across open bins: avoid making
    // this bin an outlier of unusable space.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: keep it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64;
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild stream-progression tilt: later in stream, favor tighter fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Reward leaving just enough room for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: slightly penalize fresh bins so we prefer
    // reusing open bins with good fits, but allow opening when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 6.0;
        if open_bins_count > 0 {
            let fragmentation = mean_residual / (bin_capacity as f64);
            // If existing bins are full-ish, opening a new bin is attractive.
            if fragmentation < 0.25 {
                score -= 10.0;
            }
        }
    }

    // Time-horizon modulation: early in the stream, be conservative (prefer
    // spreading); late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Mild pressure from many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // to keep balance, unless it's a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize wasted residual with a convex (quadratic) term.
    let mut score = norm_pr * norm_pr;

    // Smooth non-linear coupling: waste is worse late in the stream.
    score += 0.8 * norm_pr * (progress * progress);

    // Reward tight fits: small post-residual relative to item size.
    score -= 0.6 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: bonus if next item fits the post residual smoothly.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_ratio = norm_next / norm_pr.max(1e-9);
        score -= 0.5 * fit_ratio * (1.0 - fit_ratio) * 4.0 * norm_pr;
    } else if next_item_size > 0 {
        // Smooth penalty when next item cannot fit the leftover.
        score += 0.4 * norm_next * (1.0 - progress);
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.7 * (1.0 - progress);
    }

    // Discourage spreading across many bins when mean residual is high.
    score += 0.05 * (open_bins_count as f64 / 10.0) * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: make empty bins mildly attractive only early or for big items.
    if bin_residual == bin_capacity {
        score += 0.15 + 0.5 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" residue classes are less likely to absorb future items.
    let class = post_residual % 10;
    score += match class {
        0 => -8.0,                 // perfectly reusable residual (e.g. 0,10,20...)
        1..=4 => 2.0 + class as f64, // small awkward slivers
        5..=7 => -1.0,             // mid-range residual, decent reuse
        _ => 4.0,                  // 8..9 slivers are dead space
    };

    // Integer-division threshold: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 6.0; // dead space penalty
    } else if post_residual >= 2 * quarter {
        score -= 4.0; // half-full or more: attractive bin
    }

    // Lookahead coupling: does this bin remain useful for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0; // keeps the stream flowing in this bin
            // exact modular fit for the next item is a strong bonus
            if post_residual % next_item_size.max(1) == 0 && post_residual > next_item_size {
                score -= 2.0;
            }
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current open
    // bins are badly fragmented (high mean residual spread vs this fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // fresh bin baseline: moderately high score, reduced late in stream
        score = 30.0 + 20.0 * (1.0 - progress) - fragmentation.min(10.0);
        if fitting_bins_count <= 1 {
            score -= 15.0; // no real alternative: opening fresh is fine
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many bins open, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Penalize leaving residual far below mean residual (fragmenting)
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Slight preference for new bin when residual would be tiny relative to next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly (or closely)
    // matches the next item size — this bin stays perfectly usable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let diff = post - nxt;
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // post_residual too small for next item: dead space risk
            let waste = nxt - post;
            score += waste * 0.8;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Penalize bins far below mean residual (they are already loose fits)
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // New-bin candidate: make it attractive only when the current item is large
    // or the lookahead suggests a fresh bin is better. Penalize moderately by
    // default so open bins are used first.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0
            + 0.5 * item_size as f64
            - 10.0 * progress
            + (open_bins_count as f64).sqrt() * 2.0;
        // If next item pairs well with a fresh bin (item + next <= capacity),
        // slightly favor opening a new bin for a clean 2-chain.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is unlikely to be reusable.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && (post_residual as u32) >= next_item_size { 0.0 } else { post_residual as f64 };
        score += 1.6 * dead;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        } else if (post_residual as u32) > next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less as stream progresses.
        score += 12.0 * (1.0 - 0.7 * progress);
    } else {
        score -= 5.0 * progress;
    }

    // Crowd management: many open bins with slack mean residual -> prefer
    // filling bins below the mean residual (reduce fragmentation).
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 3.0 * dev;
    }

    // Mild bonus for using bins that already have content (avoid bin sprawl).
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: penalize wasted residual, with non-linear (quadratic) growth.
    let mut score = pr + 0.35 * (pr / cap) * pr;

    // Tight-fit reward: strongly subtract when post_residual is small but non-negative.
    let tight = 1.0 - (pr / cap);
    score -= 18.0 * tight * tight * tight;

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    let late = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * late * (pr / cap);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new {
        score -= 25.0;
    }

    // Lookahead: reward leaving space that the next item can use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: prefer it only when open bins are congested (high mean residual usage
    // leaves poor fits); otherwise penalize opening a new bin.
    if is_new {
        let congestion = mean_residual / cap;
        score += 30.0 - 22.0 * congestion * congestion;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and mod 25 define
    // "good" leftover classes (highly reusable sizes).
    let pr = post_residual;
    let r10 = pr % 10;
    let r25 = pr % 25;

    // Reward post-residuals in classic reusable classes (10,20,25,50...).
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 {
        score -= 15.0;
    } else if r10 == 0 {
        score -= 5.0;
    } else {
        // penalize awkward dead space, worse for small residues
        score += (10 - r10) as f64 * 1.5;
    }

    // Lookahead coupling: does the post-residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let nr = next_item_size as f64;
            // harmonic class match: both in same decade class
            if (next_item_size / 10) == (pr / 10) {
                score -= 8.0;
            }
            // reward leaving room for next item with small waste
            score -= 10.0 * (nr / cap);
        } else {
            // next item cannot fit here; penalize proportionally
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // scale new-bin appeal with stream progress and crowding
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (1.0 + 0.3 * progress) + 0.1 * open_bins_count as f64;
        // if the item fits perfectly in a fresh bin, opening is cheap
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mean-residual regularization: prefer bins below mean residual (tighter fills)
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Integer-division threshold: bins with post_residual < 10 are near-sealed;
    // slight bonus so they get filled rather than orphaned.
    if pr > 0 && pr / 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact fit with the next item lookahead.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // dead space relative to lookahead item
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is tight.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: mildly discourage opening a new bin unless existing
    // bins would leave very poor residuals.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual as f64 > mean_residual + 30.0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 60.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 40.0; // perfect two-item fill
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow here; penalize proportionally to wasted lookahead.
        score += 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Penalize leaving dead space below the minimum item size (1..=100 range => small slivers).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins whose post residual is near/below mean.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would be badly fragmented
    // or no good fit exists; otherwise penalize opening fresh bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin can host the next item too: mild bonus
            score -= 10.0;
        } else {
            score += 15.0;
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Slight pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0; // residual too small for the lookahead item
    }

    // Reward residual that exactly accommodates the next item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Reward residual that can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when open bins could fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Base penalty for wasting an existing fit; grows with how many alternatives exist.
            score += 30.0 + 5.0 * fitting_bins_count as f64;
            // Early in the stream, prefer consolidating into open bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 20.0 * (1.0 - progress);
            // If existing bins have large mean residual, they should be used.
            score += 0.3 * mean_residual;
            // If the next item is huge, a fresh bin may be justified: soften penalty.
            if next_item_size >= 60 {
                score -= 15.0;
            }
        } else {
            // No alternative: new bin is necessary; slight reward.
            score -= 10.0;
        }
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // Late-stream consolidation: as the stream ends, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: reward tight fits (low post residual), non-linearly.
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Quadratic coupling of post_residual with stream progress:
    // later in the stream, dead space matters more.
    score += 12.0 * (pr / cap) * (pr / cap) * (0.5 + progress);

    // Reward bins that leave room for the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - pr / cap).abs();

    // Penalize opening a new bin when good existing fits exist; allow it early
    // or when post_residual of the new bin would be very large (item small).
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Tight fits are excellent: reward small post_residual strongly.
    if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    }

    // Dead-zone classes: residuals that few item sizes (10..80) can ever fill.
    // Items are 1..100 here; class boundaries via integer division thresholds.
    let class = pr / 10; // 0..10 harmonic class
    match class {
        0 => { score -= 30.0; }          // near-perfect fit
        1 => { score -= 12.0; }          // good
        2 | 3 => { score += 6.0; }       // awkward mid-range gap
        4 | 5 => { score += 3.0; }       // moderate gap
        6 | 7 => { score -= 5.0; }       // roomy, still reusable
        _ => { score -= 10.0; }          // large residual, very reusable
    }

    // Modulo-10 oscillation: residuals divisible by 10 align with common item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == pr && pr > 0 {
            score -= 50.0;
        } else if nxt <= pr && pr - nxt <= 5 {
            score -= 20.0;
        } else if nxt > pr && nxt <= cap {
            // next item won't fit here; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Prefer new bin only when best alternative leaves big dead space.
        if pr > 0 {
            // placing in empty bin gives post_residual = cap - item, large residual
            score += 18.0;
            if fitting_bins_count == 0 {
                score -= 200.0; // no alternative: must open
            }
        }
    }

    // Progress coupling: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mean residual context: if this bin's residual is far below mean, it's tight — good.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        // Tiny unusable dead-space gap: heavy penalty scaled by gap smallness
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Lookahead (k=2): residual able to serve the next item is valuable
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // Gap too small for the upcoming item: mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin (only open bin that fits): strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: charge an opening cost that grows
        // with stream progress (late stream => pack tighter, avoid sprawl)
        score += 45.0 + progress * 20.0;
        // Large items justify opening a fresh bin
        score -= item_size as f64 * 0.25;
        if fitting_bins_count == 0 {
            // No open bin can fit the item: new bin is necessary
            score -= 70.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Fresh bin can host the incoming pair: reward leftover pair room
            score -= (bin_capacity - item_size - next_item_size) as f64 * 0.4;
        }
    } else {
        // Consolidation pressure: many open bins -> favor filling existing ones
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins already more filled than average (residual below mean)
        let diff = (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a slight super-linear penalty.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score = pr + 0.35 * (pr * pr) / cap;

    // 2-step lookahead: reward exact or near match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap <= 1.0 {
            score -= 30.0; // perfect chain: next item fills this bin exactly
        } else if gap <= 5.0 {
            score -= 18.0 - 2.0 * gap;
        } else {
            // penalize leaving residue that next item cannot use well
            score += 0.25 * gap;
        }
        // next item chains into another bin's residue? less urgency here
        let next_fits_here = nxt <= pr;
        if !next_fits_here {
            score += 6.0;
        }
    } else {
        // last item: only tightness matters
        score -= 5.0;
    }

    // Relative to mean residual: bins with above-average residual are better donors.
    let dev = pr - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        // but if next item is huge and current fit is terrible, opening is fine
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() > 25.0 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
