pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let post_residual = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, superlinearly (dead space grows costly).
    let norm_post = post_residual / cap;
    let mut score = post_residual * (1.0 + norm_post * norm_post);

    // Smooth progress coupling: residual waste matters more late in the stream.
    score += 12.0 * progress * norm_post * norm_post * cap;

    // Reward tight fits: smooth bump when post_residual is small.
    let tight = (-norm_post * 8.0).exp();
    score -= 10.0 * tight * (1.0 + progress);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size as f64) / cap);
        score -= 6.0 * snug * (1.0 - progress);
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize unusable slivers.
        score += 4.0 * (1.0 - norm_post) * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when bin is far above mean residual (keeps bins balanced),
    // damped by smooth interaction with progress.
    score += 2.0 * ((post_residual - mean_residual) / cap).abs() * (0.3 + 0.7 * progress);

    // Discard opening new bins when plenty of open bins can fit the item,
    // unless the fit would be terrible (large post_residual).
    if bin_residual == bin_capacity {
        let waste = item_size as f64 / cap;
        score += 20.0 * (1.0 - waste) * (1.0 - progress) + 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Harmonic class of post_residual: quantize into classes of 10 ---
    let class = post_residual / 10;
    score -= (10 - class.min(10)) as f64 * 2.0; // tighter classes rewarded

    // Dead space: slivers unusable by any item (items >= 1, but tiny gaps are waste)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit
    if post_residual == 0 {
        score -= 50.0;
    }
    // Residuals in the "harmonically convenient" band 10..=30 pack well later
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }
    // Integer-division threshold: post_residual divisible by 4 keeps quarter-slots
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // baseline: mid-strength, so good fits beat it, bad fits lose to it
        score = cap * 0.5 + post * 0.1;
        // large upcoming item favors a fresh bin
        if next_item_size >= 60 {
            score -= 12.0;
        }
        // many open bins: discourage opening yet another
        score += open_bins_count as f64 * 1.5;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0; // next item also fits here: excellent chaining
        } else {
            score += 5.0;  // next item won't fit after this placement
        }
        // harmonic modulo check: next item shares class with post_residual
        if post_residual > 0 && (post_residual % next_item_size.max(1)) == 0 {
            score -= 6.0;
        }
    }

    // Mild progression scaling
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward tight fits generally (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // If the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Post residual too small for the next item: dead space, penalize.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is low (all bins nearly full),
        // opening a new bin is fine.
        score -= mean_residual * 0.5;
        // Early in stream, be less reluctant to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If item is large, avoid fragmenting existing bins.
        if item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly with fill level.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, amplify non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item cannot fit in leftover: penalize dead space creation.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Compare post_residual to mean residual across open bins: leaving a residual
    // far below mean creates an outlier bin that is hard to fill later.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins can fit the item, especially
    // early in the stream when consolidation is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 18.0 + 25.0 * (1.0 - progress);
    }

    // Large leftover chunks (>50) are reusable; small leftovers (<20) are dead space.
    if post_residual > 50 {
        score -= 4.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // A brand-new bin is attractive when existing bins would leave awkward
        // dead space, or when the item is large relative to mean residual.
        // Base cost of opening a new bin, discounted as stream progresses
        // (early on, opening bins builds flexibility for the future).
        let mut new_bin_cost = 40.0 * (1.0 - 0.5 * progress);
        // If the item fits poorly everywhere (few fitting bins), opening is fine
        if fitting_bins_count <= 1 {
            new_bin_cost -= 25.0;
        }
        // Large items relative to mean residual favor a fresh bin
        let mean_res_gap = mean_residual - item_size as f64;
        if mean_res_gap < 5.0 {
            new_bin_cost -= 15.0;
        }
        // Lookahead: if next item is large, a fresh bin gives room
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_bin_cost -= 10.0;
        }
        return new_bin_cost;
    }

    // ---- Existing-bin scoring ----
    // Perfect fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize creating small unusable dead space (< 10, min item size)
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 8.0;
        }
    }

    // Reward tight fits relative to residual: waste ratio
    let waste_ratio = post_residual as f64 / bin_residual as f64;
    score += 20.0 * waste_ratio;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        // Many options: be pickier about quality (amplify penalties)
        score += 5.0 * waste_ratio;
    }

    // Lookahead coupling: if the post residual exactly fits the next item,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0; // residual still useful for next item
        } else {
            // residual too small for next item: mild penalty scaled by gap
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 10.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins (consolidation) rather than spreading.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 6.0;
    }

    // Time horizon: late in the stream, be more aggressive about closing out
    // bins tightly (less concern about future flexibility).
    score -= 10.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let cap = bin_capacity as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, small leftovers are tolerable; late, they become costly dead space.
    let dead_penalty = (pr / cap).powi(2) * (1.0 + 2.0 * progress);
    score += 6.0 * dead_penalty;

    // Reward good utilization non-linearly: item_size relative to capacity.
    let fill = it / cap;
    score -= 4.0 * fill * fill * (1.0 + progress);

    // Lookahead: if next item fits into the resulting residual, reward heavily.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let n = next_item_size as f64;
        let snug = 1.0 - ((pr - n) / cap).abs();
        score -= 5.0 + 3.0 * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty, stronger when residual is tiny.
        score += 1.0 + (pr / cap) * 2.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Prefer bins with below-mean residual (consolidate emptier space elsewhere).
    score += 0.5 * (pr - mean_residual) / cap;

    // New-bin candidate: make it attractive only when current bins are crowded
    // or the fit is bad; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let bad_fit = (pr / cap - 1.0).abs(); // = 0 for empty bin; use residual vs item instead
        let waste = (cap - it) / cap;
        score = 3.0 + waste * (10.0 - 4.0 * progress) - 0.2 * crowd;
        if fitting_bins_count <= 2 {
            score += 20.0; // existing bins are scarce: opening new bin is fine
        }
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: leftovers that are "useful" residue classes
    // (multiples of common item granularities) are less dead than odd remainders.
    let pr = post_residual;
    let class_bonus: f64 = if pr % 50 == 0 {
        -40.0
    } else if pr % 25 == 0 {
        -25.0
    } else if pr % 20 == 0 {
        -20.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // odd/unusable class penalty
    };
    score += class_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            // next item fits but leaves another leftover: grade by resulting dead space
            let npr = pr - next_item_size;
            score -= 40.0 - (npr as f64).min(40.0);
            if npr % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's leftover at all -> dead space risk
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Dead-space penalty grows when leftover is tiny but nonzero (hardest to reuse).
    if pr < 10 {
        score += (10 - pr) as f64 * 6.0;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below the mean (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream conservatism: keep bins flexible early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fills
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 30.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    }

    // Prefer bins whose residual is below mean (tighter bins get filled first)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 60.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 40.0;
        }
    }

    // Late in stream: be more aggressive about closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good, amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest conceivable item.
    if post_residual < 10 {
        score -= 8.0; // nearly-perfect closure bonus
    } else if post_residual < item_size && post_residual < next_item_size.max(1) {
        score += 6.0; // dead space: nothing known can use it
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.05 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0; // blocks the lookahead item
    }

    // Global state coupling: when many bins are open, discourage spreading;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score += 0.6 * crowding * (mean_residual / bin_capacity as f64).max(0.0);

    // New-bin candidate: make it attractive only when current fit is poor
    // or the bin is genuinely fresh; otherwise it should lose to open bins.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) > (next_item_size.max(1));
        score += 10.0 * tightness; // baseline penalty vs a real placement
        if good_fit_exists {
            score += 8.0; // extra penalty: an open bin fits well
        }
        if progress > 0.5 && open_bins_count > 4 {
            score -= 4.0; // late stream with many bins: consolidation matters
        }
    }

    // Mild time-horizon term: early on, prefer flexibility (larger post_residual);
    // late, prefer tight packing.
    score += (1.0 - progress) * 0.02 * post_residual as f64;
    score -= progress * 0.03 * tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: reward tight fits via non-linear polynomial in post_residual
    let mut score = pr.powf(1.35) * (1.0 + 0.5 * progress);

    // Smooth coupling: tight fill gets progressively more valuable as stream advances
    score -= 40.0 * fill * fill * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead: bonus if next item fits the post-residual exactly-ish (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (-gap * gap / 200.0).exp();
    }

    // Last-chance bonus: penalize opening new bin when few fitting bins exist
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for bin proliferation late in stream
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // New-bin candidate: smooth bias so empty bins only win when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let unit = (bin_capacity / 10).max(1);

    let post_class = post_residual / unit;
    let next_class = next_item_size / unit;
    let post_mod = (post_residual % unit) as f64;
    let next_mod = (next_item_size % unit) as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let mean_pressure = if cap > 0.0 {
        (mean_residual / cap).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let next_exists = next_item_size > 0;
    let next_fits = next_exists && next_item_size <= post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    let new_post = bin_capacity.saturating_sub(item_size);
    let next_fits_new = next_exists && next_item_size <= new_post;
    let next_exact_new = next_exists && next_item_size == new_post;

    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= cap;
    } else if next_fits {
        let alignment = if post_class > next_class {
            1.0
        } else if post_class == next_class && post_mod >= next_mod {
            0.8
        } else {
            0.0
        };

        let mut lookahead_reward = 0.30 + 0.025 * next_class as f64 + 0.08 * alignment;
        if next_item_size == post_residual {
            lookahead_reward += 0.18;
        }

        score -= cap * lookahead_reward;
    } else if next_exists {
        let dead_penalty = match post_class {
            0 => 0.85,
            1 => 0.65,
            2 => 0.35,
            3 => 0.10,
            _ => 0.0,
        };

        score += cap * dead_penalty;

        let harmonic_lower = next_class * unit;
        if post_residual >= harmonic_lower && post_residual < next_item_size {
            score += cap * 0.05;
        }

        if next_fits_new && (post_class == 0 || next_exact_new) {
            score += cap * 0.10;
        }
    } else if post_class == 0 {
        score += cap * 0.15;
    }

    if !is_new_bin {
        if fitting_bins_count == 1 {
            if post_residual == 0 {
                score -= cap * 0.20;
            } else if next_fits
                || (post_class >= 2
                    && !(next_exists && !next_fits && next_fits_new))
            {
                score -= cap * 0.12;
            }
        }
    } else {
        let mut opening_penalty = cap * 0.65;

        opening_penalty += cap * 0.015 * (open_bins_count as f64).min(12.0);
        opening_penalty += cap * 0.10 * mean_pressure;
        opening_penalty += cap * 0.12 * progress;

        if fitting_bins_count > 0 {
            opening_penalty += cap * 0.06 * (fitting_bins_count as f64).min(3.0);
        } else {
            opening_penalty -= cap * 0.45;
        }

        score += opening_penalty;

        if next_fits {
            let alignment = if post_class > next_class {
                1.0
            } else if post_class == next_class && post_mod >= next_mod {
                0.8
            } else {
                0.0
            };

            let mut lookahead_reward =
                0.55 + 0.03 * next_class as f64 + 0.10 * alignment;

            if next_item_size == post_residual {
                lookahead_reward += 0.40;
            }

            score -= cap * lookahead_reward;
        } else if !next_exists {
            if fitting_bins_count > 0 {
                score += cap * 0.25;
            }
        } else if post_class >= 5 {
            score -= cap * 0.08;
        } else {
            score += cap * 0.10;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 5.0; // large leftover space is reusable
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the gap -> dead space likely
        score += 15.0;
    }

    // Last-chance bin: only bin that can fit the item -> strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        score += 12.0 + 2.0 * open_bins_count as f64;
        // but if this is a big item and mean residuals are small, new bin is fine
        if item_size > 60 && mean_residual < item_size as f64 * 1.2 {
            score -= 20.0;
        }
    }

    // Favor bins tighter than average (below-mean residual means well-used bin)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Early stream: slight preference for consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving dead space next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 80.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare post_residual against mean residual: keep residual distribution balanced
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual
    if bin_residual == bin_capacity {
        score += 120.0 + 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 40.0;
        }
    }

    // Mild late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score -= (1.0 - x) * (1.0 + progress) * 20.0;
    score += x * x * (1.0 - progress) * 15.0;
    score -= x * x * x * progress * 25.0;

    // Prefer bins whose residual is close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 3.0;

    // New-bin candidate: penalize slightly unless current residual is tiny
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress) - (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space in the "hard" classes
    // (small leftovers that few future items can use) is penalized more.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -30.0,                       // perfect fit: strongly reward
        1..=10 => 25.0,                   // tiny unusable sliver
        11..=20 => 15.0,
        21..=40 => 8.0,                   // mid classes are reusable
        41..=70 => 0.0,
        _ => -6.0,                        // large residual still flexible
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: leftover congruent to small
    // residues mod common item sizes (10..=30) is more likely to be filled.
    let mut harmony = 0.0;
    for m in [10u32, 15, 20, 25, 30, 40, 50] {
        let r = pr % m;
        if r == 0 {
            harmony += 6.0;
        } else if r <= 5 {
            harmony -= 3.0;
        }
    }
    score -= harmony;

    // Best-fit flavor: tighten relative to capacity fraction.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 20.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: leftover class after chaining matters
            let chain_left = pr - next_item_size;
            score -= 10.0 + (chain_left as f64).min(20.0);
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: discourage opening a new bin when decent fits exist,
    // but allow it when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        let base = if crowded { 10.0 } else { 45.0 };
        // Early in stream, opening fresh bins is cheaper (more future items
        // to consolidate); later, squeeze into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base * (1.0 - 0.5 * progress);
        // Harmonic bonus: fresh bin residual = capacity, a "perfect" class
        score -= 5.0;
    } else {
        // Mild reward for spreading load when many bins are open
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Penalize bins whose residual deviates wildly from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (<= 1) are pure waste; the smaller the leftover gap, the worse.
    if post_residual > 0 {
        // Non-linear penalty peaking for tiny unusable gaps.
        let gap = post_residual as f64;
        score += 40.0 * (1.0 - gap / bin_capacity as f64).powi(6);
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // If a future item fits exactly into the post residual, big reward (lookahead k=2).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // The next item cannot use this bin anyway; mild penalty for stranded gap.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: as bins accumulate, discourage spreading (favor filling existing).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual coupling: bins far below mean residual are good "sink" bins.
    score -= 3.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins means prefer existing bins; make new bin costly).
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (no bins to fill yet).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving medium dead space
            let dead = (post_residual as f64 - 0.0).max(0.0);
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 10.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    } else {
        // last item: just minimize post_residual strongly
        score -= 20.0;
    }

    // Compare post_residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 12.0 * (0.5 - rel); // better than average residual
        } else if rel > 1.5 {
            score += 8.0 * (rel - 1.5); // much worse than average
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let waste = post_residual as f64; // full capacity wasted if only this item goes in
        score += 15.0 + 5.0 * pressure * (item_size as f64 / bin_capacity as f64);
        // But if next item is large and no bin fits both, new bin can be attractive
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && fitting_bins_count > 0 {
            score += 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in stream, prefer consolidating into open bins less; new bin less penalized
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    }

    // Mild penalty for very small leftover fragments that nothing (min size 1..100) may use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        } else {
            // Reward bins whose leftover exactly accommodates the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.5 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Many fitting bins: mild penalty for spreading too thin.
    if fitting_bins_count > 1 {
        score += 0.4 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, encourage consolidation into open bins;
    // late in stream, prefer tightest fit even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * tightness;

    // Global state coupling: if mean residual is high, we have slack everywhere;
    // prefer bins that reduce fragmentation (small post_residual) more strongly.
    score += 0.3 * (mean_residual / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item_size (near-perfect fill).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 4.0 * gap * gap;

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 12.0;
        let relief = if fitting_bins_count == 0 { 10.0 } else { 0.0 };
        let big_item_relief = (item_size as f64 / bin_capacity as f64) * 6.0;
        score += base_penalty - relief - big_item_relief;
    }

    // Mild penalty on very small post residuals that waste < next small items,
    // but only mid-stream where fragmentation matters.
    if post_residual > 0 && post_residual < 10 {
        score += 1.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins (low post residual); later, tolerate spread.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (1.0 - progress) * (1.0 - progress);
    score += poly * cap * 0.5;

    // Penalize dead space relative to mean residual (quadratic coupling)
    let dead = pr as f64 - mean_residual;
    score += 0.3 * dead * dead / cap;

    // Reward tight fits: item nearly fills the bin
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * cap * 0.25;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    }

    // Lookahead: if next item fits in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= (next_item_size as f64 / cap) * cap * 0.2;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 / cap) * 10.0;
    }

    // Slight preference to consolidate into fewer bins
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid creating
    // dead space that no plausible item (>=1) can use anyway.
    let post = post_residual as f64;
    if post == 0.0 {
        score -= 25.0; // perfect fill
    } else if post <= 5.0 {
        score -= 18.0;
    } else if post <= 15.0 {
        score -= 10.0;
    } else {
        // dead-space penalty grows super-linearly for large leftovers
        score += 0.35 * (post - 15.0);
    }

    // Harmonic classes: classify post_residual by its residue modulo 10.
    // Residues near 0 are "clean" slots (likely reusable by future items);
    // odd/awkward residues are less reusable.
    let residue = post_residual % 10;
    let residue_bonus = match residue {
        0 => 8.0,
        1 | 9 => -2.0,
        2 | 8 => 0.0,
        3 | 7 => -1.5,
        4 | 6 => -0.5,
        _ => 1.0, // residue 5
    };
    score -= residue_bonus;

    // Integer-division thresholds: which harmonic class (post/10) the bin lands in.
    let class = post_residual / 10;
    score -= match class {
        0 => 6.0,
        1 => 4.0,
        2 => 2.0,
        3 => 0.0,
        _ => -1.0,
    } as f64;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves further waste: mild reward scaled by fit tightness
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 3.0;
        }
    }

    // New-bin candidate: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // if item is large relative to capacity, new bin is more attractive
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 12.0 * frac;
        }
        // if many bins are open with high mean residual, prefer spreading
        if mean_residual > 40.0 {
            score -= 5.0;
        }
        // no last-chance urgency exists for the empty bin itself
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post / cap);

    // Slight preference for bins whose residual is near the mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Dead-space penalty if the leftover gap cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (below mean residual means this bin is tighter than average -> use it).
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // New empty bin candidate: penalize mildly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 70.0 + open_bins_count as f64 * 0.5;
    }

    // Late-stream conservatism: as stream ends, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining: zero waste over two steps
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 15.0 * (1.0 - (leftover as f64) / (bin_capacity as f64));
        } else {
            // next item cannot use remaining space; penalize proportionally to gap
            let gap = next_item_size - post_residual;
            score += 0.3 * gap as f64;
        }
    }

    // Prefer bins with residual below mean (compact packing), penalize outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could still take the item,
    // unless the item is large relative to capacity (better in fresh bin).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 10.0 + 20.0 * (1.0 - fill_ratio);
        } else {
            score -= 5.0 * fill_ratio;
        }
    }

    // Slight preference for keeping many bins consolidated early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly favor tight fits: penalize large post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // extra reward when next item fits snugly too
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty for leaving awkward gap
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early/mid stream.
    if bin_residual == bin_capacity {
        let urgency = 1.0 - progress;
        score += 45.0 * urgency + 10.0;
        // but if open bins have high mean residual (fragmented), new bin less bad
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Prefer bins with residual far below mean (consolidate waste into few bins).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Mild preference to fill already-open bins as count grows.
    score += open_bins_count as f64 * 0.5;

    // Late stream: prioritize closing bins tightly.
    if progress > 0.7 {
        score += post_residual as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits, with non-linear (quadratic) shaping of dead space.
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early in the stream, keep residual flexible; later, reward tight packing more.
    let flex = (1.0 - progress) * (1.0 - progress);
    score += flex * 6.0 * (pr / cap);

    // Penalize bins whose residual deviates from mean residual (encourage balance),
    // with smooth quadratic term.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    }
    // If next item would be stranded by this placement, add mild penalty.
    if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) <= bin_residual as f64 {
        score += 4.0 * (1.0 - progress);
    }

    // New empty bin candidate: penalize opening a new bin unless it's clearly better
    // (e.g., few open bins or the item fits poorly everywhere).
    if bin_residual == bin_capacity {
        score = cap + 10.0 - 5.0 * progress - 2.0 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space classes".
    // Residues near 0 (perfect fit) are heavily rewarded; mid-range residues penalized.
    let post_mod = post_residual % 10;
    let mod_penalty: f64 = match post_mod {
        0 => -30.0,
        1 | 9 => -12.0,
        2 | 8 => 4.0,
        3 | 7 => 8.0,
        _ => 14.0,
    };
    score += mod_penalty;

    // Integer-division threshold: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.10 {
        score -= 25.0; // nearly full bin: excellent
    } else if frac <= 0.30 {
        score += 6.0;
    } else if frac <= 0.60 {
        score += 2.0;
    } else {
        score += 10.0; // leaving more than 60% empty is wasteful
    }

    // Lookahead coupling: if next item fits exactly in post_residual (harmonic match), reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_mod = next_item_size % 10;
        if post_mod == next_mod % 10 || post_residual % next_item_size.max(1) == 0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual anyway; slight penalty for stranding space.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when residual of open bins is globally tight or no fit is good.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is penalized mildly; it wins only if all open bins would leave bad residue.
        let best_possible = if post_mod == 0 { 0.0 } else { 10.0 };
        score = 100.0 - progress * 10.0 + best_possible;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced: no open bin fits
        }
    }

    // Slight preference for denser bins (lower mean residual => bins are well filled).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Tie-break: prefer bins with tighter fit relative to item size.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals below the typical minimum item size are dead zones.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Heavy penalty proportional to how much capacity was "burned" into dead space.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits aggressively (tight packing is the top priority).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins that are already tighter than average.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.35;

    // Open-bin pressure: discourage spreading across many bins when few fitting bins exist,
    // but encourage using the "last chance" bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    score += open_bins_count as f64 * 0.15;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this leftover; leftover risk of dead space grows.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // New-bin candidate handling: an empty bin is attractive early in the stream
    // or when this item would leave a large awkward gap in an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins slightly less over time (consolidate late in the stream).
        score += 20.0 + progress * 15.0;
        // But if placing here would create severe dead space, opening a new bin wins.
        if (post_residual as f64) < dead_threshold && item_size < bin_capacity {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post_residual exactly matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if gap == 0.0 {
            score -= 60.0; // perfect two-item chain: fill bin completely with next item
        } else if pr >= nxt {
            // next item still fits: penalize proportionally to leftover after the pair
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space relative to next size
            score += 0.5 * gap;
        }
    } else {
        // Last item: reward tight fits maximally
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (tighter bins), discourage dumping into loose bins.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative to residuals
    // or no good chain exists; add a mild penalty so open bins are usually preferred.
    if bin_residual == bin_capacity {
        score += 8.0;
        // but if next item chains perfectly with the fresh bin, allow it
        if next_item_size > 0 && (next_item_size as f64 - item_size as f64).abs() < 1.0 {
            score -= 10.0;
        }
    }

    // Slight preference to consolidate early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (wasted space dominates).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With several options, prefer bins that become least usable.
        score += (post_residual as f64) * 0.1;
    }

    // Lookahead: if next item fits the post residual, this placement is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use.
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Penalize opening a new bin, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // If mean residual across open bins is large, reusing them is better.
        score += mean_residual * 0.3;
    } else {
        // Favor bins whose residual is below the mean (tighter bins get filled first).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Small nudge to keep residual from being awkwardly small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted space, scaled by stream progress
    let mut score = pr_norm * (1.0 + 2.0 * progress * progress);

    // Smooth non-linear coupling: small post-residuals are increasingly valuable early
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (1.0 - progress) * 3.0;

    // Penalize dead space: post_residual too small for the smallest plausible item
    let dead = if pr_norm < 0.01 { 5.0 } else { 0.0 };
    score += dead * pr_norm * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.5 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.5 * pr_norm * (next_item_size as f64 / cap);
    }

    // Mean residual coupling: prefer bins near the mean residual (keeps balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.8 * dev * dev;

    // Mild penalty for too many open bins relative to progress
    score += (open_bins_count as f64 / (1.0 + progress * 50.0)) * 0.02;

    // New-bin candidate shaping: empty bin gets a mild baseline penalty that grows
    // late in the stream, but is attractive when post_residual would be tiny waste
    if bin_residual == bin_capacity {
        score += 1.5 * progress + 0.3;
        if pr_norm < 0.2 && item_size as f64 > 0.7 * cap {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands (capacity fractions)
    let pr = post_residual as u32;
    let class = pr % 10;
    // Dead-space penalty: residuals in awkward classes (1..9 mod 10) are hard to fill
    if pr > 0 && class != 0 {
        score += (10 - class) as f64 * 0.35;
    }
    // Perfect-fit residual classes get strong reward
    if pr == 0 {
        score -= 40.0;
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    }

    // Integer-division thresholds on post_residual: tiny leftovers are dead space
    if pr <= 10 && pr > 0 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of remaining slack after next item
            let slack_class = (pr - next_item_size) % 10;
            score -= 10.0 - 0.5 * slack;
            if slack_class == 0 { score -= 5.0; }
            if (pr - next_item_size) % 25 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: mild penalty scaled by overflow
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 20 { score -= 10.0; }
    }

    // Prefer tighter fits: relative fill fraction
    let fill = (item_size as f64) / cap;
    score -= 8.0 * fill;

    // New-bin candidate handling: baseline cost of opening a fresh bin
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 12.0;
        // open a new bin only if no existing bin gives a decent fit
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item benefits from fresh space
        }
    }

    // Mild stream-progression pressure to consolidate late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress;

    // Encourage balance against mean residual: avoid extreme outliers
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let min_useful = 10.0f64; // smallest plausible item footprint
        if (post_residual as f64) < min_useful {
            score += (min_useful - post_residual as f64) * 40.0;
        } else {
            // Soft quadratic penalty on wasted space
            score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are low-value.
    if bin_residual != bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += pressure * 3.0;
    }

    // New-bin candidate: make it attractive only when item fits poorly everywhere
    // (i.e., this empty-bin call with residual == capacity gets a calibrated baseline).
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64; // == item_size baseline
        score += 8.0; // slight default cost: prefer reusing open bins when fit is decent
        if fitting_bins_count == 0 {
            score -= 50.0; // no other option: open new bin
        }
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 * 0.9 {
            score -= 10.0; // next item may pair with the fresh bin
        }
    }

    // Lookahead: favor bins whose post_residual accommodates the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // dead space relative to lookahead
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end up exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly matches the post residual,
    // this placement chains into a perfect fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward proportional to tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * tightness;
        } else {
            // Next item will NOT fit in the leftover: penalize dead space,
            // worse when the leftover is small and unusable.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 40.0 + 0.5 * dead;
            }
        }
    }

    // Penalize residual far below the mean residual (creating fragmented slivers),
    // reward keeping residuals near the fleet average.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the fit into existing bins would be poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let fit_quality = post_residual as f64; // = capacity - item for new bin
        score += 200.0 * (1.0 - crowding);
        if fit_quality < 20.0 {
            score += 300.0; // large item, fresh bin is a good home
        }
    }

    // Slight preference for filling older/denser bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large dead space quadratically, slightly damped late in stream.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64) * (1.0 - 0.3 * t);

    // Reward tight fits (small post_residual) strongly.
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if next_item_size as f64 <= post_residual as f64 + 10.0 {
            score += 3.0; // near-miss dead space risk
        }
    }

    // Prefer fuller bins relative to fleet mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for keeping number of open bins small early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: penalize moderately so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 - 5.0 * t;
        // Opening a new bin is attractive if the item is large and would leave tiny residual elsewhere.
        if item_size as f64 > bin_residual as f64 - 15.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: residual normalized, penalize mid-range waste quadratically
    let r = pr / cap;
    score += 18.0 * r * (1.0 - r) * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - r) * (1.0 - r) * (0.3 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - fit_gap * fit_gap);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space mildly
        score += 6.0 * r;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - r * r);
    }

    // Crowding: many open bins with high mean residual -> prefer filling existing bins
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score -= 0.05 * crowd * progress;

    // Smooth polynomial of progress modulating waste penalty
    let p2 = progress * progress;
    score += pr * (0.1 + 0.3 * p2) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that pair well
    // with small items (mod classes 0/5/10 are "harmonic" with typical sizes).
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect closure
    } else {
        let m = r % 10;
        score += match m {
            0 => -12.0,
            5 => -6.0,
            1 | 9 => 8.0,
            _ => 2.0,
        };
    }

    // Dead-space penalty: residuals too small for the minimum item size.
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Harmonic pairing: if the lookahead item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size < r {
            let gap = r - next_item_size;
            if gap < 10 {
                score += 18.0 * (1.0 - gap as f64 / 10.0); // near-exact but not exact: bad
            } else {
                score -= 8.0; // leaves room for another item after
            }
        } else {
            // next item cannot use this residual: residual becomes dead space
            score += (r as f64) * 0.15;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the
    // current bin would leave a badly fragmented residual.
    if bin_residual == bin_capacity {
        // Harmonic threshold: open a new bin if placing here leaves a residual
        // in an awkward mod class (fragmented leftover).
        let awkward = r > 0 && (r < 15 || (r % 10 >= 1 && r % 10 <= 4 && r < 40));
        if awkward {
            score -= 15.0;
        } else {
            score += 30.0; // keep using existing bins when fit is decent
        }
    }

    // Capacity-fraction coupling: penalize wasting large fractions of capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Progression: as stream advances, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Mean-residual alignment: prefer bins near the mean residual (balanced use).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) but awkwardly small for reuse are penalized.
    if post_residual > 0 {
        // Non-linear dead-space penalty: small residuals are "dead" unless 0.
        let dead_threshold = 10.0; // smallest observed item scale
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Perfect fit bonus: strongly reward exact fills.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Penalize leaving a gap that cannot fit the lookahead item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward reserving space for the next item when it fits snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(20) as f64 * 0.5;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins lightly,
    // but encourage using existing bins when mean residual is high.
    score += (open_bins_count as f64).ln() * 2.0;
    score -= mean_residual * 0.05;

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the current placement creates bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // If mean residual across open bins is large, prefer reusing them.
        score += mean_residual * 0.15;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual near 0) with non-linear coupling.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5.0 - post_residual as f64) * 20.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 150.0;
        }
        // Penalize leaving residual just below next item (dead space trap).
        if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 60.0;
        }
    }

    // Compare post_residual against mean residual: creating outliers (very
    // small residual) wastes space; very large residual is a good host bin.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.5;
    } else {
        score -= (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize tight fits that leave unusable slivers relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += tightness * tightness * 30.0;

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // Slight penalty for opening new bins when many are open.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= 0.9 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(4) * 40.0;

    // Dead-space penalty: post_residual too small for any item (min size 1..=10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0 * (next_item_size as f64 / 100.0);
        }
        // Perfect chaining: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding: many open bins -> prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score -= 8.0 * (open_bins_count as f64).ln() * (0.5 + progress);
    }

    // Global residual awareness: penalize bins far above mean residual when mean is high.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late-stream tightening: favor minimal waste as stream progresses.
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: keep it slightly attractive only when item is small or stream is early.
    if bin_residual == bin_capacity {
        let new_bin_bias = 15.0 - 25.0 * (item_size as f64 / 100.0) - 20.0 * (1.0 - progress);
        score += new_bin_bias.max(-30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_weight = 0.5 + 0.5 * t * t; // later: penalize residual more
    let mut score = pr * (1.0 + 0.8 * progress_weight);

    // Non-linear dead-space penalty: small residuals are quadratic dead space
    if fit_frac > 0.0 {
        score += 40.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (1.0 - fit_frac);
    }

    // Reward tight fits (small post_residual) with smooth inverse term
    score -= 60.0 * (-pr * pr / (cap * cap)).exp();

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 30.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 20.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: avoid outliers vs. average bin state
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so we prefer reusing open bins,
    // decaying with progress and number of open bins
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - t) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets
    let frac = item_size as f64 / bin_capacity as f64;
    let item_class = (frac * 10.0).floor() as i64; // 0..=10

    // Harmonic class of the post-residual dead space
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let post_class = (post_frac * 10.0).floor() as i64;

    // Perfect / near-perfect fills: harmonic classes 8,9,10 of post_residual
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_class >= 8 {
        score -= 12.0; // small dead space is good
    } else if post_class <= 2 {
        score += 8.0;  // large dead space penalized
    }

    // Dead space that CANNOT fit the typical small item (mod-10 harmonic grid)
    // Items 1..100 unknown; assume a harmonic quantum of 10 for reusability checks
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver: very bad
    }

    // Next-item lookahead: harmonic compatibility between post_residual and next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into this bin's future residual
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0; // perfect chain
            } else if slack <= 10 {
                score -= 15.0;
            } else {
                score -= (10.0 - slack.min(10) as f64) * 0.5;
            }
        } else {
            // next item cannot use this residual: dead space likely
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // modulo harmony: post_residual and next_item share a common divisor class
        let gcd_like = if next_item_size > 0 {
            let mut a = post_residual;
            let mut b = next_item_size;
            while b > 0 { let t = a % b; a = b; b = t; }
            a
        } else { 0 };
        if gcd_like >= 10 {
            score -= 5.0; // harmonic alignment: residual divisible into next item's class
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open new bins when all fits would be terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall (small residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // Mild penalty for proliferating many open bins
    score += open_bins_count as f64 * 0.05;

    // Tie-break with mean residual: prefer bins below mean residual (tighter)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless the item fits
    // very poorly in every open bin.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item could use the leftover space, reward it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better.
    score -= 3.0 * (item_size as f64) / (bin_capacity as f64);

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space creation.
        score += 4.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Relative to mean residual: bins with residual below mean are more "used", prefer filling them.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when open bins could still accommodate reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + (post_residual as f64) * 0.3;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize dead space that is too small for typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits well in post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize blocking the next item if it would have fit elsewhere.
        score += 8.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 15.0 + progress * 25.0 + (open_bins_count as f64) * 1.5;
        // But early on with few bins, opening is cheap.
        if progress < 0.2 && open_bins_count < 4 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins more strongly late in the stream.
        score -= progress * 10.0;
    }

    // Global state coupling: if mean residual is high, prefer filling a bin
    // that is below-average residual (balance reduction of open capacity).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Penalize opening bins when many are already open and could fit.
    if fitting_bins_count > 3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap); // 1 = perfect fit

    // Base: post residual, with smooth non-linear penalty on wasted space
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Reward tight fits with a smooth polynomial coupling of tightness and progress
    score -= 12.0 * tightness * tightness * (0.6 + 0.4 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: penalize if post residual cannot fit the next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving space exactly usable by next item
            let u = 1.0 - ((pr - nxt) / cap);
            score -= 5.0 * u * u;
        }
    }

    // Mild pressure toward consolidating into fewer bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Nudge relative to mean residual: prefer bins below mean residual (tighter)
    score += 0.08 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately unattractive unless residual waste is huge
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into "usability tiers" (dead space vs. reusable space).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let tier: f64 = if post_residual == 0 {
        -30.0 // perfect fit, ideal
    } else if post_residual < eighth {
        25.0 // tiny sliver: nearly dead space, heavy penalty
    } else if post_residual < quarter {
        8.0 // small leftover: likely unusable for mid items
    } else if post_residual < bin_capacity / 2 {
        0.0 // medium leftover
    } else {
        -6.0 // large leftover: still very reusable
    };
    score += tier;

    // Modulo-arithmetic harmony: does post_residual share a residue class
    // with the lookahead item? If next item could nest into the remainder,
    // reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let harmony = (post_residual % next_item_size.max(1)) as f64;
        score -= 10.0 - harmony.min(10.0);
    } else if next_item_size > 0 {
        // next item cannot fit here anyway; leftover quality matters less
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fit_ratio > 0.55 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins are open (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let penalty = 15.0 + 25.0 * (1.0 - item_frac) + 10.0 * progress;
        let relief = if open_bins_count == 0 { 40.0 } else { 0.0 };
        score += penalty - relief;
    }

    // Mild preference for filling bins tighter than the current mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are "dead". Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size {
            score += 15.0; // gap too small for next item: mild penalty
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing ones.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if this bin's residual is far below average,
    // it's a "junk" bin; using it up is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.8;
    }

    // New-bin candidate: only attractive when nothing fits well. Make the
    // empty bin costly so it is chosen only when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 70.0;
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Late in the stream, avoid spreading out.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: if the next item can fit into post_residual,
    // reward this bin heavily (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 25.0 * next_tightness;
        } else {
            // Next item cannot follow here: penalize leaving medium dead space.
            score += 8.0;
        }
        // Exact chain match: post_residual == next_item_size is ideal.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Opening a new bin is attractive only if the next item could pair with the
        // remainder elsewhere; with lookahead, a fresh bin reserves full capacity.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
        // Early in the stream, be more willing to open bins (build a good portfolio).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins: mild pressure to consolidate (fill existing bins).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for fragmenting this bin.
            score += 4.0;
        }
    }

    // Prefer filling bins that already deviate below the mean residual (balance avoidance).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize using existing bins less when plenty of stream remains);
    // late in the stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress;

    // When many bins are open, favor using them rather than opening more.
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate adjustment: an empty bin is flexible; only choose it when
    // the item is large (would leave awkward gap elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * large_item + 5.0 * progress;
    }

    // Mild reward for placing large items into bins with large residual (big-in-big pairing).
    score -= 0.1 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * (1.0 - x) + 0.25 * x * x);

    // Penalize dead space more sharply as the stream progresses (polynomial in progress)
    score += 18.0 * progress * x * x * cap * 0.1;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= (1.0 - x).powi(3) * (1.0 + 0.5 * progress) * 6.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins deviating smoothly from the mean
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            let slack = (pr as f64 - nx) / cap;
            score -= 4.0 * (1.0 - slack).powi(2);
        } else {
            score += 3.0 * (nx - pr as f64) / cap;
        }
    }

    // Mild pressure against proliferating bins early
    score += 0.4 * open_bins_count as f64 * progress * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that form
    // "nice" fractions of capacity (usable future slots), penalize odd ones.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional harmonic bands: residual in [0,25) is near-dead space.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < bin_capacity / 4 {
        score += 25.0 * (1.0 - pr / (bin_capacity as f64 / 4.0)); // dead space penalty
    } else if post_residual <= bin_capacity / 2 {
        score -= 6.0; // half-capable slot
    } else {
        score -= 10.0; // roomy slot
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 pair well
    // with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - 0.1 * slack as f64; // chain fit reward
            if slack % 10 == 0 {
                score -= 4.0; // clean chain
            }
        } else {
            score += 6.0; // next item won't chain here
        }
    } else {
        // Last item: prefer zero post-residual strongly.
        score -= 20.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: when many bins are open, discourage fragmentation.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (pr / cap);
    }

    // Stream phase: early on, keep bins roomy for flexibility.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - phase) * 5.0 * (pr / cap);

    // New-bin candidate: only attractive when residual is full and current
    // fit is poor (large post-residual waste elsewhere).
    if bin_residual == bin_capacity {
        score = 45.0 + pr * 0.0 - 10.0 * (1.0 - phase);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 range => guard ~10) are pure waste.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small but usable post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize bins whose residual is far above what the item consumes
    // (creates large unusable gaps relative to mean residual).
    if (post_residual as f64) > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * bin_pressure * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet, but
    // opening it should be penalized unless the fit into open bins is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual.max(1.0)
            || fitting_bins_count == 0;
        if poor_fit {
            score -= 18.0; // prefer fresh bin over wrecking an open bin
        } else {
            score += 20.0 + 2.0 * bin_pressure; // discourage needless new bins
        }
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
        score += 4.0; // next item won't fit here -> slight penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        if diff == 0.0 {
            score -= 50.0;
        }
        // Penalize leaving dead space that next item cannot use.
        if next_item_size > post_residual && post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward tight fits overall.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize bins whose residual deviates badly from the mean (avoid fragmentation).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New empty bin: penalize opening unless current residual is very small.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (open_bins_count as f64);
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 35.0;
        }
    }

    // Late in stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Reward filling bins nearly completely.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it heavily
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        }
        // Perfect pairing: current + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
        // Penalize leaving a gap that no typical next item (>= next size) can use.
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let pressure = open_bins_count as f64 / (mean_residual.abs() + 10.0);
    score += pressure * 2.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 15.0 + 25.0 * progress;
        // But if no open bin fits at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Penalize creating dead space that is smaller than the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for bins below mean residual (balance the pool),
    // but only when consolidation is not urgent.
    if (bin_residual as f64) > mean_residual {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post residual), scaled non-linearly.
    let mut score = pr / cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tight fits matter even more (dead space is costly).
    let tightness = 1.0 - pr / cap;
    score -= 0.35 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize very small residuals that become dead space, more so mid/late stream.
    let dead = if pr < next_item_size as f64 { 1.0 } else { 0.0 };
    let smooth_dead = (1.0 - (pr / (next_item_size.max(1) as f64 + 1.0))).max(0.0);
    score += 0.25 * smooth_dead * (0.3 + 0.7 * progress) * (1.0 - 0.5 * dead);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 0.30 * (-diff / 20.0) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but allow it late or when the fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / cap);
        score += 0.8 * (1.0 - progress) - 0.4 * fit_quality * progress;
    }

    // Mild preference for bins with larger residual when many bins are open.
    score -= 0.05 * (bin_residual as f64 / cap) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Coupling with mean residual: avoid bins far below the mean residual late.
    score += 0.10 * ((mean_residual - bin_residual as f64) / cap).abs() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: post_residual in (0,10] is nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: classify by capacity fractions.
    // post_residual <= 25 (quarter) is low-value space; <= 50 half; > 50 rich.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 25.0;
    } else if post_residual <= half {
        score += 5.0;
    } else {
        score -= 15.0; // leaving >half: bin stays flexible, good
    }

    // Modular class on post_residual (mod 10): residuals that are multiples
    // of 10 are more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            } else {
                score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            let overshoot = next_item_size - post_residual;
            score += (overshoot % 20) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor residuals. Base new-bin score near mean residual.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin useful
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    } else {
        // Slight preference for fuller bins when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    }
    // Reward tight fits (wasting almost nothing).
    if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += next_item_size as f64 * 0.6;
        } else if post_residual >= next_item_size as u32 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Residual pressure: prefer bins with below-mean residual (consolidate space).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Open-bin pressure: mild incentive to use existing bins when many are open.
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.3;
    } else {
        // New-bin candidate: slight default penalty so it only wins on bad fits.
        score += 5.0 + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: minimize post residual quadratically.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 4.0);

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 30.0 - (gap as f64) * 0.5;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize proportionally to waste.
        let waste = next_item_size.min(post_residual) as f64;
        score += waste * 0.3;
    }

    // Compare residual against mean residual of open bins: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if next item is large and this item leaves a bad fit, opening new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 55.0;
        }
    }

    // Early in stream: slightly discourage proliferation of bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (below min item size 1..100 unknown,
    // use a soft threshold around 15% of capacity).
    let dead = if (post_residual as f64) < 0.15 * cap { (0.15 * cap - post_residual as f64) } else { 0.0 };
    score += 30.0 * dead / cap;

    // Lookahead: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 18.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // Next item won't fit here after placement; slight penalty unless it's a perfect fit now.
            score += 6.0 * nxt / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let time_factor = 1.0 + 0.5 * (step_index as f64 / (total_items as f64).max(1.0));
        // Base cost of a new bin, discounted by crowding pressure and stream progress.
        score += 40.0 - 25.0 * crowding * pressure.min(4.0) / time_factor;
        // If the item is large relative to capacity, new bin is safer.
        score -= 10.0 * (item_size as f64) / cap;
    }

    // Prefer filling bins that are already relatively full (low residual) beyond raw post_residual.
    score += 8.0 * (bin_residual as f64 / cap - post_residual as f64 / cap).abs();

    // Mild global balance: penalize bins far from mean residual to keep options diverse.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - post / cap; // 0 = perfect fit, 1 = empty-ish

    // Base: penalize leftover space, with non-linear (quadratic + cubic) coupling
    let mut score = post * (1.0 + 0.5 * tight * tight) + 40.0 * tight * tight * tight;

    // Reward tight fits more strongly as the stream progresses
    score -= 60.0 * tight * tight * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - tight);
    }

    // Lookahead: if next item fits into the resulting post_residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = (post - nxt) / cap;
            score -= 30.0 * (1.0 - slack_after_next) * (1.0 - slack_after_next);
        } else {
            // Next item won't fit here; mildly penalize leaving a gap that wastes capacity
            score += 10.0 * (post / cap);
        }
    }

    // Encourage filling bins that deviate below the mean residual (consolidation)
    let dev = (mean_residual - post) / cap;
    score -= 15.0 * dev * dev.abs();

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * open_bins_count as f64 * (0.2 + 0.8 * progress);

    // New-bin candidate: make empty bins less attractive unless the fit is very poor elsewhere
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover is
    // Class bins by residue mod 10: leftovers that are multiples of 10 (common item sizes)
    // are more reusable, so reward them.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, ideal
    } else {
        let class = post % 10;
        // Reward leftovers that are exactly matchable by typical small items
        if class == 0 {
            score -= 25.0;
        } else if class <= 3 {
            score += 8.0; // awkward tiny dead space
        } else if class >= 8 {
            score += 5.0; // nearly aligned but wasteful
        }
    }

    // Integer-division thresholds: large post_residual is fine (flexible), tiny is bad
    if post > 0 && post < 10 {
        score += 30.0; // dead space: unusable for min item size
    }

    // Reward using a bin when it's the last fitting option (avoid new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins aren't opened casually
        score += 45.0;
        // But if the item would leave a large flexible residual anyway and stream is early,
        // opening fresh can be fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 {
            score -= 20.0; // big items pair well in fresh bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if progress < 0.2 {
            score -= 5.0;
        }
        // Lookahead: if next item is big, fresh bin keeps room
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Lookahead harmony: if next item fits exactly in post_residual, strong reward
        if next_item_size > 0 {
            if next_item_size == post {
                score -= 55.0;
            } else if next_item_size <= post {
                score -= 12.0;
                // harmonic bonus if next leaves aligned class too
                if post - next_item_size >= 0 && (post - next_item_size) % 10 == 0 {
                    score -= 10.0;
                }
            } else {
                score += 6.0; // next item won't fit here; leftover risk
            }
        }
    }

    // Prefer filling tighter (smaller-residual) bins when many bins open
    if open_bins_count > 3 {
        score -= 3.0;
    }
    // Mean residual coupling: penalize placing into bins far below mean residual
    // (keeps balance, avoids many half-empty bins)
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual + 20.0 {
        score += 10.0;
    } else if bin_res_f < mean_residual - 20.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    let dead = if next_item_size > 0 && post_residual < next_item_size {
        post_residual as f64
    } else {
        0.0
    };
    score += 2.5 * dead;

    // Perfect-fit bonus (very low post residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Reward using bins with larger residuals (keep tight bins free).
    score -= 0.15 * bin_residual as f64;

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it early or when this bin is the only option.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable if few open bins or no alternative fits.
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 15.0 + 6.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    } else if fitting_bins_count == 1 {
        // Last chance before opening a new bin: strongly favor using this bin.
        score -= 20.0;
    }

    // Slight preference to fill bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small dead space less if next item is large
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin unless existing fits would waste a lot.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost plus penalty that shrinks when item is large
        score = bin_capacity as f64 * 0.6
            + 0.4 * (bin_capacity - item_size) as f64
            - (if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 });
        if fitting_bins_count > 0 && post_residual >= 15 {
            score += 20.0; // discourage new bin when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space more aggressively than large dead space
    // (post_residual in (0..item_min) is truly dead; larger remnants stay usable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 20.0 * fill_ratio;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: dead-space risk
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: when few bins fit the item, discourage fragmenting others.
    if fitting_bins_count <= 2 {
        score += 4.0;
    }

    // Time horizon: early in the stream, be more exploratory (favor new bins
    // slightly to build diverse residual pool); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (use up the "worst" bins first),
    // keeping the pool of flexible bins alive.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.3 * residual_gap;

    // Mild penalty for opening a brand-new bin when many bins are already open
    // and the item is small (encourage filling existing bins).
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64 - 20.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;
    let nxs = next_item_size as f64;

    // base: prefer small post residual, with smooth polynomial sharpening
    let mut score = pr + 8.0 * pr * pr / cap;

    // dead-space penalty grows with stream progress (waste matters more later)
    score += 30.0 * progress * (pr / cap) * (1.0 - tightness);

    // lookahead coupling: reward residual that still fits next item
    if nxs > 0.0 {
        let fits_next = if pr >= nxs { 1.0 } else { 0.0 };
        let gap = ((pr - nxs) / cap).abs();
        score -= 12.0 * fits_next * (1.0 - gap) * (1.0 - progress);
        score += 10.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // last-chance bonus: avoid opening new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // crowdedness: many open bins -> favor filling existing ones
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // align with mean residual: penalize outliers creating unusable gaps
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 act as "waste classes".
    let residue = post_residual % 10;
    score += residue as f64 * 1.5;

    // Small post-residual windows are near-perfect fits: strong reward.
    if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 18.0;
    }

    // Capacity fraction thresholds on post_residual.
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        // Leaving more than half a bin empty is poor packing; penalize quadratically.
        score += (frac - 0.5) * 120.0;
    }

    // Harmonic pairing: if the lookahead item fits exactly in post_residual, huge reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead fit: reward proportional to how well it nests.
        let nest = next_item_size as f64 / post_residual as f64;
        if nest > 0.7 {
            score -= 20.0 * nest;
        } else {
            score -= 6.0 * nest;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Lookahead cannot use the leftover: penalize dead space that blocks the next item.
        score += 10.0 + (post_residual as f64) * 0.2;
    }

    // Integer-division thresholds: post_residual in (0,20] is a "dead zone" unless near zero.
    if post_residual > 0 && post_residual <= 20 {
        score -= 12.0; // tight leftover is usually fine
    } else if post_residual > 20 && post_residual <= 40 {
        score += 8.0; // awkward middle band
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size >= (bin_capacity * 2 / 3);
        if big_item || open_bins_count == 0 || (next_item_size > 0 && next_item_size as f64 > mean_residual * 0.9) {
            score -= 15.0;
        } else {
            score += 45.0 + 30.0 * (1.0 - progress);
        }
    }

    // Prefer bins below mean residual (tighter bins get filled first).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    // Mild pressure to reduce open bin count over time.
    score += open_bins_count as f64 * 0.05;

    // Harmonic class of item size: large items (>= 51) prefer the tightest bin.
    if item_size / 10 >= 5 {
        score += (post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are likely unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidating into
    // existing bins rather than spreading out.
    score -= (open_bins_count as f64).sqrt() * 4.0;

    // New-bin candidate: penalize opening a new bin, escalating with open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if no existing bin can hold the item (only candidate), accept it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild coupling to mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 1.5;
        } else {
            // Reward leaving room for the next item, scaled by how snug the fit is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + slack);
        }
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    let res_f = post_residual as f64;
    score -= (mean_residual - res_f) * 0.8;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably well.
    if bin_residual == bin_capacity {
        score += 150.0 * (open_bins_count.max(1) as f64).ln();
        // But favor a fresh bin if the current fit would strand a lot of space.
        if next_item_size > 0 && post_residual < next_item_size / 2 {
            score -= 120.0;
        }
    }

    // Late in the stream, tighten packing (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += res_f * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin now but not after placing current item: mild penalty
        score += 6.0;
    }

    // Last-chance bonus: only one bin fits the item — use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: penalize opening a new bin when decent alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin only when current bins are crowded (low mean residual)
        // or the item is huge relative to capacity.
        let crowded = (mean_residual / cap) < 0.25;
        let huge = item_size as f64 > 0.8 * cap;
        if crowded || huge {
            score -= 15.0 * progress;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
        // Extra penalty if many bins already fit the item.
        score += 4.0 * fitting_bins_count as f64;
    }

    // Mild preference for bins below mean residual (balance the pool).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight openness penalty: discourage proliferation of open bins.
    if !is_new_bin {
        score -= 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: tight fits rewarded superlinearly, more so later in stream
    let tight = (1.0 - pr / cap).powi(2);
    score -= 24.0 * tight * (0.5 + progress);

    // Penalize dead space that can't plausibly be filled (smooth threshold around typical sizes)
    let dead = ((pr - 20.0).max(0.0) / cap).powi(3);
    score += 40.0 * dead;

    // Lookahead coupling: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let snug = 1.0 - (pr - nx) / cap;
            score -= 18.0 * snug * snug;
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - fill);

    // Mean-residual alignment: prefer bins near the mean residual (balanced closing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: mildly penalize so it only wins when fits are truly bad
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize post_residuals that are "almost but not quite" reusable classes
    // Class boundaries at multiples of 10 (harmonic divisors of 100)
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // integer division threshold
        let within = (pr % 10) as f64;
        // dead-space penalty grows when pr is just below a reusable class
        score += (10.0 - within) * 0.35;
        // reward landing exactly on harmonic classes (multiples of 10/20/25)
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 2.0; }
        // very small unusable residue is dead space
        if pr < 10 { score += 8.0; }
        if class == 0 { score += 2.0; }
    }

    // Perfect fit reward
    if post_residual == 0 { score -= 15.0; }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // extra reward if next item lands on harmonic class too
            if post_residual % 10 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here: penalize tight fits that block lookahead
            score += 1.5;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin, modulated by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 4.0 * progress;
        // if many bins can fit the item, discourage new bin
        if fitting_bins_count > 2 { score += 10.0; }
        // if mean residual is large, open bins are wasteful; new bin ok-ish
        score -= (mean_residual / cap).min(1.0) * 3.0;
        // big items prefer fresh bins
        if item_size >= 3 * quarter / 2 { score -= 4.0; }
        if item_size > bin_residual - eighth && !is_new_bin { score += 3.0; }
    }

    // Mild preference for tighter existing bins (small residual before placement)
    score += (bin_residual as f64) * 0.02;

    // Spread-awareness: many open bins -> prefer consolidating into fullest bins
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap is "dead" if it cannot fit even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // General dead-space pressure: gaps below ~25% of capacity are risky.
    let dead_threshold = bin_capacity as f64 * 0.25;
    if (post_residual as f64) < dead_threshold {
        let severity = (dead_threshold - post_residual as f64) / dead_threshold;
        score += 40.0 * severity * severity;
    }

    // Perfect fit bonus: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == item_size {
        // Leaves a gap exactly the size of the current item — likely reusable.
        score -= 15.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (post_residual as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Post gap too small for next item: penalize proportionally.
            score += 20.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Open-bin pressure: discourage spreading across too many bins unless fit is good.
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += 30.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the stream is early and few bins are open, allow new bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 35.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly (small residuals are hard to reuse).
        let dead = post_residual as f64;
        score += (dead / 10.0).powi(2) * 0.5;

        // 2-step lookahead: reward bins whose post_residual matches the next item.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score -= 40.0 / (1.0 + gap);
            if post_residual == next_item_size {
                score -= 120.0;
            }
        }
    }

    // Prefer tighter bins relative to mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Late in stream, be more conservative (favor filling open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already in base).
    // Penalize large unusable dead space nonlinearly.
    let dead = post_residual as f64;
    score += 0.35 * (dead / 100.0) * (dead / 100.0) * 100.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - slack / 100.0);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty if post_residual becomes tiny dead space
        if post_residual < 10 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item is large
    // and current bins have poor fit quality.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / 100.0;
        let mean_quality = mean_residual / bin_capacity as f64;
        // Penalize new bin; discount penalty when item is big and mean residual is fragmented.
        let mut new_bin_penalty = 25.0 - 20.0 * fit_quality;
        new_bin_penalty += 10.0 * mean_quality;
        // Early in stream, opening bins is cheaper (more items to fill them later).
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty -= 8.0 * (1.0 - t);
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for fuller bins relative to the fleet mean residual.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Prefer bins that leave residuals that are multiples of common small sizes
    // (heuristic "friendly" gaps): 10,20,25,50.
    let pr = post_residual;
    if pr == 0 { score -= 15.0; }
    else if pr == 10 || pr == 20 || pr == 25 || pr == 50 { score -= 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 8.0 * (pr_norm * pr_norm) * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-like term)
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize post-residual that is small but nonzero (dead space) via smooth bump
    score += 6.0 * (1.0 - pr_norm) * pr_norm * (1.0 + progress);

    // Lookahead coupling: smooth quadratic interaction between post_residual and next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let match_term = 1.0 / (1.0 + (gap / cap).abs() * (gap / cap).abs() * 8.0);
        score -= 12.0 * match_term * (1.0 - pr_norm) * (1.0 + progress);
    }

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Mild pressure to consolidate into fewer bins
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual penalized smoothly
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "usable slots"
    // (multiples of common size classes) and penalize awkward leftovers.
    let pr = post_residual;
    if pr == 0 {
        score -= 45.0; // perfect closure is ideal
    } else {
        let class = pr % 10;
        // dead-space penalty grows when residual is not a friendly class
        let friendly = match class { 0 => 1.0, 5 => 0.5, _ => 0.0 };
        score += (1.0 - friendly) * 12.0;
        // small residuals (<10) are nearly dead space
        if pr < 10 { score += 15.0; }
        // large residuals are valuable too; middle residuals are worst
        if pr > 50 { score -= 6.0; }
    }

    // Exact integer-division harmonic: residual that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // sets up perfect follow-up
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
            if slack < 10.0 { score += 8.0; } // leaves tiny unusable sliver
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) * 10.0;
        score += 25.0 - pressure;
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0; // big pair incoming: fresh bin useful
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (fitting_bins_count as f64).min(3.0);

    // Mild preference toward bins below mean residual (balance avoidance of many half-full bins)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 range).
    // Gaps below ~10 are almost certainly dead space; gaps 10..=25 are risky.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Pure dead space: heavy penalty.
        score += 45.0;
    } else if post_residual < 25 {
        // Risky gap: moderate penalty scaling with how close to dead space.
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits proportionally: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer closing bins out (low post_residual);
    // with few open bins, opening a new one is cheaper, so penalize less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit, mildly penalize leaving this gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins close out faster).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: empty bin has residual == capacity. Only attractive
    // if the item is large and current residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 55.0;
        // Cheaper to open when many bins are open (spreading load) and item is huge.
        new_bin_cost -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        if item_size >= 70 {
            new_bin_cost -= 15.0;
        }
        // If current bin would leave a risky gap, opening new is more attractive.
        if bin_residual - item_size < 25 && bin_residual >= item_size {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit is better, but with diminishing returns
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how snugly the next item fits into the leftover space
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 + 30.0 * snug;
    } else if next_item_size > 0 {
        // Penalize leaving a dead gap that the next item cannot use
        let dead = (post_residual - (post_residual.min(next_item_size.saturating_sub(1)))) as f64;
        score += 5.0 + 10.0 * (dead / bin_capacity as f64);
    }

    // Penalize creating residual far below the mean residual (fragmenting a bin)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.1 * dev; // slight reward for staying above mean
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless the fit is perfect
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 25.0; // perfect fill of a fresh bin
        } else {
            score += 10.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Late in the stream, prefer closing bins tightly (avoid stranding tiny residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is almost always best
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 20.0; // quadratic penalty for wasted space
    }

    // Dead-space avoidance: penalize residuals that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty if we leave a large gap anyway
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // base new-bin score: slightly worse than a good existing fit
        score = (bin_capacity - item_size) as f64;
        // early in the stream, or when mean residual of open bins is small,
        // opening a new bin is attractive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        score -= mean_residual * 0.15;
        score += open_bins_count as f64 * 0.5;
        // if the next item is large, avoid fragmenting current bins
        if next_item_size > item_size {
            score -= 6.0;
        }
    }

    // Mild preference for fuller bins relative to global state.
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let sz = item_size as f64 / cap;

    // Base: post residual, non-linearly coupled with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Polynomial coupling: penalize small post residuals more late in stream
    score += 0.6 * pr * (1.0 - pr) * (0.5 + progress);

    // Reward tight fits (small post_residual) especially when item is large
    score -= 0.5 * sz * (1.0 - pr) * (1.0 - pr);

    // Dead-space penalty: post residual too small to be useful
    let dead = if post_residual < item_size { 1.0 } else { 0.0 };
    score += dead * (0.3 + 0.5 * progress) * pr;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.4 + 0.3 * progress;
    }

    // Lookahead: favor bins whose post residual can hold next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 0.25 * (next_item_size as f64 / cap);
    }

    // New-bin candidate: neutral baseline, slightly worse early, better late
    if bin_residual == bin_capacity {
        score = 0.45 + 0.35 * progress + 0.1 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mean residual coupling
    score += 0.1 * (mean_residual / cap - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste <= 10).
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Harmonic class: quantize post_residual into deciles; dead space in
    // awkward classes (leaving 41..60, too big for small items, too small
    // for large ones) gets penalized.
    let decile = post_residual / 10;
    match decile {
        0 => score -= 20.0,
        1 => score -= 8.0,
        2 | 3 => score += 10.0, // awkward dead zone 20..39
        4 | 5 => score += 18.0, // worst dead zone 40..59
        6 | 7 => score += 5.0,
        _ => {}
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize if post_residual is a "just misses" gap.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer the fullest (smallest residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // residual or open bins are all poorly fitting.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let avg_fit = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing residuals are large (fragmented) and
        // item is big.
        score = 100.0 - tightness * 55.0 + avg_fit * 45.0;
        if fitting_bins_count == 0 {
            score = -100.0; // forced: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items together in fresh bin
        }
    }

    // Mild late-stream consolidation: as stream progresses, favor filling
    // existing bins to reduce open-bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps (10..=20) are semi-dead: moderate penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Next item cannot use this bin's leftover: leftover likely dead space.
            score += (post_residual as f64) * 0.5;
        } else {
            // Next item fits; residual left after it determines dead-space risk.
            let r2 = post_residual - next_item_size;
            if r2 < 10 && r2 > 0 {
                score += 8.0;
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight; prefer finishing tight bins.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.3;

    // Progress: later in the stream, waste matters more; tighten tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    // New-bin candidate: only attractive when all fits are bad (large dead space elsewhere).
    if bin_residual == bin_capacity {
        // Neutral baseline; slightly penalized so tight fits win.
        score = 55.0 + (open_bins_count as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward perfect chain fit (next item exactly fills post_residual).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (50.0 / (1.0 + chain_waste)).min(45.0);
        } else {
            // next item cannot fit in this bin's leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    } else {
        // Last item: tight fit is ideal
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Penalize very small unusable leftovers (dead space)
    if post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Slight preference for reusing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize mildly unless stream near end
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * chain_fit;
    } else if next_item_size > post_residual {
        // Next item won't chain here; slight penalty for consuming residual.
        score += 5.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad dead space
    // or open bins are crowded (many bins, high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / 20.0;
        let bad_fit_penalty = if post_residual < 20 { 30.0 } else { 0.0 };
        score += 12.0 + crowding * 2.0 + bad_fit_penalty - 10.0 * progress;
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from mean in a useful direction.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // Mild penalty on bin count growth pressure.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual with a non-linear (quadratic) pull
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, tighten packing more aggressively
    score -= 30.0 * (1.0 - progress) * (pr / cap) * (1.0 - pr / cap);

    // Dead-space penalty: residual too small for likely future items (smooth ramp)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = ((next - pr) / cap).max(0.0);
        score += 25.0 * gap / (1.0 + gap);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_norm = (fitting_bins_count.max(1) as f64).ln();
    score -= 15.0 / fit_norm;

    // Mild penalty when bin is far above mean residual (imbalance), smooth in progress
    score += 8.0 * ((bin_residual as f64 - mean_residual) / cap) * progress;

    // New-bin candidate: make it slightly less attractive than a decent fit
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space classes in [0, capacity)
    let class = post_residual % 10;
    // Harmonic penalty: small residuals (unusable slivers) are heavily penalized
    if post_residual > 0 {
        let sliver = (10 - class) as f64;
        score += sliver * sliver * 0.15;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Integer division thresholds: residual bands
    let band = post_residual / 10;
    score -= band as f64 * 1.5;

    // Reward tight fits (small post residual)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_post = post_residual - next_item_size;
            if nxt_post == 0 {
                score -= 40.0;
            } else if nxt_post <= 10 {
                score -= 15.0;
            } else {
                score -= (nxt_post as f64) * 0.3;
            }
            // harmonic class of the two-step remainder
            let c2 = nxt_post % 10;
            if c2 >= 1 && c2 <= 3 {
                score -= 6.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally
            score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline offset so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If many open bins fit, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Early in stream, mildly discourage hoarding bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already well used (low residual relative to mean)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Encourage consolidation when many bins are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit reward
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fill_ratio < 0.5 {
            score += 10.0;
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize when next item cannot fit in this bin's post-residual (dead-ish space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * gap;
        }
        // Coupling with mean residual: bins far below mean residual are tighter, prefer them
        score += 0.2 * (mean_residual - post_residual as f64).abs().signum()
            * (mean_residual - post_residual as f64);
    }

    // Last chance: strongly prefer using the only bin that fits (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (bin_capacity - item_size) as f64;
    }

    // Tight fit reward
    if post_residual <= 10 {
        score -= 12.0;
    }

    // Stream progression: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead space penalty: leftover too small for typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 18.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over time slightly.
        score = 55.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 8.0; // fresh bin can absorb the lookahead item too
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.25 * mean_residual;
        // If this bin is the only fitting option, new bin must be very unattractive.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for fuller bins (small residual before placement).
    score += 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction with stream progress: tighter packing later
    score *= 1.0 + 0.3 * progress * (1.0 - norm_pr);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let wasted = (nxt - pr).max(0.0) / cap;
        score += 40.0 * wasted * wasted;
        // Reward leaving exactly the lookahead size
        let gap = (pr - nxt).abs() / cap;
        score -= 10.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bonus: smooth in fitting count
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.05 * (open_bins_count as f64).ln_1p() * (pr - mean_residual).abs();

    // New-bin candidate handling: only open when current bins are poor fits
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        score = cap * (1.2 - 0.4 * tightness * tightness) - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction does it land in?
    // Residuals in [0,10) are "dead space" (nothing else fits if items >= 10... but sizes 1..100, so calibrate).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional class of post_residual relative to capacity
    let frac = post / cap; // in [0,1]

    // Dead-space penalty: tiny post_residual is fine (tight fit), mid residuals are wasteful.
    // Penalize residuals in awkward middle zones using integer division thresholds.
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 15.0;
    } else {
        // Harmonic zone classes via integer division on post_residual
        let zone = post_residual / 10; // 0..10 zones
        let zone_penalty = match zone {
            0 => 0.0,        // 4..9 residual: small but may fit tiny items
            1 => 6.0,        // 10..19
            2 => 10.0,       // 20..29
            3 => 12.0,       // 30..39
            4 => 13.0,       // 40..49
            5 => 12.0,       // 50..59
            6 => 9.0,        // 60..69
            7 => 6.0,        // 70..79
            _ => 3.0,        // 80+: nearly empty bin, fine
        };
        score += zone_penalty;

        // Modulo coupling: residuals that are multiples of 10 pair well with common item sizes
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        if post_residual % 5 == 0 {
            score -= 1.5;
        }
    }

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chained fit
        } else if next_item_size < post_residual {
            // next item fits, reward proportionally to how well it uses the leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 8.0 * fill;
        } else {
            // next item will NOT fit here: leftover becomes dead unless other bins absorb it
            score += 5.0;
        }
    }

    // Last-chance bin: if only this bin fits the item, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin offers a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; escalate with number of open bins already available
        score += 18.0 + 2.5 * open_bins_count as f64;
        // But if current item is large and would nearly fill a fresh bin, opening is attractive
        let fill_ratio = item_size as f64 / cap;
        if fill_ratio > 0.75 {
            score -= 14.0 * (fill_ratio - 0.75) / 0.25;
        }
    }

    // Prefer tighter existing bins: compare residual to mean residual across open bins
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild stream-phase modulation: early on, be slightly greedy toward tight fits;
    // later, be more conservative about leaving mid-range residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 30 && post_residual < 70 {
        score += 6.0 * progress; // mid-range dead space penalized more later in stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    score -= 25.0 * (-post_residual as f64 / 30.0).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize unless current bin would leave a large useful residual
    // or this bin is a poor fit.
    if bin_residual == bin_capacity {
        let tight = (bin_residual - item_size) as f64;
        if tight < dead_threshold {
            score += 200.0; // opening a bin that immediately becomes dead space is bad
        }
        // If an open bin fits reasonably, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // Lookahead: if next item fits into the fresh residual, opening is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Lookahead: avoid leaving a residual that exactly blocks the next item while
    // another gap could have hosted the current item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mild stream-progression damping: early on, be more open to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual small).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: if the next item fits into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: penalize dead space relative to next item.
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.35 * gap;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving post_residual close to mean keeps flexibility; extreme small residuals are dead space.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dev = (pr - mean_residual).abs();
        if pr < mean_residual {
            score += 0.3 * dev; // below mean: creating unusably small residual
        } else {
            score -= 0.1 * dev; // above mean: keeps bins balanced/flexible
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: prefer tighter fits among them (post_residual already does this).
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If lookahead item is large and no tight fit exists, opening a new bin is less bad.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for leaving residuals too small to ever be useful (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let mut score = pr;

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nis = next_item_size as f64;
        if nis <= pr {
            // next item fits exactly here -> strong reward, scaled by fit tightness
            score -= 6.0 + 4.0 * (nis / cap);
        } else {
            // next item won't fit: mild penalty proportional to wasted lookahead potential
            score += 1.5 * (1.0 - (pr / cap));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 9.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: slight penalty to encourage spreading consideration
        score += 0.4 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin is penalized, but less so when existing bins are fragmented
        // (mean residual low) or when few bins fit the item
        let mut new_bin_penalty = 14.0;
        if mean_residual < isz {
            new_bin_penalty -= 6.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 20.0; // forced opening
        }
        new_bin_penalty -= 0.15 * open_bins_count as f64;
        score += new_bin_penalty.max(-30.0);
    }

    // Dead-space penalty: tiny unusable residuals are wasteful
    if pr > 0.0 && pr < 10.0 {
        score += 5.0;
    }
    // Perfect fit reward
    if pr == 0.0 {
        score -= 10.0;
    }

    // Late in the stream, residual waste matters more (fewer future chances to reuse space)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.03 * pr;

    // Global fragmentation coupling: if mean residual is high, prefer tightening the fullest-feeling bins
    score -= 0.02 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let last_chance = if fitting_bins_count == 1 && is_new_bin < 0.5 { 1.0 } else { 0.0 };

    // Core: reward small post-residual with non-linear (quadratic) coupling
    let mut score = fit_norm * (1.0 + 1.5 * fit_norm * (1.0 - progress));

    // Penalize dead space that can't fit typical items (below 10)
    score += 0.8 * fit_norm * fit_norm * (1.0 - is_new_bin);

    // New-bin penalty scaled by how many bins already fit the item
    score += is_new_bin * (2.0 + 0.15 * fitting_bins_count as f64) * (1.0 + progress);

    // Reward last-chance bins strongly
    score -= last_chance * 1.5 * (1.0 - fit_norm);

    // Mean-residual coupling: prefer bins whose residual is close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev * (1.0 - is_new_bin);

    // Lookahead: if next item fits post-residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * (next_item_size as f64 / cap) * (1.0 - is_new_bin);
    }

    // Late-stream: tighten packing (prefer tightest fits more)
    score -= progress * (1.0 - fit_norm) * (1.0 - is_new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual relative to capacity: prefer residuals
    // in "good" classes (small or perfectly reusable), penalize middle dead zones.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fill -> strong reward
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo-arithmetic coupling: residual divisible by item_size or common
    // small sizes is likely reusable by future harmonic siblings.
    if item_size > 0 && post_residual % item_size == 0 && post_residual > 0 {
        score -= 12.0;
    }
    for h in [10u32, 20, 25, 50] {
        if post_residual >= h && post_residual % h == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly or well into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 - slack as f64 * 0.4;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (post_residual as f64 - (bin_capacity - next_item_size) as f64).max(0.0) * 0.3;
        }
    }

    // Integer-division threshold on residual fraction: dead-zone classes.
    let frac = pr / cap;
    if frac > 0.05 && frac < 0.25 {
        score += 20.0; // awkward sliver
    } else if frac >= 0.25 && frac < 0.5 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it mildly unattractive unless current residuals are tight.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * mean_residual.min(60.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Stream progression: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    // Coupling with mean residual: if this bin is far below mean, it's a good "closer".
    score -= 0.2 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (strict dead-space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this bin
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item can't use this gap -> dead space likely
            score += 5.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += 0.5 * open_bins_count as f64;

    // Slight bias relative to mean residual: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: default moderately high; only attractive when all fits are bad
    if bin_residual == bin_capacity {
        // base cost of a new bin, reduced late in the stream
        score = 45.0 + 0.3 * open_bins_count as f64
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // if the next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // 2-step lookahead: strongly reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits perfectly -> big reward proportional to match
            score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // next item would not fit: penalize small dead space
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    } else {
        // last item: just prefer tightest fit
        score -= 8.0 * fit_ratio;
    }

    // Penalize creating dead space far below mean residual (unusable gaps).
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 * (1.0 - pressure);
    }

    // Mild late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space: post_residual too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * chain;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize blocking with large leftover gaps
        score += 8.0;
    }

    // Penalize bins whose residual is far below the mean residual (already fragmented)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Prefer filling bins with small residuals as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64 / bin_capacity as f64) * 15.0;

    // With many open bins, discourage opening new ones; new-bin candidate gets penalty
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins with residual close to item_size (minimal waste ratio)
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 12.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Base: prefer small post_residual, with weight that grows over the stream.
    let mut score = post * (1.0 + 1.5 * progress);

    // Smooth penalty for "awkward" residuals: post_residual near (but not at)
    // small values creates dead space. Use a smooth bump around post = cap/4.
    let awkward = (post - 0.25 * cap) / cap;
    score += 12.0 * awkward * awkward * (1.0 - progress);

    // Reward tight fits: normalized fill ratio, quadratic reward.
    let fill = item / cap;
    score -= 10.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to encourage consolidation elsewhere.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - (post - next_item_size as f64) / cap;
        score -= 8.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how close it was.
        let miss = ((next_item_size as f64 - post) / cap).min(1.0);
        score += 6.0 * miss * miss;
    }

    // Relative residual coupling: penalize bins whose residual deviates
    // upward from the mean (fragmentation), smoothed by stream progress.
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: neutralize its low post_residual advantage so it is
    // chosen only when open bins fit poorly. Scale with number of open bins.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.8 * open_bins_count as f64 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod small moduli.
    // Residuals that are multiples of 10 (or 25/50) are "harmonic" dead space
    // that typical item sizes can still fill; penalize non-harmonic waste.
    let pr = post_residual as i64;
    let harmonic10 = (pr % 10) == 0;
    let harmonic25 = (pr % 25) == 0;
    if harmonic10 { score -= 6.0; }
    if harmonic25 { score -= 4.0; }
    if pr > 0 && !harmonic10 { score += (10 - (pr % 10)) as f64 * 0.8; }

    // Integer-division threshold classes on post_residual.
    let class = pr / 10; // 0..10 coarse class
    match class {
        0 => score -= 8.0,          // nearly perfect fit
        1 => score -= 4.0,
        2 => score -= 1.0,
        3 | 4 => score += 1.5,
        5 | 6 => score += 3.0,
        _ => score += 5.0,
    }

    // Lookahead: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0; // chain of perfect fits
        } else if gap % 10 == 0 || gap % 25 == 0 {
            score -= 7.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: dead-end risk
        score += 6.0 + (next_item_size.min(post_residual.max(1)) as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer tight bins relative to the fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Mild preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current residuals are all poor fits.
        score += 18.0 - 10.0 * progress;
        if fitting_bins_count == 0 { score -= 25.0; }
        if post_residual >= 50 { score += 2.0; }
    }

    // Small tie-breaker on exact-fill potential with common sizes.
    if pr == 0 { score -= 10.0; }
    if pr == 20 || pr == 30 || pr == 40 || pr == 50 { score -= 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, the minimum item size
    // under classic assumptions, but sizes can be as small as 1) are worthless.
    // Penalize gaps that are too small to be useful relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: gap unusable by any item
    } else if post_residual < 25 {
        // small gaps usable only by tiny items: strong penalty
        score += 25.0;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Coupling with mean residual: prefer bins whose residual is already tight
    // (below average) so we consolidate space rather than spreading it.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Open bins pressure: with many open bins, discourage spreading into
    // fresh/loose bins; with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has full residual. It should win
    // only when no open bin offers a decent fit. Make the empty bin moderately
    // attractive so it beats terrible fits, but not so attractive it beats
    // reasonable placements.
    if bin_residual == bin_capacity {
        // baseline attractiveness for a fresh bin
        score -= 30.0;
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.2;
        }
        // early in the stream, opening bins is cheap
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead synergy: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover that fails to fit the known next item: mild penalty
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 - leftover.min(25.0);
    }
    // Next item does NOT fit here: penalize proportionally to wasted opportunity.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize tiny unusable dead space (below min item size 1..=10 range -> <10 is dead).
    if post_residual < 10 {
        score += 20.0 + (10 - post_residual) as f64;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (consolidate space).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: penalize mildly, but allow it when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual + 1.0);
        score += 35.0 - crowding.min(35.0);
    }

    // Late-stream bias: close out bins efficiently as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted space nonlinearly; tiny dead space is fine, large gaps are bad.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64 * 2.0);

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // If next item won't fit here anyway, prefer larger leftover space for it elsewhere.
            score += (next_item_size as f64 - pr).max(0.0) * 0.3;
        }
    }

    // Time horizon: early in stream, be conservative (favor opening bins less);
    // late in stream, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> favor consolidating
    // into existing bins rather than spreading out.
    if open_bins_count > 2 {
        score -= (mean_residual - pr).max(0.0) * 0.2;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the new bin would be well-utilized by item + lookahead.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            penalty -= 10.0;
        }
        if fit_ratio < 0.35 {
            penalty -= 20.0;
        }
        if fitting_bins_count > 3 {
            penalty += 10.0;
        }
        score += penalty;
    }

    // Slight preference for bins with residual close to item (best-fit bias).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear penalty on small-but-nonzero post residual (dead space)
    score += 40.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5) * (norm_pr - 0.5);

    // Smooth coupling with stream progress: prefer tight fits later in stream
    score -= (1.0 - norm_pr) * (0.5 + 1.5 * progress) * 20.0;

    // Penalize bins whose residual deviates from mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 15.0 * (1.0 - pr / cap) * (1.0 - nxt / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure against hoarding too many open bins early
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
