pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that no future item (size >= 10) can use.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.15;
    }

    // Lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack * 0.1);
        } else {
            // next item cannot fit here; penalize proportionally to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 20.0 * fill;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate logic: make empty bins attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Opening a new bin is penalized more when few bins are open early on,
        // but becomes more acceptable late when mean residual is low.
        let new_bin_penalty = 40.0 - 20.0 * progress - (bin_capacity as f64 - mean_residual) * 0.1;
        score += new_bin_penalty.max(2.0) + 0.05 * crowd;
    } else {
        // Slight preference for reusing bins that are already fairly full
        // (best-fit bias beyond raw post_residual).
        let residual_ratio = bin_residual as f64 / bin_capacity as f64;
        score += 8.0 * (1.0 - residual_ratio);
    }

    // Global pressure: when many bins are open with low mean residual,
    // discourage wasting space anywhere.
    if mean_residual < 20.0 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.5 * pr_n * pr_n);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fills matter more (dead space is costlier)
    let coupling = pr_n * (1.0 - pr_n) * (0.5 + progress);
    score -= 12.0 * coupling;

    // Penalize large residuals more as stream progresses (less time to reuse them)
    score += 20.0 * pr_n * pr_n * progress;

    // Reward near-perfect fits smoothly
    score -= 8.0 * (1.0 - pr_n) * (1.0 - pr_n) * (1.0 + 0.3 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * ((nx - pr) / cap);
        }
    }

    // Prefer filling bins in crowded states; new-bin candidate penalized mildly
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    } else {
        score -= 2.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));
    }

    // Mild pull toward mean residual to keep bin states balanced
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space is worse when it falls
    // into "useless" residue classes (small leftovers nothing can fill).
    let post = post_residual;
    let class = if post == 0 { 0 } else if post <= 10 { 1 } else if post <= 20 { 2 } else if post <= 35 { 3 } else { 4 };
    score += match class {
        0 => -30.0,                      // perfect fill
        1 => 15.0,                       // tiny unusable sliver
        2 => 5.0,                        // moderate
        3 => -3.0,                       // still fillable by mid items
        _ => 0.0,
    };

    // Fractional capacity coupling: reward bins whose fill ratio crosses
    // harmonic thresholds (1/2, 3/4 of capacity).
    let fill = (bin_capacity - post) as f64 / cap;
    if fill >= 0.75 { score -= 12.0; }
    else if fill >= 0.5 { score -= 6.0; }
    else if fill >= 0.25 { score -= 2.0; }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            let waste = (post - next_item_size) as f64;
            score -= 10.0 * (1.0 - waste / cap);
        } else {
            // next item cannot use this residual: penalize leftover proportionally
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins mildly, more when item is small
        score += 20.0 + 0.3 * (item_size as f64);
        // late in the stream, or when mean residual is large, discourage new bins more
        score += 10.0 * mean_residual / cap;
        score -= 5.0 * progress;
        // if item is huge, a fresh bin is actually attractive
        if item_size >= 70 { score -= 35.0; }
    }

    // Congestion: many open bins -> prefer tightening existing ones.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

