    // penalize outliers creating dead space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize tiny unusable residuals (dead space) unless it's a perfect match.
    if post_residual > 0 && post_residual < 10 {
