        score += 18.0 - 10.0 * progress;
        if item_size as f64 > mean_residual + 20.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild tie-break: prefer fuller bins (smaller residual before placement).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but dead space that is too small
    // to ever be reused is worse than moderately usable space.
    let r = post_residual as f64;
    if r > 0.0 {
        // Penalize "awkward" residual: too small for typical small items (1..=10)
        if r < 10.0 {
            score += 12.0 * (10.0 - r);
        }
        // Reward residual that exactly matches a plausible next-item niche
        if next_item_size > 0 && (next_item_size as f64) <= r {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        let diff = r - next_item_size as f64;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to how badly
            score += 0.05 * (-diff);
        }
    } else {
        // Last item in stream: just minimize post_residual tightly.
        score = r;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize new bins when any open bin fits well (post_residual small).
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // If mean residual across open bins is small (bins are full-ish), new bin is fine.
        score += 10.0 + 20.0 * (1.0 - pressure.clamp(0.0, 1.0));
        // Early in the stream, opening bins is cheap and useful for future flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> consolidate, prefer bins
    // below mean residual (drain the emptiest-ish bins) to enable closing bins.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.03 * dev;

    // Mild reward for filling bins more completely as stream progresses (endgame tightening).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (item_size as f64);

    // Tiny tie-break noise-free coupling on bin index proxy (open_bins_count) to
    // deterministically prefer older bins (lower count => opened earlier).
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap; // normalized post residual in [0,1)

    // Core: prefer small post residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * fit_norm * fit_norm);

    // Polynomial coupling of post residual with stream progress:
    // late in the stream, tight fits matter more (quadratic/cubic in progress).
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 18.0 * prog_term * fit_norm;

    // Penalize residual that cannot fit the lookahead item (smooth gate).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 12.0 * gap * gap * (1.0 - prog_term * 0.5);
        // Reward if the next item fits snugly after this placement.
        let snug = (pr - nx).max(0.0) / cap;
        score -= 6.0 * (1.0 - snug.min(1.0)) * (pr >= nx) as i32 as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * prog_term;
    } else if fitting_bins_count > 1 {
        // mild penalty spread when many options exist, encouraging consolidation
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // current item is large relative to capacity or residuals are scattered.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let scatter = (mean_residual - cap * 0.5).abs() / cap;
        let large_item = it / cap;
        let threshold = 0.35 + 0.3 * prog_term - 0.2 * scatter;
        // smooth logistic gate instead of hard piecewise
        let open_new = 1.0 / (1.0 + (-(large_item - threshold) * 20.0).exp());
        score = cap * (1.0 - open_new) + 2.0 * open_new;
    }

    // Mild preference for bins whose residual is near the mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).powi(2) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

