        } else if slack < 10 {
            score += 10.0; // would leave tiny dead space next step
        }
    } else if next_item_size > 0 {
        // next item won't fit here anyway: residual is pure dead space potential
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        // baseline penalty so we prefer reusing bins with decent fits
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in stream, opening new bins is cheaper than fragmenting
        if mean_residual < 25.0 { score -= 15.0; }
        if post_residual == 0 { score -= 0.0; }
        let _ = progress;
    }

    // mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // again are heavily penalized (dead zones below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger residuals are genuinely reusable: reward them.
        score -= (post_residual as f64) * 0.35;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead: if next item fits exactly in post_residual,
    // strongly reward; if it cannot fit, penalize the dead space more.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading out; new-bin candidate gets penalized.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual alignment: bins with residual below mean are already tight;
    // filling them further is good.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, penalize leftover after hypothetical second placement
            let second_left = post_residual - next_item_size;
            score -= 50.0 - second_left as f64 * 0.5;
        } else {
            // next item won't fit here; penalize large dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: strongly favor tight fit
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize leaving dead space below the minimum item size (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins with more residual than average
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.05;

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: residuals too small for the smallest items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete; prefer concentrating items.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers.
            score += 6.0;
        }
    }

    // Global residual pressure: many open bins with slack -> prefer filling them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual as f64 > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (30.0 + 40.0 * progress);

    // Early stream: slightly encourage opening bins to spread load.
    score -= new_bin * 20.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with less remaining slack relative to capacity.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = post + 12.0 * (post / capacity).powi(2) + 30.0 * (post / capacity).powi(3);

    // Smooth stream-progress coupling: dead space hurts more as stream advances
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits (small post residual relative to item) via smooth term
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_tightness * fit_tightness;

    // Lookahead: bonus if post_residual can host next item exactly-ish
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let gap = (post - nx) / capacity;
            score -= 10.0 * (1.0 - gap * gap); // smooth reward for chaining
        } else {
            score += 4.0 * ((nx - post) / capacity);
        }
    }

    // Last-chance bin: strong penalty to open a new bin when only this bin fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild dynamic penalty early, reward late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs() / capacity;
        score += 5.0 + 20.0 * progress - 8.0 * fragmentation;
    }

    // Mild diversity term: prefer bins whose residual differs from mean (balance residuals)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / capacity).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space quantized into deciles.
    let post_class = (post_residual / 10) as f64;
    score += post_class * post_class * 2.0;

    // Perfect fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward small but usable leftovers; penalize tiny dead slivers (<10).
        if post_residual < 10 {
            score += 25.0;
        } else {
            score -= 15.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic class match: residue and next item share a compatible class.
        let compat = (post_residual / 10) - (next_item_size / 10);
        score -= 20.0 + compat as f64 * 3.0;
    } else if next_item_size > 0 {
        // Next item won't fit: this bin's leftover likely becomes dead space.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity (harmonic class of item size).
    if bin_residual == bin_capacity {
        let item_class = (item_size / 10) as f64;
        // Large items (class >= 6) deserve a fresh bin; small ones should reuse.
        score += 55.0 - item_class * 8.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress-aware slack: early in the stream, be pickier about fit quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mean residual context: if open bins are generally loose, tighten selection.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Modulo-3 harmonic tiebreak on post_residual to break symmetry.
    score += match post_residual % 3 {
        0 => -2.0,
        1 => 1.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small post_residuals that likely cannot host future items.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.10);
        if (post_residual as f64) <= dead_threshold {
            score += 25.0 + 2.5 * (dead_threshold - post_residual as f64);
        }
    }

    // Reward tight fits (small waste) more aggressively than raw post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Reward using bins that would otherwise leave large residual (consolidation).
    score -= 0.15 * mean_residual;

    // Pressure: prefer filling existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot fit in post_residual and post_residual is small.
    if next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Prefer new bin only when residual is badly fragmented: make empty-bin candidate
    // (bin_residual == bin_capacity) mildly unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.3 * open_bins_count as f64;
    }

    // Slight stream-progression adaptation: later in stream, be more conservative
    // about dead space.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, penalize dead space nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward when the leftover space
    // exactly matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leftovers too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += 6.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (consolidate fullness), unless this is a last-chance fit.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * fit_ratio - 5.0 * progress;
        // Opening a new bin is attractive if the next item is huge and won't
        // fit leftovers of typical open bins.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Mild penalty for proliferation of open bins with large residuals.
    if open_bins_count > 3 && bin_residual as f64 > mean_residual + 20.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize more if it would have been close
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Mild penalty for opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let mean_tight = 1.0 - mean_residual / (bin_capacity as f64);
        // open new bin only if existing bins are quite full or fit is bad
        let new_bin_bonus = 15.0 * mean_tight + 10.0 * progress;
        score += 30.0 - new_bin_bonus;
        // penalize new bin more when post residual is large waste
        score += 0.2 * post_residual as f64;
    } else {
        // reward using bins tighter than average
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: later in stream, be more conservative (favor existing bins).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_r = r / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = r + 40.0 * norm_r * norm_r;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter fits matter more (dead space is costlier)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 60.0 * late * norm_r * (1.0 - norm_r) * 4.0 * norm_r;

    // Last-chance bin bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 50.0 * late;
    }

    // Lookahead: reward if next item fits the post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            let slack = (r - nx) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            // penalize residuals that can't host the next item, scaled by size gap
            let gap = (nx - r) / cap;
            score += 20.0 * gap * gap;
        }
    }

    // Prefer bins whose residual deviates below the mean (consolidating small leftovers)
    let dev = (r - mean_residual) / cap;
    score += 15.0 * dev * dev - 5.0 * dev;

    // Mild penalty for spreading across many bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_r;

    // New-bin candidate: baseline so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (capacity fractions) ---
    // Classify post_residual into "harmonic" residual classes: multiples of
    // 100/4 = 25 are ideal (combinable with common item sizes).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    let fits_next = next_item_size > 0 && post >= next_item_size;

    // Reward exact harmonic leftovers (25/50/75/100 classes)
    if post == 0 {
        score -= 40.0; // perfect fit
    } else if post % quarter == 0 {
        score -= 25.0;
    } else if post % (quarter / 2) == 0 {
        score -= 12.0;
    }

    // Integer-division dead-space thresholds: leftovers that nothing (>=10)
    // can use are dead space; penalize strongly.
    if post < 10 && post > 0 {
        score += 45.0;
    } else if post < 20 && post > 0 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit in the resulting residual?
    if next_item_size > 0 {
        if fits_next {
            // Bonus scaled by how tightly next item nests in the leftover
            let tightness = 1.0 - (post - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * tightness;
            // Harmonic pairing: next item completes a quarter/half class
            if (item_size + next_item_size) % half == 0 {
                score -= 18.0;
            } else if (item_size + next_item_size) % quarter == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // leftover unusable by lookahead
        }
    } else {
        // Last item: prefer filling bins as fully as possible
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized unless existing residuals are tight
        score += 55.0 - 60.0 * crowded - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild preference for tighter existing bins (small residual = tight fit)
    score += (bin_residual as f64) * 0.05;

    // Spread pressure: many open bins -> prefer consolidation
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 2.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: favor bins whose residual can still fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Slight preference for tighter bins (less residual before placement)
    score += (bin_residual as f64) * 0.1;

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect chain fit
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // two items exactly fill the bin
        } else if next_item_size <= post_residual {
            // next item fits: reward small leftover after the chain
            let chain_left = post_residual - next_item_size;
            score -= 25.0 - (chain_left as f64) * 0.35;
        } else {
            // next item won't fit here: penalize dead space created
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer leaving residuals that are small but usable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny dead space is nearly unusable
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: bins tighter than average are better targets
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score += 55.0 - fragmentation * 1.2 - progress * 10.0;
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative: allow opening a bin
        }
    }

    // Mild bonus for high fill ratio
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: normalized fill fraction of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize dead space that is too small to be useful for typical items.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 18.0 * (10.0 - dead) / 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin; if the next item would be blocked, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins with slack: discourage fragmenting further; prefer
    // consolidating into bins whose residual is near the mean.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        score += 0.5 * open_bins_count as f64 * (dead / bin_capacity as f64);
    }

    // Late in the stream, be more conservative: prefer filling existing bins
    // tightly rather than opening new ones.
    score *= 1.0 + 0.3 * progress;

    // Empty new-bin candidate: make it acceptable only when the item is large
    // and no open bin offers a good fit; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 8.0 + 0.05 * waste;
        if item_size > 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening
    let mut score = post + 40.0 * norm_post * norm_post;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (squared interaction)
    score += 60.0 * norm_post * norm_post * progress * progress;

    // Penalize bins whose residual is far above the mean (fragmented bins),
    // scaled smoothly by progress
    let spread = (post - mean_residual) / cap;
    score += 25.0 * spread * spread * (0.5 + progress);

    // Reward using a bin when it's the last fitting bin (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let tight = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 20.0 + 30.0 * tight * tight;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);

    // Prefer bins with smaller original residual (tighter existing bins)
    score += 10.0 * (bin_residual as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to bin capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac; // quadratic dead-space penalty

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Harmonic classes: penalize leaving residuals that no common item class can use.
    // Classes based on modulo of capacity fractions: residuals in {0..100}.
    let class = post_residual % 10;
    // Dead zones: residuals that are awkward (e.g. 1..9 too small for typical min items)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }
    // Reward residuals that are multiples of 10 (align with class boundaries)
    if class == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nf = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score += 10.0 * nf;
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it wins
    // only when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.1;
        // Late in stream, be more willing to open new bins to keep tight options.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 3.0;
        }
    }

    // Slight preference for bins with below-mean residual (concentrate packing).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.2 * dev;
    }

    // Mild pressure to reduce open bin count early.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
