pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but penalize tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space penalty
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills this bin afterwards
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits here too; reward proportionally to tightness of chain
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit; penalize leaving a large unmatchable remainder
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average when stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += rel * (10.0 + 20.0 * (1.0 - progress));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.25;
        if open_bins_count > 0 && (poor_fit || mean_residual < item_size as f64 * 0.5) {
            score -= 15.0;
        } else {
            score += 20.0; // discourage opening bins while good fits exist
        }
    }

    // Slight preference to fill fuller bins as stream progresses.
    score -= (1.0 - (bin_residual as f64 / bin_capacity as f64)) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: fraction of bin consumed by this placement
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness * tightness;

        // Dead-space penalty for small unusable leftovers
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr);
        } else if pr < 20.0 {
            score += 8.0 * (20.0 - pr) / 10.0;
        }
    }

    // Lookahead coupling: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 5.0 * (slack / cap);
    } else if next_item_size > 0 {
        // penalize leaving a gap that wastes the lookahead
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but attractive late in the stream or when mean residual is fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score += 20.0;
        score -= 25.0 * fragmentation;
        score += 10.0 * progress;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Prefer bins below mean residual (consolidate big gaps)
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(-40.0).min(40.0);

    // Slight preference for larger residuals late in stream (less fragmentation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    let mut score = pr / cap;

    // Non-linear coupling: quadratic penalty on wasted residual, amplified by stream progress.
    let prn = pr / cap;
    score += 1.8 * prn * prn * (0.5 + progress);

    // Reward good utilization (item fills most of the bin).
    let fill = it / cap;
    score -= 0.9 * fill * fill * (1.0 + progress);

    // Penalize very small residuals that are hard to reuse later (dead space).
    let dead = if pr > 0.0 { (1.0 - prn).ln().abs() } else { 0.0 };
    score += 0.15 * dead * prn;

    // Lookahead: reward leaving space that fits the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 0.6 * (1.0 - slack * slack);
        } else {
            let miss = (nx - pr) / cap;
            score += 0.8 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - progress);
        score -= 0.6;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer bins closer to the mean residual (balance).
        score += 0.1 * ((pr - mean_residual) / cap).abs();
    }

    // New-bin candidate: make it attractive only when open bins are poorly filled
    // or the fit is bad; otherwise mildly discourage proliferation.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        let new_bin_bonus = 0.9 * prn * (1.0 - avg_fill) * (1.0 - progress);
        score -= new_bin_bonus;
        score += 0.3 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let item_class = item_size / 10; // 0..=10 (item 1..100)
    let post_class = post_residual / 10;

    // Reward tight fits: small post_residual, especially in low classes
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0 + 10.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Penalize dead space: post_residual too small for the smallest future item (assume >=1, but
    // practically items rarely below 10) — dead zone (0, 10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Modulo coupling: bins whose residual is a multiple of a common divisor (e.g. 25 or 20)
    // pair well with typical item classes; reward residuals divisible by 25 or 20
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 25.0 - leftover as f64;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; slight penalty for wasting the slot
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad fit unless it's tight
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 25.0; // prefer opening a new bin over leaving tiny dead space
    }
    if fitting_bins_count == 1 && post_residual <= 5 {
        score -= 30.0; // but a near-perfect last-chance fit is great
    }

    // New-bin candidate: fresh empty bin should lose unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // open a new bin if all existing fits would leave ugly residues
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins with high mean residual -> prefer using them
        if mean_residual > cap * 0.5 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild preference for filling fuller bins (lower residual first) scaled by class difference
    score += (bin_residual as f64 - item_size as f64) * 0.05;
    score += (item_class as f64 - post_class as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (<= 10) are "dead". Penalize harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual >= 10 {
        // Small gap: only useful if next item fits it exactly-ish
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 15.0; // lookahead saves the gap
        } else {
            score += 25.0;
        }
    } else if post_residual == 0 {
        // Perfect fill: reward strongly
        score -= 80.0;
    }

    // Reward tight fits (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        // But if the current bin would leave a terrible dead space, allow new bin
        if post_residual > 0 && post_residual < 10 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing)
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Lookahead: bonus if next item exactly fits post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins where the item leaves almost no dead space.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0 - (post_residual as f64) * 20.0;
    }

    // Two-step lookahead: reward bins whose post_residual can exactly host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 400.0; // exact two-item chain: item + next fills bin perfectly
            } else {
                score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Post residual too small for next item: penalize dead space relative to next size.
            score += (nxt - pr).min(60.0) * 1.5;
        }
    }

    // Relative fill quality vs mean residual: prefer filling below-average-residual (well-used) bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large and
    // would leave a bad fit elsewhere; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if large_item && fitting_bins_count == 0 {
            score -= 80.0 + 60.0 * (1.0 - progress);
        } else {
            score += 150.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward zone (just above typical small items).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: penalize large post-residual nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 50.0;
        }
        // waste relative to smallest plausible item granularity
        score += 0.35 * (post_residual as f64).powf(1.35) / (bin_capacity as f64);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-slack / 20.0).exp();
        } else {
