            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default, scaled by how many bins could fit.
        score += 40.0 + 6.0 * fitting_bins_count as f64;
        // Late in the stream, opening fresh bins is more acceptable (avoids fragmentation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If mean residual across open bins is small (all bins nearly full), new bin is fine.
        score -= 0.25 * (100.0 - mean_residual.min(100.0));
    }

    // Prefer filling bins with larger residuals when many bins are open (bin count control).
    score += 0.08 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual to balance residuals upward.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear coupling: waste is punished more heavily as the stream progresses
    // (early on, dead space may still be exploitable; late it is pure loss).
    let progress_waste = pr_norm * pr_norm * (1.0 + 2.0 * progress);
    score += 8.0 * progress_waste;

    // Cubic term: strongly discourage very small unusable slivers, smoothly.
    score += 12.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Reward bins whose residual is well-matched to the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 6.0 * (-diff * diff * 20.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly scaled by how well the item fills it).
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 15.0 * (0.4 + 0.6 * fill.min(1.0));
    }

    // Interaction with mean residual: prefer bins below the mean residual
    // (denser bins) with a smooth quadratic preference.
    let rel = (pr as f64 - mean_residual) / cap;
    score += 5.0 * rel * rel;

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity (smooth in item_size), and more so early in the stream.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let penalty = 20.0 * (1.0 - size_frac) * (0.6 + 0.4 * (1.0 - progress));
        // But if no open bin fits well, allow the new bin: relax via fitting count.
        let relax = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        score += penalty - relax;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers that are "harmonically useful"
    // (large enough to host typical items) are rewarded.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class: f64 = if post_residual >= half {
        0.0
    } else if post_residual >= quarter {
        1.0
    } else if post_residual >= quarter / 2 {
        2.0
    } else {
        3.0
    };
    score += class * 12.0;

    // Penalize leftovers that no plausible item (>=1, typically >=10) can use,
    // scaled by how "dead" the space is.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item won't fit here; slightly penalize creating a bin that
            // strands the lookahead.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over
    // opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // moderately attractive only when open bins are crowded on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // If mean residual is small (bins nearly full), opening fresh is fine.
        score = 45.0 + 40.0 * crowding - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere; emulate by
        // keeping the empty-bin score positive relative to tight fits.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0;
        }
    } else {
        // Mild penalty for spreading across many bins when mean residual is high.
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // Modulo-based tie-breaking on post residual: prefer residuals that are
    // multiples of common item sizes (10s), which future items can fill cleanly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item can fill are heavily penalized.
    // Items are >= 1, but treat gaps below a "useful threshold" as dead space.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 4.0;

    // Exact-fit lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage opening new bins when many bins already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But if this is the only fitting bin, opening a new bin may be better than
        // fragmenting; soften the penalty.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer reusing bins more strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to avoid opening a new bin.
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals balanced, leaving uniform usable gaps).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills, but heavily penalize unusable dead space.
    // Dead space = residual that is too small to ever be useful.
    if post_residual > 0 {
        // small dead space (hard to reuse) is worse than moderate residual
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // perfect fill: big reward
        score -= 60.0;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly,
    // penalize when the next item cannot fit here (forcing a new bin later).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // exact 2-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to how much is wasted
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // prefer placing into them (relative fullness matching).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0);
        }
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no good fit exists; otherwise keep open bins busy.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = if open_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).recip()
        };
        // penalize opening new bins early in the stream; relax later
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 * (1.0 - frac) + 25.0 * pressure + 20.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 30.0; // other good fits exist, don't open a bin
        }
    }

    // Mild preference for larger items into emptier bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fill: strongly reward exact closure.
    if post_residual == 0 {
        score -= 15.0;
    }
    // Dead space: leftover too small to ever hold the smallest item (size 1..10 range guard).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins where the next item also fits into the leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 3.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover likely wasted for the known successor: mild penalty
        score += 1.5 * (1.0 - progress);
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is the only option.
            score -= 25.0;
        } else {
            // Prefer existing bins unless the fit there would be terrible.
            score += 12.0 + 0.3 * item_size as f64
                + 2.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Mild pressure toward bins below the mean residual (consolidate slack).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Base: prefer bins whose post-residual is small (tight packing),
    // non-linearly discounted as stream progresses (waste matters more later).
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Reward tight fits: fraction of bin consumed, smooth polynomial coupling.
    let fill_ratio = fit / cap;
    score -= 25.0 * fill_ratio * (1.0 + progress);

    // Penalize small dead space: residual that is hard to reuse (very small
    // relative to capacity) is quadratic waste, especially early on.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * (10.0 - post) } else { 0.0 };
    score += 0.6 * dead * (1.0 - 0.5 * progress);

    // Lookahead synergy: reward if next item fits into post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let synergy = 1.0 - (next_item_size as f64 / post);
        score -= 12.0 * synergy * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        // Slight penalty if leftover cannot host the lookahead item.
        score += 3.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - fill_ratio);
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate waste into few bins), smooth interaction with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress) - 4.0 * dev;

    // New-bin candidate handling: an empty bin is attractive only when the
    // stream is early or the item is large; penalize it mid/late stream so we
    // exhaust existing bins first.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).powf(1.5);
        score = 55.0 + 40.0 * fill_ratio - 35.0 * early;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small item sizes (harmonic slots) are valuable.
    let harmonic_slot: u32 = 10;
    let slot_count = post_residual / harmonic_slot;
    let slot_remainder = post_residual % harmonic_slot;

    // Reward residuals that divide evenly into slots (perfect harmonic fit).
    if slot_remainder == 0 {
        score -= 8.0 + (slot_count as f64) * 1.5;
    } else {
        // Penalize dead space that cannot host a 10..80 item.
        if post_residual < 10 {
            score += 25.0;
        } else {
            score += (slot_remainder as f64) * 0.6;
        }
    }

    // Integer-division threshold classes on post_residual.
    if post_residual >= 50 {
        score -= 6.0; // half-full bin still very reusable
    } else if post_residual >= 20 {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 10.0; // thin sliver: dead space risk
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: does post_residual contain next_item as slot multiple?
            let after_next = post_residual - next_item_size;
            if after_next % harmonic_slot == 0 {
                score -= 12.0;
            }
            score -= (after_next as f64) * 0.15;
        } else {
            // Next item won't fit here; penalize less if post_residual is still slot-aligned.
            if post_residual % harmonic_slot != 0 {
                score += 4.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // gives a tight fit (post_residual small) or the stream is early.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size && bin_residual == bin_capacity;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Cheaper to open when many items remain (amortization) and item is large.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
        score -= (item_size as f64) * 0.15;
        // If next item is small, a fresh bin may pair well with current item.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0;
        }
        let _ = is_new_bin;
    }

    // Mean-residual coupling: prefer bins far from the mean when mean is low,
    // prefer near-mean (balanced) bins when mean is high.
    let diff = (post_residual as f64) - mean_residual;
    if mean_residual < 40.0 {
        score -= diff * 0.3;
    } else {
        score += diff.abs() * 0.1;
    }

    // Modulo-3 harmonic class of item size vs post residual (coarse packing synergy).
    if post_residual > 0 && item_size % 3 == post_residual % 3 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item fits into the post residual,
    // this placement is excellent (chained packing) -> reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decays with the leftover slack after the chain.
            score -= 90.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much dead space we would strand.
            let stranded = post_residual as f64;
            score += 0.5 * stranded;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "tight" bins; placing there to tighten them is good.
    let res_f = post_residual as f64;
    let dev = res_f - mean_residual;
    if dev < 0.0 {
        score -= 0.3 * (-dev);
    } else {
        score += 0.3 * dev;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere (large post residual in existing bins) or the
    // lookahead suggests a big next item benefits from a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        let big_next = next_item_size >= 50 && next_item_size <= bin_residual;
        if poor_fit || big_next {
            score -= 70.0;
        } else {
            score += 80.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize very small dead space
    // that is unlikely to ever be useful again.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 12.0 {
        score += 18.0; // tiny unusable gap is worse than a moderately sized gap
    }

    // Reward filling a bin nearly completely (post_residual near 0) even more.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 12.0; // next item can still go here
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across too many open bins when many bins fit the item
    // (prefer keeping bins consolidated); but if very few bins fit, be lenient.
    let fit_factor = fitting_bins_count as f64;
    score += 3.0 * fit_factor.ln().max(0.0);

    // Global residual pressure: if mean residual is low (bins nearly full),
    // slightly prefer opening fresh bins for large items to avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual < item_size as f64 * 1.2 && bin_residual == bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Early in the stream, be more willing to open new bins (keeps options open);
    // late in the stream, squeeze into existing bins.
    score -= 8.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;
    score += 6.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild preference for bins whose residual is close to mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize large post-residual quadratically (dead space).
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.8 + 1.4 * p2 + 0.9 * p3);

    // Reward near-perfect fits (small post_residual) increasingly with progress.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (2.0 + 3.0 * p3) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, scaled by residual waste.
        score += (fitting_bins_count as f64 - 1.0).ln() * pr * 0.15;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (below-mean residual => better fill).
    let dev = mean_residual - pr;
    score -= dev * 0.5 * (1.0 + p2);

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += gap * 0.6;
        if pr >= nxt {
            score -= 3.0 * (1.0 - gap / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for opening a new bin when open bins exist, decaying
    // smoothly as the stream progresses (consolidate early).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (1.0 - progress) * 6.0 + 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo buckets.
    // Residuals in [0,10) are near-perfect; [10,40) moderately reusable; >=40 wasteful.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -30.0 // perfect fill: strong reward
    } else if pr < 10 {
        -8.0
    } else if pr < 40 {
        0.0
    } else {
        (pr - 40) as f64 * 0.9 // quadratically-ish penalize big dead space
    };
    score += class;

    // Harmonic coupling: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // partial lookahead fit: reward proportional to how well it packs
            let fill = next_item_size as f64 / pr as f64;
            score -= 12.0 * fill;
        } else {
            // next item won't fit here; penalize tight-but-wasted residuals less if small
            score += 4.0 * (next_item_size as f64 - pr as f64).min(30.0) / 10.0;
        }
    }

    // Last chance: only this bin can fit the item -> strong preference to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has no sunk cost; make it mildly
    // unattractive unless the fit here is bad. Base penalty on tightness of fit.
    if bin_residual == bin_capacity {
        // tightness = how much of the bin the item consumes
        let tight = item_size as f64 / cap;
        // prefer new bin when item is large and would leave small residual elsewhere anyway
        score += 18.0 * (1.0 - tight);
        if pr < 10 {
            score -= 20.0; // item nearly fills a fresh bin: good to open
        }
    }

    // Tight fit reward: small post residual relative to item size is good.
    if item_size > 0 {
        let ratio = pr as f64 / item_size as f64;
        score += 6.0 * ratio; // big leftover relative to item => penalize
    }

    // Mean residual context: when open bins are generally loose, avoid adding
    // another loose bin; when residuals are tight, encourage packing here.
    let mres_norm = mean_residual / cap;
    score += 10.0 * (mres_norm - 0.3).max(0.0);

    // Stream progression: late in the stream, be more conservative (prefer tight fills).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (pr as f64 / cap);

    // Harmonic modulo threshold on post_residual: multiples of 5 are more reusable
    // (many item sizes are multiples of 5), reward them.
    if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Medium dead zones (11..=19) also rarely reusable given items >= 1 but skewed large.
    else if post_residual > 10 && post_residual <= 19 {
        score += 15.0;
    }

    // Reward tight fits (exact or near-exact placement).
    if post_residual == 0 {
        score -= 100.0;
    } else if (post_residual as f64) < 0.15 * bin_capacity as f64 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If next item is huge, opening fresh bin may be wise.
        if next_item_size > 60 {
            score -= 35.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: discourage excessive bin proliferation.
    score += 0.5 * open_bins_count as f64;

    // Progress-aware: later in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins with below-average residual (tighter bins get filled first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (bin_capacity as f64);
    score -= 30.0 * (1.0 - fit_ratio * fit_ratio);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item won't fit here; penalize leaving a gap smaller than next item
            let gap = post_residual as f64;
            if gap < next_item_size as f64 && gap > 0.0 {
                score += 12.0 * (1.0 - gap / (next_item_size as f64));
            }
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage closing out nearly-full bins
    if open_bins_count > 8 {
        score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit.
    // Base new-bin score moderately high; it wins when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize creating tiny unusable dead space (very small residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining bonus, stronger when the leftover is nearly consumed by next item.
            let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 + 10.0 * chain_tightness;
        } else {
            // Post residual too small for next item: penalize dead space, scaled by how close it came.
            let miss = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.08 * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when other bins can already fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // New bin is wasteful unless it would be very tight (large item).
            let waste = post_residual as f64;
            score += 10.0 + 0.25 * waste;
            // Early in stream, be more conservative about opening bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 6.0 * (1.0 - progress);
        } else {
            // No alternative: opening a new bin is necessary, mild reward.
            score -= 5.0;
        }
    }

    // Global state coupling: prefer placing into bins whose residual is far from mean
    // (reduces variance of open residuals, keeping some bins large for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins that keep a large residual when open_bins_count is low (future flexibility),
    // and prefer filling bins fully when many bins are open.
    let flex = (open_bins_count as f64).ln().max(0.0);
    score += 0.3 * post_residual as f64 / (bin_capacity as f64) * (1.0 / (1.0 + flex));

    // Late-stream urgency: drive residual to zero as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * post_residual as f64 * progress / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: waste penalized more as stream progresses
    score += 18.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post residual) with a non-linear bonus
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_item;

    // Dead-space penalty: post residual too small for typical future items
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 6.0 * (gap / bin_capacity as f64) * (gap / bin_capacity as f64);
    } else {
        score += 4.0 * norm_post; // last item: prefer fullest packing
    }

    // Last-chance bin bonus: only fitting bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // Mild preference for bins below mean residual (balance residuals smoothly)
    score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate: penalize mildly, more when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score += 8.0 + 14.0 * (1.0 - scarcity) * (1.0 - 0.5 * progress);
    }

    // Smooth stream-progress interaction with item size (large items early vs late)
    score += 5.0 * norm_item * progress * (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable" classes
    // (multiples of small divisors of capacity) are more likely to host future items.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 2 == 0 {
            -1.0
        } else {
            1.5
        };
        score += class_bonus;

        // Dead-space penalty: tiny odd residuals are nearly unusable.
        if pr < 10 {
            score += 12.0;
        } else if pr < 20 {
            score += 4.0;
        }
    } else {
        // Perfect fit is ideal.
        score -= 25.0;
    }

    // Integer-division threshold: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain bonus scaled by how well the next item fills the remaining space.
            let fill_after = (pr - next_item_size) as f64;
            score -= 8.0 - 0.05 * fill_after;
            // Harmonic coupling: next item leaves a clean class again.
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; penalize slightly less if this bin is the
            // only fitting option (avoid wasting a near-full bin).
            if fitting_bins_count == 1 {
                score -= 2.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item,
    // especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer tighter bins relative to the fleet mean residual.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when no open bin is a good host
    // (large item, few fitting bins, high mean residual).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if pressure > 0.55 && (item_size as f64) > 0.6 * cap {
            score -= 8.0 * pressure;
        } else {
            score += 15.0;
        }
    }

    // Mild preference for keeping the number of open bins bounded early on.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (min item size is small but typical items are large), so heavily
    // penalize any nonzero post_residual below a "usable gap" threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is good.
    score += open_bins_count as f64 * 0.35;

    // New-bin candidate handling: an empty bin should only win when the
    // item fits poorly everywhere else. Give it a moderate base cost so
    // decent fits into existing bins beat it, but keep it competitive
    // against badly fragmented bins.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If lookahead item is large and would also benefit from a fresh bin,
        // slightly encourage opening one.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0;
        }
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it is a tight fit; prefer consuming such tight bins first.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    } else {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    // Late in the stream, consolidate: weight residual waste more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Lookahead: if next item exactly fills the post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover anyway; mild penalty for leaving it.
        score += post_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Tight match: gap near 0 is great; decays quickly
            score -= 200.0 * (-gap / 25.0).exp();
        } else {
            // Next item can't fit here: penalize wasted tightness
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (1.0 - (-gap / 20.0).exp());
        }
    } else {
        // Last item: prefer minimal leftover
        score += 50.0;
    }

    // Prefer bins tighter than average (small residuals are precious)
    let tightness = mean_residual - post_residual as f64;
    score += 0.6 * tightness;

    // Last chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New empty bin candidate: penalize unless current bin would leave dead space
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if next item is huge and this item is small, opening fresh bin is fine
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 200.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins relative to progress (encourage reuse)
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio after placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space: residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bins attractive only when existing
    // fits are poor (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        // Default: discourage opening a new bin...
        let mut new_bin_score = score + 70.0;
        // ...unless the item is large (creates big residual waste elsewhere) or
        // few alternatives exist and mean residual across open bins is low.
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 && poor_fit < 0.35 {
            new_bin_score -= 90.0;
        }
        if pressure > 0.5 && mean_residual < 20.0 {
            new_bin_score -= 45.0;
        }
        return new_bin_score;
    }

    // Global state coupling: prefer bins whose residual is near the mean residual
    // (keeps bin residuals balanced, leaving structured space for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: early in the stream, be slightly conservative (favor balance);
    // late in the stream, aggressively fill whatever fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * t * fill;
    score += 10.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins when they are mostly empty.
    if open_bins_count > 4 && bin_residual > 80 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty growth.
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: early on, tolerate larger residuals (keep flexibility);
    // late in the stream, tighten preference for small post_residual.
    let progress_tightening = 1.0 + 2.0 * progress * progress;
    score += norm_pr * cap * (progress_tightening - 1.0);

    // Interaction: post_residual vs mean residual — penalize leaving more waste than average.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty for very small leftover
            score += 5.0 * (1.0 - norm_pr);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, less so early or when bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap + 25.0 * progress + crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference, slightly amplified
    score = post_residual as f64 * 1.05;

    // Harmonic class of post_residual: perfect fills are ideal
    if post_residual == 0 {
        score -= 60.0; // exact fit, close the bin
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect fill, dead space negligible
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    } else if post_residual <= 30 {
        score += 6.0;
    } else {
        score += 14.0; // large leftover = wasteful placement
    }

    // Harmonic coupling: does the NEXT item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining opportunity
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0; // next item leaves a tight, useful bin
            } else if slack > 50 {
                score += 8.0; // next item would waste most of the bin
            }
        } else {
            // next item cannot follow here; leftover must stand alone
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // the item is large and current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.35 {
            score += 40.0; // open bins are roomy, use them
        } else {
            score -= 5.0; // bins fragmented; fresh bin acceptable
        }
        // Large items prefer fresh bins to avoid fragmenting others
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // Early stream: opening bins early is cheap and useful
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 8.0;
        }
    }

    // Prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Modulo-class penalty: residuals that are awkward for common item sizes
    let r = post_residual % 10;
    if r != 0 && post_residual > 0 {
        score += 3.0; // non-multiple-of-10 residual is harder to reuse
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are pure waste; penalize them super-linearly.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is "replenished" to a useful zone after
    // placement (post_residual can still host a mid-size item).
    if post_residual >= 40 && post_residual <= 80 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another;
    // few open bins -> allow spreading to keep residuals flexible.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded
        // or the fit would leave an awkward gap.
        score += 20.0 + pressure * 2.0;
        if post_residual > 0 && post_residual < dead_threshold {
            score += 30.0;
        }
        // Lookahead: if next item fits the would-be residual of an existing
        // bin, opening a new bin is less urgent.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= pressure.min(25.0);
        // Lookahead synergy: placing here so next item fits too is great.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
            score += 8.0; // would block the next item's fit here
        }
    }

    // Mean-residual coupling: if this bin is far from the mean, nudge score
    // toward balance to avoid a tail of nearly-empty bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, be slightly conservative (keep bins flexible);
    // late in the stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (1.0 - progress) * 10.0; // early dead space is costlier long-term
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 45.0 + 10.0 * progress;
        } else {
            // Distance between post_residual and next item size: closer is better.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += gap * 0.35;

            // Bonus if next item still fits after current placement.
            if next_item_size <= post_residual {
                score -= 8.0;
            } else {
                // Next item won't fit: penalize leftover dead space proportionally.
                score += (post_residual as f64 / bin_capacity as f64) * 6.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 5.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual deviates favorably from the mean: filling a
    // bin below the mean residual tightens the global residual distribution.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that can fit the item: avoid opening a new bin.
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would leave
        // terrible dead space or the item is huge and fits nothing well.
        let worst_case_waste = if fitting_bins_count == 0 { 0.0 } else {
            // waste if forced into an existing bin is unknown; use mean residual as proxy
            (mean_residual - item_size as f64).max(0.0)
        };
        let big_item_bonus = if item_size > bin_capacity / 2 { 4.0 } else { 0.0 };
        score += 30.0 + big_item_bonus - worst_case_waste * 0.25;

        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= (1.0 - progress) * 10.0;
    }

    // --- Waste shaping ---
    // Non-linear penalty for small, unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on large post-residual.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (next_item_size as f64);
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 0.4 * (post_residual as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // End of stream: minimize waste aggressively.
        score += 0.8 * post_residual as f64;
    }

    // Prefer bins with residuals below the mean (compact the waste).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Progress-scaled exploration: early on, slightly favor opening new bins
    // to diversify residual structure; late, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize normally, less so early in the stream.
        score += 25.0 * (1.0 - 0.5 * progress);
        // Never open a new bin if an open bin would be nearly perfectly filled.
        if post_residual <= 10 && bin_residual != bin_capacity {
            score += 100.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty when many bins are open (consolidation pressure).
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post residual with stream progress
    let mut score = x * (1.0 + 0.6 * progress) + 0.8 * x * x * (1.0 - progress);

    // Reward tight fits: post_residual small relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 1.5 * gap * gap;
        // bonus if post residual still fits next item
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= 0.5 * fits_next * x;
    } else {
        // last item: strongly prefer filling existing bins
        score -= 1.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64;

    // Slight pull toward mean residual to consolidate space
    score += 0.1 * (x - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins whose leftover is "waste-class"
    // (very small, unusable) get rewarded for tight packing.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        let pr_mod = pr % 10;
        // class of dead space: 1..=9 mod 10 -> likely unusable for small items
        if pr_mod != 0 && pr < 10 {
            score += 15.0; // tiny dead space, penalize moderately
        }
        // integer-division thresholds on post_residual
        let q = pr / 20; // 0..=4 classes
        score -= q as f64 * 3.0; // larger usable residual classes preferred slightly
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match via integer division of next item class
            let nq = next_item_size / 10;
            score -= 6.0 + nq as f64 * 0.5; // reward chains
        } else {
            score += 4.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current residual is badly fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins are usually preferred
        score += 25.0;
        // but if all open bins would leave tiny dead space, new bin is better
        let waste_here = (bin_residual - item_size) as f64;
        if waste_here < 8.0 {
            score -= 35.0;
        }
        // early in stream, allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // capacity fraction harmonic: reward filling large fractions of the bin
    let fill_frac = item_size as f64 / cap_f;
    score -= fill_frac * 8.0;

    // many open bins -> encourage consolidation
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins whose post_residual is very small.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: post_residual in unusable small gaps (nothing in an
    // unknown 1..100 distribution reliably fits a gap of 1..9 later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.3;
    }
    // Lookahead failure: post_residual too small for next item -> dead space risk.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones,
    // unless this is the last fitting bin (avoid wasting its uniqueness).
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Opening a new bin is penalized more when many bins are already open.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But allow opening when current bin fits are all poor (large post_residual).
        if post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid a new bin.
        score -= 25.0;
    }

    // Mean residual coupling: penalize bins far above mean residual (hoarding space).
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Early-stream: be slightly more willing to open bins to build diverse residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- 2-step lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains: next item can land here too.
            // Bonus grows as the chain becomes tighter (post_residual ~ next_item_size).
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 6.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit here: mild penalty, stronger if we leave a tiny dead slit.
            score += 3.0;
            if post_residual < 10 {
                score += 5.0;
            }
        }
    } else {
        // Last item of the stream: pure tight-fit preference, extra aggressive.
        score -= 4.0;
    }

    // ---- Dead-space penalty: residual too small to ever hold min-size item ----
    if post_residual > 0 && post_residual < 10 {
        score += 7.0;
    }

    // ---- Last-chance bonus: only this open bin fits the item ----
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // ---- Consolidation relative to mean residual ----
    // Favor bins whose post_residual dips below the fleet mean (packing tightly).
    let pr = post_residual as f64;
    if mean_residual > pr {
        score -= (mean_residual - pr).min(50.0) * 0.12;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.05;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced opening: no open bin can host the item; make it acceptable.
            score -= 25.0;
        } else {
            // Discourage opening a new bin while open bins fit, unless the item
            // is huge and would leave a perfectly reusable residual for the lookahead.
            score += 15.0;
            if next_item_size > 0 && post_residual >= next_item_size
                && (post_residual as i64 - next_item_size as i64).abs() <= 5
            {
                score -= 18.0; // "fresh bin sized for the next item" trick
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear penalty on waste.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are nearly useless
    } else if post_residual >= 10 && post_residual < 30 {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward;
    // if next item cannot fit post residual but this bin was roomy, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            // next item won't fit here after placement; penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    // (consolidation pressure), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    score -= 0.05 * open_f * (bin_residual as f64 - mean_residual).max(0.0);

    // Early in the stream: mildly discourage opening new bins so bins fill up.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it is clearly better to spread load.
        let spread_benefit = if next_item_size > 0 && next_item_size >= item_size { 8.0 } else { 0.0 };
        score += 12.0 - 8.0 * progress - spread_benefit + 0.3 * open_f.max(4.0);
    }

    // Late in the stream: be greedy about exact fills.
    if progress > 0.8 && post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (bins stay flexible); later, punish dead space quadratically.
    let w = 1.0 + 3.0 * progress * progress;
    score += w * (pr / cap) * (pr / cap) * cap * 0.5;

    // Reward bins whose residual exactly accommodates the lookahead item (smooth gaussian-like coupling)
    let gap = (pr - nx).abs();
    score -= 12.0 * (-(gap * gap) / (2.0 * 15.0 * 15.0));

    // Penalize last-chance bins less when post_residual is small (avoid wasting a nearly-full bin)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Slight penalty proportional to number of alternatives (prefer scarce options implicitly via above;
    // add mild normalization against mean residual to avoid outlier hoarding)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor;
    // penalty fades with progress (late stream: fresh bins less valuable)
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_c * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "nice" divisibility classes are more reusable later.
    let cap = bin_capacity as f64;

    // Reward small post_residual (tight fit) non-linearly.
    let tight = (1.0 - (post_residual as f64) / cap).powi(3);
    score -= 8.0 * tight;

    // Penalize residuals that are awkward: small but not zero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Harmonic classes: post_residual divisible by 10 or 25 is "clean".
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd primes-ish residuals are bad.
    let half = post_residual / 2;
    if post_residual > 3 && post_residual % 2 == 1 && half % 2 == 1 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // Prefer leaving residuals in friendly classes for the next step.
            if nxt_post % 10 == 0 {
                score -= 5.0;
            }
            score += (nxt_post as f64) * 0.15;
        } else {
            // Next item won't fit here: slight penalty unless residual is tiny.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        let item_frac = item_size as f64 / cap;
        // Opening a bin is attractive for big items or when mean residual is small.
        score += 25.0 - 30.0 * item_frac - 0.5 * crowded - 5.0 * progress;
        // Don't open a new bin if some open bin fits nearly perfectly.
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 40.0;
        }
    }

    // Exact fit is always best.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference for bins below mean residual (spread load evenly).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=12) are hard to reuse.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 4.0; // up to +48 penalty for tiny gaps
    }
    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness reward relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage scattering items across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let dead = 100.0 - item_size as f64;
        score = dead * 1.2 + 25.0;
        if post_residual >= 0 && item_size <= 50 {
            score -= 10.0; // small items keep new bins flexible
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0; // leftover too small for next item -> dead space risk
        }
    }

    // Late in stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item fits: mild reward proportional to tightness of the chain.
            score -= 20.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item cannot fit in the residual: penalize wasted space.
            score += 15.0 + lookahead_gap * 0.5;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    if mean_residual > 0.0 {
        if (post_residual as f64) < mean_residual {
            score -= 10.0 * tightness;
        } else {
            score += 5.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave large dead space.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; discount when item is huge relative to capacity.
        score += 30.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
        // But if the item is large and would leave a big hole in existing bins, new bin is fine.
        if post_residual > 0 && post_residual < 15 {
            score -= 35.0;
        }
        // Early in the stream, opening bins is cheaper.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by the base term.

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
