    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize proportionally to wasted space.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the current
    // fit is very poor (large post_residual) and many bins already fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 25.0 - 35.0 * fit_pressure * (1.0 - poor_fit);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global state: when mean residual across open bins is high,
    // there is slack; mildly penalize placements that leave above-average residual.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.1;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Reward filling nearly-full bins completely.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Mild preference to spread load when many bins are open but few fit.
    if fitting_bins_count <= 2 && open_bins_count > 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Non-linear coupling: quadratic in post_residual modulated by progress
    score += (norm_post * norm_post) * 30.0 * (0.5 + progress);
    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - norm_post).powi(2) * 20.0 * (0.3 + progress);
    // Penalize dead space relative to next item (wasted capacity for lookahead)
    if next_item_size > 0 {
        let norm_next = next_item_size as f64 / bin_capacity as f64;
        let waste = (norm_post - norm_next).max(0.0);
        score += waste * waste * 25.0;
        // Reward leaving exactly room for next item
        let gap = (norm_post - norm_next).abs();
        score -= (1.0 - gap).powi(3) * 15.0;
    }
    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (0.5 + progress);
    }
    // New-bin candidate: penalize slightly, more when many open bins exist or early stream
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5 + (1.0 - progress) * 10.0;
    }
    // Encourage balancing residuals against mean
    score += (post_residual as f64 - mean_residual).abs() * 0.15;
    // Cubic smoothing term coupling item size and residual
    score += (norm_item * norm_post) * (norm_item - norm_post).abs() * 10.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity left

    // Perfect fit gets overwhelming priority
    if post_residual == 0 {
        return -10000.0;
    }

    // Dead space penalty: residuals that no typical item (1..=100) can use well
    // Penalize small unusable slivers quadratically.
    if post_residual < 10 {
        score += (10.0 - post) * 8.0;
    }

    // Harmonic class: classify residual by capacity thirds / quarters
    // Residuals near multiples of 25 are "reusable" classes (items often ~25ish)
    let quarter = post_residual % 25;
    if quarter == 0 && post_residual > 0 {
        score -= 30.0; // harmonic class: exact quarter multiples are highly reusable
    } else if quarter <= 5 {
        score -= 10.0; // near-quarter class
    } else {
        score += (quarter as f64) * 0.5; // off-class residuals slightly penalized
    }

    // Integer division thresholds: how many "slots" of the next item fit in post residual
    if next_item_size > 0 {
        let slots = post_residual / next_item_size.max(1);
        if slots >= 1 {
            score -= 20.0 + 5.0 * (slots as f64).min(3.0);
        } else {
            // next item cannot fit here: dead space for lookahead
            score += 15.0;
        }
        // If next item exactly fills residual, big reward
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Best-fit bias: among many candidates prefer smallest post residual (already in base)
        score += 0.0;
    }

    // New-bin candidate handling: opening a new bin wastes current mean residual
    if bin_residual == bin_capacity {
        // Fresh bin is attractive only if existing residuals are badly fragmented
        let fragmentation = (mean_residual - post).abs();
        score = cap - fragmentation;
        // Early in stream, prefer packing into open bins less; later, prefer tight fits
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If many open bins with large residuals, discourage new bin
        score += (open_bins_count as f64) * (mean_residual / cap) * 20.0;
    }

    // Mild preference to balance residuals toward mean (avoid extreme outliers)
    score += (post - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps left after placement.
    if post_residual > 0 && post_residual < 10 {
        // The smaller the dead gap, the worse it is (wasted space that nothing fits).
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
