    // Open-bin pressure: mildly discourage accumulating too many open bins,
    // scaled by stream progression (late in stream, consolidation matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Slight penalty for the brand-new empty bin candidate so we don't open
    // bins frivolously when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    // Reward bins tighter than the average residual (best-fit flavor).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match lookahead: reward when next item fits into post_residual, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot follow in this bin; penalize if we leave awkward dead space.
        score += 50.0;
    }

    // Reward tight fits (small post residual relative to bin capacity) with a nonlinear curve.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 80.0 * tightness * tightness;

    // Penalize leaving dead space below the minimum item size (unusable gap).
    if post_residual < 1 {
        score -= 200.0; // bin perfectly closed is great
    } else if post_residual < item_size.max(1) {
        // gap smaller than current item class: likely unusable
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "dregs",
    // prefer filling them; bins above mean should be saved for future items.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 60.0 * dev;

    // Prefer opening a new bin for very large items when few tight options exist.
    if item_size >= 70 && post_residual > 0 && post_residual < 20 {
        score += 40.0;
    }

    // Early stream: be slightly more liberal in opening bins; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 100.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

