    }

    // Lookahead: reward if the next item can also fit in the post residual.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0;
        // extra reward if next item would exactly fill it
        if next_item_size as u32 == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving dead space the next item cannot use
        score += 8.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 35.0;
        // But if the item is large relative to capacity, opening a fresh bin is natural.
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 30.0 * (frac - 0.5);
        }
        // If many bins are open and mean residual is large, opening a new bin
        // spreads load; mildly encourage when mean residual is high.
        if mean_residual > cap * 0.5 && open_bins_count > 2 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferation of new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Non-empty bins: small global-state coupling.
        // Prefer using bins whose residual is already below average (consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Many open bins: encourage consolidation into existing bins.
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Time horizon: early in the stream, be more willing to spread (handled via
    // new-bin term); late in the stream, be greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
