    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or when current
        // open bins have poor fit potential (high mean residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        score -= item_frac * 20.0;
        score += mean_residual * 0.15;
        // Late in stream, prefer filling existing bins.
        score += progress * 10.0;
    }

    // Fraction-of-capacity harmonic bands on post_residual.
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score += 6.0; // wasteful to leave more than half a bin empty after placing
    } else if frac > 0.25 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small to ever be useful (items >= 1, but tiny gaps
    // below the minimum item size are pure waste). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 150.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Next item cannot use the remaining gap: penalize proportionally to wasted space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins have large residuals (poor fits elsewhere) or many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 40.0;
        // More open bins -> new bin slightly cheaper (spreads load).
        score -= (open_bins_count as f64).min(10.0) * 2.0;
        // If mean residual is small, open bins are nearly full anyway -> new bin is fine.
        score += (mean_residual - 20.0) * 1.5;
        // Large items prefer a fresh bin to avoid fragmenting partial bins.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    } else {
        // Using an existing bin: mild pressure proportional to how full it already is,
        // encouraging consolidation into the fullest usable bin.
        let used = (bin_capacity - bin_residual) as f64;
        score -= (used / bin_capacity as f64) * 15.0;
    }

    // Progression: later in the stream, be slightly more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: penalize opening a new bin unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual as f64 <= (bin_capacity as f64 - item_size as f64).max(0.0) * 0.0 + 15.0 {
            score -= 45.0; // near-perfect fit in fresh bin
        }
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize dead space
            let dead = (post_residual - next_item_size.min(post_residual)) as f64;
            score += dead * 0.5;
        }
    } else {
        // last item: just minimize post residual
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than mean
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize very small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for using more open bins early vs late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 15.0;

    // Penalize dead space: residual too small for any realistic future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 10.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + fit_ratio * 10.0;
    }

    // New-bin candidate handling: empty bin gets baseline adjusted by global state.
    if bin_residual == bin_capacity {
        // Prefer new bin when open bins are fragmented (high mean residual spread)
        // or when current item is large relative to mean residual.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 45.0 + fragmentation * 0.2 - fit_ratio * 5.0 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
        return score;
    }

    // Time horizon: early in stream, be slightly conservative (keep bins balanced);
    // later, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.5;

    // Prefer bins with residual below mean (consolidating small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Mild penalty for many open bins already (encourage filling existing ones).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;

    let mut score = post + 12.0 * poly * cap;

    // Penalize dead space more strongly later in the stream (smooth cubic ramp)
    let ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 8.0 * norm_post * norm_post * ramp;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - norm_post;
    score -= 20.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin bonus (smooth, not piecewise)
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - post).abs();
        let compat = 1.0 / (1.0 + gap / cap);
        score -= 10.0 * compat * compat;
    }

    // Mild penalty for spreading across many open bins, smoothed with mean residual
    let mean_norm = mean_residual / cap;
    score += 3.0 * open_bins_count as f64 * mean_norm * mean_norm / (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes are more reusable; penalize "dead" residue classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Non-linear penalty for large leftover space, scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (post / cap) * (30.0 + 40.0 * progress);
    }

    // Harmonic class check: is post_residual a multiple of small common sizes?
    // Residuals divisible by 10 (or by the next item size) stay usable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
            // extra harmonic bonus if next item also divides post-residual
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64 - post) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score -= (mean_residual - post) * 0.15;

    // New-bin candidate: make an empty bin unattractive unless residual space
    // of open bins is truly dead (all residuals too small to matter).
    if bin_residual == bin_capacity {
        let dead_space = if next_item_size > 0 {
            mean_residual < next_item_size as f64 && mean_residual < 20.0
        } else {
            mean_residual < 20.0
        };
        if dead_space {
            score -= 15.0; // open a new bin, current ones are hopeless
        } else {
            score += 55.0; // keep using open bins
        }
    }

    // Mild preference to consolidate into fewer bins early on.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1) could use
    // are catastrophic; gaps below typical item sizes are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Tight fit reward: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // would strand the next item
    }

    // Open-bin pressure: discourage scattering across many bins early,
    // allow more bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - 1.0 * progress);

    // New-bin candidate: neutral baseline, mildly high so it only wins when
    // no open bin offers a decent fit (post_residual == bin_capacity here).
    if bin_residual == bin_capacity {
        score = 85.0 + (open_bins_count as f64) * 0.5 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Dead space for the next item: penalize proportionally to wasted capacity.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Tightness reward: placing into a bin that barely fits is good.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize so we only open when fits are bad,
    // but allow it when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pairing potential makes a fresh bin attractive
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += post_residual as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Reward bins that will be nearly full after placement (small waste).
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0; // dead space small enough to be nearly useless anyway
    }

    // Penalize leaving residual that is awkwardly small but not tiny:
    // space between 1 and 10 is often wasted; space just above typical small items is fine.
    if post_residual >= 1 && post_residual <= 5 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item still has a home here
        } else {
            score += 8.0; // bin dies and next item must go elsewhere
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Many fitting bins: mild penalty for hoarding space in the best bin? Prefer spreading:
    // penalize bins whose residual is far above the mean (space hoarding).
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.3;

    // New-bin candidate logic: empty bin has residual == capacity. Opening a new bin is
    // attractive only when the item fits poorly everywhere else; make empty bin costly
    // unless post_residual (== capacity - item) is large AND this is a good fresh start.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score += 25.0 + (open_bins_count as f64) * 2.0;
        // If the item is large, a fresh bin wastes little; discount the cost.
        score -= (item_size as f64) * 0.2;
        // Late in the stream, opening new bins is less useful (bins won't be reused).
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        score += progress * 30.0;
        // If several bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
    }

    // Time horizon: early in the stream, be conservative with existing bins (favor tight fits
    // more); late in the stream, just pack anything anywhere to close bins.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // Slight preference for bins with low residual overall (consolidate near-full bins).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth quadratic dead-space penalty: residuals that are too small to be useful
    let dead = if pr > 0 { ((20.0 - pr).max(0.0) / 20.0).powi(2) } else { 0.0 };
    score += 15.0 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits (small normalized post residual) with smooth cubic term
    score -= 10.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Smooth interaction with mean residual: prefer bins below mean residual (tighter)
    score += 0.3 * (mean_residual - bin_residual as f64) * (1.0 - progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr).powi(2));
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item nearly fits but cannot (fragmentation)
        let gap = next_item_size as f64 - pr;
        if gap < 10.0 {
            score += 6.0 * (1.0 - gap / 10.0);
        }
    }

    // Mild penalty for bin proliferation early in the stream
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress + (mean_residual / cap).powi(2) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 capture
    // "dead space" classes that are hard to fill for integer item sizes.
    let residue_class = post_residual % 10;
    score += (10 - residue_class) as f64 * 0.35;

    // Reward tight fits: small post_residual is good.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Penalize post residuals in awkward bands that few item sizes (1..100)
    // can still use: 41..49 and 51..59 are the least reusable leftovers.
    if post_residual >= 41 && post_residual <= 49 {
        score += 12.0;
    }
    if post_residual >= 51 && post_residual <= 59 {
        score += 9.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it barely does not fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - slack as f64 * 0.4;
        } else {
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin should be discouraged unless the
    // current bin leaves a very poor leftover. Bias the empty bin upward.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large, opening a fresh bin is natural.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Progress-based mild exploration: late in the stream, consolidate
    // more aggressively (tighter packing preferred over new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps < 10 cannot hold any item).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Extra penalty for moderately small gaps that are hard to fill.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 30.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 5.0 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: bins far below mean residual are better fill targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 400.0; // next item fills this bin perfectly
        } else if post_residual as i64 >= next_item_size as i64 {
            // next item fits here: reward tightness of the two-step chain
            score -= 150.0 / (1.0 + diff);
        } else {
            // next item won't fit: penalize leaving dead space relative to smallest item
            score += 60.0 + diff * 0.5;
        }
    }

    // Prefer bins whose residual was already tight (below-average residual).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.8;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current bins would leave large dead space.
    if bin_residual == bin_capacity {
        let waste_if_forced = (post_residual as f64) - (next_item_size as f64);
        let pressure = if next_item_size > 0 && waste_if_forced > 0.0 { 1.0 } else { 0.0 };
        score = 120.0 + pressure * 200.0 - (open_bins_count as f64) * 2.0;
    }

    // Slight late-stream preference for consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0 * (1.0 - res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize leaving large but unusable gaps for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver = dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // New-bin candidate logic: discourage opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so empty bins lose to reasonable fits.
        score += 15.0;
        // If no other bin fits (this is the only option), remove penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with slack: avoid adding another.
        if mean_residual > item_size as f64 {
            score += 12.0;
        }
    }

    // Mild preference for fuller bins when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // Global balance: prefer bins whose residual is close to mean residual (harmonized slack).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but with smooth non-linear penalty shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste hurts more (bins last long); late, favor tight fits even more.
    let poly = (1.0 - progress) * norm_pr * norm_pr * cap + progress * norm_pr * cap;
    score += 0.6 * poly;

    // Perfect fit reward (strongly subtract)
    if post_residual == 0 {
        score -= 40.0 + 30.0 * progress;
    } else if post_residual < item_size.min(20) {
        // small dead space penalty
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0;
    } else if next_item_size > 0 {
        // penalize leaving residual that nothing useful fits into
        score += 5.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize opening new bins early, less later
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Encourage balancing against mean residual (smooth coupling)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..100, capacity 100.
    // Classify post_residual into residue classes of 10 (decile bands).
    let decile = post_residual % 10;
    let band = post_residual / 10;

    // Dead-space penalty: residuals that are small but not zero are worst
    // (wasted space that almost nothing fits). Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic coupling: post_residual divisible by small integers is more
    // reusable by future items drawn from unknown distributions.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 2 == 0 {
        score -= 2.0;
    }
    // Odd, non-small residuals are slightly less attractive.
    if post_residual % 2 == 1 && post_residual > 10 {
        score += 3.0;
    }
    if post_residual % 3 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial match: reward proportional to fill of next item
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this bin's remainder; penalize large leftovers
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when all open bins would leave terrible
    // residue. Give the empty bin a moderate baseline so tight fits win.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap; later, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping larger residual bins available for big future items.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Integer-division threshold on band: very large leftover bands (>50)
    // are fine to create; mid bands (10..50) are moderately wasteful.
    if band >= 1 && band <= 5 && post_residual > 0 {
        score += 5.0;
    }

    // Coupling with item size: placing large items rewards tight fits more.
    if item_size >= 50 && post_residual < 20 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        // Medium gaps are risky too but less so.
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward using bins that would otherwise leave large wasted space.
    if post_residual as f64 > mean_residual {
        score += 8.0;
    } else {
        score -= 8.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it.
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late-stream tightening: prefer tighter fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post_residual exactly matches the next item size (2-step chain fill)
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step closure
        }
    }

    // Penalize dead space relative to mean residual
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the fit is tight
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual <= 10 {
            score -= 30.0; // near-perfect fill of fresh bin
        }
    }

    // Late in stream: tighten packing, avoid small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * item_size as f64 * 0.5;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    }

    // Penalize dead space that likely cannot be reused (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // New-bin candidate handling: neutral baseline, discourage unless open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when it clearly beats existing bins.
        score += 30.0 + open_bins_count as f64 * 0.5;
        // But if the item fills a fresh bin well, encourage it.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 25.0;
        }
        // Early stream: opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that blocks the next item, reward leaving
    // a residual that exactly (or nearly) accommodates it.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here: leftover is dead for the lookahead horizon.
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.8;
        }
    }

    // Global state coupling: prefer filling bins when many bins are open (consolidation),
    // prefer spreading when few bins are open.
    if open_bins_count > 4 {
        score -= 5.0;
    } else {
        score += (4 - open_bins_count.min(4)) as f64 * 2.0;
    }

    // Mean-residual coupling: if this bin is much tighter than average, filling it is good.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Time horizon: late in the stream, avoid opening bins and squeeze tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score -= progress * 8.0;
    } else {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more.
    let coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0; // smooth bump, max mid-stream
    score -= (cap - pr) * 0.35 * coupling;

    // Quadratic penalty on small dead space that becomes unusable
    score += norm_pr * norm_pr * (cap * 0.25);

    // Reward using last-chance bins smoothly
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Mild preference for bins below mean residual (spreading fill)
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff * diff / cap;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Penalize opening new bins late in the stream when alternatives exist
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod 10 quantization of dead space
    let pr = post_residual;
    let class = pr % 10;
    // Dead space that is a "harmonic" multiple of 10 is more reusable
    let harmonic_bonus = if class == 0 && pr > 0 {
        -6.0
    } else if class <= 2 {
        -2.0
    } else if class >= 8 {
        4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold: small post_residual is nearly dead
    if pr <= 10 {
        score += 15.0;
    } else if pr <= 20 {
        score += 6.0;
    } else if pr >= 50 {
        score -= 5.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            score += 3.0;
        }
        // Harmonic class match between leftover and next item
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless
    // existing fits are terrible; empty bin keeps full residual anyway
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // Stream progression: late in stream, tighten up — avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64 * 0.05);

    // Prefer filling bins below mean residual (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize wasting a large residual on a small item (poor fill ratio).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.25 * waste * waste / bin_capacity as f64;

    // Open-bin pressure: fewer open bins relative to items processed -> prefer
    // reusing bins; when many bins are open, allow new-bin flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * (open_bins_count as f64 - mean_residual / 10.0).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit the post-residual exactly, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 { score -= 50.0; }
            else if gap < 10 { score -= 15.0; }
            else { score += 0.1 * gap as f64; }
        } else {
            // Next item cannot use this residual: dead space likely.
            score += 5.0 + 0.2 * post_residual as f64 * progress;
        }
    }

    // Mild preference for established bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled slightly super-linearly.
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.002 * pr / cap);

    // Lookahead: if the next item exactly fits the post-residual, strongly reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 30.0;
        } else if nxt <= pr {
            // Next item fits: reward proportionally to how well it uses leftover space.
            score -= 12.0 * (nxt / pr.max(1.0));
        } else {
            // Next item does NOT fit here: penalize leaving a gap smaller than next item
            // (dead space that the lookahead item cannot use).
            let waste = pr / cap;
            score += 8.0 * waste;
            if pr < nxt {
                score += 4.0 * (nxt - pr) / cap;
            }
        }
    }

    // Compare residual against mean residual of open bins: prefer bins whose residual
    // deviates downward (tighter than average) after placement.
    let dev = (mean_residual - pr) / cap;
    score -= 6.0 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when fits elsewhere are very poor.
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.5 * pr;
        if fitting_bins_count <= 1 {
            // No good alternative exists; new bin is fine.
            score -= 10.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild penalty for very small leftover slivers that likely become dead space.
    if pr > 0 && pr < 10.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let tight_bonus = 60.0 * (-post_residual as f64 / 25.0).exp();
    score -= tight_bonus;

    // Penalize leaving residuals that are too small for typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) < 10 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // next item cannot use this leftover; mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Many options: encourage consolidation into fullest usable bin.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin is attractive only if the item
    // is large relative to capacity or existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items; penalize for small items.
        score += 55.0 * (1.0 - fill_ratio);
        // If many bins already open and mean residual is high, discourage new bin.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.2 {
            score += 30.0;
        }
        // Late in stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Existing bin: slight preference for bins with lower residual (fuller bins)
        // to keep large residuals concentrated in few bins.
        score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);
        // If mean residual is low overall, be frugal with space.
        if mean_residual < 20.0 && post_residual > 0 {
            score += post_residual as f64 * 0.3;
        }
    }

    // Mild global pressure: many open bins -> prefer packing into existing ones.
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64 - 4.0).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize key quantities
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;              // normalized post residual
    let fit_norm = if bin_residual >= item_size { 1.0 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, waste is heavily penalized.
    let waste_weight = 1.0 + 4.0 * progress * progress; // smooth ramp 1..5
    score += waste_weight * pr * pr * cap * 0.5;

    // Reward tight fits via smooth cubic of (1 - pr)
    score -= (1.0 - pr).powi(3) * cap * 0.6;

    // Last-chance bonus: smooth decay, stronger late in stream
    let last_chance = if fitting_bins_count == 1 && fit_norm > 0.0 { 1.0 } else { 0.0 };
    score -= last_chance * (10.0 + 20.0 * progress);

    // Lookahead: penalize if next item cannot use the post residual (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr * cap - nxt).max(0.0) / cap;
        score -= usable * usable * cap * 0.8;
        score += (nxt / cap) * 5.0 * (1.0 - pr);
    }

    // Mean residual context: prefer bins below mean residual when mean is high (fragmentation)
    let mr = mean_residual / cap;
    score += (pr - mr) * 8.0 * (0.5 + progress);

    // Mild penalty for proliferating bins
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: make it attractive only when residual is large and fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= 15.0 * scarcity * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes are more likely to be filled later.
    let post = post_residual;
    let cap = bin_capacity;

    // Reward tight fits: post_residual in low classes (0..=10) heavily favored.
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= 10 {
        score -= 40.0;
    } else if post <= 20 {
        score -= 15.0;
    }

    // Penalize "awkward" residuals that few item sizes can use.
    // Items are 1..=100; a residual r is usable by item s if s <= r.
    // Dead-space penalty grows when post_residual is small-but-not-tiny
    // relative to typical item sizes.
    if post > 0 && post < 10 {
        score += 25.0; // sliver: nearly unusable
    }

    // Modulo-classes: residuals divisible by common item granularities
    // (e.g. multiples of 10, 25, 50) are more reusable.
    if post % 10 == 0 && post > 0 {
        score -= 8.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 6.0;
    }
    if post % 50 == 0 && post > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap as f64);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much space is wasted.
            score += 5.0 * (post as f64 / cap as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post <= cap / 2 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current fit is bad (large post_residual that
    // no next item can use) or when few bins are open.
    if bin_residual == cap {
        let fit_quality = post as f64 / cap as f64; // = 1 - item/cap for empty bin
        // Base cost of opening a new bin, discounted early in the stream
        // and when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        score += open_cost;
        // But if item is large (leaves little residual), a fresh bin is good.
        score -= 30.0 * (1.0 - fit_quality);
        // If no open bin fits well, opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Prefer filling bins with below-average residual (balance avoidance):
    // packing into tighter bins preserves large spaces for large future items.
    score -= (mean_residual - post as f64).max(0.0) * 0.3;

    // Mild penalty for wasting a big bin on a small item.
    score += 0.1 * (post as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Strong penalty for very small gaps relative to item size (fragmentation risk).
    if post_residual > 0 && (post_residual as f64) < 0.25 * item_size as f64 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) superlinearly.
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap: penalize dead space more.
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // with few open bins, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open or late in stream.
        score += 30.0 + 5.0 * bin_pressure + 20.0 * progress;
        // But if no open bin gives a decent fit (best post_residual would be tiny),
        // this penalty is effectively countered by their dead-space penalties.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin guarantees next item fits; slight reward.
            score -= 5.0;
        }
    } else {
        // Reward using existing bins, scaled by how much residual they consume.
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (concentrate filling of fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here too: mild reward proportional to its size
            score -= (next_item_size as f64) * 0.5;
        } else {
            // dead space for next item: penalize small unusable gaps
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 40.0;
            }
        }
    }

    // Prefer bins with residuals near mean (balanced packing), penalize outliers
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin before opening a new bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when good open-bin candidates exist
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 50.0;
        }
    }

    // Slight preference for tighter bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64) * (0.1 + 0.2 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // moderate dead space, mildly penalized relative to mean residual
        score += 6.0 * (1.0 - (post_residual as f64 / mean_residual.max(1.0)).min(1.0));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual < 5 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 4.0;
        }
    }

    // New-bin candidate logic: empty bin should win only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base handicap so open bins with decent fits win.
        score += 35.0;
        // More open bins -> harder to justify a new one.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // But if the item is large relative to capacity and few bins fit it,
        // opening a fresh bin is reasonable (large item gets a clean bin).
        if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
        // If next item is huge, keep capacity free: opening new bin now preserves flexibility.
        if next_item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    } else {
        // Crowding bonus: prefer bins whose residual is close to item (best-fit flavor),
        // scaled by how many alternatives exist.
        let waste = (bin_residual - item_size) as f64;
        score += 3.0 * (waste / (bin_capacity as f64)) * (fitting_bins_count as f64);
    }

    // Global dispersion: if mean residual is high, prefer filling the emptiest-feeling
    // bins (align score with deviation from mean residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 1.5 * dev / (bin_capacity as f64);

    // Early stream: slightly encourage keeping bins balanced to preserve options.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64 - 0.5).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth coupling: dead space matters more as the stream progresses
    score += 25.0 * norm_pr * norm_pr * progress * (1.0 - progress + 0.5);

    // Reward near-perfect fills more aggressively over time
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize bins far below mean residual (wasted large gap) via smooth term
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    let dev = (pr - mr) / cap;
    score += 8.0 * dev * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how much it overshoots
        let over = (next_item_size as f64 - pr) / cap;
        score += 4.0 * over * over;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let mean_tight = 1.0 - (mr / cap);
        score = pr + 30.0 * (1.0 - crowd * mean_tight) * (0.5 + 0.5 * progress);
    }

    // Slight preference to consolidate across many open bins
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (integer division into decile buckets) ----
    // Small-but-nonzero residuals are "dead space" classes: heavily penalized.
    let class = (post_residual / 10) as i32;
    score += match class {
        0 => 12.0,          // 0..9 : near-dead space, almost unusable
        1 => 2.0,           // 10..19: only fits tiny items
        2 => 0.0,
        3 => -1.5,          // 30..39: decent mid class
        4 => -2.0,          // 40..49: sweet spot
        5 => -1.0,
        6 => 0.5,
        7 => 1.0,
        8 => 0.0,
        9 => -0.5,
        _ => 0.0,
    };

    // ---- Modulo-10 harmonic coupling: residuals that are multiples of 10 chain well ----
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.5;
    }
    // Odd tiny remainders are worst offenders
    if post_residual % 2 == 1 && post_residual < 15 {
        score += 4.0;
    }

    // ---- Lookahead: reward if next item fits in post_residual, penalize mismatch ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.04;
        }
    }

    // ---- Last-chance bin: strongly prefer using it over opening a new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // ---- Crowding: many open bins with high mean residual -> prefer consolidation ----
    if open_bins_count > 3 && bin_residual < mean_residual as u32 {
        score -= 1.5;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // No (or only this) viable bin: opening fresh is cheap and attractive
            score = 15.0 - 0.05 * mean_residual;
        } else {
            // Good existing fits exist: make new bin very unattractive
            score = 80.0 + mean_residual * 0.2 + (fitting_bins_count as f64) * 2.0;
        }
    }

    // ---- Late-stream tightening: near the end, waste hurts more ----
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual that no plausible future item (1..=100) can use well is wasted.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Small gaps (< 10) are pure dead space: heavy penalty.
        if post_residual < 10 {
            score += 200.0 + (10.0 - pr) * 20.0;
        }
        // Mid gaps that can only fit tiny items are also risky.
        if post_residual >= 10 && post_residual < 30 {
            score += 40.0 + (30.0 - pr) * 2.0;
        }
        // Gaps just above a common size band boundary are awkward.
        if post_residual > 90 {
            score -= 50.0; // nearly-empty bin anyway; low cost
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another gap: mild reward scaled by tightness
        let left = post_residual - next_item_size;
        if left < 10 {
            score -= 80.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this gap: penalize proportionally to wasted potential
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // New bin base cost grows with open bins count and mean residual availability.
        score += 100.0 + open_bins_count as f64 * 25.0 + mean_residual * 1.5;
        // But if this is a late stream stage and open bins are few, opening is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
        // If no other bin can fit (fitting_bins_count == 1 means only this new bin), allow it.
        if fitting_bins_count <= 1 {
            score -= 400.0;
        }
    } else {
        // Reward placing into existing bins, more so when many bins are open.
        score -= open_bins_count as f64 * 3.0;
        // Tight fits into existing bins are extra valuable.
        if post_residual <= 5 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 150.0; // next item will close this bin perfectly
        } else {
            score -= 60.0 / (1.0 + gap);
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist: new bin has full residual.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    }

    // Late-stream pressure: be more conservative as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual with a convex term.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize leaving residuals that are too small for typical future items
    // (dead space), but reward residuals that could fit the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead bonus: residual can host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the next item.
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item fits poorly everywhere else. Penalize new bins mildly so open
    // bins with decent fits win, but not so much that a bad fit is forced.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 - 4.0 * progress;
        // If open bins are crowded on average, a new bin is more reasonable.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 6.0;
    } else {
        // Reward using existing bins when the mean residual is large (waste avoidance).
        let gap = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * gap;
    }

    // Mild reward for consolidating many open bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + progress) - pr_norm * progress * 0.7;
    score += 40.0 * poly;

    // Tight fits are rewarded more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space relative to the mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr_norm);
    }

    // Mild penalty for bin proliferation early in the stream
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer it only when it promises a large usable residual
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "useful"
    // (small, or exactly consumable by typical small items) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: best possible outcome.
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals below 10 (min item) are pure waste.
        if pr < 10 {
            score += 40.0;
        }
        // Modulo-10 class: residuals that are multiples of 10 align with
        // common item sizes; reward them mildly.
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // Harmonic divisibility classes on capacity fraction.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if pr % half == 0 {
            score -= 12.0;
        }
        if pr % quarter == 0 {
            score -= 6.0;
        }
        // Integer-division thresholds: classify residual into bands.
        let band = pr / 10; // 0..=10
        score += band as f64 * 1.5; // larger leftover slightly worse (baseline)
        // Lookahead coupling: if next item fits exactly into post_residual,
        // this bin chains perfectly.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0;
            } else if next_item_size < pr {
                let chain_residual = pr - next_item_size;
                if chain_residual < 10 {
                    // chain leaves dead space -> mild penalty
                    score += 5.0;
                } else if chain_residual % 10 == 0 {
                    score -= 15.0;
                }
                // how well next item divides the residual (harmonic classes)
                if pr % next_item_size == 0 {
                    score -= 10.0;
                }
            } else {
                // next item cannot fit here; residual must survive further
                // steps -> penalize awkward residuals more.
                if pr % 10 != 0 {
                    score += 6.0;
                }
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless it's a terrible fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // even a dead-space fit beats opening a bin
        }
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // open bins are fragmented (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64;
        score -= 5.0 + fragmentation * 0.5;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if the next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins that are already heavily loaded.
    let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= load_frac * 5.0;

    // Coupling with mean residual: prefer bins below mean residual
    // (denser bins) to keep fragmentation low.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10) are unusable for
    // typical items; penalize them heavily (non-linearly).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one (empty candidate) is less bad.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate (empty bin): add a fixed opening cost so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual deviates favorably from the mean:
        // below-mean residual means this bin is already tight -> use it.
        score -= 0.4 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would be blocked by a small dead gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
