pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed
    let t = step_index as f64 / (total_items as f64).max(1.0);

    // Reward tight fits: strongly favor small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used by the lookahead item
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += 6.0 + 0.05 * (next_item_size as f64);
        } else {
            // Reward bins that can still host the next item
            score -= 3.0;
        }
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's already
    // fragmented; penalize leaving odd leftovers here.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev.abs();

    // Early in stream: be pickier about tight fits (more future structure possible);
    // Late in stream: simply minimize post_residual.
    score += 8.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or nothing fits well anywhere.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let poor_options = (fitting_bins_count as f64).max(1.0);
        score = 25.0 + 55.0 * large_item - 10.0 / poor_options;
        // Late in the stream, opening new bins is cheap since leftovers matter less
        score -= 10.0 * t;
        // If lookahead is large and item is large, fresh bin is good
        if next_item_size >= 50 && item_size >= 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual, with non-linear shaping
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits; late, strongly punish wasted space
    let progress_coupling = pr * (0.25 + 1.75 * progress * progress);
    score += progress_coupling;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = if pr < 10.0 { pr } else { 0.0 };
    score += dead * (1.0 + progress);

    // Lookahead: reward bins whose post-residual can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: acceptable early, increasingly discouraged as stream advances
    score += is_new_bin * (10.0 + 25.0 * progress + 5.0 * open_bins_count as f64 * progress);

    // Slight tie-break toward bins below mean residual (consolidation)
    score += 0.15 * (mean_residual - pr).max(0.0) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residues mod small primes.
    let pr = post_residual;
    let r3 = (pr % 3) as f64;
    let r5 = (pr % 5) as f64;
    let r7 = (pr % 7) as f64;

    // Dead-space penalty: residual that no typical item (1..=100) can pair with.
    // Residuals 1..9 are near-dead; large residuals are fine.
    if pr > 0 && pr < 10 {
        score += 40.0 - (pr as f64) * 2.0; // small residuals are dead space
    }
    if pr == 0 {
        score -= 30.0; // perfect closure is excellent
    }

    // Modulo harmonic coupling: residuals divisible by 3,5,7 are more reusable
    // by integer-sized items drawn from broad distributions.
    if pr > 0 {
        if pr % 3 == 0 { score -= 4.0; }
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 7 == 0 { score -= 3.0; }
        score += r3 * 0.5 + r5 * 0.4 + r7 * 0.3;
    }

    // Lookahead: does next_item_size fit exactly into the post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // chain completion
        } else if next_item_size < pr {
            score -= 6.0; // next item still fits here
        } else {
            score += 5.0; // next item won't fit: residual becomes dead
        }
        // Harmonic class match between residual and next item
        if pr > 0 && next_item_size % pr.max(1) == 0 {
            score -= 3.0;
        }
        if pr % 10 == 0 && next_item_size % 10 == 0 {
            score -= 4.0; // decade-aligned items pair well
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, consolidate.
        let new_bin_cost = 15.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // Accept new bin only if item leaves a huge residual in any existing bin
        // (i.e., fit is loose) — compare against mean residual.
        let fit_quality = post_residual as f64 / cap; // 1.0 for empty-bin fit of small item
        let _ = mean_residual;
        score = score * 0.5 + new_bin_cost + fit_quality * 20.0;
        // If item exactly fills a new bin's capacity fraction, allow it.
        if item_size % 25 == 0 {
            score -= 10.0;
        }
    }

    // Mild consolidation pressure: bins tighter than mean residual are better targets.
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100 unknown; treat < 12 as likely dead)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward snug fits relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate gets penalized), encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // unless the fit into existing bins is terrible (large post_residual elsewhere).
        score += 20.0 + 8.0 * pressure;
    } else {
        score -= pressure;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size < 12 {
            // next item can't use this dead space anyway; soften penalty slightly
            score -= 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill the fuller bins first), keep large residuals for future big items.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
