pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively for large items.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * (item_size as f64) * 0.8;

    // Penalize dead space that cannot fit typical future items (small residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (next_item_size as f64) * 0.2;
        } else {
            // Penalize leaving a residual that wastes space relative to next item.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += waste * 0.1;
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (fill fuller bins first).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.15;
    }

    // Time horizon: late in the stream, consolidate more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Many open bins: encourage closing out (filling) existing bins rather than spreading.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }

    // New empty bin candidate: only attractive if no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
