    // Base: post residual, normalized, with non-linear penalty on very small residuals (dead space)
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.6 * pr_norm * (1.0 - pr_norm));

    // Tight fits rewarded: quadratic coupling of fill ratio with stream progress
    let fill = fit;
    score -= 0.9 * fill * fill * (1.0 + 0.8 * progress);

