    if pr == 0 {
        score -= 1.5;
    } else {
        // Penalize residuals too small for likely future items (dead space), smooth in progress
        let dead = (1.0 - pr_norm).min(0.2) / 0.2;
        score += 0.4 * dead * dead * (0.5 + progress);
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.3 * progress;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // Crowding: many open bins with low mean residual -> prefer filling existing bins
    let mr = mean_residual / cap;
    score += 0.2 * (open_bins_count as f64).ln() * mr * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a mild penalty unless residuals are tight
    if bin_residual == bin_capacity {
        score = 1.0 + 0.5 * progress - 0.6 * mr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality classes.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual in 1..=10 (small dead space, often unusable) -> mild reward.
    // Class 2: post_residual in 11..=30 -> neutral-ish.
    // Class 3: post_residual > 30 -> penalize leaving large usable space wasted by a bad fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score += (post_residual as f64 - 10.0) * 0.35;
    } else {
        score += 12.0 + (post_residual as f64 - 30.0) * 0.25;
    }

    // Modulo-arithmetic harmonic coupling: bins whose residual after placement
    // can host a "harmonic" future item (next_item_size divides into post_residual
    // region) are favored.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still fit here: strong reward, scaled by tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight * 0.3;
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // Harmonic divisibility bonus: post_residual % next_item_size small
        // means future near-perfect packing potential.
        if next_item_size > 0 && post_residual > 0 {
            let r = post_residual % next_item_size;
            if r == 0 {
                score -= 15.0;
            } else if r <= 3 {
                score -= 6.0;
            }
        }
    } else {
        // Last item: perfect fit is all that matters.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly; the baseline post_residual (= capacity - item)
        // already reflects leftover size.
        score += 30.0 + 0.1 * open_bins_count as f64;
    }

    // Prefer fuller bins (smaller residual before placement) slightly.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mean-residual coupling: when the fleet is generally full, avoid spreading.
    if (mean_residual as f64) < 20.0 && post_residual > 0 {
        score += 5.0;
    }

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing small can use are worse.
    // A residual below the minimum item size (1..100 domain, but treat <10 as dead)
    // is pure waste; penalize heavily with a non-linear term.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold {
        // near-perfect but slightly wasted: mild reward still
        score -= 5.0;
    }

    // Prefer bins whose residual was already fragmented (large residual wasted on small item)
    if (item_size as f64) < bin_residual as f64 * 0.3 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += 25.0 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // But if the item fits poorly everywhere else, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover -> leftover likely dead
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;

    let mut score = post;

    // Perfect-fit lookahead: strongly reward bins whose post residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 0.5 * item;
    }
    // Near-exact fit (small gap) also rewarded proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = post - nxt;
        if gap <= 10.0 {
            score -= 25.0 - 2.0 * gap;
        }
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Penalize creating tiny unusable residuals (dead space) relative to capacity.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }
    // Reward tight fits overall (small post residual).
    score -= (cap - post) / cap * 8.0;

    // Compare against mean residual: bins far below mean residual are "tight" already;
    // prefer spreading load into loose bins when fit is poor.
    if post > mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * item;
    }

    // New-bin candidate handling: opening a new bin is attractive early in the stream
    // or when many bins are open with high mean residual (fragmented state).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheaper early, pricier late.
        score += 18.0 + 25.0 * progress;
        // If existing bins fragment badly (mean residual high) and item is large,
        // opening fresh is competitive.
        if mean_residual > 0.45 * cap && item > 0.5 * cap {
            score -= 22.0;
        }
        // If next item is huge, keep a fresh bin available.
        if nxt > 0.7 * cap {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * fill_ratio;
    } else if fill_ratio > 0.6 {
        score -= 12.0 * fill_ratio;
    }

    // Dead-space penalty: small post_residual that can't hold a typical item is wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0; // base cost of opening a fresh bin
        // A large item deserves a fresh bin (keeps small residuals flexible).
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If the current item pairs perfectly with the next item, a fresh bin is great.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && (bin_capacity - item_size - next_item_size) < 10 {
            score -= 45.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins with small mean residual: reuse instead of opening new.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        }
    }

    // Prefer bins whose residual deviates below the mean (compact them first).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 3.0 * dev.min(20.0) / 20.0;
        } else {
            score += 2.0 * (-dev).min(20.0) / 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 18.0 * (x - 0.5) * (x - 0.5) * (1.0 + progress) * cap;
    score -= 12.0 * x * (1.0 - x) * (0.5 + progress) * cap;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= 20.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if x < nx {
            score += 10.0 * (nx - x) * (1.0 + progress) * cap;
        } else {
            score -= 6.0 * (x - nx) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 10 classes.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,               // perfect fit -> strongly reward
        1 | 2 => -3.0,           // near-perfect: still very usable
        3 | 4 | 5 | 6 | 7 => 0.0,
        8 | 9 => 2.5,            // awkward sliver -> penalize
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: does post_residual still admit a "typical" item?
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 2.0; // roomy bin stays flexible
    } else if post_residual >= quarter {
        score -= 0.5;
    } else if post_residual > 0 {
        score += 1.5; // cramped bin, poor future utility
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // modular class of slack after hypothetical next placement
            score -= match slack % 10 {
                0 => 4.0,
                1 | 2 => 2.0,
                _ => 0.5,
            };
        } else {
            // next item won't fit here: slightly prefer bins already "dead-ish"
            let dead = post_residual < 10;
            if dead {
                score += 0.0;
            } else {
                score += 1.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // if all open bins are badly fragmented or this is a perfect-fit-starved state.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // penalize opening a bin when open bins have healthy mean residual
        score += 14.0 * fragmentation;
        // early stream: mildly discourage proliferation
        score += 4.0 * (1.0 - progress);
        // if the item is large, a fresh bin is often fine
        if item_size > bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Prefer bins whose residual tightly matches the item (small slack relative to item).
    if bin_residual > item_size {
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 25.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the empty-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 4.0;
        score += pressure;
        // Only open a new bin if no open bin fits well.
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Late in the stream, opening new bins is even less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Reward using existing bins, scaled by how full the fleet already is.
        score -= 3.0 * open_bins_count as f64;
    }

    // Lookahead: penalize leaving a residual that can't hold the next item
    // unless this bin is the only option.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 10.0;
        } else {
            score -= 5.0;
        }
    }

    // Mild deviation from mean residual: prefer bins with residual near mean
    // to keep the fleet balanced, but reward below-mean (fuller) bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Penalize residuals too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward residuals that can still host the next item comfortably.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= ((post_residual - next_item_size) as f64).sqrt() * 2.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild bias toward filling existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate: make it slightly unattractive unless it beats a poor fit.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization, super-linear).
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * residual_frac * residual_frac;

    // Reward exact fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space too small for the smallest item (<= 10 unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward;
    // if next item would leave this bin nearly dead, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item can't use the leftover: leftover becomes dead unless reusable.
            let dead = post_residual as f64;
            score += 8.0 * (dead / bin_capacity as f64);
        }
    }

    // Prefer filling bins whose residual is already below the mean (consolidate waste).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Late in the stream: be more conservative, prefer tighter fits / fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * residual_frac;

    // Many open bins: discourage new-bin opening, encourage using existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty growing with open bins.
        score += 12.0 + 2.5 * open_bins_count as f64;
        // But if the item is large and no bin fits well, new bin may be fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post residual), with a convex penalty on large post residuals.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, tolerate slack; later, tighten aggressively.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Reward using bins that are already below-average residual (consolidating waste).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward; otherwise penalize dead space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - (nx / cap));
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for opening many bins late in the stream when a new-bin candidate.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more likely to be closed out efficiently.
    let r = post_residual % 10;
    let residue_bonus: f64 = match r {
        0 => -6.0,          // perfectly divisible leftover, highly reusable
        1 | 2 | 3 => -3.0,  // small leftover, near-full bin is good
        8 | 9 => 4.0,       // awkward large-ish leftover
        _ => 0.0,
    };
    score += residue_bonus;

    // Integer-division thresholds on post_residual: reward tight fits.
    let tight = post_residual / 10; // 0..=10 class
    score -= (10 - tight as i32).max(0) as f64 * 0.8;

    // Penalize leaving a residual that no plausible item can use:
    // dead space if post_residual is tiny but nonzero is fine; but a
    // leftover just above the minimum item size is a trap.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 2.5; // trap zone: only tiny items can use it
    }

    // Coupling with next item (lookahead): if the next item fits exactly
    // into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are all quite full or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let item_class = item_size / 20; // 0..4 harmonic class of item size
        let penalty = 20.0 + item_class as f64 * 3.0 - avg_fullness * 25.0 - progress * 5.0;
        score += penalty.max(2.0);
    }

    // Mild preference for filling bins that deviate below mean residual
    // (concentrate usage in emptier bins to keep tight bins tight).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps that are too small to fit any plausible
    // future item are wasted capacity. Penalize them super-linearly.
    let dead_threshold = cap * 0.2; // gaps below 20 units are nearly unusable
    if (post_residual as f64) < dead_threshold {
        let gap = dead_threshold - post_residual as f64;
        score += 4.0 * gap * gap / cap; // quadratic dead-space penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 12.0 * tightness;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // rather than spreading items out.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a useful residual elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow new bin when item is big (would fit almost nowhere else).
        if (item_size as f64) > 0.8 * cap {
            score -= 55.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post residual but would fit in this bin's
    // current residual, mild penalty for consuming that option.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Slight preference for bins whose residual is above the mean (keep
    // flexible bins available for future awkward items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space penalty: leftover after placement that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Aggressive 2-step lookahead: perfect match leaves exactly room for next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward for still being usable by the next item.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin, less aggressively late in stream.
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
        // If no open bin leaves room for the next item, new bin is less bad.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer tighter-than-average bins (best-fit flavor relative to mean residual).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize dead space, nonlinearly worse for small leftovers
        let pr = post_residual as f64;
        score += (bin_capacity as f64 - pr).max(0.0) * 0.15;
        if pr < 10.0 { score += 30.0; }
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // chain bonus proportional to tightness of chain fit
            score -= ((post_residual - next_item_size) as f64).min(20.0) * 0.5;
        } else {
            score += 15.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Time horizon: later in stream, prefer filling existing bins tighter
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;
    score += (post_residual as f64) * progress * 0.5;

    // Global state coupling: many open bins with high mean residual -> discourage new bins
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score += 50.0 + 40.0 * (1.0 - pressure.min(1.0));
        if open_bins_count == 0 { score -= 100.0; }
    } else {
        // Slight preference for bins with residual close to mean (balance load)
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear emphasis
    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, waste is penalized more heavily (quartic ramp)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * late * x * x;

    // Reward near-perfect fits via smooth gaussian-like term on x
    score -= 25.0 * (-(x * x) / 0.02).exp();

    // Penalize dead space that is too small for typical items (below half capacity),
    // smoothly: unusable slivers are worse than generous space
    let unusable = (0.5 - x).max(0.0);
    score += 30.0 * unusable * unusable;

    // Lookahead: if next item fits into post residual, reward this bin smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0) / cap;
        let tight = 1.0 - (nx / cap).min(1.0);
        score -= 15.0 * (1.0 - fits.min(1.0)) * tight;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - late);
    }

    // Mild pull toward bins deviating from mean residual (diversity of sizes),
    // scaled by number of open bins
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * (1.0 - late);

    // Slight preference for consolidating when many bins are open
    score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - x);

    // New-bin candidate: empty bin gets a smooth penalty that decays with progress
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: prefer small dead space classes.
    // Items 1..100 unknown distribution; treat residuals via integer division bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity wasted if bin closes here

    // Penalize large leftover fraction superlinearly (dead space).
    score += 40.0 * frac * frac;

    // Modulo-classes on post_residual: residuals that are "nice" (multiples of
    // common item sizes) are more likely to be filled later.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmonic_bonus += 8.0;
            }
        }
        // small residuals (<10) are nearly dead space
        if pr < 10 {
            harmonic_bonus -= 30.0;
        }
        score -= harmonic_bonus;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next fits but imperfectly: mild reward scaled by tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 30.0 * tight;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 10.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual mass.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, offset if open bins are crowded or
        // current item is huge (little to gain from squeezing).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 55.0 + 25.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            open_cost -= 20.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            open_cost -= 25.0; // existing bins nearly full anyway
        }
        score += open_cost;
    } else {
        // Prefer tighter existing bins slightly.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimize dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) == next {
            score -= 400.0; // perfect chain placement
        } else if (post_residual as f64) >= next {
            let slack = post_residual as f64 - next;
            score -= 150.0 * (1.0 - slack / 100.0); // next item fits: better the tighter
        } else {
            let gap = next - post_residual as f64;
            score += 30.0 * (gap / 100.0); // next item won't fit here: mild penalty
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 50.0 * dev;

    // Last-chance bonus: avoid opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let open_bonus = if open_bins_count > 0 { 60.0 + 5.0 * open_bins_count as f64 } else { -500.0 };
        score += open_bonus;
        // New bin is attractive only if no open bin gives a good fit.
        if item_size as f64 > mean_residual {
            score -= 80.0;
        }
    }

    // Late-stream tightening: be greedier as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: reward near-perfect fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // extra reward if next item fits *exactly-ish*
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            let overflow = (next_item_size as f64 - post_residual as f64).min(50.0);
            score += 0.15 * overflow;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when open bins could fit the item.
    if bin_residual == bin_capacity {
        // Base penalty for new bin, scaled by how many alternatives exist.
        if fitting_bins_count > 0 {
            score += 35.0 + 5.0 * (fitting_bins_count as f64).min(6.0);
        }
        // Early in the stream, new bins are cheaper (more future items to fill them).
        score -= 20.0 * (1.0 - progress);
        // If mean residual of open bins is large, prefer reusing them.
        score += 0.1 * mean_residual;
        // If the item is large and would leave a big hole in a fresh bin anyway,
        // soften the penalty slightly.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    } else {
        // Mild reward for consolidating into existing bins as bins accumulate.
        score -= 0.5 * (open_bins_count as f64).min(20.0) * (1.0 - progress);
    }

    // Global balance: prefer bins whose residual is near the mean (avoid
    // fragmenting one bin while others stay full).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Smooth non-linear coupling of post_residual with progress:
    // early on, waste is tolerable; late, tight fits matter more.
    let tightness_weight = 0.5 + 2.0 * progress * progress;
    let pr = post_residual as f64;
    score += tightness_weight * (pr * pr) / (bin_capacity as f64);

    // Reward near-perfect fits smoothly (bell-shaped around zero residual)
    let cap = bin_capacity as f64;
    let perfect = (-pr / (0.25 * cap)).exp();
    score -= 8.0 * perfect * (1.0 + progress);

    // Penalize leaving residual that matches next item poorly:
    // reward when post_residual is close to (but >=) next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 4.0 * (-gap / (0.2 * cap)).exp();
        } else {
            // residual too small for lookahead: smooth penalty
            score += 2.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // New-bin candidate handling: penalize opening a new bin when
    // alternatives exist, more strongly as stream progresses.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 6.0 + 10.0 * progress + 0.5 * open;
        if fitting_bins_count > 0 {
            score += 15.0 * (1.0 + progress);
        }
        // still allow opening when item is large and would leave tiny residual anywhere
        let fill_ratio = item_size as f64 / cap;
        score -= 5.0 * fill_ratio * fill_ratio;
    } else {
        // Reward bins that are already well-filled (low residual before placement)
        let pre_fill = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * pre_fill * pre_fill;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild pull toward bins with residual below the mean (compact bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev - 0.5 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification by capacity fractions.
    let pr = post_residual;
    // Perfect-fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Small unusable leftovers are dead space: penalize residuals that no item (>=1)
    // would fill usefully — but since min size is 1, weight by fraction of capacity.
    let frac = pr as f64 / cap;
    if frac < 0.15 {
        score += 25.0 * (0.15 - frac); // tight fit bonus region
    } else if frac > 0.5 {
        score += 10.0 * (frac - 0.5); // wasteful large leftover
    }

    // Modulo-class logic: residuals divisible into common item sizes are more reusable.
    if pr > 0 {
        let mut reusable = 0u32;
        for m in [10u32, 20, 25, 30, 40, 50].iter() {
            if pr % m == 0 {
                reusable += 1;
            }
        }
        score -= 8.0 * reusable as f64;
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
        } else {
            score += 5.0;
        }
        // Harmonic pair: item + next exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets a base premium so it is only
    // chosen when all alternatives look bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening fresh is more attractive when few bins are open or mean residual is low.
        score -= 3.0 * open_bins_count as f64;
        score += 0.1 * mean_residual;
        // Late in the stream, avoid spawning bins for tiny items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (small waste fraction).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins; the empty-bin candidate gets a surcharge.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 3.0;
        score += 15.0 + pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if next item cannot fit in post residual but would fit elsewhere
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill the fullest).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late-stream consolidation: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus (avoid opening new bin when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 20.0 + 0.5 * waste;
        // favor new bin if item is big relative to capacity
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 45.0;
        }
    }

    // Early stream: be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving residual that is too
            // small to be useful relative to the next item.
            let waste = (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
            score += 0.5 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty for consuming a scarce-good bin.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual below mean (consolidate small leftovers),
    // but avoid bins that are already very full if alternatives exist.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: early in the stream, keep bins flexible (penalize tiny residuals);
    // late in the stream, prioritize filling bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * tightness;
    score -= progress * 10.0 * tightness;

    // Penalize opening new bins when open bins can fit the item,
    // unless the item is large and post-residual would be very small.
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        let new_bin_bonus = 45.0 * (1.0 - tightness) - 10.0 * (open_bins_count as f64).ln().max(0.0);
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight fit reward: smooth polynomial coupling of post_residual with capacity
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap_f);
    score -= 30.0 * tightness * tightness * tightness;

    // Dead-space penalty: residual too small for the lookahead item is wasted
    if next_item_size > 0 {
        let dead = (next_item_size as f64 - post_residual as f64).max(0.0);
        let dead_frac = dead / cap_f;
        score += 60.0 * dead_frac * dead_frac * (1.0 + progress);
        // Reward if post_residual exactly accommodates the next item
        if post_residual == next_item_size {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: baseline score so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score = cap_f * 0.55;
        // Opening a new bin is cheap early, expensive late
        score *= 0.7 + 0.6 * progress;
        // If other bins fit, discourage opening a new one more strongly
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
        // Few open bins and large mean residual: reuse instead of opening
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0;
        }
        return score;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap_f;
    score -= 8.0 * dev;

    // Slight preference for bins in active use as stream progresses
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify residual capacity into capacity-fraction classes.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward placements that leave residual in "usable" harmonic classes
    // (residuals that common item sizes can still fill: >= 10..=80 range).
    if post_residual == 0 {
        score -= 100.0; // perfect fit, best possible
    } else if post_residual >= 10 && post_residual <= 80 {
        // Residual is itself a plausible future item size -> highly reusable.
        score -= 30.0 + 0.5 * (post_residual as f64);
    } else if post_residual < 10 {
        // Dead space: unusable sliver.
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    } else {
        // Residual > 80: large but wasteful chunk.
        score += 5.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more likely to be exactly filled.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 20 == 0 { score -= 4.0; }
    if pr % 25 == 0 { score -= 3.0; }
    if pr % 50 == 0 { score -= 5.0; }
    if pr % 10 != 0 && pr < 20 { score += 6.0; } // awkward small residual

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fill
        } else if next_item_size <= post_residual {
            score -= 0.3 * (next_item_size as f64);
        } else {
            // Next item won't fit here regardless; slight penalty for hoarding space.
            score += 0.1 * (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // New bin: residual after placing = 100 - item_size.
        // Penalize opening a new bin unless current item is large or
        // open-bin alternatives are poor (mean residual low relative to item).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0
            - 0.4 * item_size as f64
            + 0.3 * mean_residual
            - 20.0 * progress;
        if item_size >= 70 {
            score -= 30.0; // big items pair well with a fresh bin
        }
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
    } else {
        // Existing bin: mild reward for consolidating load.
        score -= 0.05 * open_bins_count as f64;
        // Prefer bins whose residual is close to item (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.15 * tightness;
    }

    // Integer-division threshold: item size class vs residual class harmony.
    let item_class = item_size / 10;
    let resid_class = if post_residual > 0 { post_residual / 10 } else { 0 };
    if item_class == resid_class && post_residual > 0 {
        score -= 10.0; // same decade: likely exact refill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == dead_threshold {
        // Leaves exactly room for the next item: excellent lookahead fit.
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward residual that can still accommodate the lookahead item.
        score -= 10.0;
    }

    // Tightness reward: filling a large fraction of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over spreading; when few are open, mild relief.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost, plus pressure so new bins are
        // only chosen when existing bins would create bad dead space.
        score += 25.0 + pressure * 8.0;
    } else {
        // Slight bonus for reusing an existing bin, stronger under pressure.
        score -= pressure * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: bins far above the mean residual are the
    // "loose" ones; prefer filling them to keep residuals homogeneous.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Early in the stream, be slightly more willing to open bins
    // (long horizon to use them); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 3.0;
    }

    score
}

