pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let dead = post_residual as f64;

    // Reward tight fits (post_residual small relative to capacity)
    score -= (1.0 - dead / bin_capacity as f64) * 30.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else if post_residual >= next_item_size {
            score -= 5.0; // next item can still use this bin
        }
    }

    // Penalize very loose fits
    if fit_ratio < 0.4 {
        score += (0.4 - fit_ratio) * 40.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins over opening new ones
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early in stream
        score += 20.0 + open_bins_count as f64 * 3.0 + (1.0 - progress) * 10.0;
        // Allow opening a new bin if item is large and existing residuals are small
        if item_size as f64 > mean_residual * 1.5 {
            score -= 30.0;
        }
    } else {
        // Prefer bins with residual close to mean (balance load)
        score += (bin_residual as f64 - mean_residual).abs() * 0.3;
    }

    // Late in stream: be more conservative, keep bins tight
    score += progress * 5.0;

