}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Quadratic waste penalty: large leftovers are disproportionately bad
    let norm_post = post_residual as f64 / cap;
    score += 0.8 * norm_post * norm_post * cap;

    // Tight-fit reward: subtract more when post_residual is tiny (smooth, non-linear)
    let tightness = 1.0 - norm_post;
    score -= 0.6 * tightness * tightness * tightness * cap;

    // Exact / near-perfect fit bonus (smooth exponential)
    if post_residual > 0 {
        score -= 12.0 * (-post_residual as f64 / 4.0).exp();
    } else {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Crowding pressure: when many bins are open, prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean-residual coupling: bins far below the mean residual are better targets
    // for large items; smooth polynomial interaction with progress.
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += (0.5 + 0.5 * progress) * dev * dev * cap;

    // Lookahead coupling: if the next item could exactly fill this bin's post
    // residual, reward strongly (smooth bell around the match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (-diff / 6.0).exp();
        // If next item cannot fit post residual at all, mild penalty for stranding space
        if (post_residual as f64) < next_item_size as f64 {
            score += 3.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // New-bin candidate: make empty bin moderately attractive only when current
    // fit is poor; otherwise open bins should win.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * norm_post) + 5.0 * (1.0 - progress);
        // If this is the only fitting option, opening a new bin is fine
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, discourage spreading into new bins
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residue 0) heavily rewarded
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows quadratically for small unusable residuals
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        }
        // Modulo-10 class: residuals that are multiples of 10 are "harmonic"
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division thresholds: reward residuals that can host common
        // harmonic item classes (multiples of 10)
        score -= (pr / 10) as f64 * 0.5;
    }

    // Fractional capacity coupling: prefer filling bins proportionally
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 10.0;

    // Lookahead: if next item fits the post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // harmonic match: next item leaves another multiple-of-10 residue
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize stranding residual the next item cannot use
        score += (post_residual.min(next_item_size.saturating_sub(1))) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (post_residual already does this)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin is tight
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        // but if existing bins would leave tiny dead space, new bin is better
        if bin_residual > item_size {
            let waste_if_forced = (bin_residual - item_size) % 10;
            if waste_if_forced < 5 && post_residual >= 40 {
                score -= 45.0;
            }
        }
        // late in stream, fewer bins is better: discourage new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mean residual coupling: if open bins are already loose, avoid spreading
    if mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 5.0;
    } else if mean_residual < 15.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Mild open-bin pressure: consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap that cannot hold even the smallest plausible item is pure waste.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0; // hard penalty for creating a tiny unusable gap
    }

    // Non-linear penalty on post_residual: small gaps are quadratic-bad,
    // large gaps are fine (room for future items).
    let pr = post_residual as f64;
    score += 0.6 * ((100.0 - pr) / 100.0).powf(2.0) * (100.0 - pr);

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize choices less when few bins.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure * (post_residual as f64 / 100.0);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // gap useless for the known next item
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // fits well (i.e., this call is the empty-bin call itself).
    if bin_residual == bin_capacity {
        // Slight bias so a well-fitting existing bin beats a new bin,
        // but a poor fit (large dead space) loses to a fresh bin.
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mean residual coupling: if the fleet of open bins is already tight on
    // average, prefer placements that preserve flexibility (larger post residual).
    score += (mean_residual - post_residual as f64) * 0.15;

    // Stream progression: late in the stream, be more aggressive about
    // filling bins tightly since fewer items remain to use slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post == 0 {
        score -= 60.0;
    } else if post <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let match_quality = (next_item_size as f64) / post; // closer to 1 = tighter
        score -= 30.0 * match_quality;
