        if next_item_size as u32 == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize dead space relative to next item.
        score += 0.35 * (post - (next_item_size as f64 - 1.0)).max(0.0);
    }

    // Penalize residuals far below mean residual (fragmented bin) mildly.
    score += 0.10 * (mean_residual - post).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; slightly reduced late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap + 5.0 - 3.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 5.0;
        }
    }

    // Mild penalty for too many open bins relative to stream length.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding: when many bins are open, discourage spreading; when few, allow it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.3 * crowding * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_capacity as f64 - mean_residual) < item_size as f64;
        if decent_fit_exists {
            score += 40.0; // penalize opening new bin when a fit exists
        } else {
            score -= 5.0; // slight preference for fresh bin over bad fits
        }
    }

    // Mild bonus for using bins with low residual (consolidation).
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, minimize post_residual aggressively (tight packs);
    // later, prefer mid-range residuals (keep flexibility).
    let shape = (1.0 - progress) * pr_norm * pr_norm + progress * (pr_norm - 0.5) * (pr_norm - 0.5);
    score += 8.0 * shape * cap;

    // Dead-space penalty: residual too small to be useful for typical items
    let dead = ((pr - 20.0).max(0.0) / cap).min(1.0);
    score -= 6.0 * dead * dead * (1.0 - progress);

    // Perfect fit reward
    if pr == 0.0 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 6.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 4.0 * gap * gap;
        if pr >= nxt {
            score -= 3.0;
        }
    }

    // Discourage opening new bins when many open bins already fit the item
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (5.0 + 2.0 * (open_bins_count as f64).sqrt()) * (0.5 + 0.5 * (1.0 - progress));

    // Mild alignment with mean residual: avoid outliers relative to fleet state
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Modulo classes of post_residual against common small-item sizes.
        // Leftovers divisible by small granularities are more reusable.
        let pr = post_residual;
        let mut reusability = 0.0;
        for m in [5u32, 10, 20, 25, 50] {
            if pr % m == 0 {
                reusability += 4.0;
            }
        }
        score -= reusability;

        // Integer-division threshold: leftover that can hold a "half bin" or more
        // is valuable; leftover below 10 is dead space.
        if pr >= bin_capacity / 2 {
            score -= 8.0;
        } else if pr < 10 {
            score += 6.0; // dead space penalty
        } else if pr < 20 {
            score += 2.0;
        }

        // Coupling with lookahead: does the leftover match next item's class?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 30.0; // next item fills this bin exactly
            } else if next_item_size < pr {
                // harmonic match: next item divides leftover into clean classes
                let rem = pr % next_item_size.max(1);
                if rem == 0 {
                    score -= 10.0;
                } else if rem <= 5 {
                    score -= 4.0;
                } else {
                    score += rem as f64 * 0.15;
                }
            } else {
                // next item cannot use this leftover: mild penalty scaled by gap
                score += (next_item_size - pr) as f64 * 0.1;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost of opening.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6
            + (open_bins_count as f64).sqrt() * 2.0
            - mean_residual * 0.1;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, prefer packing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Mild preference for tight bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Spread-awareness: when mean residual is high, exploit fullest bins.
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward scaled by leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 60.0 - (after_next as f64).min(60.0);
        } else {
            // Next item cannot use the residual: penalize dead space relative to next_item.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Penalize small unusable residuals (dead space threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Prefer bins with residual below mean residual (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are very tight.
    if bin_residual == bin_capacity {
        let tightness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        score += 400.0 * (1.0 - tightness);
        // If item is large relative to capacity, opening fresh bin is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 200.0;
    }

    // Late in the stream: consolidate, discourage opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tight * tight * item_size as f64;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits the post-residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // chain bonus: next item leaves a small remainder too
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to mismatch
            score += 0.5 * ((next_item_size - post_residual) as f64 / 10.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Crowding: when many bins are open, prefer reusing existing ones
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.3 * crowding;

    // Compare against mean residual: bins with below-average residual are tighter, prefer them
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (favor packing tight);
    // late in the stream, avoid opening new bins at all costs
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so late in the stream
        score += 25.0 + 40.0 * progress;
        // but if item is huge relative to mean residual, a fresh bin is fine
        if item_size as f64 > mean_residual + 10.0 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic waste penalty: dead space is superlinearly bad
    score += 0.9 * pr * pr / cap;

    // Smooth progress coupling: tighten packing later in the stream
    score -= (0.5 + 2.5 * progress) * (item_size as f64 / cap) * 20.0;

    // Reward tight fits via smooth inverse of post_residual
    if post_residual > 0 {
        score -= 30.0 * (cap / pr).ln().max(0.0);
    } else {
        score -= 40.0; // perfect fill
    }

    // Lookahead: favor residuals that can host the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.15 * gap;
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize fragmentation relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: mildly discourage unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveals
    // how "composable" the leftover space is for future items.
    let pr = post_residual;
    let mod4 = (pr % 4) as f64;
    let mod10 = (pr % 10) as f64;
    let mod25 = (pr % 25) as f64;

    // Penalize residuals that are awkward (non-divisible into common item sizes).
    score += 0.35 * mod4 + 0.15 * mod10 + 0.08 * mod25;

    // Integer-division thresholds: residuals in "harmonic bands".
    let band = pr / 25; // 0..4
    score += match band {
        0 => 8.0,                 // tiny dead space is nearly unusable
        1 => 2.0,                 // fits small items
        2 => 0.0,                 // sweet spot
        3 => -1.5,                // large usable space, good
        _ => -2.5,                // near-empty bin, very flexible
    };

    // Exact harmony: post_residual divisible by common item sizes is valuable.
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 3.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits harmonically into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && pr >= next_item_size {
        let next_post = pr - next_item_size;
        score -= 4.0;
        if next_post % 10 == 0 || next_post % 25 == 0 {
            score -= 3.0;
        }
        // Chain fit: next item leaves space for a third typical item.
        if next_post >= 10 {
            score -= 1.5;
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // Next item cannot use this leftover: penalize proportionally.
        score += 0.05 * (next_item_size - pr) as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; becomes attractive only if mean residual is low.
        score = 55.0 - 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins overall.
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= ~12) are effectively unusable.
    if post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item can't use the gap -> dead space risk
            score += (post_residual as f64) * 0.15;
        }
    }

    // Pressure from number of open bins: discourage spreading when many
    // bins are open, encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Make the empty bin attractive only for
    // large items (perfect-ish fits) or when all fits would be terrible.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // = capacity - item_size
        if waste < 20 {
            score -= 20.0; // large item nearly fills a fresh bin
        } else if fitting_bins_count == 0 {
            score -= 15.0; // no alternative
        } else {
            score += 30.0 + waste * 0.3; // keep using open bins
        }
    }

    // Slight stream-progression tilt: late in the stream, prefer filling
    // existing bins ever more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            score -= 60.0; // perfect chain fit
        } else if diff > 0.0 && diff <= 20.0 {
            score -= 0.9 * (20.0 - diff); // next item fits well
        } else {
            // next item too big or leaves big gap: mild penalty
            score += 0.15 * diff.abs().min(cap);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose post_residual is close to (or below) the mean,
    // keeping residuals homogeneous for future fits.
    score += 0.4 * (pr - mean_residual).abs();

    // Last-chance bin: strongly reward using the only fitting bin to avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 30.0 - 40.0 * fill;
        if next_item_size > 0 && (next_item_size as f64) > pr * 0.9 {
            score -= 20.0; // reserve fresh bin for big next item
        }
    }

    // Late in stream: prefer tighter packing, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    let min_item = 1.0f64;
    if post < min_item {
        score += 50.0;
    } else {
        // Non-linear waste curve: small usable leftovers are fine, mid-range leftovers are worst.
        let frac = post / cap;
        score += 12.0 * frac * (1.0 - frac) * 4.0; // peaks at half-empty
    }

    // Lookahead: reward bins whose post residual still fits the next item (chaining),
    // penalize when next item is stranded.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item fits here afterwards: good chaining, stronger early when bins are scarce
            score -= 4.0 + 6.0 * (1.0 - progress);
        } else if bin_residual >= nxt && post < nxt {
            // we consumed the only space the next item needed
            score += 6.0;
        }
        // bonus if post residual exactly matches next item
        if (post - nxt).abs() < 0.5 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item fits poorly everywhere
        // (post residual large relative to capacity) or many bins already open.
        let poor_fit_elsewhere = post / cap; // = 1 - item/cap for empty bin
        score = post + 30.0 * (1.0 - poor_fit_elsewhere) + 5.0 * open_bins_count as f64;
        // Late in the stream, avoid spawning bins; consolidate.
        score += 20.0 * progress;
        // If item is large, a fresh bin is natural (perfect fit potential).
        if item / cap > 0.6 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates from mean (harmonize with global state):
        // bins already tighter than average get slight preference to consolidate.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= 3.0 * dev;
    }

    // Global pressure: when many open bins exist, discourage spreading; favor tight fills.
    score += 0.5 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Core: quadratic penalty on wasted residual (smooth, convex).
    let mut score = norm_pr * norm_pr;

    // Cubic term: strongly punish near-empty leftovers late in the stream.
    score += 0.5 * norm_pr * norm_pr * norm_pr;

    // Non-linear coupling of residual with stream progress:
    // waste matters more as the stream advances (packing hardens).
    let progress_coupling = (progress * (1.0 - progress) * 4.0).sqrt(); // peaks mid-stream
    score += 0.8 * norm_pr * (1.0 + progress_coupling);

    // Reward tight fits: subtract a smooth bump when post_residual is small.
    let tightness = (1.0 - norm_pr).max(0.0);
    score -= 1.2 * tightness * tightness * norm_item;

    // Lookahead: if the next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = norm_next / (norm_pr + 1e-6);
        score -= 0.6 * (chain_fit.min(1.0)) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + norm_pr);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    // (post_residual in existing bins would be large) or many bins are open.
    if bin_residual == bin_capacity {
        let escape_bonus = 3.0 * (norm_item * norm_item) * (1.0 + progress);
        score += 2.5 + escape_bonus - 0.02 * open_bins_count as f64;
        // If item is large and would leave big residual elsewhere, new bin looks better.
        score -= 1.5 * norm_item * progress;
    }

    // Mild pull toward bins with residuals close to the item (best-fit flavor, smooth).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 0.3 * fit_gap * fit_gap;

    // Small regularization tied to mean residual: prefer bins below mean residual
    // (pack fuller bins first), smoothly.
    score += 0.2 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exponential bonus as post_residual approaches 0.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= 60.0 / (post_residual as f64).powf(0.7);
    }

    // Harmonic class of post_residual (mod 10): residuals that are multiples
    // of 10 are "usable" slots for typical item sizes; odd/prime remainders
    // are dead space. Penalize non-multiple-of-10 residuals.
    let class = post_residual % 10;
    score += match class {
        0 => -8.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        _ => 0.5 * class as f64,
    };

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64 / bin_capacity as f64) * 12.0;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / 20.0).min(10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // item leaves a very clean residual or existing bins are very full.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        let mut new_score = 55.0; // baseline cost of a fresh bin
        new_score -= fill * 40.0; // big items justify new bins
        if item_size % 10 == 0 {
            new_score -= 6.0; // item leaves harmonic residual
        }
        if open_bins_count == 0 {
            new_score -= 100.0; // no alternative
        }
        // As stream progresses and open bins are on average full, new bins OK.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_score -= progress * 5.0;
        new_score += (mean_residual / bin_capacity as f64) * 15.0;
        score = score.max(new_score);
        score = new_score.min(score.max(new_score)); // keep new-bin score distinct
        score = new_score;
        return score;
    }

    // Prefer filling bins that are already relatively full (small residual
    // before placement), keeping large-residual bins for larger future items.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild penalty for having many open bins: consolidate when possible.
    score += (open_bins_count as f64).sqrt() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small gaps unlikely to fit future items (min size ~1..100 unknown,
    // so weight gaps below a soft threshold heavily).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Nonlinear dead-space: gaps that are "too small to be useful" cost extra.
        let dead_thresh = 30.0;
        if gap < dead_thresh {
            score += (dead_thresh - gap) * 3.0;
        }
        // Fragmentation pressure: heavily penalize leaving moderate gaps when bin is nearly full.
        if gap <= 10.0 {
            score += 60.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else if post_residual > 0 {
            // gap wasted relative to next item
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via this term only applying to open bins).
    if bin_residual < bin_capacity {
        score -= 10.0 + 2.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize more when many bins already open.
        score += 5.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Reward bins that are already tight relative to mean residual.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item fills bin exactly with next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item cannot fit here: the leftover is dead space relative to lookahead.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize unusable small remnants (below minimum plausible item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill now
    }

    // Prefer bins whose residual deviates favorably from the mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): moderate default so only clearly bad fits open new bins.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.2 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with a large follow-up item
        }
    }

    // Slight preference to fill older/more crowded bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: squared waste penalty
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual matches the next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space unusable by the known next item
        score += 8.0 * post_residual as f64 / 100.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 60.0 || fitting_bins_count == 0;
        score += if poor_fit { 5.0 } else { 120.0 + 40.0 * progress };
        // toward stream end, opening bins is safer (no future to amortize)
        if progress > 0.85 { score -= 30.0; }
    }

    // Prefer filling bins that deviate from mean residual (balance consolidation)
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for fewer open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly scaled
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; late, tighten fits aggressively
    let coupling = 1.0 + progress * progress * (3.0 - 2.0 * progress);
    score *= coupling;

    // Reward bins that can also fit the next item (lookahead chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.35 * next_item_size as f64 * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild scarcity pressure
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Penalize opening a new bin when open bins exist and mean residual is high
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.4 * (1.0 + progress);
    }

    // Slight preference for bins with residual close to item size (smooth term)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += diff * diff * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues near capacity multiples
    // of 10 are "harmonic" (reusable by typical items); tiny residues are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let harmonic = (post_residual % 10) as f64;
    let dead = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    score += dead + harmonic * 0.8;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 8.0;
        }
        // Harmonic class of next item: if next item leaves a harmonic residue too,
        // chain-fitting is likely; slightly boost reward.
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong penalty to open new bins only when truly needed.
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // New-bin candidate: empty bin should only win when current bins are crowded
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        score = cap * 0.55
            + (open_bins_count as f64) * 1.5
            - mean_residual * 0.4
            + (post_residual as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mild preference for bins already below mean residual (balance avoidance of
    // fragmenting the fullest usable bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically small gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize leaving gaps that cannot fit the next item when it would otherwise fit well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward tight fits (small post_residual) relative to mean residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    score -= mean_residual * 0.05;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if post_residual exactly accommodates next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless all fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.1;
        if fitting_bins_count == 1 {
            score -= 30.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled slightly.
    score *= 1.0 + 0.01 * (item_size as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step chain: bin becomes exactly reusable
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how close the next item comes to filling the remainder
            let tightness = 1.0 - slack / bin_capacity as f64;
            score -= 20.0 * tightness * tightness;
        } else {
            // next item cannot fit here: penalize leftover that is too small to be useful
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 25.0 * (10.0 - dead); // tiny unusable dead space
            } else {
                score += 0.05 * dead; // mild penalty for large leftovers
            }
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is huge
    // relative to residual of open bins, i.e., only open new bins for poor fits.
    if bin_residual == bin_capacity {
        // neutral base cost of a fresh bin; rises when open bins are plentiful and roomy
        let openness = open_bins_count as f64;
        let mean_room = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - item_size as f64;
        score += 8.0 * openness.max(1.0).ln() * (0.5 + mean_room);
        // but if the item is large and would leave a huge awkward remainder in any bin,
        // a fresh bin is fine
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: strongly reward bins whose post_residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize creating residual too small for the next item (dead space risk).
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: just minimize residual.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Penalize opening new bins when good open bins exist (mean residual is high).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / bin_capacity as f64;
        // New bin is fine if mean residual across open bins is small (they're all nearly full).
        score += 25.0 + 40.0 * pressure * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if mean residual is very small, opening a bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Slight preference for reusing bins over opening new ones.
        score -= 8.0;
        // Prefer bins with residual close to item (minimize leftover fragmentation).
        let frag = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * frag * frag;
    }

    // Late in the stream, be more aggressive about filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;

    // Mild penalty for bins that leave residual in awkward zone (1..10 unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild quadratic penalty on waste; late: stronger quartic penalty
    // since leftover space is less likely to be filled later.
    let poly = pr * pr / (cap * cap) * (1.0 + 3.0 * progress) + pr * pr * pr * pr / (cap * cap * cap * cap) * (6.0 * progress);
    score += poly * cap;

    // Reward tight fits: subtract a smooth bell-shaped term centered at zero post_residual.
    let tight = (-(pr / cap).powi(2) * 8.0).exp();
    score -= 12.0 * tight;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly;
    // smooth interaction term rather than a hard piecewise rule.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs() / cap;
        score -= 10.0 * (-(gap * gap) * 6.0).exp();
        // Penalize if post_residual is awkwardly larger than next item (dead space).
        if pr > nx {
            score += 0.5 * (pr - nx) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // existing bins fit and mean residual is healthy.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 30.0 + 5.0 * fit_pressure + mean_residual * 0.2 * (1.0 - progress);
    } else {
        // Reward using bins whose residual is close to the item (good density).
        let density = item_size as f64 / bin_residual.max(1) as f64;
        score -= 4.0 * density;
        // Mild penalty for spreading across too many bins late in the stream.
        score += 0.05 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A post_residual that cannot host even the smallest plausible item is wasted space.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // unusable sliver
    } else if (post_residual as f64) < 25.0 {
        score += 15.0; // likely dead space for most item sizes
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize blocking the next item into a near-miss gap.
        if post_residual as f64 >= next_item_size as f64 * 0.7 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins
    // and prefer filling existing ones; when few bins are open, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open,
        // and when current mean residual still has room.
        score += 25.0 + 10.0 * pressure + 0.3 * mean_residual;
        // But if no existing bin fits well, allow opening (softened).
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Existing bin: slight reward under pressure to consolidate.
        score -= 3.0 * pressure;
        // Prefer bins whose residual is below mean (fill the emptier-tail bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, favor packing into
    // existing bins harder to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here afterwards: good chaining.
            let chain_waste = post_residual - next_item_size;
            score -= 100.0 - (chain_waste as f64).min(100.0);
        } else {
            // Next item cannot fit in the leftover: penalize proportionally to the mismatch.
            let mismatch = next_item_size - post_residual;
            score += (mismatch as f64) * 1.5;
        }
    }

    // Prefer bins that are already fairly full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 50.0;

    // Penalize bins far from the mean residual (avoid fragmenting many bins evenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // relative to capacity or all open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive when existing bins are congested
        // or the item is big and would leave awkward leftovers elsewhere.
        let new_bin_bonus = 80.0 * avg_fill + 60.0 * item_ratio - 40.0;
        score += 200.0 - new_bin_bonus.max(0.0);
        // If the item is huge, a fresh bin is often the best home.
        if item_ratio > 0.7 {
            score -= 150.0;
        }
    }

    // Mild late-stream urgency: consolidate toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * fill_ratio;

    // Slight penalty for spreading across many open bins.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential decay of wasted space
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving residuals that are too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit here; mild penalty for large dead space
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let base_penalty = 15.0;
        let scarcity_bonus = if fitting_bins_count == 0 { -50.0 } else { 0.0 };
        // open new bin more readily when open bins have high mean residual
        score += base_penalty + scarcity_bonus - 0.15 * mean_residual;
    }

    // Prefer filling bins with many open bins (bin consolidation pressure)
    score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time horizon: early stream, be conservative with space; late stream, pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = (post_residual as f64 / cap).clamp(0.0, 1.0);
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear dead-space penalty: quartic in normalized residual
    score += 18.0 * x * x * x * x;

    // Tight fit reward: strong discount when post_residual is small
    score -= 22.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Stream progress coupling: late in the stream, waste hurts more
    score += 10.0 * progress * x * x;

    // Coupling with mean residual: avoid bins that deviate badly from fleet state
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead: if the next item fits the post residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for proliferation of open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: quantize post_residual into
    // capacity-fraction buckets and reward residuals likely to be reusable.
    let pr = post_residual as f64;
    let class = (pr / 10.0).floor(); // 0..=10 harmonic classes
    score -= 6.0 * (class / 10.0);

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 unknown,
    // but small residuals are risky). Modulo-style coupling: residual that is NOT a divisor-like
    // fraction of capacity is less useful.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use the leftover: mild penalty scaled by leftover size
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0 + 0.1 * (post_residual as f64).min(50.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // bin is very full (tiny residual) or fit is poor.
    if bin_residual == bin_capacity {
        // brand-new bin: baseline score is the full capacity minus item
        score = (bin_capacity - item_size) as f64;
        // discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // open new bins early in stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count > 4 {
            score += (open_bins_count as f64 - 4.0) * 2.0;
        }
    } else {
        // Reward filling bins tighter than the current mean residual suggests.
        if pr < mean_residual {
            score -= (mean_residual - pr).min(30.0);
        } else {
            score += (pr - mean_residual).min(30.0) * 0.3;
        }
    }

    // Harmonic modulo bonus: residuals that are multiples of common item-size
    // classes (10/20/25/50) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 6.0; }
    }

    // Small penalty for leaving residual exactly in the awkward 11..19 band.
    if (11..=19).contains(&post_residual) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. A residual is "dead" if no plausible future
    // item (sizes 1..=100, unknown distribution) can comfortably use it.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Lookahead coupling: penalize leaving a gap that the next item ALMOST
    // fits but not quite (frustrated fit = pure dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward reserving space for the next item, scaled by how snug it is.
            let snug = (post_residual - next_item_size) as f64;
            score -= (next_item_size as f64) * 1.5 - snug * 0.3;
        } else if next_item_size > post_residual {
            let frustration = (next_item_size - post_residual) as f64;
            if frustration <= 10.0 {
                score += frustration * 2.0; // near-miss gap is likely wasted
            }
        }
    }

    // Tightness reward: smaller post_residual relative to item_size is better.
    score -= (item_size as f64) * 0.4;

    // Open-bin pressure: discourage spreading across many bins when a decent
    // fit exists; encourage closing out nearly-full bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress * 2.0) * 0.5;

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the fleet mean (larger-than-mean residual bins absorb big items;
    // smaller-than-mean bins get filled out to completion).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no good fit exists. Give the empty bin a moderate baseline so it wins
    // only when open-bin scores are high (bad fits / dead space).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // Early stream: be more willing to open bins (stock up capacity).
        if progress < 0.3 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_ratio = next_item_size as f64 / post_residual as f64;
        // Prefer chains where next item fills most of the remaining space.
        score -= 40.0 + 60.0 * next_fit_ratio;
        if post_residual == next_item_size {
            score -= 150.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use.
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.3 * gap;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // filling them is good; bins far above mean waste potential.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless item is huge
    // relative to residual or stream is early and bins are few.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 60.0 * tightness - 30.0 * (1.0 - progress);
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            score -= 90.0; // fresh bin can host a perfect 2-item pair
        }
    }

    // Mild preference for consolidating into fewer bins as stream matures.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // If next item does NOT fit here, mildly penalize wasting a large residual.
    if next_item_size > post_residual {
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }
    // Many fitting bins: prefer the tightest among them; add small penalty to spread pressure.
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Penalize opening a new bin when decent open capacity exists globally.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 22.0 * urgency;
        // New bin is more attractive late in stream when open bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 6.0; // next item won't fit after placing here anyway; fresh bin keeps options
        }
    } else {
        // Prefer bins whose residual is below mean (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild time-horizon coupling: early on, be slightly conservative about filling bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: reward tight fits more strongly as stream progresses
    let fill = 1.0 - pr / cap; // fraction of bin filled after placement
    let fill2 = fill * fill;
    score -= fill2 * (1.0 + progress) * 12.0;

    // Penalize small-but-nonzero residuals (dead space), smoothly
    let dead = (pr / cap) * (1.0 - pr / cap);
    score += dead * 20.0;

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 + 6.0 * (pr - next_item_size as f64) / cap;
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 6.0;

    // New-bin candidate: penalize opening a bin when good fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into coarse "usable slots" for typical item sizes.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Dead space penalty: residuals below the smallest item class are wasted.
    if post > 0 && post < 10 {
        score += 60.0;
    }

    // Harmonic class reward: post_residual divisible by common item sizes
    // (10, 20, 25, 50) is reusable; reward perfect class matches.
    let mut class_bonus = 0.0;
    for m in [10i64, 20, 25, 40, 50] {
        if post % m == 0 {
            class_bonus += 8.0 * (m as f64 / 50.0);
        }
    }
    score -= class_bonus;

    // Slot count: how many mid-size (25) items still fit; more slots = better bin.
    let slots = post / 25;
    score -= 6.0 * slots as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == post {
            score -= 45.0;
        } else if nxt <= post {
            // next fits but leaves another residual: mild reward scaled by harmony
            let rem = post - nxt;
            if rem % 10 == 0 { score -= 15.0; } else { score -= 5.0; }
        } else {
            // next item won't fit here: penalize proportional to wasted potential
            score += 10.0 + 0.15 * (nxt - post) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only attractive when
    // open bins are fragmented (low mean residual) or many bins open.
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.55
            + 0.5 * open_bins_count as f64
            - 0.8 * (mean_residual.max(0.0))
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        if next_item_size > 0 && (next_item_size as i64) <= cap {
            score -= 5.0; // fresh bin trivially fits the next item too
        }
    }

    // Slight preference for tighter fits overall (low post_residual relative to cap).
    score += 0.1 * (post as f64 / cap as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // minimum plausible item are essentially wasted capacity.
    let min_item = 1u32;
    if post_residual < min_item.max(0) {
        score += 1000.0;
    }
    // Hard dead zone: gaps below the smallest typical item (1..10 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // moderate dead space: hard for future items to exploit
        score += 25.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact match with lookahead item: strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If lookahead item can still fit in the resulting gap, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // lookahead cannot use the gap: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate gets penalized progressively.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far below the mean (i.e., consolidating
    // space into fewer, emptier bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect 2-step completion: this bin gets exactly filled next step.
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Closer gap = better chance next item fits; penalize proportionally.
            score += 0.25 * gap;
            // Bonus if next item leaves a near-full bin afterwards.
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit in this bin after placement: mild penalty scaled by overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Compare post_residual against mean residual of open bins.
    if mean_residual > 0.0 {
        let rel = (post_residual as f64) / mean_residual;
        if rel < 0.5 {
            // Creating much less residual than average: good compaction.
            score -= 8.0 * (0.5 - rel);
        } else if rel > 1.5 {
            // Leaving excessive residual relative to fleet: dead-space risk.
            score += 6.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        let best_possible = post_residual as f64;
        score += 25.0 + 0.5 * best_possible;
    }

    // Slight late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Small penalty for any wasted residual to break ties toward fuller bins.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: post_residual quality weighted by stream progress.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual (smooth interaction).
    score += 0.6 * (pr - mean_residual).abs() + 0.4 * (pr - mean_residual);

    // Reward filling a bin almost perfectly.
    if pr == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving room for the next item (smooth fit term).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0) / cap;
        let fit = if pr >= nx { 1.0 - slack } else { -1.0 };
        score -= 8.0 * fit * (1.0 - progress);
        // Perfect pairing: next item exactly fills leftover.
        if (pr as u32) == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate: mild penalty, growing with number of open bins and progress.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But allow opening when item is large and nothing fits well.
        score -= 0.15 * item_size as f64;
    }

    // Discourage spreading across many bins when residuals are large.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/2, 1/3, 1/4 of C)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Penalize dead space that is too small to fit typical items.
    if post_residual > 0 && post_residual < quarter {
        score += (quarter - post_residual) as f64 * 2.5; // unusable sliver
    }

    // Reward tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 12.0;
    }

    // Harmonic pairing: if the next item fits exactly in the post-residual,
    // this placement is perfect — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_class = if next_item_size > half { 3 } else if next_item_size > third { 2 } else { 1 };
        let resid_class = if post_residual > half { 3 } else if post_residual > third { 2 } else { 1 };
        if next_class == resid_class {
            score -= 18.0; // same harmonic class: likely good chaining
        }
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize more if we waste a scarce bin.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item-size classes (multiples of 10-ish chunks) are more reusable.
    let chunk = bin_capacity / 10;
    if post_residual % chunk == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Integer-division threshold: bins whose residual falls in the "middle band"
    // (between third and half) are flexible — slight reward.
    let band = post_residual / third;
    if band == 1 {
        score -= 3.0;
    } else if band >= 2 && post_residual > half {
        score += 2.0; // large residual is fine elsewhere (new bin keeps it)
    }

    // New-bin candidate handling: opening a fresh bin is good when the item is
    // large (harmonic class 3) and few bins are open; bad for small items.
    if bin_residual == bin_capacity {
        let item_class = if item_size > half { 3 } else if item_size > third { 2 } else { 1 };
        match item_class {
            3 => score -= 20.0,  // big items deserve fresh bins
            2 => score += 4.0,
            _ => score += 14.0,  // don't waste a bin on tiny items
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 1.5;
    }

    // Mean residual coupling: if open bins are generally loose, prefer filling them.
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else if bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small gaps (below min item size 1..100) are hard to reuse.
    // Treat post_residual < item_size threshold region: gap unusable if smaller than
    // the smallest plausible future item. Penalize proportionally to "wastedness".
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let min_useful = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < min_useful && post_residual > 0 {
        // gap too small to ever be refilled: heavy penalty
        score += 400.0 * (1.0 - post_residual as f64 / min_useful.max(1.0));
    }

    // Moderate gaps (below half capacity) are semi-dead: mild penalty scaled by progress.
    if post_residual > 0 && (post_residual as f64) < bin_capacity as f64 * 0.5 {
        score += 30.0 * progress;
    }

    // Reward leaving a gap that exactly fits the next item (lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Penalize leaving a gap that can't fit the next item while it could otherwise fit here.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 2.0;

    // Reward bins with residual below mean (tighter bins get priority).
    score -= (mean_residual - post_residual as f64) * 1.5;

    // New-bin candidate logic: only attractive when all open bins fit poorly
    // (large dead space would result) or no bins fit well.
    if bin_residual == bin_capacity {
        let base_penalty = 250.0 + 150.0 * progress;
        // If this is the only fitting option, new bin is fine.
        if fitting_bins_count <= 1 {
            score = base_penalty - 200.0;
        } else {
            // Compare: opening new bin wastes (capacity - item) immediately;
            // penalize unless item is large relative to capacity.
            score = base_penalty + (bin_capacity - item_size) as f64 * 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly/tightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 50.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize dead space.
        score += 30.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins with residual near/below mean (tighter bins).
    score -= 10.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it moderately attractive only when the item is large
    // or the current bin would leave a very awkward leftover.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) < (next_item_size as f64) && next_item_size > 0;
        if awkward && post_residual > 0 {
            score -= 20.0; // opening a fresh bin better than awkward leftover
        } else {
            score += 25.0; // default: prefer reusing open bins
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Penalize large dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize wasted potential slightly
            score += 4.0;
        }
    }

    // Prefer bins with residual above the mean (balance residuals across bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Discourage opening new bins when many open bins exist with room.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 30.0;
        // More acceptable early in the stream or when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // If item is large and few fitting bins, new bin is more attractive.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Slight preference for filling fuller bins (best-fit flavor) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty on wasted residual, growing with stream progress
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth coupling
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Lookahead: penalize leaving residual that fails to host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr - nxt).abs() / cap;
        score += 12.0 * usable * (1.0 - (pr / nxt.max(1.0)).min(1.0));
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (mean_residual / cap).max(0.0);
        score = cap + 10.0 * crowd - 15.0 * (1.0 - crowd) * progress;
        if fitting_bins_count == 0 {
            score -= cap;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover matches "useful" residue classes
    // (small remainders that pair well with typical small items) get rewarded.
    let pr = post_residual;
    let pr_mod_10 = (pr % 10) as f64;
    // Residue 0 (perfect fit) is best; residues 1..=3 are decent; large residues (7..9) waste.
    score -= (10.0 - pr_mod_10) * 0.8;
    if pr == 0 { score -= 25.0; }
    if pr_mod_10 == 0.0 && pr > 0 { score -= 6.0; }

    // Integer-division threshold: leftover >= next item size is valuable (lookahead pairing).
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // Harmonic check: can next item divide the leftover into clean chunks?
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 8.0;
        }
    }

    // Capacity fraction classes: bins with residual in "half" or "third" bands are flexible.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    if pr >= half { score -= 4.0; }
    else if pr >= third { score += 2.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are terrible
    // (post_residual creates unusable sliver < 10) or lookahead won't pair.
    if bin_residual == bin_capacity {
        score = 55.0 - (pr_mod_10 * 0.0);
        if next_item_size > 0 && next_item_size >= 10 {
            // fresh bin can host next item too; mild preference when current fit is bad
            score -= if pr < 10 { 10.0 } else { 0.0 };
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // Many open bins with high mean residual: discourage new bins.
        score += (open_bins_count as f64).sqrt() * 2.0;
        if mean_residual > 30.0 { score += 6.0; }
    }

    // Penalize leaving slivers below minimum item size (unusable dead space).
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Mild tie-break: prefer fuller bins (smaller residual) among equals.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer bins whose post_residual is either 0 (perfect fit) or large enough to be reusable.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual >= 10 {
        score += post_residual as f64 * 0.5;
    } else {
        // Unusable dead space: tiny gap < 10 (or < min item size under unknown distribution)
        score += post_residual as f64 * 0.5 + 50.0;
    }

    // Reward tight fits: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only if no open bin
    // fits well (post_residual would be dead space) and the next item is large.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is large (reusable).
        score = bin_capacity as f64 * 0.5;
        // Prefer new bin if next item is big and this item would leave dead space elsewhere.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Lookahead: if next item exactly matches this bin's post_residual, reward keeping it.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 25.0;
    }

    // Slight nudge toward bins with residuals above the mean (keeps balance).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring dead space penalizes large leftovers super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            let next_leftover = post_residual - next_item_size;
            score -= 30.0 - (next_leftover as f64).min(30.0); // next item fits, leftover small is better
        } else {
            // next item cannot fit: dead space risk grows with how close it is
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight bins;
    // placing here when mean is large suggests we're consolidating well.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let ratio = res_f / mean_residual;
        if ratio < 1.0 {
            score -= 10.0 * (1.0 - ratio); // tighter-than-average bin favored
        } else {
            score += 5.0 * (ratio - 1.0); // looser-than-average bin mildly penalized
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is huge
    // relative to the residual (poor fit everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; the penalty shrinks for big items.
        score += 45.0 * (1.0 - fill_ratio);
        if step_index == 0 {
            score -= 100.0; // first item must open a bin
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, avoid opening new bins even harder (waste minimization).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Penalize creating residual space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize bins that will leave a dead sliver relative to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // Global pressure: many open bins -> discourage opening new bins.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 15.0 + pressure * 3.0;
        // But allow new bins early when mean residual is low (fragmented state).
        if mean_residual < 15.0 && progress < 0.3 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (above-average space used).
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // Mild bonus for large items into large-residual bins.
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth interaction: dead space penalty grows with progress
    let dead = prn * prn * (0.5 + 1.5 * p);
    score += 40.0 * dead;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tight = (1.0 - prn).powi(3);
    score -= 25.0 * tight * (0.6 + 0.4 * p);

    // Lookahead coupling: penalize if next item cannot use the residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 10.0 + 15.0 * prn * (0.5 + p);
    } else if next_item_size > 0 {
        // reward if next item fits nicely into the post residual
        let gap = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - gap / cap).powi(2);
    }

    // Last-chance bin bonus: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - prn);
    }

    // Mild penalty relative to mean residual: avoid leaving bins far above average
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues are "harmonically dead"
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Perfect-fit reward: post_residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize dead space: residues below the minimum item size are unusable.
        if post_residual < 10 {
            score += 60.0;
        }
        // Modulo classes on post_residual (capacity = 100): residues that are
        // multiples of 10 are "harmonic" and more likely reusable by future items.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // Integer-division thresholds: half/full-capacity classes are attractive.
        if post_residual >= bin_capacity / 2 {
            score -= 8.0;
        } else if post_residual >= bin_capacity / 4 {
            score -= 3.0;
        } else {
            score += 6.0;
        }
        // Quadratic waste penalty on tiny unusable fractions.
        if frac < 0.15 {
            score += (0.15 - frac) * 200.0;
        }
    }

    // Lookahead coupling: reward if next item fits into the post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Harmonic match: next item exactly fills the residue.
            if next_item_size == post_residual {
                score -= 25.0;
            }
            // Modulo harmony between next item and residue class.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin has large residual; penalize it
    // mildly unless current bins have poor (small) mean residual.
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual < 20.0 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with residual close to item_size (tight fit) using a
    // harmonic distance term.
    let tight = (bin_residual - item_size) as f64;
    score += tight * 0.15;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps are hard to fill later.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + 4.0 * (12 - post_residual) as f64;
    }
    // Mid-range gaps are moderately wasteful; large gaps stay usable.
    if post_residual >= 12 && post_residual < 30 {
        score += 0.5 * (post_residual as f64 - 12.0);
    }

    // Reward tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; large residual looks good but must pay opening cost.
        score += 30.0;
        // If the next item is large and this item is small, a fresh bin is safer.
        if next_item_size > 60 && item_size < 40 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual is close to the mean (balanced packing),
        // unless this is a near-perfect fit.
        let dev = (bin_residual as f64 - mean_residual).abs();
        if post_residual > 5 {
            score += 0.15 * dev;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 5 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize leaving a gap just above the next item (awkward fit).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 8 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use the remainder.
        score += 15.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize residuals far below the mean (this bin is unusually full already;
    // prefer spreading load if other bins are emptier).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild penalty for opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = post_residual as f64;
        score += 25.0 + 0.2 * waste;
        // But if the item is large and would leave tiny residue, new bin is fine.
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    // Early-stream exploration: slightly favor reusing bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else if dead < 30.0 {
            score += 0.35 * (30.0 - dead);
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, keep best-fit pressure
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for exact chain: post_residual close to next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // penalize leaving a residual that just barely misses the next item
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 15.0 {
                score += 0.6 * miss;
            }
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Global state: if mean residual across open bins is high, discourage spreading;
    // prefer compacting into existing bins when they already have room.
    if mean_residual > item_size as f64 {
        score += 0.0;
    } else {
        score += 3.0 * (item_size as f64 - mean_residual) / cap;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Penalize the empty bin moderately, but relax the
    // penalty if the item is large relative to capacity (few bins can host it anyway).
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / cap).powi(2) * 45.0;
        score += 35.0 - large_item_bonus;
        // early in the stream, new bins are cheap; later, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // many open bins with room => discourage opening yet another
        score += 1.5 * (open_bins_count as f64).min(20.0);
    }

    // Small tie-break noise-free nudge toward bins with more residual headroom overall.
    score += 0.05 * (bin_residual as f64 - item_size as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual). Late: tolerate larger residuals
    // slightly since consolidation pressure rises.
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    let coupling = pr * (0.35 * prog_sq + 0.55 * prog_cu) - 0.15 * progress;
    score += coupling;

    // Reward filling bins nearly full (post_residual small relative to capacity).
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * fill;

    // Penalize residuals that are unusable dead space (small but nonzero).
    let dead = (pr / cap) * (1.0 - pr / cap);
    score += 8.0 * dead * dead;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted potential.
        score += 3.0 * (next_item_size as f64 - pr).min(cap) / cap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (mean_residual / cap).min(1.0) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod 10 partition dead space.
    let residue = post_residual % 10;
    let harmonic = (post_residual / 10) as f64; // number of full 10-slots left

    // Penalize leftovers that are too small to be useful (dead space).
    // A leftover < 10 is nearly unusable given min item size 1..100 unknown;
    // weight by harmonic class: prefer leftovers that are multiples of 10.
    if residue == 0 {
        score -= 6.0 * harmonic.min(8.0);
    } else {
        // non-aligned leftovers: penalty grows as residue deviates from 0/5
        let dev = residue.min(10 - residue) as f64;
        score += 1.5 * dev;
    }

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // reward proportional to how tightly next item nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0; // nested leftover stays harmonic-aligned
            }
        } else {
            // next item won't fit here: mild penalty for stranding space
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
        if post_residual <= 5 {
            score -= 30.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a fresh bin when existing fits are very poor (large post_residual
    // relative to capacity) or when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: keep it moderately high so it loses to good fits
        score = bin_capacity as f64 * 0.55;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64).ln().max(0.0);
        // open a new bin if mean residual across open bins is small (they're all tight)
        let tight = (mean_residual / bin_capacity as f64) < 0.15;
        if tight || fitting_bins_count == 0 {
            score -= 25.0 + 10.0 * crowded * (1.0 - progress);
        }
        // late in the stream, avoid spawning bins for tiny gains
        if progress > 0.9 {
            score += 10.0;
        }
    } else {
        // penalty for leaving very large holes in partially filled bins
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score += 12.0 * frac;
        }
        // slight preference for filling fuller bins (best-fit bias already via base)
        score -= 0.05 * (1.0 - frac) * (bin_residual as f64);
    }

    // Mean-residual steering: prefer bins below the mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so
    // existing bins are preferred unless they create dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
        // If lookahead item fits better in a fresh bin's residual, ease penalty.
        if next_item_size > 0 && (bin_capacity as f64 - post_residual as f64) < next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Lookahead synergy: reward leaving a gap that exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 3.0;
    }

    // Mild stream progression: later in stream, be more conservative about waste.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled quadratically
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size < post_residual {
            // next fits but leaves more waste; penalize proportionally
            let chain_waste = (post_residual - next_item_size) as f64;
            score += 0.5 * chain_waste;
            // mild reward if chain waste is small
            if chain_waste <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            score += 10.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 12.0; // much tighter than average: good consolidation
        } else if rel > 1.5 {
            score += 8.0; // leaves more space than average: fragmentation
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 95.0 + 0.3 * open_bins_count as f64;
        // if the new bin could chain with the next item perfectly, slightly cheaper
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        // early in stream, opening bins is cheap; late in stream, avoid proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Discourage leaving residuals that are hard to fill (prime-ish awkward gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny dead space is nearly unusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item can plausibly use
    // (smallest item is 1 in general interface; treat residual < 10 as near-dead)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 15.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave a large awkward residual
            if post_residual > 0 && post_residual < next_item_size {
                score += 8.0 * (post_residual as f64 / next_item_size as f64);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // cheaper to open new bin when few bins open or late in stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
        // if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // if mean residual across open bins is small, opening new bin is better
        score += 0.3 * mean_residual;
    }

    // Mild preference for filling bins that are already partially used
    // (keeps bin count low, balances residuals)
    if bin_residual < bin_capacity {
        let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * used_frac;
    }

    // Penalize creating residual that is much larger than mean but awkward
    if post_residual as f64 > mean_residual * 1.5 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post residual
    let p = progress;
    // Smooth interaction: dead-space penalty grows quadratically with progress
    score += 40.0 * x * x * (0.5 + p);
    // Cubic coupling term: large residuals become more costly late in the stream
    score += 25.0 * x * x * x * p;

    // Reward tight fits (small post residual), smoothly.
    score -= 15.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * p;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: penalize bins whose post residual can't fit next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // smooth reward for leaving room for the next item
            score -= 10.0 * (gap / cap) * (1.0 - p);
        } else {
            // smooth penalty proportional to shortfall
            score += 12.0 * (-gap / cap) * (1.0 + p);
        }
    }

    // Mean-residual divergence penalty: discourage bins far from fleet average.
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild new-bin preference early (empty bin candidate), declining with progress.
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - p) * (1.0 - p);
        // penalize opening bins when many are already open
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes of 10 (classic bin-packing dead zones)
    let post = post_residual as u32;
    let class = post % 10;
    // Penalize residuals that are too small to hold even the smallest item (dead space)
    if post > 0 && post < 10 {
        score += 40.0 * (1.0 - post as f64 / 10.0);
    }
    // Reward "harmonic" residuals that are multiples of 10 (likely reusable by future items)
    if class == 0 {
        score -= 12.0;
    } else {
        score += class as f64 * 0.8;
    }

    // Tight fit reward: post_residual small but nonzero-ish relative to capacity
    let tight = (post as f64) / cap;
    if post == 0 {
        score -= 30.0; // perfect fill
    } else if tight < 0.10 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size < post {
            // fraction of next item absorbed if post is its harmonic class
            let nxt_class = next_item_size % 10;
            if post % 10 == nxt_class && post >= next_item_size {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here; slight penalty proportional to overflow gap
            score += 2.0 * ((next_item_size - post) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is bad (large post_residual)
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; competitive only if existing bins waste space
        score = cap * 0.55 + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // prefer bins with residual closest to item (best-fit flavor) modulated by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.15 * (bin_residual as f64 - item_size as f64) * (0.5 + 0.5 * progress);
    }

    // Prefer balancing against mean residual: avoid dumping into already-empty bins early
    if (bin_residual as f64) > mean_residual * 1.5 && open_bins_count > 1 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 6.0 } else if post_residual < 20 { 3.0 } else { 0.0 };
        score += dead * (post_residual as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 0.5;

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 10.0;
        }
    }

    // Slight preference for tighter bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Late-stream tightening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: exact match of post_residual with next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 600.0;
    }

    // Next item fits into the post-residual: mild reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - tight / bin_capacity as f64);
    }

    // Post-residual too small for next item: penalize dead space, worse when small.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 120.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a very large item
    // or few bins fit the item.
    if bin_residual == bin_capacity {
        let base = 60.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 15.0 };
        score += base + scarcity;
        // Big items justify fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Mild preference to consolidate early, spread late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but reward exactness super-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 3.0 * (nxt - post_residual as f64);
        }
        // Reward leaving exactly enough room for the next item.
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or the stream is early (building good structure early pays off).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let load = item_size as f64 / cap;
        score += 4.0 + 6.0 * progress - 5.0 * load;
        // If no open bin fits well, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 6.0;
        }
    }

    // Prefer filling bins that are already below-average residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for bins with more remaining peers that could take overflow later.
    score -= 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tightness: reward small post_residual non-linearly.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Lookahead pairing: if next item fits into post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let pair_fit = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 10.0 * pair_fit * (1.0 - progress);
    } else if next_item_size > 0 {
        // Dead space relative to lookahead item: penalize unusable gap.
        let gap = (post - next_item_size as f64).max(0.0);
        score += 0.15 * gap * (1.0 - progress);
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening new bins when open bins have healthy residuals.
    if bin_residual == bin_capacity {
        let mean_ratio = (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 + 15.0 * mean_ratio + 2.0 * (open_bins_count as f64).sqrt();
        // But allow new bins late in the stream if fit is bad.
        if tightness > 0.7 {
            score -= 10.0 * progress;
        }
    }

    // Mild penalty for waste relative to mean residual state.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by small
    // moduli are more reusable by future items drawn from arbitrary ranges.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr == 0 {
        reusability += 20.0; // perfect closure
    } else {
        if pr % 10 == 0 { reusability += 8.0; }
        if pr % 5 == 0 { reusability += 3.0; }
        if pr % 2 == 0 { reusability += 1.5; }
        if pr <= 10 { reusability -= 6.0; } // sliver, nearly dead space
    }
    score -= reusability;

    // Lookahead coupling: does the next item land on a harmonic class of pr?
    if next_item_size > 0 {
        let diff = pr as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 25.0; // next item exactly closes this bin
        } else if diff > 0 && (diff as u32) <= 10 {
            score -= 12.0; // next item leaves a tiny but acceptable remainder
        } else if diff > 0 {
            let d = diff as u32;
            if pr % d.max(1) == 0 { score -= 6.0; } // divisible residual class
            if d % 10 == 0 { score -= 4.0; }
        } else {
            score += 10.0; // next item cannot follow here
        }
        // next item size harmonic class (common "nice" sizes)
        if next_item_size % 25 == 0 { score -= 2.0; }
        if next_item_size % 20 == 0 { score -= 1.0; }
    }

    // Integer-division threshold on post_residual: classify leftover quarters.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > half {
        score -= 5.0; // still roomy bin
    } else if pr > quarter {
        score -= 1.0;
    } else if pr > 0 {
        score += 3.0; // cramped bin, penalize mildly
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit is poor; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit = (item_size as f64) < 0.5 * bin_capacity as f64;
        score += 12.0 - pressure.min(12.0);
        if poor_fit && fitting_bins_count > 0 {
            score += 8.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 4.0; // fresh bin pairs well with a mid-size next item
        }
    }

    // Mild stream-progress tilt: early on, keep bins tight; late, close out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can use are pure waste.
    // Treat gaps < 10 as total loss; 10..20 as partial loss (only tiny items fit).
    if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward; if next item almost fits, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual >= 10 && next_item_size - post_residual <= 10 {
            score += 10.0; // next item will strand this gap
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, new bins are cheaper.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: empty bin gets a base offset so it only wins
    // when open bins have poor fits; offset shrinks as stream progresses.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 - 15.0 * progress;
        // But if no open bin can fit, opening is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference to place into bins below mean residual (balance load).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0; // exact 2-step chain: this bin becomes perfect for the next item
        } else {
            // Penalize wasted residual relative to next item's size
            let wasted = post_residual as f64 - (post_residual as f64).min(next_item_size as f64);
            score += wasted * 0.5;
            // Small reward if next item still fits in this bin after placement
            if post_residual >= next_item_size {
                score -= 30.0 + 20.0 * (post_residual as f64 - next_item_size as f64).recip().min(1.0);
            }
        }

        // Chain bonus: item + next item nearly fill the bin
        if item_size + next_item_size >= bin_residual {
            score -= 150.0;
        }
    }

    // Compare against mean residual: penalize leaving residual far above mean (fragmentation)
    let residual_gap = post_residual as f64 - mean_residual;
    score += residual_gap * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when good open bins exist (new-bin candidate has residual == capacity)
    if bin_residual == bin_capacity {
        score += 80.0 + 50.0 * (1.0 - progress);
        // Allow new bin only if no other bin fits or open bins are all nearly full
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0;
        }
        // If mean residual is large, prefer reusing existing bins
        score += mean_residual * 0.2;
    }

    // Mild reward for filling larger fraction of the bin
    score -= (item_size as f64 / bin_capacity as f64) * 50.0;

    // Dead-space penalty: residual too small for any plausible item (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // small unusable slivers are bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        let wasted = if (post_residual as u32) < next_item_size { post_residual as f64 } else { 0.0 };
        score += 1.8 * wasted;
        // Bonus if post_residual exactly accommodates the next item.
        if (post_residual as u32) == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size == 0 {
        // Last item: just minimize post residual, already base.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when plenty of aggregate residual exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let aggregate_slack = mean_residual * (open_bins_count as f64);
        let item_fits_slack = (item_size as f64) <= aggregate_slack;
        let mut new_bin_penalty = 8.0;
        if item_fits_slack { new_bin_penalty += 6.0; }
        // Later in stream, prefer consolidating into existing bins.
        new_bin_penalty += 10.0 * progress;
        // Few open bins -> cheaper to open one; many open bins -> discourage.
        new_bin_penalty += 0.15 * (open_bins_count as f64);
        // If next item is large and would need a fresh bin anyway, opening now is fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            new_bin_penalty -= 5.0;
        }
        score += new_bin_penalty;
    } else {
        // Slight preference for bins with residual close to item (best-fit flavor).
        let gap = (bin_residual as f64) - (item_size as f64);
        score += 0.05 * gap;
        // Prefer using bins whose residual deviates below mean (consume scarce space first).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    // Mild penalty for leaving post_residual in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / capacity;

    // Smooth polynomial coupling: tight fits are rewarded more strongly as stream progresses.
    let tightness = (1.0 - pr / capacity).powi(3);
    let mut score = pr * (1.0 + 0.8 * progress) - 60.0 * tightness * (0.5 + progress);

    // Penalize residual that cannot fit the lookahead item (wasted dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / capacity;
        score += 25.0 * gap * gap;
        // Reward leaving room exactly for the next item (perfect chaining).
        let chain = 1.0 - ((pr - nxt) / capacity).abs();
        score -= 15.0 * chain.max(0.0) * (1.0 - progress);
    } else {
        // Last item: strongly prefer minimal residual.
        score += 40.0 * (pr / capacity).powi(2);
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * fill;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64).ln() * (2.0 + 3.0 * (1.0 - fill));

    // New-bin candidate: keep it neutral-ish but slightly worse than a good fit,
    // better than a very poor fit (large post_residual).
    if bin_residual == bin_capacity {
        score += 0.5 * capacity + 10.0 * (mean_residual / capacity);
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: bins whose leftover falls into
    // "small usable" classes should be rewarded (tight packing).
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual <= 10 -> perfect fit, reward strongly.
    if post_residual <= 10 {
        score -= 25.0;
    }
    // Class B: post_residual divisible by 10 (harmonic with typical item sizes)
    else if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class C: post_residual in (10, 20] -> likely a future small item fits.
    else if post_residual <= 20 {
        score -= 3.0;
    }
    // Class D: dead zone 21..=39 -> awkward, penalize.
    else if post_residual <= 39 {
        score += 5.0;
    }

    // Integer-division threshold coupling: leftover large enough for half the
    // next item is more valuable than a fragment.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // Next item fits here: reward, scaled by how tight the fit would be.
            let future_post = (post_residual - next_item_size) as f64;
            score -= 8.0 + 10.0 * (1.0 - future_post / cap_f);
        } else if post_residual * 2 >= next_item_size {
            // Half-class: partial usefulness, small reward.
            score -= 2.0;
        } else {
            // Leftover can never host the next item: mild penalty.
            score += 3.0;
        }
    } else {
        // Last item: prefer tightest possible closure.
        score -= 15.0;
    }

    // Fractional capacity coupling: reward filling a large fraction of the bin.
    let fill_frac = item_size as f64 / cap_f;
    score -= 12.0 * fill_frac * fill_frac;

    // Mean-residual contrast: choosing a bin well below mean residual means
    // concentrating packing; reward it.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large relative to remaining residuals or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // Early stream: opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // Large items justify fresh bins.
        score -= 10.0 * fill_frac;
        // If many open bins have big residuals, discourage a new one.
        if mean_residual > 0.5 * cap_f && open_bins_count > 2 {
            score += 15.0;
        }
        // If no open bin fits at all, opening is mandatory: strong reward.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference for bins whose residual class matches the item's
    // harmonic class (item_size mod 10 vs bin_residual mod 10).
    if bin_residual % 10 == item_size % 10 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Tiny tie-break so lower post_residual always wins among equals.
    score + post_residual as f64 * 0.001
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // (min item size 10) -> heavy penalty so we prefer exact fits or
    // post_residual >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Last chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins would leave
        // bad dead space; otherwise penalize.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 && post_residual >= 10 {
            score += 20.0;
        }
    }

    // Lookahead: if next item could use this bin's post_residual,
    // reward leaving a usable gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If post_residual is a gap the next item cannot use, penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Stream progression: late in stream, prefer using existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins below mean residual (reduces variance of residuals).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // next item won't fit here; penalize wasted residual slightly
            score += 20.0;
        }
    }

    // Compare post residual to mean residual: small post_residual relative to mean is good
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Tightness reward: small post_residual relative to capacity
    score -= 0.3 * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is very small
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Progression: later in stream, prefer consolidating into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Prefer tight fits: reward small post_residual non-linearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; slight penalty for large leftovers
            score += 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Mild penalty when many bins compete (encourage consolidation)
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Compare bin residual against mean residual: prefer filling below-average-residual bins
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate aggressively into open bins rather than opening new ones
    score += 10.0 * t * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: opening a new bin is only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;
        // If this bin is the only fitting option, opening may be necessary
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Early in stream, opening new bins is cheaper; late, expensive
        score -= 20.0 * (1.0 - t);
        // If next item is large and current item is small, a fresh bin may serve both better
        if next_item_size > 0 && next_item_size > post_residual + item_size {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is an exact multiple structure (diversity term)
    if bin_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space quadratically, more so late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 25.0 * (-norm_pr * 8.0).exp() * (1.0 + progress);

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 15.0 * snug * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open and this one is far from mean residual
    let dev = (mean_residual - pr).abs() / cap;
    score += 8.0 * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate: make it moderately attractive early, less so later
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate ----
    if bin_residual == bin_capacity {
        // Baseline score: slightly worse than a decent fit, but better than
        // catastrophic dead space. Easier to open early, harder late.
        let mut nb = bin_capacity as f64 * 0.85 + open_bins_count as f64 * 2.0;
        nb -= progress * 10.0; // late in the stream, prefer reusing open bins
        // If the lookahead item is huge, a fresh bin is more attractive.
        if next_item_size >= 40 { nb -= 5.0; }
        return nb;
    }

    // ---- Real bin candidate ----
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: tiny remainders are dead space.
    let cls = post_residual / 10; // 0..10 classes
    if post_residual > 0 {
        match cls {
            0 => score += 25.0,                       // 1..9: nearly unusable
            1 => score += 12.0,                       // 10..19: poor
            2 => score += 5.0,                        // 20..29: mediocre
            3 | 4 => score -= 2.0,                    // 30..49: useful
            5 | 6 => score -= 4.0,                    // 50..69: very useful
            7 | 8 => score -= 3.0,                    // 70..89: good
            _ => {}                                   // 90..99: near full, fine
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward if the next item leaves another small remainder
            let npr = post_residual - next_item_size;
            if npr <= 15 && npr > 0 { score -= 3.0; }
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            if post_residual < 20 { score += 10.0; }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty for spreading items too thin
        score += (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Prefer bins tighter than the mean (good packing direction).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are always dead; but mid-range gaps that no plausible item fits well
    // are heavily penalized. Treat gaps < 10 as fully dead, and gaps that
    // are "awkward" (just above a small item) as partially dead.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable sliver: treat like a perfect fit minus a small penalty.
        score = 5.0 + post_residual as f64 * 0.5 - 900.0;
    } else {
        // Awkward gap penalty: peaks when post_residual is slightly larger
        // than a small item (wasted potential), decays as gap grows.
        let gap = post_residual as f64;
        let awkward = 30.0 * (-(gap - 15.0f64).abs() / 10.0).exp();
        score += awkward;

        // Reward leaving a gap that can host the lookahead item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0; // mild reward for keeping lookahead feasible
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
        // Extra pressure when many bins are already open (consolidate).
        score -= open_bins_count as f64 * 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins with below-mean residual (fill the emptier ones first,
    // keeping tight bins for future tight fits).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate: only attractive when the fit into open bins is
    // hopeless (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 250.0;
        // Cheaper to open a bin late in the stream (less future to plan).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 150.0;
        // If many bins fit the item, opening a new bin is wasteful.
        score += fitting_bins_count as f64 * 80.0;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured.

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = if post_residual == next_item_size { 40.0 } else { 0.0 };
        score -= perfect - diff * 0.6;

        // If next item could chain into this bin after current item, big reward.
        if post_residual >= next_item_size {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Dead space penalty scaled by how unusable the leftover is.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the fleet average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0 + item_size as f64 * 0.2;
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Mild preference for filling nearly-full bins completely.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // tiny unusable slivers are wasteful
    } else if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: neutral-to-slightly-averse score so it
        // only wins when no existing bin offers a decent fit.
        score = 60.0
            + 0.15 * open_bins_count as f64
            - 0.25 * mean_residual
            - 20.0 * progress; // later in stream: slightly more willing to open bins
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is necessary.
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Tight fit reward.
        if post_residual == 0 {
            score -= 12.0;
        }
        // Last-chance bin: strongly avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 9.0 + 4.0 * progress;
        }
        // Lookahead: penalize leaving dead space the next item cannot use,
        // reward leaving space the next item can still fill.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += 5.0 + 3.0 * progress;
            } else if post_residual >= next_item_size {
                score -= 2.0;
            }
        }
        // Prefer bins whose residual is already below average (consolidate waste).
        score += 0.08 * (bin_residual as f64 - mean_residual);
        // Mild penalty for spreading across many open bins.
        score += 0.03 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on, tolerate waste;
    // late in the stream, penalize residual space more aggressively.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Smooth penalty for leaving residual close to the smallest item size
    // (unusable dead space), using a smooth bump rather than a threshold.
    let dead_zone_center = 10.0 / cap;
    let bump = (-((norm_pr - dead_zone_center) * (norm_pr - dead_zone_center)) / (2.0 * dead_zone_center * dead_zone_center)).exp();
    score += 12.0 * bump;

    // Reward bins that also fit the next item (smooth lookahead coupling).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 3.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild penalty when this bin's residual deviates from the mean residual
    // (encourage balanced residual distribution across open bins).
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: score relative to current waste landscape; opening a
    // new bin is favored when existing bins would leave very tight residuals.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 2.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items leaving residuals divisible by
    // common item-size classes (multiples of 10) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        4.0 // awkward residual
    };
    score += class_bonus;

    // Dead-zone penalty: residual too small for the smallest plausible next item.
    let min_next = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if pr > 0 && pr < min_next {
        score += 15.0 + (min_next - pr) as f64 * 0.5;
    }

    // Reward leaving exactly enough room for the lookahead item (chaining).
    if next_item_size > 0 && pr >= next_item_size && pr < next_item_size + 10 {
        score -= 20.0;
    } else if next_item_size > 0 && pr >= next_item_size {
        score -= (next_item_size as f64) * 0.15;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / cap;
    score -= fill * 25.0;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize so it only wins when fits are awful.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin fits well, allow opening when item is large.
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mild preference for spreading across many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // moderately awkward gap
    }

    // Reward tight fits (small post_residual is good, but not dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0; // gap won't serve next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.5 + 2.0 * progress);

    // Prefer bins with residual close to the mean (keeps bin states uniform).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.4 * diff;

    // New-bin candidate: baseline score; only chosen if no decent fit exists.
    if bin_residual == bin_capacity {
        score = 95.0
            + 3.0 * (open_bins_count as f64)
            + 10.0 * (1.0 - progress)
            - if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin helps large upcoming items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack left over.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }
    // Next item would not fit here: mild bonus proportional to how tight this bin is closed.
    else if next_item_size > 0 {
        score -= (post_residual as f64 / 20.0).min(10.0);
    }

    // Penalize creating tiny unusable dead space (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward filling bins tightly relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Late in the stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space quadratically when residual is small but unusable.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) * 0.02;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Extra reward if next item exactly fills post_residual.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Penalize opening a new bin when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * open_bins_count as f64 * 0.1;
        // But if mean residual across open bins is small (bins nearly full),
        // opening a new bin becomes more attractive.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
        // If no open bin fits well (large post_residual elsewhere), new bin is fine.
        if fitting_bins_count > 0 {
            let best_other = mean_residual;
            if (best_other - item_size as f64).abs() > (bin_capacity as f64 - item_size as f64) {
                score -= 10.0;
            }
        }
    }

    // Mild penalty for bins with residual far from typical item sizes.
    let mid = 40.0;
    let residual_dist = (post_residual as f64 - mid).abs();
    score += residual_dist * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) coupling
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Progress coupling: waste tolerance shrinks as stream advances
    let urgency = 1.0 + 2.0 * progress;
    score *= urgency;

    // Dead-space penalty: residuals too small to hold any plausible item
    let dead = if pr < 1.0 { 0.0 } else { ((1.0 - norm_pr).powi(3)) * 40.0 };
    score -= dead;

    // Lookahead: reward residuals that can also hold the next item (chaining)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 18.0 * (1.0 - (pr - nx) / cap);
        } else {
            // next item won't fit here: penalize if residual is awkward
            score += 10.0 * (1.0 - norm_pr);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual coupling: penalize bins far from the mean residual (imbalance)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make empty bin attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let pressure = mean_residual / cap;
        score = cap * (0.6 + 0.4 * pressure) - 15.0 * (1.0 - (1.0 - (crowd / (crowd + 5.0))).sqrt());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes
    // modulo a few divisors of capacity to reward "harmonic" leftovers that
    // small future items can still fill.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward post_residuals that are multiples of small harmonic units (10, 20, 25, 50)
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 4.0; }
    }
    // Perfect fit is best
    if pr == 0 { score -= 25.0; }

    // Penalize tiny unusable dead space (1..=5): near-dead residual
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Integer-division threshold: post_residual bucket by quarter capacity
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    let frac = pr as f64 / cap;
    if frac < 0.25 { score += 4.0; }        // mostly-empty leftover is bad
    else if frac < 0.5 { score += 1.0; }
    else if frac < 0.75 { score -= 2.0; }   // roomy bin is good
    else { score -= 4.0; }

    // Lookahead coupling: does this bin still serve the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits exactly into the leftover -> strong reward
            score -= 5.0;
            if pr == next_item_size { score -= 6.0; }
            // harmonic match: leftover divisible by next item size
            if next_item_size > 0 && pr % next_item_size == 0 { score -= 3.0; }
        } else {
            // leftover too small for the next item: penalize proportionally
            score += 3.0 * (next_item_size as f64 - pr as f64) / cap * 10.0;
        }
    } else {
        // last item: prefer tightest packing
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when
    // open bins can absorb the item; make new bin unattractive unless the
    // item is large relative to residual (poor fit everywhere).
    if bin_residual == bin_capacity {
        // baseline for fresh bin: capacity minus item (large leftover)
        score = (bin_capacity - item_size) as f64;
        // early in the stream, new bins are cheap; later, reuse is preferred
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if many bins already open, discourage spreading
        score += 0.5 * open_bins_count as f64;
        // but if item barely fits anywhere (item_size > mean_residual), new bin is fine
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Mild tie-breaker toward bins tighter than average (compactness)
    score -= 2.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are essentially dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Semi-dead zone: only large next items could use it.
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    }
    // If next item almost fits, slight penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by pressure and mean residual.
        score += 30.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // But if no existing bin fits well (large dead-space risk), opening
        // a fresh bin is acceptable: relax the penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Mild bonus for filling existing bins when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Early stream: slightly favor keeping bins balanced for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: post_residual close to zero relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted post_residual relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Penalize post_residual far below mean residual (fragmenting a roomy bin badly)
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.3 * (-dev);
    } else {
        score -= 0.15 * dev.min(50.0);
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Discard spreading across many bins when few fit
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual <= bin_capacity
            && fitting_bins_count > 0
            && (bin_residual - item_size) < mean_residual as u32;
        // base penalty so open bins win unless they fit poorly
        score += 250.0;
        // if item is small relative to capacity and bins are crowded with small residuals,
        // opening a fresh bin becomes viable
        let open_ratio = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
        score -= 100.0 * (item_size as f64 / bin_capacity as f64) * open_ratio.min(2.0);
        if mean_residual < item_size as f64 * 0.5 {
            score -= 300.0;
        }
        let _ = good_fit_exists;
    }

    // mild stream-progression scaling: be more conservative early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post_residual dominates).
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, scaled by how close it is to capacity.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early or when open bins have large residuals,
        // but costly when open bins are nearly full.
        let avg_tightness = 1.0 - mean_residual / (bin_capacity as f64 * open_bins_count.max(1) as f64);
        score += 10.0 + 20.0 * avg_tightness + 8.0 * t;
        // If the item is large relative to residual, new bin is safer.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        // Reward using bins with residual close to item size (best-fit sharpening).
        let waste = (bin_residual - item_size) as f64;
        score += 0.5 * (waste / bin_capacity as f64).powi(2) * bin_capacity as f64;
        // Mild reward for consolidating many open bins.
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    // Late in the stream, favor closing out bins: penalize leaving medium residuals.
    if t > 0.8 && post_residual > 0 && post_residual < 20 {
        score += 5.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64 / cap);

    // Reward tight fits with a smooth polynomial coupling to stream progress
    score -= 34.0 * fill * fill * (1.0 + 0.7 * progress);

    // Penalize residual that is too small to ever be useful (dead space),
    // coupled non-linearly with progress (dead space matters more later)
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += 22.0 * dead * (0.5 + progress);

    // Smooth dead-space pressure: residuals just above 10 are also wasteful
    let r = post_residual as f64;
    let waste = (1.0 - (r / 30.0).min(1.0)).max(0.0);
    score += 9.0 * waste * waste * (0.4 + progress);

    // Lookahead: if the next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 16.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 28.0;
    }

    // Penalize spreading across many open bins mildly
    score += 0.35 * open_bins_count as f64 * (1.0 - fill);

    // New-bin candidate (empty bin): make it unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 14.0 + 18.0 * mean_residual / cap + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits via quadratic post_residual penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Small residues (< 10, i.e., unusable dead space for items >= 10... but sizes can be 1..100)
    let dead_threshold: u32 = 5;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0; // creating tiny unusable slivers is bad
    }

    // Reward residuals that are harmonic multiples of common item classes.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 8.0; // round residuals are more likely reusable
    } else if cls >= 5 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 - (slack as f64) * 0.3;
            if slack == 0 {
                score -= 30.0; // chain of perfect fits
            }
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with lower residual among ties (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Prefer reusing existing bins over opening new ones, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses (consolidation).
        score += 10.0 + 25.0 * progress;
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    // Mild pressure to close out bins when many are open.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Residual usable only by a very small next item: mild penalty unless it exactly fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 0.1 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins.
    score += 0.8 * open_bins_count as f64;
    // New-bin candidate: only attractive when it beats poor fits (its post_residual is large,
    // so base score already penalizes it); add fixed opening cost.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in the stream, tighten packing (avoid leaving many half-full bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward closeness of match
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 15.0 * (over / bin_capacity as f64).min(1.0);
        }
    }

    // Compare post_residual against mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open when fits are truly bad
    if bin_residual == bin_capacity {
        score += 40.0 + post_residual as f64 * 0.1;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - frac).powi(6);

    // Penalize unusable dead space: residual too small for smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 3.0;
        }
    } else {
        // Last item: prefer filling existing bins as tightly as possible.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a bin is attractive only if current bin
    // would leave large residual and many bins can already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = mean_residual / bin_capacity as f64;
        let penalty = 18.0 + 40.0 * (1.0 - tightness) + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += penalty;
        } else {
            score -= 10.0; // must open a bin anyway
        }
    } else {
        // Favor bins with residual close to item (best-fit bias) scaled by congestion.
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.05 * fit_gap * (open_bins_count as f64).sqrt();
    }

    // Mild preference for consolidating into fewer bins when mean residual is high.
    score -= 0.02 * mean_residual * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Early stream: prefer tight fits (low post_residual) mildly; late stream: penalize waste strongly
    let waste_weight = 0.5 + 3.0 * p2 + 2.0 * p3;
    score += waste_weight * pr_norm * pr_norm * bin_capacity as f64;

    // Smooth interaction: dead space becomes more costly as open bins accumulate
    let bin_pressure = (open_bins_count as f64).ln() + 1.0;
    score += 0.8 * bin_pressure * pr_norm * (1.0 - progress);

    // Reward near-perfect fills with a smooth quadratic bonus
    let fill = 1.0 - pr_norm;
    score -= 4.0 * fill * fill * (1.0 + progress);

    // Last-chance bin: smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 2.5 + 3.0 * progress;
    }

    // Lookahead: smooth penalty if next item won't fit the post-residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 1.5 * (1.0 - (pr / next_item_size as f64).max(0.0)) * (0.5 + progress);
    }

    // Anchor relative to mean residual of open bins (smooth deviation term)
    score += 0.3 * (pr - mean_residual) * (1.0 + p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 as a "waste band"
    let post = post_residual as i64;
    let residue = (post % 10) as f64;
    // Penalize awkward residues (dead space not reusable by small items)
    score += residue * 0.15;

    // Exact-fill bonus
    if post == 0 {
        score -= 100.0;
    }

    // Harmonic threshold on post_residual via integer division: bands of 10
    let band = post / 10;
    match band {
        0 => score += 20.0,          // tiny leftover, nearly unusable
        1 => score += 8.0,           // small leftover
        2 => score -= 4.0,           // sweet spot for medium items
        3 => score -= 2.0,
        _ => {}
    }

    // Coupling with next item: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size as i64 <= post {
            // reward chains: next item fits, prefer bins with tight chain fit
            let chain_waste = (post - next_item_size as i64) as f64;
            score -= 10.0 + (10.0 - chain_waste * 0.5).max(0.0);
        } else {
            // penalize if next item almost fits (frustrating miss)
            let miss = (next_item_size as i64 - post) as f64;
            if miss <= 10.0 {
                score += 6.0 + (10.0 - miss);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity fraction and many bins are already open
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // opening a new bin is good for big items, bad for small ones
        score += 30.0 - 40.0 * frac;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins with slack -> avoid new bin
        if mean_residual > frac * bin_capacity as f64 * 2.0 {
            score += 10.0;
        }
    }

    // Mild preference for tighter bins overall
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 {
        // smallest item is 1 under the interface; gaps below ~10 are near-dead
        let dead_threshold: f64 = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 25.0;
        }
        // medium gaps (10..=25) are semi-dead: moderate penalty
        else if post_residual <= 25 {
            score += (25.0 - post_residual as f64) * 2.0;
        }
    }

    // Reward leaving a gap that exactly fits the lookahead item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // post_residual smaller than next item: gap likely wasted
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: discourage spreading across many bins when fit is poor
    score += (open_bins_count as f64) * (post_residual as f64) * 0.05;

    // Prefer filling bins with residual below mean (tight packing)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Discourage opening a new bin early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
        // but if no open bin fits well, allow opening
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 6.0;
        } else {
            score += diff * 0.5;
        }

        // Chain fit: item fits here AND next item fits in the remainder exactly.
        if post_residual >= next_item_size && next_item_size >= 1 {
            let chain_left = post_residual - next_item_size;
            if chain_left == 0 {
                score -= 30.0;
            } else if chain_left < 10 {
                score += 10.0; // tiny unusable sliver after chain
            }
        }
    }

    // Penalize creating dead space too small for any plausible item (min size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive if no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let tight_exists = next_item_size > 0
            && (post_residual as i64 - next_item_size as i64).abs() <= 5;
        if tight_exists || fitting_bins_count <= 2 {
            score += 80.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 10.0; // mild encouragement for poor-fit situations
        }
    }

    // Prefer bins tighter than average residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference to fill earlier bins as stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            // Next item won't fit here; slight penalty for wasting residual potential.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(30.0);
        }
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln_1p();
        // Penalize new bins more mid-stream when mean residual is still large (usable space exists).
        score += 18.0 + 10.0 * open_pressure * (1.0 - progress) + 0.2 * mean_residual;
        // But late in the stream, or when the item barely fits elsewhere, new bin is cheap.
        if fitting_bins_count == 1 && (item_size as f64) > 0.8 * (bin_capacity as f64) {
            score -= 30.0;
        }
    }

    // Global fragmentation pressure: if mean residual is small, cherish bins with big residuals.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score -= 0.08 * residual_gap;

    // Mild time-horizon coupling: early stream, prefer consolidation into few bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);

    // Small penalty proportional to item size filling a bin partially (prefer big items in big gaps).
    score += 0.05 * (item_size as f64) * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) penalty
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in stream, penalize large residuals more strongly
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Interaction: post_residual vs mean residual — reward bins tighter than average
    let mean_gap = mean_residual - pr;
    score -= 8.0 * mean_gap * (0.5 + progress);

    // Non-linear dead-space term: residuals too small for any item (min size 1) are wasted
    if pr > 0.0 {
        let dead = 1.0 - (pr / 1.0f64.min(cap)).min(1.0);
        score += 15.0 * dead * dead * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item could exactly fill post residual, reward heavily
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_next = (next_item_size as f64 <= pr) as i32 as f64;
        score -= 20.0 * fit_next * (1.0 - diff / cap) * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are hopeless
    if bin_residual == bin_capacity {
        score += 25.0 + 25.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    score
}

