    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Penalize new bin when a decent fit already exists.
        if post_residual as f64 <= mean_residual {
            score += 30.0;
        }
    }

    // Slight progress-based tightening: later in stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: reward if next item exactly fills the post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to waste
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * gap / 100.0;
        }
    } else {
        // last item: pure tight fit, no future to save space for
        score -= 5.0;
    }

    // Compare post_residual against mean residual: avoid leaving much more
    // (or much less) usable space than the fleet average
    let mean_post = mean_residual - item_size as f64;
    score += 0.15 * (post_residual as f64 - mean_post).abs();

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // but allow opening when the item is huge and would leave tiny waste elsewhere
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Early in stream: be slightly conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post-residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let big_item_relief = if item_size as f64 > 0.6 * bin_capacity as f64 { 25.0 } else { 0.0 };
        score += base_penalty + scarcity_bonus + big_item_relief - 0.5 * mean_residual.min(50.0);
    }

    // Mild preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Slight preference for bins with residual above the mean (keep balanced spread).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * 0.5;
    score += 20.0 * poly;

    // Reward tight fits, more so late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space below typical next item size
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (ns - pr).max(0.0) / cap;
        score += 30.0 * waste * waste;
        // Reward leaving room for the lookahead item
        let room = (pr - ns).max(0.0) / cap;
        score -= 10.0 * room;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize early, mildly encourage late
    score += is_new_bin * (30.0 - 20.0 * progress);

    // Prefer filling bins when many are open
    score += (open_bins_count as f64).ln() * norm_pr * 5.0;

    // Slight preference for bins below mean residual (balancing)
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Residuals that are "dead" (1..=9) are worst; exact 0 is best; large residuals
    // are re-usable.
    let r = post_residual % 10;
    match r {
        0 => score -= 8.0,                 // perfect class
        1..=9 => score += (10 - r) as f64 * 1.5, // dead space penalty grows with closeness to a full class
        _ => {}
    }

    // Integer-division thresholds on post_residual: quarters of capacity.
    let q = post_residual / (bin_capacity / 4);
    score -= q as f64 * 2.0; // larger residual blocks are more valuable

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional fit tightness (harmonic: next item nearly fills remainder)
            let tight = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 10.0 * tight;
            // Bonus if next item exactly consumes the residual class
            if post_residual - next_item_size < 10 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual; penalize small leftover residuals more.
            score += 4.0;
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance logic: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it is a
    // good "absorber" bin.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // Penalize leaving residual in classes 1..=9 when many bins are open (fragmentation).
    if open_bins_count > 4 && r >= 1 && r <= 9 {
        score += (open_bins_count as f64).ln() * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64 * 8.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward residual that can still fit typical items; penalize large waste in a mostly-full bin.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by this residual (small dead gap), penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean.
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: make it mildly attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled by capacity fraction.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // --- Aggressive 2-step lookahead: reward bins whose post_residual matches next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect chain: next item exactly fills this bin afterwards -> huge reward.
        if post == nxt {
            score -= 60.0;
        } else if post > nxt {
            // Next item fits again: reward proportionally to how well it nests.
            let nest = 1.0 - ((post - nxt) / bin_capacity as f64);
            score -= 25.0 * nest;
        } else {
            // Next item does NOT fit here: penalize leaving dead space, worse when
            // the waste is close to but below the next item (near-miss is worst).
            let gap = nxt - post;
            let near_miss = 1.0 - (gap / nxt).min(1.0);
            score += 18.0 * near_miss;
            // Penalize unusable slivers harder as stream progresses.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * progress * (post / bin_capacity as f64);
        }
    } else {
        // Last item: only current fit matters.
        score -= 15.0;
    }

    // --- Relative-to-mean coupling: prefer bins tighter than the fleet average ---
    score += 0.25 * (mean_residual - post_residual as f64);

    // --- Last-chance bonus: if this is the only bin that fits, avoid wasting it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual) or few bins fit at all.
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.35;
        if poor_fit || (next_item_size > 0 && next_item_size as f64 > post_residual as f64) {
            score -= 12.0;
        } else {
            // Discourage needless bin proliferation.
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item can fill later.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill
    } else if post_residual > 60 {
        score += 3.0; // large leftover wastes the bin
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Time horizon: early in the stream, be more conservative (prefer filling
    // existing bins); late in the stream, allow new bins when fits are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax as stream progresses.
        score += 12.0 * (1.0 - progress);
        if item_size >= 80 { score -= 5.0; } // huge items fine in fresh bin
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // reusing bins to consolidate; few open bins -> new bins are cheaper.
    score += mean_residual * 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Reward filling bins that are already mostly consumed.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 3.0 * fill_ratio;

    // Slight noise-free deterministic tiebreak based on residual parity mix.
    score += (post_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let fit = item_size as f64;

    // Base: tightness of fit, non-linearly shaped
    let base = pr.powf(1.6) / cap;

    // Smooth interaction: tight fits matter more later in the stream
    let coupling = base * (1.0 + 1.2 * progress * progress);

    // Reward near-perfect fits smoothly (post_residual small relative to capacity)
    let tight_bonus = -8.0 * (-pr / (0.15 * cap)).exp();

    // Penalize dead space that likely can't host the lookahead item
    let mut score = coupling + tight_bonus;
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.6 * (gap / cap).powf(1.5);
        // Smooth reward when post-residual nicely fits the next item
        score -= 3.0 * (-(pr - nxt).abs() / (0.2 * cap)).exp();
    }

    // Last-chance bin: penalize leaving it unused strongly
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize opening fresh bins, more so early and when good fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If mean residual is large, opening new bins wastes space
        score += 0.3 * mean_residual;
    }

    // Mild preference for bins below mean residual (spread waste evenly)
    score += 0.2 * ((r - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: integer division thresholds on capacity fractions
    let post = post_residual as f64;
    let class = (post / (cap / 4.0)).floor(); // 0..4 harmonic quartile class
    let dead_penalty = match class as u32 {
        0 => 60.0,                 // near-perfect fill: heavily reward (already low via post_residual)
        1 => 18.0,                 // small residual: mild penalty
        2 => 6.0,                  // mid residual
        3 => 14.0,                 // large residual: moderately bad
        _ => 0.0,                  // empty/new bin class
    };
    score += dead_penalty;

    // Modulo arithmetic on post_residual: residual mod small harmonics (5,10) —
    // residuals divisible by 10 pair well with typical item sizes.
    let r = post_residual;
    if r > 0 && r % 10 == 0 {
        score -= 8.0;
    } else if r % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0; // odd residuals create dead space
    }

    // Lookahead coupling: can next_item_size exactly fill this residual class?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post_residual {
            score -= 45.0; // perfect future pairing
        } else if nxt <= post_residual && post_residual - nxt <= 10 {
            score -= 20.0; // near-perfect future pairing
        } else if nxt > post_residual {
            // next item cannot use this residual: penalize proportionally to waste
            score += (nxt.min(post_residual.max(1)) as f64) * 0.15;
            if post_residual < 10 {
                score += 12.0; // tiny unusable sliver
            }
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = cap - item_size as f64 + 5.0; // baseline: residual of fresh bin + slight cost
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open new bin
        } else if fitting_bins_count == 1 {
            // last-chance bin exists: discourage new bin unless current fit is terrible
            score += (post_residual_of_last_chance_hint(cap, post) ) * 0.0 + 10.0;
        }
    } else {
        // Last-chance bonus: this is the only bin that fits -> avoid opening new bin
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Tight-fit reward: item nearly fills bin
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 30.0;
        } else if fill_ratio > 0.7 {
            score -= 12.0;
        }
    }

    // Stream progression: later in stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= progress * 6.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's an outlier
    // worth emptying; if far above mean, it's loose and usable.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * 10.0;

    // Penalize many open bins mildly to discourage fragmentation
    if !is_new_bin {
        score += (open_bins_count as f64).sqrt() * 0.8;
    }

    score
}

fn post_residual_of_last_chance_hint(cap: f64, post: f64) -> f64 {
    // harmonic helper: fraction of capacity left after placement
    post / cap
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead space". Penalize them heavily (non-linearly).
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 30.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Penalize large leftover only mildly, but reward leaving room that could
    // plausibly fit the lookahead item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 12.0; // bin stays useful for the next item
        } else {
            score += 8.0;  // lookahead item won't fit here
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin moderately unattractive unless
    // the fit is genuinely bad (large post_residual) or many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Open-bin pressure: encourage filling existing bins as they accumulate.
    score += 0.05 * open_bins_count as f64;

    // Progress-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.5 * progress;

    // Slight preference for bins whose residual is near the mean (balanced use).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // reward heavily (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // Next item does NOT fit this bin after placement: penalize
            // leaving a gap smaller than the next item (dead space risk).
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.3 * (next_item_size as f64 - gap);
            }
        }
    }

    // Compare post_residual against the mean residual of open bins.
    // Leaving more than average residual is wasteful; leaving less is good.
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize creating very small unusable slivers unless the next item matches.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 6.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual - item_size.min(bin_residual) {
            // opening a fresh bin keeps large residual for future items
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual), super-linear penalty.
    score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize if leftover space is too small for the next item
    // (dead space), but reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // dead space that likely can never be used
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // If this bin is the last chance and next item is big, prefer using it now.
        if fitting_bins_count == 1 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: minimize waste directly.
        score -= 20.0;
    }

    // Scarcity pressure: if few bins can fit this item, favor using an existing one.
    if fitting_bins_count <= 2 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to residual or existing bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize new bins early; relax as stream progresses or bins fill up.
        score += 25.0 - 20.0 * progress - 15.0 * avg_fullness;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    }

    // Slight preference for bins below mean residual (keeps residuals balanced),
    // but avoid over-penalizing when item barely fits.
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 1.5;
    }

    // Mild encouragement to fill bins as the stream nears its end.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= horizon * 4.0;

    score
}

