pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions (1/4, 1/2, 3/4) and integer-division buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows superlinearly when post_residual falls in
    // "unusable" classes: (0,10) is nearly dead for future items (min size 1,
    // but small leftovers waste capacity on average).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 8.0;
    } else if post_residual < 50 {
        score -= 2.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10
    // are "harmonic" slots — small leftover classes pair well with
    // typical item sizes (multiples of 10).
    let residue = post_residual % 10;
    if residue == 0 {
        score -= 6.0; // perfectly harmonic leftover
    } else if residue <= 2 {
        score += 3.0; // sliver leftover, likely dead space
    }

    // Integer division thresholds: post_residual / 25 quarter-classes.
    let quarter = post_residual / 25;
    match quarter {
        0 => score += 5.0,  // <25: poor class
        1 => score -= 1.0,  // 25..49
        2 => score -= 3.0,  // 50..74
        _ => score -= 0.0,  // >=75: plenty of room, no bonus needed
    }

    // Lookahead coupling: if next item fits the post residual exactly
    // or nearly, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0) * 0.5;
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-item closure
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; mildly penalize large leftovers that
        // will strand capacity anyway.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins
    // score worse. Penalize opening a new bin when mean residual across
    // open bins is still substantial.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.3 + (open_bins_count as f64) * 0.5;
    }

    // Progress coupling: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

