    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by how fragmented open bins are.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = bin_capacity as f64 * 0.35 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, opening is fine
        }
        if fragmentation > 30.0 {
            score += 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        if next_fit < 10.0 {
            score -= 30.0 - 3.0 * next_fit;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: mild penalty for stranding space.
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect or near-perfect fit (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of the chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize slightly, since leftover may be dead space.
            score += 30.0;
        }
    }

    // Compare against mean residual: bins with residuals far below the mean are
    // "tight" bins; placing here consolidates waste.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f);
    } else {
        score += 0.3 * (resid_f - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit,
    // unless the current item is large and the new bin offers future flexibility.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let flexibility = (bin_capacity - item_size) as f64;
        // New bin starts at its capacity residual; subtract a bonus that grows with
        // remaining flexibility and early stream position (more future items to place).
        score -= 40.0 + 60.0 * (1.0 - progress) * (flexibility / bin_capacity as f64);
        // But if an existing bin has a very tight fit, prefer it over the new bin.
        if post_residual <= 10 && bin_residual == bin_capacity {
            score += 500.0;
        }
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

