        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // this placement breaks a possible next-item fit
        score += 6.0;
    }

    // Last-chance bonus: only one bin fits the item
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Time horizon: early in stream, favor consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0 * (1.0 - (open_bins_count as f64) / (open_bins_count as f64 + 5.0));

    // Prefer bins below mean residual (fill emptier bins less, keep balanced spread)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        score += 45.0 + 2.0 * open_bins_count as f64;
        // but if item is large and would leave big dead space elsewhere, new bin is fine
        if item_size >= 60 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, avoid opening bins for small leftovers
        if progress > 0.9 && item_size < 40 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
