    let mut score = pr;

    // Smooth non-linear coupling: reward small post_residual, modulated by progress
    let poly = x * x - 1.5 * x * x * x + 0.5 * x * x * x * x;
    score -= poly * cap * (0.5 + 0.5 * progress);

