    // Lookahead: penalize if post residual can't fit the next item but a smaller post residual could
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap); // next item still fits: small reward
        } else {
            score += 6.0 * (1.0 - progress); // wasted capacity for lookahead early on
        }
