    // Slight penalty for many open bins to discourage spreading
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate handling: prefer new bin only when residuals are large
    if bin_residual == bin_capacity {
        score = cap - pr + 10.0 + 40.0 * (1.0 - progress) - 30.0 * progress;
    }

    score
