    let pressure = open_bins_count as f64 / (2.0 + 20.0 * progress.max(0.05));
    score += 2.0 * pressure * fit_ratio;

    // Prefer bins below mean residual (more packed bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty for opening a new bin
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual < bin_capacity) {
            score -= 60.0; // no real alternative, open freely
        }
        // If item is huge and would leave a very empty new bin anyway, fine.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in stream with high pressure, discourage new bins more.
        score += 20.0 * pressure * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over progress
    let mut score = pr;

    // Smooth polynomial coupling: reward small post_residual more strongly late in stream
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 40.0 * poly;

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving space that fits the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (gap / cap) * (gap / cap);
        score += 15.0 * kernel - 8.0 * (1.0 - kernel.min(1.0));
    }

    // Mild penalty for too many open bins, smoothed by progress
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral-ish baseline with progress-dependent reluctance
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on
    // "useful" residue classes (multiples of small item sizes) are favored.
    let class = post_residual / 10; // integer-division class, 0..10
    let class_bonus = match class {
        0 => 0.0,          // perfect fit, best possible
        1 => 12.0,         // tiny dead space, nearly useless
        2 => 4.0,
        3 => 6.0,
        4 => 3.0,
        5 => 8.0,          // half-capacity leftover: reusable
        6 => 4.0,
        7 => 5.0,
        8 => 3.0,
        9 => 2.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if next item fits into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to how wasted the space is.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= 15.0; // nothing fits well elsewhere -> open new bin
        } else {
            score += 20.0 + mean_gap * 0.5; // decent fits exist -> discourage new bin
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit a minimum item (<=10)
    // are pure waste; penalize them heavily.
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // unusable dead space
    } else {
        // Usable residual: reward larger usable leftovers mildly, but reward tight fits more
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tightness reward: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless the current bin's
    // residual is small/unusable or the item fits very poorly.
    if bin_residual == bin_capacity {
        // Base new-bin penalty, relaxed when open bins can't help
        let pressure = (open_bins_count as f64) * 0.6;
        score += 15.0 + pressure;
        // If the item is large relative to capacity, a fresh bin is fine
        score -= 10.0 * fill;
        // If many bins already exist and mean residual is high, prefer reusing
        if mean_residual > 20.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual >= 10 {
            // dead space for next item: penalize if leftover too small for it
            score += 4.0;
        }
    }

    // Open-bin pressure: fewer open bins is better; mild reward for consolidating
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Early stream: be slightly more willing to open bins for good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space).
    if post_residual == 0 {
        score -= 200.0; // perfect fit: strongly preferred
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize proportionally to leftover waste after both
            let two_step_waste = post_residual - next_item_size;
            score -= 40.0 - two_step_waste as f64 * 0.5;
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3;
        }
    }

    // Compare against mean residual: prefer bins that are already tight
    // (below-mean residual means we're consolidating space well).
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize so it's chosen only when
    // no open bin gives a reasonable fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if nothing else fits, opening a bin is inevitable — soften penalty
        // when few bins are open early in the stream.
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // Late in stream, prefer closing out existing bins rather than spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Slight preference for using bins with larger residuals when many bins open,
    // to encourage consolidation into fewer bins.
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * item_size as f64;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0; // leftover too small for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or late in the stream; relax slightly early when open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 {
            score += 10.0; // plenty of collective space already open
        }
    }

    // Prefer filling bins that deviate from the mean residual (consolidate).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * dev;

    // Mild reward for using bins with larger residual when many bins are open.
    score -= 0.1 * bin_residual as f64 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits: small post_residual relative to capacity
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * norm_next * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 8.0 * norm_next * norm_pr;
    }

    // Penalize dead space when many bins fit (avoid wasting flexible bins)
    if fitting_bins_count > 1 {
        score += 5.0 * norm_pr * (fitting_bins_count as f64).ln();
    }
    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: keep it moderately attractive early, less so late
    if bin_residual == bin_capacity {
        score = score * 0.9 + 20.0 * (1.0 - progress) + 10.0 * norm_item;
        if open_bins_count as f64 > mean_residual.max(1.0) / cap.max(1.0) * (open_bins_count as f64 + 1.0) {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space is far worse in low
    // classes (small residuals that nothing can ever use).
    let class = (post_residual / 10).min(9) as f64;
    score += (9.0 - class) * class * 0.9;

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual
    // exactly or tightly; penalize residual classes that strand the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 25.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // Next item won't fit: residual becomes dead unless very small.
            if post_residual >= 10 {
                score += 12.0;
            } else {
                score -= 8.0; // tiny dead space is acceptable
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would be left with a large unusable residual.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + crowded * 0.4 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Penalize leaving residual far from mean (fragmenting the pool).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Mild preference to fill already-open bins early in the stream.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=10) are highly undesirable.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 2.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 6.0; // mildly awkward zone
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is well-matched to the item (tight fit).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Lookahead: if the next item fits exactly in the post residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in post residual but this bin closes nicely, slight bonus.
    if next_item_size > 0 && post_residual < next_item_size && post_residual <= 10 {
        score -= 3.0; // closing the bin avoids stranded space
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins,
    // encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost plus pressure.
        score += 15.0 + pressure * 2.0;
        // Opening a new bin is acceptable if mean residual of open bins is low
        // (existing bins nearly full) or next item is large.
        if next_item_size >= 60 && mean_residual < 40.0 {
            score -= 20.0;
        }
    } else {
        // Filling existing bins is rewarded proportional to open-bin pressure.
        score -= pressure.min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match => big reward; loose match => mild penalty.
        if match_gap <= 5.0 {
            score -= 40.0 * (1.0 - match_gap / 5.0);
        } else {
            score += (match_gap - 5.0).min(30.0) * 0.3;
        }
        // Exact two-item fill is ideal.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Prefer bins already below the mean residual (tighter bins fill first),
    // penalize bins far above mean residual (wasteful placement).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Reward good fits now (small post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the new-bin candidate unless current bins are mostly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 30.0 * avg_fill;
    }

    // Late in the stream, be more conservative about leaving slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fills bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = mean_residual - item_size as f64;
        // If mean residual barely fits the item, prefer existing bins.
        if avg_fit_gap < 15.0 {
            score += 40.0;
        } else {
            score += 10.0 + 20.0 * progress;
        }
        // More open bins -> prefer consolidation into existing bins.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward using fuller bins (best-fit style): lower residual bins preferred.
        score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);
        // Slight penalty when many bins can fit: prefer the fullest one anyway.
        if fitting_bins_count > 2 {
            score += 1.5 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Mild global pressure: early in stream, be picky; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: bin far below mean residual is "wasted" capacity.
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = pr / cap;

    // Smooth base: quadratic coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 0.35 * cap * progress * norm_post;

    // Non-linear waste penalty: dead space that is too small to be useful.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = pr - next;
        if gap >= 0.0 {
            // Post residual can host the next item: smooth reward scaled by fit tightness.
            let tight = 1.0 - (gap / cap);
            score -= 12.0 * tight * tight * (gap / cap);
        } else {
            // Dead space relative to next item: smooth cubic-ish penalty.
            let dead = (-gap) / cap;
            score += 10.0 * dead * dead * (2.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Scarcity coupling: fewer fitting bins => prefer tighter fills (small post_residual).
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score += scarcity * pr * 0.5 * (1.0 - progress);

    // Penalize bins far from mean residual when open bins are plentiful (encourage consolidation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).ln().max(1.0) * 0.3;

    // Mild reward for high fill ratio, smoothed by progress.
    score -= 4.0 * (1.0 - norm_post) * (1.0 - norm_post) * progress;

    // New-bin candidate: keep neutral baseline so it's chosen only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Harmonic class of post_residual: exact quarter/half fills are excellent
    let cap = bin_capacity as u32;
    let quarter = cap / 4;
    let half = cap / 2;
    let three_quarter = 3 * quarter;
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual == quarter || post_residual == three_quarter {
        score -= 8.0;
    } else if post_residual == half {
        score -= 5.0;
    } else if post_residual % 10 == 0 {
        score -= 2.0; // decile residuals are reusable
    } else {
        // penalize awkward small dead space
        if post_residual < 10 {
            score += 15.0; // dead space below min item size
        } else if post_residual < 20 {
            score += 6.0;
        }
    }

    // Integer-division threshold classes on residual
    let res_class = post_residual / 20; // 0..5
    score += res_class as f64 * 1.5;

    // Lookahead: can next item fill the post_residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            // next item cannot fit here -> residual becomes dead unless reusable later
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // existing fits are poor (high post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        // empty bin score = penalty that shrinks when fits are bad
        score = 0.55 * bin_capacity as f64 - 0.4 * (fitting_bins_count as f64) - (poor_fit * 20.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Stream progression: later in stream, be greedier about closing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // Slight preference to balance load across bins
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1,
    // but practically gaps < ~10 are hard to use) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space is quadratic-penalized relative to capacity.
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.6 * (25.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 5.0; // leftover useless for next item
        }
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins implicitly by rewarding consolidation).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below mean (filler bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline, only chosen when all fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 30.0 * match_quality * match_quality;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Post-residual too small for the next item: penalize dead space, more so if tiny.
        score += 0.5 * (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Reward closing the bin perfectly (zero waste).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare against mean residual: favor bins that are already relatively full.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, allow opening new bins more freely (keep score of empty bin moderate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin, discounted early.
        score = bin_capacity as f64 - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: penalize if next item could have used the leftover space.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // leftover is dead space for the next item; penalize proportionally
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 8.0 * waste;
        } else {
            // next item fits in the leftover: reward a chained placement
            let chain = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 * chain;
            // extra reward if the chain nearly exhausts the bin
            if post_residual - next_item_size < 10 {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 3.0 * open_pressure;

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (keeps bin pool homogeneous), unless a very tight fit is available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream, be slightly more willing to open new bins (exploration);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Brand-new empty bin candidate: neutral base but penalize slightly unless
    // the item is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 5.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 12.0 * poly * (0.5 + progress);

    // Penalize large dead space more as stream progresses
    score += 0.5 * pr_norm * pr_norm * progress * 20.0;

    // Reward tight fits (small post_residual) with smooth quadratic term
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let slack = ((pr as u32).saturating_sub(next_item_size)) as f64 / cap;
        score -= 6.0 * fits_next * (1.0 - slack * slack);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr).abs();

    // Slight preference to keep many bins consolidated early
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Residuals in "nice" classes (multiples of 10, 20, 25, 50) are more
    // likely to be fillable by future items, so reward them.
    let pr = post_residual;
    let nice_bonus = if pr == 0 {
        40.0 // perfect fit, heavily rewarded
    } else if pr % 50 == 0 {
        18.0
    } else if pr % 25 == 0 {
        12.0
    } else if pr % 20 == 0 {
        10.0
    } else if pr % 10 == 0 {
        7.0
    } else if pr % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= nice_bonus;

    // Dead-space penalty: tiny unusable residuals are bad. Items range
    // 1..100, so anything < some threshold may be dead weight.
    if pr > 0 && pr < 10 {
        score += 15.0;
    } else if pr > 0 && pr < 20 {
        score += 5.0;
    }

    // Integer-division threshold on post_residual: how well does the
    // residual "chunk" relative to typical item granularity?
    let chunk = pr / 10; // number of 10-sized chunks
    score -= chunk as f64 * 0.8;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a harmonic pair - reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if pr >= next_item_size {
            let next_post = pr - next_item_size;
            // reward if next item leaves another nice residual
            if next_post % 10 == 0 {
                score -= 8.0;
            }
            if next_post < 10 && next_post > 0 {
                score += 6.0; // next placement would create dead space
            }
        } else {
            // next item cannot fit here regardless; mild penalty for
            // leaving a residual that blocks the lookahead chain
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when current bin fits are poor (large post_residual or dead space).
    if bin_residual == bin_capacity {
        // Base reluctance: prefer filling existing bins when fit is decent.
        score += 12.0;
        // But if the item leaves a huge residual everywhere else, allow it.
        if post_residual >= 55 {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheaper (more future items to
        // distribute); late in stream, squeeze into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 6.0;
        // Many open bins with high mean residual: don't open more.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Prefer tighter fits overall (post_residual already dominates).
    // Slight penalty proportional to fragmentation of the bin.
    let frag = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += frag * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; treat anything below ~10 as dead space with superlinear penalty.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 + progress) * 0.8;

    // Lookahead (k=2): if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another gap: mild reward scaled by fit quality
            let nxt_left = post_residual - next_item_size;
            score -= 8.0 - (nxt_left as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize residuals just below next_item_size
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            }
        }
    }

    // Prefer bins with residuals near the mean (keep pool homogeneous),
    // but slightly favor tighter-than-mean bins.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev.abs() * 0.3 - dev * 0.15;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = (bin_capacity as f64) * 0.95 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        } else if fitting_bins_count == 1 {
            score += 30.0; // discourage stealing the last-chance bin
        }
        // early stream: new bins are cheaper to open
        score -= progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small dead space is valuable).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size, and penalize near-misses that
    // strand the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here; reward tight two-item packing
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover; penalize stranded gap
            score += 40.0 + 2.0 * gap;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit style), but
    // penalize bins far looser than the mean (wasteful use of a roomy bin).
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Mild penalty for spreading across many open bins; encourages
    // consolidation when bins are plentiful.
    score += 0.3 * open_bins_count as f64;

    // Slight early-stream preference for filling bins aggressively,
    // late-stream preference for consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small leftover relative to item size
    let tight = post_residual as f64 / item_size.max(1) as f64;
    score -= 60.0 / (1.0 + tight);

    // Penalize dead space that nothing in the typical size range can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead coupling: reward residual that can host the next item exactly,
    // penalize residual that nearly-but-not-quite fits the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            score -= 40.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 35.0; // next item won't fit here; wasted space
        }
        // Bin that fits both current and next item is valuable
        if bin_residual >= item_size + next_item_size {
            score -= 70.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is empty
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins are crowded
        let crowding = mean_residual / bin_capacity as f64;
        score += 120.0 + 300.0 * (1.0 - crowding);
        // Early in the stream, opening bins is cheaper; late, avoid fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // If many bins already open, discourage more
        score += 8.0 * open_bins_count as f64;
    } else {
        // Favor filling bins that are already relatively full
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 50.0 * fill;
        // Reward bins whose residual is below the mean residual (more packed than average)
        if (bin_residual as f64) < mean_residual {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Mild preference to consolidate when many open bins exist
    score += 3.0 * open_bins_count as f64;

    // Late-stream urgency: squeeze items into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize leaving dead space that the next item likely can't use
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 30.0 * waste * waste;
        if next_item_size as f64 <= pr {
            score -= 15.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    }

    // Deviation from mean residual: prefer bins below average residual (more filled)
    score += 3.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: divide capacity into 4 bands.
    let q = post_residual / (bin_capacity / 4).max(1);
    // Dead-space penalty grows superlinearly in the smallest band.
    match q {
        0 => score += 12.0,                                   // < 25% left: nearly dead
        1 => score += 4.0,                                    // 25-50%
        2 => score += 1.0,                                    // 50-75%
        _ => {}                                               // 75-100%: fine
    }

    // Modulo classes: residuals that are multiples of 10 pair well with
    // typical item sizes; reward exact divisibility structure.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let nq = next_item_size / (bin_capacity / 4).max(1);
            score -= 4.0 + nq as f64;
        } else {
            // Next item won't fit here anyway; slight penalty for wasting a big slot.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 10.0;
        score += 15.0 - crowding - 5.0 * progress;
        // If mean residual is large, prefer existing bins.
        score += mean_residual * 0.05;
    } else {
        // Mild reward for packing into tight (small-residual) bins first: best-fit core.
        score += (bin_residual as f64 - post_residual as f64) * 0.0;
        // Prefer bins whose residual is close to the item (tight fit).
        score -= (bin_capacity as f64 - (bin_residual as f64 - item_size as f64).abs()) * 0.02;
    }

    // Mean-residual coupling: when average residual is low, waste hurts more.
    score += post_residual as f64 * (mean_residual / bin_capacity as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit anything are pure waste.
    // Items are 1..=100, so a residual of 0 is perfect; small residuals are bad.
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    } else if post_residual < 10 {
        score += 40.0; // nearly-dead space: penalize hard
    } else if post_residual < 25 {
        score += 15.0; // small gap: mildly penalize
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from many open bins: prefer closing out existing bins
    // rather than spreading items thinly.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_ratio = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * lookahead_ratio;
    }
    // If next item would be blocked by a small leftover, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Prefer bins below mean residual (larger-than-average bins absorb big items,
    // keeping small bins for small items).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: discourage opening a new bin unless the item is large
    // or no good existing option exists (handled via fitting_bins_count bonus above).
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is less costly (no future to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: reward when next item could fit with little waste.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize more as dead space grows.
        let dead = (post_residual - next_item_size) as f64;
        score += 0.15 * dead;
    }

    // Penalize small unusable residuals (dead space), unless it's a near-perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward tight fits relative to the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Compare against mean residual: prefer bins that are relatively full already.
    if mean_residual > 0.0 {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item is large or
    // no good fit exists among open bins; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 70 || fitting_bins_count == 0 {
            score -= 35.0;
        } else {
            score += 25.0 - 10.0 * early;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of item size relative to capacity
    let size_frac = item_size as f64 / bin_capacity as f64;

    // Tightness of fit: reward near-perfect fits (small post_residual relative to item)
    let tightness = if item_size > 0 {
        (bin_residual as f64 - item_size as f64) / item_size as f64
    } else { 0.0 };
    score += tightness * (1.0 + 2.0 * size_frac);

    // Strong reward for exact fit
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 7.0;
    }

    // Penalize leaving dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable gap is bad unless exact
    }

    // Lookahead: if next item fits into the post-residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 6.0 * (1.0 - progress);
        // extra reward if next item exactly consumes what's left
        if next_item_size == post_residual {
            score -= 12.0;
        }
    }
    // If next item would NOT fit here but would fit elsewhere, mild penalty
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 3.0 * (1.0 - size_frac);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to encourage diversity of residual sizes
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: residual == capacity means fresh bin
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is discouraged unless the item is large or fits poorly anywhere
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        let bad_fit_elsewhere = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // New bin baseline: post_residual = capacity, so it's naturally high; add penalty
        score += 12.0 + 10.0 * pressure * (1.0 - progress) - 30.0 * bad_fit_elsewhere;
        // Very large items open new bins more readily
        if size_frac > 0.7 {
            score -= 10.0;
        }
        // Small items should almost never open a new bin
        if size_frac < 0.3 && fitting_bins_count > 0 {
            score += 25.0;
        }
    } else {
        // Reward using bins with larger residuals (waste big holes first)
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    if open_bins_count > 5 && mean_residual > 30.0 && !is_new_bin {
        score -= 2.0;
    }

    // Time horizon: late in stream, be greedier (minimize post residual more aggressively)
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - prn); // peaks mid-range residual
    score -= 20.0 * poly * (1.0 + 2.0 * progress);

    // Penalize residual that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0 * (1.0 - prn) * (1.0 + progress);
    }
    // Reward residual that fits the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 * prn;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }
    // Penalize when many bins could fit (encourage tightest fit selection via residual)
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln() * 1.5;
    }

    // Coupling with mean residual: bins far below mean residual are less attractive late
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    // Mild pressure to open new bins early when residuals are high
    score += 2.0 * prn * (1.0 - progress) * (open_bins_count as f64).sqrt().ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: penalize dead space in "hard to fill" bands
    let pr = post_residual as i64;
    let class = pr / 10; // decade classes 0..10
    let dead_penalty = match class {
        0 => -20.0,          // 0-9 residual: near perfect
        1 => 5.0,            // 10-19
        2 => 12.0,
        3 => 18.0,
        4 => 22.0,
        5 => 15.0,           // ~50 residual: half-full, moderately useful
        6 => 10.0,
        7 => 6.0,
        8 => 2.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Modulo coupling: residual that matches common item sizes is more reusable
    let reusable = [0u32, 10, 20, 25, 30, 40, 50, 60, 70, 80]
        .iter()
        .any(|&s| s <= post_residual && post_residual - s < 5);
    if reusable {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 60.0 * (1.0 - slack as f64 / 50.0).max(0.0);
        } else {
            // next item cannot fit here: residual becomes waste if nothing else fits
            score += 10.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses or many bins open
        score += 80.0 + 150.0 * progress + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // new bin useful if next item also large
        }
    }

    // Small penalty for exact-capacity-fraction placements (harmonic halves/quarters)
    let cap = bin_capacity as u32;
    if post_residual == cap / 2 || post_residual == cap / 4 || post_residual == 3 * cap / 4 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to hold even the
    // smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Dead-space penalty grows sharply for tiny-but-nonzero leftovers.
    if post_residual > 0 {
        let dead = (min_item as f64 / post_residual as f64).powf(2.0);
        score += 50.0 * dead;
    }

    // Reward tight fits (small post_residual) with a strong subtraction.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is small, opening a fresh bin
        // may be the only way to avoid a terrible fit.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in this bin's post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin_candidate {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // Reward a good chain: small leftover after the *next* item too.
            let post2 = post_residual as f64 - next;
            score -= (bin_capacity as f64 - post2) * 0.35;
            // Bonus if next item fills bin nearly perfectly after this placement.
            if post2 <= 5.0 {
                score -= 12.0;
            }
        } else {
            // Penalize dead space the next item cannot use.
            score += (next - post_residual as f64).min(30.0) * 0.55;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers),
    // but allow deviation when it yields a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins as stream progresses (encourage packing into existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    // Mild penalty for large residual waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual can host the next item: bonus scaled by how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= snug * 8.0;
        } else {
            // Dead space for the lookahead item: penalty grows with wasted gap.
            let gap = (post_residual as f64) / (next_item_size as f64).max(1.0);
            score += gap * 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins that are already well used (low residual relative to capacity).
    let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= used_frac * 6.0;

    // Time horizon: early in the stream, be conservative (keep residuals flexible);
    // later, push harder to close bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * fit_ratio * 5.0;

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than opening more.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += consolidation * 2.0;
        score -= 3.0; // mild bias toward existing bins when many are open
    }

    // New-bin candidate handling: empty bin is attractive only if current item is large
    // or no good fit exists; otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            // Large item: a fresh bin is fine, slight discount.
            score -= 5.0;
        } else {
            // Small item into a new bin wastes capacity unless it's a last resort.
            let penalty = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
            score += penalty + (bin_capacity - item_size) as f64 * 0.2;
        }
        // Late in the stream, avoid spawning bins that will barely be used.
        score += progress * 6.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small but nonzero leftover: mild reward, hard to reuse.
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core: reward tight fits (low post_residual), non-linearly.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = 10.0 * (x * x * (3.0 - 2.0 * x)) * cap; // smoothstep-style dead-space penalty

    // Interaction: as stream progresses, demand tighter fits more strongly.
    score += 20.0 * progress * x * x * cap;

    // Penalize bins whose residual deviates badly from the mean residual (imbalance).
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate handling: residual == capacity means fresh bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when the item is large (few bins
        // could ever fit it well) or late in the stream with many open bins.
        score += 45.0 - 0.35 * item + 0.05 * (open_bins_count as f64) - 20.0 * progress;
    } else {
        // Mild reward for keeping bins count low.
        score -= 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "friendly"
    // residue classes (multiples of small divisors) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;

    // Reward tight fits: near-full bins are excellent.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Modulo-class bonus: leftovers divisible by 10 (and 5) match the
    // granularity of typical item sizes, so they remain usable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer-division dead-space classes: leftovers in awkward bands
    // (just above common item sizes) get penalized.
    if post_residual > 80 {
        score += 6.0; // very empty bin after a small item: wasteful placement
    } else if post_residual > 60 {
        score += 2.0;
    }

    // Harmonic threshold: leftover just under a "half" class is worst.
    let half = post_residual / 2;
    if half > 40 && post_residual < 90 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack.min(30) as f64) * 0.4;
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current bins
    // are already well-packed (high mean fill) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fill = 1.0 - mean_residual / cap;
        // Penalize new bins, less so late in the stream when bins are full.
        score += 30.0 - 20.0 * mean_fill - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score -= (fill_frac * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals too small for typical future items are costly.
    // Treat gaps < 10 as pure dead space; penalize quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Penalize medium gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 3.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still host the next item.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is below the mean (more filled bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (residual of new bin equals capacity; make it unattractive by default,
    // but competitive when current fit would waste a lot).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 60.0 + open_bins_count as f64 * 2.0;
        // If the best alternative would leave big dead space, allow new bin.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-residual that exactly matches
    // the next item (perfect chaining), or a near match.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after next placement is still good
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Tight fit now: reward small post residual relative to item size.
    score -= 0.8 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins below mean residual are already tight;
    // prefer spreading load when mean residual is high.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements
    // would leave large waste; an empty bin has huge residual which is naturally
    // high-scored, but add explicit penalty that shrinks late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (post_residual as f64 / bin_capacity as f64) * (1.0 - progress);
        score += 15.0 + 20.0 * waste_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) super-linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Penalize dead space that no plausible future item (>= 10, or >= 1) can use.
    let min_item = if total_items > 0 { 1.0 } else { 10.0 };
    if (post_residual as f64) < min_item {
        score += 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty for leaving large unusable gap.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bonus: only bin that fits avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer fuller bins relative to global mean residual (balance exploitation).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (preserve flexibility); late, consolidate tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bins are crowded or fit is poor.
        let crowding = (open_bins_count as f64) / (1.0 + t * 10.0);
        score += 25.0 + crowding - 20.0 * t;
        if fitting_bins_count == 0 {
            score -= 1000.0; // forced new bin
        }
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 15.0 * t;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but penalize very small dead space (unusable slivers)
    let mut score = pr as f64;
    let sliver = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += 12.0 * (1.0 - sliver);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, keep bins roomy; late, pack tight aggressively.
    let tight = norm_pr * norm_pr * (0.5 + 1.5 * progress);
    score += 30.0 * tight;

    // Interaction: post_residual vs next item lookahead — bonus if next item fits
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            let snug = 1.0 - ((pr - next) / cap);
            score -= 18.0 * snug * (0.4 + 0.6 * progress);
        } else {
            score += 10.0 * (next - pr) / cap;
        }
    }

    // Last-chance bin: strongly reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_pr);
    }

    // Relative to mean residual of open bins: prefer bins deviating from mean
    // to balance the portfolio early, but converge to tightest bin later.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (1.0 - progress) * 8.0 * dev * dev - progress * 6.0 * dev;

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let crowd = mean_residual / cap;
        score = cap * (0.35 + 0.65 * (1.0 - crowd)) + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space via integer division.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual / 10).min(10) as f64; // 0..10 harmonic bucket

    // Reward perfect or near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Penalize residuals in the "dead zone" (11..30) that few future items can use.
    if post_residual > 10 && post_residual < 30 {
        score += 60.0;
    }

    // Modulo arithmetic on capacity fractions: residuals that are multiples of 10
    // harmonize with the item-size grid and are more reusable.
    if post_residual % 10 == 0 {
        score -= 40.0;
    } else {
        score += (post_residual % 10) as f64 * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a chain fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: mild penalty scaled by waste.
            score += ((next_item_size - post_residual) as f64).min(cap) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - post / cap);
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (already via post_residual),
        // but add mild penalty to spread pressure.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when existing fits are poor (post_residual large).
    if bin_residual == bin_capacity {
        // Neutral baseline: new bin costs one extra bin, so slightly disfavored,
        // but its post_residual (== capacity) is large which naturally hurts it.
        score += 25.0;
    }

    // Stream progression: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post / cap);

    // Deviation from mean residual: prefer bins whose residual is below mean
    // (tighter bins) to keep large-residual bins available for big items.
    score += (mean_residual - post) * 0.5;

    // Harmonic class bonus: small class index (small residual) is better.
    score -= class * class * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Penalize large post residuals only mildly (they stay usable),
    // but reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Allow new bin when existing fits are very poor.
        if post_residual == bin_capacity && fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild preference to fill bins below mean residual (tighter bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Stream progression: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect lookahead match is a jackpot.
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Penalize leaving dead space that next item can't use.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual (fuller) bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize creating large unusable gaps (dead space) unless lookahead can use them.
    let gap = post_residual as f64;
    if next_item_size == 0 || gap < next_item_size as f64 {
        score += 0.2 * gap * gap / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && (post_residual as f64 <= 5.0
                || (next_item_size > 0 && post_residual == next_item_size));
        if good_fit_exists {
            score += 500.0; // keep using existing bins
        } else {
            score -= 20.0 + 0.1 * open_bins_count as f64; // allow fresh bin
        }
    }

    // Late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating small unusable gaps that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if next item fits perfectly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += 3.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 15.0 * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: prefer the fullest (small residual) more strongly.
    if fitting_bins_count > 2 {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: early in the stream, be pickier about dead space;
    // late in the stream, prioritize consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage closing them out (filling existing bins).
    score -= 0.3 * open_bins_count as f64 * tightness;

    // Mean residual coupling: prefer bins whose residual is below average
    // (they are "fuller" than typical), reward using them.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 40.0 }
                      else if next_item_size > 0 && (bin_capacity as f64 - mean_residual) < next_item_size as f64 { 15.0 }
                      else { 6.0 };
        // Early stream: opening fresh bins is cheap; late: expensive.
        score = (post_residual as f64) - urgency + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (0.5 + 0.5 * progress);

    // Dead-space penalty: very small post-residuals are wasted space
    let dead = -(norm_pr * (1.0 - norm_pr)) * (1.0 + progress);

    // Lookahead: reward bins whose post-residual can fit the next item
    let lookahead = if next_item_size > 0 && next_item_size as f64 <= pr {
        -0.5 * (1.0 - progress)
    } else {
        0.15 * progress
    };

    // Last-chance bin bonus
    let last_chance = if fitting_bins_count == 1 { -0.3 } else { 0.0 };

    // Prefer tighter-than-average bins mildly
    let mean_term = 0.1 * (mean_residual - pr) / cap;

    let mut score = pr + 20.0 * poly + 10.0 * dead + lookahead * 10.0 + last_chance * 10.0 + mean_term * 10.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space bands via modulo classes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Fraction of capacity wasted after placement.
        let waste_frac = pr as f64 / cap;
        score += waste_frac * 60.0;

        // Harmonic classes: residuals that are multiples of common item sizes
        // (10,20,25,50) are more reusable.
        let reusable = pr % 10 == 0 || pr % 25 == 0 || pr == 50;
        if reusable {
            score -= 25.0;
        } else if pr < 10 {
            // Tiny dead space: unusable for items >= 10.
            score += 40.0;
        }

        // Non-linear coupling: penalize mid-band residuals that nothing fits.
        if pr > 0 && pr < 20 {
            score += 30.0 * (1.0 - (pr as f64) / 20.0);
        }

        // Lookahead: does the next item fit exactly into the post residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if next_item_size <= pr {
                score -= 10.0 + 0.3 * next_item_size as f64;
            } else {
                score += 15.0;
            }
        } else {
            // Last item: prefer tightest fit.
            score += 0.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are poor (fragmented) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // Penalize opening a new bin moderately; less when fragmentation is high.
        score += 55.0 - 40.0 * fragmentation.min(1.0) + 20.0 * progress;
        // If next item is large, a fresh bin preserves room for it.
        if next_item_size > 60 {
            score -= 25.0;
        }
    } else {
        // Slight preference for tighter existing bins beyond post_residual.
        score += 0.15 * (bin_capacity - bin_residual) as f64 / cap;
    }

    // Mild scaling with open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below smallest item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is highly rewarded.
        score -= 25.0;
    } else {
        // Moderate gaps that can still hold small items: mild reward for tightness.
        score -= (post_residual as f64) * 0.15;
    }

    // Penalize gaps too small for the lookahead item if it would otherwise force a new bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing bins.
    let pressure = (open_bins_count as f64) * 0.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current item is large relative to
    // residuals of open bins, or when few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream length.
        let mut new_bin_cost = 30.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // Cheaper to open a new bin when many bins already fit the item poorly elsewhere.
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        // If item is large, a fresh bin wastes less.
        new_bin_cost -= (item_size as f64) * 0.2;
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.89;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Wasted capacity for the known next item.
            score += 4.0;
        }
        // Perfect chain fit: post residual exactly matches next item.
        if post_residual as u32 == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins with slack -> prefer consolidating into fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap.max(0.0);
    score -= 0.05 * residual_gap.min(0.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor empty-bin candidates); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 30.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        score -= 6.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with a smooth non-linear penalty
    // that grows super-linearly for large dead space.
    let mut score = pr * (1.0 + norm_pr * norm_pr * 2.0);

    // Stream-progress coupling: early in the stream, tolerate slack (bins can absorb
    // future items); late in the stream, aggressively minimize post_residual.
    let tightness = 1.0 + progress * 1.5;
    score *= tightness;

    // Smooth interaction: post_residual vs mean_residual deviation, damped by progress.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // (penalize opening a new bin) with a smooth decay as post_residual grows.
    if fitting_bins_count == 1 {
        score -= (cap - pr) * 0.8;
    }

    // Lookahead: reward bins whose post_residual can still host the next item,
    // scaled by how much slack remains relative to capacity.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let next_norm = next_item_size as f64 / cap;
        score -= fits_next * cap * 0.25 * (1.0 - next_norm) * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins when residuals are large.
    score += (open_bins_count as f64).ln_1p() * norm_pr * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "useful"
    // residue class (divisible by 5 or >= next item size) are rewarded.
    let next = next_item_size.max(1);
    let usable = post_residual >= next;
    let class = post_residual % 10;

    if usable {
        score -= 8.0; // leftover can host the lookahead item
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if class == 0 {
        score -= 4.0; // residue class aligned with common item sizes
    } else if post_residual < 10 {
        score += 30.0; // dead space below minimum item size
    } else {
        score += 10.0;
    }

    // Fractional capacity fill: reward high fill ratio non-linearly.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Penalize very tight fits that barely squeeze the item in when the
    // lookahead item is large (would be stranded).
    if !usable && next > post_residual && next > 40 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default neutral-ish score based on capacity;
    // open a fresh bin only when no open bin fits well (post_residual
    // there would be large, so open bins win when fit is decent).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 6.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // Many open bins with large mean residual: discourage new bins.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > next as f64 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to hold anything useful
    // (smaller than the minimum plausible item) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(item_size)) {
        score += 25.0;
    }
    // General super-linear dead-space aversion.
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is cheaper.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate: make it attractive only when existing residuals
    // are large/fragmented; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        score = 0.6 * bin_capacity as f64
            + 2.0 * open_bins_count as f64
            - 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the pair well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            score += 10.0 + 0.5 * diff; // next item cannot reuse residual well
        }
    } else if next_item_size == 0 {
        // Last item: just minimize waste
        score += 5.0;
    }

    // Penalize small dead space (unusable residual) more than proportionally
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Favor bins tighter than average residual (good fits leave less than mean)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin leaves bad residual
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // opening fresh bin is reasonable when item is large / next is large
            score -= 40.0;
        }
    }

    // Late in stream: consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no plausible item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // small slivers are nearly unusable
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; slight penalty proportional to wasted opportunity.
        score += 5.0;
    }

    // Global state coupling: prefer filling bins when many bins are open.
    let open_f = open_bins_count as f64;
    score -= 2.0 * open_f.max(1.0).ln() * (1.0 - tightness);

    // Mean residual coupling: if this bin is much tighter than average, favor it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Time horizon: early in the stream, be more liberal about opening bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * tightness;
    score -= 8.0 * progress * (1.0 - tightness);

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if current bin would leave a very poor fit, new bin becomes competitive.
        if post_residual > 0 && post_residual < 15 {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening bins.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + progress) - pr_norm * progress * progress;

    let mut score = pr;
    score += 40.0 * poly;

    // Reward tight fits smoothly (low post residual)
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize waste relative to mean residual
    score += 0.3 * (pr - mean_residual);

    // Last-chance bonus: few fitting bins
    if fitting_bins_count <= 1 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose leftover fits the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as f64 >= ni {
            score -= 15.0 * (ni / cap);
        } else {
            score += 10.0 * (ni / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals in fine-grained classes (small modulo buckets) are more reusable.
    let class_width = 10u32;
    let class = post_residual / class_width;
    let class_offset = post_residual % class_width;

    // Reward small residuals that fall into "harmonious" classes (multiples of 10, 20, 25, 50)
    let harmonic = (post_residual % 10 == 0) as f64 * 4.0
        + (post_residual % 20 == 0) as f64 * 3.0
        + (post_residual % 25 == 0) as f64 * 3.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= harmonic;

    // Penalize mid-range dead space: residuals that are too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly dead space
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Class-level preference: lower class index (tighter fit) is better
    score += class as f64 * 2.0;
    // Small nudge by offset within class (finer fit preferred)
    score += class_offset as f64 * 0.1;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nxt_class = next_item_size / class_width;
            let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / class_width as f64;
            score -= fit_quality * (4.0 + nxt_class as f64);
            // harmonic match between post_residual and next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to excess
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits more aggressively
        score += 2.0 * (fitting_bins_count.min(10) as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate logic: only attractive when open bins would leave bad residuals
    if bin_residual == bin_capacity {
        let bad_fit_pressure = if post_residual >= 0 {
            // estimate: would placing in mean open bin leave worse residual?
            let mean_post = mean_residual - item_size as f64;
            if mean_residual > 0.0 && mean_post > post_residual as f64 {
                (mean_post - post_residual as f64) * 0.8
            } else {
                -8.0
            }
        } else { 0.0 };
        // early in stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + bad_fit_pressure + progress * 20.0
            - (open_bins_count as f64 * 0.3);
        // new bin is fine if item is large relative to capacity
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Slight global preference for filling bins tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    // Mean residual coupling: when mean residual is high, be pickier about waste
    score += (mean_residual / bin_capacity as f64) * (post_residual as f64 * 0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size is 1, but tiny gaps waste capacity); penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-to-medium dead space that few items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chains good placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize proportionally to wasted potential.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and penalize opening new bins (new-bin candidate has residual == capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 1.5 * progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when few bins are open
    // or the item fits nowhere well; otherwise the pressure term pushes it up.
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strong reward for an exact 2-step lookahead match: post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Reward when the next item can still fit in the resulting residual (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * next_item_size as f64 * (1.0 - progress);
    }

    // Penalize dead space that cannot hold the next item, scaled by tightness of stream.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 1.5 * (next_item_size - post_residual) as f64 * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline so that
    // only genuinely poor fits among open bins lose to it.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 0.5 * item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        score += 40.0 * progress;
        // If only one bin fits, never open a new one.
        if fitting_bins_count == 1 {
            score += 10000.0;
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer filling bins with larger items when many bins are open.
    score -= 0.2 * item_size as f64 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to typical item size scale.
    if post_residual > 0 && post_residual < item_size {
        score += 4.0; // small but unusable-looking gap for similar items
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening new bins is cheap early, expensive late (fewer chances to fill them).
        score = 30.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.5 {
            score -= 5.0; // room for the lookahead item in a fresh bin
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 3.0; // lookahead item won't fit here; mild penalty
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (tighter bins) to reduce fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Slight preference to use bins when many are open (avoid bin proliferation).
    score -= 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / capacity;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Penalize large dead space quadratically as stream progresses
    score += 40.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - post) / capacity;
    }

    // Mild penalty relative to mean residual to prefer below-average fills early
    score += 0.15 * (post - mean_residual) * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight early bias toward opening bins
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * progress - 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: residual below 10 is near-perfect packing
    if post_residual < 10 {
        score -= 15.0;
    }

    // Harmonic class analysis on post_residual (mod 10 classes)
    let cls = post_residual % 10;
    if cls >= 1 && cls < 5 {
        // Awkward small dead space class: penalize proportionally
        score += 3.0 + cls as f64;
    } else if cls == 0 && post_residual > 0 {
        // Exact decile residual: pairs well with common item sizes
        score -= 5.0;
    }

    // Integer-division threshold: residual that can host another mid-size item
    let half = bin_capacity / 2;
    if post_residual >= half {
        score += 2.0; // large leftover suggests this bin was under-filled
    }

    // Lookahead coupling: can this bin also host the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin before opening a new bin: strongly favor it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize so it only wins when no open bin fits decently
    if bin_residual == bin_capacity {
        score += 8.0 + item_size as f64 * 0.15;
    }

    // Stream progression: later in the stream, consolidate more aggressively
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 2.0;

    // Mean residual context: if this bin is far below mean residual, it is already crowded; prefer it
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are "dead". Penalize small-but-nonzero gaps hard.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead zone: gap below ~20 cannot fit most items (sizes 1..100, but
        // tight fits waste capacity). Quadratic penalty in the dead zone.
        if post_residual < 20 {
            score += (20.0 - pr) * (20.0 - pr) * 2.5;
        } else if post_residual <= 40 {
            // Semi-usable zone: mild penalty to prefer larger leftovers.
            score += (40.0 - pr) * 1.5;
        } else {
            // Comfortable residual: reward proportionally.
            score -= (pr - 40.0) * 0.8;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Exact-fit lookahead: if the next item exactly consumes post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits comfortably: mild reward.
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this leftover: penalize proportional dead space.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Open-bins pressure: penalize spreading across many bins when a tight
    // fit exists; encourage consolidating into fewer bins.
    let pressure = open_bins_count as f64 * 0.15;
    score += pressure * (pr / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual becomes dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh bin should only win when placing
    // here would create severe dead space or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.85;
        // Reward opening a new bin for large items that would leave tiny gaps.
        if post_residual < 15 {
            score -= 40.0;
        }
        // If the next item chains perfectly in the fresh bin, encourage it.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come
        // can fill residuals later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    } else {
        // Mean-residual coupling: placing into a bin far below the mean
        // residual (very full bin) is efficient; reward it slightly.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.25;
        } else {
            score += (-dev) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits relative to mean residual
    score -= (mean_residual - post_residual as f64).abs() * 0.3;

    // Aggressive 2-step lookahead: reward if next item exactly matches post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full next step
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fits the leftover
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fit_ratio;
        } else {
            // next item won't fit: leftover may be dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(30.0) * 0.5;
        }
    }

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize leaving very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, favor opening new bins slightly less (keep bins tight later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when few bins are open or progress is early
        score += 15.0 - 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to wasted potential.
        score += (post_residual as f64) * 0.15;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins more when many bins are open and fit options exist.
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + 10.0 * openness * (1.0 - 0.3 * progress);
        // But if the item is huge relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Mild global pressure: when mean residual across bins is large, prefer bins
    // whose residual deviates downward (consume the fullest bins first).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with a non-linear penalty for dead space.
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth coupling: dead space matters more as the stream progresses.
    score += 60.0 * norm_post * progress * progress;

    // Interaction between post_residual and mean residual: penalize bins that
    // deviate from the fleet mean (keeps residuals homogeneous).
    let dev = (mean_residual - post) / cap;
    score += 25.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - norm_post);
    }

    // Lookahead: reward leaving space that fits the next item (smooth kernel).
    if next_item_size > 0 {
        let d = (post - next_item_size as f64) / cap;
        let fit_kernel = (-d * d * 50.0).exp();
        score -= 30.0 * fit_kernel;
        // Penalize wasting a large bin on a small item when next item is large.
        score += 10.0 * (next_item_size as f64 / cap) * norm_post;
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + mean_residual / cap)).min(3.0);
        score += 35.0 + 20.0 * (1.0 - progress) - 15.0 * crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let mut class_penalty = 0.0;
    if post_residual == 0 {
        class_penalty -= 40.0; // perfect fill
    } else if post_residual < eighth {
        class_penalty -= 20.0; // near-perfect: dead space negligible
    } else if post_residual < quarter {
        class_penalty += 5.0;
    } else if post_residual < 2 * quarter {
        class_penalty += 12.0;
    } else {
        class_penalty += 25.0; // large leftover: bin stays very usable, less urgent to fill
    }
    score += class_penalty;

    // Modulo-style harmonic classes on post_residual (period 10).
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // round residual: easy to pair with small items
    } else if m >= 8 {
        score += 4.0;
    }

    // Lookahead: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly: strong reward, scaled by tightness
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 + 10.0 * tight;
            if post_residual == next_item_size {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted opportunity
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.15 * gap;
        }
    } else {
        // last item: strongly prefer zero residual
        score -= 30.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline plus mild penalty so tight fits in open bins win
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // reward tightness of fit relative to residual
        let fill_ratio = (item_size as f64) / (bin_residual as f64);
        score -= 20.0 * fill_ratio;
    }

    // Stream progression: late in stream, be more aggressive about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Many open bins: discourage spreading; prefer consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * ((post_residual as f64) / cap);

    // Mean residual coupling: if mean residual is small, bins are nearly full; reward using them.
    if mean_residual < 20.0 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are wasted. Penalize unusable gaps heavily.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fill, actually great -> reward instead
        score -= 2000.0;
    } else if post_residual > 0 {
        // Usability factor: gaps that can't fit next_item_size (or a small item)
        // are dead space; penalize quadratically.
        let threshold = if next_item_size > 0 { next_item_size.min(50) } else { 10 } as f64;
        if (post_residual as f64) < threshold {
            let dead = threshold - post_residual as f64;
            score += 3.0 * dead * dead;
        }
        // Perfect-ish fits are excellent.
        if post_residual <= 2 {
            score -= 50.0;
        }
    }

    // Reward tight fit relative to bin capacity.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin is cheap so new-bin candidate stays competitive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * pressure;

    // New-bin candidate: neutral baseline, slightly penalized so it only wins
    // when open bins have terrible fits (large dead-space penalties above).
    if bin_residual == bin_capacity {
        score = 60.0 + 0.02 * open_bins_count as f64 - 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next == 0 {
                score -= 45.0;
            } else if slack_after_next < 10 {
                score -= 20.0; // leaves only tiny unusable gap -> mild penalty below
            } else {
                score -= 10.0 * (1.0 - (slack_after_next as f64) / (bin_capacity as f64));
            }
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins whose post-residual stays near/above mean
    // (keeps open bins flexible), but avoid leaving huge residual spread.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.12 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // item would leave a large residual in every existing bin (poor fits elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; discount early in the stream when flexibility is valuable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * (1.0 + 0.5 * (1.0 - progress));
        // If item is large, a new bin wastes less relative space later.
        score -= 0.3 * item_size as f64;
        // If many bins are open and mean residual is small, prefer reusing.
        score += 0.05 * open_bins_count as f64 + 0.2 * mean_residual;
        // If next item is large, a fresh bin can host it later: mild discount.
        score -= 0.1 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-exact fills more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space below the smallest plausible item (unknown dist: use 1).
    if post_residual > 0 && post_residual < item_size {
        score += 3.0 * (item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, big reward; if it would
    // fit better elsewhere, mild penalty for consuming this residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 2.0;
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> prefer filling
    // existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (residual much smaller than item) or stream is very early.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) as f64 > mean_residual);
        if poor_fit {
            score -= 6.0 + 10.0 * (1.0 - progress);
        } else {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.9 * x * x) + 12.0 * x * x * x * cap * (0.5 + progress);

    // Stream-progress coupling: late in the stream, waste is costlier.
    score += 20.0 * progress * x * x * cap;

    // Lookahead: reward if next item fits in post residual (smooth bonus).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).max(0.0) / cap;
        let fit_frac = (pr / nxt).min(2.0);
        score -= 8.0 * fit_frac * (1.0 - fit) * (0.4 + 0.6 * progress);
        // Penalize leaving a gap just below next item size (dead space).
        let gap = (nxt - pr) / cap;
        if gap > 0.0 {
            score += 15.0 * gap * gap * cap * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Encourage consolidating into bins with many alternatives.
    score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Mild penalty for opening a new bin when mean residual is high.
    if bin_residual == bin_capacity {
        score += 18.0 * (mean_residual / cap) * (0.5 + progress);
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/2, 1/3, 1/4 of C)
    let c = bin_capacity as f64;
    let item_f = item_size as f64;
    let item_class = (c / item_f).floor(); // 1 for huge items, higher for small

    // Reward tight fits: penalize large post_residual less when it lands on
    // harmonic boundaries (0, or small multiples of capacity/4)
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 {
        score -= 12.0; // perfect harmonic leftover (0, 25, 50, 75)
    } else if post_residual <= quarter / 2 {
        score -= 8.0; // near-dead space but tiny: acceptable
    } else if post_residual > bin_capacity / 2 {
        score += 6.0; // wasting more than half the remaining space
    }

    // Integer-division threshold on post_residual: dead space classes
    let dead_class = post_residual / 10;
    score += dead_class as f64 * 0.8;

    // Lookahead coupling: if the next item fits into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item exactly fills the bin (harmonic completion)
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for the next item: penalize proportional to dead space
        score += (post_residual as f64).min(next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive for large items
    // or when no open bin fits well (item nearly fills a fresh bin)
    if bin_residual == bin_capacity {
        let fill_ratio = item_f / c;
        if fill_ratio > 0.7 {
            score -= 30.0; // big item: fresh bin is great
        } else {
            score += 10.0 + 20.0 * (1.0 - fill_ratio); // small item in new bin wastes space
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // if many bins are open with slack, prefer reusing them
        if open_bins_count > 2 && mean_residual > item_f {
            score += 12.0;
        }
    }

    // Slight preference for fuller bins overall (best-fit baseline sharpening)
    score -= (c - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100, but tiny gaps < ~10 are near-worthless) are
    // heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-usable gap: mild penalty to prefer tighter fits.
        score += 8.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fills that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 5.0; // creates a gap the next item cannot use
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // and slightly discourage spreading items across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: must overcome the base residual advantage of an
        // empty bin (residual = capacity). Penalize proportional to pressure.
        score += 30.0 + pressure * 4.0;
        if fitting_bins_count <= 1 {
            // No (or one marginal) alternative: opening a new bin is fine.
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward to keep using already-open bins.
        score -= 2.0 + pressure * 0.3;
    }

    // Prefer bins whose residual deviates from the mean in a "fillable" way:
    // a bin with residual above the mean can absorb the current item while
    // tighter bins stay for smaller items.
    let residual = bin_residual as f64;
    if residual > mean_residual {
        score -= 0.25 * (residual - mean_residual);
    } else {
        score += 0.25 * (mean_residual - residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact-fit reward (tight packing is best)
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // penalize small dead space quadratically
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64) * 0.3;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits after this placement -> good chaining
            score -= 15.0 + 10.0 * (nxt / 100.0);
            // bonus if post_residual is close to next item (efficient chain)
            let slack = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here -> dead space risk
            score += 10.0 + 0.2 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if current item is large and lookahead is large, allow new bin
        if item_size > 60 && next_item_size > 60 {
            score -= 45.0;
        }
    }

    // Late in stream: prefer tight closures to finish cleanly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual == 0) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Extra reward if post-residual matches next item almost exactly.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 3 {
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin mildly, more so
    // when many bins are already open or mean residual is large.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // Reward using bins whose residual deviates from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
    }

    // Time horizon: early in the stream, be more conservative about opening bins
    // (future items unknown); late in the stream, tolerate new bins less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Prefer filling bins with large residual when many bins are open.
    score -= 0.03 * bin_residual as f64 * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = post_norm * post_norm * 40.0 + post_norm * 20.0;

    // Smooth non-linear coupling of post-residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier).
    let urgency = progress * progress;
    score += urgency * post_norm * 30.0;

    // Reward tight fits (post_residual near zero) more strongly as stream advances.
    score -= (1.0 - post_norm).powi(3) * (10.0 + 20.0 * urgency);

    // Last-chance bonus: if this is the only fitting bin, penalize opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening a fresh bin when open bins exist,
    // unless residual would be very small (item nearly fills a bin anyway).
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 12.0 + open_f * 2.0 - 10.0 * (item_size as f64 / cap);
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (post - nxt).abs();
        if post >= nxt {
            score -= 10.0 * (1.0 - fit / cap).powi(2);
        } else {
            score += 5.0 * (fit / cap);
        }
    }

    // Mild penalty for deviating from mean residual (balance bin fullness).
    score += ((mean_residual - post) / cap).powi(2) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (mod 10) are hard to reuse -> penalize.
    let r = post_residual;
    let residue_class = (r % 10) as f64;
    let decade = (r / 10) as f64;

    // Dead space: leftovers below the minimum plausible item size are useless.
    if r < 10 {
        score += 25.0;
    }

    // Penalize small awkward leftovers; reward near-perfect fits.
    if r == 0 {
        score -= 60.0; // perfect closure
    } else if r <= 5 {
        score += 12.0 + residue_class;
    } else if r <= 15 {
        score += 4.0 - residue_class * 0.3; // class 0..5 leftovers are reusable
    }

    // Decade-based harmonic reward: leftover in high decades is flexible.
    score -= decade * 2.0;

    // Lookahead coupling: if next item fits the post residual exactly or well,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 80.0;
        } else if next_item_size <= r {
            let after = r - next_item_size;
            if after < 10 {
                score -= 20.0; // chains into closure
            } else {
                score -= (after as f64) * 0.2;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += ((next_item_size - r) as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer reusing open bins when their residual is
    // reasonably large; opening a bin is only attractive when the item is big
    // relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early (accumulate fragmentation), reward late when
        // open bins are fragmented (mean residual low).
        score += 35.0 - 40.0 * progress;
        if (mean_residual < item_size as f64) && item_size >= 50 {
            score -= 45.0;
        }
        // Harmonic threshold: open new bin for large items on decade boundaries
        if item_size % 10 == 0 && item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight preference to pack into bins below mean residual (tighter bins first).
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.05;

    // Modulo-class tiebreak on bin residual itself: residuals that are exact
    // multiples of 10 pack predictably with decade-sized items.
    if bin_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 6.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead space is worse late in the stream when there's less chance to fill it.
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 70.0;
        } else if leftover < 10 {
            score -= 20.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty for wasting the lookahead opportunity.
        score += 5.0;
    }

    // Open bin pressure: discourage spreading across many bins when few fit options exist.
    if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 45.0;
    } else {
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // New-bin candidate: neutral baseline; only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized unless many bins exist and fits are poor.
        score += 15.0 + open_bins_count as f64 * 0.8;
        if fitting_bins_count == 1 {
            // Even so, using the last fitting bin beats a new bin.
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus: next item fits snugly with little waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack * 0.15);
    }
    // Penalize post_residual that cannot fit the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    // (no good fit among open bins). Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let mut good_fit_exists = false;
        // Heuristic proxy: if several bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count >= 2 {
            good_fit_exists = true;
        }
        // If the next item is large relative to the item, a fresh bin may still be useful.
        let fresh_useful = next_item_size == 0
            || (next_item_size <= post_residual && fitting_bins_count == 0);
        if good_fit_exists || !fresh_useful {
            score += 80.0;
        } else {
            score += 15.0;
        }
    }

    // Mild penalty for very small post_residuals that create unusable slivers
    // (< 10, minimum item size), unless they are exactly zero (perfect closure).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    // Early-stream: encourage keeping bins balanced when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit even the smallest plausible item is extra bad.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 15.0; // perfect fill bonus
    } else if (post_residual as f64) < 20.0 {
        score -= 6.0; // near-perfect fill
    }

    // Penalize residual that is unlikely to be reused by the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward for keeping this bin attractive
            score -= (next_item_size as f64) * 0.35;
        } else {
            // wasted space relative to lookahead
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
        // extra urgency late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins rather than
    // opening new ones (fragmentation penalty on new-bin candidate).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // new empty bin candidate: base score = capacity is high already;
        // penalize further when many bins are open or mean residual is large.
        score += (open_bins_count as f64) * 1.5;
        score += mean_residual * 0.3;
        // allow new bins early when few exist and mean residual is low
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    } else {
        // existing bin: mild bonus for filling bins that are already smallish
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Time-horizon coupling: early in the stream, be more willing to open
    // new bins (long future to fill them); late, prefer tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 25.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Non-linear coupling: penalize medium-size leftover gaps that are too
    // big to be "full" but too small for typical items.
    let gap = post_residual as f64;
    if gap > 20.0 && gap < 45.0 {
        score += (45.0 - gap) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p = progress;
    let coupling = pr_norm * pr_norm * (0.5 + p) + pr_norm * p * p;
    score += 8.0 * coupling;

    // Reward tight fits more aggressively as the stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * p);

    // Penalize dead space relative to mean residual of open bins.
    let dead = pr - mean_residual;
    score += 0.05 * dead * dead.abs().sqrt().signum() * dead.abs().sqrt();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * p;
    }

    // Lookahead: bonus if next item can fit into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 * (1.0 - slack) * (1.0 + p);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Penalize leaving a gap that neither next item nor typical items can use.
        score += 4.0 * pr_norm * (1.0 + p);
    }

    // New-bin candidate: make it moderately attractive early, less so late
    // unless the fit into existing bins is terrible.
    if bin_residual == bin_capacity {
        let base = 20.0 + 30.0 * p;
        score = score.max(base) + base;
    }

    // Slight penalty for proliferating open bins late in the stream.
    score += 0.3 * (open_bins_count as f64).sqrt() * p;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" leftover space is.
    // Classes via integer division thresholds on post_residual.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -30.0 // perfect fit, best possible
    } else if pr <= 10 {
        0.0 // small dead space, still harmonically compatible with tiny items
    } else if pr <= 20 {
        5.0
    } else if pr <= 35 {
        12.0
    } else if pr <= 50 {
        20.0
    } else {
        30.0 // large residual, wasteful placement
    };
    score += class;

    // Modulo harmony: residual divisible into nice chunks is more reusable.
    if pr > 0 {
        let mut harmony = 0.0;
        for chunk in [10u32, 20, 25, 50] {
            if pr % chunk == 0 {
                harmony -= 4.0;
            }
        }
        score += harmony;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = pr.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer good fits into open bins,
    // but allow opening when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * open_bins_count as f64;
    }

    // Tightness reward: fraction of bin used by this item.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Progress adaptation: later in stream, be greedier about tight fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * fill;

    // Mean residual context: if this bin is far below mean residual, it's a good filler.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    let dead_threshold: f64 = 8.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        score += 60.0; // heavy penalty for creating tiny unusable gap
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Penalize gaps that cannot fit the known next item but could otherwise be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward leaving room exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 15.0 + 0.4 * open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
    } else {
        score -= 5.0;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize small dead space after placement (waste), reward large post residual only mildly.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it heavily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        // Base penalty for opening a new bin; reduced for large items.
        score += 25.0 - (item_size as f64 - 1.0) * 0.25;
        // Later in stream, opening new bins slightly more acceptable for big items.
        if item_size >= 50 {
            score -= 10.0 * progress;
        }
        // If many bins already open and mean residual is small, avoid new bins.
        if mean_residual < waste {
            score += 10.0;
        }
        let _ = open_bins_count;
    }

    // Mild preference for fuller bins overall (compare residual to mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let t = progress;
    // penalize large post_residual more as stream progresses (less time to fill gaps)
    let late_weight = 0.4 + 1.6 * t * t;
    score += late_weight * prn * prn * cap * 0.5;

    // reward tight fits: smooth quadratic bonus as post_residual -> 0
    let tightness = (1.0 - prn) * (1.0 - prn);
    score -= 8.0 * tightness;

    // lookahead coupling: penalize if post_residual can't fit next item, smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0);
        let usable = 1.0 - (gap / cap).min(1.0);
        score -= 5.0 * usable * usable * (prn / (prn + 0.25));
    }

    // last-chance bin: smooth reward when few fitting bins
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - prn);
    }

    // penalize opening new bin when many bins have large residuals, smoothly
    let mean_res_n = mean_residual / cap;
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * mean_res_n * mean_res_n + 0.5 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // in [0,1]

    // Class 0: near-perfect fit (residual < 1/8 of capacity) -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if frac < 0.125 {
        score -= 60.0;
    } else if frac < 0.25 {
        score -= 15.0;
    } else if frac < 0.5 {
        score -= 4.0;
    }

    // Modulo arithmetic on post_residual: residuals in "usable" harmonic classes
    // (can host small items 1..=10 or common sizes) are penalized less.
    let mod8 = post_residual % 8;
    let mod16 = post_residual % 16;
    if mod8 == 0 && post_residual > 0 {
        score -= 6.0; // divisible residual is more reusable
    }
    if mod16 >= 1 && mod16 <= 10 {
        score -= 2.0; // can host a small item exactly
    }

    // Integer-division thresholds: residual >= next_item_size means lookahead fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Harmonic pairing: item + next exactly fills capacity -> big reward.
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 200.0;
        }
    }

    // Tightness coupling: reward filling bins with small residual before placement.
    let tight = 1.0 - (bin_residual as f64) / cap_f;
    score -= 20.0 * tight * tight;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            -1000.0
        } else {
            (mean_residual / cap_f) * 50.0
                + (open_bins_count as f64).ln() * 10.0
                + (step_index as f64 / total_items.max(1) as f64) * 20.0
        };
        // Base cost of opening a new bin.
        score += 120.0 - pressure;
        // If next item is huge, a fresh bin is attractive for pairing.
        if next_item_size >= 50 && item_size <= 50 {
            score -= 25.0;
        }
    }

    // Late-stream consolidation: prefer closing bins tightly as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold even the
    // smallest item are pure waste; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 20.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward bins whose post_residual still accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for next item: mild penalty.
        score += 15.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Reward using bins with small residuals (consolidate near-full bins).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Open-bin pressure: with many open bins, discourage opening a new one
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Early in stream, be slightly more open to new bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the residual: strong reward, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.4 * slack;
    }
    // Next item does NOT fit: penalize proportional to wasted potential.
    else if next_item_size > 0 {
        score += 15.0;
    }

    // Dead-space penalty: residual too small to ever be useful (min item 1, but small residuals are poor).
    if post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit character).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, only chosen when open bins look bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Exact / near-exact fills are gold.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    }
    // Penalize leaving a residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: only attractive when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when open bins fit badly.
        score += 120.0;
        // More open bins -> more reluctant to open yet another.
        score += 4.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (builds a fleet).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // If mean residual across open bins can't fit the item, a new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 90.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 30.0;
        }
    } else {
        // Prefer bins with larger residual among fitting bins (waste less of a tight bin).
        score -= 0.15 * bin_residual as f64;
    }

    // Slight preference to balance residuals toward the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic-plus-cubic shaping of dead space.
    let x = post / cap;
    score += 12.0 * x * x * cap + 6.0 * x * x * x * cap;

    // Reward near-perfect fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= (1.5 + 6.0 * progress) * tightness * tightness * cap * 0.1;

    // Lookahead: bonus if next item fits exactly into the resulting residual,
    // smooth falloff with the gap between residual and next item.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let fit_quality = (-gap / 20.0).exp();
        score -= 8.0 * fit_quality * (1.0 + progress);
        // Penalize residuals that can't host the next item at all.
        if post < next_item_size as f64 {
            score += 3.0 + 2.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64 * x;

    // Align residual with the fleet mean: prefer bins whose post residual
    // sits near the mean (keeps future options uniform).
    let dev = (post - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * cap;

    // New-bin candidate: make it attractive only when it beats poor fits,
    // i.e., when the current item would leave a large awkward residual.
    if bin_residual == bin_capacity {
        let newbin_score = 0.35 * cap + 0.4 * item_size as f64 - 6.0 * progress * cap;
        score = score.min(newbin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (dead space) are penalized super-linearly.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10; // harmonic class within decades
        score += (class as f64) * 0.35;
        // Integer-division thresholds: leftover < 10 is nearly dead space
        if pr < 10 {
            score += 6.0;
        } else if pr < 20 {
            score += 2.5;
        } else if pr < 30 {
            score -= 1.0;
        }
    } else {
        // Perfect fill: strong reward
        score -= 25.0;
    }

    // Fraction-of-capacity coupling: reward post_residual near common
    // item-size fractions of capacity (harmonic alignment).
    let frac = post_residual as f64 / bin_capacity as f64;
    let harmonics = [0.1f64, 0.2, 0.25, 0.3, 0.5, 0.75];
    let mut min_dist = 1.0f64;
    for &h in &harmonics {
        let d = (frac - h).abs();
        if d < min_dist {
            min_dist = d;
        }
    }
    score -= 4.0 * (1.0 - min_dist * 2.0).max(0.0);

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 3.0; // aligned leftover for future classes
            }
            score += (gap as f64) * 0.08;
        } else {
            // next item won't fit here; leftover is terminal dead space
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + (item_size as f64 / bin_capacity as f64) * 6.0;
    }

    // New-bin candidate: only prefer it when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64) / bin_capacity as f64;
        if tightness > 0.5 {
            score += 12.0; // opening a bin wastes more than half its space
        } else {
            score += 2.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild pressure against keeping many bins with large mean residual.
    score += 0.05 * open_bins_count as f64;
    score -= 0.03 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1..100,
    // but treat gaps < 12 as likely unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64) / 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally: penalize wasted fraction quadratically.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (i.e., make existing bins more attractive relative to the empty-bin call,
    // whose post_residual == capacity gives a high base score).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mild penalty if this bin is much tighter than average (keep slack spread).
    if (bin_residual as f64) < mean_residual * 0.5 && bin_residual > item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: leftover exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Partial lookahead reward: next item fits into the leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (post_residual - next_item_size) as f64 * -0.0;
        // still prefer tighter leftovers that fit next item
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
    } else {
        // Penalize dead space relative to mean residual
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // Reward tight fits overall
    score -= (bin_residual - item_size) as f64 * 0.0;
    score -= item_size as f64 * 0.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item exactly matches full capacity usage chain, allow new bin
        if next_item_size > 0 && next_item_size >= item_size + post_residual {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred near end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Lookahead: penalize if next item fits into post_residual (leaving room is good),
    // but reward if post_residual is dead space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // chain placement possible
        } else {
            score += 0.5 * (post_residual as f64); // dead space penalty
            if post_residual < 10 {
                score -= 20.0; // near-full bin is still good
            }
        }
        // If next item fits exactly into post_residual, big reward.
        if next_item_size == post_residual {
            score -= 120.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Many open bins: encourage closing bins (small residual) to consolidate.
    if open_bins_count > 3 {
        score += 0.3 * (open_bins_count as f64) * tightness;
    }

    // Global residual pressure: if mean residual is low, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * tightness * mean_residual * (1.0 - progress);

    // New-bin candidate: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, reduced early in the stream when flexibility helps.
        score = 70.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(item_size) {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 18.0 * fit_norm * fit_norm * (1.0 + progress);
    score -= 14.0 * fit_norm * (1.0 - progress) * (1.0 - progress);

    // Reward near-perfect fits (low post_residual) more strongly later in stream
    score -= 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * progress;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }

    // Penalize bins far below mean residual (fragmentation) with smooth coupling
    score += 0.15 * (mean_residual - pr).abs() * (0.5 + progress);

    // Slight penalty for spreading across many bins
    score += 0.4 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: keep neutral-ish baseline with smooth adjustment
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 5.0 * fit_norm * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals in "useful" bands
    // (multiples of common item sizes / capacity fractions).
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -50.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr <= 9 {
        8.0 // unusable dead space (min item is 10 in classic streams)
    } else if pr <= 19 {
        4.0
    } else {
        0.0
    };
    score += class;

    // Integer-division thresholds on post_residual relative to capacity fractions
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 3.0; // small leftover, but below quarter may be dead space
    } else if pr <= bin_capacity / 2 {
        score -= 4.0; // sweet spot: half-fillable
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 2.0; // next item cannot use this bin's leftover
        }
        // harmonic match: next item and post_residual share a common divisor class
        if pr % 10 == next_item_size % 10 && next_item_size <= pr {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        score += 25.0 + 10.0 * (1.0 - progress) - pressure.min(15.0);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 5.0; // next item pairs well with fresh bin
        }
    } else {
        // Prefer bins whose residual is close to item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += tightness * 5.0;
        // Favor bins with residuals far from mean (spread usage evenly)
        score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    score += (open_bins_count as f64).ln() * 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful are worse
    // than large residuals (which may still fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 5.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item won't fit here; gap likely wasted
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 20.0;
    }

    // Pressure on number of open bins: with many open bins, prefer packing
    // into existing ones (penalize the new-bin candidate implicitly via
    // residual, but add pressure to consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * 3.0 * (0.5 + progress);

    // New-bin candidate: bin_residual == bin_capacity means empty bin.
    // Opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is flexible for the future
        }
    }

    // Mild preference for bins below mean residual (balance the load).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post_residual is small relative to mean residual.
    let tightness = if mean_residual > 0.0 {
        post_residual as f64 / mean_residual.max(1.0)
    } else {
        1.0
    };
    score += 12.0 * (tightness - 1.0);

    // 2-step lookahead: if the next item exactly fits post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover after the hypothetical next placement
            score += 0.4 * gap;
        } else {
            // next item cannot fit here; penalize proportional to wasted lookahead
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss;
        }
    } else {
        // last item: just minimize post_residual (already base) and reward exact fill
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Exact fill of current bin is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize creating small unusable dead space (below minimum plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in stream: prefer closing bins (small residual) more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize mildly unless residual-based pressure justifies it
        score += 15.0 + 2.0 * open_bins_count as f64;
        // allow opening a new bin when existing bins have tiny residuals vs item
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * (next_item_size as f64);
            // Perfect pairing bonus
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward residual
            score += 0.2 * (post_residual as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 0.3 * mean_residual / (open_bins_count.max(1) as f64);
    }

    // Late in the stream, be more conservative with new bins
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Smooth non-linear progress coupling: quadratic ramp
    let prog2 = progress * progress;

    // Reward tight fits: smaller post_residual relative to capacity gets a discount
    let tightness = post_residual as f64 / cap;
    score -= (1.0 - tightness) * (1.0 - tightness) * 0.30 * cap;

    // Penalize leaving residuals that are awkwardly small relative to mean residual
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        score += (ratio - 1.0) * (ratio - 1.0) * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 0.5 * (1.0 - slack) * (1.0 - slack) * cap;
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let over = (nxt - post_residual as f64) / cap;
            score += over * over * 0.4 * cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 0.45 * cap * (1.0 + prog2);
    }

    // When many bins are open, mild pressure to consolidate into existing bins
    score -= (open_bins_count as f64).ln() * 3.0 * (1.0 - tightness);

    // New-bin candidate: empty bin has large post_residual; add penalty scaled by progress
    // so late in the stream we prefer filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += cap * (0.35 + 0.65 * prog2);
    }

    // Smooth interaction: post_residual x progress polynomial
    score += tightness * tightness * cap * (0.2 + 0.6 * prog2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "usable" classes
    // (divisible into small-item friendly chunks). Class 0 = perfectly tight.
    let post = post_residual;
    let tight_bonus = if post == 0 {
        -60.0 // perfect fit is always best
    } else if post <= 10 {
        -25.0 // near-tight: only tiny items fit, but little waste
    } else if post % 10 == 0 && post <= 50 {
        -18.0 // harmonic class: residual matches common item-size grid
    } else if post % 20 == 0 {
        -12.0
    } else if post % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residual: dead-space penalty
    };
    score += tight_bonus;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 && post >= next_item_size {
        let slack = (post - next_item_size) as f64;
        score -= 14.0 - slack * 0.08; // exact next-fit is best, decaying with slack
        if (post - next_item_size) % 10 == 0 {
            score -= 4.0; // harmonic chain: next placement also lands on grid
        }
    } else if next_item_size > 0 && post < next_item_size {
        score += 5.0; // next item won't fit here; slight penalty for closing awkwardly
    }

    // Integer-division threshold on post_residual relative to capacity
    let quarter = bin_capacity / 4;
    if post < quarter {
        score += 6.0; // very small residual: low utility
    } else if post >= quarter && post <= bin_capacity / 2 {
        score -= 7.0; // sweet spot: half-capable residual
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a fresh bin wastes capacity; only attractive
    // when the item is large and no tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 30.0 - frac * 40.0; // large items justify a new bin
        if open_bins_count == 0 {
            score -= 35.0; // must open a bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // fresh bin naturally hosts the next item too
        }
    }

    // Stream progression: later in the stream, consolidate harder (avoid sprawl)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.25;

    // Mild preference for bins below mean residual (balance residual spread)
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest possible item (1)
    // are pure waste; penalize small-but-nonzero gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 3.0;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward keeping
    // this residual; if it just barely misses, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // favor filling existing bins over the new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized as bins accumulate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + open_bins_count as f64 * 6.0 + progress * 20.0;
        // But if mean residual of open bins is too small for the item,
        // opening a new bin becomes attractive: reduce penalty.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 40.0;
        }
    } else {
        // Existing bin: mild reward scaled by how much slack it absorbs.
        score -= (item_size as f64 / bin_capacity as f64) * 12.0;
        // Prefer bins with residuals close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // Slight penalty for using a bin when many alternatives exist,
        // preserving flexibility for future items.
        if fitting_bins_count > 3 {
            score += 4.0;
        }
    }

    // Mean-residual coupling: bins far below mean residual are "loose";
    // prefer placing into bins whose residual is near the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match => big subtraction; near matches rewarded proportionally.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for the next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits now: small post_residual relative to capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates far below mean residual (unbalanced bins).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if no other bin fits well (post_residual of new bin matches next item), soften.
        if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 {
            score -= 70.0;
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already rewarded).

    // Lookahead: if the next item fits into post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving space that the known next item cannot use (dead space risk).
        let wasted = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 0.3 * wasted;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when many bins are already open. Reward only if current fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 30.0 * progress + 1.5 * open_bins_count as f64;
        // If no open bin fits well (this call is the new-bin candidate with poor alternatives),
        // reduce the penalty when the item is large relative to capacity.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * large_item;
        // If mean residual across open bins is small, open bins are nearly full anyway.
        score -= 0.2 * mean_residual;
    } else {
        // Mild preference for fuller bins when many bins are open (bin consolidation).
        score -= 0.05 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: small post_residual rewarded more as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that is too small to be useful later (non-linear threshold).
    let dead = (pr - 10.0).max(0.0) / cap;
    score += 8.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - dead) * progress;

    // Last-chance bonus: only one fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when good alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 5.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating residuals near the mean.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 10.0;

    // Harmonic class of post_residual: residues modulo 10 identify "dead" slivers.
    let r = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += (10.0 - r) * 0.8; // penalize residues close to 9 (awkward slivers)
    }
    // Perfect closure or exact half classes are attractive.
    if post_residual == 0 {
        score -= 25.0;
    }
    if post_residual == bin_capacity / 2 {
        score -= 12.0;
    }
    // Integer-division classes: post_residual divisible by common item sizes is reusable.
    if post_residual > 0 && post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 4.0;
    }

    // Lookahead: reward bins whose post_residual can host next_item_size exactly or closely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= (gap as f64).min(15.0) * 0.6;
        } else {
            // next item cannot fit here; penalize proportionally to shortfall.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        // Open new bin when open bins are mostly full (low mean residual).
        score += 30.0 * pressure;
        // Early stream: keep some openness; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
        if post_residual as f64 > mean_residual {
            score -= 4.0; // fresh bin has above-average room
        }
    }

    // Prefer bins with residual near the mean (balanced packing) slightly.
    score -= 3.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64).min(1.0));

    // Slight preference to fill more-open states to limit bin proliferation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (1..10) are wasted forever.
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        // Small but potentially usable gap: mild penalty scaled by tightness.
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual in usable range).
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= (15 - post_residual) as f64 * 0.6;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it competitive only if current fit is poor.
    if bin_residual == bin_capacity {
        score += 6.0;
        if post_residual >= 10 && post_residual <= 30 {
            score -= 4.0; // fresh bin gives a clean, usable residual
        }
    }

    // Lookahead: bonus if next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + (post_residual - next_item_size).min(20) as f64 * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 5.0; // dead space confirmed by lookahead
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Late in stream: be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // chain-fit: excellent, penalize less the leftover
            score -= 60.0;
            // perfect chain: next item exactly consumes the rest
            if next_item_size == post_residual {
                score -= 300.0;
            }
        } else {
            // next item cannot use this bin's remainder -> dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when open bins exist with decent residual.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0;
        // but if no open bin fits well (large mean residual mismatch), soften
        if post_residual as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Late in the stream, tighten packing (avoid leaving many slightly-used bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Prefer filling fuller bins (small bin_residual) when item fits.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0 + 8.0 * (6.0 - post_residual as f64);
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Penalize dead space relative to capacity and mean residual.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += 90.0 * frag * frag;

    // Lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 45.0 + 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here: penalize leaving awkward gaps.
            let gap_ratio = post_residual as f64 / (next_item_size.max(1) as f64);
            score += 25.0 * (1.0 - (gap_ratio.min(1.0)));
        }
    } else {
        // Last item: closing a bin fully is ideal.
        score -= 60.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Time horizon: late in the stream, be more aggressive about filling bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - frag);

    // Prefer using existing bins when many are open and residuals are small.
    score += 0.6 * (open_bins_count as f64).sqrt() * frag;

    // Coupling with mean residual: if this bin's residual is far below the mean,
    // it is already tight — favor placing here to consolidate.
    let dev = mean_residual - post_residual as f64;
    score -= 0.35 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 - mean_residual).abs()
        };
        score += 55.0 - 20.0 * progress - poor_fit.min(40.0);
        if item_size >= 70 {
            score -= 15.0; // big items may justify fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = (item_size, bin_residual, bin_capacity, step_index, total_items, open_bins_count, mean_residual, next_item_size, post_residual, fitting_bins_count);
    0.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity are more reusable by future items.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward residuals that are multiples of common item-size harmonics (10, 20, 25, 50).
    let harmonic_bonus: f64 = {
        let r = post_residual;
        let mut b = 0.0;
        if r % 10 == 0 { b += 2.0; }
        if r % 20 == 0 { b += 2.0; }
        if r % 25 == 0 { b += 1.5; }
        if r % 50 == 0 { b += 3.0; }
        b
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space that nothing (min size 1..100) can use usefully:
    // residuals in (0, 10) are near-waste; heavily penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chains two items perfectly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward small leftover after the lookahead item
            score -= (10.0 - (nxt_post as f64 / 10.0)).max(0.0);
            if nxt_post < 10 { score += 8.0; } // but avoid creating dead space
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is
    // large and would leave a highly reusable harmonic residual.
    if bin_residual == bin_capacity {
        let base = 30.0;
        // opening new bins is worse late in the stream when many bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = base + progress * 10.0 + (open_bins_count as f64) * 0.5;
        // but if item is huge (> 70% capacity), a fresh bin is reasonable
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            nb -= 20.0;
        }
        // residual after placement in fresh bin being harmonic softens penalty
        if post_residual % 10 == 0 { nb -= 3.0; }
        score += nb;
    }

    // Mild preference for tighter (fuller) bins relative to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size is 1, but tiny gaps waste capacity). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Penalize residual that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        } else {
            // Post residual can host next item: reward proportionally.
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits
    // (mean residual low means bins are mostly full; high mean residual with
    // poor fit here suggests fragmentation -> new bin may be better).
    if bin_residual == bin_capacity {
        let fit_here = (bin_residual - item_size) as f64;
        if fitting_bins_count > 0 {
            // Compare against best possible fit in existing bins: penalize
            // opening new bins when any open bin leaves less waste.
            score += 15.0 + fit_here * 0.2;
            if mean_residual < item_size as f64 + 5.0 {
                score -= 10.0; // existing bins nearly full, new bin is fine
            }
        }
    }

    // Late-stream conservatism: near the end, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins that stay near the pack's average fill.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        score -= 40.0 * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
        if next_fit_gap == 0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space for the next item
        score += 30.0 * (next_item_size - post_residual) as f64 / 100.0;
    }

    // Penalize bins with residual far from mean (avoid fragmenting many bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * open_bins_count as f64;
        // but if the item is large and would leave awkward residual elsewhere, mild discount
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Late-stream: tighten packing, prefer existing bins more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small waste relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 120.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 5 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let rem_after_next = post_residual - next_item_size;
            // small leftover after next item is good
            score -= (1.0 - rem_after_next as f64 / bin_capacity as f64) * 40.0;
            if rem_after_next == 0 {
                score -= 80.0;
            }
        } else {
            // next item won't fit here; mild penalty for large trapped residual
            score += (post_residual as f64 - (post_residual as f64 % 10.0)) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the tightest among many; slight penalty softens
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when current residuals are poor
    if bin_residual == bin_capacity {
        let mean_fit_quality = 1.0 - (mean_residual / bin_capacity as f64);
        // If open bins are on average roomy (bad), opening a new bin is reasonable
        score = 60.0 + mean_fit_quality * 80.0 + open_bins_count as f64 * 2.0;
        // Early in stream, prefer filling existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 30.0;
        // If this is a large item and nothing fits well, new bin is fine
        if item_size > bin_capacity as u32 * 3 / 4 {
            score -= 40.0;
        }
        // Never open a new bin when a perfect-ish fit exists elsewhere
        if mean_residual < 15.0 {
            score += 200.0;
        }
    }

    // Penalize creating dead space that is too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Global state: many open bins -> consolidate, favor existing bins
    score += open_bins_count as f64 * 1.5;
    // Deviation from mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // smooth polynomial coupling of residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 20.0 * poly;

    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }

    // last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // penalize spreading residual too thin across many bins
    score += 3.0 * ((mean_residual - pr).abs() / cap);

    // new-bin candidate: mildly penalize early, allow late when residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let class = pr % 10; // fine harmonic class
    let coarse = pr / 25; // coarse quarter-class of capacity

    // Reward residual sizes that are "harmonic" — likely to be filled by
    // common item sizes (multiples of 10 or small residuals near item sizes).
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // residual exactly divisible by 10 -> highly reusable
        }
        if class <= 2 || class >= 8 {
            score -= 2.0; // near-multiples of 10 are also decent
        } else {
            score += 2.0; // awkward middle classes
        }
        // Dead space penalty: residuals too small for the smallest plausible item
        if pr < 10 {
            score += 25.0;
        }
    } else {
        score -= 12.0; // perfect fit
    }

    // Coarse class coupling: prefer bins whose quarter-class matches item size class
    let item_class = item_size / 25;
    if coarse == item_class {
        score -= 3.0;
    }

    // Lookahead: if next item fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= 4.0 + (pr - next_item_size) as f64 / 10.0;
        } else {
            // next item won't fit here: penalize leaving residual it almost fits
            let gap = (next_item_size - pr) as f64;
            if gap < 10.0 {
                score += gap; // near-miss dead space
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // no open bin offers a good fit (post_residual close to capacity - item).
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: residual after placement is large
        score = (bin_capacity - item_size) as f64;
        // Opening a new bin is fine early or when many bins already open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 10.0; // nothing fits elsewhere: must open
        }
        // Discard new-bin option if some open bin achieves tight fit
        if fitting_bins_count > 0 && post_residual as f64 <= cap * 0.2 {
            score += 30.0;
        }
    } else {
        // Tightness reward: smaller post_residual relative to capacity is better
        score -= 8.0 * (1.0 - post_residual as f64 / cap);
        // Prefer bins with below-mean residual (denser bins) for consolidation
        score += (mean_residual - post_residual as f64) * 0.15;
        // Many open bins: encourage filling existing ones rather than spreading
        if open_bins_count > 4 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 25 {
        // Tight fits are rewarded proportionally to how snug they are.
        score -= (25.0 - post_residual as f64) * 1.5;
    }

    // Reward using bins that are nearly full (low residual before placement).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.5 * progress);
    score += pressure * 2.0;

    // New-bin candidate: penalize opening a new bin unless the current item
    // would leave an unusable gap in every existing bin.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 5.0;
        if fitting_bins_count > 0 && post_residual >= 10 {
            score += 25.0; // an open bin could take it without dead space
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this placement; otherwise penalize blocking the lookahead.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Mild preference for bins whose residual is close to the mean
    // (keeps residuals balanced across open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item fits tightly into the leftover
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in leftover: penalize proportionally to wasted lookahead
    if next_item_size > 0 && next_item_size > post_residual {
        let overshoot = (next_item_size - post_residual) as f64;
        score += 12.0 * (overshoot / bin_capacity as f64);
    }

    // Penalize small unusable dead space (fragmentation)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // Relative to mean residual: prefer bins whose post_residual is close to mean
    score += 0.35 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless it is the only option
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 130.0 - 25.0 * progress;
        if next_item_size > 0 && next_item_size <= item_size {
            // opening fresh bin is fine if next item can also chain here
            score -= 10.0;
        }
    }

    // Slight preference for fuller bins
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // unusable dead space relative to the next item.
    if bin_residual == bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        let next_needs = next_item_size as f64;
        if next_item_size > 0 && dead > 0.0 && dead < next_needs {
            score += 40.0; // would create space too small for next item
        }
        // Time-dependent opening pressure: open new bins more freely early.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * (1.0 - t) - 10.0 * t;
        if next_item_size > 0 && dead >= next_needs {
            score -= 12.0; // new bin can host both current and next item
        }
    } else {
        // Favor bins whose post-residual matches the next item size (lookahead coupling).
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= (1.0 - gap as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins, keep tight ones free).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight penalty when many bins are open: encourage filling existing bins.
    score += open_bins_count as f64 * 0.05;

    // Small noise-free diversity term to break ties deterministically.
    score += (post_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space after placement
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals become more valuable (less penalized),
    // large dead space is penalized more aggressively.
    let late = progress * progress;
    score -= 12.0 * late * (1.0 - norm_pr) * norm_pr;
    score += 20.0 * late * norm_pr * norm_pr;

    // Early-stream smoothing: prefer tighter fits early via cubic term
    let early = (1.0 - progress).powi(3);
    score += 8.0 * early * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if (next_item_size as u32) == post_residual {
            score -= 25.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 5.0 * (next_item_size as f64 / cap);
        }
    }

    // Penalize bins whose residual deviates from mean (fragmentation pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild penalty for opening many bins relative to stream length
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Small post_residual = tight fit = reward (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let tenth = bin_capacity / 10;

    // Class 1: post_residual in a "usable residue class" (multiple of 10 or small)
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 6.0; // residue aligns with typical item granularity
    } else if mod_class <= 2 {
        score -= 3.0;
    } else {
        score += (mod_class as f64) * 0.8; // penalize off-class dead space
    }

    // Integer-division thresholds on post_residual
    let k = post_residual / tenth; // 0..=10 class index
    score += match k {
        0 => -15.0,                    // near-perfect fill
        1 => -10.0,
        2 => -6.0,
        3 | 4 => 0.0,
        5 => 4.0,                      // half-empty: mediocre
        6 | 7 => 6.0,
        8 => 10.0,
        _ => 14.0,                     // barely touched bin
    };

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let nxt_mod = next_item_size % 10;
            if nxt_mod == mod_class && mod_class == 0 {
                score -= 8.0; // same harmonic class: likely chain
            }
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // unless the current fit is terrible (large post_residual) and many bins open.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual >= bin_capacity - item_size {
            // trivially true for new bin; adjust by item size class
            if item_size <= quarter {
                score += 3.0; // small item into fresh bin is wasteful
            }
        }
        // If existing fits are bad (few fitting bins, high mean residual), allow new bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress-aware dead-space penalty: later in stream, tolerate less waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * (0.05 + 0.10 * progress);

    // Spread-aware: many open bins with low mean residual -> prefer filling existing.
    if open_bins_count > 2 && pr < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers that nothing can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can also host the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for the next item: dead space penalty scaled by gap
        score += (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Prefer bins whose residual is close to the item (tight fit) over very large residuals.
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += gap * 0.3;

    // New-bin candidate: attractive when open bins are crowded or the fit is terrible,
    // but not when this bin offers a perfect fit.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.0 && post_residual < 10;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if bad_fit || crowded || open_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 20.0;
        }
    }

    // Mild tie-breaker toward bins with residual near mean (balance load).
    score -= (mean_residual - bin_residual as f64).abs() * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact / tight fits: post_residual small relative to item size.
    let fit_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 60.0 * (1.0 - fit_ratio.min(1.0));

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - (lookahead_gap / 100.0).min(1.0));
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Penalize dead space far below the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins that are already more filled than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If lookahead chains perfectly into an empty bin, allow it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Late in stream: prefer closing bins tightly, keep few open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item exactly fills the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item still fits in leftover: mild reward proportional to tightness
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving medium dead space
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when plenty of open bins have space
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty grows with open bins and mean residual
        score += 20.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // early in stream, opening bins is cheaper (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        // reward packing into existing bins when many are open
        score -= 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from mean (tighter than average)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Slight bias to use larger residual bins for large items
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress.
    // Later in the stream, residual waste matters more (quadratic coupling).
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Penalize tiny residuals that become dead space, smoothly.
    score += 6.0 * (1.0 - norm_pr) * norm_pr * (1.0 - norm_pr) * cap * 0.0;

    // Reward tight fits: subtract when post_residual is small, scaled by progress.
    score -= (1.0 - norm_pr).powi(3) * 8.0 * (0.5 + progress);

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        score -= fits_next * (next_item_size as f64 / cap) * 5.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, more so early (prefer consolidation early).
    let is_new_bin = (bin_residual as u32 == bin_capacity) && item_size > 0;
    if is_new_bin {
        score += pr * (1.2 - 0.7 * progress) + 4.0 * (1.0 - progress);
        // Favor new bin if it perfectly fits item (zero waste).
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mean residual alignment: prefer bins near mean residual (smooth).
    score += 0.3 * ((pr - mean_residual) / cap).abs() * cap * 0.1;

    // Slight penalty for many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as u32; // 0: <25%, 1: 25-50%, 2: 50-75%, 3: >75%

    // Reward tight fits: dead space below small-item size is nearly worthless.
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 20 {
        score -= 30.0;
    }

    // Penalize residuals that no typical item can use (dead zone between classes).
    if post_residual > 80 {
        // Large residual is fine — still very usable.
        score -= 25.0;
    } else if post_residual >= 40 && post_residual <= 55 {
        // Mid dead-zone: too big for small items, awkward for medium.
        score += 8.0;
    }

    // Modulo arithmetic on post_residual: residuals matching common item sizes are valuable.
    let usable = [10u32, 20, 25, 30, 40, 50, 60, 80];
    for u in usable.iter() {
        if post_residual >= *u && (post_residual % u == 0 || post_residual - *u < 10) {
            score -= 15.0;
            break;
        }
    }

    // Integer-division threshold: residual that can still hold the lookahead item is good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if it fits exactly into a harmonic class boundary.
        if (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // This bin becomes dead after placement if lookahead can't fit.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make it unattractive early, more acceptable late in stream
    // or when many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress - 0.3 * open_bins_count as f64;
        if mean_residual > 30.0 {
            score -= 10.0; // existing bins fragmented; a fresh bin may help
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative — open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize "dead space": small leftover gaps that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger leftovers are more reusable; soften the base residual term.
        score -= 5.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using the LAST bin that can fit the item (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins when a tight fit exists.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate: default moderate score; open a new bin only when no open bin
    // offers a tight fit (tight fits get big rewards above, beating this baseline).
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Reward perfect 2-step match: post_residual == next_item_size
    if next > 0.0 && post == next {
        score -= 40.0 + 0.5 * (capacity - post);
    }

    // Penalize large post_residual that cannot host the next item (dead space)
    if next > 0.0 && post < next {
        score += 8.0 * (next - post) / capacity;
    }

    // Reward post_residual that still leaves useful slack relative to mean residual
    score -= 0.3 * (post - mean_residual);

    // Tight fits are good: small post_residual relative to capacity
    score += 10.0 * (post / capacity);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: prefer keeping bins tight and consolidated
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post / capacity);

    // Discourage spreading across too many bins
    score += 0.5 * open_bins_count as f64 * (post / capacity);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = next > 0.0 && post < next;
        score += if poor_fit { -5.0 } else { 60.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 6.0 * (1.0 - tight) * (item_size as f64 / bin_capacity as f64);

    // Perfect-fit amplification.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward leaving space exactly matching the next item,
    // penalize leaving space that neither fits the next item nor is useful.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item can't use this bin; leftover is pure dead space
            score += 2.0 + (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 - 8.0 * (congestion / (congestion + 3.0));
        // early stream: opening bins is cheap; late stream: consolidate.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * t;
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Global fragmentation pressure: when mean residual is high, prefer
    // filling bins deeply rather than spreading.
    if bin_residual < bin_capacity {
        let depth = (bin_residual - post_residual) as f64;
        score -= 1.5 * (depth / bin_capacity as f64) * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for using fewer bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling: tight fits (small post_residual) rewarded superlinearly.
    let norm_pr = pr / cap;
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (it / cap);

    // Penalize residuals that are too small to host typical future items (dead space),
    // smoothly via a quadratic bump centered around unusable small residuals.
    let dead = ((pr - 10.0) / cap).max(0.0);
    score += 8.0 * dead * dead * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth, graded).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * gap * gap;
        let fit_next = ((pr - next_item_size as f64) / cap).max(0.0);
        score -= 6.0 * fit_next * (1.0 - fit_next);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // but allow it late when mean residual across open bins is small (poor fits everywhere).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 6.0 + 14.0 * (1.0 - progress);
        let scarcity = (mean_residual / cap).max(0.0).min(1.0);
        score -= 18.0 * (1.0 - scarcity) * progress;
    } else {
        // Prefer bins whose residual deviates favorably from the mean (consolidation).
        let dev = (r - mean_residual) / cap;
        score -= 4.0 * dev;
    }

    // Mild pressure to close out bins as the stream progresses.
    score += 3.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small item sizes (or near capacity
    // fractions) remain reusable; awkward residuals become dead space.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = post / cap_f;

    // Penalize small-but-nonzero post_residual (dead space band)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post as f64;
    }

    // Reward exact-fit-like placements
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class via modulo: residuals divisible by 25, 20, 10, 5 are
    // statistically more likely to be filled by future items.
    let divisibility_bonus = if post_residual % 25 == 0 {
        18.0
    } else if post_residual % 20 == 0 {
        14.0
    } else if post_residual % 10 == 0 {
        10.0
    } else if post_residual % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= divisibility_bonus;

    // Lookahead coupling: reward if post_residual can host next_item_size exactly
    // or with small waste; penalize if it nearly (but not) fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= 20.0 - waste as f64 * 0.5;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item cannot use this residual: residual likely dead
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: neutral baseline tied to mean residual pressure.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when open bins are already tight on average
        // and many bins are open; bad early in the stream or when mean residual
        // is large (existing bins have room).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 35.0 + mean_residual * 0.4 - progress * 15.0
            - (open_bins_count as f64).min(20.0) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score += 10.0; // big next item: fresh bin attractive
        }
    }

    // Mild non-linear tightening: quadratic penalty on mid-range residuals
    let mid = (frac - 0.5).abs();
    score += mid * mid * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Tight fit bonus.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // If this bin is the last chance to avoid opening a new bin, reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        // If next item is small, a fresh bin keeps large residual for it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // If next item fits exactly in this bin's post_residual, big reward (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here; slight penalty
    }

    // Open-bin pressure: discourage proliferation of bins mid-stream.
    score += 0.4 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below mean residual (fill emptier-trending bins less).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect chain fit bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leaving a residual smaller than any plausible item (dead space)
        if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Relative to mean residual: bins already fragmented are less attractive
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin before opening a new one: strong bonus to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
        // But if no open bin fits well (large item, small residuals), new bin is fine
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Late-stream tightening: waste hurts more near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasting little space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64);

    // Penalize residual that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead: if the next item can fill post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use the residual: mild penalty proportional to gap
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_penalty = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        // Early in the stream: opening bins is cheap; later: prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 60.0 * progress - avg_fit_penalty * 0.3;
        if item_size >= 70 {
            score -= 15.0; // big items deserve fresh bins
        }
        if post_residual == 0 {
            score -= 100.0; // perfect new-bin placement
        }
    }

    // Prefer consolidating into bins whose residual is near item_size.
    let diff = (bin_residual as f64 - item_size as f64);
    score += 0.2 * diff * diff / bin_capacity as f64;

    // Mild pressure to keep number of open bins down early on.
    score += 0.5 * (open_bins_count as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: progress modulates how harshly dead space is penalized
    let progress_weight = 1.0 + 2.0 * t * t; // quadratic ramp in t

    // Post-residual polynomial shaping (quartic-ish curvature, smooth)
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += progress_weight * (norm_pr * norm_pr * norm_pr) * bin_capacity as f64;

    // Tight fit bonus: subtract a smooth bump when post_residual is small
    let tightness = 1.0 - norm_pr;
    score -= progress_weight * 8.0 * tightness * tightness * tightness;

    // Last-chance bin reward (smooth in fitting_bins_count)
    if fitting_bins_count > 0 {
        let urgency = 1.0 / fitting_bins_count as f64;
        score -= 10.0 * urgency * (1.0 + t);
    }

    // Penalize bins far below mean residual (wasteful spread), smooth coupling with t
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * (1.0 - t) * dev * dev * bin_capacity as f64;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (gap / bin_capacity as f64) * (1.0 + t);
        } else {
            score += 2.0 * (-gap / bin_capacity as f64) * (1.0 + t);
        }
    }

    // Mild penalty for opening a new bin when many bins are open (smooth in open count)
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot sizes" (capacity fractions) remain
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Reward landing on exact harmonic boundaries (perfect fills)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual == quarter {
        score -= 8.0;
    } else if post_residual == half {
        score -= 4.0;
    } else if post_residual == eighth {
        score -= 2.0;
    }

    // Penalize dead space below the minimum item size (1..=100 unknown, use small threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Modular coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly -> strong reward
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                score -= (next_item_size as f64) * 0.15;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted space
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // current item is large relative to capacity or few bins fit it
    if bin_residual == bin_capacity {
        let large_item = item_size > half;
        if large_item || fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            // prefer reusing existing bins over opening new ones
            score += 10.0 + (open_bins_count as f64) * 0.2;
        }
    }

    // Prefer bins with residual below mean (tighter bins get filled first)
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Progress-based mild pressure: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.02;

    // Integer-division harmonic threshold on post_residual
    let class = post_residual / eighth; // 0..8 harmonic class
    score += (class as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept another item (min item size 1, but practically small gaps)
    // are pure waste. Penalize heavily when post_residual is tiny but nonzero.
    if post_residual > 0 && post_residual <= 8 {
        score += 40.0 * (1.0 + (8 - post_residual) as f64 / 8.0);
    } else if post_residual > 8 && post_residual < 16 {
        score += 12.0 * (1.0 - (post_residual as f64 - 8.0) / 8.0);
    }

    // Reward very tight fits (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 4 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        score = bin_capacity as f64 + 18.0 + 2.0 * open_bins_count as f64;
        // If this item is a last chance (only one fitting bin), opening a new
        // bin is comparatively better than wasting that bin's flexibility.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
        return score;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize less tightly fitting placements less).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the final fitting bin rather
    // than opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit post residual but could fit
    // elsewhere, mild penalty for fragmenting.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Mean-residual coupling: placing into a bin with residual far below
    // mean wastes the mean; slight normalization.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Stream progression: early on, be more selective about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Strong reward for near-perfect fit
    if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 15.0 * next_fit_tightness;
        if next_item_size == post_residual {
            score -= 25.0; // perfect 2-item packing
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item can't use
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.15 * waste;
        if post_residual < next_item_size && post_residual < 10 {
            score += 10.0; // tiny unusable sliver
        }
    }

    // Compare against mean residual across open bins
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 8.0; // leaving less than average waste is good
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 6.0; // leaving much more waste than average
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are all poor fits
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { -50.0 } else { 25.0 + 5.0 * (fitting_bins_count as f64) };
        score += urgency;
        // Early in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to prefer bins with less residual (best-fit flavor)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible future item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0;
        }
        // If next item barely misses, slightly penalize creating a near-miss gap
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let mean_fit_penalty = if mean_residual >= item_size as f64 { 0.0 } else { 20.0 };
        score += 45.0 - mean_fit_penalty
            - 0.05 * (open_bins_count as f64)
            + 0.3 * mean_residual.min(100.0);
        // Late in stream, prefer closing out open bins rather than spreading
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild preference for fuller bins among many open bins
    score -= 0.02 * open_bins_count as f64 * tightness;

    // Small time-dependent noise-free diversification
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (progress - 0.5) * (mean_residual / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = post;

    // Smooth tightness reward: reward small post_residual non-linearly.
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Reward exact-ish fills even more with cubic coupling.
    score -= 20.0 * tightness.powi(3) * (0.5 + 0.5 * progress);

    // Penalize dead space: unusable residual (smaller than min item) is bad.
    let dead = (post < item_size as f64 * 0.15) as f64;
    score += 15.0 * dead * post / cap;

    // New-bin candidate: penalize mildly, more so early (prefer filling open bins),
    // but relax penalty late when fragmentation dominates.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
        // If many open bins are fragmented, opening a fresh bin is attractive.
        score -= 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: bonus if post_residual accommodates next item (chain packing).
    if next_item_size > 0 && (post as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / post;
        score -= 12.0 * fit_frac * (1.0 - fit_frac) * (0.5 + progress);
    }

    // Prefer bins whose residual deviates from the mean (consolidate fullness).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class logic: post_residual modulo classes.
    // Residuals in classes that small items (<=10) can still fill are valuable.
    let fillable_small = post_residual <= 10 && post_residual > 0;
    if fillable_small {
        score -= 8.0;
    }
    // Residuals that only a mid item (11..30) can fill: mildly valuable
    if post_residual > 10 && post_residual <= 30 {
        score -= 3.0;
    }
    // Dead zone: 31..49 residual is hard to fill without wasting
    if post_residual >= 31 && post_residual <= 49 {
        score += 6.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0 - gap as f64 * 0.7;
            } else {
                score += gap as f64 * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize new-bin candidate unless current bins fit poorly
    if bin_residual == bin_capacity {
        // New bin: baseline cost of opening
        score = item_size as f64 * 0.5 + 25.0;
        // If many bins already fit the item, opening new is bad
        if fitting_bins_count > 0 {
            score += 30.0 + 10.0 * fitting_bins_count as f64;
        }
        // Early in stream, prefer consolidating; late, allow spreading
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Mild pressure toward bins with lower-than-mean residual (denser bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Prefer filling bins with more remaining siblings? slight bias by occupancy fraction
    let occupancy = 1.0 - bin_residual as f64 / cap;
    score -= occupancy * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large usable ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving space exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure against accumulating many open bins when a new bin is viable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * (bin_residual == bin_capacity) as i32 as f64;

    // Slightly prefer bins tighter than the average residual.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
