pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Smooth non-linear coupling: polynomial penalty on wasted residual, modulated by stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress;
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= (2.0 + 8.0 * progress) * tightness * tightness;

    // Lookahead: reward residual that can still fit the next item, penalize residual just below it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Prefer reusing existing bins over opening new ones, weighted by current congestion.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 3.0 + 0.05 * open_bins_count as f64;
        // New bin more attractive late in the stream when mean residual is fragmented.
        score += 0.02 * mean_residual * progress;
    } else {
        score -= 1.0;
    }

    // Mild attraction toward bins whose residual is close to the item (best-fit flavor, smooth).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "nice" capacity fractions
    let pr = post_residual as u32;
    let classes: [(u32, f64); 8] = [
        (0, -30.0),      // perfect fit
        (10, -14.0),     // smallest item class
        (20, -10.0),
        (25, -12.0),     // quarter class
        (50, -8.0),      // half class
        (33, -6.0),
        (40, -5.0),
        (75, -4.0),
    ];
    for (c, bonus) in classes.iter() {
        if pr == *c {
            score += bonus;
        }
    }

    // Modulo-10 harmonic banding of post_residual
    let m = pr % 10;
    score -= match m {
        0 => 6.0,
        5 => 4.0,
        2 | 8 => 1.5,
        _ => 0.0,
    };

    // Penalize awkward dead space via integer division thresholds
    if pr > 0 && pr < 10 {
        score += 12.0; // tiny unusable sliver
    } else if pr >= 10 && pr < 25 {
        score += 3.0;  // only fits smallest class
    }

    // Lookahead coupling: does post_residual fit next item nicely?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            let rem2 = pr - n;
            if rem2 == 0 {
                score -= 18.0; // chained perfect fit
            } else if rem2 % 10 == 0 {
                score -= 8.0;
            } else if rem2 < 10 {
                score += 4.0; // creates sliver for next step
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot follow in this bin; slight penalty if this bin becomes near-wasted
            if pr < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.35 * cap;
        if poor_fit {
            score -= 8.0 + 6.0 * progress;
        } else {
            score += 10.0; // keep using existing bins when fit is decent
        }
        // discourage bin proliferation
        score += 0.8 * open_bins_count as f64;
    }

    // Mild pressure toward bins tighter than the mean residual
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Progress-based tightening: later in stream, prefer tighter fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item (1..100 interface, but typical sizes >= 10) are unusable waste.
    let min_item = 10u32.min(bin_capacity);
    if post_residual < min_item {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 120.0; // perfect fit: strongly favored
    } else {
        // Reward tight fits: small positive post_residual is good.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Penalize post_residual that cannot host the lookahead item (k=2) but is
    // otherwise "usable" — creates stranded gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residuals that exactly accommodate the next item too.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin leaves residual = capacity - item_size,
    // which is large; make it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score -= 15.0;
        score += 0.5 * (open_bins_count as f64);
    }

    // Mild preference toward bins whose residual is near the mean (balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits into the post residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to how close the next item fits (slack small is good).
