        // scaled by how badly it misses (small miss = small penalty).
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 + 20.0 * (1.0 - miss / bin_capacity as f64);
    }

    // Penalize post residuals that are too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // if the item is large relative to mean residual (poor fits everywhere).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0;
        if mean_residual > 0.0 {
            let tight = item_size as f64 / mean_residual;
            if tight > 0.9 {
                new_bin_penalty *= 0.3;
            } else if tight > 0.7 {
                new_bin_penalty *= 0.7;
            }
        }
        // Later in the stream, slightly discourage leaving many open bins.
        if open_bins_count > 6 {
            new_bin_penalty *= 0.8;
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins that are already more filled (small residual
    // relative to mean residual) to consolidate waste.
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        let rel = bin_residual as f64 / mean_residual;
        score += 8.0 * (rel - 1.0).clamp(-1.0, 1.0);
    }

    // Slight end-of-stream urgency: pack tightly as we approach the end.
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward partial compatibility, scaled by how much slack remains after both items
            let after_next = post_residual as i64 - next_item_size as i64;
            score -= 8.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover space: mild penalty proportional to mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.05 * mismatch.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64) / (bin_capacity as f64)
        };
        // A fresh bin leaves a full-capacity residual: penalize it, but less when
        // the stream is early (more future items to fill it) or many bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 + 10.0 * progress - 0.15 * (open_bins_count as f64).min(20.0);
        // If the item perfectly fills a fresh bin later in the stream, allow it.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 10.0;
        }
        let _ = poor_fit_elsewhere;
    } else {
        // Prefer bins whose residual is below the mean residual (consolidate emptier space).
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Time horizon: later in the stream, prefer minimizing bin count aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling: waste penalty grows non-linearly with progress
    let waste_coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += 6.0 * waste_coupling;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-free ramp)
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (0.3 + progress);

    // Lookahead: reward residual that can host the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - ((pr - nx) / cap).abs();
            score -= 4.0 * fit_quality * (0.4 + 0.6 * progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bin: penalize opening new bins, especially late in stream
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open relative to mean residual (fragmentation)
    let frag = (open_bins_count as f64) * (mean_residual / cap) * pr_norm;
    score += 0.5 * frag;

    // New-bin candidate: prefer it only when residuals elsewhere are large and item is small
    if bin_residual == bin_capacity {
        let spread = mean_residual / cap;
        score = 20.0 + 40.0 * spread * (1.0 - progress) - 15.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are prized.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 5 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 12.0;
    }

    // Dead-space penalty for unusable residuals relative to item-size granularity.
    if pr > 0 && pr < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Modulo structure: residuals that are multiples of common item sizes are reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Harmonic coupling with next item (k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0; // next item exactly fills this bin
        } else if next_item_size <= pr {
            let ratio = next_item_size as f64 / pr as f64;
            score -= 20.0 * ratio; // prefer bins where next item fills most of residual
        } else {
            score += 10.0; // next item cannot use this bin's residual
        }
        // Harmonic class match: next item divides residual evenly
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; penalize opening when good fits exist.
        score = 55.0 + 0.15 * (open_bins_count as f64);
        if fitting_bins_count > 0 {
            // if some open bin fits, discourage new bin unless residuals are all large
            let mean_r = mean_residual;
            if mean_r < item_size as f64 + 10.0 {
                score += 30.0; // open bins are tight, new bin reasonable
            } else {
                score += 60.0;
            }
        } else {
            score -= 100.0; // nothing fits anywhere: definitely open new bin
        }
    }

    // Tightness reward: bins with small residual before placement are valuable to fill.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Stream progression: late in the stream, prefer consolidating into few bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when open bins are loose, prefer filling the loosest structure.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps that nothing typical can use)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strong penalty for leaving a gap just below a plausible item size range
    if post_residual >= 1 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New-bin candidate: penalize unless the current item is large and
    // existing residuals are poor fits
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        if item_size >= 70 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Lookahead: if next item would fit the post-residual exactly, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 3.0 {
            score -= 30.0;
        }
    }
    // Penalize if next item won't fit and post-residual is a stranded gap
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins tighter than average (better packing density)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits perfectly into
    // the post-residual, this is an ideal two-item packing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits; reward proportionally to how snug the pair is.
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 120.0 - slack * 4.0;
            } else {
                score -= (20.0 / slack).max(2.0);
            }
        } else {
            // Next item will NOT fit in this bin's remainder: penalize
            // leaving a dead residual that nothing may use later.
            let dead = post_residual as f64;
            score += dead * 0.6;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 30.0;
    }

    // Compare residual against the mean residual of open bins:
    // prefer bins that are already more loaded than average (packing
    // into fuller bins keeps many partially-filled bins available).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid).min(50.0) * 1.5;
    } else {
        score += (resid - mean_residual).min(50.0) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins can still accommodate,
    // scaled by how many bins are already open (bin proliferation cost).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + open_bins_count as f64 * 10.0 * (0.5 + progress);
    }

    // Mild bonus for using bins early in the stream (keeps options open).
    score -= (1.0 - step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Dead-space penalty: residuals too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Post-residual can host next item: reward closeness of that fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual cannot host next item: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / bin_capacity as f64).min(1.0);
        }
        // If next item also fits here after placing current one, big bonus.
        if next_item_size <= post_residual && next_item_size >= 10 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bin fit is poor (large post_residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 here
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).recip()
        } else {
            1.0
        };
        // Open a new bin only when many bins fit and the best fit would waste a lot.
        let waste_elsewhere = if fitting_bins_count > 0 {
            // approximate: mean residual signals typical waste
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else {
            1.0
        };
        score += 60.0 - 45.0 * waste_elsewhere - 20.0 * (1.0 - pressure);
        // Late in the stream, prefer consolidation into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // Too many open bins already: discourage opening another.
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Encourage bins whose residual is above average (use the "roomy" bins first),
    // keeping tight bins for smaller future items.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= 2.0 * (diff / bin_capacity as f64);
    }

    // Mild reward for using many open bins instead of spreading.
    if bin_residual != bin_capacity && open_bins_count > 0 {
        score -= 1.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (1.0 - (nx / pr)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Slight penalty when many bins are open and residual far from mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: keep it moderately attractive only for large items / bad fits
    if bin_residual == bin_capacity {
        score += 5.0 - 6.0 * (item_size as f64 / cap) + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable, reward them.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { class_bonus += 6.0; }
        if pr % 20 == 0 { class_bonus += 4.0; }
        if pr % 25 == 0 { class_bonus += 4.0; }
        if pr % 50 == 0 { class_bonus += 6.0; }
        // exact fill is perfect
        if pr == 0 { class_bonus += 40.0; }
    } else {
        class_bonus += 40.0;
    }
    score -= class_bonus;

    // Dead-space penalty: residuals in awkward zones (1..10 or 11..19 style
    // slivers) are nearly unusable for items >= 10... but sizes go down to 1,
    // so scale awkwardness by how small the residual is relative to capacity.
    if pr > 0 && pr <= 10 {
        score += 12.0;
    } else if pr > 10 && pr < 20 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // how well the next item's own post-residual class behaves
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 8.0; }
            if npr <= 5 { score += 6.0; }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64).min(20.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // the residual left behind in other bins; penalize proportionally to how
    // full the stream is and how many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual.max(0.0) * 0.5;
        score += 18.0 + waste + progress * 10.0 + open_bins_count as f64 * 0.5;
        // but if item is huge, a fresh bin is naturally fine (post_residual small)
        score -= (bin_capacity - post_residual) as f64 * 0.15;
    }

    // Prefer tighter fits generally: scale by fraction of bin consumed.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Mild preference to consolidate into fewer bins early on.
    score += (open_bins_count as f64) * 0.1;

    // Small tie-break noise-free deterministic jitter based on residual class.
    score += ((pr as f64) * 0.017).sin() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: fraction of residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: if next item fits exactly in post_residual, big reward;
    // if next item can't use post_residual, penalize leaving it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            score -= 4.0; // next item also fits, chain packing is good
        }
    }

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.35;
        if poor_fit && item_size >= 50 {
            score -= 18.0;
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild stream progression: later in stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Slight pull toward bins near mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 500.0; // next item will perfectly fill this bin
        } else if diff > 0 {
            // next item fits: mild reward proportional to tightness
            score -= 50.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize creating dead space
            score += 30.0 * (-diff) as f64;
        }
    }

    // Penalize small unusable post_residual (dead space) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins whose residual is below mean (tight bins get filled first),
    // penalize placement in bins far above mean residual.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mildly penalize so we only open new bins when
    // placements elsewhere are truly bad; relax penalty late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 50.0 * progress;
        // If next item is huge and current item is small, opening fresh bin is attractive.
        if next_item_size > bin_capacity / 2 && item_size < 20 {
            score -= 100.0;
        }
    }

    // Slight preference for bins that already hold a similar-size item pattern:
    // reward when item consumes a large fraction of the residual.
    if bin_residual > 0 {
        score -= 20.0 * (item_size as f64 / bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize large post-residuals nonlinearly (dead space that likely goes unused).
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Lookahead: if next item fits into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        score -= 25.0;
        // Extra coupling: even better if the pair nearly exhausts the bin.
        let pair_fill = (item_size as f64 + next_item_size as f64) / bin_capacity as f64;
        score -= 20.0 * pair_fill * pair_fill;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that is awkwardly close to but below the next item.
        let gap = pr - (next_item_size as f64 - 1.0);
        if gap >= 0.0 && gap < 10.0 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 2 {
        score -= 0.5 * open_bins_count as f64 * fill;
    }

    // Compare residual to the global mean residual: bins above mean are "emptier",
    // prefer filling emptier bins first to keep tight bins for tight items.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score -= 5.0 * (rel - 1.0);
    }

    // Time horizon: late in the stream, be more conservative — prefer exact fills,
    // penalize opening new bins implicitly via higher new-bin scores.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (pr / bin_capacity as f64);

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when current bins are very full
        // or the item is huge and would leave awkward residuals elsewhere.
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let mut new_score = 40.0;
        new_score -= 25.0 * avg_fill * avg_fill; // cheaper to open new bin when others are full
        if next_item_size > 0 && next_item_size <= item_size {
            new_score -= 5.0; // next item can stack into the fresh bin
        }
        if fitting_bins_count <= 1 {
            new_score -= 20.0;
        }
        score = score.max(new_score) + (score - score); // keep signature usage
        score = new_score + 0.001 * pr; // tiny tie-break
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.12;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of 10, 25, 50) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward residue
    };
    score += class_bonus;

    // Dead-space penalty: tiny leftovers that few future items can use.
    if pr > 0 && pr < 10 {
        score += 15.0 * (10 - pr) as f64 / 10.0;
    }

    // Lookahead coupling: reward if next item fits harmonically into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // exact chain fit
        } else if next_item_size <= pr {
            let r2 = pr - next_item_size;
            if r2 % 10 == 0 {
                score -= 10.0;
            } else if r2 % 5 == 0 {
                score -= 5.0;
            }
            score -= (next_item_size as f64 / cap) * 8.0;
        } else {
            // next item won't fit here: penalize wasting large residuals on small items
            score += (next_item_size as f64 / cap) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer filling existing bins over opening new ones as stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open / late stream.
        score += 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Coupling with mean residual: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Integer-division threshold: bins with residual in [item_size, item_size+9]
    // (same decade) give near-perfect packing; reward via quotient structure.
    if pr / 10 == (bin_residual - item_size) / 10 && pr >= item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A post_residual that is too small to ever hold a future item (>= 1) is pure waste,
    // but gaps in the "hard to fill" band (1..=20) are the worst offenders.
    if post_residual > 0 {
        let dead = (20u32.saturating_sub(post_residual)) as f64;
        score += 3.0 * dead;
        // Perfect or near-perfect fits are highly desirable.
        if post_residual == 0 {
            score -= 50.0;
        } else if post_residual <= 5 {
            score -= 10.0;
        }
    }

    // Reward tight fits: post_residual small relative to item_size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 8.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another.
    if bin_residual == bin_capacity {
        score += 12.0 * open_bins_count as f64;
        // But allow opening a new bin if the item would leave a bad gap in existing bins.
        if post_residual > 25 {
            score -= 6.0;
        }
    } else {
        // Slight reward for using existing bins as open_bins_count grows.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use the leftover; leftover is more likely dead space.
        score += 4.0;
    }

    // Alignment with mean residual: prefer bins whose post_residual is near the mean
    // (keeps residual distribution balanced, easier to pack later).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * drift;

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this leftover; penalize large leftovers
            score += 0.15 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open (fragmentation).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if no bin fits well, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Global pressure: if mean residual is low, conserve space in fuller bins.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Time horizon: late in stream, be greedier about tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let it_norm = it / cap;

    // Base: penalize leftover residual, but with a non-linear (quartic) waste curve
    let mut score = 2.0 * pr_norm * pr_norm * pr_norm * pr_norm + pr_norm;

    // Smooth coupling: large post_residual hurts more as the stream progresses
    score += 3.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: interaction of item size with residual
    score -= 1.5 * it_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize bins whose residual deviates from the mean residual (imbalance)
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.5 + 1.5 * progress;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly (smooth via ratio)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_q = 1.0 - ((pr - nx) / cap).abs();
            score -= 2.0 * fit_q * fit_q;
        } else {
            // next item won't fit: mildly penalize leaving too-large residual
            score += 0.5 * pr_norm * (1.0 - progress);
        }
    }

    // Many open bins: prefer consolidating into existing bins (smooth in open count)
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: make an empty bin slightly unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 1.2 + 2.0 * (1.0 - progress) - 0.5 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish score so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer keeping items in open bins; penalty grows with item size
        // (large items open new bins more readily since residual stays usable).
        let base = bin_capacity as f64 * 0.55 + 8.0 * (1.0 - tightness);
        // Late in stream, opening a new bin is cheap (no future to plan for).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        return base - 20.0 * progress * progress;
    }

    // --- Best-fit core: exact fill is perfect ---
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Harmonic class logic: classify post_residual by capacity fractions.
        let classes: [u32; 5] = [bin_capacity / 4, bin_capacity / 3, bin_capacity / 2, 2 * bin_capacity / 3, 3 * bin_capacity / 4];
        let mut class_index = 5;
        for (i, &c) in classes.iter().enumerate() {
            if post_residual <= c {
                class_index = i;
                break;
            }
        }
        // Small class index = small residual = tight fit => reward.
        score -= (5 - class_index) as f64 * 12.0;

        // Dead-space penalty: residual below the smallest item size is unusable.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Chain bonus, stronger if the chain nearly exhausts the bin.
        let chain_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 + 25.0 * chain_fill;
        // Modulo harmony: next item divides residual evenly => great pairing.
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item can't follow here; slight penalty scaled by how far off.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins already below mean residual (consolidating emptiness).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for bins with more remaining usable space when many bins open.
    score += (open_bins_count as f64).ln().max(0.0) * post_residual as f64 * 0.02;

    // Integer-division threshold: penalize leaving residual in the awkward
    // (capacity/2, capacity/2 + 10) dead zone.
    let half = bin_capacity / 2;
    if post_residual > half && post_residual <= half + 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect fill relative to capacity: tiny post_residual fraction.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Open-bin pressure: discourage spreading across many open bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap — the gap is likely wasted.
        score += 0.3 * (post_residual as f64);
    }

    // New-bin candidate: keep it neutral-ish but slightly penalized so it only
    // wins when all open bins are poor fits (dead-space penalty dominates).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if next item is large, a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Progression: early in stream, be slightly more conservative with bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 400.0; // perfect 2-chain: next item fills this bin exactly
        } else if slack <= 10.0 {
            score -= 120.0 - slack * 4.0;
        } else {
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize dead space relative to next item
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare post_residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins are open, or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 180.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 100.0; // fresh bin can host the lookahead too
        }
    }

    // Late in the stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Many open bins: discourage spreading across bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Placing here would break the next item's fit; penalize mildly.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Global mean residual coupling: if this bin is much fuller than average, reward.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Time horizon: early in stream, be more open to starting new bins;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * fill * progress;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor
    // (high post_residual would be wasted) or item is large.
    if bin_residual == bin_capacity {
        let best_alternative_penalty = 8.0 * (1.0 - fit_ratio);
        score += best_alternative_penalty;
        score -= 4.0 * progress;
        if item_size >= 60 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Reward tight fits: subtract a smooth non-linear term of post_residual ratio
    let pr_ratio = post_residual as f64 / cap;
    score -= (1.0 - pr_ratio).powf(2.0) * (cap * 0.35) * (1.0 + progress);

    // Penalize creating dead space that can't fit the next item (lookahead coupling)
    if next > 0.0 && post_residual > 0 {
        let gap = (next - post_residual as f64).max(0.0) / cap;
        score += gap.powf(1.5) * cap * 0.5 * (1.0 - progress);
    }
    // Reward bins whose residual perfectly anticipates the next item
    if next > 0.0 && next <= post_residual as f64 {
        let util = next / post_residual as f64;
        score -= util.powf(2.0) * item * 0.4;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (1.0 + progress);
    }

    // Mild penalty when bin is far below mean residual (keeps residuals homogeneous)
    score += ((post_residual as f64 - mean_residual) / cap).abs().powf(2.0) * cap * 0.15;

    // Discourage opening new bins when open bins fit well, more so late in stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += cap * (0.25 + 0.5 * progress) * (1.0 - pr_ratio.min(1.0));
    }

    // Slight preference for filling larger items into bins with small residuals
    score -= (item / cap) * (bin_residual as f64 - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1

    // Perfect fit: heavily reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Near-perfect fits (small unusable residue) still rewarded
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0 - (post_residual as f64) * 2.0;
    }

    // Integer-division harmonic classes: post_residual in [0,10), [10,20), ... [90,100)
    let class = post_residual / 10; // 0..10
    let class_center = (class * 10 + 5) as f64;
    // Dead space penalty grows superlinearly for mid-range residuals that few item sizes can fill
    score += 0.05 * (class_center - 50.0).abs() * (class as f64);

    // Modulo arithmetic on capacity: residuals that match common item-size residues are reusable
    let common: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut reusable = false;
    for &s in common.iter() {
        if post_residual >= s && post_residual - s.min(post_residual) <= 10 {
            reusable = true;
        }
        if post_residual >= s && post_residual < s + 10 {
            score -= 15.0; // residual exactly accommodates a common size
        }
    }
    if reusable {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / c);
        } else {
            // next item cannot follow here; penalize if this bin would be stranded
            score += 10.0;
        }
        // Harmonic pairing: next_item_size + item_size divides capacity nicely
        if (item_size + next_item_size) <= bin_residual && bin_residual % (item_size + next_item_size) == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity C - item_size
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its future residual
        score = (bin_capacity - item_size) as f64 + 5.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0; // new bin can chain the next item
        }
        // Late in stream, avoid opening bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress * (1.0 - item_size as f64 / c);
    }

    // Prefer filling bins far below mean residual (tightest fit logic)
    score -= 0.3 * (mean_residual - pr);

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful later are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // barely usable
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, no dead space at all
    }

    // Reward tight fits relative to the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight match).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    }
    // Penalize if post_residual can't hold the next item and is small anyway.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 25 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score += 70.0 - 10.0 * pressure;
    }

    // Stream progression: early on, be more willing to open bins (long horizon to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    // Mean residual alignment: prefer bins near the average residual state.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Strong reward when next item fills the remaining space (perfect chain).
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 30.0; // exact chain match bonus
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to the leftover dead space.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Penalize post_residual that is small but not zero (unusable sliver).
    if post_residual > 0 {
        let r = post_residual as f64;
        let min_item = 1.0;
        if r < min_item * 5.0 {
            score += 15.0 * (1.0 - r / (min_item * 5.0));
        }
    }

    // Prefer bins whose residual is below average (denser bins keep tighter control).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be more willing to spread items (mild penalty on full bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * (bin_capacity as f64 - post_residual as f64);

    // Slight penalty when many bins are open already (encourage consolidation).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste more strongly as it shrinks.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 18.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: penalize if next item would not fit in the post residual.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0;
        } else {
            let slack = post_residual - next_item_size;
            score -= (slack as f64).ln() * 2.0;
            // Bonus if next item perfectly consumes remaining space.
            if slack == 0 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);

    // Prefer bins with residuals below the mean residual (fill laggard bins).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: open a fresh bin only when fits are poor and
    // existing bins are fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.35;
        let fragmented = mean_residual < 25.0;
        if poor_fit && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        } else {
            score += 10.0 + 5.0 * (1.0 - fit_ratio);
        }
    }

    // Late in the stream, tighten up: avoid opening bins near the end.
    if progress > 0.85 && bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let prog = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = 0.5 + prog;
    score += 12.0 * norm_pr * norm_pr * p;
    score -= 6.0 * norm_pr * fit * (1.0 - prog);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (2.0 + 8.0 * prog);

    // Penalize creating residual that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * gap * gap * (0.5 + prog);
        // Reward residual that exactly accommodates next item
        let cover = (pr - next_item_size as f64).abs() / cap;
        score -= 4.0 * (1.0 - cover.min(1.0)) * (1.0 - prog);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * prog;
    }

    // Mild dispersion penalty: prefer bins near mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // Slight preference to keep few bins open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by integer division.
    // Small leftovers (class 0: 0..=5) are near-perfect fits -> strong reward.
    let cls = post_residual / 6; // 0..=16 classes for cap 100
    score -= match cls {
        0 => 40.0,
        1 => 22.0,
        2 => 10.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Modulo coupling: leftover that pairs with common small sizes (mod 10 bands)
    // is reusable by future items; reward residuals in [10, 30] range more.
    let pr = post_residual;
    if pr >= 10 && pr <= 30 {
        score -= 8.0 + (30 - pr) as f64 * 0.3;
    } else if pr > 30 && pr <= 50 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if slack < 6.0 {
            score -= 15.0; // near-perfect two-item chaining
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // leftover too small for next item: dead space risk, mild penalty
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean residual pull: prefer bins whose residual deviates below the mean
    // (they are "almost full", finish them off).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.25;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only attractive when no good fit exists (large post_residual would be
    // penalized anyway); add a fixed opening cost so it's chosen only when
    // existing fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    // Perfect fit absolute reward
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead gap is worthless
    }
    // Penalize residual that cannot fit the next item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that can accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Bonus if post_residual is a near-perfect fit for the next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    }
    // Reward tight fits of the current item (small post_residual relative to bin).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness);

    // Open-bins pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + 0.5 * progress;
    score += 0.4 * (open_bins_count as f64) * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // If several bins fit, prefer the one closest to mean residual (balanced use).
    if fitting_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.25 * dev;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item or all residuals too small). Make empty bin mildly costly.
    if bin_residual == bin_capacity {
        let good_open_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual >= item_size as f64;
        if good_open_exists {
            score += 30.0; // prefer reusing an open bin
        } else {
            score -= 5.0; // opening fresh is reasonable
        }
        // Late in the stream, opening new bins is cheap since bins won't be reused much.
        if progress > 0.8 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Reward fitting relative to mean residual (tighter than average is good)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when open bins could fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 1 {
        score += 20.0;
    }
    // But allow new bin if it creates a perfect future fit and current bins waste a lot
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mild preference for high occupancy early vs late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item could use the post residual, reward keeping this bin viable;
    // if next item is much larger than post_residual, residual is likely wasted.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // residual remains useful
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(80.0);
        }
        // Perfect chain: item + next fills the bin exactly
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual < 10 {
            score += 6.0; // but not if it creates tiny dead space
        }
    }

    // Many open bins: encourage consolidation into fuller bins.
    if open_bins_count > 3 {
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
    }

    // Global slack: if mean residual is high, spreading is cheap; if low, tighten.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a new bin is attractive early in the stream
    // or when current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 > 40.0; // item small relative to empty bin
        let mut new_bin_score = 30.0 * progress;
        if bad_fit {
            new_bin_score -= 15.0;
        }
        if open_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_score -= 10.0; // big next item: fresh bin useful
        }
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr_n * pr_n * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly
    let coupling = 1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress;
    score *= coupling;

    // Reward exact-ish fits with a smooth quadratic bonus
    let fit_bonus = (1.0 - pr_n) * (1.0 - pr_n) * item_size as f64;
    score -= fit_bonus;

    // Penalize bins whose residual deviates strongly from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Last-chance bin: strongly favor using it (smooth sigmoid-like weight)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 30.0 * last_chance * (1.0 - pr_n);

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (nx / cap);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Mild pressure against proliferating open bins, smoothly scaled by progress
    score += (open_bins_count as f64) * progress * 0.5;

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small for the smallest possible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) over huge leftovers.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // Penalize if post residual is just barely too small for the next item (frustrating gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // but when this is the only fitting bin, strongly favor using it.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is high.
        score += 20.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
    } else if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight early-stream aggression toward consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strongly favor exact-ish fits: small post_residual gets a bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.15; // tighter two-item packing preferred
        if slack <= 5.0 {
            score -= 15.0; // near-perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item, scaled by how big the gap is.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        // Early in the stream, opening bins is cheaper; later, avoid fragmentation.
        let early_discount = (1.0 - progress) * 20.0;
        score += base_penalty - early_discount;
        // If an open bin would leave very small post_residual, opening new bin is ok.
        if post_residual == bin_capacity && next_item_size > 0 {
            let would_leave = bin_capacity.saturating_sub(item_size) as f64;
            if would_leave < next_item_size as f64 {
                score -= 35.0; // nothing else fits well anyway
            }
        }
    }

    // Mildly discourage scattering across many open bins late in the stream.
    score += (open_bins_count as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: waste is quadratic in leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Penalize creating dead space that can never hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            // dead space relative to lookahead item
            score += (nx - post_residual as f64) * 1.5;
            // if next item would fit perfectly in post_residual, reward this placement
        } else {
            score -= 2.0; // enables chained tight packing
            // reward near-perfect pairing: leftover just above next item
            let gap = post_residual as f64 - nx;
            score -= 3.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins are tight or none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // opening a new bin costs ~1 bin; make it competitive only when mean residual is low
        score = 55.0 + 40.0 * pressure - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is mandatory
        }
    }

    // Slight preference for fuller bins among equals.
    score -= (bin_residual as f64) * 0.05;

    // Mild global balance: many open bins with high residual -> encourage consolidation.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal leftover space (tight fit).
    let mut score = post;

    // Smooth non-linear waste penalty: normalized leftover, cubed, amplified late in stream.
    let waste_norm = post / cap;
    score += (waste_norm * waste_norm * waste_norm) * cap * (0.5 + 2.0 * progress);

    // Reward near-perfect fits with a smooth valley around zero post-residual.
    let tightness = 1.0 - waste_norm;
    score -= (tightness * tightness * tightness) * cap * 0.35;

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        if post >= nx {
            // Next item can chain into this bin: reward smooth closeness of fit.
            let chain_fit = 1.0 - gap / cap;
            score -= chain_fit * chain_fit * cap * 0.6;
        } else {
            // Next item won't fit here: mildly penalize leaving a large unusable gap.
            let unusable = post / cap;
            score += unusable * unusable * cap * (0.2 + 0.5 * progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * 0.8;
    }

    // New-bin candidate handling: make fresh bins attractive only early or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tight = 1.0 - (mean_residual / cap);
        let openness = 1.0 - progress;
        // Penalize new bins when existing bins are roomy; reward when bins are nearly full.
        score += cap * (0.55 * crowd + 0.4 * openness - 0.5 * mean_tight * mean_tight);
    }

    // Smooth global pressure: many open bins with high mean residual -> prefer filling existing ones.
    let pressure = (mean_residual / cap) * (open_bins_count as f64).ln_1p();
    score += pressure * cap * 0.15 * (0.3 + progress);

    // Small quadratic dither on post-residual to break ties toward balanced residuals.
    score += (post - mean_residual) * (post - mean_residual) / cap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap_f;

    // Integer-division thresholds on post_residual (harmonic classes of C):
    // residuals in (0,10] are dead space; (10,20] marginal; larger is fine.
    let dead = (post_residual + 9) / 10; // ceil(post/10)
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual <= 10 {
        score += 25.0; // dead space below smallest item class
    } else if post_residual <= 20 {
        score += 8.0;
    } else if post_residual <= 25 {
        score += 2.0;
    }

    // Modulo-10 harmonic class of residual: prefer residuals that align with
    // common item-size classes (multiples of 10 and 5).
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m == 5 {
        score -= 3.0;
    } else {
        score += m as f64 * 0.4;
    }

    // Lookahead coupling: can next item (harmonic class) land in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if next item exactly divides the residual class
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 18.0;
        // but if it creates sub-10 dead space and a new bin would be cleaner, soften
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
            score += 12.0;
        }
    }

    // New-bin candidate (empty bin): neutral baseline, slightly worse than a
    // good existing fit but better than a bad one.
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 - 15.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Mild pull toward bins with residual close to the mean (harmonic balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Small penalty for proliferation of open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // A residual that is too small to hold any plausible future item is dead space.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Graded penalty: gaps just above zero are worse than medium gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // quadratic dead-space term, strongest for small gaps
        score += 60.0 * (1.0 - gap / bin_capacity as f64).powi(6);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit reward: fraction of residual consumed by this item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * chain;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the gap -> penalize
        score += 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early stream flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 12.0 * (open_bins_count as f64) - 30.0 * progress;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Prefer bins below mean residual (more filled bins get priority)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportional to dead space
            score += 10.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 60.0 * (1.0 - progress);
        // but allow if next item pairs well with current item in fresh bin
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 55.0;
        }
    }

    // Slight preference to fill fuller bins as stream progresses
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Reward tight fits non-linearly
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Exact or near-exact fills are gold
    if post == 0 { score -= 60.0; }
    else if post <= 3 { score -= 35.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next > 0.0 {
        if next == post { score -= 45.0; }
        else if next < post {
            let slack = post - next;
            if slack <= 5.0 { score -= 20.0; }
            else { score += slack * 0.35; } // wasted gap after next item
        }
        // next item slightly larger than post: near-miss, mild penalty
        else if next - post <= 5.0 { score += 6.0; }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive, but worthwhile when no open bin fits well
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 + pressure * 55.0;
        // Early in stream, new bins are cheaper (more future items to fill them)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If item is large, a fresh bin wastes less
        score -= item * 0.15;
    }

    // Penalize bins whose residual deviates wildly from mean (fragmentation)
    let dev = (resid - mean_residual).abs();
    score += dev * 0.08;

    // Mild penalty for spreading across many bins when few fit
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize last-chance bin usage lightly to preserve flexibility
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post_residual can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (ni / cap) * (1.0 - norm_pr);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Smooth coupling with mean residual: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + progress);

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // New-bin candidate: penalize opening a new bin unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Harmonic class of post_residual: residues modulo 8 create discrete
    // quality classes; small residues (1..4) are near-perfect fits.
    let r = post_residual % 8;
    let class_bonus = match r {
        0 => 1.8,
        1 => 2.2,
        2 => 1.4,
        3 => 1.0,
        4 => 0.4,
        5 => -0.3,
        6 => -0.7,
        _ => -1.0,
    };
    score -= class_bonus;

    // Lookahead coupling: dead space that cannot hold the next item is waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residual that exactly or nearly fits next item.
            let gap = post_residual - next_item_size;
            score -= 1.5 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Penalize unusable dead space relative to next item.
            score += 0.9 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive for large items or when
    // existing fits are all terrible.
    let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new_bin {
        score = post_residual as f64; // = capacity, naturally high
        // Large items open bins cheaply (good residual structure).
        if item_size > bin_capacity / 2 {
            score -= 1.2;
        }
        // If no open bin fits well (post_residuals large), opening is fine.
        if mean_residual > 0.35 * bin_capacity as f64 {
            score -= 0.8;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 1.5 * progress;
        // Crowding: prefer existing bins when many are open.
        score += 0.05 * open_bins_count as f64;
    } else {
        // Mild preference to spread across bins when mean residual is high.
        if bin_residual as f64 > mean_residual {
            score -= 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals 1..=9 are nearly unusable
    // (min item size is small but packing efficiency collapses), so
    // penalize them heavily beyond their raw value.
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (waste ratio penalty).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // If the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 9 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot use the residual at all, mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 9 && post_residual > 0 {
            score += 15.0; // undo part of the discount for dead space
        }
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // the fit is loose; encourage consolidation when bins are numerous.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual < bin_capacity {
        // Placing into an existing bin reduces pressure slightly when tight.
        score -= pressure * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize by open-bin pressure, but discount
        // when current best fits would leave large dead space.
        score += pressure;
        if next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — prefer filling it to keep the mean high.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.2 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty on waste.
    score += 0.02 * (post_residual as f64).powi(2);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post >= nxt {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to blocked space
            score += 0.3 * (nxt - post);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins whose residual deviates usefully.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when no open bin offers a good (chained) fit, i.e. when its raw
    // residual (capacity - item) is competitive. Slight bias toward reusing bins
    // keeps bin count low.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Mild late-stream tightening: as stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin, more strongly when
    // existing bins could fit and the item is not oversized.
    if bin_residual == bin_capacity {
        let fit_pressure = fitting_bins_count as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 60.0 + 40.0 * fit_pressure;
        // Large items waste little space in an empty bin; soften penalty.
        new_bin_penalty *= (1.0 - 0.5 * item_frac);
        // Early in the stream, opening bins is cheaper (future packing freedom).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= (1.0 - 0.4 * progress);
        // If next item is huge and this item is small, a fresh bin may pair better.
        if next_item_size > 0 && next_item_size as f64 > 0.7 * bin_capacity as f64 && item_size < 30 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
        return score;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
        // Extra reward if the leftover would still be useful for the next item.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 20.0;
        }
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer bins whose residual matches item scale.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness * tightness;
    }

    // Lookahead: penalize leaving residual just below the next item size
    // (unusable dead space for the upcoming item).
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -(next_item_size as f64) {
            score += 10.0 + (-gap) * 0.3;
        } else if gap >= 0.0 {
            // Reward residual that exactly accommodates the next item.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Global state: if mean residual across open bins is high, prefer
    // consolidating into bins with below-average residual (tighter bins).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Time horizon: late in the stream, be greedy about waste; early on,
    // keep flexibility by mildly penalizing very low post-residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins when residuals are healthy.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 6.0 * poly * cap * 0.1;

    // Penalize dead space more as the stream advances (less chance to reuse it).
    score += 4.0 * norm_post * norm_post * (progress * progress);

    // Reward near-perfect fits.
    if post == 0 {
        score -= 25.0;
    } else if post <= 5 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin bias: favor it slightly when it's the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead synergy: if next item fits the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * (1.0 - (next_item_size as f64 / post));
    } else if next_item_size > 0 {
        // Penalize leaving a residual that next item cannot use.
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate: encourage opening a fresh bin only when existing bins fit poorly.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score = cap - 10.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if post < item_size as f64 * 0.25 {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into modulo buckets.
    // Residuals that are multiples of common small sizes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus = 30.0; // perfect fit
    } else if pr % 50 == 0 {
        class_bonus = 12.0;
    } else if pr % 25 == 0 {
        class_bonus = 8.0;
    } else if pr % 10 == 0 {
        class_bonus = 5.0;
    } else if pr % 5 == 0 {
        class_bonus = 2.0;
    } else {
        class_bonus = -3.0; // awkward leftover
    }
    score -= class_bonus;

    // If next item fits exactly in the post residual, big reward (chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let nxt_class = if pr % next_item_size == 0 { 10.0 } else { 0.0 };
            score -= 4.0 + nxt_class;
        } else {
            score += 6.0; // next item won't fit here; bin likely dead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a mostly-empty bin when many bins are open (fragmentation control).
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score += (1.0 - fill_frac) * 4.0;

    // Prefer bins whose residual is close to mean (balance), mild effect.
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 35.0 - pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..100)
    // are pure waste. Penalize sharply when post_residual falls in the "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        // Small gap: only useful if next item fits exactly-ish
        if (next_item_size as f64 - post_residual as f64).abs() > 5.0 {
            score += 12.0;
        } else {
            score -= 15.0; // perfect follow-up fit reward
        }
    }

    // Reward tight fits (low post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when necessary
        score += 30.0;
        // If this is the only fitting option, new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // As stream progresses and many bins are open, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Open-bin pressure: with many open bins, prefer bins below mean residual
        // (consolidate space) to reduce fragmentation.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Mild pressure proportional to open bins count: discourage spreading
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: if next item fits the post_residual exactly, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // dead space relative to lookahead
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 2.0 * next_item_size as f64;
            score += 0.5 * chain_waste;
            if chain_waste == 0.0 {
                score -= 300.0; // exact 2-item chain fill
            }
        } else {
            // next item cannot follow: penalize proportionally to leftover unusable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize large post residual that is likely dead space
    score += 0.3 * post_residual as f64;

    // Compare against mean residual: bins with residual far below mean are precious
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.4 * dev; // tighter-than-average bin: discourage wasting it on poor fits
    } else {
        score += 0.1 * dev;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a new bin only if no good chain exists
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 20.0; // fresh bin can host the chain too
        }
    }

    // Early stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64 + 1.0)).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit a plausible next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that can still host the lookahead item.
            score -= 8.0;
            if post_residual - next_item_size <= 10 {
                score -= 10.0; // near-perfect two-item pairing
            }
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 100.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 40.0 + 30.0 * (1.0 - progress) + 25.0 * scarcity;
        // Late in the stream, opening fresh bins is more acceptable.
        score -= 40.0 * progress * progress;
        // If mean residual is large, prefer reusing open bins.
        score += 0.3 * mean_residual;
    }

    // Mild penalty for very small post_residual that wastes nothing but fragments.
    if post_residual > 0 && post_residual < 5 {
        score -= 5.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (pack fuller bins first).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: post-residual, damped by progress (late stream => tighter packing preferred)
    let mut score = r * (1.0 - 0.35 * progress);

    // Non-linear coupling: quadratic dead-space penalty, stronger late in stream
    score += 12.0 * norm_r * norm_r * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth saturating term
    score -= 25.0 * (1.0 - norm_r).powi(3) * (1.0 + 0.5 * progress);

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing bins
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let diff = (r - next_item_size as f64).abs();
        score -= 15.0 * (-diff / 20.0).exp();
    }

    // Mean residual coupling: penalize bins far from mean (smooth)
    score += 0.15 * (r - mean_residual).abs();

    // New-bin candidate: penalize mildly unless post_residual would be large and stream early
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * (1.0 - progress) - 8.0 * norm_r;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: dead space eliminated entirely.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic classes of post_residual: small leftovers are reusable niches.
    let pr = post_residual;
    if pr > 0 && pr <= 5 {
        score += 3.0; // tiny slivers are nearly dead space
    } else if pr <= 15 {
        score -= 4.0; // sweet spot: fits the smallest items (10..)
    } else if pr <= 30 {
        score -= 2.0;
    } else if pr > 80 {
        score += 5.0; // huge residual means item barely dented the bin
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains perfectly into this bin -> strong reward,
            // scaled by how snugly it fits (small leftover-of-leftover).
            let chain_left = pr - next_item_size;
            score -= 8.0 - (chain_left as f64) * 0.15;
        } else {
            // Next item won't fit here: penalize unless residual is tiny
            // (tiny residuals are acceptable dead space).
            if pr > 10 {
                score += (next_item_size - pr) as f64 * 0.08;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a fresh bin should be discouraged
    // unless the item is large (a big item in a new bin leaves a useful
    // complement for future small items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 - (item_size as f64) * 0.12 + progress * 3.0;
        // If no existing bin fits at all, opening a new bin is mandatory anyway;
        // soften the penalty so it doesn't distort ranking among empty-bin calls.
        if fitting_bins_count == 0 {
            score -= 14.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead gap: penalize proportionally to how much is trapped.
        score += 25.0 + (post_residual as f64) * 0.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.4 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with far less residual than average
    // are "almost full" — finishing them is good.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff.min(30.0) * 0.4;
    } else {
        score += (-diff).min(30.0) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this empty-bin call sees tight existing capacity pressure).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; slightly above a perfect fit.
        score = 5.0 + (open_bins_count as f64) * 0.3;
        // If next item is large and current item leaves a useful gap, opening is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 3.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild quadratic penalty.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: item + next item fill bin
        } else if post_residual >= next_item_size {
            let slack = pr - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted space relative to next item
            score += 0.25 * (nxt - pr).min(nxt);
        }
    }

    // Compare post_residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        if rel < 0.0 {
            score -= 8.0 * (-rel).min(2.0); // below-average waste is good
        } else {
            score += 6.0 * rel.min(2.0); // above-average waste is bad
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 - 55.0 * frac - 10.0 * open_pressure - 15.0 * progress;
    }

    // Slight preference to fill nearly-full bins early in the stream.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Penalize large post-residuals that could still hold typical items.
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 6.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to mean (balanced packing),
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_options = if fitting_bins_count <= 1 { 0.0 } else { 0.0 };
        let badness = (mean_residual - item_size as f64).max(0.0);
        score = bin_capacity as f64 * (0.9 + 0.2 * progress)
            - badness * 0.3
            - poor_options;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a bin
        }
        if fitting_bins_count == 1 {
            score += 10.0; // existing last-chance bin preferred
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Base: quadratic penalty on wasted residual, amplified by stream progress.
    let waste_frac = pr / cap;
    score += 4.0 * waste_frac * waste_frac * cap * (0.5 + 0.5 * progress);

    // Tight-fit reward: smooth sigmoid-like bonus as item fills the bin.
    let fill = it / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill * (1.0 - fill * 0.5);

    // Penalize residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 10.0 * gap * gap * cap;
        // Reward if post_residual still accommodates next item.
        let fits_next = (pr / nx).min(1.0);
        score -= 3.0 * fits_next;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: discourage spreading; prefer consolidation into fuller bins.
    let open_norm = (open_bins_count as f64).ln().max(0.0);
    score += open_norm * (pr / cap) * 2.0;

    // Compare against mean residual: bins with residual well below mean are precious.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 2.0 * dev;

    // New-bin candidate handling: empty bin has high raw residual; make it
    // attractive only when no existing bin gives a decent fit.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let poor_fits = ((pr - cap * 0.5) / cap).max(0.0);
        score -= 6.0 * scarcity * (1.0 + poor_fits) * (0.3 + 0.7 * progress);
        // Mild early-stream penalty so we fill bins first before opening many.
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" residue
    // classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // reward if post_residual is divisible by common small item sizes (harmonic fit)
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += 6.0;
            }
        }
        score -= harmonic_bonus;

        // penalize "dead zone" residuals that are too small for any plausible item
        if pr < 10 {
            score += 40.0; // nearly unusable sliver
        } else if pr < 20 {
            score += 18.0;
        }

        // quantized threshold: residuals in [25,50) are awkward; [50,100) excellent
        let bucket = pr / 25;
        score -= match bucket {
            0 => 0.0,
            1 => 5.0,
            2 => 12.0,
            _ => 20.0,
        };
    } else {
        score -= 30.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (pr as f64 - next_item_size as f64) / cap;
        } else {
            score += 8.0; // next item won't fit here; this bin likely closes
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if all open bins would leave bad residue, opening is fine
        if fitting_bins_count > 0 {
            let worst_case = (bin_residual - item_size) as f64;
            if worst_case < 10.0 {
                score -= 45.0; // opening new bin beats creating dead space
            }
        }
    }

    // Tight fit reward
    score -= 10.0 * (item_size as f64 / bin_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item (<= 10) are pure waste -> heavy penalty.
    let dead_zone = 9.0;
    if (post_residual as f64) < dead_zone {
        score += 40.0 * (dead_zone - post_residual as f64);
    }

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Bonus when this bin's residual exactly matches the lookahead item (or
    // lookahead + slack), chaining placements efficiently.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // lookahead cannot use this bin's leftover: mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer dense fills;
    // few open bins -> allow opening new bins more freely.
    let pressure = (open_bins_count as f64).ln() / 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure; make it attractive only
        // if the fit in existing bins is poor (large post_residual there).
        score = bin_capacity as f64 * 0.55 + 20.0 * pressure + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host the next item too
        }
    } else {
        score += pressure * 4.0;
    }

    // Late in the stream, be more conservative: favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress * (mean_residual / bin_capacity as f64);
    } else {
        score += 25.0 * progress;
    }

    // Mild tie-break: prefer bins whose residual is close to the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: place here if next item exactly fills the remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the post-residual: strong reward scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }
    // Next item would NOT fit here: penalize leaving a gap the next item can't use,
    // especially when the gap is small (unusable dead space).
    if next_item_size > post_residual && next_item_size > 0 {
        let gap = post_residual as f64;
        let dead = if gap < next_item_size as f64 { gap } else { 0.0 };
        score += dead * 2.0;
    }

    // Tight fit reward relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.8;
    } else {
        score += (pr - mean_residual) * 0.4;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Mildly discourage spreading across many open bins early; encourage consolidation later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Penalize near-empty leftovers that are too small for typical items.
    if pr > 0 && pr < 10 {
        score += 50.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 + fitting_bins_count as f64 * 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin pairs well with a large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average upcoming item.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 3.0; // nearly perfect closure is fine
        } else {
            score += 2.0; // leaves a gap the next item can't use
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // with the penalty shrinking as the stream progresses.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: prefer leaving small residual (tight fit), quadratic coupling with progress.
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.5 * progress * pr / cap);

    // Normalized fit quality: how well the item fills the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Penalize residual that is too small to be useful for typical future items.
    let useless = (1.0 - (pr / 10.0).min(1.0)).max(0.0);
    score += 5.0 * useless;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Residual too small for next item: mild penalty proportional to gap.
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
        // But if many open bins and mean residual is large, opening new bin is fine.
        score -= (mean_residual / cap).min(1.0) * 4.0;
    }

    // Late-stream consolidation: prefer packing into existing bins more tightly.
    score += progress * (open_bins_count as f64) * 0.5 * (1.0 - fill);

    // Smooth interaction: residual variance pressure via mean_residual.
    score += 2.0 * ((pr - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: residuals in awkward modulo classes are less
    // likely to be filled by future items (sizes 1..100, common decile blocks).
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 0.35;

    // Integer-division thresholds: classify residual into usable bands.
    // Residual < 10 is dead space -> strong penalty (nothing fits).
    if post_residual < 10 && !(bin_residual == bin_capacity) {
        score -= 15.0; // but a nearly-perfect fill is actually great
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // narrow band, only tiny items fit
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if the next item can also land here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it creates huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        if post_residual > 40 {
            score += 18.0; // don't burn a whole bin for one item
        }
    }

    // New-bin candidate handling: penalize mildly, but allow opening a fresh
    // bin for large items or when all existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 14.0;
        score += (bin_capacity - item_size.min(bin_capacity)) as f64 * 0.35;
        if item_size >= 60 {
            score -= 25.0; // big items deserve fresh space
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative anyway
        }
        if mean_residual > (item_size as f64) + 15.0 {
            score -= 12.0; // open bins are roomy; a new bin is fine too
        }
    }

    // Reward high utilization fraction of the current placement.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Slight stream-progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Mean-residual coupling: bins far from the mean residual get a nudge
    // toward uniformity (keeps the pool of usable residuals coherent).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    } else {
        // Reward leaving a gap that could fit a typical next item exactly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // gap still usable by lookahead item
        }
        // Non-linear bonus for very tight fits (small but usable residual).
        let tightness = (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is loose.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Penalize choosing a new empty bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits tightly, new bin is attractive: reduce penalty
        // when mean residual is large (open bins are fragmented/underused).
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    }

    // Early stream: slight preference to consolidate (fewer bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: penalize small post_residual quadratically.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Aggressive 2-step lookahead: strongly reward post_residual matching next item.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).powi(3);
        // Perfect lookahead match bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual slightly below next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count > 1 {
            score += 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

