    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness).powf(6.0);

    // Penalize dead space that no future item could plausibly fill.
    let min_size = 1.0;
    if (post_residual as f64) < min_size {
        score -= 25.0; // exact fill
    } else if post_residual < item_size.min(100) / 2 {
        score += 8.0; // small unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 3.0 * (miss / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
