    // Prefer filling bins with large residuals when many bins are open (bin consolidation).
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score -= (bin_residual as f64 / bin_capacity as f64) * 12.0 * pressure.min(3.0);

    // Time horizon: early in the stream, be more conservative (penalize fragmentation);
    // late in the stream, accept imperfect fits to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * tightness;
    score -= 8.0 * progress * (1.0 - tightness);

    // Global residual context: if this bin's residual is far below the mean,
    // placing here evens out residuals (good); if far above, penalize slightly.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // New-bin candidate: modest baseline so it's chosen only when no open bin is decent.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * progress;
        // If the next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size < 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual
    let irn = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post residual); late, tolerate spread.
    let w = 0.5 + 0.5 * progress;
    score += w * (prn * prn) * cap * (1.0 - irn);

    // Smooth penalty for near-full bins wasted on small items
    score -= (1.0 - w) * (prn * (1.0 - prn)) * 20.0;

    // Last-chance bin bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * prn * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = if pr as f64 >= nxt { 1.0 } else { 0.0 };
        let smooth = fit * (1.0 - (nxt / cap)) * (1.0 - progress);
        score -= 15.0 * smooth;
        // penalize post residual that almost fits next item (dead space)
        let gap = (nxt - pr) / cap;
        if gap > 0.0 {
            score += 10.0 * gap * (1.0 - gap) * (1.0 - progress);
        }
    }

    // Prefer bins with residuals close to the mean (balance), smoothly
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for proliferating bins early
    score += 0.3 * open_bins_count as f64 * progress * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual: leftover in (0,10] is dead space.
    let dead = post_residual / 10; // 0 => dead space class
    if dead == 0 && post_residual > 0 {
        score += 15.0; // unusable sliver
    } else {
        // Reward leftovers that match common harmonic classes (multiples of 10/20/25/50)
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 2.0; }
    }

    // Perfect fit dominates.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item can fit in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 20.0 - rem2 as f64 / 4.0;
            if rem2 % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot follow here: penalize based on gap size
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // penalize opening a new bin generally
        score += 30.0 + 0.5 * open_bins_count as f64;
        // but reward it for very large items (harmonic class >= 3/4 of capacity)
        if load_frac >= 0.75 { score -= 45.0; }
        else if load_frac >= 0.5 { score -= 15.0; }
        // if few bins fit the item, opening fresh is more acceptable
        if fitting_bins_count <= 1 { score -= 20.0; }
        // early in stream, prefer consolidation less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer filling bins that are already well loaded (low residual relative to mean).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Mild modulo-class penalty on item size to diversify bin class assignments.
    score += (item_size % 10) as f64 * 0.1;

    // Slight preference for bins whose residual is in a "friendly" integer-division band.
    let band = bin_residual / 25;
    score += band as f64 * 1.5;

    // Fraction-based nudge on residual fraction.
    score += frac * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps (< 10, or < half next item)
    if post_residual < 10 {
        score += 1000.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 5.0;

    // Last-chance bin bonus: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins; favor filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when current bin leaves bad dead space
    if bin_residual == bin_capacity {
        if post_residual > 0 && post_residual < 10 {
            score -= 500.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect two-item fill: heavily reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            let slack = (post_residual as f64 - next).abs();
            score -= 20.0 / (1.0 + slack / 20.0);
        } else {
            // Next item will NOT fit here: penalize leaving a residue that is too small.
            let waste = next - post_residual as f64;
            score += 10.0 * (waste / 40.0).min(2.0);
        }
    } else {
        // Last item: minimize residual directly (already base score).
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (< smallest item size 10) when
    // it is unlikely to be filled by the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with mean residual: prefer bins whose post-residual is close to the
    // mean residual (keeps bin states uniform, easier future matching).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for tighter bins early vs late in the stream: as the stream
    // progresses, be more conservative and favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    // Mild penalty for opening a brand-new bin when open bins exist and fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: waste ratio penalization.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * fill * 40.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 15.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening new bins, more so when
    // open bins exist and mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64;
        score += 45.0
            + crowding * 2.0
            + mean_residual * 0.3
            + (1.0 - progress) * 20.0;
        // But if the item is huge and mean residual is small, new bin is less bad.
        score -= fill * 30.0;
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    // Slight preference for bins below mean residual (balance load lightly).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Reward tight fits: non-linear coupling of fit ratio with stream progress.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tightness = fit_ratio * fit_ratio * (1.0 + progress);
    score -= 30.0 * tightness;

    // Penalize large leftover dead space, scaled by mean residual pressure.
    let dead = pr / cap;
    score += 40.0 * dead * dead * (1.0 + (mean_residual / cap).tanh());

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let next_fit = next_item_size as f64 / pr.max(1.0);
        score -= 20.0 * next_fit * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for proliferating open bins early in the stream.
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate (empty bin): penalize so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - fit_ratio) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let cap = bin_capacity;
    // Class 0: post_residual in small dead zone -> penalize heavily.
    let dead = if pr == 0 { 0.0 } else if pr < 10 { 60.0 } else { 0.0 };
    score += dead;

    // Harmonic bucket: post_residual grouped by capacity/8 bands.
    let band = pr / (cap / 8).max(1);
    let band_bonus = match band {
        0 => -25.0, // nearly full bin: excellent
        1 => -12.0,
        2 => 0.0,
        3 => 6.0,
        4 => 10.0,
        _ => 14.0, // large residual left: wasteful
    };
    score += band_bonus;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            score -= 10.0;
        } else {
            score += 8.0;
        }
        // Harmonic coupling: next_item_size mod 10 alignment with pr
        if next_item_size > 0 && pr >= next_item_size && (pr % 10) == (next_item_size % 10) {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if item is large and few bins fit it, new bin is reasonable.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        if mean_residual < 5.0 {
            score -= 20.0;
        }
    }

    // Progress-based tuning: tighten packing later in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Penalize bins far below mean residual (fragmentation avoidance).
    score += ((mean_residual - post_residual as f64).abs()) * 0.15;

    // Integer-division threshold on item_size class.
    if item_size % 10 == 0 {
        score -= 3.0; // round items pack well with round residuals
    }
    if (pr % 10) == 0 && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (1..100 range, but typical items are >= 10) are
    // effectively wasted. Penalize small non-zero gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: hard penalty proportional to how "dead" it is.
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            // Marginal gap: moderate penalty.
            score += 12.0 * (20.0 - gap) / 10.0;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward leaving a gap that can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the next item would fill the bin completely.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin unattractive by default,
    // except when the current item is large relative to a fresh bin and
    // existing fits are poor (handled by the penalties above). Scale the
    // baseline slightly with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 5.0 * progress;
    }

    // Prefer bins whose residual is close to what we consume (tight fit).
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += (1.0 - tightness) * 6.0;

    // Mild preference toward bins with above-average residual when the item
    // is large, to avoid fragmenting small-capacity bins.
    if item_size > bin_capacity / 2 && (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted space, scaled by capacity
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste_frac * waste_frac;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // prefer chains that leave small slack
            score -= 200.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * gap / bin_capacity as f64;
        }
    }

    // Compare residual against mean residual across open bins:
    // favor bins whose post-residual deviates favorably (smaller) from mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 250.0;
        // more tolerable early in the stream / when few bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
        // acceptable if the item is large relative to capacity
        score += 0.5 * item_size as f64;
        // if many bins fit the item, opening a new one is less attractive
        score += 40.0 * fitting_bins_count as f64;
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size && post_residual < 2 * next_item_size {
            // Reward bins whose leftover can host the next item.
            score -= 1.5;
        }
    }

    // Perfect fit: extreme reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin is attractive only if mean residual is small (open bins nearly full)
        // or early in the stream with few bins.
        let new_bin_bonus = 4.0 * (1.0 - fragmentation) * (1.0 - progress)
            + 6.0 * (1.0 - fragmentation);
        score -= new_bin_bonus;
        // Mild cost to prevent runaway bin opening.
        score += 0.15 * open_bins_count as f64;
    } else {
        // Favor bins with residual close to item_size (minimize wasted capacity ratio).
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 4.0 * waste_ratio;
        // Slight preference for bins with below-average residual (fill fuller bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        } else {
            score += 1.0;
        }
    }

    // Time-horizon modulation: later in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as stream progresses.
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Smooth interaction with mean residual: prefer bins that reduce dispersion.
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.01;

    // Lookahead coupling: bonus if next item fits into the resulting post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // New empty bin candidate: penalize opening a bin unless residuals are tight
    // and few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + (mean_residual < item_size as f64) as i32 as f64;
        score += cap * (1.0 - 0.35 * pressure.min(1.0)) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: exponential bonus for small post_residual.
    let tight = 1.0 - post / cap;
    score -= 60.0 * tight * tight * tight;

    // Harmonic class of post_residual: penalize dead space in awkward residue classes.
    let pr = post_residual;
    if pr > 0 {
        // Class sizes that are hard to fill (small odd residues, prime-ish gaps)
        let class = pr % 12;
        let awkward = match class {
            1 | 5 | 7 | 11 => 12.0,
            2 | 3 | 9 => 6.0,
            4 | 8 => 3.0,
            _ => 0.0,
        };
        score += awkward * (1.0 - post / cap);
        // Very small unusable residue
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        }
    }

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead coupling: reward if next item fits post_residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let nm = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - nm / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use leftover: mild penalty scaled by leftover size.
        score += 8.0 * (post / cap);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Base penalty to prefer existing bins; reduced if item is huge or no bins fit.
        let mut pen = 45.0;
        if item_size as f64 / cap > 0.7 {
            pen -= 20.0;
        }
        if fitting_bins_count == 0 {
            pen -= 60.0;
        }
        if open_bins_count == 0 {
            pen -= 30.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        pen += 15.0 * progress;
        score += pen.max(0.0);
    }

    // Prefer bins below mean residual (keeps residuals balanced).
    score += 0.05 * (mean_residual - post).max(0.0);

    // Slight preference for already-open bins vs. nothing (implicit) and
    // mild penalty for spreading across too many bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, ideal
    } else if post_residual <= 10 {
        // small gap likely unusable: heavily penalize unless it exactly fits next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // gap is usable by lookahead item
        } else {
            score += 25.0;
        }
    } else {
        // Usable gap: mild penalty scaled by waste ratio
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
        // Reward if next item fits into the post residual
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // Reward tight fits (post_residual small relative to residual)
    if bin_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= tightness * 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good
    if fitting_bins_count > 1 {
        // competition: prefer bins where this item fits well
        score += 0.0;
    } else if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // last-chance bin: strong bonus to use it rather than open a new bin
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large or no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of a fresh bin
        score += 30.0;
        // large items pack better in fresh bins
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // if current bin would leave a tiny dead gap, opening new bin is fine
        if post_residual > 0 && post_residual <= 10 && next_item_size > post_residual {
            score -= 15.0;
        }
        // early in stream, new bins are cheaper (plenty of items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    } else {
        // pressure from number of open bins: consolidate when many are open
        score += (open_bins_count as f64) * 0.3;
        // if bin residual is far above mean residual, this bin is roomy: slight penalty
        if (bin_residual as f64) > mean_residual {
            score += ((bin_residual as f64) - mean_residual) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose post-residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // exact 2-step match: post_residual consumed fully by next item
        } else if post_residual >= next_item_size {
            // next item fits; reward small leftover after the hypothetical next placement
            let after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to how badly it fails
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / 50.0).min(2.0);
        }
    }

    // Tightness reward: small post_residual relative to mean residual is a good squeeze.
    let tightness = post_residual as f64 / (mean_residual + 1.0);
    score += 4.0 * (tightness - 1.0).clamp(-1.5, 1.5);

    // Penalize leaving large unusable slivers (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.6 * open_bins_count as f64;

    // Early in the stream, slightly prefer filling existing bins to keep bin count low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well (handled implicitly),
    // but make an empty bin mildly unattractive so we prefer squeezing into open bins.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize leaving residuals that no plausible future item (1..100) can use well:
    // residual in "dead zone" (e.g. < 10 but > 0) is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Reward residuals that are either 0 (perfect) or large enough to be reusable.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // heavily favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate handling: opening a new bin is penalized more when many
    // bins are already open and the stream is early (future consolidation likely).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (1.0 - progress);
        // But if existing fit is very loose (huge dead space), new bin becomes attractive.
        if fitting_bins_count <= 1 {
            score -= 14.0;
        }
    }

    // Global state: prefer filling bins with residual far from mean residual
    // (balance conservation vs. waste reduction).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for bins whose residual is closest to the item (best fit).
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.08 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_ratio = post_residual as f64 / cap;

    // Reward tight fits (small post_residual) with smooth quadratic coupling to progress
    score -= (1.0 - post_ratio) * (1.0 - post_ratio) * (30.0 + 40.0 * progress);

    // Penalize dead space that cannot fit typical future items: smooth interaction
    // between post_residual and the stream progress
    let dead = post_ratio * post_ratio;
    score += dead * 25.0 * (0.5 + progress);

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / cap;
        score -= 10.0 + 20.0 * chain * (1.0 - post_ratio);
    } else if next_item_size > 0 {
        // penalize leaving residual too small for the next item
        score += 8.0 * (1.0 - post_ratio) * (1.0 - post_ratio);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score += 20.0 + open_pressure * 2.0;
        // allow new bin when existing residuals are all poor
        let mean_gap = (mean_residual - item_size as f64).abs();
        score -= mean_gap * 0.3;
        // late in stream, opening a fresh bin is less costly
        score -= 15.0 * progress;
    }

    // Mild preference for balancing residuals across bins
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    // Smooth non-linear polynomial coupling of post_residual and progress
    let pr = post_ratio;
    score += pr * pr * pr * 12.0 * (1.0 - progress) - pr * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = (post_residual / (bin_capacity / 5).max(1)) as f64; // 0..=5 classes

    // Reward small post_residual, especially when it lands in a "useful" class
    // (post residual that a typical next item of size 10..30 could still use).
    score -= (cap - post) * 0.15; // prefer tight fills

    // Penalize dead space: post_residual too small for the smallest class (>0 but < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic coupling: if next item exactly divides into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_next = post_residual % next_item_size == 0;
        if fits_next {
            score -= 40.0;
        } else {
            score -= (post_residual.min(next_item_size * 3) as f64) * 0.3;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot use this bin's leftover; penalize proportionally
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Class-based bonus: mid classes (residual 20..50) are reusable; extremes less so
    let class_utility = match post_class as u32 {
        0 => 30.0,                 // perfect fit
        1 => 15.0,                 // residual <= 20, marginal
        2 => 20.0,                 // residual <= 40, very reusable
        3 => 12.0,
        4 => 6.0,
        _ => 0.0,
    };
    score -= class_utility;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // opening fresh is penalized when many bins are open and mean residual is high
        score = cap * 0.9
            - mean_residual * 0.5
            - (open_bins_count as f64) * 1.5
            + (fitting_bins_count as f64) * 8.0;
        // late in the stream, prefer consolidation into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Slight tie-breaker toward bins whose residual is close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (post_residual small relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized slightly when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    // Progress pressure: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // 2-step lookahead: reward if next item fits into post_residual exactly/perfectly
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        if gap == 0.0 {
            score -= 25.0; // perfect 2-item packing
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize dead space scaled by leftover size
        score += (post_residual as f64) * 0.15;
    }

    // Relative to mean residual: prefer bins that deviate favorably
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless all fits are bad
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Slight preference for bins with less residual among equals (fill older bins first)
    score += (bin_residual as f64) * 0.05;

    // Few open bins: encourage reuse to keep bin count low
    if open_bins_count > 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible item could fill
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // nearly perfect fill
    } else if post_residual < item_size.min(60) {
        // residual smaller than typical items -> likely waste
        score += 0.35 * (post_residual as f64);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.10 * over.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: discourage spreading, prefer consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }
    if (mean_residual - bin_residual as f64).abs() < 5.0 && bin_residual < bin_capacity {
        score -= 4.0; // aligning residuals enables future swaps
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big upcoming item: fresh bin more attractive
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in stream: be greedy about closing bins tightly
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (norm_pr * norm_pr) * (1.0 - progress) * 50.0
                 + (norm_pr * norm_pr * norm_pr) * progress * 80.0
                 + (norm_pr * (1.0 - norm_pr)) * progress * 20.0;
    score += coupling;
    // Penalize near-full residual waste more as stream advances
    score += (norm_pr - 0.5) * (norm_pr - 0.5) * 30.0 * (0.5 + progress);
    // Reward tight fits
    score -= (item_size as f64 / cap) * (1.0 - norm_pr) * 25.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }
    // Prefer spreading when many bins open and residual below mean
    let dev = mean_residual - pr;
    score += dev * 0.1 * progress;
    // Lookahead: penalize if next item cannot use post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            score += (ni - pr) * 0.3 * (0.5 + progress);
        } else {
            score -= (pr - ni) / cap * 10.0;
        }
    }
    // New-bin candidate: keep it competitive only for large items / late stream
    if bin_residual == bin_capacity {
        score = pr + 20.0 - 15.0 * progress - (item_size as f64 / cap) * 10.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect closure, ideal
    } else {
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 4.0; }
        if pr % 50 == 0 { harmony_bonus += 5.0; }
        score -= harmony_bonus;

        // Penalize dead-space "bad classes": tiny residuals that nothing
        // (min item 1, but realistically small items) can use.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }

        // Integer-division threshold: how many "average items" fit later.
        let slots = pr / 25;
        score -= slots as f64 * 2.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Lookahead coupling: reward if next item harmonizes with post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or leaves a harmonic residual
            let nr = pr - next_item_size;
            if nr == 0 {
                score -= 40.0;
            } else if nr % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 5.0;
            // unless the remainder is so small it's effectively dead anyway
            if pr < 10 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item)
    // space; make it unattractive unless the item barely fits any open bin
    // or open bins are nearly full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_capacity - item_size) as f64;
        score += 60.0 + waste * 0.5;
        // early in the stream, spreading items across bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // if mean residual is low (all bins nearly full), new bin is good
        score -= (bin_capacity as f64 - mean_residual) * 0.3;
        // many fitting bins means no need for a new one
        score += fitting_bins_count as f64 * 8.0;
    }

    // Mild preference to balance load across many open bins.
    if !is_new_bin {
        score += open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot plausibly hold a future item (very small residual).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 40.0;
    }

    // Reward residual that could still fit the lookahead item (k=2 lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for the next item: mild penalty for wasted potential.
        score += 15.0;
    }

    // Reward tight fits relative to the bin (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor consolidating into existing bins, especially the last fitting one.
    score += 0.8 * open_bins_count as f64;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all existing fits
    // would create dead space and the item is large.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual plus a fixed opening cost.
        score += 60.0;
        if post_residual < 20 {
            // Opening a bin that immediately becomes mostly dead is very bad.
            score += 150.0;
        }
    }

    // Slight adaptation over the stream: early on, be a bit more liberal (explore),
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * (1.0 - progress);

    // Mean residual coupling: if open bins are already slack, penalize adding more slack.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // strongly reward this bin (chained perfect fit).
    if next > 0.0 {
        if post == next {
            score -= 45.0;
        } else if next <= post {
            // Next item fits: mild reward proportional to how snugly it fits.
            score -= 12.0 * (next / post.max(1.0));
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small to be useful for the lookahead item.
            score += 8.0 * (1.0 - post / next.max(1.0));
        }
    }

    // Penalize residuals below the minimum plausible item size (dead space).
    let min_item = 1.0;
    if post < min_item {
        score += 20.0;
    }

    // Relative-to-mean coupling: bins with residual near the mean residual
    // are "typical"; strongly empty bins (new bin) handled below.
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate detection: full residual means brand-new empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer opening a new bin only when existing fits are poor:
        // if many bins fit, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 25.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin and a new bin exists: keep score moderate,
            // lookahead decides.
            score += 5.0;
        }
        // Slight bonus early in the stream to build a diverse bin pool.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Last-chance bonus: if this is the only fitting bin, prefer using it
        // over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Mild penalty for very large post residual when item is small
    // (poor space utilization this step).
    score += 0.05 * (post / cap) * (cap - item);

    // Small progression-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead synergy: reward if the next item fits into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 6.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space too small for likely future items: penalize.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins can fit the item,
    // unless the fit into existing bins is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // New bin becomes more attractive late in the stream or when open bins are fragmented.
        score += 12.0 * (1.0 - 0.5 * progress) - 4.0 * fragmentation;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Avoid hoarding too many open bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual deviates from the mean (consolidate).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = pr_norm * pr_norm;
    let cubic = quad * pr_norm;
    let g = 1.0 + 0.6 * progress - 0.8 * quad * progress + 0.3 * cubic;
    score *= g;

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 12.0 * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward leaving just enough room for the lookahead item
        let tightness = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 8.0 * tightness * tightness;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (good fills)
    score -= 3.0 * (mean_residual - bin_residual as f64) / cap;

    // Mild preference for compactness as bins accumulate
    score += 0.02 * open_bins_count as f64 * quad;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fits are excellent: reward small post_residual super-linearly.
    score -= (1.0 - post / cap).powi(6) * 12.0;

    // Harmonic classes: classify post_residual by capacity fraction.
    // Residuals in (0,10] are near-dead space -> mild penalty; large residuals fine.
    if post > 0.0 && post <= 10.0 {
        score += 6.0;
    }
    // Integer division thresholds: post_residual / 10 class
    let cls = post_residual / 10; // 0..10
    score -= (cls as f64) * 0.4;

    // Perfect fill
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nx_post = post - nx;
            score -= (1.0 - nx_post / cap).powi(5) * 8.0;
            if nx_post <= 10.0 { score += 4.0; }
        } else {
            // next item cannot use this bin's remainder: penalize wasted space
            score += post * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // base penalty to prefer reusing open bins
        score += 30.0;
        // but if existing bins fit poorly (high mean residual waste) and
        // few bins fit, opening fresh is reasonable
        let fit_pressure = (fitting_bins_count as f64).max(1.0);
        score -= (mean_residual - post).max(0.0) * 0.2 / fit_pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item now, next large too: fresh bin good
        }
    }

    // Late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (1.0 - post / cap);

    // Slight preference to keep number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (near-zero post residual) relative to item size.
    let tightness = (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= (1.0 - tightness) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize creating a gap that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins fit poorly.
        score += open_bins_count as f64 * 8.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 40.0;
    }

    // Mild preference to balance residuals toward the mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Early-stream exploration vs late-stream consolidation.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 400.0; // perfect chaining: bin becomes optimally reusable
        } else if post_residual > next_item_size {
            // leftover still fits next item: mild bonus scaled by tightness
            score -= 60.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space,
            // worse when the gap is small (nearly-useless sliver)
            let gap = nxt - pr;
            score += 40.0 * (1.0 - gap / nxt.max(1.0) as f64);
        }
        // Coupling with mean residual: if this bin's post residual deviates
        // favorably from the fleet mean, prefer it.
        score -= 0.5 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin early in the stream or when few bins open;
    // encourage consolidation when many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (open_bins_count as f64).sqrt();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild tie-breaking: prefer tighter current residual (better fill ratio).
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    score -= 0.6 * (item / cap) * 100.0;

    // Penalize small-but-not-zero post residual (dead space that nothing may reuse).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 - 2.5 * pr;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 60.0;
        } else if nxt <= pr {
            score -= 15.0 * (nxt / pr.max(1.0));
        } else {
            // next item can't use the leftover: penalize large leftovers slightly more
            score += 0.15 * pr;
        }
        // If next item fits the current residual better than this one, mild penalty (swap pressure)
        if (bin_residual as f64 - nxt).abs() < pr.abs() {
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // many options: prefer the tightest, keep base ordering
        score += 0.0;
    }

    // Global state: many open bins with high mean residual -> avoid spreading waste.
    score += 0.05 * mean_residual;

    // Time horizon: early in stream, opening bins is cheaper; late, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 10.0 - t * 5.0;

    // New-bin candidate logic: only attractive when no bin is a good fit or item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && (residual - item) <= 15.0;
        if good_fit_exists {
            score += 120.0; // strongly discourage new bin when a tight fit exists
        } else {
            // opening a bin for a large item is fine; for tiny items it wastes capacity
            score -= 20.0 * (item / cap);
            if fitting_bins_count == 0 {
                score -= 30.0;
            }
        }
        // late in the stream prefer closing out open bins
        score += t * 15.0;
    }

    // Mild penalty for very large post residual relative to smallest plausible item.
    if pr > 50.0 {
        score += 0.1 * (pr - 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * 0.5;
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 20.0 * (1.0 - norm_post) * (1.0 - progress) * norm_item;

    // Penalize leaving residuals that neither current nor next item can use
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 8.0 * norm_post * (0.5 + progress);
    }

    // Reward leaving space exactly usable by the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - (post_residual as f64 - norm_next * bin_capacity) / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins when mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * mean_residual / bin_capacity as f64 * 2.0;

    // New-bin candidate: prefer only when no good fit exists
    if bin_residual == bin_capacity {
        score += 10.0 - 12.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: 4 classes by capacity quarters.
    let q = post_residual / (bin_capacity / 4);
    let class_penalty = match q {
        0 => -60.0, // near-perfect fill
        1 => -20.0,
        2 => 15.0,
        _ => 40.0,  // large dead space
    };
    score += class_penalty;

    // Lookahead: reward if next item fits into post_residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            // penalize residuals that waste the lookahead
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
        // modulo coupling: next item in same harmonic class as post_residual
        if post_residual > 0 && (next_item_size % post_residual.max(1)) == 0 {
            score -= 10.0;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * open_bins_count as f64;

    // Integer-division threshold on post_residual: divisible-by-10 residuals are clean.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio penalty).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
        // Nonlinear bonus when fill is nearly exact but not zero residual.
        if post_residual > 12 && fill_ratio > 0.8 {
            score -= 15.0 * (fill_ratio - 0.8);
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 2.0;
        // If item fits poorly anywhere, opening a fresh bin becomes preferable.
        if post_residual <= 12 {
            score -= 70.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is ample.
    if open_bins_count > 2 {
        score += (open_bins_count as f64 - 2.0) * 1.5;
    }

    // Lookahead coupling: leave room for the next item if it fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size / 2 {
            // Dead space relative to the next item: penalize.
            score += 8.0;
        }
    }

    // Mild late-stream tightening: prefer consolidation as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight_fit;

    // 2-step lookahead: if the next item fits into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_leftover = post_residual - next_item_size;
        score -= 18.0;
        score -= 10.0 * (1.0 - (chain_leftover as f64) / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item won't chain: penalize dead space proportionally.
        score += 6.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Compare against mean residual: prefer bins with less residual than average.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves a
    // very usable residual (e.g., post_residual can host the next item or is tiny).
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
