    // Slight penalty for accumulating many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Penalize leaving residual that is small but unusable for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus: residual can host the lookahead item.
            let slack = post_residual - next_item_size;
            score -= 1.5 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead item.
            let dead = next_item_size - post_residual;
            score += 0.05 * dead as f64;
        }
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly encourage using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Penalize opening a new bin when good open bins exist, unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // New bin baseline: its residual equals capacity, so add a fixed handicap.
        score += 4.0;
        // If the item fits poorly anyway (large leftover would remain even here),
        // slightly reduce the handicap since no open bin does better.
        if fit_quality < 0.25 {
            score -= 2.0;
        }
        // More open bins => more fragmentation risk; discourage new bins mildly.
        score += 0.15 * open_bins_count as f64;
    } else {
        // Reward reusing bins with larger residuals (consolidate into emptier bins).
        score -= 0.02 * bin_residual as f64;
    }

    // Time-horizon coupling: early in the stream, be frugal with bins; later, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * tightness;

    // Global residual coupling: if mean residual across open bins is high,
    // prefer bins that absorb the most space (reduce fragmentation).
    if mean_residual > 0.0 {
        let absorb = item_size as f64 / bin_capacity as f64;
        score -= 1.0 * absorb * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic in normalized post-residual. Tight fits (x near 0) score low;
    // large leftover space scores super-linearly worse.
    let mut score = 10.0 * x * x + 2.0 * x;

    // Smooth cubic coupling with stream progress: late in the stream, dead space
    // becomes increasingly costly (waste compounds), so penalize large residuals more.
    score += 8.0 * x * x * x * (0.3 + 0.7 * progress);

    // Reward bins whose residual is close to the mean residual of open bins
    // (keeps the bin pool homogeneous, easier to pair future items).
    let mean_norm = mean_residual / cap;
    score -= 1.5 * (-((x - mean_norm) * (x - mean_norm)) * 4.0).exp();

    // Lookahead: if the next item fits into the post-residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how close it is.
        score += 2.0 * (next_item_size as f64 / cap) * x;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 3.0 * (1.0 - x);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Its post_residual is large (x = 1 - item/cap). The quadratic base already
    // penalizes it, but if the fit into an existing bin would leave a tiny,
    // unusable sliver (x very small but next item doesn't fit), opening a new
    // bin is better — give the new bin a smooth bonus proportional to progress.
    if bin_residual == bin_capacity {
        score -= 1.0 + 2.0 * progress;
    }

    // Small smooth tie-breaker against bin crowding: spreading across many open
    // bins is mildly discouraged when residuals are large.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 / mod-20 structure
    let post_mod10 = post_residual % 10;
    let post_mod20 = post_residual % 20;
    let post_div10 = post_residual / 10;

    // Penalize residuals that are awkward (not multiples of 10 / 20)
    if post_mod10 != 0 {
        score += 2.0 + (post_mod10 as f64) * 0.15;
    }
    if post_mod20 == 10 {
        score += 1.0;
    }

    // Reward residuals that can host common item sizes (harmonic classes)
    let next = next_item_size as f64;
    if next > 0.0 {
        if (post_residual as f64) >= next {
            score -= 4.0; // next item fits here
        }
        // Reward residual matching next item size exactly (perfect pairing)
        if post_residual as u32 == next_item_size {
            score -= 6.0;
        }
    }

    // Dead space penalty: small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Fraction-of-capacity coupling
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 10.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Prefer filling bins tightly when many bins are open
    score -= (bin_residual - post_residual) as f64 * 0.05;

    // Progression-aware tie-breaking
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive if no bin fits well
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Mean residual alignment bonus
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    // Treat any gap below a "dead zone" threshold as wasted capacity.
    let dead_threshold: u32 = 10u32.max(next_item_size.min(30));
    if post_residual < dead_threshold {
        // Dead space: penalize proportionally to how much capacity is locked away.
        score += 25.0 + (dead_threshold - post_residual) as f64 * 1.5;
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness ratio: reward bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead coupling: if the next item can fit into the post residual, reward this bin;
    // otherwise penalize leaving a gap that neither helps nor hurts.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for chaining: post residual matches next item closely.
            let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= (10.0 - chain_gap).max(0.0) * 0.8;
        } else {
            score += 4.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and prefer consolidating into existing ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open,
        // but relax when existing residuals are large and fragmented (mean_residual high).
        score += 20.0 + open_pressure * 2.5 - (mean_residual / bin_capacity as f64) * 10.0;
        // A new bin is attractive when the item is large and would leave a bad fit elsewhere.
        if item_size > 60 {
            score -= 8.0;
        }
    } else {
        // Existing bin: slight reward scaling with open bin count (consolidation).
        score -= open_pressure.min(10.0) * 0.3;
    }

    // Prefer bins with residual close to the item (best-fit behavior) via residual deviation.
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += dev * 0.05;

    // Mild stream progression: later in the stream, be slightly more conservative
    // about leaving large residuals.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += post_residual as f64 * progress * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
