        score += 3.0 * pressure;
        // Mild penalty early in the stream (keep bins open, they may absorb later items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * (1.0 - progress);
    }

    // Global residual state: if mean residual across open bins is large, reuse space.
    if bin_residual != bin_capacity {
