    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling: quadratic + cubic in normalized post_residual,
    // modulated by stream progress.
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * norm_post * norm_post * 2.0;
    score += 40.0 * poly;

    // Reward tight fits more strongly later in the stream.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let match_quality = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 15.0 * match_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use.
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current residual is
    // highly fragmented relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs() / cap;
        score += 35.0 - 20.0 * fragmentation * fragmentation * (1.0 + progress);
        score += 3.0 * open_bins_count as f64;
    } else {
        // Favor bins whose residual deviates from the mean in a useful way.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev * dev;
    }

    // Mild penalty for accumulating many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: residual classes mod capacity fractions
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4).max(1);
