    let post = post_residual;

    // Class 1: near-perfect fit (post_residual small) -> strong reward
    if post == 0 {
        score -= 60.0;
    } else if post <= eighth {
        score -= 25.0;
    } else if post < quarter {
        score -= 8.0;
    } else if post < 2 * quarter {
        // mid-range residual: moderately useful, mild penalty to prefer tighter fits
        score += 4.0;
    } else {
        // large leftover: dead space risk
        score += 10.0;
    }

    // Harmonic class via integer division thresholds on post_residual
    let harmonic = (post / eighth) as f64; // 0..8 class index
    score += harmonic * 1.5;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        if post >= next_item_size {
            // reward proportional to how snugly next item fits
            let slack = (post - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if slack <= eighth as f64 {
                score -= 6.0; // near-perfect two-item chain
            }
        } else {
            // next item cannot follow here: penalize creating a stranded bin
            score += 8.0 + 0.05 * (next_item_size as f64);
        }
    } else {
        // last item: maximize fill, minimal residual matters most
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well; make the empty-bin candidate costly by default.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.0 + 0.3 * progress) + 15.0 + 2.0 * open_pressure;
        // allow new bin when item is huge (little would remain anyway)
        if item_size * 10 >= bin_capacity * 8 {
            score -= 25.0;
        }
        // late in stream, prefer consolidating into open bins
        score += 10.0 * progress;
    }

    // Mild global balancing: prefer bins below mean residual (evening out)
    score += 0.1 * ((post as f64) - mean_residual);

    // Slight preference for bins with tighter current residual
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
