        score += 40.0; // unusable sliver
    } else if post_residual < 25 {
        score += 15.0; // risky small gap
    }

    // Reward tight fits (post_residual small relative to item size)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + fit_ratio);

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creates a gap the next item can't use
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with below-mean residual (consolidate space)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // existing residuals are poor fits; penalize mildly by default.
    if bin_residual == bin_capacity {
        score += 25.0;
        score -= (item_size as f64) * 0.2;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward proportional to slack.
            score -= 30.0;
        } else {
            // Dead space for the next item: penalize unusable remainder.
            let dead = post_residual as f64;
            score += dead * 0.8;
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already tighter than average (concentrate fill), avoid leaving many
    // near-full bins fragmented.
    if (bin_residual as f64) > mean_residual + 1.0 {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no open bin fits well (handled above); a fresh bin wastes capacity.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if the item is large relative to capacity, opening a fresh bin
        // is less bad (large items are hard to place later).
        if item_size > bin_capacity / 2 {
            score -= 120.0;
        }
        // Late in the stream, avoid spreading out.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Small bonus for filling large items into tight bins (fragmentation control).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: penalize if post residual cannot fit the next item but
    // the current bin could have; reward if next item fits the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0 + (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Dead space penalty relative to mean residual: leaving residual far
    // below the mean wastes capacity relative to fleet state.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Penalize scattering across many open bins when a fresh bin is a candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly.
        let fit_quality = if bin_residual >= item_size {
            1.0 - (item_size as f64 / bin_capacity as f64)
        } else {
            1.0
        };
        score += 10.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        let _ = fit_quality;
    } else {
        // Slight preference for bins with larger residuals (pack tight first).
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear tightness reward: quadratically favor bins filled to near capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 40.0 * tightness * tightness;

    // Cubic micro-coupling: mild extra reward for extremely tight fits.
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling with next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // Residual can host the next item: reward proportionally (capped).
            let ratio = (pr / nx).min(2.0);
            score -= 6.0 * ratio * (1.0 - 0.5 * progress);
        } else {
            // Dead space for the next item: penalize smoothly, stronger later in stream.
            let gap = nx - pr;
            score += gap * (0.6 + 1.2 * progress);
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize smoothly, scaled with how many bins are already open
    // and how large the leftover would be, so a new bin wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.5 * (open_bins_count as f64).sqrt() + 0.15 * pr;
    }

    // Mean-residual divergence: prefer bins whose residual deviates from the average
    // in the direction of being fuller (smooth absolute coupling).
    score += 0.25 * (mean_residual - pr).abs() - 0.1 * (mean_residual - pr);

    // Stream-progress drift: later in the stream, slightly prefer consolidating into
    // existing bins (non-linear saturating term).
    score += 4.0 * progress * (1.0 - progress) * 2.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: exact "nice" residuals are valuable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals in "dead zones" (small, hard-to-fill slivers)
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    } else if post_residual <= 10 {
        score += 25.0;
    }

    // Reward residuals that are harmonic fractions of capacity (1/2, 1/3, 1/4, 1/5)
    for (k, w) in [(2u32, 30.0), (3, 22.0), (4, 15.0), (5, 10.0)].iter() {
        let target = cap / *k as f64;
        let diff = (pr - target).abs();
        if diff < 1.0 {
            score -= *w;
        } else if diff < 5.0 {
            score -= *w * 0.4;
        }
    }

    // Modulo logic: residual that is a multiple of common item sizes (10s, 25s) is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nicely
            let nr = post_residual - next_item_size;
            if nr == 0 {
                score -= 120.0;
            } else if nr <= 10 {
                score -= 40.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: residual likely becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic pairing: next item matches residual class
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= (1.0 - frac) * (open_bins_count as f64).sqrt() * 4.0;

    // Late in the stream, tighten up: penalize waste more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.15 * progress;

    // Slight preference for bins below mean residual (balance toward filling emptier bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40 || fitting_bins_count == 0;
        if poor_fit {
            score -= 5.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10) can use are dead.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, strongly reward
    } else if post_residual < 20 {
        score += 18.0; // barely usable gap
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // wastes the gap relative to known next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Tightness reward: filling a bin proportionally to its residual.
    score -= 0.25 * (item_size as f64 / bin_residual.max(1) as f64) * 100.0;

    // New-bin candidate: only attractive when current bin fits are terrible.
    if bin_residual == bin_capacity {
        // neutral-ish: slightly above a perfect fit, below a dead-space fit
        score += 15.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (exact match after placement).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item also fits here: reward proportional to how well it fills.
            let two_step_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 300.0 * two_step_fill;
        } else {
            // Next item cannot use the post-residual: penalize dead space,
            // scaled by how much of the bin is wasted.
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            score += 120.0 * dead_frac;
        }
    }

    // Favor bins whose residual is already below average (tight bins first),
    // keeping large-residual bins flexible for future large items.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // placing here over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for tighter fits overall (post_residual quadratic penalty).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits terribly everywhere else. Penalize the empty-bin candidate
    // (bin_residual == bin_capacity) unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_frac = item_size as f64 / bin_capacity as f64;
        score += 200.0 * (1.0 - large_item_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact / near-exact fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Relative fit quality: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are fine (near-full)
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 5.0; // awkward zone: many items 21..80 won't fit
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here anyway; mild penalty for wasting large residual
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is usually wasteful unless
    // the item fits poorly everywhere (large item, huge residual elsewhere).
    if bin_residual == bin_capacity {
        let new_bin_cost = 40.0 + 30.0 * progress; // later in stream, prefer consolidation
        let spread_bonus = if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            15.0 // plenty of slack elsewhere; opening a bin is worse
        } else {
            -10.0 // open bins are tight; a fresh bin is reasonable
        };
        score += new_bin_cost + spread_bonus;
        if item_size > bin_capacity / 2 {
            score -= 20.0; // big items pair well in fresh bins
        }
    }

    // Global state: many open bins with high mean residual -> discourage spreading.
    if open_bins_count > 3 {
        score += 0.5 * (open_bins_count as f64 - 3.0).min(10.0);
        if bin_residual as f64 > mean_residual {
            score += 2.0; // prefer bins tighter than average
        } else {
            score -= 2.0;
        }
    }

    // Early stream: allow slight exploration of emptier bins.
    if progress < 0.2 {
        score -= 3.0 * (1.0 - progress / 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic in post_residual, slightly super-linear via coupling with progress.
    let mut score = post * (1.0 + 0.6 * progress) + 0.004 * post * post;

    // Reward tight fits smoothly (fit_ratio near 1.0).
    score -= 18.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual too small to host a typical future item.
    let dead = ((28.0 - post) / 28.0).max(0.0);
    score += 14.0 * dead * dead * (1.0 - 0.4 * progress);

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * ((-gap) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current fit is poor and stream is late.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - fit_ratio) * (1.0 - 0.5 * progress);
        score -= 8.0 * (open_bins_count as f64).ln();
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.3 * mean_residual * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo 10 buckets.
    // Residuals that are multiples of 10 are "harmonic" (many item sizes 10..80
    // can pair with them), so reward them; odd/prime-ish residues penalized.
    let r = post_residual;
    let cls = r % 10;
    let harmonic_bonus: f64 = match cls {
        0 => 18.0,
        5 => 6.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead-space cliff: post_residual too small for the smallest item is waste.
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Integer-division threshold: how many "average" items (size ~ (1+100)/2 = 50)
    // still fit — more future capacity is better.
    let fits_avg = r / 50;
    score -= 8.0 * fits_avg as f64;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this bin is perfect for a two-item chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
            // harmonic chain: both residuals stay on nice classes
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many options: prefer tight fits, penalize loose ones more
        score += 0.05 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Favor it only when the item is large relative to capacity or when open
    // bins are already crowded (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        // opening new bin attractive for big items or late in stream with crowded bins
        let new_bin_pull = 30.0 * (item_size as f64 / bin_capacity as f64)
            + 25.0 * (1.0 - crowded)
            + 10.0 * progress;
        score -= new_bin_pull;
    } else {
        // Existing bin: reward closeness of fit (small post residual) beyond raw value.
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 10.0 * tightness;

        // Prefer bins whose residual is below mean (consolidating small leftovers)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild penalty for proliferating bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor dense packing.
    let open_pressure = open_bins_count as f64 / 8.0;
    score += open_pressure * (post_residual as f64 / 20.0);

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 15.0 - 45.0 * poor_fit;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        score += 6.0;
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 10.0);

    // Mean residual coupling: if this bin is far below average residual, it's a good target.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where the NEXT item fits exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain fit (next item exactly fills the remainder) is gold.
            if slack == 0.0 {
                score -= 25.0;
            } else {
                score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize residual smaller than next item
            // (dead space relative to the lookahead), scaled by how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 5.0;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than average residual is good (tight packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize very small post_residuals that create unusable dead space
    // when the next item cannot use them anyway.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Early in the stream, be slightly more willing to spread items
    // across bins (keep residuals balanced); later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * open_bins_count as f64;

    // New-bin candidate: only attractive when it beats a very poor fit.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64) * (waste / bin_capacity as f64) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item can still fit here: mild reward, prefer leaving usable space.
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit: penalize leaving awkward dead space.
            score += 0.25 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs();
        }
    }

    // Penalize placing small items into large-residual bins (waste of good space).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.4 {
        score += 12.0 * (0.4 - fill_ratio);
    }

    // Prefer bins with residuals below the mean (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (bin_capacity as f64 - mean_residual).abs() < 1.0;
        if tight_exists {
            score += 60.0; // discourage new bin when tight fits exist
        } else {
            score += 10.0; // mild baseline cost of opening a bin
        }
        // Late in the stream, avoid opening new bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && item_size < 50 {
            score += 20.0 * progress;
        }
    }

    // Slight preference to spread across fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fits are rewarded more as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= (1.0 + progress) * tightness * tightness * cap * 0.5;

    // Penalize dead space: residuals too small for any item (min size 1) but awkward.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (1.0 + progress) * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += cap * (1.5 - poor_fit) * (0.5 + progress);
    }

    // Lookahead: reward if next item can use the post residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= (1.0 - (pr - ni) / cap) * 8.0;
        } else {
            score += (ni - pr) / cap * 6.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: prefer filling existing ones rather than spreading.
    score += (open_bins_count as f64).ln() * (pr / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item-size classes (10, 20, 25, 50)
    // are more likely to be filled exactly by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20u32, 25u32, 50u32] {
        if post_residual % m == 0 && post_residual > 0 {
            harmonic_bonus += (m as f64) * 0.35;
        }
    }
    score -= harmonic_bonus;

    // Integer-division threshold: dead space below 10 can never be reused
    // (min item size is 10). Penalize small unusable leftovers heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Fractional coupling: how much of the post residual the next item would consume.
        let frac = next_item_size as f64 / pr.max(1.0);
        score -= frac * 25.0;
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover; penalize proportionally to waste.
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // New-bin candidate: only prefer it when the item is large relative to
    // capacity or the mean residual across open bins is tight.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / cap;
        let tight = mean_residual < item_size as f64 * 1.5;
        if pressure > 0.7 || tight {
            score -= 30.0;
        } else {
            score += 35.0;
        }
    }

    // Modulo class of item itself: items in "awkward" classes (e.g. 33, 37, 41...)
    // pair poorly with typical residuals; slight extra caution on tight bins.
    if item_size % 10 != 0 && bin_residual - item_size < item_size {
        score += 6.0;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the minimum item (<=10)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: an empty bin should only win when the
    // fit into existing bins is poor (large post_residual) or no bin fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bin slightly so tight existing fits win.
        score += 6.0;
        // But if the item would leave a big unusable gap elsewhere,
        // a fresh bin with full flexibility is attractive.
        if post_residual > 40 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 4.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 8.0;
    }

    // Prefer bins tighter than the mean residual (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item is a double win.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement: mild bonus scaled by slack quality
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item would NOT fit here: penalize dead space left behind
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large post-residual relative to mean residual (wasteful slack).
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight bias toward filling already-open bins vs opening new ones.
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    // Late in stream, tighten packing to reduce residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize dead space relative to the next item's needs.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) < next {
            score += (next - post_residual as f64) * 0.8; // wasted space for lookahead item
        } else {
            score -= 2.5; // bin remains useful for the next item
        }
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: only absolute tightness matters
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is costly; discourage unless
    // existing residuals are all poor fits (large mean_residual mismatch).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins more when many open bins with slack exist.
        score += 15.0 + 10.0 * pressure + 5.0 * progress;
        // But if current item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 18.0;
        }
        // Late in stream, prefer closing out open bins instead of new ones.
        score += 8.0 * progress;
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post-residual (tight fit), scaled by capacity
    let mut score = pr / cap;

    // Smooth non-linear penalty on large dead space: quadratic coupling with progress
    let dead = pr / cap;
    score += 1.8 * dead * dead * (1.0 + 2.0 * progress);

    // Cubic interaction: late in stream, waste is amplified super-linearly
    score += 2.5 * dead * dead * dead * progress;

    // Favor bins whose residual matches the item well (relative fit term)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 0.6 * fit_ratio * (1.0 - progress);

    // New-bin candidate: penalize mildly, but less when open bins are congested
    if is_new_bin {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 0.35 - 0.15 * (1.0 - dead) * congestion.min(3.0) / 3.0;
    } else {
        // Last-chance bonus: strongly prefer the only bin that fits
        if fitting_bins_count == 1 {
            score -= 1.2;
        }
        // Lookahead: if next item fits exactly in post_residual, reward heavily
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 1.5;
        } else if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 0.4 * (next_item_size as f64 / cap);
        }
        // Penalize bins that differ from the mean residual (balance preservation)
        score += 0.25 * ((bin_residual as f64 - mean_residual) / cap).abs();
    }

    // Mild global pressure to use existing bins as stream progresses
    score += 0.1 * progress * (open_bins_count as f64).ln() / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "usable" residue classes are rewarded, dead-space classes penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> clean slot for future items.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> mildly usable.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class C: tiny dead space (unusable for items >= 10) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division threshold on post_residual: quarter-capacity buckets.
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    if post <= quarter && post_residual > 0 {
        // Nearly-full bin: good, we compacted it. Reward.
        score -= 6.0;
    } else if post > half {
        // Bin still mostly empty after placement: wasteful use of a bin.
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement creates a perfect chain -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot use the leftover: leftover likely dead.
            score += 5.0;
        }
        // Harmonic pairing: post_residual + next_item_size divides capacity cleanly.
        if (post_residual + next_item_size) % 10 == 0 && post_residual >= next_item_size {
            score -= 7.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // is bad elsewhere. Base penalty for opening a new bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += (mean_residual / cap) * 25.0;
        // Early in the stream, new bins are cheaper (few open bins to fragment).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // Large items justify fresh bins more (hard to pack later).
        if item_size > (bin_capacity * 3 / 5) {
            score -= 12.0;
        }
    }

    // Prefer tighter fits generally: reward small post_residual relative to item.
    score -= (item_size as f64 / cap) * 5.0;

    // Fragmentation guard: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && post > mean_residual {
        score += 4.0;
    } else if open_bins_count > 3 && post < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item are wasted.
    // Treat gaps below a "min useful gap" as nearly full dead weight.
    let min_useful_gap = 10.0f64;
    if (post_residual as f64) < min_useful_gap {
        // Tight fit: excellent, reward heavily (small gap = item packed snugly).
        score -= 25.0;
    } else if (post_residual as f64) < 2.0 * min_useful_gap {
        // Medium gap: mildly penalize relative to raw residual to prefer snugger fits.
        score += 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < min_useful_gap as u32 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This placement blocks the known next item; penalize proportionally.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // the new-bin candidate (bin_residual == bin_capacity) gets an opening surcharge
    // that grows with the number of already open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight reward for filling existing bins when many are open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Stream position: early in the stream, be more willing to open bins (diversity),
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (avoid stranding outliers),
    // unless it's a new bin.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post_residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mildly reward, scaled by
            // how much slack would remain after the follow-up placement.
            let follow_slack = post_residual as f64 - next_item_size as f64;
            score -= 25.0 * (1.0 - follow_slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space
            // proportional to how big and unusable it is.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * dead * dead;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // good targets (they have room); bins below mean are scarce-space bins.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 10.0 * rel;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit,
    // especially late in the stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 15.0 * progress;
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize post_residual that is too small to hold any future item (dead space).
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 7.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty to keep competition among bins tight.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state coupling: prefer filling bins when many bins are already open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins with residual above mean (balance residuals) early, exploit low-residual bins late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    if progress < 0.5 {
        score += 5.0 * dev; // early: spread load toward larger-residual bins
    } else {
        score -= 5.0 * dev; // late: concentrate into tighter bins
    }

    // New-bin candidate: penalize opening a new bin unless item is large or stream is early.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 35.0;
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity) {
            // next item also large; opening fresh bin can be fine
            new_bin_penalty -= 10.0 * item_frac;
        }
        if progress < 0.15 {
            new_bin_penalty -= 12.0; // early stream: keep options open
        }
        if item_frac > 0.7 {
            new_bin_penalty -= 20.0; // big item barely fits anywhere; new bin ok
        }
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: post_residual shaped by progress polynomial
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let progress_poly = 1.0 + 0.8 * progress * progress - 0.3 * progress;
    score += 12.0 * pr_norm * pr_norm * progress_poly;

    // Reward tight fits, more strongly late in the stream
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space below smallest plausible item, smoothly
    let dead = pr / 40.0;
    score += 6.0 * (dead * dead) / (1.0 + dead);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward bins whose post-residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = next_item_size as f64 / pr;
        score -= 5.0 * fit_quality * (1.0 - fit_quality.abs());
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.15 * open_bins_count as f64 * pr_norm;
    score -= 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover can still host
    // common item sizes are valuable; dead-space classes are penalized.
    let post = post_residual;
    if post > 0 {
        // residual divisible by common sizes (harmonic classes)
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post % d == 0 {
                harmonic_bonus += 15.0;
            }
        }
        score -= harmonic_bonus;

        // dead space: too small for the smallest plausible item
        if post < 10 {
            score += 60.0;
        }
        // awkward mid-band residuals are penalized
        if post > 5 && post < 15 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 400.0;
        } else if post > next_item_size {
            let slack = post - next_item_size;
            if slack < 10 {
                score -= 120.0; // next item nearly fills this bin
            }
            score -= (slack as f64).sqrt() * 5.0;
        } else {
            score += (next_item_size - post) as f64 * 1.5; // next item won't fit here
        }
    }

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave very awkward residuals and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = mean_residual < item_size as f64 * 0.6;
        if awkward && progress < 0.7 {
            score -= 80.0;
        } else {
            score += 200.0; // default: prefer filling existing bins
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= mean_residual * 0.3;
    score += open_bins_count as f64 * 0.5;

    // small tie-break noise-free deterministic jitter on step parity (harmonic)
    if step_index % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // A gap is "dead" if it cannot fit the next item (or any plausible item).
        let unusable_for_next = next_item_size > 0 && (next_item_size as f64) > gap;
        let tiny_gap = gap < 10.0;
        if unusable_for_next {
            score += 45.0 + 0.5 * (bin_capacity as f64 - gap);
        }
        if tiny_gap {
            score += 30.0;
        }
        // Smooth curvature: mid-size gaps are moderately bad, exact fits great.
        score += 0.15 * gap * (1.0 - gap / bin_capacity as f64);
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize the fresh-bin candidate implicitly via residual,
    // but also add mild pressure proportional to open bins for high residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * (0.5 + progress);

    // Prefer bins whose residual is below mean (tighter bins get priority).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // New-bin candidate: only attractive when nothing fits well or item is huge.
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        let desperation = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        let big_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 25.0 + big_item_bonus - desperation;
        // Late in the stream, opening fresh bins is safer for lookahead pairing.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Lookahead synergy: leaving room exactly for the next item is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 5 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportionally to how well it fills leftover
            let fill = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 25.0 * fill;
        } else {
            // next item cannot fit here: penalize large dead space
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste;
        }
    } else {
        // last item: prefer minimal post_residual
        score += 0.0;
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (consolidating into emptier bins keeps other bins available)
    let mean_res = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.3 * (bin_residual as f64 - mean_res);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate penalty: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        // Penalize new bins more as stream progresses, unless item is huge
        let size_pressure = (item_size as f64) / (bin_capacity as f64);
        score += 35.0 * (1.0 - size_pressure) * (0.5 + progress);
        // If next item is large and won't fit elsewhere, new bin may be needed
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin now but not after placing current item
            score += 10.0;
        }
        // exact chain fit bonus
        if next_item_size == post_residual {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins well
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global residual pressure: if mean residual is large, prefer bins below mean
    // (i.e., tighter-than-average bins) to consolidate waste
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in stream, be more willing to open fresh bins for
    // large items (keeps big residual bins flexible); late, consolidate hard
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if item is large or fit elsewhere is bad
        let large_item_bonus = if item_size > bin_capacity / 2 { 20.0 } else { 0.0 };
        score += 35.0 - large_item_bonus - 15.0 * progress
            - if fitting_bins_count <= 1 { 40.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // roomy bin good for upcoming large item
        }
    } else {
        // Late stream: reward near-perfect fills more aggressively
        score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Mild preference for bins whose residual is a "nice" complement
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear reward for tight fits (small post_residual), stronger later in stream
    score -= 30.0 * (1.0 - norm_pr).powf(2.0) * (0.5 + progress);
    // Penalize dead space: residual too small to be useful for typical items
    if pr > 0.0 {
        let dead = (1.0 - (pr / 80.0)).max(0.0);
        score += 15.0 * dead * dead;
    }
    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let exact = 1.0 - ((pr - nx) / cap);
            score -= 25.0 * exact * exact;
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }
    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // New-bin candidate: penalize mildly unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt();
        if pr == cap { score += 10.0; }
    }
    // Prefer bins with below-mean residual (consolidate waste)
    score += 0.3 * (mean_residual - bin_residual as f64);
    // Smooth progress coupling on residual
    score += 10.0 * norm_pr * norm_pr * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: 10-wide residue classes.
    let class = post_residual / 10;
    let phase = post_residual % 10;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small dead space (< 10) is nearly worthless: penalize relative waste.
        if class == 0 {
            score += 12.0 - phase as f64; // closer to 0 residual => slightly less bad
        }
        // Mid classes (10..30) are prime slots for the typical item range.
        if class >= 1 && class <= 2 {
            score -= 8.0 - (phase as f64) * 0.1;
        }
        // Large residual classes: mildly discourage hoarding space in one bin.
        if class >= 5 {
            score += (class as f64) * 1.5;
        }
    }

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Residual remains usable -> reward, scaled by how much room is left after next item.
            let next_post = post_residual - next_item_size;
            score -= 10.0 + (next_post as f64) * 0.05;
        } else {
            // Residual is dead for the lookahead item -> penalty grows with overshoot.
            let gap = next_item_size - post_residual;
            score += 4.0 + (gap as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative: new bin is fine
        } else {
            // Only open a new bin if existing residuals are badly fragmented.
            let spread = mean_residual - post_residual as f64;
            score += 15.0 + spread.max(0.0) * 0.5;
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (mean_residual * 0.1);

    // Tie-break noise-free deterministic coupling on open-bin pressure.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (min item size 1, but practically small gaps) are wasted.
    // Penalize "unusable" gaps harshly with a non-linear ramp.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Dead space: gap too small for typical items -> strong penalty.
            score += (11 - post_residual as i32) as f64 * 12.0;
        } else if post_residual < 25 {
            // Marginal gap: moderately risky.
            score += 8.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 30.0;
    }

    // Reward gaps that can still accommodate the lookahead item (k=2 coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // This bin won't help the next item: slight penalty.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin by rewarding this placement.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Competition exists: prefer tighter fits among rivals.
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // more residual; when few are open, be lenient.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += 0.10 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Penalize placements far below mean residual (creates fragmented bins).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if all
    // open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, becomes attractive when open bins
        // are crowded (low mean residual).
        score -= 5.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // No alternative: new bin is fine.
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (post_residual small relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly or nearly.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff >= 0.0 {
            // Next item fits exactly -> big bonus; small slack -> moderate bonus.
            let exactness = 1.0 - diff / bin_capacity as f64;
            score -= 18.0 * exactness * exactness;
        } else {
            // Post-residual too small for next item: penalize wasted dead space,
            // scaled by how badly it misses.
            score += 0.35 * (-diff);
        }
    }

    // Penalize residuals far below the mean residual (fragmented bin),
    // reward bins with large residual that stay useful.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score += 0.25 * (mean_residual - resid);
    } else {
        score -= 0.10 * (resid - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0);

    // Slight preference for keeping large residuals for large future items.
    if next_item_size > 60 && resid < next_item_size as f64 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).powi(2) * 0.02;

    // Penalize small dead space that nothing can ever use (items >= 1, but
    // typical items are chunky): residual below ~10 is near-useless.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Opening a new bin: penalize mildly when many bins are open and fit exists,
    // but allow it when fit is poor relative to mean residual.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > mean_residual * 0.9;
        score += 15.0 - 6.0 * progress;
        if fitting_bins_count == 0 || poor_fit {
            score -= 20.0;
        }
        if open_bins_count > 8 {
            score += 5.0; // discourage bin proliferation late in stream
        }
    } else {
        // Favor bins whose residual is close to item size (best-fit flavor).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.15;
        // Favor bins below mean residual (concentrate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post * post / cap;

    // favor tight fits, more strongly as stream progresses
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // penalize dead space relative to mean residual
    score += 0.05 * (post - mean_residual).abs();

    // last chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // lookahead coupling: reward leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if post >= nx { 1.0 } else { 0.0 };
        score -= 4.0 * usable * (1.0 - (post - nx) / cap).abs();
        score += 0.02 * (post - nx).abs();
    }

    // slight penalty for opening new bins when many fit
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (fitting_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10, or tiny leftovers) are more valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        let class_bonus: f64 = match pr % 10 {
            0 => 12.0,                    // decile-aligned leftover, reusable
            1..=3 => 6.0,                 // near-tight, likely dead space but small
            4..=7 => 0.0,                 // neutral band
            _ => -6.0,                    // awkward 8-9 leftover
        };
        score -= class_bonus;

        // Integer-division thresholds: does a typical future item (10..80)
        // fit in post_residual? Reward bins that can still host common sizes.
        let fits_small = pr >= 10;
        let fits_mid = pr >= 40;
        let fits_big = pr >= 70;
        if fits_small { score -= 8.0; }
        if fits_mid { score -= 8.0; }
        if fits_big { score -= 6.0; }

        // Harmonic coupling with the lookahead item: exact modulo match of
        // next_item_size into post_residual is highly desirable.
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 10.0;
                if pr % next_item_size.max(1) == 0 {
                    score -= 8.0; // divides evenly: future perfect fit likely
                }
            } else {
                // next item cannot go here; slight penalty if this bin is the
                // only fitting one (last-chance logic)
                if fitting_bins_count == 1 {
                    score += 4.0;
                }
            }
        }
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the empty bin proportionally to how many
    // open bins exist and how much residual mass is stranded there.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 {
            score += (next_item_size as f64) * 0.1;
        }
    }

    // Progress-aware tightness pressure: as the stream advances, prefer
    // tighter packing (smaller post_residual) more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Spread pressure: if mean residual is high, many bins are slack; reward
    // filling the loosest ones to consolidate.
    score -= 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual becomes small relative to mean residual (poor fit)
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor leaving a gap that can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Prefer using nearly-full bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 - progress);

    // Mild penalty for opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual < bin_capacity {
        // new-bin candidate score: base on wasted capacity
        score += 5.0 + (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (item + next item fills bin nicely)
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual == next_item_size -> big reward
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: reward tightness of the pair
            score -= 30.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportional to gap
            score += 8.0 + 0.5 * lookahead_gap;
        }
    } else {
        // Last item: reward minimal residual directly
        score -= 20.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score += 0.6 * (post_residual as f64 - mean_residual).max(-40.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * progress;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0; // an open bin already supports the 2-step plan
        }
    }

    // Small bonus for many open bins: consolidation pressure
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: best-fit core — prefer minimal post_residual, with slight nonlinearity
    // to strongly punish leaving awkward mid-range residuals.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64).powf(1.7) * bin_capacity as f64;

    // Perfect-fit reward: exact fill is always excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: reward proportionally to how snugly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize placements that strand the lookahead item.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity or when
    // many open bins already exist (diversification), otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        // Large items waste little in a fresh bin; small items should go into open bins.
        score += 25.0 * (1.0 - size_ratio);
        // Late in the stream or with many open bins, opening fresh bins is fine.
        score -= 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins slightly, more so when mean residual is high
        // (bins are fragmented; consolidate into them).
        score -= 2.0 + 0.05 * mean_residual;
    }

    // Penalize placements into nearly-full bins that leave tiny unusable slivers
    // (residual 1..=5) unless it's a perfect fit.
    if post_residual > 0 && post_residual <= 5 {
        score += 6.0;
    }

    // Mild time-horizon term: early on, prefer keeping residuals flexible
    // (closer to mean_residual); later, prioritize tight packing.
    score += (1.0 - progress) * 0.03 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with mild concavity.
    let mut score = pr * (1.0 + 0.5 * norm_pr);

    // Non-linear coupling: post_residual interacts with stream progress.
    // Late in the stream, waste matters more (fewer future items to fill gaps).
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward filling a bin almost completely, especially late.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill * (0.5 + progress);

    // Dead-space penalty: post_residual too small to be useful later.
    let dead = (norm_pr - 0.1).max(0.0) * (norm_pr - 0.5).min(0.0).abs().min(norm_pr);
    score += 15.0 * (if pr < 10.0 { 0.0 } else if pr < 20.0 { (20.0 - pr) / 10.0 } else { 1.0 }) * norm_pr * (1.0 - progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 8.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin when the item fits well
    // elsewhere; allow it only for very poor fits.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - fill) * (0.5 + progress);
        score += 5.0 * (open_bins_count as f64).sqrt();
    } else {
        // Slight preference for bins below mean residual (spread load evenly).
        score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fits are heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 10 {
        score -= 12.0; // near-perfect residual, still very usable for small items
    }

    // Modulo arithmetic on residual: residuals that are multiples of common
    // small-item sizes (e.g. divisible by 10 or 20) remain "harmonic".
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 1.5; }
        // Awkward residuals (odd, non-divisible) get penalized.
        if pr % 10 != 0 && pr < 30 { score += 2.0; }
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 5 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == pr {
            score -= 25.0;
        } else if nxt <= pr {
            // next item fits: reward proportional to how well it fills
            score -= 8.0 * (nxt as f64 / pr.max(1.0) as f64);
        } else if pr > 0 && nxt > pr && nxt - pr <= 10 {
            // next item just barely misses: mild penalty
            score += 3.0;
        }
        // If post_residual is a harmonic class matching next item's complement
        if pr > 0 && (pr + nxt) % 50 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer opening a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with how many bins are open.
        score = cap - item_size as f64; // same post_residual as any empty placement
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is cheaper (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // If many bins are open with slack, discourage new bins.
        score += 0.05 * open_bins_count as f64;
        // If next item is huge and would need a fresh bin anyway, encourage.
        if next_item_size >= 80 {
            score -= 6.0;
        }
    }

    // Tightness coupling: prefer bins where the item fills a large fraction
    // of the residual (dense packing).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_frac;

    // Penalize placing small items into large-residual bins when other
    // harmonic classes might use them better.
    if item_size < 30 && bin_residual > 70 && bin_residual < bin_capacity {
        score += 4.0;
    }

    // Mean residual anchoring: bins far below mean residual are already tight;
    // slight preference to keep them that way.
    if post < mean_residual {
        score += 0.5;
    } else {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (nonlinearly).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead); // tiny gap => nearly wasted space
        } else if dead < 25.0 {
            score += 8.0 * (25.0 - dead);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin content.
    let fill_ratio = item_size as f64 / cap;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: leftover riskier.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // current bin is a reasonable fit.
    score += 2.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to concentrate waste.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.4;
    } else {
        score += (res - mean_residual).min(50.0) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // early in the stream with plenty of room to grow.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_big = item_size as f64 / cap;
        // Penalize opening new bins generally, less so for big items.
        score += 55.0 - 35.0 * item_big + 20.0 * progress;
        if fitting_bins_count > 1 {
            score += 25.0; // other options exist; new bin is wasteful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        // Two-step lookahead: reward when next item exactly fills the new residual.
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits too, but leave flexibility: mild reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 - gap.min(300.0);
        } else {
            // Next item cannot fit in this residual: penalize dead space, worse if tiny.
            let dead = (next_item_size - post_residual) as f64;
            score += 150.0 + dead;
        }
    }

    // Penalize residuals that are too small to ever be useful (items >= 1... but
    // realistically dead space below a small threshold wastes capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Prefer bins whose residual is below mean (tighter packing) when this bin fits.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 400.0;
        // Slightly cheaper to open new bins early in the stream (more future items
        // to fill them with).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 150.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate into fewer bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

