    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual is reusable by the next item: reward proportionally.
            let reuse = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * reuse;
        } else {
            // Dead space: penalize more if the gap is just below next item size.
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * gap;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (penalize the new-bin option implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new empty bin, more so when open bins fit reasonably well
    // and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        let waste_new = (bin_capacity - item_size) as f64;
        score += 15.0;
        score += 0.05 * waste_new;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheaper (build a pool for future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Few open bins: opening is less costly.
        score -= 3.0 * open_bins_count as f64;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 8.0;
        }
    } else {
        // Slight preference for bins with less residual already (consolidate waste).
        score += 0.02 * (bin_residual as f64 - mean_residual);
    }

    // Mild global pressure: as stream progresses, discourage fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Reward using bins whose residual closely matches the item (minimize leftover).
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.03 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1))
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;

    // Non-linear waste term: squared normalized post_residual, amplified as stream progresses
    let pr_norm = post_residual as f64 / cap;
    score += (pr_norm * pr_norm) * cap * (0.5 + progress);

    // Tight-fit reward: smooth bell around zero post_residual
    let tightness = (1.0 - pr_norm).max(0.0);
    score -= tightness * tightness * (item_size as f64) * (0.3 + 0.7 * progress);

    // Penalize post_residual that matches no plausible future need:
    // dead space is post_residual smaller than the smallest conceivable item (1)
    // but large post_residual is fine only if it can host next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // wasted relative to lookahead: gap to next item, quadratic coupling
            let gap = nxt - post_residual as f64;
            score += gap * gap * (0.05 + 0.15 * progress);
        } else {
            // reward bins that can host the lookahead item, smoother for near-exact fits
            let slack = (post_residual as f64) - nxt;
            score -= (1.0 - slack / cap).max(0.0) * nxt * 0.2;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 50.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // High mean residual => open bins still useful => new bin is bad
        score += 60.0 + 80.0 * fragmentation * (0.5 + progress);
        // Late in the stream, prefer filling existing bins even harder
        score += 40.0 * progress * progress;
    } else {
        // Mild reward for keeping bin count low
        score -= 5.0 / (1.0 + open_bins_count as f64);
    }

    // Smooth interaction: prefer near-full bins as stream progresses (polynomial coupling)
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * fill * fill * 10.0 * (0.2 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fractions of C/10)
    let res_class = (post_residual % 10) as f64;
    score += 0.35 * res_class;

    // Integer-division thresholds on post_residual: dead-space classes
    let big_space = post_residual / 25; // 0..=4 quarters-ish
    score += 4.0 * big_space as f64;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: penalize leaving space that next item cannot use
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // leftover is dead for the next item; penalize proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // leftover can host next item: reward harmonic match
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 25.0;
            } else if gap <= 10 {
                score -= 8.0;
            } else {
                score += 0.2 * gap as f64;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // but allow it when open bins are very fragmented (high mean residual)
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 18.0 + 25.0 * (1.0 - fragmentation);
    } else {
        // Prefer bins with residual below mean (fill the emptier-tail bins)
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Late-stream consolidation: fewer bins favored as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1) but awkwardly small relative to typical items are unusable gaps.
    // Penalize residuals in (0, 10) heavily — they can never be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Penalize small-but-usable residuals that are unlikely to match future
    // items: the tighter the fit beyond the item, the worse the leftover.
    if post_residual > 0 && post_residual < 20 {
        score += 80.0;
    }

    // Reward bins whose residual is close to the item (tight fit overall).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }
    // If next item cannot fit in post_residual, mild penalty (dead space risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones
    // rather than opening new bins (consolidation).
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate handling: empty bin gets a moderate penalty so we
    // only open a new bin when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 60.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits at all, opening a new bin is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a good consolidation target (small residual = nearly full).
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Slight preference for acting early in the stream (keep options open later).
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * gap;
        if post_residual == next_item_size {
            score -= 300.0; // chain fit: next item closes this bin perfectly
        }
        // Penalize residuals too small for the next item only mildly (item may go elsewhere),
        // but reward residuals that are a sum fit for both is already captured by post_residual.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist: new bin has full residual,
    // so add a penalty scaled by stream progress and number of open bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (large post_residual waste elsewhere), allow new bin:
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // Allow new bin if lookahead item is huge and residuals are all small.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && post_residual >= next_item_size as u32 {
            score -= 80.0;
        }
    }

    // Mild tightness reward: smaller post_residual relative to capacity is better.
    score += 0.1 * (bin_capacity as f64 - post_residual as f64) * -0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving residual that is too small to be useful later,
    // but reward residuals that exactly match typical future needs.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty if post_residual tiny
            score += (post_residual as f64).min(10.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fewer bins.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 3.0;
    }

    // Prefer bins with residual below the mean residual (tighter bins),
    // keeping some diversity across open bins.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly less);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score = 55.0 + progress * 40.0 - (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size == 0 {
            score += 10.0;
        }
    } else if progress > 0.7 {
        // Late stage: reward filling bins nearly completely.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Small bonus for keeping open bin count manageable.
    if open_bins_count > 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: normalized post-residual (waste created by this placement)
    let mut score = post / cap;

    // Smooth non-linear waste penalty: quadratic coupling of post_residual with item fill ratio
    let fill = item / cap;
    score -= 0.9 * (1.0 - post / cap) * (1.0 - post / cap) * (0.5 + fill);

    // Progress coupling: as stream advances, prefer tighter fits more aggressively
    let tight = 1.0 - post / cap;
    score -= progress * 0.6 * tight * tight;

    // Penalize bins whose residual is far from mean residual (fragmentation pressure)
    score += 0.15 * ((res - mean_residual) / cap).abs();

    // Lookahead: reward if next item fits exactly into post_residual; penalize near misses
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 0.5 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 0.2 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 0.4 + 0.3 * progress;
    }

    // New-bin candidate: penalize mildly early, more when open bins have plenty of room
    if bin_residual == bin_capacity {
        score += 0.35 + 0.25 * (mean_residual / cap) + 0.05 * (open_bins_count as f64).ln();
    } else {
        // Reward using existing bins as they get fuller
        score -= 0.1 * (1.0 - res / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic classes: penalize post_residuals that fall into "dead" classes
    // (small leftovers that few future items can use). Items are 1..=100, so
    // leftovers <= 10 are nearly unusable; 11..=25 marginally usable.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Modulo-style class of post_residual relative to common small item bands.
    let pr = post_residual;
    let dead_mod = pr % 20;
    if pr > 0 && pr < 20 && dead_mod < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // Next item fits: leftover after that placement matters too.
            let pr2 = pr - next_item_size;
            score -= 12.0 * (1.0 - (pr2 as f64) / cap);
            if pr2 <= 10 { score -= 6.0; }
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled
            // by how much wasted space we would strand.
            score += 0.08 * (pr as f64) * (1.0 - (next_item_size as f64 / 100.0).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        // Base cost of a fresh bin.
        score += 55.0;
        // Discount if the item is big and would leave open bins fragmented.
        score -= (item_size as f64 / 100.0) * 30.0;
        // Discount when existing residuals are small (nothing useful to fill).
        score -= 25.0 * (1.0 - (mean_residual / cap).min(1.0));
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 20.0 * (1.0 - progress);
        // Many open bins with small mean residual: avoid adding more.
        if crowded > 3.0 { score += 10.0; }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10% capacity)
    let dead_threshold = bin_capacity as f64 * 0.1;
    if (post_residual as f64) < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual) nonlinearly
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Open-bin pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits the resulting residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 1.5;
        } else {
            score += 1.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual as f64 > dead_threshold {
            score -= 6.0;
        }
        score -= 0.1 * mean_residual;
    }

    // Stream progression: slight tightening bias over time
    score += 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (no dead space at all).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post-placement residual (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Reward when next item fits at all into the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating dead space the next item cannot use,
        // scaled by how much wasted space remains.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose residual after placement is small relative to the mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening new bins more when many bins are already open.
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * open_bins_count as f64;
    }

    // Early in the stream, be more willing to spread items (mild new-bin discount).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: reward small post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(1.5) * 20.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64 / bin_capacity as f64) * 8.0;
    }
    // Penalize post_residual too small to ever be useful again (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: many open bins with large mean residual -> avoid opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more so when open bins are underfilled.
        score += 25.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
    } else {
        // Reward filling already-open bins, especially when they are below mean residual.
        score -= 5.0;
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (10.0 + post_residual as f64 * 0.1);

    // Waste ratio coupling: penalize proportional waste.
    score += (item_size as f64 / bin_residual.max(1) as f64) * -4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // remainder classes (multiples of 10, i.e. capacity/10 grid) are more
    // likely to be filled by future items -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: quadratic in residual (waste grows superlinearly)
    score += 0.02 * pr * pr / cap;

    // Modulo-10 harmonic class: residuals divisible by 10 are "harmonic"
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Class of residual that exactly matches a common small item size
    if post_residual <= 20 && post_residual >= 10 {
        score -= 5.0;
    }

    // Integer-division threshold: bins with residual < 10 are nearly dead
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            let nr = post_residual - next_item_size;
            score -= 10.0 + 0.3 * nr as f64;
        } else {
            // next item won't fit here: penalize large leftover relative to next item
            score += 0.1 * (next_item_size as f64 - pr).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: opening a new bin is penalized when open bins
    // exist with decent residual, but encouraged when all residuals are bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a bin
        let mut penalty = 55.0;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable -> reduce penalty.
        penalty -= (mean_residual / cap).min(1.0) * 35.0;
        // Few open bins -> prefer consolidation into them slightly less
        if open_bins_count <= 2 {
            penalty += 10.0;
        }
        // Late in stream, avoid leaving many partially filled bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 15.0 * (1.0 - progress);
        // If item is large and nothing fits well, new bin is fine
        if item_size >= 60 {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Prefer fuller bins overall: compare residual to mean residual
    if bin_residual < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += 8.0 * pressure.min(5.0);

    // Prefer bins whose residual is above the mean (keeps big gaps alive for big items).
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward leaving that gap; if next item is large and gap too small, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else {
            // Slight bias toward using existing bins.
            score += 25.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect 2-chain: next item exactly fills this bin
        } else if post_residual as f64 >= next {
            // next item fits here too: reward tight coupling
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
            // extra reward if next item nearly fills bin after both placements
            let post2 = post_residual as f64 - next;
            if post2 < 10.0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: penalize leaving awkward gap
            score += 8.0 * (1.0 - (post_residual as f64 / next));
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 {
            (bin_capacity - item_size.min(bin_capacity)) as f64
        } else {
            (bin_capacity - item_size.min(bin_capacity)) as f64
        };
        score = tightness + 30.0 * (post_residual as f64 / bin_capacity as f64);
        if fitting_bins_count > 2 {
            score += 20.0; // plenty of alternatives; discourage new bin
        }
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 * 0.9 {
            score -= 10.0; // new bin pairs well with next item
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize leaving residuals that neither fit nor combine with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual is reusable by the lookahead item -> reward proportional to reuse
            score -= 12.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // dead space relative to next item -> penalize
            score += 0.35 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
        }
    } else {
        // last item: just minimize post residual aggressively
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Scarcity pressure: when few bins can fit, reward this bin more.
    if fitting_bins_count > 0 {
        score -= 10.0 / fitting_bins_count as f64;
    }

    // Global state: if mean residual is high (waste accumulating), be pickier
    // about poor fits; if low, accept placements more freely.
    let waste = mean_residual - post_residual as f64;
    score += 0.25 * waste.max(0.0);

    // Time horizon: early in stream, keep bins flexible (penalize small residuals);
    // late in stream, pack tightly regardless.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 0.15 * post_residual as f64;
    score -= progress * 0.10 * post_residual as f64;

    // Open-bin load balancing: many open bins -> prefer filling existing ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only open a new bin when the best existing fit
    // is genuinely poor (large post residual relative to capacity or next item).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.55 * bin_capacity as f64
            && (next_item_size == 0 || post_residual < next_item_size as f64);
        if poor_fit {
            score -= 55.0; // opening a fresh bin is better than fragmenting
        } else {
            score += 70.0; // an existing bin can absorb this item acceptably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, waste is increasingly penalized
    score += 30.0 * x * x * (0.2 + 0.8 * progress) * (1.0 + progress);

    // Penalize large dead space relative to mean residual state
    score += 5.0 * (x - mean_residual / cap).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x) * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (x - nx).max(0.0) / cap;
        score -= 10.0 * usable * (1.0 - progress);
        // penalize post residual that is too small for the next item
        if x < nx {
            score += 8.0 * (nx - x) * (1.0 + progress);
        }
    }

    // Mild preference for consolidating into fewer bins
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: classify post_residual by integer division into
    // capacity quarters. Dead space in the lowest class (0..=25) is nearly
    // unusable for typical items -> penalize; mid classes are valuable.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    match quarter {
        0 => {
            if post_residual > 0 { score += 25.0; } else { score -= 60.0; }
        }
        1 => { score -= 8.0; }
        2 => { score -= 12.0; }
        _ => { score -= 4.0; }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // small item-friendly sizes (10, 20, 25) pair well with future items.
    let pr = post_residual as i64;
    let mut harmony = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 5.0; }
        if pr % 50 == 0 { harmony += 6.0; }
    }
    score -= harmony;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // Reward proportionally to how tight the chain fit is.
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here regardless; slight penalty for leaving
            // a residual that tempts but fails.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 15 && post_residual > 0 {
            score -= 20.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin when existing
    // bins have decent usable residual; reward it when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 40.0;
        // If many open bins can fit the item, prefer reusing one.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, opening new bins is less costly (fewer future
        // chances to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // If mean residual across open bins is large, definitely reuse.
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // Small items start fresh bins happily (easy to combine later).
        if item_size <= 25 {
            score -= 15.0;
        }
        if item_size >= 60 {
            score += 10.0;
        }
    } else {
        // Reusing an open bin reduces fragmentation pressure.
        score -= 5.0;
        // Reward bins whose residual is far from the mean (diversity of
        // residual classes helps future fits).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 * (dev / bin_capacity as f64);
    }

    // Stream-phase modulation: early on, keep bins tidy (penalize messy
    // residuals); late, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 0.15 * post_residual as f64;
    } else if progress > 0.7 {
        score -= 0.10 * post_residual as f64;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Archetype #1232: strict dead-space avoidance + open-bin pressure.
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Dead-space trap: residual too small to ever hold a meaningful item.
    // Items are >= 1, but gaps below a small threshold are practically dead.
    let dead_threshold: u32 = 8;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64 * 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - next_waste / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit here: slight penalty unless this bin is nearly full anyway.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure proportional to open bins.
        score += 55.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well (this bin is the only fitter), reduce cost.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // If mean residual across open bins is small, open bins are nearly full:
        // opening a new bin is natural, reduce penalty.
        if mean_residual < 20.0 {
            score -= 20.0;
        }
    } else {
        // Mild reward for filling already-open bins, scaled by how full they are.
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Stream progression: early on, be a bit more conservative about tight fits
    // (uncertainty about future items); later, commit to tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Penalize bins whose residual deviates far below mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
