            score -= 20.0;
        } else if nx <= post {
            score -= 6.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current
    // fit is poor. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        score += cap * 0.35 + mean_residual * 0.2;
        // Late in the stream, opening new bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild preference to fill fuller bins (low residual) via tightness ratio.
    score += (post / cap) * 4.0;

    // Modulo threshold: residuals in [1,9] are near-dead; penalize by class.
    if pr >= 1 && pr <= 9 {
        score += (10 - pr) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum plausible item size are "dead" unless exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Moderately small gaps (< ~20) are risky dead space too.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if it cannot fit, the gap risks becoming dead.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0 + post_residual as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage proliferation of bins, so the
    // brand-new-bin candidate (large post_residual, no dead-space penalty)
    // only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 4.0 * (open_bins_count as f64 + 1.0);
    } else {
        score += 1.5 * open_bins_count as f64;
    }

    // Slight preference to fill bins below mean residual (balance consolidation).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect 2-chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if gap == 0.0 {
            score -= 60.0; // perfect lookahead match
        } else if post >= next {
            // next item fits after this one: reward proportionally to tightness
            score -= 40.0 * (next / post);
        } else {
            // next item would not fit: penalize leftover dead space
            score += 15.0 * (next - post) / bin_capacity as f64;
        }
        // Extra reward if the item after next could chain too (post == 2*next or near)
        if (post - 2.0 * next).abs() <= 2.0 && post > 0.0 {
            score -= 20.0;
        }
    } else {
        // Last item: prefer the fullest bin
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter,
    // favor packing into them to consolidate open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a brand-new empty bin when decent fits exist,
    // unless the item is huge (near capacity) where a fresh bin is natural.
    if bin_residual == bin_capacity {
        let huge = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - huge);
        // Late in the stream, keep bins consolidated
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild consolidation pressure: many open bins -> prefer filling existing ones
    score += 0.3 * open_bins_count as f64;

    // Prefer small post_residual overall (tight fits)
    score += 0.2 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but nonzero (dead space)
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    } else {
        score -= 20.0; // perfect fill
    }

    // Penalize leaving residuals that are too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 4.0; // blocks next item's fit here
        }
        // reward saving space for a large upcoming item
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= 0.05 * gap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score += 25.0 + 15.0 * progress + 2.0 * pressure;
        // allow opening when item is large and few bins fit it
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
    }

    // Mild preference for bins below mean residual (balance loads)
    score += 0.02 * (mean_residual - bin_residual as f64).abs();

    // Slight time decay: prefer filling older bins as stream progresses
    score -= 0.5 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, softly
    let mut score = pr;

    // Non-linear coupling: post_residual polynomial interacting with stream progress
    let quad = pr_norm * pr_norm;
    let cube = quad * pr_norm;
    score += 40.0 * quad * (0.5 + progress) + 25.0 * cube * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (nxt / cap);
        } else {
            let waste = (nxt - pr) / cap;
            score += 20.0 * waste * waste;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: mild penalty to prefer consolidation
    score += (open_bins_count as f64).ln() * pr_norm * 3.0;

    // Deviation from mean residual: prefer bins near/below mean residual usage
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless the current item
    // would leave a "harmonically useful" residual that pairs well with the
    // lookahead item, or there is essentially no alternative.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: strongly discourage opening a new bin.
        score += bin_capacity as f64 * 2.0;

        // Relax the penalty when no open bin fits (last resort).
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 2.5;
        }

        // Harmonic pairing: if next item divides into post_residual with
        // small remainder, opening a fresh bin is actually good.
        if next_item_size > 0 && next_item_size <= post_residual {
            let rem = post_residual % next_item_size;
            let quot = post_residual / next_item_size;
            if rem == 0 {
                score -= 60.0 + 10.0 * quot as f64;
            } else if rem <= 5 {
                score -= 25.0;
            }
        }
        // Perfect-fit bonus for current item itself.
        if post_residual == 0 {
            score -= 150.0;
        }
        // Few open bins: spreading is cheaper early on.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    } else {
        // Exact fit is ideal.
        if post_residual == 0 {
            score -= 200.0;
        }

        // Tight-fit reward: item fills most of the bin.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            score -= 30.0 * fill_frac;
        }

        // Penalize leaving dead space that no plausible item can use.
        // Items range 1..100; residual below the smallest item is dead.
        if post_residual < 3 {
            score -= 40.0; // near-perfect packing, good
        } else if post_residual < 10 {
            score += 15.0; // awkward small gap
        }

        // Harmonic classes on post_residual modulo capacity quarters:
        // residuals that are clean fractions of capacity (25/50/75) are
        // more reusable, reward them.
        let pr = post_residual;
        if pr == 25 || pr == 50 || pr == 75 {
            score -= 20.0;
        }

        // Lookahead coupling: does next item fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                let rem = pr % next_item_size;
                if rem == 0 {
                    score -= 35.0; // next item perfectly consumes remainder
                } else {
                    score -= 10.0; // next item still fits
                }
            } else {
                // Next item won't fit here; slight penalty if this placement
                // wastes the bin, but if this bin is the last chance, place
                // here regardless.
                if fitting_bins_count > 1 {
                    score += 12.0;
                }
            }
        }

        // Last-chance bin: strongly reward using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }

        // Prefer bins with residuals far below the mean (fill emptier bins
        // first keeps more large gaps available elsewhere).
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

        // Modulo-3 class on residual: diversify residual classes across bins
        // so future items of varied sizes find matches.
        let class = (pr % 3) as f64;
        score += class * 2.0;

        // Early stream: be slightly greedy to keep bin count low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score *= 1.0 + 0.1 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize wasting a large residual on a small item (poor fill efficiency).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * waste * 30.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: reward leaving space exactly usable by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward placements that leave a residual exactly matching (or close to)
    // the next item size (2-step lookahead matching).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: reward tight packing only
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual of open bins:
    // leaving more slack than average wastes capacity elsewhere.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Penalize creating residuals that are too small to be useful
    // (below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in the stream, mildly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).ln_1p();

    // New-bin candidate: make it attractive only when the item would leave a bad fit
    // everywhere else; a fresh bin's residual equals capacity minus item.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit, below a bad fit.
        score += 20.0;
        // But if the fresh bin perfectly chains with the next item, reward it.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize large dead space relative to item size.
    if post_residual > 0 {
        score += (post_residual as f64 / item_size.max(1) as f64) * 4.0;
    }

    // Last-chance bonus: only one bin can fit the item -> strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins have poor fit (large post_residual elsewhere)
        // and when many bins are open with high mean residual.
        let pressure = mean_residual / bin_capacity as f64;
        score = (bin_capacity as f64) * 0.9;
        if fitting_bins_count > 0 {
            // Slightly discourage new bin when open bins can fit.
            score += 5.0 + 10.0 * (1.0 - pressure);
        } else {
            score -= 10.0;
        }
        // Late in stream, prefer reusing open bins to avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Global state: when mean residual is high, favor using bins with residual near mean.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    // Mild penalty for opening many bins relative to progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bins_per_progress = open_bins_count as f64 / (progress * total_items.max(1) as f64 + 1.0);
    score += bins_per_progress * 2.0;

    // Time horizon: early in stream, be more selective (prefer near-perfect fits);
    // late in stream, accept decent fits to close bins.
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.05;

    // Small tie-breaker favoring fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post_norm * post_norm * (1.0 + 2.0 * progress) + post_norm * (0.5 * (1.0 - progress));

    // Reward tight fits: subtract when post_residual is small
    let tight_reward = -2.0 * (1.0 - post_norm) * (1.0 - post_norm);

    // Penalize dead space that cannot fit a typical next item
    let dead_penalty = if next_item_size > 0 {
        if (post as u32) < next_item_size { 1.5 * (1.0 - post_norm) } else { 0.0 }
    } else { 0.0 };

    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Slight preference for consolidating into fewer bins as stream progresses
    let consolidation = -0.5 * progress * (mean_residual / cap);

    // New-bin candidate: neutral baseline, slightly penalized when good fits exist elsewhere
    let new_bin_bias = if bin_residual == bin_capacity { 0.8 + 0.5 * progress } else { 0.0 };

    let mut score = post + 10.0 * (poly + tight_reward + dead_penalty + last_chance + consolidation + new_bin_bias);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead) / 10.0;
    } else if dead >= 10.0 && dead < 20.0 {
        score += 15.0 * (20.0 - dead) / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward leaving a gap exactly usable by the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins open or early stream.
        score += 40.0 + 10.0 * open_bins_count as f64 - 20.0 * progress;
        // But if no existing bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it instead of opening a new bin.
        score -= 45.0;
    }

    // Mild preference for bins below mean residual (keeps balance).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but rescale against mean residual
    let mean_r = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    score += (post_residual as f64 - mean_r) * 0.35;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-step lookahead match: next item exactly fills this bin
        if (pr - nxt).abs() < 0.5 {
            score -= 60.0;
        } else if pr >= nxt {
            // Next item still fits: reward proportional to how snugly it will nest
            let snug = 1.0 - (pr - nxt) / (bin_capacity as f64);
            score -= 12.0 * snug * snug;
        } else {
            // Next item will NOT fit in the leftover: penalize dead space
            let waste = nxt - pr;
            score += 10.0 + waste.min(40.0) as f64 * 0.8;
        }

        // Combined fill: item + next item nearly filling the bin is excellent
        let two_fill = (item_size as f64 + nxt) / bin_capacity as f64;
        if two_fill > 0.95 && bin_residual >= item_size {
            score -= 8.0 * (two_fill - 0.95) / 0.05;
        }
    } else {
        // Last item: just minimize post_residual aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave bad waste
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slight preference when many bins are open
        score = bin_capacity as f64 * 0.9 - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size as f64 >= mean_r {
            score -= 5.0; // fresh bin will pair well with the next item
        }
    }

    // Mild time decay: as stream progresses, consolidate into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post_residual is valuable dead-space-wise.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize medium dead space that likely becomes unusable
    // (residuals too small for typical items are wasted).
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 10.0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 30.0 + 20.0 * (1.0 - chain_quality / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item won't chain; mild penalty scaled by how badly it misses.
        let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 5.0 * (miss / 50.0).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fullness * (10.0 + 20.0 * progress);
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - fullness) * 8.0;

    // Compare against mean residual: bins below mean residual are emptier;
    // prefer filling emptier bins when mean residual is small (late consolidation).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        score += (rel - 1.0) * 10.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin ~ its unused capacity.
        score = (bin_capacity - item_size) as f64;
        // Early in stream, opening bins is cheaper (more future to fill them).
        score -= 30.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 80.0;
        }
        // Lookahead: if next item also large, a fresh bin is fine.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let coupling = (1.0 + 2.0 * t * t) * (1.0 - pr / cap);
    score += 3.0 * coupling * pr / cap;

    // Penalize dead space relative to mean residual smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + t);

    // Reward tight fits (small post_residual) with smooth saturating term.
    score -= 5.0 * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: penalize leaving residual too small for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - pr;
        if gap > 0.0 {
            score += 2.0 * (gap / cap) * (1.0 + t);
        } else {
            score -= 1.5 * (-gap / cap);
        }
    }

    // New-bin candidate: mildly penalize early, allow late when bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (mean_residual / cap);
        score += 6.0 * (1.0 - t) - 2.0 * fragmentation * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring the post-residual punishes large leftovers
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 8.0);

    // Harmonic class of the item: which quarter of capacity it occupies
    let item_class = (item_size * 4).max(bin_capacity + 1) / bin_capacity; // 1..=4
    let fit_ratio = item_size as f64 / bin_residual as f64;
    match item_class {
        1 => score -= 4.0,                       // tiny items: very flexible
        2 => score -= 2.0 + 2.0 * fit_ratio,     // small-medium
        3 => score -= 3.0 + 3.0 * fit_ratio,     // medium-large: fill greedily
        _ => score -= 6.0 + 4.0 * fit_ratio,     // large items: place almost anywhere
    }

    // Perfect-fill harmonic bonuses via integer division on post_residual
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: leftover too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Lookahead: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; bonus scaled by how well it fits
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use this leftover; penalize stranded residue
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin if the item is large
    // relative to typical residuals and existing fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        // Penalize new bins generally, less so as stream progresses
        let mut new_bin_score = 30.0 - 10.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 1 {
            new_bin_score += 20.0;
        }
        // Large items justify fresh bins; tiny items never do
        new_bin_score -= (item_size as f64 - 40.0).max(0.0) * 0.4;
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 5.0; // big follow-up item makes room valuable
        }
        score += new_bin_score / open_pressure;
    }

    // Mild tie-break toward bins below mean residual (consolidating emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the min item size)
    // are pure waste — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small to fit the lookahead item are less useful; mild penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room exactly usable by the next item.
        score -= 6.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Perfect fit: exceptional reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure;

    // New-bin candidate: only attractive when this bin is the last chance and
    // the fit is poor, or when few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let last_chance = fitting_bins_count == 1;
        let poor_fit = (post_residual as f64) > mean_residual;
        if last_chance && poor_fit {
            score -= 15.0; // opening a new bin beats wasting the last usable bin
        } else {
            score += 25.0 + 10.0 * progress; // prefer existing bins otherwise
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference for bins whose residual is below the mean (compact bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
