pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates less when small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving residuals that waste potential for the next item.
            let waste = (next_item_size as f64 - post_residual as f64).min(40.0);
            score += 0.15 * waste;
        }
    }

    // Global state coupling: with many open bins and high mean residual,
    // prefer consolidating into existing bins rather than spreading.
    let consolidation_pressure = mean_residual / bin_capacity as f64
        * (open_bins_count as f64).ln().max(1.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * consolidation_pressure;
    } else {
        // New-bin candidate: penalize opening a new bin, more so when
        // existing bins have plenty of room or stream is late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 8.0 * consolidation_pressure + 4.0 * progress;
        // Allow new bin only if item is large relative to mean residual.
        if item_size as f64 > mean_residual {
            score -= 7.0;
        }
    }

    // Early stream: slight preference for keeping bins balanced (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        let imbalance = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * imbalance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, compact placements matter more, so penalize large residuals.
    let progress_coupling = pr * (progress * progress) * (0.5 + fit_ratio);
    score += 0.8 * progress_coupling;

    // Reward tight fits with a smooth quartic term in tightness.
    score -= 6.0 * tightness * tightness * tightness * tightness * (1.0 + progress);

    // Penalize large dead space softly (quadratic in normalized residual).
    let dead = pr / cap;
    score += 10.0 * dead * dead;

    // Last-chance bin: strongly favor using it when it fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0 + 4.0 * (1.0 - (post_residual - next_item_size as u32) as f64 / cap);
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // current open bins have poor residuals relative to the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score = cap * (0.6 + 0.4 * progress) - 12.0 * mean_gap * mean_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into usable bands
    // Classes based on integer division by capacity fractions (1/4, 1/2, 3/4).
    let post_class = post_residual / (bin_capacity / 4);
    match post_class {
        0 => score -= 25.0,                 // near-perfect fit, tiny dead space
        1 => score -= 8.0,                  // leftover fits small items (<=25)
        2 => score -= 12.0,                 // leftover fits medium items (<=50)
        3 => score -= 4.0,                  // large leftover, mediocre fill
        _ => score += 0.0,                  // empty-ish bin placement
    }

    // Modular coupling: does post_residual align with common small-item classes?
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0;                       // post_residual is multiple of 10 -> likely exact future fit
    } else if r >= 7 {
        score += 4.0;                       // awkward remainder creates dead space
    }

    // Lookahead: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // bonus if next item also aligns to harmonic class of post_residual
            if post_residual / next_item_size.max(1) >= 2 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize slightly more if this was a tight fit
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins with low mean residual: prefer filling existing bins tightly.
    if open_bins_count > 3 {
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= tightness * 10.0;
    }

    // New-bin candidate logic: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 20.0 + (open_bins_count as f64) * 2.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // if next item is large, having a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier -> good to fill it.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    } else if dead == 0.0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward using bins that would otherwise waste large residuals.
    if post_residual as u32 == bin_residual - item_size {
        // no-op guard; post_residual already reflects this
    }
    if bin_residual as f64 > mean_residual + 20.0 {
        score -= 8.0; // prefer fattest bins when it helps
    }

    // Open-bin pressure: discourage spreading across many bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
