    }

    // New-bin candidate calibration: opening a new bin should only win when
    // this placement would create bad dead space in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, softened when many bins are open or
        // the current item is large.
        score = 15.0 + 0.2 * (open_bins_count as f64) - 0.05 * (item_size as f64);
