pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // 2-step lookahead: reward bins whose residual matches the next item well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item could also fit here: strong reward for tight chain match.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: penalize wasted potential.
            score += 8.0 * (1.0 - (bin_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
        }
        // Exact match with next item is ideal.
        if post_residual == next_item_size as u32 {
            score -= 25.0;
        }
    } else {
        // Last item: maximize packing tightness.
        score -= 20.0 * (1.0 - fit_ratio);
    }

    // Penalize creating dead space far from mean residual (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // or no open bin fits well. Base penalty keeps it from being chosen lightly.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size as f64 >= item_size as f64 {
            // If next item is larger, opening a fresh bin is more reasonable.
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 10.0;
        }
    }

    // Slight early-stream preference to keep bins consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
