                score += 12.0; // tiny unusable sliver
            } else {
                score += 4.0 * (1.0 - gap / (bin_capacity as f64));
            }
        }
    } else {
        // Last item: prefer filling bins as completely as possible.
        score -= 30.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual space in all
    // existing bins. Penalize new bins unless current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Cheaper to open a new bin when many bins are already open with large mean residual
        // (fragmentation is high; consolidation is failing).
        score -= 0.15 * (open_bins_count as f64);
        score -= 0.3 * mean_residual;
        // Early in the stream, opening bins is fine; late in the stream it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If the item is large relative to capacity, a fresh bin is a natural home.
        score -= 0.2 * (item_size as f64);
    } else {
        // Mild bonus for using existing bins when fragmentation is low.
        score -= 0.1 * (open_bins_count as f64).recip();
    }

    // Penalize bins whose residual deviates far from the mean (keeps a diverse residual portfolio).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins that would end up with residual matching the next item size (harmonization).
    if next_item_size > 0 {
        let mismatch = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.08 * mismatch;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    score += 6.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score -= 4.0 * norm_pr * (1.0 - progress) * (1.0 - progress);
    // Reward tight fits more strongly as stream progresses
    score -= (item_size as f64 / cap) * (1.0 + 2.0 * progress) * 2.0;
    // Penalize creating dead space below typical item sizes
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 1.5 * (gap / cap) * (0.5 + progress);
        } else {
            score -= 2.0 * (pr / next_item_size as f64) * (1.0 - progress);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }
    // Slight penalty for spreading across too many bins late
    score += (open_bins_count as f64) * 0.05 * progress;
    // New-bin candidate: mild baseline so it's chosen only when residuals are large
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 define "usable" slots
    let residue_class = post_residual % 10;
    // Classes near 0 (perfect fit) or near 10 (can host a small item) are valuable
    let class_bonus: f64 = match residue_class {
        0 => -12.0,
        1..=4 => -6.0,
        5..=8 => 0.0,
        _ => -3.0,
    };
    score += class_bonus;

    // Integer-division thresholds: post_residual buckets by quarter-capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score -= 8.0; // tight bin, good to close out
    } else if post_residual < 2 * quarter {
        score -= 2.0;
    } else if post_residual < 3 * quarter {
        score += 3.0;
    } else {
        score += 6.0; // wastefully empty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual == next_item_size) as i32 as f64;
        score -= 15.0 + 10.0 * exact;
        // harmonic match: next_item_size and post_residual share a mod-10 class
        if next_item_size % 10 == post_residual % 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to wasted potential
        score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / cap_f).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin preserves flexibility for larger items
        }
    }

    // Progress-aware pressure: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap_f);

    // Deviation from mean residual: prefer bins with residuals close to item needs
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Small penalty per open bin to discourage bin sprawl
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are wasted. Penalize heavily with a non-linear ramp.
    let dead_threshold = 10.0f64; // smallest item size
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    } else {
        // Prefer tight fits: quadratic bonus for small post_residual
        score -= (bin_capacity as f64 - post_residual as f64) * 0.35;
    }

    // Penalize residuals that cannot fit the lookahead item but are above
    // the dead threshold (moderately wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward if lookahead fits exactly in post_residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.15;

    // Deviation from mean residual: prefer bins already below mean residual
    // (tighter bins get filled first, preserving larger gaps elsewhere).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate calibration: only attractive when no open bin fits
    // well (post_residual small in every fitting bin). Base cost of a new bin.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 0.5;
        // Opening a bin is fine if it perfectly hosts the item and lookahead.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual penalizes large leftover gaps
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 22.0 - 0.25 * chain_quality;
    } else if next_item_size > post_residual {
        // Penalize leaving a gap that the next item cannot use (dead space)
        let waste = (post_residual as f64) / (next_item_size as f64).max(1.0);
        score += 8.0 * waste.min(1.5);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Perfect fit extreme reward
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early; relax later or when mean residual is low
        let new_bin_penalty = 55.0 * (1.0 - 0.5 * progress) - 20.0 * (1.0 - fragmentation.min(1.0));
        score += new_bin_penalty.max(5.0);
        // If item is large relative to capacity, new bin is fine
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (fuller bins)
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.12 * residual_gap;

    // Slight preference to fill older bins when many bins are open
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let ni = next_item_size as f64;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) emphasis on small post_residual.
    let mut score = pr + 0.9 * (pr / cap).powi(2) * cap + 0.4 * (pr / cap).powi(3) * cap;

    // Smooth coupling: dead space is worse later in the stream.
    score += 12.0 * progress * (pr / cap);

    // Lookahead: reward bins whose post_residual can still hold the next item,
    // penalize post_residual that is just barely too small (unusable sliver).
    if ni > 0.0 {
        let fits_next = if pr >= ni { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (ni / cap);
        let sliver = (ni - pr) / cap;
        if fits_next == 0.0 && sliver < 0.15 {
            score += 10.0 * (0.15 - sliver) / 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when other bins fit, more so early on
    // and when open bins have plenty of residual room.
    if bin_residual == bin_capacity {
        let spread = mean_residual / cap;
        score += 15.0 + 10.0 * (1.0 - progress) + 6.0 * spread;
    }

    // Mild preference for bins with below-average residual (consolidate fullness).
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * diff;

    // Slight preference for larger item placement density (item relative to residual).
    score -= 2.0 * (it / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured.

    // Harmonic class of post_residual: reward residuals that are "perfect"
    // (zero) or fall into low-waste classes (1..=5), penalize mid-range waste.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0 - (pr as f64) * 2.0;
    } else if pr <= 15 {
        // usable zone for small future items: mild reward scaled by class
        score -= 6.0 - ((pr as f64) - 5.0) * 0.4;
    } else if pr <= 25 {
        // dead-space risk zone: penalty grows
        score += ((pr as f64) - 15.0) * 1.2;
    } else {
        // large residual: somewhat neutral, may still hold mid-size items
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize wasted opportunity.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 18.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            // next item won't fit here: residual is dead unless tiny
            if pr < 10 {
                score += 4.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 unit of capacity potential; only attractive
        // when the item is large relative to capacity (poor fit anywhere) or
        // when many bins are already open with slack.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = 55.0 - size_frac * 70.0;
        score += open_bins_count as f64 * 1.5;
        score += (mean_residual - 40.0) * 0.15;
        // Late in the stream, prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Small items should almost never open a new bin.
        if item_size <= 30 {
            score += 25.0;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // strongly prefer the sole fitting bin
        }
    }

    // Mild preference to fill already-open bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 4.0;
    }

    // Prefer bins whose residual is close to the mean (balance load) when
    // many bins are open; avoids accumulating many near-full bins too early.
    if open_bins_count > 3 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // are worse than larger residuals. Items are 1..100, so treat small gaps
    // (< ~20) as nearly unusable.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fit is excellent: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // nearly, reward; if next item can never fit this residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (early stream), encourage consolidation when many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    if new_bin > 0.5 {
        score += 25.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        // If no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate similar residuals to keep packing options coherent).
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit here: penalize small dead space that is
            // unlikely to be usable later.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - waste);
            }
        }
    }

    // Relative residual vs mean: prefer bins tighter than the average open bin.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize leaving very small unusable residuals (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: default neutral; make it attractive only when no
    // open bin offers a good fit (large post_residual on existing bins),
    // by adding a mild penalty that scales with how many bins fit the item.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when the item fits poorly everywhere else.
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else {
            // Slightly discourage opening when alternatives exist.
            score += 20.0 + 5.0 * (fitting_bins_count as f64).sqrt();
        }
    }

    // Early stream: be a bit more willing to spread (keep options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling (k=2): residual after placement should remain usable
    // by the next item, otherwise part of it becomes dead space.
    if next_item_size > 0 {
        if (next_item_size as f64) <= score + 1000.0 && (next_item_size as u32) <= post_residual {
            // Next item fits exactly-ish into the new residual: reward tight reuse.
            let slack = post_residual - next_item_size;
            score -= 8.0 - 0.08 * slack as f64;
        } else {
            // Dead space relative to the lookahead item: penalize proportionally.
            let dead = next_item_size as f64 - post_residual as f64;
            score += 0.6 * dead.max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Penalize very tight-but-nonzero leftovers that are likely unusable
    // (items are >= 1, but small slivers relative to typical sizes are waste).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Reward tighter packing overall (less residual left is better, already in base,
    // add small bonus for filling deeply into the bin).
    score -= 0.05 * (item_size as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: opening a new bin should be discouraged when
    // any open bin can fit, more so late in the stream or with many open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 0.5 * open_bins_count as f64 + 5.0 * progress;
        // Exception: if no open bin fits well (we are the only "fitting" option),
        // soften the penalty so a fresh bin can win over a terrible fit.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            // Compare: using the last-chance bin is usually better; keep penalty high.
            score += 5.0;
        }
    }

    // Mild global pressure: when mean residual across open bins is high, we can
    // afford slightly worse fits; when low, be pickier (amplify differences).
    score *= 1.0 + 0.002 * (mean_residual - 50.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: penalize leftover space, amplified quadratically (dead space hurts more as it grows).
    let mut score = post * (1.0 + 0.01 * (post / cap) * (1.0 + progress));

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - post / res.max(1.0);
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Perfect fit bonus (smooth, no hard threshold).
    let pf = (post / cap).max(0.0);
    score -= 10.0 * (-20.0 * pf).exp();

    // Coupling with next item: reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = 1.0 - gap / cap;
        score -= 6.0 * fit_next.max(0.0) * (1.0 - progress * 0.3);
        // Penalize leaving a residual just barely too small for next item (bad dead space).
        if post < nxt {
            score += 4.0 * (1.0 - post / nxt.max(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post / cap);
    }

    // Prefer bins with below-mean residual (consolidate emptiness).
    score += 0.05 * (mean_residual - res);

    // Slight preference for fewer open bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 0.05 * open_bins_count as f64 - 3.0 * (fitting_bins_count as f64).min(5.0);
        if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "useful" small classes (likely fillable by future items), penalize
    // mid-range dead space.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -30.0,
        1..=5 => -20.0,
        6..=15 => -8.0,
        16..=30 => 6.0,
        31..=50 => 14.0,
        _ => 4.0,
    };
    score += class_penalty;

    // Modulo coupling: residuals that are multiples of common item sizes
    // (10/20/25/50) are more likely to be exactly filled later.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 10.0;
    }
    if pr > 0 && next_item_size > 0 && next_item_size <= pr {
        // Lookahead: this bin can also host the next item -> strong reward,
        // scaled by how snugly the next item fits.
        let snug = (pr - next_item_size) as f64;
        score -= 18.0 - 0.25 * snug;
        if (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item cannot follow here; slight penalty.
        score += 5.0;
    }

    // Perfect fit bonus relative to capacity fractions.
    let frac = post_residual as f64 / cap;
    if frac < 0.05 {
        score -= 15.0;
    } else if frac > 0.5 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and spreading capacity is cheap.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.9 + 25.0 * progress + 6.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // prefer using the single fitting bin
        }
        if mean_residual > 35.0 {
            score += 10.0; // open bins already have slack; reuse them
        }
    }

    // Mild preference for tighter existing bins when many fit.
    if fitting_bins_count > 2 {
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving residuals that can likely host future items.
    if post_residual >= 10 {
        let usable_bonus = if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
            12.0
        } else {
            0.0
        };
        score -= usable_bonus;
        // Penalize residuals just above item range maxima that are hard to fill.
        if post_residual > 80 {
            score += 4.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize wasting a residual that would have fit the next item.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 1.5;
        let mean_gap = mean_residual - item_size as f64;
        let new_bin_penalty = 30.0 + pressure - if mean_gap > 0.0 { mean_gap.min(20.0) } else { 0.0 };
        score += new_bin_penalty;
    }

    // Open-bin pressure: mild reward for consolidating when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Late-stream consolidation bias.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover usable by next item: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 30.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // perfect chaining: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow opening when next item is large and this item is small
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 60.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 - 20.0 * post_residual as f64;
    } else {
        // Penalize large dead space super-linearly.
        let pr = post_residual as f64;
        score += 0.05 * pr * pr;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Many fitting bins: mild penalty for spreading; prefer fuller bins.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward leaving room for the next item if it fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Creating dead space the next item cannot use is bad.
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state: if mean residual across bins is large, encourage consolidating
    // into existing bins (penalize opening new bins implicitly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let open_penalty = 20.0 * (open_bins_count as f64).ln().max(1.0);
    score += new_bin * (open_penalty + 50.0 * progress);

    // New bin is acceptable only if the item is large relative to capacity
    // (poor fit anywhere else) — reward slightly then.
    if new_bin > 0.0 {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 60.0 * large_item;
        }
    }

    // Slight preference for bins with residual below the mean (fuller bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: strongly penalize large residuals (waste); late stream:
    // residual dominates less and tight fits matter more.
    let w = 1.0 + 2.0 * progress * (1.0 - progress); // smooth bump peaking mid-stream
    score += w * (prn * prn) * 30.0;

    // Cubic term: punish very large dead space super-linearly as stream advances.
    score += progress * (prn * prn * prn) * 40.0;

    // Lookahead coupling: reward residuals that can host the next item,
    // scaled smoothly by progress.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - progress) * 12.0 + 6.0 * (slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how close it was.
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 8.0 * miss * miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Scarcity of fitting bins: mild reward when alternatives are few.
    if fitting_bins_count > 0 {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (tighter bins), smoothly weighted.
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
        score += 5.0 * dev * dev.abs();
    }

    // New-bin candidate: make it attractive only when item fits poorly anywhere,
    // otherwise keep it mildly penalized so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if item_size >= 50 {
            score -= 8.0; // big items start fresh bins reasonably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize wasted space quadratically.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Harmonic class logic: classify post_residual into capacity-fraction buckets.
    // Residuals in "dead zones" (too small for likely items, i.e. < 10..20) are heavily penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    if frac < 0.10 {
        score += 40.0 * (0.10 - frac); // nearly-full bin: fine, but tiny residual is dead space
    } else if frac < 0.20 {
        score -= 25.0; // excellent: residual in small-item harmonic class
    } else if frac < 0.34 {
        score -= 12.0; // good medium class
    } else if frac < 0.51 {
        score -= 6.0;  // half-bin class
    } else {
        score += 8.0 * frac; // leaving a large gap: weak placement
    }

    // Integer-division thresholds: residual divisible into common item classes is reusable.
    if post_residual >= 10 {
        let usable = (post_residual / 10) as f64;
        score -= 2.0 * usable;
    } else {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // extra harmonic bonus when next item exactly matches a class threshold of the residual
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 10.0; // near-perfect chain
        }
    } else if next_item_size > post_residual {
        score += 5.0; // next item will need another bin anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into fuller bins.
    if open_bins_count > 3 {
        score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - frac);
    }

    // Mean residual coupling: if this bin is much emptier than average, deprioritize slightly
    // (prefer filling bins that are already partially used), keeping mean residual low overall.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else {
            // penalize opening a new bin when open bins fit; scale with stream progress
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 55.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the smallest plausible item (~1..10) is pure dead space.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (post_residual near 0 but not wastefully small).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual.
        score += open_bins_count as f64 * 5.0;
        score += mean_residual * 0.5;
        // Early in stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Slight reward for using existing bins as pressure builds.
        score -= open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for stranding space.
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it neutral-to-slightly-averse so we only open
    // a new bin when fitting into an open bin would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        return score;
    }

    // Perfect fit reward: post_residual zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space non-linearly (small leftovers are nearly useless).
        if post_residual < 10 {
            score += 25.0; // tiny unusable slivers
        } else {
            score += (post_residual as f64).powf(1.3) * 0.05;
        }
    }

    // 2-step lookahead: reward bins where the next item fits snugly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chained perfect fit
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over.min(50.0) * 0.3;
        }
    }

    // Compare residual against mean residual: prefer tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early stream: consolidate into few bins to build tight packs.
    if open_bins_count > 3 {
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Lookahead: if leftover can still hold the next item, this bin stays useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Dead space relative to next item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.10 * dead;
            // Perfect wrap (post_residual == 0) is still great.
            if post_residual == 0 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Mild spread bonus when several bins compete: prefer emptier ones.
        score += 0.03 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let urgency = (fitting_bins_count == 0) as i32 as f64;
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        score = 40.0 - 45.0 * urgency - if large_item { 10.0 } else { 0.0 };
        // Early in stream, opening bins is cheaper; late, reuse matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight penalty for accumulating too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild preference for tight fits; late: strongly avoid wasting space.
    let tightness = 1.0 - (pr / cap);
    let progress_coupling = progress * (1.0 - progress * 0.5);
    score -= 12.0 * tightness * tightness * (0.5 + progress_coupling);

    // Reward when post_residual matches the next item size (chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 10.0 * (1.0 - diff / cap).powi(3);
    } else {
        // Last item: dead space is pure waste, penalize quadratically.
        score += 0.05 * pr * pr / cap;
    }

    // Penalize creating small unusable slivers relative to the smallest possible item (1).
    if pr > 0 {
        score += 3.0 * (1.0 - pr / cap).powi(4);
    }

    // New-bin candidate (empty bin): discourage unless existing fits are poor.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).max(1.0);
        let mean_gap = (mean_residual - pr).abs();
        score += 8.0 + 0.5 * crowd + 2.0 * (1.0 - mean_gap / cap);
        // Late in the stream, opening new bins is cheaper than fragmentation.
        score -= 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight preference for bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: low mod classes are "usable" slots
    let mod_class = post_residual % 10;
    let class_penalty = match mod_class {
        0 => -30.0,
        1 | 2 | 3 => -12.0,
        4 | 5 | 6 => 0.0,
        7 | 8 => 8.0,
        _ => 15.0,
    };
    score += class_penalty;

    // Integer-division thresholds: tiny residuals are dead space
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect-fit harmonic bonus (post_residual divides capacity nicely)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized unless
    // the fit into existing bins is terrible (large post_residual)
    if bin_residual == bin_capacity {
        score = 50.0 + item_size as f64 * 0.3 - (next_item_size as f64) * 0.1;
        if post_residual >= 60 {
            score -= 20.0;
        }
    }

    // Fraction of capacity used: reward tight packing
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Late-stream tightening: fewer wasted slots as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.4 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.25;

    // Many open bins: discourage spreading, favor filling existing ones
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (1..=8) are "dead". Penalize them hard.
    if post_residual > 0 && post_residual <= 8 {
        score += 40.0 + (8 - post_residual) as f64 * 6.0;
    }
    // Gaps that cannot fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // Reward tight fits: item filling most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64).sqrt() * 2.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_pressure = mean_residual / bin_capacity as f64;
        score = 55.0 + spread_pressure * 30.0 - progress * 10.0;
        if item_size > mean_residual as u32 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild lookahead coupling: if this placement leaves room exactly for
    // the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 25.0; // perfect 2-chain match
            }
        } else {
            // next item cannot follow into this bin: penalize proportionally to wasted chain potential
            score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already tight relative to mean residual.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Penalize large dead space (post residual too small to be useful for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless it enables a good 2-chain.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post_residual.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward residuals that are hard to fill by other items (dead-space avoidance).
        score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Penalize fragmenting bins when many bins are open and mean residual is low.
    if open_bins_count > 1 {
        let frag = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * frag.max(0.0) - 2.0 * frag.min(0.0);
    }

    // Early in stream: mild preference for consolidating into existing bins.
    score -= (1.0 - progress) * 3.0;
    // Late in stream: prefer filling bins as fully as possible.
    score += progress * 0.05 * post_residual as f64;

    // New-bin candidate: open a new bin only if all fits are poor or it's a very tight item.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64) > 0.6 * bin_capacity as f64 && next_item_size > post_residual;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 20.0 * (1.0 - norm_pr) * progress;

    // Reward when the next item can exactly fill the remaining space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 15.0 * match_bonus * match_bonus;
        // Penalize if next item cannot fit the leftover (dead space risk).
        if nxt > pr {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening a brand-new bin when other bins fit and residuals are healthy.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 40.0 + 10.0 * mean_residual / cap;
    }

    // Mild pressure against accumulating too many open bins late in the stream.
    score += 2.0 * open_bins_count as f64 * progress / (1.0 + progress);

    // Slight preference for bins below mean residual (balance spreading).
    score += 5.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill (equivalently, small post_residual) non-linearly
    score -= 60.0 * fill * fill;

    // Harmonic class of post_residual: dead space that no item (1..100) can use
    // is the worst outcome; residual below the smallest item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 400.0; // unusable sliver
    }

    // Dead-space classes: residual that cannot fit common small items
    let dead = |r: u32| r > 0 && r < 25;
    if dead(post_residual) {
        score += 120.0;
    }

    // If the next item fits into the resulting residual, big reward (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 - 0.35 * slack; // prefer snug follow-up fit
    } else if next_item_size > 0 {
        // next item won't chain here: penalize proportionally
        score += 15.0;
    }

    // Perfect or near-perfect closure
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is huge relative to capacity or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size * 2 >= bin_capacity {
            score -= 200.0; // big items start fresh bins happily
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // forced new bin
        }
        // late in stream, fewer open bins is better than spreading
        if open_bins_count > 8 {
            score += 60.0 * ((open_bins_count as f64) / 8.0 - 1.0);
        }
    }

    // Prefer bins with residual already below the mean (consolidate tight bins)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.25 * (mean_residual - res);
    } else {
        score += 0.15 * (res - mean_residual);
    }

    // Slight preference for keeping bin count low as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Modulo/harmonic tie-breaking on post_residual classes (multiples of 10
    // leave room for the smallest items)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Favor bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 15.0;
        }
    }

    // Pressure on number of open bins: prefer fewer open bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: acceptable early or when it enables a large residual buffer,
    // penalized when decent fits already exist.
    if bin_residual == bin_capacity {
        score = 55.0 + 2.0 * open_bins_count as f64 - 10.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the only fitting bin
        }
        if item_size > 50 {
            score -= 10.0; // big items are fine in a fresh bin
        }
    }

    // Mild preference for bins with below-average residual (fill emptier bins first).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * lookahead_gap;

        // Perfect chain: post_residual == next_item_size -> strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Also reward if next item fits with small slack.
        if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item cannot follow here; penalize proportionally to wasted space.
            score += 5.0;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, especially mid-stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 5.0 {
            score += 10.0;
        }
    }

    // Slight penalty for leaving very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize bins whose residual is much larger than mean residual (poorly packed bins)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here: slight penalty for leaving awkward space
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized when good fits exist.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) + 5.0;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // avoid abandoning a last-chance bin
        }
        // opening new bins is cheaper early on
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * (1.0 - progress);
    }

    // Mild penalty for accumulating many open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Waste becomes progressively more costly as the stream advances.
    let w = post / cap;
    let coupling = w * w * (0.5 + progress) + w * w * w * (1.5 * progress);
    score += 4.0 * coupling;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item / (item + post + 1.0);
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit, more so early/mid stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 8.0 * (1.0 - fit_pressure) * (1.0 + progress);
        // Allow new bin if it would create a very small residual (near-perfect fit).
        if post < 6.0 {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins with residual close to mean (balance residuals).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 2.0 * dev * dev;
    }

    // Lookahead: reward leaving residual that can still host the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            let slack_fit = 1.0 - ((post - n) / cap);
            score -= 3.0 * slack_fit * slack_fit;
        } else {
            score += 2.0 * (n - post) / cap;
        }
    }

    // Mild open-bin consolidation pressure.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < quarter {
        score -= 25.0;
    } else if post_residual < half {
        score += 10.0;
    } else {
        score += 30.0; // large residual = bin still mostly usable
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are more reusable
    // under integer item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // next item cannot use this residual; penalize wasting space now
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer fuller bins (tight fit) slightly more when many bins are open.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 8.0;

    // Mean-residual coupling: if this bin's residual is far below mean,
    // placing here consolidates small residuals.
    let diff = mean_residual - post_residual as f64;
    score += 0.15 * diff;

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 15.0;

    // New-bin candidate: only attractive if no good fit exists.
    if bin_residual == bin_capacity {
        score += 70.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 30.0; // pairing impossible anyway; open fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving gaps that are too small for typical future items
    // but large enough to be "wasted" (unusable dead space band).
    if post_residual > 0 && post_residual < item_size && post_residual < 50 {
        score += 8.0;
    }

    // Reward using bins that would otherwise be near-empty (consolidation).
    if bin_residual as f64 > mean_residual * 1.5 {
        score -= 5.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (a fresh bin has full residual, so its raw score is high; adjust mildly).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact-ish fits (small post_residual)
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // 2-step lookahead: if next item fits perfectly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item cannot fit here: penalize leaving awkward leftovers
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare post_residual to mean residual: leaving much less than average is good (tight packing)
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Penalize unusable dead space (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // mild default penalty; overcome only if open bins score very badly
        score += 12.0;
        // early stream: opening bins is cheap-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Slight preference to fill bins with larger residuals when many bins are open
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).
    // Add a non-linear penalty for awkward dead space (small but nonzero leftovers).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead = if pr < 10.0 { pr * 2.5 } else { 0.0 };
        score += dead;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, tighter if near-exact chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * (gap / 20.0).min(3.0);
        }
    } else {
        // Last item: just minimize leftover, reward near-full closure.
        score -= 5.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // opening is OK only when existing residuals are too small / few fitting bins
        score += 30.0 - 20.0 * (1.0 - frag) - if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
    } else {
        // Slight preference for fuller bins among open ones.
        score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be conservative (favor new bins to build diversity);
    // late in stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t); // new bins cheaper early
    } else {
        score -= 6.0 * t; // reuse more attractive late
    }

    // Coupling with global mean residual: if this bin's residual is far below mean,
    // it's a "rich" bin — prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress in (0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear waste pressure: dead space hurts more as the stream progresses.
    let waste_pressure = (pr / cap).powi(2) * (1.0 + 2.0 * progress);
    score += waste_pressure * cap * 0.5;

    // Perfect / near-perfect fits get a smooth reward (no piecewise cutoffs).
    let tightness = 1.0 - (pr / cap);
    score -= tightness.powi(3) * cap * 0.6;

    // Last-resort bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.45 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if it barely misses, penalize (fragmentation risk).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let lookahead_fit = (1.0 - gap / cap).max(0.0);
        score -= lookahead_fit.powi(2) * cap * 0.35;
        if nxt > pr {
            score += (nxt - pr) * 0.25 * (1.0 + progress);
        }
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // residuals are badly fragmented relative to the item size.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).powi(2);
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score += cap * (0.35 - 0.5 * frag) * (0.5 + openness);
        // Late in the stream, prefer consolidating into open bins.
        score += cap * progress * 0.3;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions (1/8 granularity) with modulo arithmetic.
    let cap = bin_capacity as f64;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..8 integer class
    let next_class = next_item_size / eighth;

    // Penalize dead space: leftover that no plausible item (>=1) can use well.
    // Small leftovers (class 0) are pure waste; large leftovers are reusable.
    match post_class {
        0 => score += 12.0,
        1 => score += 6.0,
        2 => score += 2.5,
        3 => score -= 1.0,
        4 => score -= 2.0,
        5 => score -= 2.5,
        6 => score -= 2.0,
        7 => score -= 1.0,
        _ => {}
    }

    // Perfect fit reward: post_residual exactly divisible into capacity fractions.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // round-number leftover pairs well with typical sizes
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward if next item fits the post residual nicely.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // exact chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / cap);
            if slack / eighth >= 3 {
                score += 1.5; // too loose a chain match
            }
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 1.0 + (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented (low mean residual) or many bins open.
    if bin_residual == bin_capacity {
        score = cap * 0.55; // neutral baseline for fresh bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (mean_residual / cap); // prefer new bin when mean residual low
        score += 2.0 * progress; // late in stream, prefer consolidation
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 6.0; // an open bin could still absorb it
        }
        if post_class >= 5 {
            score -= 1.0; // fresh bin guarantees a large reusable residual
        }
    } else {
        // Fragmentation pressure: penalize placing into bins whose residual
        // deviates from the mean in a wasteful direction.
        let dev = bin_residual as f64 - mean_residual;
        if dev < 0.0 {
            score += 0.02 * (-dev); // tighter-than-average bin: slightly risky
        } else {
            score -= 0.015 * dev;  // roomier bin: good host for this item
        }

        // Harmonic modulo threshold on (post_residual * 7) to break ties
        // deterministically across harmonic classes.
        let tie = (post_residual * 7 + item_size) % 13;
        score += tie as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (later steps: slightly prefer consolidating)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Dead-space avoidance: if the leftover gap is smaller than the next
    // item (and nonzero), it is likely unusable -> penalize heavily.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Very small nonzero gaps are generally dead space (min item unknown,
    // but tiny slivers rarely usable) -> mild penalty.
    if post_residual > 0 && post_residual <= 5 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 5.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin when decent alternatives
    // exist; relax the penalty for large items or many already-open bins.
    if bin_residual == bin_capacity {
        let alt_pressure = (fitting_bins_count.saturating_sub(1)) as f64 * 9.0;
        let item_relief = 0.35 * item_size as f64;
        let crowd_relief = if open_bins_count > 8 { 10.0 } else { 0.0 };
        score += 20.0 + alt_pressure - item_relief - crowd_relief;
    }

    // Open-bins pressure: with many open bins and high mean residual,
    // prefer placements that consolidate into existing capacity.
    score += 0.4 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Slight tilt: later in the stream, prefer tighter packing overall.
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match between post_residual and next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - lookahead_gap / (bin_capacity as f64));
        // Perfect chain: item fits now AND next item fills remainder exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item can still fit after this placement.
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Tightness reward: relative fill of this placement.
    score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Penalize placements that leave residuals near unusable small values (< min item 1..100 -> below ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged when good fits exist;
    // encourage opening a new bin when mean residual is fragmented (high dispersion).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 10.0;
        if mean_residual > 40.0 && fitting_bins_count > 2 {
            score -= 20.0; // open bins are fragmented; fresh bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.0;
        }
    }

    // Mild preference to balance residuals across open bins.
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space: residuals too small for any plausible item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot go here; slight penalty proportional to waste
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare residual to mean residual: bins with more free space than average
    // should absorb the item, preserving tight bins for small future items.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: empty bin gets a moderate default score so it
    // wins only when existing fits are poor (high post_residual / penalties).
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * progress - (item_size as f64 / bin_capacity as f64) * 20.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Reward tight fits: non-linear coupling of post_residual with stream progress.
    // Tight fits matter more as the stream matures (waste compounds late).
    let tight = 1.0 - (pr / cap);
    score -= tight * tight * (20.0 + 60.0 * progress * progress);

    // Penalize post-residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 40.0;
    } else if next_item_size > 0 {
        // Reward leaving exactly a usable gap for the next item.
        let gap = pr - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: discourage opening a bin when decent fits exist,
    // but allow it when open bins are all crowded (mean residual low).
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / cap).max(0.0);
        score += 30.0 * (1.0 - crowded) + 20.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 35.0; // still allow escape hatch if only one fit exists
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-100.0).min(100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "usable" is the post residual?
    // Residuals that are multiples of common small item sizes (10..=20) are valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fill: best possible outcome
    } else if pr <= 10 {
        -25.0 // tiny dead space, nearly perfect
    } else if pr % 10 == 0 && pr >= 20 {
        -18.0 // round residual, likely reusable by harmonic item classes
    } else if pr % 5 == 0 {
        -9.0
    } else {
        // awkward residual: penalize proportionally to how non-round it is
        let awkwardness = (pr % 10) as f64 / 10.0;
        awkwardness * 12.0
    };
    score += harmonic_bonus;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward by how well it nests
            let nest = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - nest / cap);
        } else {
            // next item won't fit here: slight penalty scaled by overshoot class
            let over = (next_item_size - pr) as f64;
            score += (over / 20.0).min(3.0) * 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when the item
    // could fit elsewhere, unless current bins are nearly full (small residuals).
    if bin_residual == bin_capacity {
        // New bin: base cost plus penalty if open bins still have room.
        score = cap * 0.55;
        if fitting_bins_count >= 1 {
            // existing bins can fit the item; opening new is wasteful
            score += 25.0 + 3.0 * open_bins_count as f64;
        }
        // If the next item is large and mean residual is small, a fresh bin is fine.
        if next_item_size >= 60 && mean_residual < 25.0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating: penalize new bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Existing bin: reward tight fits relative to capacity fraction.
        let fill = (bin_residual - post_residual) as f64 / cap;
        score -= fill * 15.0;
    }

    // Prefer bins whose residual is far below the mean (they are the "odd ones out"
    // and should be drained first), keeping mean residual bins for future items.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
