        score -= 50.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mild pressure from number of open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 0.5;

    // Progress-aware: early on, be slightly more open to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins with residuals near the mean (keeps residuals balanced).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if post_residual exactly matches the next item's size (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize residuals too small for the next item (dead space) unless tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize leftover directly.
        score += post_residual as f64 * 0.5;
    }

    // Reward tight fits (small post_residual generally).
    score -= 0.3 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward bins with residuals below mean (consolidating fuller bins).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when item is large (poor fit elsewhere)
    // or no good chain exists; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && (item_size + next_item_size) as u32 <= bin_capacity {
            score += 10.0;
        }
    }

    // Slight preference for fewer open bins as stream progresses.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * dead * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives, prefer best-fit selection.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in the post residual, reward leaving this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; mild penalty for wasting space.
            score += 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation into fuller bins.
    if open_bins_count > 2 && mean_residual > 20.0 {
        score += (mean_residual - 20.0) * 0.3;
    }

    // Time horizon: early in stream, be conservative (keep residuals flexible); later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - dead);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Discourage opening new bins when existing bins can fit the item.
            score += 12.0 + 3.0 * fitting_bins_count as f64;
            if fitting_bins_count == 1 { score += 25.0; }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), normalized.
    let mut score = pr / cap;

    // Smooth non-linear penalty on dead space: quadratic coupling with progress.
    // Early in the stream, dead space matters less (bins can still be filled later);
    // late in the stream, leftover space is more likely wasted.
    let dead = pr / cap;
    score += dead * dead * (0.5 + 2.0 * progress);

    // Cubic coupling: strongly punish near-empty leftovers late in the stream.
    score += dead * dead * dead * 3.0 * progress;

    // Perfect fit reward (smooth exponential-like term).
    if post_residual == 0 {
        score -= 0.5 + 0.5 * progress;
    }

    // Lookahead: reward if the next item can fit in the post-residual (smooth bonus),
    // penalize slightly if it cannot (bin becomes unusable for the immediate future).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 0.15 * (1.0 - pr / cap) * (1.0 - progress);
        } else {
            score += 0.1 * (pr / cap) * (0.3 + progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.4 * (1.0 - dead);
    }

    // New-bin candidate handling: empty bin gets a baseline score that adapts
    // with the mean residual of open bins and stream progress.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when open bins have plenty of room
        // on average, and when early in the stream (many future items to pack).
        score = 0.6 + 0.5 * (mean_residual / cap).min(1.0) * (1.0 - progress) + 0.3 * progress;
    }

    // Mild regularization against hoarding many open bins.
    score += 0.01 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes (<= 10, <= 20) are nearly perfect packings -> reward.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if post_residual <= 30 {
        score -= 6.0;
    }

    // Modulo-class logic on post_residual: residuals that are multiples of
    // common small item sizes (5, 10, 20, 25) are reusable dead space.
    let pr = post_residual;
    if pr > 0 && (pr % 5 == 0 || pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 8.0;
    } else if pr > 0 && pr < 10 {
        // tiny awkward sliver
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0;
        // exact harmonic match for next item
        if next_item_size == pr {
            score -= 20.0;
        }
    } else if next_item_size > pr {
        score += 3.0; // dead space for the lookahead
    }

    // Tightness ratio reward: favor bins that become very full.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 40.0 * fill * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current fit is bad and lookahead also won't fit here.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = cap - item_size as f64; // baseline: wasted space of new bin
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Penalize bins much emptier than the mean (fragmentation avoidance).
    let res = post_residual as f64;
    if res > mean_residual + 20.0 {
        score += 6.0;
    } else if res < mean_residual {
        score -= 4.0;
    }

    // Many open bins -> encourage filling existing ones tightly.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (res / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Treat post_residual below ~10 as dead space; penalize quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.35 + 0.65 * progress);
    score += pressure * 0.15;

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit snugly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty scaled by how much is stranded.
        score += (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (more fragmented side),
    // since filling low-residual bins balances the fleet.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev.clamp(-30.0, 30.0) * 0.2;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when few bins are open
    // or the item is large and no tight fit exists. Make the empty bin moderately unattractive
    // by default so existing bins win unless they score badly.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.4 + progress * 10.0;
        // Large items benefit from a fresh bin when they would leave big gaps elsewhere.
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space is good; penalize unusable remnants
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // 2-step lookahead: reward bins whose residual will accept the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // even better if next item nearly fills what's left
        if post_residual - next_item_size < 10 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot host the next item
        score += 15.0;
    }

    // Prefer bins with residual close to item_size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 80.0;

    // Compare against mean residual: prefer below-average residual bins (denser)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current bins are very full
    if bin_residual == bin_capacity {
        score += 120.0;
        if mean_residual < 25.0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 20.0; // new bin can host next item too
        }
    }

    // Late in stream: prefer tighter packing, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 45.0;

    // Penalize dead space that is too small for typical future items
    // (residual below ~10 is unusable waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste < 10 {
                score -= 25.0;
            } else {
                score -= 15.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // Last item: just minimize waste hard.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have large mean residual (poor global packing) or many bins
    // are open and current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it high so tight fits in open bins win.
        score = bin_capacity as f64 * 0.55;
        // If existing bins are quite full on average, a new bin is reasonable.
        score -= (mean_residual / bin_capacity as f64) * 30.0;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If no other bin fits (fitting_bins_count counts only open bins),
        // the new bin must be chosen: drop its score decisively.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If many bins are open with big residuals, opening another is wasteful.
        if open_bins_count > 4 && mean_residual > 0.5 * bin_capacity as f64 {
            score += 40.0;
        }
    }

    // Mild penalty for adding to very crowded bin sets when fit is loose,
    // encouraging consolidation early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.2 + 0.3 * progress);
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Small tie-break noise-free deterministic jitter based on step.
    score -= ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer bins with small leftover space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, favor balanced leftovers; late, be aggressive (tight fits).
    let w_tight = 1.0 + 1.5 * progress * progress;
    score -= w_tight * (cap - pr) * 0.5 * progress;

    // Penalize dead space quadratically (small unusable leftovers).
    let dead = pr / cap;
    score += 40.0 * dead * dead * (1.0 - progress);

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * fit_quality * (0.5 + progress);
        } else {
            // post_residual can't host next item: mild penalty scaled by gap.
            score += 4.0 * ((nxt - pr) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Prefer bins where item fits relatively snugly among alternatives.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0) * (pr / cap);
    }

    // New-bin candidate (empty bin): discourage unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 30.0 * (1.0 - size_ratio) * (1.0 - 0.5 * progress);
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    // Align with mean residual: prefer bins below mean residual (tighter than average).
    score += 2.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are "nice"
    // (divisible into common item sizes) are less wasteful.
    let pr = post_residual as i64;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { class_bonus -= 6.0; }
        else if pr % 5 == 0 { class_bonus -= 3.0; }
        else if pr % 20 == 0 { class_bonus -= 8.0; }
        else if pr % 25 == 0 { class_bonus -= 7.0; }
        else { class_bonus += 4.0; } // awkward residual
    } else if pr == 0 {
        class_bonus -= 15.0; // perfect fit
    }

    // Integer-division threshold: small dead space zones are bad.
    if pr > 0 && pr < 10 { class_bonus += 12.0; }
    if pr >= 10 && pr < 20 { class_bonus += 5.0; }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && (next_item_size as i64) <= pr {
        class_bonus -= 10.0;
        // Harmonic match: next item divides the residual evenly
        if pr % (next_item_size as i64) == 0 { class_bonus -= 8.0; }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a stranded gap.
        class_bonus += 3.0;
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        class_bonus -= 18.0;
    }

    // New-bin candidate: baseline competitive score; open a new bin only
    // when placement elsewhere would be poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + mean_residual * 0.3;
        // Don't open new bins early in the stream or when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 50.0; }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 { score -= 6.0; }
        return score;
    }

    // Prefer tighter bins (small residual before placement) mildly.
    score += (bin_residual as f64) * 0.05;

    // Spread load when many bins are open and mean residual is high.
    if (mean_residual - post_residual as f64) > 0.0 {
        class_bonus -= 1.5;
    }

    score += class_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful for future items (min item size is 1, but small gaps < ~15 are
    // unlikely to be filled well given typical item distributions).
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold {
        // Dead space: heavily penalize proportionally to how close to zero.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    score -= (bin_capacity as f64 - post_residual as f64).powf(1.3) * 0.05;

    // Open bins pressure: discourage spreading into new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty if we leave a big gap.
            score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
        }
    }

    // New-bin candidate: make opening a new bin costly unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // But if the item is large, a fresh bin is actually good.
        if item_size > bin_capacity * 2 / 3 {
            score -= 35.0;
        }
    }

    // Prefer bins with below-mean residual (fill emptier-but-viable bins first
    // keeps tighter bins available for small items).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-waste extremes
    // that strand the next item.
    if next_item_size > 0 {
        // Perfect 2-step lookahead match: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward proportionally to how tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this residual: penalize stranded space,
            // worse when the leftover is small (unusable) relative to mean residual.
            let dead = post_residual as f64;
            let unusability = 1.0 - (dead / mean_residual.max(1.0)).min(1.0);
            score += 25.0 * unusability;
        }
    }

    // Reward filling bins that are relatively full compared to fleet average.
    let fill_ratio = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New empty bin candidate: make it attractive only when the item is large
    // (would leave awkward residual elsewhere) or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 50 { 18.0 } else { 0.0 };
        score += 55.0 - large_item_bonus
            + 5.0 * (fitting_bins_count as f64);
        // Early in the stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Small tie-breaker toward exact-fill potential.
    score -= 0.05 * (bin_capacity as f64 - post_residual as f64).abs().recip().min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, amplify near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.35;
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
        // Reward leaving room usable by next item partially.
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to encourage spreading / consolidation balance.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    // Global state: if mean residual is high relative to item, prefer filling sparse bins.
    if mean_residual > item_size as f64 {
        score -= 0.05 * (mean_residual - item_size as f64);
    } else {
        score += 0.08 * (item_size as f64 - mean_residual);
    }

    // Penalize opening new bins when plenty of open bins exist with room.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 20.0 + 3.0 * openness.sqrt() + 15.0 * (1.0 - progress);
        // But allow new bin if item is large and no bin fits well.
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Slight preference for bins with residual close to item size (best-fit core).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * gap;

    // Nonlinear coupling: penalize very small leftovers more as stream progresses.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let t = progress;
    score += 12.0 * pr_norm * pr_norm * (0.5 + t) * cap * 0.01;

    // Penalize tight fits more as stream progresses (fragmentation avoidance)
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (1.0 + t);

    // Dead-space penalty: residuals too small for typical future items
    if pr > 0.0 {
        score += 8.0 * (1.0 - (pr / 40.0).min(1.0)) * pr_norm;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 5.0 * (nxt / cap);
        } else {
            score += 4.0 * (1.0 - pr_norm) * (nxt / cap);
        }
    }

    // Prefer filling bins when many are open
    score += 0.6 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // Mean residual alignment: prefer bins close to mean residual
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + t);

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward post-residuals that fall into
    // "reusable" classes (small dead space, divisible-friendly slots).
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 10 {
        // Near-perfect; small residual unlikely to be usable (items >= 10 typically).
        score -= 5.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual <= third {
        score += 6.0;
    } else if post_residual <= half {
        score += 10.0;
    } else {
        // Large leftover: mostly only when placing small items into big gaps.
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is a chain win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's remainder; penalize wasting space.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should be chosen only
    // when no open bin offers a decent fit. Make the empty bin mildly
    // attractive by default, but unattractive when good fits exist.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is great if the next item is large (needs fresh space).
            if next_item_size >= half {
                score -= 10.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fits).
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += 5.0 * tightness;
    }

    // Mild stream-phase adaptation: late in the stream, consolidate harder.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * phase * (1.0 - post / cap);

    // Nudge toward bins below mean residual (packing into emptier bins first
    // keeps tight bins tight for future tight items).
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (min size 1..100)
    // can use are heavily penalized. Gaps in (0, next_item_size) are dead for the
    // lookahead item; gaps below 10 (or below typical small item) are near-dead.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual == 0 {
        score -= 25.0; // perfect fit, best possible outcome
    } else if (post_residual as f64) < dead_threshold as f64 {
        score += 12.0 + 0.5 * (dead_threshold as f64 - post_residual as f64); // unusable for lookahead
    } else if post_residual < 10 {
        score += 15.0; // near-dead gap, nothing in 1..100 range likely fits well
    } else {
        // Usable gap: reward larger usable residuals mildly, but keep tightness pressure
        score -= 2.0;
    }

    // Tightness: reward small post_residual relative to bin capacity
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score -= 3.0; // chain placement possible
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by open-bin pressure.
    // Opening is only attractive when open bins are very fragmented (high mean residual
    // spread) or when no real bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is small (bins nearly full), new bin less bad
        if mean_residual < 20.0 {
            score -= 15.0;
        }
        // Late in stream, avoid proliferating bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 5.0;
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins
    score += 0.3 * open_bins_count as f64;

    // Fragmentation coupling: penalize leaving residuals far from mean (creates outliers)
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero post_residual (perfect fit) is best.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += waste * waste * 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next_item_size exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Exact chain fit is heavily rewarded; looser chain fits less so.
        score -= 30.0 - slack.min(30.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small to chain: penalize proportionally to how "wasted" the leftover is.
        let unusable = (post_residual as f64) / (next_item_size as f64);
        score += unusable * 10.0;
    }

    // Compare against mean residual: prefer bins that are already below-average residual
    // (consolidating fullness) rather than spreading across emptier bins.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += residual_gap * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit. Base new-bin penalty grows with stream progression
    // (later in the stream, prefer consolidating into existing bins).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + progress * 20.0;

        // But if the item is large and next item is also large, opening fresh space
        // can be reasonable: soften the penalty.
        if item_size >= 50 && next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild preference for filling bins when many are open (reduce open-bin sprawl).
    score += (open_bins_count as f64) * ((bin_residual as f64) / (bin_capacity as f64)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of the bin consumed by this placement.
    let fill = (item_size as f64) / (bin_capacity as f64);
    let tightness = (bin_residual as f64) / (bin_capacity as f64);

    // Reward tight fits: subtract proportional to how well the item fills the bin.
    score -= 40.0 * fill * tightness;

    // Penalize leaving awkward mid-range residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is fine, small bonus penalty
    } else if post_residual >= 10 && post_residual <= 25 {
        score -= 15.0; // residual usable by small items: good
    } else if post_residual > 50 && post_residual < 70 {
        score += 12.0; // awkward zone
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - exact / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if open_bins_count > 0 {
        let pressure = mean_residual / (bin_capacity as f64) * (open_bins_count as f64).ln();
        score -= 8.0 * pressure * tightness;
    }

    // Time horizon: early on, keep bins flexible (penalize very small residuals less
    // harshly); late in the stream, push for maximal filling.
    if progress > 0.7 {
        score -= 20.0 * fill;
    } else if progress < 0.2 {
        // Early: avoid fragmenting bins too early with near-full placements unless exact.
        if post_residual > 0 && post_residual < 5 {
            score -= 10.0;
        }
        score += 6.0 * (1.0 - fill);
    }

    // New-bin candidate handling: an empty bin's raw score equals capacity (100).
    // Make it attractive only when no good fit exists: penalize opening a new bin
    // when decent fitting bins exist, but keep it competitive when the best fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by how many bins already fit the item.
        let mut new_bin_score = item_size as f64 + 55.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a bin anyway
        } else {
            // If existing fits are poor (large post residuals elsewhere), new bin is fine.
            new_bin_score -= 30.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));
            new_bin_score += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late stream: slightly prefer reusing bins.
        new_bin_score += 15.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post-residual with stream progress.
    // Early on, prefer tight fits less aggressively (leave room for future items);
    // later, minimize dead space strongly.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Cubic smoothness term: penalize very small residuals superlinearly (dead space).
    score += 8.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Crowd penalty: with many open bins, prefer consolidating into existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - nxt / cap) * (0.5 + progress);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mean-residual deviation: prefer bins whose residual is near the mean
    // (balanced packing), smoothly coupled.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    // Perfect-fit reward (smooth, no hard threshold).
    score -= 5.0 * (-pr as f64 / 5.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post-residual: quantize dead space into capacity fractions.
    let frac = pr / cap; // 0..1
    // Penalize residuals in "dead zones": small unusable slivers (1..10) and awkward mid gaps.
    if post_residual > 0 {
        let class = post_residual % 10;
        if class <= 2 {
            score += 6.0; // sliver class: nearly dead space
        } else if class >= 8 {
            score += 3.0; // awkward gap class
        } else {
            score -= 2.0; // reusable class
        }
    } else {
        score -= 12.0; // perfect fill: strongly reward
    }

    // Integer-division thresholds on post_residual (capacity quarters).
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 4.0;
    } else if post_residual < quarter * 2 {
        score -= 1.0;
    } else if post_residual < quarter * 3 {
        score -= 3.0;
    }

    // Coupling with next item: reward residuals that can host the lookahead exactly or near-exactly.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 15.0; // next item exactly fills this bin
        } else if nd > 0 && (nd as u32) < 10 {
            score -= 8.0; // next item leaves only a sliver
        } else if nd < 0 {
            score += 2.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, softened late in stream / when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap as f64 * 0.55 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 5.0; // new bin guarantees fit for next item too
        }
        if mean_residual > 0.0 && mean_residual >= item_size as f64 {
            score += 6.0; // existing bins have room; discourage opening
        }
    }

    // Mild tie-break: tighter fit (smaller relative waste) preferred.
    score += (item_size as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (min size 1, but practically small gaps) are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else {
        // Smooth penalty for larger wasted residual, scaled by bin capacity.
        score += 0.15 * (post_residual as f64 / bin_capacity as f64) * post_residual as f64;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 12.0 * tightness;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when many are open.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Next item won't fit here; penalize leaving a residual that strands it.
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose post residual stays near mean
    // (keeps residual distribution homogeneous, easier future packing).
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_diff;

    // New-bin candidate handling: empty bin gets a moderate baseline penalty so
    // it's chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits, opening is fine (relieve pressure).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late-stream bias: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact-ish fits (small post_residual)
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powf(2.0);

    // 2-step lookahead: strongly reward when next item fills the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 * (overshoot / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: bins with residual far below mean are "tight" -> keep them tight
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins have poor fits
    if bin_residual == bin_capacity {
        // new empty bin: post_residual = capacity - item_size, large residual
        // penalize unless no good open option exists
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual as f64 >= mean_residual {
            score += 10.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Prefer bins that will end closed (post_residual small relative to smallest items)
    if post_residual < 10 {
        score -= 20.0; // residual too small for any item (min size 1... but small dead space is fine)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits super-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(6);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small unusable sliver: fine, bin is "sealed"
    } else if post_residual >= 10 {
        // residual usable by medium items — mildly good
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; wasted residual matters more
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // New-bin candidate handling: opening a bin is costly unless current bins fit badly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let badness = if fitting_bins_count > 0 {
            // how poorly do existing bins fit? compare best-case post residual via mean
            ((mean_residual - item_size as f64).abs()) / bin_capacity as f64
        } else {
            1.0
        };
        score = 45.0 - 30.0 * pressure - 25.0 * badness.min(1.0);
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // many open bins with slack: discourage new bin
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Global balance: prefer bins whose residual deviates from mean toward filling them.
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.05 * dev; // fill below-average-residual (fuller) bins first
    }

    // Late-stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = post / cap;

    // Base: prefer minimal post residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.5 * post_frac * post_frac);

    // Reward tight fits more strongly as the stream progresses.
    score -= 15.0 * (1.0 - post_frac) * (1.0 - post_frac) * (0.5 + progress);

    // Penalize bins whose residual is far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead coupling: bonus if the next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 10.0 * (1.0 - post_frac);
    } else if next_item_size > post_residual {
        score += 3.0 * post_frac;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when
    // open bins exist; smooth penalty decreasing with progress.
    if bin_residual == bin_capacity {
        let open_term = (open_bins_count as f64).ln_1p();
        score += 18.0 + 10.0 * open_term * (1.0 - progress) + 5.0 * fit_frac;
    }

    // Mild penalty for accumulating many open bins with large residuals.
    score += 0.05 * open_bins_count as f64 * mean_residual / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity quartiles
    let q = bin_capacity / 4; // 25 for C=100
    let r = post_residual % q;
    // Rewards for post_residual landing in "harmonic" residue classes (0, small)
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual < 10 {
        score -= 40.0;
    } else {
        // penalize awkward dead space: residues near half of the quartile are worst
        let awkward = (r as f64 - (q as f64 / 2.0)).abs();
        score += 0.3 * awkward;
    }

    // Integer-division threshold: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // next item closes this bin perfectly
        } else if next_item_size < post_residual {
            let new_post = post_residual - next_item_size;
            if new_post < 10 {
                score -= 25.0; // lookahead nearly closes bin
            } else {
                score += 0.1 * new_post as f64; // future waste penalty
            }
        } else {
            // next item cannot fit here; bin will freeze with dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of a new bin, discounted late in the stream or when fragmented
        score = 55.0 + 0.2 * fragmentation - 25.0 * progress;
        if open_bins_count == 0 {
            score = -10.0; // must open first bin
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below min item size 1..small threshold) are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to the item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Penalize leaving a gap that exactly invites a wasteful tiny remainder:
    // if post_residual is nonzero but smaller than a typical next item,
    // discourage unless it enables the lookahead item to fit perfectly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // lookahead perfect fit
        } else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    score += bin_pressure * 8.0 * (1.0 - fill_ratio);
    score += progress * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins whose residual is already below
    // average (they are the "nearly full" ones we want to finish off).
    score -= (mean_residual - post_residual as f64) * 1.5;

    // New-bin candidate: make empty bins attractive only when the item is
    // large and no open bin fits well; otherwise keep them less preferred.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing else fits: open new bin
        } else {
            score += 60.0 + fill_ratio * 40.0; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (6.0 - post_residual as f64) * 10.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        if lookahead_waste == 0.0 {
            score -= 300.0;
        } else if lookahead_waste <= 10.0 {
            score -= 150.0 - lookahead_waste * 8.0;
        } else {
            score -= 40.0 - lookahead_waste * 0.5;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize proportionally to wasted space.
        score += (next_item_size as f64 - post_residual as f64).min(cap) * 0.6;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.35;

    // Penalize leaving residual in the "dead zone" (11..25) that few items can use.
    if post_residual > 10 && post_residual < 25 {
        score += (25 - post_residual as f64) * 2.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Mild early-stream pressure to keep bins open (spread items), tighter later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is excellent (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large item, few fitting bins) or when
    // placing here would strand a lot of space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste_if_open = bin_capacity - item_size; // residual left in fresh bin
        let poor_fit_elsewhere = if fitting_bins_count >= 1 { (fitting_bins_count as f64).recip() } else { 1.0 };
        // Prefer new bin when item is large (little waste) and few alternatives.
        score += 40.0; // default: discourage opening new bins
        score -= 0.5 * waste_if_open as f64 * poor_fit_elsewhere;
        if item_size >= 70 {
            score -= 35.0; // big items: fresh bin is natural
        }
        if next_item_size > 0 && next_item_size >= item_size && waste_if_open >= next_item_size {
            score -= 15.0; // fresh bin can host the next item too
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing space rather than spreading.
    if !is_new_bin {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation;
        if open_bins_count > 4 && post_residual as f64 > mean_residual {
            score += 3.0; // avoid leaving above-average slack
        }
    }

    // Time horizon: late in the stream, be greedy (close bins out); early, keep
    // flexibility by mildly favoring moderate residuals.
    if progress < 0.3 && post_residual > 40 {
        score += 5.0;
    } else if progress > 0.7 {
        score -= 0.1 * post_residual as f64; // late: prefer filling bins deeply
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = pr - 60.0 * poly * (1.0 + progress);

    // Reward tight fits more strongly late in the stream
    score -= (item_size as f64 / cap) * (1.0 + 2.0 * progress) * 10.0;

    // Penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 { score -= 15.0; }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild penalty for proliferating open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: discourage unless residuals elsewhere are poor
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that align with
    // "useful" size classes (small, reusable slivers), penalize awkward
    // mid-range dead zones.
    let pr = post_residual;
    let cls = pr % 10;                       // harmonic class modulo 10
    let bucket = pr / 10;                    // coarse bucket (0..10)

    // Dead-zone penalty: residuals in 1..10 are nearly unusable (min item 1,
    // but tiny slivers waste capacity); 30..60 are awkward mid gaps.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    if pr >= 30 && pr <= 60 {
        score += 4.0;
    }

    // Perfect or near-perfect fits are golden.
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 10.0;
    }

    // Reward residuals that can host the lookahead item exactly (harmonic pairing).
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr >= next_item_size {
            let pair_post = pr - next_item_size;
            if pair_post == 0 {
                score -= 15.0;
            } else if pair_post < 10 {
                score -= 6.0;
            } else if pair_post >= 30 && pair_post <= 60 {
                score += 3.0;
            }
        } else {
            // Lookahead cannot fit here: mild penalty unless pr is small anyway.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Class-based micro-tuning: even classes slightly favored (divisible by 2/5
    // pair better with common item sizes).
    if cls % 5 == 0 {
        score -= 1.5;
    } else if cls % 2 == 0 {
        score -= 0.5;
    } else {
        score += 0.5;
    }

    // Bucket shaping: prefer leaving large usable chunks (bucket >= 7) over
    // fragmented mid buckets.
    match bucket {
        0 => score += 3.0,
        1 | 2 => score -= 1.0,
        3 | 4 | 5 => score += 1.0,
        6 | 7 => score -= 2.0,
        _ => { score -= 0.5; }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (item large relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fit = mean_residual < item_size as f64 * 1.05;
        if poor_fit || open_bins_count == 0 {
            score -= 18.0 + 10.0 * (1.0 - progress);
        } else {
            score += 8.0 + mean_residual * 0.1;
        }
    }

    // Tie-breaker: prefer filling bins with less mean slack across fleet,
    // encouraging consolidation into already-open bins.
    score += mean_residual * 0.02 - (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold: u32 = 10; // smallest possible item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Pressure from number of open bins: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave
    // a very poor fit or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If placing in this bin would leave a dead gap elsewhere, new bin is fine.
        if post_residual >= dead_threshold || post_residual == 0 {
            score -= 5.0;
        }
        // If next item fits perfectly in a fresh bin alongside current item, favor it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let combo_left = bin_capacity - item_size - next_item_size;
            if combo_left < dead_threshold {
                score -= 10.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot use the leftover, penalize proportional waste.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (leaving big bins untouched) is mildly penalized.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly in the post residual,
    // this bin is a perfect chain candidate -> reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_slack = (post_residual - next_item_size) as f64;
            if chain_slack == 0.0 {
                score -= 55.0;
            } else if chain_slack < 10.0 {
                score -= 25.0 - 2.0 * chain_slack;
            } else {
                // next item fits but leaves a wide gap: mild reward
                score -= 5.0;
            }
        } else {
            // Next item does NOT fit here: post residual becomes dead space
            // unless it is tiny. Penalize dead space proportional to its size.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 10.0 - dead; // small leftovers are still fine
            } else {
                score += (dead - 10.0).min(40.0) * 0.8; // unusable gap penalty
            }
        }
    } else {
        // Last item: only exact fits matter.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "nearly full" and should be filled first (low residual = good target).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Discourage opening a fresh bin when decent open bins exist,
    // but allow it when the stream is early and few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (1.0 - 0.5 * progress);
        score += 20.0 + pressure * 2.0;
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) non-linearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight;

    // Reward using an existing bin over opening a new one.
    if bin_residual != bin_capacity {
        score -= 15.0;
    } else {
        // New bin: penalize, but less if current bin's leftover would be dead space.
        score += 25.0;
        if post_residual < next_item_size as f64 && next_item_size > 0 {
            score += 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving residual that fits the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        } else {
            score += 6.0;
        }
    }

    // Prefer bins whose residual is below mean residual (fills fuller bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mild penalty for too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Smooth polynomial coupling: penalize mid-range dead space more as stream progresses.
    let dead = (1.0 - (2.0 * x - 1.0).powi(2)) * (0.5 + progress);
    score += 12.0 * dead;

    // Reward tight fits more strongly later in the stream.
    score -= (1.0 - x) * (1.0 - x) * 6.0 * (0.3 + 0.7 * progress);

    // Lookahead: reward residual matching next item size (smooth gaussian-like coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (-gap * gap * 40.0).exp();
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default mild penalty; allow opening only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 8.0 + 10.0 * progress;
        let poor_fit_bonus = if fitting_bins_count <= 1 { 0.0 } else { 4.0 };
        score = base + poor_fit_bonus + 20.0 * (1.0 - (item_size as f64 / cap));
    }

    // Mild tie-breaker against many open bins.
    score += 0.05 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fill: strongly reward exact closures.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class: post_residual divisible by 10 leaves a "clean" slot
    // that is more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead (k=2): if the next item fits in the leftover space, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Dead-space penalty: leftover too small for anything useful
    // (minimum item is 10; small odd residues are wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 10.0;
    }

    // New-bin candidate: penalize so we only open when no open bin fits well.
    // Penalty grows over the stream (prefer consolidating early).
    if is_new_bin {
        score += 60.0 + 40.0 * progress;
        // If the next item also fits in a fresh bin, slightly soften the penalty
        // since the new bin will not be stranded.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor
    // using it instead of opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Mild pull toward bins whose residual is near the stream's mean residual,
    // keeping the open-bin pool balanced.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Dead space relative to bin: penalize leaving large residual only if it is
    // awkward (not matching a plausible future item).
    let awkward = (post_residual as f64) < (next_item_size as f64) && post_residual > 0;
    if awkward {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual can host the next item: reward mildly.
        score -= 8.0;
    }

    // Open-bin pressure: prefer existing bins when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residual close to the item (tightest fit).
    score += 0.3 * ((bin_residual - item_size) as f64 - mean_residual).abs();

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin fits well, opening fresh is fine.
        if post_residual >= 60 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: fewer bins preferred as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 60.0 * (1.0 - slack_gap / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 400.0;
            }
        } else {
            // Next item cannot use this leftover space: penalize dead space.
            score += 25.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins: favor bins tighter than average.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when plenty of open bins already exist.
    if bin_residual == bin_capacity {
        score += 80.0 + 5.0 * open_bins_count as f64;
        // But allow new bin if no existing bin fits well.
        if post_residual as f64 > mean_residual * 0.5 {
            score -= 40.0;
        }
    }

    // Late-stream tightening: waste matters more near the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 0.3 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= 1.5 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 20.0;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty when this fit wastes more than mean residual.
    if post_residual as f64 > mean_residual + 15.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic waste penalty (dead space grows quadratically in badness)
    let mut score = pr * pr / cap;

    // Reward tight fits: subtract for small post_residual (smooth cubic damping)
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Non-linear stream coupling: waste matters more as stream progresses
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_coupling;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // New-bin candidate: penalize slightly so we prefer good existing fits,
    // but relax penalty when open bins have poor average fit or late stream
    if is_new_bin {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0);
        let penalty = 15.0 + 0.4 * mean_fit_gap - 20.0 * progress;
        score += penalty.max(2.0);
    } else {
        // Penalize placing into bins whose residual deviates strongly from mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Lookahead: reward leaving space that the next item can still use
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = pr - n;
            score -= 10.0 * (1.0 - slack / cap); // next item fits well
        } else {
            // next item won't fit: penalize proportional to leftover unusability
            score += 0.3 * (n - pr);
        }
    }

    // Mild preference for fewer open bins early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer placements that leave small post_residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(4);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: classify post_residual by capacity fraction bands.
    // Residuals that are "dead" (too small for the smallest plausible item) are penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0;
    }

    // Modulo-classes on post_residual: residuals divisible into common item sizes
    // (10,20,25,50) are reusable; odd residuals are less useful.
    let reusable = [10u32, 20, 25, 50];
    let mut reuse_bonus = 0.0;
    for r in reusable.iter() {
        if post_residual >= *r && post_residual % r == 0 {
            reuse_bonus += 8.0;
        }
    }
    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        reuse_bonus += 20.0;
        if post_residual % next_item_size == 0 {
            reuse_bonus += 15.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's remainder; mild penalty scaled by waste.
        score += 5.0 * (post_residual as f64 / 100.0);
    }
    score -= reuse_bonus;

    // Integer-division threshold: post_residual classes by quotient of capacity/4.
    let q = post_residual / 25; // 0..=4
    score -= match q {
        0 => 6.0,          // tiny remainder
        1 => 0.0,          // 25..49, good
        2 => 2.0,          // 50..74
        3 => 6.0,          // 75..99, wasteful placement
        _ => -4.0,         // full bin closed, great
    };

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 60.0;
        // If no open bin fits, opening is necessary (fitting_bins_count counts only
        // open bins, so a sole call with capacity residual means it is the fallback).
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Few open bins relative to stream: opening is cheaper early.
        score += 3.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Slight preference to keep number of open bins low.
        score += 0.5 * open_bins_count as f64;
        // Prefer bins with residual below mean (fill the emptier-tail bins less,
        // keep balanced residuals): reward being close to mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (1..=min plausible size) are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // hard dead space penalty
    }

    // Non-linear penalty on unusable small gaps: any post_residual below the
    // smallest likely future item creates a "graveyard" gap.
    let gap = post_residual as f64;
    if gap > 0.0 && gap <= 10.0 {
        score += (11.0 - gap) * 15.0; // the smaller the leftover, the worse
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is consumed by a large fraction by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Coupling with lookahead: if the next item fits exactly in the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item would NOT fit here but would fit if we left
    // more room — i.e., post_residual is a bad trap for the lookahead.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // prefer filling existing bins when many are already open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — finishing it off is good; if far above mean,
    // lightly discourage dumping into it.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.2;

    // New-bin candidate handling: an empty bin has huge residual by
    // definition; make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins
        // could fit the item (few fitting bins => new bin is less wasteful).
        score = bin_capacity as f64 * 0.9 + (fitting_bins_count as f64) * 8.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If the item would leave a perfectly reusable residual in a new bin
        // matching the lookahead, allow the new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are highly desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // leftover after hypothetical next placement
            let chain = post_residual - next_item_size;
            score -= 150.0 - (chain as f64).min(150.0);
            if chain == 0 {
                score -= 250.0;
            }
        } else {
            // next item cannot follow into this bin: penalize wasted potential
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.8;
        }
    }

    // Compare post_residual to mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Penalize large dead space that few items could use
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // as stream progresses, be more willing to open new bins
        score -= (step_index as f64 / (total_items.max(1) as f64)) * 40.0;
    }

    // Slight preference to fill bins with more content already (denser bins)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild penalty for proliferation of open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), strongly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    // or the next item will need this residual more.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
        // If this bin is a poor fit anyway (large post_residual), new bin looks better.
        if post_residual > 30 {
            score -= 20.0;
        }
        // If no open bin fits tightly, opening new bin is fine.
        if post_residual > 20 && fitting_bins_count <= 2 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item could exactly fill the post_residual, keep this space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // reserve for perfect follow-up
        } else if next_item_size <= post_residual {
            score += 10.0; // placing here leaves usable space for next item anyway
        } else {
            // next item won't fit in residual either way; slight penalty for
            // fragmenting space that nothing can use
            score += (post_residual as f64) * 0.2;
        }
    }

    // Global state: many open bins with slack -> prefer consolidating into
    // bins with below-mean residual (fill emptier bins first is wrong; we want
    // to close out bins, so prefer bins whose residual is below mean).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.5;
    }

    // Time horizon: early in stream, be more conservative about opening new bins;
    // late in stream, tighter fits matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Small-item penalty: don't waste a nearly-full bin on a tiny item if the
    // tiny item fits elsewhere too.
    if item_size < 20 && post_residual > 0 && fitting_bins_count > 2 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tighter fills (small post_residual) are rewarded more.
    let pr_norm = pr / cap; // in [0,1]
    let tight_reward = (1.0 - pr_norm).powf(2.0 + 3.0 * progress) * (20.0 + 40.0 * progress);
    score -= tight_reward;

    // Penalize mid-range dead space with a smooth polynomial bump
    let dead = pr_norm * (1.0 - pr_norm); // peaks at pr_norm = 0.5
    score += 15.0 * dead * (1.0 + progress);

    // Lookahead: reward if next item fits into the post residual (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr / nx).min(1.0); // 1 if next item fits exactly or with slack
        score -= 25.0 * fits * (1.0 - pr / (nx + pr)).max(0.0);
        // penalize leaving just-barely-too-small residual for the next item
        let miss = (nx - pr).max(0.0) / cap;
        score += 30.0 * miss * (1.0 - miss);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 * (1.0 - pr_norm);
    }

    // Many open bins: discourage spreading, favor tight bins
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * pr_norm * 8.0;

    // New-bin candidate: make it moderately attractive only when no tight option exists
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress - open_pressure * 2.0;
    }

    // Mean residual coupling: bins far from mean residual get slight penalty (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: items leaving residuals that
    // divide cleanly into small capacity fractions are more reusable.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals that are multiples of common size classes (10, 20, 25, 50)
    if post_residual >= 10 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    } else {
        // tiny dead space penalty: residual < 10 is nearly unusable
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Integer-division thresholds: bucket the residual into fifths of capacity
    let fifth = (bin_capacity / 5).max(1);
    let bucket = post_residual / fifth;
    score -= (bucket as f64) * 2.0; // larger usable buckets preferred

    // Lookahead: if the next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use this residual: mild penalty proportional to waste
        score += post * 0.03;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost + scaling with open bins
        score = cap_f * 0.9 + open_bins_count as f64 * 2.0;
        // allow new bin if existing residuals are all poor for this item
        if fitting_bins_count > 0 {
            let worst_gap = (mean_residual - item_size as f64).abs();
            score += worst_gap * 0.2;
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 5.0;
    }

    // Slight preference for tight fits overall
    score += (item_size as f64 / cap_f) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size < 10) are pure waste; penalize them heavily and non-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score += 8.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if nothing fits well elsewhere, allow new bin via lookahead check:
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a residual the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for bins with residuals above the mean (consolidate
    // space into emptier bins, keeping tight bins for small items).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Early in the stream, be more willing to spread out (mild).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Penalize leaving residual far below mean residual (dead space relative to fleet).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_existing = mean_residual; // rough proxy for best available residual
        if best_existing >= item_size as f64 {
            score += 80.0 + 50.0 * (1.0 - progress);
        } else {
            score -= 30.0 * progress;
        }
        // Mildly discourage many open bins.
        score += 5.0 * open_bins_count as f64;
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize wasting space that could have held it.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Many options: penalize mediocre fits harder.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state coupling: prefer filling bins when many are open with low mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
    }

    // New-bin candidate handling: penalize opening a new bin, but relax when
    // no open bin fits well or stream is early with plenty of room ahead.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 8.0 };
        score += desperation + 10.0 * (1.0 - progress);
        // If mean residual across open bins is small (fragmented), opening fresh is less bad.
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // Small time-dependent jitter-free refinement: as stream ends, prioritize closing bins.
    if progress > 0.8 {
        score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = (pr / cap).clamp(0.0, 1.0);

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = fit_norm * fit_norm * (1.0 - progress) + fit_norm * progress * progress;
    score += 6.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - fit_norm;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist, favor it when residuals are large
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let bonus = if mean_gap > 0.0 { 8.0 * (mean_gap / cap) } else { -10.0 };
        score += 5.0 + bonus;
    }

    // Lookahead coupling: reward leaving space exactly matching the next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 3.0 * (1.0 - diff / cap).max(0.0);
    }

    // Mild penalty for bin proliferation
    score += 0.05 * open_bins_count as f64 * (0.5 + fit_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but discount small residuals that are hard to reuse.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Harmonic class of post_residual: residuals in "dead" classes get penalized.
    // Classes mod 10 model typical item granularity; residuals 1..=9 are near-useless.
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if cls != 0 && post_residual < 20 {
        score += 10.0;
    }

    // Integer-division thresholds: can next item fit after this placement?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward reserving space for the lookahead item (chained fit).
            let chain_left = post_residual - next_item_size;
            score -= 15.0;
            score -= 0.3 * chain_left as f64;
            // Perfect chain: lookahead exactly fills remainder.
            if chain_left == 0 {
                score -= 30.0;
            } else if chain_left < 10 {
                score += 8.0; // creates sliver after chain
            }
        } else {
            score += 12.0; // lookahead cannot follow into this bin
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are large (poor fits everywhere) or few bins are open.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = avg_open / bin_capacity as f64;
        score = bin_capacity as f64 * 0.9 - 60.0 * pressure - 8.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild stream-progress term: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Penalize creating residual far from mean (fragmentation drift).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 1000.0; // perfect fit, extremely favorable
    }

    // Penalize unusable dead space: residual too small for any plausible item (1..=100),
    // but nonzero. Scale penalty by how close the gap is to being "trapped".
    if post_residual > 0 && post_residual < item_size {
        // gap cannot hold the current item class; treat as waste
        score += 0.5 * (item_size - post_residual) as f64;
    }

    // Tight-fit reward: the smaller the post_residual relative to item_size, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Dead-space cliff: residuals in [1, 15] are nearly unusable for items 10..80
    // (or generally small items); penalize sharply.
    if post_residual >= 1 && post_residual <= 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward residuals that can still accommodate a future item comfortably.
    if post_residual >= 50 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    if fitting_bins_count > 1 {
        // mild penalty so that among several fitting bins only the best-fit wins,
        // but never enough to trigger a new bin
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when this bin
    // would leave a nasty dead gap or the item fits almost nothing else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a new bin (avoid frivolous opening).
        score += 30.0 + 0.05 * open_bins_count as f64;
        // If placing here would leave a trapped gap, make the new bin more attractive.
        if post_residual >= 1 && post_residual <= 15 {
            score -= 80.0;
        }
        // Lookahead: if the next item fits exactly in the fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        }
        // Late in the stream, consolidate: new bins become more expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into this bin's post-residual,
    // reward the placement heavily (chains two items perfectly).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits but not perfectly: mild reward proportional to fit quality
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: penalize proportionally to wasted gap
        score += 0.3 * post_residual as f64;
    }

    // Mean-residual coupling: if this bin is far from the mean residual, slight
    // normalization pressure toward keeping residuals uniform.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a large unusable remnant
            let waste = post_residual as f64;
            score += waste * 0.3;
        }
    }

    // Penalize bins whose residual deviates favorably from mean (avoid fragmenting average bins)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 - (bin_capacity as f64 - item_size as f64);
        let _ = bad_fit;
        score = (bin_capacity - item_size) as f64
            + (bin_capacity as f64 - next_item_size as f64).abs() * 0.2
            + open_bins_count as f64 * 2.0;
        // discourage opening new bins when the item fits reasonably well somewhere
        if fit_ratio > 0.6 {
            score += 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // next item pairs well with fresh bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize tiny unusable dead space (fragmentation trap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.12;
        }
    } else {
        // Last item: only the immediate fit matters; reward tight packing harder.
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // good alternatives exist or the item is large (large items fit anywhere fresh).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.35 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0 + (item_size as f64 / cap) * 15.0;
        }
    }

    // Reward tight fills (large item into small residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Global-state coupling: when mean residual across open bins is high,
    // slightly favor filling existing bins (consolidation pressure).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (mean_residual / cap) * (1.0 - t) * 8.0;

    // Late-stream conservatism: prefer exact-ish fits as the stream ends.
    score += t * (post_residual as f64 / cap) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 6.0 * smooth * norm_pr * norm_pr * cap;

    // Reward tight fits more strongly as stream progresses
    score -= smooth * (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0;

    // Penalize dead space relative to mean residual of open bins
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 3.0 * (1.0 - gap / cap) * smooth;
        if pr >= nxt {
            score -= 2.5 * smooth;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: only attractive for large items or when nothing fits well
    if bin_residual == bin_capacity {
        score += 5.0 - 8.0 * norm_item + 4.0 * smooth;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (small or
    // exactly fillable by common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class boundaries: 0, 10, 20, 50, 80 -> harmonic classes of capacity
    let class = if post_residual == 0 {
        0u32 // perfect fit
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 20 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };

    // Reward small residuals strongly (non-linear)
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 10.0,
        3 => { /* neutral */ }
        _ => score += 8.0, // large dead space penalty
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be filled exactly later.
    if post_residual > 0 {
        let fillable = post_residual % 10 == 0 || post_residual % 20 == 0
            || post_residual % 25 == 0 || post_residual == 50;
        if fillable {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nxt_frac = next_item_size as f64 / post_residual as f64;
            // good chain fit when next item consumes most of the leftover
            if nxt_frac > 0.6 {
                score -= 12.0 * nxt_frac;
            } else {
                score += 4.0 * (1.0 - nxt_frac);
            }
        } else {
            // next item cannot use this residual at all: penalize large leftovers
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no good fit exists among open bins (high mean
    // residual fragmentation or few fitting bins).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score -= 20.0; // only one option, new bin competitive
        }
        // open new bins more readily early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if open bins are already fragmented (high mean residual), prefer them
        if mean_residual > 30.0 {
            score += 8.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (i.e., fuller bins), tightening packing.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals below next_item_size are likely unusable waste.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: highly desirable
    } else {
        if post_residual < 10 {
            score += 25.0; // tiny dead space penalty
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // gap unusable by the known next item
        }
    }

    // Reward tight fits (small relative waste)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins would create large dead space. Penalize the empty-bin call
    // moderately, but less when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_dead = (mean_residual - item_size as f64).max(0.0);
        score += 22.0 - 14.0 * crowding + 0.15 * mean_dead;
    } else {
        // Prefer bins with residuals close to the item (best-fit flavor)
        score += 0.05 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

        // Pressure from too many open bins: encourage consolidation
        score += 0.4 * open_bins_count as f64;

        // If next item fits exactly in the resulting residual, bonus
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, be slightly more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Slack that can still host the next item: mild reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-gap / 25.0).exp();
        } else {
            // Dead space relative to next item: penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += 1.5 * dead;
        }
    } else {
        // Last item: reward tightest fit only.
        score -= 10.0;
    }

    // Reward bins already tighter than average (consolidation).
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin is fine if it can host a perfect pair.
            score -= 15.0;
        }
        // Early in stream, new bins are cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling nearly-full bins harder as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}
